// generated by scripts/catalogue/build.mjs from catalogue/ — do not edit
export default JSON.parse('{"1000":["雙腳分開站立，與臀部同寬，將彈力帶套在腳掌前緣。","扶住穩固的物體以保持平衡。","慢慢將腳跟抬離地面，將身體重量轉移到前腳掌上。","在最高點稍作停頓，然後慢慢將腳跟放回起始位置。","重複所需次數，然後換另一條腿。"],"1001":["雙腳分開站立，與臀部同寬，將阻力帶套在腳踝上。","右腳向前跨出一大步，左腳向後退一小步。","彎曲膝蓋並下沉身體，直到右大腿與地面平行，保持左膝略高於地面。","踩穩右腳跟發力推回起始位置。","換另一側重複。"],"1002":["平躺，雙腿伸直，雙腳併攏。","將彈力帶套在腳底足弓處，雙手握住彈力帶兩端。","收緊腹肌，將雙腿抬離地面，直到與地板垂直。","在最高點稍作停頓，然後慢慢將雙腿放回起始位置。","重複所需次數。"],"1003":["將彈力帶固定在腰部高度的堅固錨點上。","面向錨點站立，雙腳分開與肩同寬。","雙手握住彈力帶握把，掌心相對，雙臂向前伸展。","彎曲膝蓋下蹲，保持背部挺直、挺胸。","從深蹲姿勢開始，將彈力帶握把拉向身體，將兩側肩胛骨向內夾緊。","在最高點稍作停頓，然後慢慢釋放張力，回到起始位置。","重複所需次數。"],"1004":["雙腳分開站立，與肩同寬，將彈力帶套在膝蓋上方。","保持挺胸、核心收緊，將臀部向後推，彎曲膝蓋下蹲。","確保膝蓋對齊腳尖方向，重心落在腳跟。","在最低點稍作停頓，然後踩穩腳跟推回起始位置。","重複所需次數。"],"1005":["將彈力帶固定在腰部高度的堅固錨點上。","背對錨點站立，雙腳與肩同寬。","雙手握住彈力帶並拉至胸前，手肘彎曲並貼近身體兩側。","收緊腹肌，慢慢向前捲動胸口，使胸部靠近膝蓋。","在捲腹的最高點稍作停頓，然後慢慢回到起始位置。","重複所需次數。"],"1006":["將彈力帶固定在胸口高度，雙手伸直握住兩端。","往後退一步，直到彈力帶繃緊。","手肘抬高，將雙手往胸口拉。","夾緊肩胛骨。","慢慢回放，不要讓肩膀往前圓肩。"],"1007":["雙腳分開與肩同寬站立，將彈力帶繞在上背部並穿過胸前。","雙手握住彈力帶兩端，手肘彎曲貼近身體兩側。","收緊腹肌並將軀幹轉向一側，將手肘移向對側膝蓋。","稍作停頓，然後回到起始位置。","換另一側重複。","兩側交替進行至所需次數。"],"1008":["將一條彈力帶套在大腿上（膝蓋正上方）。","面向階梯或踏台站立，雙腳分開與臀部同寬。","右腳踏上踏台，踩穩腳跟向上蹬起。","將左腿向後伸展，保持伸直。","將左腳放回地面。","換左腳踩上踏台重複動作。","雙腿交替進行至所需次數。"],"1009":["雙腳分開站立與肩同寬，將彈力帶套在腳踝上。","雙手將彈力帶維持在大腿前方，掌心朝向身體。","保持背部挺直、核心收緊，進行屈髖，慢慢將上半身向地面傾斜。","下沉時將臀部向後推，雙膝微彎。","將彈力帶降向地面，感受腿後肌群的拉伸。","在最低點稍作停頓，然後啟動臀肌與腿後肌群，將上半身帶回起始位置。","重複所需次數。"],"1010":["雙腳分開與肩同寬站立，將彈力帶踩在腳下。","雙手握住彈力帶，掌心朝向身體，雙臂伸直。","收緊核心，膝蓋保持微彎。","慢慢以臀部為軸心向前屈髖，保持背部挺直、挺胸。","將彈力帶降向地面，同時雙腿維持微彎伸直。","在最低點稍作停頓，然後夾緊臀肌與腿後肌群，回到起始位置。","重複所需次數。"],"1011":["坐在地上，雙腿向前伸直，背部挺直。","將彈力帶繞在腰部，雙手握住兩端。","收緊腹肌，慢慢將軀幹轉向一側，保持背部挺直，雙腳貼地。","轉體到底時稍作停頓，然後慢慢回到起始位置。","換另一側轉體重複。","兩側交替進行至所需次數。"],"1012":["雙腳分開與肩同寬站立，將彈力帶踩在腳下。","將彈力帶手把維持在肩部高度，掌心朝前。","啟動核心，將彈力帶向上推過頭頂，手臂完全伸直。","推舉的同時將軀幹轉向一側，保持骨盆與下盤穩定。","在頂端稍作停頓，然後回到起始位置。","換另一側重複推舉與轉體。","兩側交替進行至所需次數。"],"1013":["將彈力帶固定在高處錨點（例如單槓或穩固橫樑）。","面向錨點站立，雙腳分開與肩同寬。","以反握方式抓住彈力帶，雙手間距略寬於肩寬。","雙臂完全伸過頭頂，手肘保持微彎。","收縮背闊肌，將彈力帶往下拉向胸口，肩胛骨向內夾緊。","在動作底部稍作停頓，然後慢慢釋放張力，回到起始位置。","重複所需次數。"],"1014":["平躺，雙腿伸直，雙臂伸過頭頂握住彈力帶。","收緊腹肌，同時將雙腿與上半身抬離地面，雙手朝腳尖方向延伸。","在最高點稍作停頓，然後慢慢將雙腿與上半身放回起始位置。","重複所需次數。"],"1015":["雙腳分開與肩同寬站立，將彈力帶固定在胸部高度的堅固物體上。","雙手握住彈力帶並側向跨步遠離錨點，拉緊彈力帶產生張力。","身體與錨點垂直站立，一側面向彈力帶固定端。","雙臂在胸前伸直，保持雙手與胸部同高。","收緊核心肌群，將彈力帶向前推離胸口，手臂完全伸直。","保持這個姿勢數秒，然後慢慢將彈力帶拉回胸前。","重複所需次數，然後換邊。"],"1016":["坐在重訓椅或椅子上，雙腳平放在地面上。","雙手握住彈力帶，掌心朝上，前臂平放在大腿上。","慢慢向上彎曲手腕，收縮前臂肌群。","在最高點稍作停頓，然後慢慢將手腕放回起始位置。","重複所需次數。"],"1017":["雙腳分開與肩同寬站立，彈力帶置於大腿前，掌心朝內。","保持雙臂伸直，向兩側斜上方舉起，與身體形成「Y」字形。","在動作頂端將肩胛骨向內夾緊。","慢慢將手臂放回起始位置。","重複所需次數。"],"1018":["雙腳分開與肩同寬站立，將彈力帶踩在腳下，雙手握住兩端。","手臂伸直放鬆，讓彈力帶垂在大腿前方。","向上聳肩，盡可能將彈力帶拉高，啟動斜方肌。","在頂端收縮處停留片刻，然後慢慢將肩膀放回起始位置。","重複所需次數。"],"1020":["將彈力帶固定在高處，在旁邊採跪姿或站姿。","用靠近彈力帶的那隻手，在肩膀處拉住彈力帶。","身體向側邊的髖部彎曲。","穩定控制身體回到直立。","做完所有次數後換邊。"],"1021":["將彈力帶套在雙腳或單腳腳踝上並固定好。","身體站直，需要時可扶著支撐物。","將一腿打直，往前抬到與髖部同高。","慢慢放下。","完成次數後換腿。"],"1022":["雙腳分開與肩同寬站立，將彈力帶踩在腳下。","雙手握住彈力帶手把，掌心相對，雙臂向前伸展。","膝蓋微彎，髖部向前鉸鏈屈髖，保持背部平直。","將彈力帶拉向胸口，肩胛骨向內夾緊。","在最高點稍作停頓，然後慢慢釋放張力回到起始位置。","重複所需次數。"],"1023":["雙腳分開與肩同寬站立，將彈力帶套在大腿上。","雙手將彈力帶維持在大腿前方，掌心朝向身體。","保持背部平直、膝蓋微彎，進行屈髖將彈力帶放低至小腿高度。","向下時感受大腿後側（腿後肌群）的拉伸。","啟動臀肌與腿後肌群發力，將身體帶回起始位置。","重複所需次數。"],"1027":["坐在機台上，將一隻腳踩在踏板上。","解開安全扣，放下踏板直到膝蓋彎曲約 90 度。","腳跟發力將腿推直，但膝蓋不要鎖死。","穩定控制並慢慢放回。","保持髖部貼緊椅墊。做完次數後換腿。"],"1028":["設定好輔助重量，握住握把並站上踏墊。","手肘夾近身體，挺胸。","彎曲手肘直到 90 度，將身體往下放。","往上推回直到手臂伸直。","避免聳肩，動作保持流暢。"],"1029":["調整座椅高度，讓握把對準胸口中央，向後坐穩。","握住握把，手肘略低於肩膀。","將握把往前推，直到手臂接近伸直。","慢慢放回，直到感覺胸部有伸展感。","背部貼緊靠墊。"],"1030":["坐在蝴蝶機上，背部貼平，手臂抬至胸口高度。","將前臂或雙手放在靠墊上，手肘微彎。","雙臂在胸前向內合攏。","稍微夾緊停頓一下，再慢慢打開直到感覺胸部伸展。","保持肩膀下壓並往後收。"],"1031":["面向機台站立，雙手扶在支撐桿上。","將訓練腿的後側貼在槓桿軟墊上。","收緊臀肌，將腿往後並稍微往上推。","慢慢回到起始位置。","保持軀幹直立，不要拱背。做完次數後換腿。"],"1032":["坐好並將上臂貼在靠墊上，握住握把。","將單邊握把往肩膀方向彎舉。","在頂點用力收縮二頭肌。","慢慢放下的同時，換另一隻手往上彎舉。","保持肩膀放鬆，避免晃動身體。"],"1033":["坐下並調整座椅，讓上臂可以靠在軟墊上。","手肘彎曲，握住握把。","將握把往下壓，直到手臂伸直。","用力收縮三頭肌約 1 秒。","慢慢放回，過程中不要聳肩。"],"1034":["站在機台旁，將腿部外側貼在軟墊上。","扶住支撐桿保持平衡。","流暢地將腿往側邊推開。","稍微停頓一下，再慢慢放回。","保持軀幹直立。做完次數後換腿。"],"1035":["站在機台旁，將腿部內側貼在軟墊上。","扶住支撐桿保持平衡。","大腿內側用力，將腿拉過身體前側。","慢慢回到起始位置。","保持髖部水平，避免身體歪斜。做完次數後換腿。"],"1036":["面向機台站立，雙手扶住支撐桿。","將大腿前側貼在軟墊上。","將腿往前抬起，直到大腿約與地面平行。","慢慢放回起始位置。","保持軀幹挺直。做完次數後換腿。"],"1037":["面向機台站立，握住握把支撐身體。","將訓練腿的後側貼在軟墊上。","收緊臀肌，將腿往後踢。","在最高點停頓一下，再慢慢放回。","保持軀幹直立。做完次數後換腿。"],"1038":["進入機台，讓肩墊靠在肩膀上，雙腳與肩同寬。","解開安全扣並繃緊核心。","彎曲膝蓋，臀部往後往下坐。","腳跟發力站回原位。","保持挺胸，膝蓋朝向腳尖方向。"],"1039":["走進機台，讓肩墊靠在肩膀上，雙腳與肩同寬。","解開安全扣並繃緊核心。","在舒適範圍內盡量往下深蹲。","腳跟發力站起。","保持挺胸，膝蓋對齊腳尖方向。"],"1040":["走進機台，單腳踩在踏板上，另一腿抬起或伸直。","繃緊核心並解開安全扣。","用單腿慢慢往下深蹲。","腳跟發力站起。","保持膝蓋對齊腳尖。做完次數後換腿。"],"1041":["仰躺在機台長凳上，握住胸口高度的握把。","雙腳踩穩，肩膀往後收。","將握把往上推，直到手臂接近伸直。","慢慢放下，直到感覺胸部有伸展感。","全程保持背部貼緊靠墊。"],"1042":["俯臥在長凳上，頭部懸空於邊緣外，在後腦勺放上輕量重物。","一開始先將下巴收向胸口。","慢慢抬起頭，直到頸部與軀幹呈一直線。","稍微停頓一下，再穩定控制往下放。","負重保持輕量，動作維持平順。"],"1043":["仰躺在長凳上，頭部懸空於邊緣外，額頭上放一個輕量重物。","用手扶著重物以維持穩定。","收下巴，慢慢將頭往上捲起。","稍微停頓一下，再穩定控制往下放。","負重保持輕量，避免猛力拉扯。"],"1044":["拿起兩片平滑的槓片疊在一起，平滑面朝外。","用指尖與拇指將槓片捏緊。","身體站直，手臂自然垂在身側。","維持 20 到 30 秒，不要讓槓片滑落。","換手重複動作。"],"1045":["將長凳放進深蹲架內，把槓鈴設定在肩膀高度。","坐直，雙手握距略寬於肩，將槓鈴起槓。","將槓鈴筆直推過頭頂，直到手臂伸直。","穩定控制將槓鈴放回上胸處。","保持肋骨下壓，背部貼緊靠墊。"],"1046":["將滑輪握把設定在約頭部高度，站穩腳步。","握住握把，身體微微後傾，手臂伸直。","手肘往後帶，將握把拉向上胸。","用力夾緊肩胛骨。","慢慢放回直到手臂伸直。"],"1047":["坐在下拉機上，將大腿固定在腿墊下。","以窄握握住橫桿。","身體微微後傾，將橫桿拉到上胸處。","手肘往下帶，用力收縮背闊肌。","讓橫桿慢慢往上升，直到手臂伸直。"],"1048":["側躺在長凳上，上方的手拿一個輕啞鈴。","起始時手臂垂在身前，手肘微彎。","將手臂往外往上舉，直到約與肩膀同高。","停頓一下，再穩定控制放下。","做完次數後換邊。"],"1049":["雙手扶在長凳上，雙腳往後退，讓身體呈髖屈姿勢。","保持背部平坦，核心繃緊。","收緊臀肌，將一腿筆直往後上方踢。","放下時不要讓髖部翻轉。","做完次數後換腿。"],"1050":["在史密斯機橫桿下放一個踏塊，將橫桿扛在上背。","前腳掌踩在踏塊上站好。","將腳跟往下放，充分伸展小腿。","盡可能踮起腳尖到最高點。","在頂點停頓一下，再慢慢放下。"],"1051":["採四足跪姿，雙手在肩膀正下方。","收下巴，將背部往天花板方向拱起。","肚臍往內收，維持幾個呼吸。","回到脊椎中立位置。","慢慢重複動作，每次拱背維持 15 到 20 秒。"],"1052":["在約髖部高度握住固定橫桿或柱子。","雙腳往後退，直到手臂伸直。","臀部往後往下坐，讓胸口自然下沉。","感受背部與身體兩側的伸展感。","維持 20 到 30 秒。"],"1053":["單膝跪地，另一腳踩在前方呈弓步。","骨盆後傾並夾緊後側腿的臀肌。","將髖部輕輕往前推。","保持軀幹挺直，維持 20 到 30 秒。","換邊重複動作。"],"1054":["跨出弓步，雙手扶在牆上或前膝上。","後腿打直，腳跟踩地。","身體往前傾，直到感覺小腿有伸展感。","保持腳尖朝前。","維持 20 到 30 秒後換邊。"],"1056":["仰躺在地面上。","將一腳腳踝跨在另一腿的膝蓋上。","將下方那條腿往胸口方向拉。","保持頭部與肩膀放鬆。","維持 20 到 30 秒後換邊。"],"1058":["站在牆壁或門框旁。","將前臂或手掌貼在與肩同高的牆面上。","身體慢慢往手臂的反方向轉開。","維持 20 到 30 秒。","換手重複動作。"],"1059":["身體站直，需要時可扶著東西保持平衡。","彎曲一側膝蓋並抓住腳踝。","雙膝併攏，將腳跟拉向臀肌。","維持 20 到 30 秒。","換腿重複動作。"],"1060":["坐在地板上，上背靠著長凳，將加墊的槓鈴放在髖部上方。","雙腳踩穩與髖同寬，透過腳跟發力。","抬起髖部，直到軀幹與地面平行。","在頂點夾緊臀肌，並收下巴。","有控制地放下髖部。","重複動作，過程中不要讓下背過度拱起。"],"1061":["上背靠在長凳上，將加墊的槓鈴放在髖部上方。","一腿伸直或屈膝騰空。","踩地腳的腳跟發力，將髖部抬到水平。","在頂點夾緊臀肌，身體不要扭轉。","有控制地放下。","完成次數後換腿。"],"1062":["上背靠在長凳上，把負重放在髖部上。","單腳踩穩，另一腿抬離地面。","腳跟發力抬起髖部，直到軀幹呈水平。","停頓並夾緊臀肌。","慢慢放下。","完成次數後換腿。"],"1063":["將槓鈴放在上背，雙腳站得比肩更寬。","腳尖朝外轉約 30 度。","收緊核心，往下坐到雙腿之間。","膝蓋朝腳尖方向移動。","下蹲到大腿平行地面或更低，再透過腳跟發力站起。","全程保持挺胸。"],"1064":["雙腳寬站，腳尖朝外。","雙手在胸前合握。","髖部往後往下坐到雙腿之間。","膝蓋對齊腳尖，保持挺胸。","下蹲到大腿平行地面。","透過腳跟發力站起，並夾緊臀肌。"],"1065":["仰臥，雙腳腳跟放在健身球上。","雙臂壓穩地面作為支撐。","抬起髖部，直到身體呈一直線。","在頂點夾緊臀肌。","有控制地放下髖部。","全程穩住健身球。"],"1067":["面對高處滑輪站立並握住橫桿。","上半身微微前傾。","將橫桿往下拉到大腿處。","收縮背闊肌。","慢慢放回。"],"1068":["身體前傾，手肘彎曲握住把手。","上臂保持與地面平行。","將手臂往後伸直。","收縮三頭肌。","慢慢放回，完成後換邊。"],"1069":["側對滑輪站立，雙手握住把手。","雙臂保持伸直。","將軀幹往遠離配重片的方向旋轉。","慢慢轉回。","換邊重複。"],"1070":["握住把手，雙臂伸直、身體後傾。","保持身體呈一直線。","彎曲手肘將身體拉起。","收縮二頭肌。","慢慢放下。"],"1071":["躺在懸吊帶下方並握住把手。","雙膝彎曲，腳底平踩地面。","抬起髖部，將胸口拉向把手。","夾緊肩胛骨。","慢慢放下。"],"1072":["雙臂伸直撐在懸吊帶上。","身體微微前傾。","往下直到手肘呈 90 度。","推回上方。","保持懸吊帶穩定。"],"1073":["背對固定點，雙手在胸前高度握住把手。","身體保持一直線往前傾。","將身體推離把手。","收縮胸肌。","慢慢放回。"],"1074":["背對固定點，雙手置於胸前高度。","雙臂併攏、身體往前傾。","將雙臂往兩側打開。","拉回胸前併攏。","手肘保持微彎。"],"1075":["握住把手，雙臂朝下、身體後傾。","保持身體呈一直線。","將雙臂往頭頂方向抬起。","稍作停頓。","慢慢放下。"],"1076":["仰臥，雙腳腳跟放進懸吊帶並抬起髖部。","雙臂壓穩地面維持平衡。","一腳腳跟往臀肌方向彎起，另一腿同時伸直。","以流暢的跑步節奏交替雙腿。","保持髖部抬高且水平。","持續完成整組動作。"],"1077":["一腳放進懸吊帶，另一腳站直，手扶固定物維持平衡。","收緊核心。","將懸吊帶那側的腿往外滑開。","在最遠處短暫停頓。","有控制地收腿回來。","完成次數後換腿。"],"1078":["仰臥，腳跟放進懸吊帶且雙膝彎曲。","雙臂放在身體兩側。","腳跟發力並抬起髖部。","在頂點夾緊臀肌，讓肩膀到膝蓋呈一直線。","慢慢放下但臀部不碰地。","重複目標次數。"],"1079":["雙腳放進懸吊帶並俯臥，雙手放在頭後或抱胸。","收緊核心。","伸展背部與髖部，將胸口抬起。","身體呈一直線時停住。","慢慢放下。","在頂點避免過度拱背。"],"1080":["握住把手，雙臂伸直、身體打直後傾。","收緊腹肌與臀肌。","手肘往後帶，將胸口拉向雙手。","將肩胛骨往中間夾緊。","有控制地放回，直到手臂完全伸直。","雙腳往前走會增加難度。"],"1081":["雙腳放進懸吊帶，雙手在肩膀正下方呈棒式起始。","雙腿保持伸直。","將髖部往天花板方向高高抬起。","折起身體呈倒 V 字形。","慢慢放回棒式。","全程保持手臂伸直。"],"1082":["雙腳放進懸吊帶，雙手在肩膀正下方呈棒式起始。","收緊核心。","捲起髖部，將雙膝拉向胸口。","短暫停頓。","雙腿往後伸直回到棒式。","肩膀保持在手腕正上方。"],"1083":["仰臥，腳跟放進懸吊帶，雙腿伸直。","將髖部抬離地面。","將腳跟往臀肌方向勾起。","保持髖部抬高。","慢慢將雙腿伸直。","重複目標次數。"],"1084":["雙腳放進懸吊帶，以棒式姿勢開始。","雙手保持在肩膀正下方。","將單側膝蓋往胸口帶。","以快速的跑步節奏交替雙腿。","保持髖部水平。","持續完成整組動作。"],"1086":["雙手握住握把，手臂伸直，身體向後傾。","身體維持一直線。","用手臂和背部的力量爆發上拉。","將胸口拉向雙手。","慢慢放下身體。","核心保持收緊。"],"1087":["背對固定點，在雙腿之間握住握把。","往前走一步讓懸吊帶繃緊。","髖部往後推，讓雙手穿過雙腿之間。","髖部往前推。","站直並夾緊臀肌。","背部保持平坦。"],"1088":["雙手伸直握住握把懸掛。","收緊核心。","將胸口往上拉到兩個握把之間。","以手肘帶動往上拉。","在頂端停頓一下。","慢慢放下身體。"],"1090":["雙手握住握把，手臂伸直，身體向後傾。","身體保持打直。","雙臂向兩側打開。","夾緊肩胛骨。","慢慢回到原位。","不要聳肩。"],"1091":["呈跪姿，在胸前握住握把。","收緊核心。","身體向前傾，同時將雙臂往前推。","背部保持平坦。","拉回起始位置。","不要讓髖部往下掉。"],"1093":["雙手握住握把並伸直手臂，雙腳踩在地面上。","胸口稍微前傾。","彎曲手肘放下身體。","用雙腿稍微輔助支撐。","推回上方。","肩膀保持下壓。"],"1094":["雙手握住握把，雙腳踩在地面上。","身體向後傾。","將胸口拉向雙手。","用雙腿稍微輔助發力。","慢慢放下身體。","核心保持收緊。"],"1095":["雙手握住握把並伸直手臂，雙腳踩在地面上。","軀幹保持直立。","彎曲手肘放下身體。","用雙腿稍微輔助發力。","推回上方。","手肘貼近身體兩側。"],"1096":["握住握把，手肘彎曲呈 90 度。","身體稍微向後傾。","將前臂往外並往上旋轉。","手肘貼在身體兩側。","慢慢回到原位。","動作幅度保持小一點。"],"1097":["側對固定點站立，握住握把。","收緊核心。","身體往遠離固定點的方向側彎。","用側腹的力量拉回直立姿勢。","完成所有次數後換邊。","髖部保持穩定不動。"],"1098":["側躺，雙腳放進懸吊帶，手肘在肩膀正下方撐地。","抬起髖部。","身體維持一直線。","保持平穩呼吸。","維持 20 到 30 秒。","換邊進行。"],"1099":["雙手握住握把，一腳往後踩。","身體站直。","後腳膝蓋朝地面下蹲。","用雙臂稍微輔助拉住。","透過前腳腳跟往下踩，站回原位。","換腳進行。"],"1100":["後腳放進懸吊帶，前腳往前跨一步。","身體站直。","降低髖部，後腳膝蓋往下蹲。","前腳膝蓋維持在腳掌上方。","往上推回原位。","換腳進行。"],"1101":["握住握把，單腳站立。","另一隻腳往前伸直。","臀部往後坐並下蹲。","膝蓋維持在腳趾方向上方。","站回原位。","換腳進行。"],"1102":["仰躺，雙腳腳跟放進懸吊帶。","抬起髖部讓身體呈一直線。","將腳跟朝身體方向勾進來。","髖部保持抬高。","慢慢伸直雙腿。","重複動作。"],"1103":["雙手握住握把並伸直手臂。","身體保持直立。","彎曲手肘放下身體。","手肘貼近身體。","推回上方。","全程保持穩定控制。"],"1104":["雙手握住握把，身體向前傾。","手肘彎曲並維持在頭部兩側。","伸直雙臂。","身體保持打直。","慢慢回到原位。","手肘保持固定不動。"],"1105":["雙腳放進懸吊帶，從棒式開始。","雙臂打直。","髖部轉向一側。","回到中間。","轉向另一側。","肩膀保持穩定。"],"1106":["雙腳放進懸吊帶，擺出直臂棒式。","肩膀維持在手掌正上方。","雙膝拉向胸口，同時扭轉朝向一邊手肘。","稍微停頓，再把腿伸直回到棒式。","每次交替換邊。","回放時別讓髖部下塌。"],"1107":["握住握把，雙臂打直，身體呈一直線往後傾。","核心收緊，雙腳踩穩。","雙臂往上往外舉，在頭頂形成 Y 字。","在頂點停一下，不要聳肩。","慢慢放回起始位置。","雙腳往前踩可增加難度。"],"1108":["掌心朝上握住握把，雙臂伸直，身體後傾。","從頭到腳跟呈一直線。","手肘彎曲，把雙手拉向耳朵。","手肘抬高並往兩側打開。","在頂點收緊二頭肌。","控制速度放回，直到雙臂打直。"],"1109":["掌心朝上握住握把，雙臂打直，身體後傾。","身體保持繃緊。","將自己拉起，雙手收在頭部兩側。","在頂點停留 1 秒並用力收緊。","慢慢放回直到雙臂打直。","雙腳往前走會比較輕鬆。"],"1110":["雙腳放進懸吊帶，以前臂撐地準備。","收緊腹肌，身體保持一直線。","前臂推地，將身體往後移。","受控地小幅往前擺，超過起始位置。","髖部保持水平，下背不要凹陷。","依設定的次數或時間繼續執行。"],"1111":["雙手靠近握住握把，雙臂打直，身體前傾。","身體維持一直線。","手肘夾近身體，將胸口降到兩個握把之間。","胸口靠近雙手時停一下。","往上推回直到雙臂打直。","雙腳往後踩可增加難度。"],"1112":["雙腳放進懸吊帶，擺出直臂棒式。","肩膀維持在手掌上方。","膝蓋拉向胸口，脊椎微微拱起。","在頂點收緊腹肌。","雙腿慢慢伸直回到棒式。","回放時避免髖部下掉。"],"1113":["掌心相對握住握把，身體後傾。","身體打直，雙臂伸直。","手肘往外抬高，將握把拉向額頭。","在終點夾緊肩胛骨。","慢慢放回直到手臂完全伸展。","不要讓髖部掉下去。"],"1115":["懸吊帶調低，雙手握住握把，擺出折體姿勢。","核心收緊，雙腳往上踢或走成倒立姿勢。","彎曲手肘，將頭降到握把之間。","往上推回直到雙臂打直。","穩定身體，需要的話可靠牆或請人護槓。","結束時小心下來。"],"1116":["握住握把，雙腳往後走，讓身體呈斜角。","身體打直，核心收緊。","彎曲手肘，把胸口降向握把。","手肘保持約 45 度。","往上推到雙臂打直。","雙腳再往後走可增加難度。"],"1117":["手臂微彎握住握把，站直。","挺胸往下深蹲。","雙腳用力蹬地往上跳。","前腳掌輕柔落地，順勢蹲入下一次。","懸吊帶只用來保持平衡。","膝蓋對齊腳尖方向。"],"1119":["握住握把，面向錨點站立。","單腿往後並跨到另一腿後方。","往下蹲到前側大腿接近平行地面。","挺胸，前膝在腳踝上方。","前腳跟推地站起。","完成次數後換邊。"],"1120":["握住握把，雙臂打直，身體後傾。","身體保持一直線。","手肘貼近身體，將胸口拉向雙手。","夾緊肩胛骨。","慢慢放回直到雙臂打直。","往前踩可減輕負荷。"],"1121":["雙腳放進懸吊帶，擺出高棒式。","身體保持一直線，做 1 下伏地挺身。","單膝拉向胸口，再換另一腳。","以穩定節奏交替雙腿。","髖部保持水平。","整組重複這個順序。"],"1122":["跪姿或站姿握住握把，雙臂在身前。","核心收緊，背部打平。","身體往前延伸，雙臂斜向一側。","延伸到背部還能維持平直的範圍就好。","用腹肌發力拉回起始位置。","每次交替換邊。"],"1123":["單手掌心朝上握住握把，身體斜向後傾。","雙腳踩穩，身體打直。","彎曲手肘，將身體拉向手部。","在頂點收緊二頭肌。","慢慢放回直到手臂打直。","完成次數後換手。"],"1124":["單手握住握把，身體前傾，雙腳站寬保持平衡。","髖部擺正。","彎曲手肘，將胸口降向手部。","軀幹抵抗扭轉。","推回直到手臂打直。","做完所有次數後換邊。"],"1125":["雙腳放進懸吊帶，單手撐地擺出棒式。","核心用力收緊。","彎曲支撐手的手肘，降低胸口。","髖部保持水平，避免扭轉。","往上推回。","完成次數後換手。"],"1126":["握住握把，身體前傾，一腳離地抬起。","身體保持打直。","將胸口降到雙手之間。","往上推回，不要讓髖部掉下去。","抬起的腿與身體維持一直線。","做完一組後換腿。"],"1127":["雙手握住頭頂上方的握把，手臂打直懸吊。","收緊核心。","手肘往下帶，將胸口拉向握把。","在頂點收緊背部。","慢慢放回直到手臂完全伸直。","屈膝或身體後傾會比較輕鬆。"],"1128":["握住握把，雙手在肩膀下方擺出棒式。","身體維持一直線。","將胸口降到握把之間。","懸吊帶保持穩定，手肘約呈 45 度。","往上推到雙臂打直。","不要讓髖部下塌。"],"1129":["握住握把，面向錨點站直。","單腿往後跨，下蹲呈弓步。","前膝維持在腳踝上方。","前腳跟推地回到起始位置。","懸吊帶只用來輔助平衡。","雙腿交替或先做完同一邊。"],"1130":["握住握把，雙臂在身前打直，身體後傾。","身體維持一直線。","雙臂往兩側大幅打開，把肩胛骨夾起來。","手臂微彎，與肩膀維持同高。","慢慢回到起始位置。","雙腳往前走可減輕負荷。"],"1131":["握住握把站直。","單腿跨過身體，往側邊且略微往後踩出。","背部打平，髖部往後坐。","作用腳推地回到起始位置。","膝蓋對齊腳尖方向。","完成次數後換邊。"],"1132":["握住握把，雙腳併攏站立。","往一側大步跨出。","彎曲該側膝蓋、髖部往後推，另一腿保持打直。","挺胸，腳跟踩穩。","推地回到起始位置。","左右交替。"],"1133":["單手握住握把，身體斜向後傾。","髖部保持水平，空著的手放在胸口或髖部。","手肘往外打開，把握把拉向肩膀。","在終點收緊後三角肌。","慢慢放回直到手臂打直。","完成次數後換手。"],"1134":["雙腳放進懸吊帶，擺出高棒式。","單腿稍微抬高。","髖部保持水平，身體打直。","維持 20 到 30 秒。","放下腿，換邊。","全程保持穩定呼吸。"],"1135":["雙腳放進懸吊帶，前臂撐地。","將一條腿抬得比另一條稍高。","髖部擺正，腹肌收緊。","維持 20 到 30 秒。","放下並換腿。","不要讓下背凹陷。"],"1136":["握住握把單腿站立，另一腿往前伸。","髖部往後坐並彎曲膝蓋。","在可控制的範圍內盡量蹲低。","膝蓋對齊腳尖，保持挺胸。","腳跟推地站起。","完成次數後換腿。"],"1137":["仰臥，雙腳放進懸吊帶，膝蓋彎曲。","雙手放在頭側或胸前交叉。","捲起軀幹朝向膝蓋。","在頂點收緊腹肌。","慢慢躺回。","避免拉扯脖子。"],"1138":["雙腳放進懸吊帶，擺出高棒式。","往下做伏地挺身。","下壓時，將單膝拉向同側手肘。","推起身體，同時把腿往後伸直。","每次交替換邊。","髖部維持低位且穩定。"],"1139":["握住握把，跨出成前後分腿站姿並身體前傾。","手臂微彎，雙手在身前。","雙臂往兩側大幅打開。","在伸展終點收緊肌肉，不要聳肩。","控制速度把雙臂合回。","做到一半時換前腳。"],"1140":["握住握把，身體微微前傾。","單腿站立，另一膝抬起。","一側提膝時，對側手臂跟著擺動。","輕跳快速換腿。","全程用前腳掌著地。","核心收緊，維持穩定節奏。"],"1141":["雙臂打直，在頭頂上方握住握把。","雙腳與肩同寬站立。","髖部往後往下坐成深蹲。","雙臂保持高舉，挺胸。","腳跟推地站起。","下背不要拱起。"],"1143":["雙臂伸直握住握把。","雙腳與肩同寬站立。","髖部往後坐，彎曲膝蓋。","下蹲到大腿與地面平行。","腳跟推地站起。","保持挺胸，膝蓋對齊腳尖。"],"1144":["雙手在身前握住握把，身體向前傾。","收緊腹肌，骨盆微收。","身體向前延伸的同時，將雙臂往頭頂方向伸展。","在下背拱起之前停住。","用腹肌發力拉回起始位置。","需要的話可以縮小動作幅度。"],"1145":["雙腳套進吊帶，擺出高棒式姿勢。","將雙腿往兩側寬距打開。","保持髖部水平、身體呈一直線。","收緊腹肌。","維持 20-30 秒。","保持平穩呼吸，腰部不要塌陷。"],"1146":["雙腳套進吊帶並寬距打開，擺出高棒式。","保持核心收緊。","將胸口朝地板下放。","手肘與身體維持約 45 度。","推回上方。","整組動作都維持雙腿寬距打開。"],"1147":["仰躺，雙腳套進吊帶並將雙腿抬高。","雙臂平放在地面。","將髖部往上捲起，膝蓋拉向胸口。","在頂點收緊腹肌。","慢慢放回起始位置。","不要擺動雙腿。"],"1148":["仰躺，雙腳腳跟套進吊帶。","腳跟下壓，將髖部抬起。","讓肩膀到腳跟呈一直線。","夾緊臀肌並收緊腹肌。","維持 20-30 秒。","有控制地放下。"],"1149":["握住握把，雙臂伸直並將身體前傾。","保持身體呈一直線。","彎曲手肘，將額頭降到雙手之間。","保持手肘朝前。","推回雙臂伸直的位置。","雙腳往後退可以增加難度。"],"1150":["握住握把，身體向前傾，手肘貼在身體兩側。","保持上臂固定不動。","伸直雙臂並往身後推。","在末端收緊三頭肌。","慢慢彎曲手肘回到原位。","保持背部平直。"],"1151":["雙腳套進吊帶，擺出高棒式姿勢。","收緊核心。","將髖部扭向一側，帶動膝蓋跨過身體。","有控制地回到中間。","扭向另一側。","保持雙肩朝正前方。"],"1152":["雙腳套進吊帶，擺出高棒式姿勢。","將雙膝往上拉，並轉向其中一側手肘。","短暫停頓並收緊腹斜肌。","雙腿往後伸直回到棒式。","換邊重複。","雙手穩穩撐在地面。"],"1153":["握住握把往後退，讓雙臂打直。","髖部往後坐，壓低胸口。","輕輕拱起上背，將吊帶往外推。","感受肩胛骨之間的伸展。","維持 20-30 秒。","緩慢呼吸並回到原位。"],"1154":["握住握把站立，雙腳與髖部同寬。","保持身體直立。","以前腳掌用力，盡量將腳跟墊到最高。","短暫停頓並收緊小腿。","若覺得舒適，將腳跟慢慢降到比起始位置更低。","吊帶只用來輔助平衡。"],"1155":["握住握把，單腳站立。","站立腳膝蓋微彎。","髖部往後折，另一腿往身後延伸。","保持背部平直、髖部擺正。","夾緊臀肌站回直立。","完成次數後換腳。"],"1156":["雙腳套進吊帶，擺出高棒式姿勢。","收緊核心。","雙腿併攏擺向一側。","經過中間擺向另一側。","動作保持緩慢且受控。","保持雙肩穩定。"],"1157":["握住握把、雙臂伸直，雙腳與髖部同寬。","膝蓋微彎。","背部打直，將髖部往後推。","靠吊帶支撐平衡。","髖部往前推，站直身體。","在頂點夾緊臀肌。"],"1158":["握住握把，雙腳大幅往兩側跨開。","重心移向一側並彎曲該側膝蓋。","另一腿保持伸直。","臀部往後坐，進入伸展姿勢。","維持 20-30 秒。","換邊進行。"],"1159":["握住握把並站直。","往一側跨出大步。","彎曲該側膝蓋，將髖部往後推。","保持挺胸，另一腿伸直。","推地回到原位。","左右交替進行。"],"1160":["從站立姿勢開始，雙腳分開與肩同寬。","彎曲膝蓋並將雙手放在身前的地板上，下沉至蹲姿。","雙腳向後跳躍蹬出成伏地挺身預備姿勢（高棒式）。","完成一次伏地挺身，全程保持身體成一直線。","雙腳向前跳回蹲姿。","爆發力向上起跳，雙臂舉過頭頂。","輕巧落地並立即回到深蹲姿勢，開始下一次重複。"],"1161":["坐在器材上固定雙腳，雙臂伸直握住握把。","先用雙腿用力推，接著身體微向後傾。","手肘貼近身體，將握把拉向下肋骨位置。","依相反順序回放：雙臂伸出、髖部前傾，最後彎曲膝蓋向前滑回。","以舒適的配速保持流暢節奏，持續 10-30 分鐘。"],"1162":["在肩膀高度起槓，雙手握距略寬於肩。","站直，雙腳與髖部同寬並夾緊臀肌。","將槓鈴筆直往上推，頭部先稍微後讓再往前穿出。","在頭頂完全伸直手臂鎖定，槓鈴位於足弓正上方。","有控制地將槓鈴放回鎖骨位置。"],"1163":["仰躺，雙腿伸直，雙手墊在髖部下方。","將下背輕輕壓向地板。","雙腿併攏抬起，直到指向天花板。","慢慢放下雙腿，在離地一點點的位置停住。","全程避免下背拱起。"],"1164":["將槓鈴扛在肩上，以前腳掌踩在踏板上站立。","膝蓋保持接近伸直，軀幹直立。","下放腳跟直到完全伸展。","盡可能將腳尖墊到最高。","在頂點短暫停頓，接著有控制地放下。"],"1165":["用安全的上搏，或硬舉接彎舉的方式，將槓鈴從地面提到鎖骨位置。","雙腳與髖部同寬，雙手握距略寬於肩。","收緊核心與臀肌。","將槓鈴筆直往頭頂推至手臂完全鎖定。","有控制地放回鎖骨位置並重複。"],"1166":["採分腿站姿開始，微蹲進入弓步。","下蹲後用力向上跳起。","在空中交換雙腿前後位置。","輕柔落地，換另一腿在前呈弓步。","保持軀幹直立，以穩定節奏重複。"],"1167":["站直，雙腳分開與肩同寬。","雙臂向兩側水平伸展，與地面平行。","慢慢將雙臂向前收，在胸前交叉。","感受胸部肌群的拉伸感。","保持拉伸 10-30 秒。","回到起始位置並重複所需次數。"],"1168":["面朝下趴著，雙手放在肩膀下方。","慢慢將身體推起，在舒適範圍內盡量伸直雙臂。","保持髖部貼地，放鬆臀肌。","眼睛看向前方，感受腹部的伸展。","維持 20-30 秒，接著放下身體。"],"1169":["在地板上坐直，雙腳腳底相對。","握住雙腳或腳踝，讓膝蓋自然往兩側下沉。","保持背部平直並挺胸。","從髖部微微往前傾，直到感覺有伸展感。","維持 20-30 秒並緩慢呼吸。"],"1170":["將靠墊調到髖部下方，單腳勾住滾筒，另一腿抬離。","雙臂交叉抱胸，保持身體呈一直線。","背部打直，將軀幹朝地面下放。","夾緊臀肌將身體抬起，直到身體呈一直線，不要過度反折。","完成所有次數後換腳。"],"1171":["趴在長凳上，腳踝卡在靠墊下，髖部剛好露在靠墊邊緣外。","雙臂交叉抱胸，背部打直將軀幹下放。","夾緊臀肌，將軀幹抬起。","在頂點時，將上半身輕輕轉向一側，再轉回中間。","每一下交替換邊，動作保持緩慢且受控。"],"1172":["擺出棒式，雙手在肩膀正下方，將負重放在上背。","收緊核心，保持身體呈一直線。","將胸口朝地面下放。","推起身體直到手肘伸直。","視需要使用輔助，讓每一下動作都標準乾淨。"],"1173":["躺在上斜長凳上，掌心朝自己、寬距握住槓鈴。","起槓，將槓鈴穩定在上胸上方。","手肘微收，將槓鈴下放到上胸。","推起直到手肘完全伸直。","這種握法較不穩定，建議請人護槓。"],"1174":["跪在地面，雙手放在胸口下方，拇指與食指相觸成鑽石形。","保持膝蓋到頭部呈一直線。","手肘貼近身體，將胸口朝雙手下放。","往上推直到雙臂伸直。","全程保持核心收緊。"],"1175":["雙手各持一個啞鈴站直，雙腳與髖部同寬。","一腳往前跨出，背部保持平直、胸口微微前傾。","下蹲直到雙膝都彎曲約 90 度。","前腳腳跟推地，回到站姿。","雙腿交替進行，或單邊完成所有次數再換腳。"],"1176":["面朝下趴或仰躺在上斜長凳上，雙手持啞鈴。","雙臂自然下垂或置於身前開始。","雙臂保持伸直，將啞鈴往前舉到肩膀高度。","在頂點短暫停頓。","有控制地慢慢放下。"],"1177":["躺在長凳上，雙手持啞鈴、掌心相對。","將啞鈴舉在胸口上方開始。","手肘微收，將啞鈴下放到胸口兩側。","往上推直到雙臂伸直。","雙腳踩穩地面，肩胛骨保持後收夾緊。"],"1178":["單手持啞鈴，單腳站在台階上。","另一手扶牆或欄杆維持平衡。","下放腳跟直到完全伸展。","盡可能將腳尖墊到最高。","完成次數後換腳。"],"1179":["仰躺，雙手墊在髖部下方。","將雙腿抬離地面幾吋。","雙腿以小幅度快速上下交替踢動。","將下背壓緊地面。","持續 20-40 秒。"],"1180":["仰躺，雙腿伸直，雙手墊在髖部下方或放在身體兩側。","將下背壓向地板並收緊腹肌。","雙腿保持伸直，一腿抬起的同時另一腿朝地面下放。","如剪刀般流暢交替雙腿，不讓下背拱起。","依設定的次數或時間持續進行。"],"1181":["仰躺，雙腿伸直，雙手墊在髖部下方。","將下背壓緊地面。","雙腿併攏抬起，直到指向天花板。","慢慢放下雙腿，在離地一點點的位置停住。","保持核心收緊，避免下背拱起。"],"1182":["跪在地面，雙手撐地略寬於肩。","保持頭部到膝蓋呈一直線。","彎曲手肘，將胸口朝地面下放。","往上推直到雙臂伸直。","保持核心收緊，髖部不要下塌。"],"1183":["將槓鈴設在低位，四足跪姿面向槓鈴，單腳腳底抵在槓鈴下方。","收緊腹肌並保持背部平直。","腳底用力將槓鈴往上往後推，直到髖部完全伸展。","在頂點夾緊臀肌，接著有控制地放下。","完成次數後換腳。"],"1184":["將槓鈴設在腰部高度，躺在下方並在軀幹放上額外負重。","雙手握槓，略寬於肩。","保持腳跟到頭部呈一直線。","將胸口拉向槓鈴。","有控制地放下。"],"1186":["仰躺在波速球上支撐下背，雙手輕扶球體。","收緊腹肌並伸直雙腿。","保持腿部伸直，將單腿抬起。","放下後換另一腿抬起。","保持軀幹穩定，有控制地移動。"],"1187":["仰躺屈膝，雙手將壺鈴抱在胸前。","收緊核心。","往上捲起身體直到軀幹直立。","保持壺鈴貼近身體。","慢慢躺回地面。"],"1188":["仰躺在長凳上，雙膝彎曲，胸前抱著重物。","收緊腹肌，將上半身往上捲起。","轉動軀幹，讓一側手肘朝對側膝蓋移動。","慢慢躺回，過程保持肌肉張力不放掉。","每一下交替換邊。"],"1189":["坐在波速球上，身體稍微後傾，雙手在胸前拿著負重。","雙腳離地，雙腿彎曲或伸直都可以。","胸口和膝蓋往中間靠攏，讓身體呈 V 字形。","脊椎保持延伸，有控制地躺回原位。","全程在球上保持穩定。"],"1190":["躺在上斜長凳上，雙腳固定好。","雙手輕放在頭後方。","捲起上半身，同時把軀幹轉向一側。","慢慢躺回原位。","每次交替換邊。"],"1191":["躺在長凳上，頭部剛好超出邊緣，雙手在頭頂上方拿著負重。","上臂保持穩定並朝上。","彎曲手肘，把負重往頭部方向放下。","將手臂推直。","手肘保持往內收好。"],"1193":["從棒式開始，雙手在肩膀正下方。","手腳往外張開，呈 X 字形。","收緊核心，讓髖部保持水平。","保持平穩呼吸。","維持 20-40 秒。"],"1194":["胸口貼在軟墊上趴好，握住把手。","開始時手臂伸直。","把把手往身體方向拉。","夾緊肩胛骨。","有控制地放回原位。"],"1195":["調整座椅高度，讓把手對準上胸位置。","向後坐好，肩胛骨貼緊背墊，以對握方式握住把手。","將把手往前上方推，直到手臂接近伸直。","慢慢放回，直到感覺胸部有伸展感。","手腕保持打直，背部貼緊背墊。"],"1196":["站直，雙手各拿一顆啞鈴，掌心朝前。","手肘貼近身體兩側，將一邊的啞鈴往肩膀方向彎舉。","在頂端收緊二頭肌，再有控制地放回。","換另一隻手重複動作，兩邊交替執行。","避免靠甩動身體把重量帶起來。"],"1197":["雙腳約與肩同寬站立，腳尖微朝外。","髖部往後推、彎曲膝蓋往下蹲。","在腳跟貼地、挺胸的前提下，盡量蹲到最深。","雙腳踩穩地面，發力站回起始位置。","膝蓋保持對準腳尖方向。"],"1198":["站在單槓下方，雙手握距略寬於肩。","彎曲膝蓋往上跳，順勢把下巴拉過單槓。","在頂端停頓一下。","慢慢將身體放低，直到手臂完全伸直。","雙腳踩回地面重新準備，接著重複動作。"],"1199":["採寬站距，雙手窄握雙腿中間的槓鈴。","背部打直，雙腿發力站起。","槓鈴經過髖部時，手肘抬高，順勢將槓鈴拉到胸口高度。","沿著原本的軌跡把槓鈴放回。","全程讓槓鈴貼近身體。"],"1200":["將槓鈴架在上胸位置，手肘稍微在槓鈴前方。","軀幹保持直立，膝蓋微彎往下蹲幾公分。","雙腿用力往上蹬，順勢將槓鈴推過頭頂。","在足弓正上方推直鎖定，再將槓鈴放回胸前。","收緊核心，避免身體往後仰。"],"1201":["從站立姿勢開始，雙腳分開與肩同寬，雙手各持一個啞鈴。","下沉至深蹲姿勢，將啞鈴放在身前的地面上。","雙腳向後跳成伏地挺身姿勢，保持身體呈一直線。","進行一次伏地挺身，彎曲手肘將胸部靠近地面。","雙腳向前跳回雙手後方，成深蹲姿勢著地。","爆發力站起，將啞鈴順勢從地面拉起並翻轉置於肩上。","手臂完全向上伸展，將啞鈴推過頭頂。","將啞鈴收回肩膀處，接著重複整個動作流程至所需次數。"],"1202":["將滑輪設定在胸口高度，側身面對器械站立。","雙手在胸前握住把手，收緊核心。","將把手往正前方推出，直到手臂伸直。","停留 1 秒，不要讓身體被拉過去扭轉。","收回胸前，做完這組次數後換邊。"],"1203":["將把手裝在低位滑輪上，面對器械站立。","單手反握把手，掌心朝上，手肘稍微往外轉。","將把手往肩膀方向彎舉。","在頂端收緊肌肉，再有控制地放回。","完成單邊所有次數後換手。"],"1204":["將把手裝在高位滑輪上，面對器械坐好。","單手握住把手，坐直身體。","手肘往髖部方向帶，將把手拉到胸口外側。","停頓一下，再讓手臂慢慢往上回放。","做完單邊次數後換邊。"],"1205":["坐在低位滑輪前，雙腳踩穩，單手握住把手。","開始時上半身稍微轉向滑輪方向。","將把手拉向身體側面，同時把胸口轉開。","肩胛骨往後夾緊，再慢慢回放。","做完所有次數後換手。"],"1206":["將繩索裝在低位滑輪上，背對器械站立，雙手從雙腿之間握住繩索。","往前走直到滑輪繩拉緊，膝蓋微彎。","髖部往後推，讓繩索往雙腿後方穿過去。","髖部往前推、夾緊臀肌，直到身體站直。","全程保持背部平直。"],"1207":["將滑輪調到低位，側身對著器械站立，雙手握住把手。","開始時把手靠近下側髖部，雙手大致伸直。","轉動軀幹，將把手斜向往上拉過身體前方。","後腳順勢轉動，髖部保持穩定。","慢慢回放，完成單邊次數後換邊。"],"1208":["將滑輪調到高位，側身對著器械站立，雙手握住把手。","開始時把手在肩膀上方，雙手大致伸直。","轉動軀幹，將把手斜向往下拉過身體前方。","保持髖部穩定並收緊核心。","慢慢回放，完成單邊次數後換邊。"],"1209":["將滑輪調到低位並側身站立，在肩膀位置握住把手。","收緊核心，身體稍微轉向滑輪。","將把手推過頭頂，同時把軀幹轉向正前方。","有控制地把把手放回肩膀位置。","完成單邊次數後換邊。"],"1210":["將滑輪設定在大約頭部高度，面對器械站立，單手握住把手。","採前後分腿站姿，身體稍微後傾。","將把手拉向上胸，同時順勢轉動軀幹。","夾緊肩胛骨，再慢慢回放。","做完這組後換邊。"],"1211":["將滑輪設定在胸口高度，側身站立，用靠近器械那側的手握住把手。","站穩腳步，把把手停在胸前。","將把手往前推，同時讓軀幹順著推的方向轉動。","有控制地回到起始位置。","完成單邊次數後換邊。"],"1212":["將滑輪設定在中間高度，面對器械站立，單手握住把手。","踩穩腳步，身體稍微後傾。","將把手拉向肋骨位置，同時把軀幹轉開。","在動作末端夾緊肩胛骨。","慢慢回放，完成單邊次數後換邊。"],"1213":["將滑輪設定在高位或低位，側身面對器械站立。","雙手在胸前握住把手。","沿著垂直線將把手直直往上（或往下）推。","停留 1 秒，不要讓身體扭轉。","收回胸前，做完這組後換邊。"],"1214":["將長凳設定在約 30 度，躺下後雙手反握啞鈴，掌心朝向自己。","開始時將啞鈴停在胸口上方。","往上推，直到手臂接近伸直。","慢慢將啞鈴放回胸口位置。","手肘保持貼近身體兩側。"],"1215":["雙手各拿一顆啞鈴，或雙手在胸前抱一顆啞鈴，站直身體。","往側面跨出一大步，髖部往後坐。","另一隻腳保持伸直，挺胸不駝背。","彎曲的那隻腳踩地發力，推回中間起始位置。","可以左右交替，或單邊做完所有次數再換邊。"],"1216":["坐在器械上，將單腳前腳掌踩在踏板上。","將軟墊壓在大腿上，解開安全扣。","放低腳跟，充分伸展小腿。","盡量把腳跟往上推到最高，墊起腳尖。","停頓一下，慢慢放低，完成後換腳。"],"1220":["坐在器械上，雙腳前腳掌踩在下方的踏板或推板上。","往前推直雙腿，解開安全扣。","在舒適的範圍內盡量放低腳跟。","墊起腳尖，盡可能往上推到最高。","在頂端停頓一下，再有控制地放低。"],"1221":["調整器械讓把手位在身體兩側，雙手握緊。","站直或坐直，手臂保持伸直。","將肩膀直直往耳朵方向聳起。","在頂端停頓一下。","慢慢放下肩膀，不要轉動肩關節。"],"1222":["設定好輔助重量，跪在或站在踏板上。","雙手窄距反握單槓，掌心朝向自己。","將身體往上拉，直到下巴超過單槓。","在頂端收緊背部與二頭肌。","慢慢放低身體，直到手臂伸直。"],"1223":["將槓鈴設定在腰部高度，躺到槓下，雙手反握槓鈴，掌心朝向自己。","讓身體從腳跟到頭頂呈一直線。","將胸口往槓鈴方向拉，夾緊肩胛骨。","有控制地放低身體，直到手臂伸直。","全程保持髖部挺直不下掉。"],"1224":["將槓鈴設定在肩膀高度，站在槓下，雙手約與肩同寬握槓。","起槓後，將槓鈴停在鎖骨位置。","往上推，直到手臂伸直。","慢慢把槓鈴放回肩膀高度。","收緊核心，肋骨收好不外翻。"],"1225":["站直，雙手握住槓片兩側，停在胸口高度。","收緊核心，手肘稍微朝前。","將槓片推過頭頂，直到手臂伸直。","慢慢將槓片放回胸前。","肋骨收好，避免腰部過度拱起。"],"1226":["站立，用舒適的握距將 EZ 槓拿在上胸位置。","收緊核心並夾緊臀肌。","將槓鈴推過頭頂，直到手臂伸直。","慢慢將槓鈴放回胸前。","頭部保持中立，避免身體往後仰。"],"1227":["將把手裝在高位滑輪上，面對器械站立。","單手正握把手，手肘貼緊身體側面。","往下壓，直到手臂完全伸直。","收緊三頭肌，再讓把手慢慢回升。","完成單邊次數後換手。"],"1228":["站直，雙手各拿一顆啞鈴，手肘稍微往身體外側轉開。","將啞鈴往肩膀方向彎舉。","在頂端收緊二頭肌。","慢慢放回起始位置。","上臂保持穩定不動。"],"1229":["將繩索裝在高位滑輪上，面對器械站立，上半身稍微前傾。","手臂保持伸直，握住繩索。","手臂維持接近伸直的狀態，將繩索往下壓到大腿前側。","在底部收緊背闊肌。","讓繩索慢慢回升到肩膀高度。"],"1230":["站立，雙手在大腿旁拿著啞鈴，掌心相對。","將一邊的啞鈴直直往前舉到肩膀高度。","停頓一下，再慢慢放回。","換另一隻手重複，兩邊交替執行。","避免晃動身體借力。"],"1231":["坐在有背墊支撐的長凳上，單手在肩膀高度拿著啞鈴。","收緊核心。","將啞鈴往上推，直到手臂伸直。","慢慢將啞鈴放回肩膀位置。","完成單邊次數後換手。"],"1232":["坐在器械上，背部貼緊背墊，肩膀靠在肩墊下方。","雙腳踩在踏板上，約與肩同寬。","雙腳發力往前推，直到雙腿伸展。","慢慢放回，直到膝蓋彎曲到舒適的角度。","膝蓋保持對準腳尖方向。"],"1233":["躺靠在上斜長凳上，雙手拿著啞鈴，掌心相對。","讓雙手自然往下垂放。","手腕不轉動，將一邊的啞鈴往上彎舉。","慢慢放下，再換另一隻手重複。","上臂保持穩定不動。"],"1234":["調整羅馬椅，讓髖部剛好超出軟墊邊緣。","將槓片貼在胸前，雙手交叉抱穩。","背部保持平直，將上半身往地面方向放低。","抬起上半身，直到身體呈一直線。","在頂端夾緊臀肌，避免腰部過度後仰。"],"1235":["坐在器械上，胸口貼穩軟墊，單手握住把手。","開始時手臂往前伸展。","手肘往後帶，將把手拉向身體。","夾緊肩胛骨，再慢慢放回。","完成單邊次數後換手。"],"1236":["單手扶在架子或穩固物體上，髖部後推、上半身前傾並保持背部平直。","另一隻手拿啞鈴，自然下垂。","將啞鈴往髖部方向拉起。","在頂端收緊背部，再慢慢放回。","完成單邊次數後換手。"],"1237":["調整好座椅與胸墊位置，握住把手。","坐直身體，胸口貼緊軟墊。","將把手拉向身體，同時夾緊肩胛骨。","停頓一下。","慢慢放回，直到手臂伸直。"],"1238":["坐在低位滑輪機前，雙腳踩在踏板上，膝蓋微彎。","雙手握住彎桿。","背部保持挺直，將握桿拉向下胸肋骨處。","夾緊肩胛骨。","慢慢伸直手臂回放，注意不要圓背往前探。"],"1241":["採四足跪姿，雙手在肩膀正下方，膝蓋在髖部正下方。","右手往前延伸，同時左腳往後踢直。","保持髖部水平、背部平直。","停留一下，再回到起始位置。","換邊重複，左右交替執行。"],"1242":["坐在波速球上往後躺，讓球支撐在下背處。","雙手輕放在頭後方。","收縮腹肌，將肩膀往上捲起。","在頂端短暫停留。","慢慢放回，雙腳保持踩穩地面。"],"1243":["仰臥，雙手朝上舉直，膝蓋彎曲呈 90 度。","將下背貼緊地面。","將右手與左腳同時往地面方向放低。","收回原位後換邊。","動作放慢，全程保持下背貼平。"],"1244":["仰臥，雙腿伸直，雙手墊在髖部下方。","將雙腿抬離地面幾公分。","雙腿一上一下做小幅度的交替踢水動作。","保持下背貼緊地面。","維持平穩呼吸，持續踢動至設定的時間。"],"1245":["仰臥，雙腿伸直，雙手放在身體兩側。","將下背貼緊地面。","將雙腿往上抬，直到與地面垂直。","將雙腿放低到離地一點點的位置，停留幾秒。","重複動作，注意不要讓下背拱起。"],"1246":["仰臥，雙手往頭頂上方延伸，雙腿伸直。","將下背貼緊地面。","將肩膀與雙腿抬離地面幾公分。","維持這個姿勢，保持平穩呼吸。","撐住 20-30 秒後休息。"],"1247":["坐姿屈膝，身體稍微後傾，雙手在胸前拿著藥球。","能力許可的話，可以將雙腳稍微抬離地面。","將軀幹轉向一側，讓藥球輕點髖部旁邊的地面。","接著轉向另一側。","保持挺胸，有控制地完成動作。"],"1248":["仰臥，雙手往兩側打開貼地作為支撐。","抬起雙腿，讓膝蓋彎曲呈 90 度。","將雙膝往一側放低，在碰到地面前停住。","帶回中間，再往另一側放低。","全程保持雙肩貼緊地面。"],"1249":["仰臥，雙手往兩側打開貼地。","將雙腿伸直舉到髖部正上方。","有控制地將雙腿往一側放低。","將雙腿抬回中間，再往另一側放低。","全程保持雙肩平貼地面。"],"1250":["仰臥，雙膝彎曲，雙腳平踩地面。","雙手在頭後方拿著負重，手肘朝外打開。","收縮腹肌，將肩膀往上捲起。","在頂端停頓一下。","慢慢躺回原位，注意不要拉扯脖子。"],"1253":["調整小腿訓練機（提踵機）至適合身高的高度。","面對機器站立，前腳掌踩在踏台上，腳跟懸空於邊緣外。","雙手扶在把手或支撐桿上以保持穩定。","利用前腳掌發力收縮小腿，盡可能將腳跟抬高。","在最高點稍作停頓，然後慢慢放低腳跟回到起始位置。","重複所需次數。"],"1254":["平躺在重訓椅上，雙腳踩實地面，背部緊貼椅面。","正握抓住彈力帶手把，握距略寬於肩寬。","手臂完全伸展，將彈力帶推離胸口。","慢慢將彈力帶降回胸前，手肘保持 90 度角。","重複所需次數。"],"1255":["躺在下斜臥推椅上，頭部低於臀部，雙腳固定妥當。","正握抓住槓鈴（掌心朝外/背向自己），雙手間距略寬於肩寬。","將手臂推至胸部上方，手肘保持微彎。","以弧線動作將槓鈴向頭後方放下，感受胸部與肩膀的拉伸。","稍作停頓，然後沿反向弧線將槓鈴帶回起始位置。","重複所需次數。"],"1256":["躺在下斜臥推椅上，雙腳固定，頭部低於臀部。","反握抓住槓鈴，握距略寬於肩寬。","起槓後慢慢將槓鈴降至胸部，手肘適度內收。","在最低點稍作停頓，然後將槓鈴推回起始位置。","重複所需次數。"],"1257":["將重訓椅調整至約 45 度上斜角度。","躺在椅上，雙腳踩實地面。","反握抓住槓鈴，雙手間距略寬於肩寬。","起槓後慢慢將槓鈴降至上胸處，手肘保持內收。","槓鈴輕觸胸口時稍作停頓。","將槓鈴推回起始位置，雙臂完全伸展。","重複所需次數。"],"1258":["平躺在重訓椅上，雙腳踩實地面，背部貼緊椅面。","寬握距反握抓住槓鈴，握距略寬於肩寬。","將槓鈴起槓並推至胸部正上方，雙臂完全伸直。","慢慢將槓鈴降向胸部，手肘微扣、手腕打直。","槓鈴輕觸胸部時稍作停頓，隨後將其推回起始位置。","重複所需次數。"],"1259":["站直，雙腳分開與肩同寬。","十指交扣放在後腦勺，手肘朝外展開。","慢慢將肩胛骨向內夾緊，同時胸部向前挺。","保持拉伸 15-30 秒。","放鬆伸展，視需求重複。"],"1260":["將滑輪機調至低位。","背對滑輪機站立，單手握住把手。","背靠在下斜重訓椅上，手臂在身前伸直。","彎曲手肘將把手朝胸部方向降下，同時保持上臂固定。","在底部稍作停頓，然後將把手推回起始位置。","重複所需次數，然後換手。"],"1261":["將滑輪機調至低位。","坐在面向滑輪機的下斜重訓椅上。","正握抓住把手，置於胸部水平位置。","雙腳踩穩地面，背部牢牢靠在椅背上。","吐氣並將把手向外推離身體，雙臂完全伸展。","動作頂端稍作停頓，收縮擠壓胸肌。","吸氣並慢慢將把手帶回起始位置。","重複所需次數。"],"1262":["將 D 型握把連接在低滑輪機上，並將重訓椅設定為下斜角度。","躺在椅上，頭朝向滑輪機，右手抓住把手。","將手臂伸直於胸部上方，手肘保持微彎。","在控制下將手臂向外側放低，直到手與肩膀成一直線。","稍作停頓，然後依反向軌跡將手臂帶回起始位置。","重複所需次數，換左手重複進行。"],"1263":["坐在抗力球上，雙腳踩平地面，背部打直。","單手握住滑輪把手，將手臂向側邊伸展，與地面平行。","手肘微彎，掌心朝前。","慢慢將手臂向胸前收攏內收，擠壓胸部肌群。","動作結束時稍作停頓，然後慢慢回到起始位置。","重複所需次數，然後換邊。"],"1264":["坐在抗力球上，雙腳平放地面，背部斜靠在球上。","單手握住滑輪把手，手臂伸直，掌心朝內。","手肘微彎，慢慢將手臂向側下方展開，直到手與肩膀成一直線。","稍作停頓，然後胸肌發力將手臂帶回起始位置。","重複所需次數，然後換手。"],"1265":["將滑輪機調整至低滑輪位置。","坐在上斜重訓椅上，背對滑輪機。","單手握住把手並舉至肩膀高度。","雙腳踩實地面，維持軀幹穩定。","將把手向前上方推起，完全伸展手臂。","在最高點稍作停頓，然後慢慢將把手降回起始位置。","重複所需次數，然後換邊。"],"1266":["坐在抗力球上，雙腳踩實地面，背部靠在斜面上。","單手握住滑輪把手，手臂彎曲呈 90 度角。","向前上方推舉滑輪把手，完全伸直手臂。","在頂部稍作停頓，然後慢慢將把手帶回起始位置。","重複所需次數，然後換另一隻手。"],"1267":["坐在抗力球上，雙腳平放地面，背部挺直。","單手握住滑輪把手，置於胸部高度，手肘彎曲。","另一隻手叉腰以維持軀幹穩定。","將滑輪把手向前推，完全伸展手臂。","稍作停頓，然後慢慢回到起始位置。","重複所需次數，然後換手。"],"1268":["坐在抗力球上，雙腳踩平地面，膝蓋呈 90 度角。","將滑輪把手維持在胸部高度，掌心朝下，手肘彎曲。","收緊核心，向前推動滑輪把手直到手臂完全伸直。","稍作停頓，然後控制張力慢慢將把手收回胸前。","重複所需次數。"],"1269":["站在滑輪機（飛鳥機）中央，雙腳分開與肩同寬。","掌心朝下握住纜繩把手，手臂向兩側展開。","保持雙臂伸展，將雙手向胸前收攏並交叉。","稍作停頓，然後在控制下慢慢回到展開的起始位置。","重複所需次數。"],"1270":["將握把固定在滑輪機約胸部的高度。","站在滑輪交叉機正中央，採前後弓箭步站姿。","掌心朝下握住把手，手臂向兩側伸展。","手肘保持微彎，啟動核心肌群。","將兩側纜繩向胸前靠攏交叉。","在動作極限處用力擠壓收縮胸大肌。","控制速度慢慢放回起始位置。","重複所需次數。"],"1271":["站直，雙腳分開與肩同寬。","雙臂向前水平伸出，與肩同高。","雙臂在身前交叉，右臂疊在左臂上方。","雙手手指交扣，掌心貼合。","輕輕向內夾緊肩胛骨，同時將雙手向前推，伸展胸部與三角肌前束。","維持伸展 20-30 秒，然後放鬆。","重複所需次數。"],"1272":["坐在抗力球上，雙腳平放地面，背部挺直。","雙手抱住一顆抗力球，雙臂向前伸直。","慢慢將抗力球壓向胸部，感受胸肌收緊與伸展。","保持伸展數秒，然後慢慢回到起始位置。","重複所需次數。"],"1273":["從高棒式（伏地挺身預備姿勢）開始，雙手間距略寬於肩寬。","彎曲手肘，核心收緊，將身體降向地面。","手掌用力推地產生爆發力，將上半身彈離地面。","在空中快速拍手一次，隨後穩穩著地回到起始姿勢。","重複所需次數。"],"1274":["從高棒式開始，雙手略寬於肩，身體從頭到腳呈一直線。","彎曲手肘，將胸部下沉靠近地面。","雙手推地伸直手臂，推回起始位置。","重複所需次數。"],"1275":["從高棒式開始，雙手間距略寬於肩寬。","胸部降向地面，手肘微收貼近軀幹。","當胸口快要接觸地面時，迅速將膝蓋著地支撐。","手臂推直，將身體推回起始位置。","重複所需次數。"],"1276":["躺在上斜椅上，單手持啞鈴置於大腿上。","用大腿輔助將啞鈴頂至肩部位置，掌心朝向軀幹。","旋轉手腕使掌心朝前。","吸氣時，慢慢將啞鈴下放至一側，直到感受胸部拉伸。","吐氣，胸肌發力將啞鈴推回起始位置。","重複所需次數，然後換手。"],"1277":["坐在抗力球上，雙手各持一個啞鈴。","雙腳向前走，身體順著球體向下滑，直到頭部、頸部與上背部獲得球體穩固支撐。","雙臂伸展於胸部上方，掌心相對。","手肘保持微彎，將雙臂以大弧度向兩側打開，直到感受胸部拉伸。","稍作停頓，然後胸大肌發力將啞鈴夾回胸部上方。","重複所需次數。"],"1278":["將重訓椅調整至約 45 度上斜角。","坐在抗力球上，往前滾動直到上背部靠在斜椅上。","雙手各握啞鈴，掌心相對，手臂伸直於胸前。","將啞鈴向兩側弧形展開放低，感受胸大肌拉伸。","稍作停頓，然後胸肌發力將啞鈴收回起始位置。","重複所需次數。"],"1279":["將上斜重訓椅調整為 30-45 度。","坐在椅上，單手握啞鈴放在大腿上。","向後躺平在斜椅上，雙腳踩穩地面。","單手將啞鈴推直於胸部上方。","手肘微彎，將啞鈴以弧形向側邊下放展開。","當手臂與地面大致平行時稍作停頓，然後胸肌發力推回起始位置。","重複所需次數，然後換手。"],"1280":["坐在抗力球上，單手持啞鈴。","雙腳向前踏步，身體向下滾動，直到頭、頸、上背靠在球上。","單手將啞鈴推直於胸前，掌心朝內。","手肘微彎，控制著將啞鈴向外側放低。","手臂接近平行地面時稍作停頓。","啟動胸大肌，將啞鈴拉回起始位置。","重複所需次數，然後換邊。"],"1281":["坐在上斜椅上，單手持啞鈴放在大腿上。","躺上椅背，將啞鈴提至肩膀高度，掌心朝前。","將啞鈴向上並微向內推起，手臂完全伸直。","在頂端稍作停頓，然後慢慢降回起始位置。","重複所需次數，然後換另一隻手。"],"1282":["坐在抗力球上，單手持啞鈴，雙腳平踩地面。","雙腳緩步向前移動，將球滾動至頭部、頸部與上背部平穩支撐。","將啞鈴持於肩膀高度，掌心朝前。","向上推舉啞鈴，直到手臂完全伸直。","在最高點稍作停頓，然後緩緩降回起始位置。","重複所需次數，換手重複。"],"1283":["坐在抗力球上，雙手各持一啞鈴，掌心朝前。","雙腳慢慢往前踏，身體順著球滑動，直到頭、頸、上背獲得支撐。","將啞鈴維持在肩部高度，手肘彎曲朝向兩側。","向上推舉啞鈴，手臂完全伸直。","在最高點稍作停頓，然後慢慢降回肩部起始位置。","重複所需次數。"],"1284":["坐在抗力球上，往前滑步直到上背部躺在球面上。","雙手合握一個啞鈴，將手臂伸直於胸部上方。","保持手臂微彎打直，慢慢將啞鈴呈弧線放向後腦勺。","稍作停頓，胸肌與背肌協同發力將啞鈴拉回起始位置。","重複所需次數。"],"1285":["坐在平凳上，單手持啞鈴置於大腿前側。","躺下時順勢用大腿將啞鈴頂至胸部上方。","空出的手可輔助支撐或置於身側維持平衡。","啞鈴垂直於肩部上方，掌心朝內。","手肘保持微彎，將啞鈴向側邊以弧線放低展開。","手臂接近水平時稍作停頓，然後胸肌發力將啞鈴夾回胸前。","重複所需次數，換邊操作。"],"1286":["坐在抗力球上，單手拿啞鈴，雙腳踩穩地面。","往前移動雙腳，讓球體支撐上背，頭頸自然放鬆懸空或微靠。","將啞鈴向上伸直於胸口上方，掌心朝內。","手肘微彎，緩慢將啞鈴向外側放低。","與地面平行時停頓片刻。","胸大肌發力將啞鈴收回起始位置。","重複所需次數，然後換邊。"],"1287":["躺在下斜椅上，單手握啞鈴置於胸前。","雙腳勾緊腳架，背部貼合椅面。","伸直手臂將啞鈴垂直推向天花板。","在頂端稍作停頓，然後慢慢將啞鈴下放回胸部。","重複所需次數，然後換手。"],"1288":["坐在抗力球上，單手持啞鈴，雙腳踩實。","雙腳向前走，身體下沉至上背部靠在球上。","單手伸直將啞鈴舉於胸口上方，掌心朝內。","手肘保持微彎，慢慢將啞鈴向外側弧形打開。","稍作停頓，隨後胸肌發力將啞鈴夾回正上方。","重複所需次數，換手重複。"],"1289":["將上斜椅調整至 45 度角。","坐在椅上，背靠椅背，雙腳踩實。","單手正握啞鈴置於肩上。","將啞鈴向上推離身體，手臂完全伸直。","在頂部稍作停頓，然後慢慢將啞鈴降回肩膀。","重複所需次數，換手重複。"],"1290":["坐在抗力球上，雙腳踩平地面，膝蓋彎曲成 90 度。","單手握啞鈴置於肩膀高度，手肘彎曲，掌心朝前。","在抗力球上收緊核心維持平衡，慢慢將啞鈴向上推直。","最高點稍作停頓，然後控制速度降回肩部。","重複所需次數，換手重複。"],"1291":["坐在抗力球上，雙腳踩實，膝蓋呈 90 度。","單手持啞鈴，雙臂伸直於胸前。","保持手臂微屈伸直，將啞鈴向後腦勺方向放下（套頭動作）。","稍作停頓，然後將啞鈴拉回胸前起始位置。","重複所需次數，換手重複。"],"1292":["坐在抗力球上，雙手各持一啞鈴，掌心相對。","一腳踩在地上，另一條腿向前平舉伸直以挑戰平衡。","微向前傾，手肘微彎，慢慢將雙臂向兩側打開感受胸肌拉伸。","底部稍作停頓，胸肌發力將啞鈴收回身前。","重複所需次數，換腿重複。"],"1293":["坐在抗力球上，雙手持啞鈴置於大腿，雙腳踩地。","雙腳緩步向前，球滾至下背處支撐，膝蓋呈 90 度。","將啞鈴提至肩部，掌心朝前。","向上推舉啞鈴至手臂完全伸展。","最高點停頓片刻，慢慢降回肩部。","重複所需次數。"],"1294":["坐在抗力球上，雙手持啞鈴置於大腿。","雙腳向前滑，使球滾動至頭頸與上背部平穩支撐。","雙手合抱或各持啞鈴伸展於胸前，手肘微彎。","將啞鈴控制著下放到後腦勺方向。","稍作停頓，將啞鈴拉回胸前。","同時夾緊臀肌抬高髖部成橋式，啟動核心。","放低臀部回到起始高度。","重複所需次數。"],"1295":["坐在抗力球上，雙手合握啞鈴伸展於胸前。","保持雙臂伸直微彎，將啞鈴向頭後下方放低。","停頓片刻，隨後拉回胸前起始位置。","重複所需次數。"],"1296":["從伏地挺身姿勢開始，雙手撐地，雙腳小腿置於抗力球上。","收緊核心，抬高臀部將球拉向雙手，使身體成倒 V 形（折刀派克式）。","手肘彎曲，將頭部垂直降向地面（派克伏地挺身）。","雙手推地伸直手臂回到倒 V 姿勢。","重複所需次數。"],"1297":["雙腳分開與肩同寬站立，膝蓋微彎。","雙臂在身前水平伸展，掌心相對。","保持雙臂伸直，用力向內夾緊收縮胸大肌（等長收縮）。","維持收縮數秒，專注於胸肌發力。","釋放收縮，放鬆胸部肌群。","重複所需次數。"],"1298":["平躺在地板上，雙腿彎曲，雙腳踩穩。","單手持壺鈴置於胸前，壺底朝上或靠在前臂外側，垂直推向天花板。","手肘微屈慢慢將壺鈴降回胸側，上手臂貼近軀幹。","在胸部正上方稍作停頓，隨後伸直手肘推回起始位置。","重複所需次數，換手重複。"],"1299":["調整坐姿推胸機（機械式胸推機）的座椅與把手至合適位置。","坐在機台上，背靠椅墊，雙腳平踩地面。","正握抓住把手，雙手間距略寬於肩寬。","向前推動把手，直到雙臂完全伸展（手肘不鎖死）。","停頓片刻，隨後控制手肘彎曲，將把手放回胸前。","重複所需次數。"],"1300":["調整機台座椅高度與椅背至舒適位置。","背靠椅墊，雙腳踩穩。","雙手正握把手，間距略寬於肩寬。","向前推動把手，直到雙臂完全伸展。","慢慢將把手收回胸前，手肘保持微彎張力。","在底部停頓片刻，再次向前推起。","重複所需次數。"],"1301":["調整座椅高度，坐上坐姿胸推機，背部緊貼椅墊。","正握把手，手肘呈 90 度。","吐氣將把手向前推直，完全伸展雙臂。","頂端停留片刻，吸氣並緩慢回到起始位置。","重複所需次數。"],"1302":["雙腳分開與肩同寬站立，雙手在胸前持藥球。","雙臂向前爆發力伸展，用力將藥球向前推擲出（胸前傳球）。","釋放藥球時重心由後腳轉換至前腳。","接住彈回或夥伴回傳的藥球，立即進行下一次重複。","持續進行至所需次數。"],"1303":["採三點支撐伏地挺身姿勢：一手按在藥球上，另一手撐在地面。","雙腿後伸，身體呈一直線。","胸部降向地面，維持背部平直。","推地將身體推起，手臂伸直。","重複所需次數後換手操作。"],"1304":["雙腳分開與肩同寬站立，雙手將藥球持於胸前。","雙臂向前伸展，將藥球推離胸口。","稍作停頓，然後慢慢將藥球收回胸前。","重複所需次數。"],"1305":["雙腳分開與肩同寬站立，雙手持藥球於胸前。","雙臂向前伸展，將藥球推離胸口。","稍作停頓，慢慢將球收回胸前。","重複所需次數。"],"1306":["從高棒式姿勢開始，雙手略寬於肩寬。","手肘彎曲，胸部貼向地面，身體保持成一直線。","胸大肌發力爆發性推離地面，使雙手稍微騰空。","雙手輕巧著地回到起始位置。","重複所需次數。"],"1307":["將 BOSU 半圓平衡球平放地面，平坦面朝上。","雙手握住 BOSU 球外緣，擺出伏地挺身姿勢。","彎曲手肘，啟動核心，將身體向球體沉降。","手臂推直，將身體推回起始位置。","重複所需次數。"],"1308":["將史密斯機內的重訓椅調整至水平位置。","躺在椅上，雙腳踩實地面。","寬握抓住史密斯槓，握距略寬於肩。","旋轉解鎖槓鈴，慢慢降至胸前，手肘向兩側自然張開。","槓鈴輕觸胸口時停頓片刻。","發力推回起始位置，雙臂伸直。","重複所需次數。"],"1309":["將史密斯機下的重訓椅調至下斜角度。","躺在下斜椅上，雙腳扣緊固定架。","寬握抓住槓鈴，握距略寬於肩。","解鎖槓鈴並將其緩慢降向胸下緣。","輕觸胸部時停頓片刻。","推回起始位置，雙臂伸展。","重複所需次數。"],"1310":["從高棒式開始，雙手略寬於肩，雙腳併攏。","手肘微收將胸部降向地面。","快到地面時爆發力推起，雙手短暫離地。","推起瞬間將雙手向外張開成寬距落地，順勢下沉進行寬距伏地挺身。","寬距推起後再次跳回窄距。","持續在寬距與窄距間切換，完成指定次數。"],"1311":["從高棒式姿勢開始，雙手間距明顯寬於肩寬。","身體從頭到腳保持一直線。","手肘彎曲，將胸口沉向地面。","掌心發力推地伸直手臂，回到起始位置。","重複所需次數。"],"1312":["雙腳與肩同寬站立，雙手持藥球於胸前。","右腳向前跨一步，同時向前推擲藥球，雙臂完全伸展。","順勢鬆手讓球向前滾動。","快速向前奔跑，在球停下前將球拾起或接住。","收回胸前，換左腳跨步重複。","雙腿交替重複至指定次數。"],"1313":["調整機械坐姿划船機的座椅，面對機台坐好。","正握抓住把手，背部打直。","將把手拉向軀幹，兩側肩胛骨向內夾緊。","在動作頂峰稍作停頓，然後控制速度伸直手臂放回。","重複所需次數。"],"1314":["將抗力球放地上，腹部與髖部趴在球面上，雙腳頂住牆面維持穩定。","雙手抱在後腦勺或交叉在胸前。","收緊核心，背部發力慢慢將上半身抬離球體，直到身體從頭到腳跟成一直線（羅馬椅挺身動作）。","最高點停頓片刻，緩緩回到起始位置。","重複所需次數。"],"1315":["採舒適的休息姿勢，例如跪姿並讓上半身往前趴。","雙臂輕鬆擺放。","讓背部自然拱起並放鬆。","慢慢吸氣，把氣息帶到下背。","維持 30 到 60 秒。"],"1316":["平躺在平凳上，雙腳踩地。","握距與肩同寬抓住槓鈴，雙臂垂直伸展於胸前。","手肘微彎，慢慢將槓鈴放向頭頂後方（仰臥套頭）。","稍作停頓，然後將槓鈴拉回胸前起始位置。","重複所需次數。"],"1317":["將重訓椅調整為 45 度上斜。","胸部貼靠在椅背上，面對椅子坐或趴。","反握抓住槓鈴（掌心朝外/朝下），間距略寬於肩。","保持背部挺直，核心收緊。","將槓鈴拉向上腹部，肩胛骨向後夾緊。","在最高收縮點稍作停頓。","慢慢將槓鈴放回起始位置。","重複所需次數。"],"1318":["將重訓椅調整為 45 度上斜，滑輪把手連接在低位。","坐在椅上面向滑輪機，雙腳踩實，膝蓋微彎。","正握抓住滑輪把手，雙臂完全向前伸展。","從臀部輕微前傾，背部維持平直。","肩胛後收並彎曲手肘，將把手拉向胸口。","頂端擠壓背部肌群，隨後緩緩伸展手臂回到原位。","重複所需次數。"],"1319":["將把手接在腰部高度的滑輪繩索上。","面向機台站立，雙腳與肩同寬。","正握抓住把手，掌心朝下。","後退一步使纜繩緊繃，背部打直、膝蓋微彎。","將把手拉向身體，拉動時順勢旋轉手腕使掌心朝上。","動作末端將肩胛骨向內夾緊。","緩慢放回把手至起始位置。","重複所需次數。"],"1320":["坐在坐姿划船機上，雙腳踩在腳踏板上，膝蓋微屈。","握住滑輪手把，掌心相對（對握）。","身體微向後傾，背部打直，核心收緊。","將纜繩手把拉向胸腹部，肩胛骨用力夾緊。","頂端稍作停頓，然後控制張力慢慢放回起始位置。","重複所需次數。"],"1321":["坐在面對滑輪機的高位座椅上。","正握或對握抓住滑輪把手。","背部挺直微後傾，膝蓋微彎。","後收肩胛骨、擠壓背肌，將纜繩拉向軀幹。","在完全收縮位置停留片刻。","緩緩釋放阻力，手臂伸展回起始位置。","重複所需次數。"],"1322":["將重訓椅調至 45 度斜角，連接低滑輪與繩索把手。","面對滑輪機坐在斜椅上，胸靠椅背。","抓住繩索兩端，身體前傾，背部打直。","雙臂完全伸展後，將繩索拉向胸部上方，手肘貼近軀幹。","動作結束時用力夾緊肩胛骨。","控制速度緩慢放回。","重複所需次數。"],"1323":["坐在划船機上，雙腳踩實踏板，雙膝微彎。","抓住把手，掌心相對。","背部挺直，身體微前傾，手肘微屈。","將纜繩拉向身體，後收夾緊肩胛骨。","頂點停頓片刻，隨後緩慢放回。","重複所需次數。"],"1324":["將直桿接在胸部高度的滑輪機上。","面對滑輪機站立，雙腳分開與肩同寬。","正握直桿，雙手間距略寬於肩寬。","背部挺直，核心收緊。","將直桿水平拉向上胸部，肩胛骨向內用力夾緊。","頂端停頓片刻。","慢慢將直桿放回起始位置。","重複所需次數。"],"1325":["調整滑輪下拉機，使橫桿高度位於頭頂上方。","坐在坐墊上，以較寬的正握握住下拉長桿。","身體微向後傾，挺胸並保持背部平直。","將橫桿往下拉至上胸部鎖骨位置，肩胛骨向後向下收緊。","底部停頓片刻，然後有控制地讓橫桿升回原位。","重複所需次數。"],"1326":["雙手反握（掌心朝向自己）抓住單槓，握距約與肩同寬。","啟動核心，挺胸將身體向上拉起。","持續向上拉，直到下巴超過單槓高度。","在頂部稍作停頓，然後控制身體緩慢下降回懸掛姿勢。","重複所需次數。"],"1327":["雙手反握抓住單槓，雙手間距與肩同寬。","雙臂完全伸直懸掛，雙腳離地。","收縮背部肌群與二頭肌，向上拉起身體，手肘貼近身體兩側。","拉至下巴超過單槓。","頂端停頓片刻，慢慢下放回原位。","重複所需次數。"],"1328":["俯臥趴在平凳上，雙手各持一個啞鈴，掌心相對。","雙臂自然下垂指向地面，手肘微彎。","啟動背部肌群，將啞鈴拉向胸部兩側，肩胛骨用力夾緊。","頂部停頓片刻，然後慢慢放低啞鈴回原位。","重複所需次數。"],"1329":["雙腳分開與肩同寬站立，雙手各握一啞鈴，正握。","屈髖前傾，保持背部平直、膝蓋微彎。","手臂自然下垂，掌心朝向身體。","收緊核心，將啞鈴拉向腹部兩側，手肘保持夾緊。","向上拉起啞鈴時順勢旋轉手腕，使掌心朝外。","動作頂點夾緊肩胛骨。","慢慢將啞鈴放回，同時手腕旋轉回原位。","重複所需次數。"],"1330":["將重訓椅調整至 45 度上斜。","將啞鈴放在重訓椅旁的地面。","面對重訓椅站立，雙腳與肩同寬。","屈髖，將左膝與左手支撐在重訓椅上。","右手正握拿起啞鈴。","背部維持平直，核心收緊。","將啞鈴向上拉向腰際胸側，手肘貼近軀幹。","頂端充分收緊背部肌群。","有控制地下放啞鈴回到起始位置。","重複所需次數後換左手操作。"],"1331":["將重訓椅調整至 45 度斜角。","胸靠椅背趴在斜椅上，雙腳踩實地面。","雙手各持一啞鈴，反握或對握。","身體前傾，雙臂自然下垂伸直。","將啞鈴拉向胸側，肩胛骨向內夾緊。","頂端稍作停頓，然後慢慢降回原位。","重複所需次數。"],"1332":["坐在抗力球上，雙腳踩平地面，背部挺直。","雙手各握一啞鈴，掌心朝內，手臂垂於身體兩側。","收緊核心，手肘微彎，單手慢慢向側前方舉起至肩高。","頂點稍作停頓，隨後放回。","換另一隻手臂重複動作。","雙臂交替進行至所需次數。"],"1333":["將抗力球放地上，髖部與腹部趴在球上，雙腳頂住牆面維持穩定。","雙臂在身前向前伸展，掌心朝下。","啟動核心，背肌發力將上半身抬離球體，維持頸椎與脊椎中立成一直線。","最高點稍作停頓，然後緩緩降回。","重複所需次數。"],"1334":["將抗力球放地上，髖部靠在球上趴好。","雙腳踩住牆面或其他穩固物體支撐。","雙手交疊放於後腦勺。","啟動核心與豎脊肌，將上半身挺起，直到從頭部到臀部成一直線。","動作頂峰稍作停頓，然後慢慢放低上半身回到原位。","重複所需次數。"],"1335":["抗力球放地上，髖腹貼球趴好，雙腳抵住牆壁維持穩定。","雙手抱頭或交叉在胸前。","啟動核心，慢慢將上半身抬離球體，直到身體從頭到腳跟成一直線。","頂端稍作停頓，緩慢放回。","重複所需次數。"],"1336":["趴在抗力球上，髖部貼球，雙腳踩實地面。","雙手放於後腦勺或胸前。","啟動核心，挺起上半身直到身體成一直線。","在頂點維持挺身姿勢，慢慢將軀幹向一側旋轉，保持下盤穩定。","回到中央，再向另一側旋轉。","降回上半身，重複指定次數。"],"1337":["坐在健身球上，雙腳慢慢往前走。","身體往後躺，直到整個背部貼在球上。","雙臂自然往頭頂方向垂放並放鬆。","深呼吸，讓背部慢慢打開。","維持 20 到 30 秒。"],"1338":["坐在抗力球上，雙腳踩實地面，背部打直。","雙手環抱抗力球於胸前。","啟動核心，慢慢向後仰靠，保持雙腳貼地、背部平整。","持續向後傾斜，直到感受到背部伸展。","維持姿勢數秒，然後回到起始位置。","重複所需次數。"],"1339":["坐在抗力球上，雙腳踩平，背部挺直。","單手拿啞鈴，手臂垂直向上伸向天花板。","慢慢將上半身向對側側彎，感受背闊肌的拉伸。","保持拉伸 20-30 秒，然後回正。","換邊重複。"],"1340":["跪在健身球旁，將上半身趴在球上。","身體往前滾動，讓髖部靠在球上。","雙臂與頭部自然垂下放鬆。","慢慢呼吸，讓下背完全放鬆。","維持 20 到 30 秒。"],"1341":["坐在抗力球上，雙腳踩穩，膝蓋呈 90 度。","雙腳緩緩向前走，讓球沿著背部向上滾，直到下背躺在球面上。","雙手抱頭或交叉胸前。","放鬆核心，讓上半身順著球面的弧度向後下沉，伸展下背與腹部。","停留伸展數秒，然後慢慢收回起始位置。","重複所需次數。"],"1342":["側躺在地面上，雙腿伸展，頭部枕在抗力球上。","上手臂靠在球上維持平衡。","將上手臂向上越過頭頂延伸，讓軀幹微幅旋轉。","感受體側與背闊肌的拉伸感。","保持拉伸 20-30 秒，換邊重複。"],"1343":["俯臥趴在瑜珈墊上，雙腿伸展，腳尖放在抗力球上。","雙手撐地與肩同寬，核心收緊。","保持雙腿伸直，下背與臀部發力將雙腿向上抬起。","最高點稍作停頓，然後慢慢放回球上。","重複所需次數。"],"1344":["站姿，雙腳分開與肩同寬，雙膝微彎。","反握（掌心朝上）抓住 EZ 槓，握距與肩同寬。","屈髖前傾，挺胸背打直，直到軀幹幾乎與地面平行。","將 EZ 槓拉向下胸部/肚臍方向，肩胛骨向內夾緊。","頂端停頓片刻，慢慢放回原位。","重複所需次數。"],"1345":["雙腳分開與肩同寬站立，膝蓋微彎，雙手各持一個壺鈴，掌心相對。","屈髖前傾，背部維持平直，核心收緊。","將壺鈴拉向胸腹部兩側，夾緊肩胛骨。","頂端停頓片刻，緩慢降回。","重複所需次數。"],"1346":["高跪姿於地面，雙膝與臀同寬，腳背貼地。","雙臂伸過頭頂，十指交扣。","背部打直，慢慢向右側側傾，感受左側背闊肌的拉伸。","保持伸展 20-30 秒，然後回正。","向左側傾斜重複，伸展右側背闊肌。","交替進行至所需次數。"],"1347":["調整機械下拉機的座椅高度，胸靠支撐墊，雙腳踩實。","正握抓住把手，手臂完全伸直，手肘微屈。","將把手斜向下拉過身體朝向對側髖部，動作底端收縮背闊肌。","控制速度將把手送回起始位置。","重複所需次數，然後換手。"],"1348":["調整坐姿划船機的座椅與腳踏位置。","坐在機台上，胸部靠著胸墊，雙腳踩在踏板上。","反握抓住把手，掌心朝上。","背部挺直，收緊核心。","將把手拉向胸部，肩胛骨用力夾緊。","頂端停頓片刻，然後慢慢放回。","重複所需次數。"],"1349":["調整槓桿划船機的座椅與腳踏板。","坐上機台，胸貼胸墊，雙腳踩實。","正握抓把手，間距略寬於肩。","背部維持挺直，啟動核心。","將把手拉向胸腹，夾緊肩胛骨。","頂峰停頓片刻，緩慢放回。","重複所需次數。"],"1350":["調整座椅與腳踏板至舒適位置。","坐於機台上，胸靠襯墊，雙腳踩踏板。","正握抓把手，間距與肩同寬。","背打直，核心收緊。","將把手拉向軀幹，後收肩胛骨。","頂端停留片刻。","慢慢放開把手回到原位。","重複所需次數。"],"1351":["調整座椅高度，坐穩機台，胸貼前墊，雙腳踩地。","正握握把，握距略寬於肩。","保持背部挺直，核心收緊。","將把手拉向胸口，肩胛骨向內夾緊。","頂峰停頓片刻，隨後控制速度伸展雙臂放回。","重複所需次數。"],"1352":["平躺，雙腿伸直，雙臂放於身側。","收緊臀肌與腿後肌群，慢慢將上半身向後仰抬離地面，形成反弓拱背。","頂端停留片刻，慢慢降回起始位置。","重複所需次數。"],"1353":["雙腳與肩同寬站立，雙手在胸前持藥球。","膝蓋微彎，收緊核心。","下蹲成深蹲姿勢，保持背部平直、挺胸。","雙腿蹬地爆發性起立，同時將藥球向上垂直拋過頭頂。","拋至最高點後在下落過程中穩穩接住。","順勢沉身回到深蹲，重複進行。"],"1354":["雙腳分開與肩同寬站立，雙手將藥球高舉過頭頂。","啟動核心，保持背部挺直。","膝蓋微彎，用全身力量將藥球重重砸向身前的地板（藥球砸地 Slam）。","砸球時運用肩膀、胸背與核心全力爆發。","接住彈起的藥球，重複所需次數。"],"1355":["面對牆壁站立，雙腳與肩同寬。","單臂向前伸直，掌心貼在牆上。","收緊核心，身體向前傾，手臂維持伸直、背部打平。","用手掌施力向下向內推牆，啟動背闊肌收縮。","維持等長收縮數秒，換另一隻手臂重複。"],"1356":["調整座椅高度，面對划船機台坐好。","單手抓住把手，背部打直。","將把手拉向軀幹，手肘緊貼身側。","動作頂點用力擠壓背肌。","慢慢放回把手。","重複所需次數後換手。"],"1357":["站在引體向上槓下方，用單手握住橫槓。","雙腳離地，手臂打直自然懸垂。","讓肩膀保持出力，身體維持穩定不晃動。","維持 10 到 20 秒。","小心落地，接著換手進行。"],"1358":["側躺，雙腿伸直，下側手臂伸過頭頂平貼地面。","上側腿彎曲，腳掌踩在下側腿前方的地面。","上側手臂伸過頭頂，握住穩固的支撐物（如柱子或重訓架）。","將下側伸直的腿慢慢向上抬離地面，感受體側拉伸。","保持拉伸 20-30 秒，然後慢慢放下。","換邊重複。"],"1359":["將史密斯機槓鈴調整至約臀部高度。","面對槓鈴站立，雙腳與肩同寬。","膝蓋微彎，屈髖前傾，保持背部挺直。","正握抓槓，握距略寬於肩。","將槓鈴拉向下胸處，肩胛骨向內夾緊。","頂峰停頓片刻，慢慢將槓鈴降回。","重複所需次數。"],"1360":["將史密斯槓調整至腰部高度。","面對史密斯機站立，雙腳與肩同寬。","膝微屈，屈髖前傾，背部挺直。","單手正握槓鈴，掌心朝下。","手肘貼緊身體，將槓鈴向上拉向腰間，肩胛骨向後縮。","頂端停留片刻，緩慢放回。","重複所需次數，換手操作。"],"1361":["史密斯槓設在臀部高度。","面向槓鈴站立，雙腳與肩同寬。","膝蓋微屈，屈髖前傾，背部平直。","反握抓住槓鈴，握距與肩同寬。","將槓鈴拉向下胸腹部，夾緊肩胛骨。","頂峰停頓片刻，緩緩降回。","重複所需次數。"],"1362":["俯臥趴在地上，前臂貼平地板，手肘正對肩膀下方（海豹式/獅身人面式）。","收緊核心，前臂壓地將胸口抬離地面，腳尖點地。","維持姿勢數秒，保持頸椎中立不聳肩。","慢慢將胸部降回地面。","重複所需次數。"],"1363":["坐在地上，雙腿向前伸直。","雙手置於身後地面，手指朝向身體。","收緊核心，身體慢慢向後仰，背部維持平直。","後仰至感受到脊椎與腹部伸展。","保持伸展數秒，然後慢慢回正。","重複所需次數。"],"1364":["雙腳分開與肩同寬站立，膝蓋微彎。","雙手叉腰或放於身側。","啟動骨盆肌群進行骨盆後傾，感受下背伸展。","維持姿勢數秒，然後放鬆回正。","重複所需次數。"],"1365":["站直，雙腳分開與肩同寬。","雙臂在身前向前伸直，與地面平行。","十指交扣，手掌向外翻轉。","慢慢將雙臂舉過頭頂，維持手臂伸直。","向上推舉時感受肩胛骨與背部伸展。","保持拉伸 15-30 秒，放鬆重複。"],"1366":["俯臥趴在地板上，雙腿向後伸展。","雙手撐在下胸旁的地面，手指朝前。","手掌用力推地伸直手臂，將軀幹與大腿抬離地面（眼鏡蛇式/上犬式）。","雙肩下沉後展，打開胸腔，視線朝向斜上方。","維持數個呼吸，然後慢慢放回地面。","重複所需次數。"],"1367":["正握寬握抓住單槓，雙手間距寬於肩。","雙臂伸直懸掛，身體維持直線。","啟動背闊肌，挺胸將身體拉向單槓。","持續拉至下巴超過單槓。","頂端停頓片刻，隨後有控制地降回。","重複所需次數。"],"1368":["坐在地上，雙腿向前伸直。","單腳抬離地面，以腳踝為軸心轉圈。","順時針旋轉指定圈數，隨後換逆時針旋轉。","換另一隻腳重複。"],"1369":["雙腳與肩同寬站立，將阻力帶踩在雙腳腳掌下。","雙手拉住彈力帶兩端維持適度張力。","小腿發力將腳跟盡可能抬高（提踵）。","頂峰停頓片刻，緩慢放低腳跟。","重複所需次數。"],"1370":["在身前地面放一根槓鈴或槓片。","前腳掌踩在槓鈴邊緣，腳跟懸空。","手扶穩固物體維持平衡。","盡可能將腳跟抬高，收縮小腿。","頂峰停頓片刻，慢慢降回腳跟。","重複所需次數。"],"1371":["坐在重訓椅上，槓鈴放在大腿近膝蓋處。","前腳掌踩在踏台或槓片上，腳跟懸空。","盡可能放低腳跟，拉伸小腿肌群。","隨後發力向上抬高腳跟至極限，收縮小腿。","重複所需次數。"],"1372":["雙腳分開與肩同寬站立，槓鈴扛在上背部。","前腳掌用力推地，盡可能抬高腳跟。","頂峰停頓片刻，慢慢放回腳跟。","重複所需次數。"],"1373":["雙腳分開與肩同寬站立，腳尖朝前。","雙手扶牆或穩固表面以維持平衡。","慢慢將腳跟抬離地面，重心移至前腳掌。","頂端停留片刻，緩緩將腳跟放回地面。","重複所需次數。"],"1374":["站在跳箱或踏台前，雙腳與肩同寬。","屈膝跳上跳箱，單腳輕巧著地，腳跟懸於邊緣外。","單腳站穩於箱上，另一隻腳懸空。","在此姿勢維持數秒，收縮小腿以維持平衡。","慢慢步下跳箱回到起始位置。","換另一條腿重複。"],"1375":["面對滑輪機站立，雙腳與肩同寬。","手握滑輪把手或將踝帶固定在腳踝上。","小腿發力向下蹬伸腳踝，將腳跟抬高。","頂端停留片刻，慢慢放低腳跟。","重複所需次數。"],"1376":["面對滑輪機站立，手扶機台作為支撐。","單腿懸空，用另一隻腳單腳站立平衡。","慢慢將腳跟抬高，用前腳掌墊起身體。","頂峰稍作停頓，緩慢降回腳跟。","重複所需次數，換腿重複。"],"1377":["面向牆壁站立，雙腳與臀部同寬。","雙手推牆，高度約與肩同高。","右腳向後退一步，保持右腳跟踩實地面、右膝伸直。","彎曲左膝前傾，拉伸右小腿。","保持拉伸 20-30 秒。","換腿重複伸展。"],"1378":["面對牆壁站立，雙腳分開。","雙手握毛巾或彈力帶兩端，中段套在右腳前腳掌。","左腳退後一步，右腿伸直。","身體前傾，輕拉毛巾伸展右小腿。","保持 20-30 秒後放鬆。","換另一條腿重複。"],"1379":["坐在重訓椅或椅子邊緣，啞鈴置於大腿上。","前腳掌踩在踏板或槓片邊緣，腳跟懸空。","雙手扶住啞鈴維持穩定。","盡可能抬高腳跟，將重量壓在前腳掌。","最高點停頓片刻，慢慢降回腳跟。","重複所需次數。"],"1380":["坐在重訓椅上，啞鈴放在大腿上。","單腳前腳掌踩在踏台邊緣，腳跟懸空。","雙手扶著啞鈴。","核心收緊、背打直，單腳前腳掌發力將腳跟推至最高點。","頂峰停留片刻，緩緩降回。","重複所需次數後換腳。"],"1381":["坐在重訓椅上，單手拿啞鈴置於大腿上。","單腳伸直向前懸空，膝蓋微彎。","用著地腳的前腳掌發力將腳跟抬至最高。","頂峰停頓片刻，慢慢下放。","重複所需次數，換腿操作。"],"1382":["背靠牆站立，將抗力球夾在下背部與牆壁之間。","雙腳與肩同寬，腳尖朝前。","雙手各握一啞鈴垂於體側。","收縮小腿將腳跟抬離地面，重心移至腳尖。","頂端停頓片刻，然後慢慢放回腳跟。","重複所需次數。"],"1383":["調整斜躺推腿機（雪橇機）至合適重量。","雙腳踩在平台上，前腳掌著力，腳跟懸空。","雙手握住安全把手。","小腿發力蹬起腳跟推動踏板。","頂端稍作停頓，慢慢降回腳跟感受小腿拉伸。","重複所需次數。"],"1384":["調整推腿機重量。","單腳踩在平台下緣，腳跟懸空，另一腳懸空。","手握把手維持穩定。","單腳前腳掌發力將腳跟推至最高。","頂端停頓片刻，緩緩放回。","重複所需次數後換腳。"],"1385":["調整推腿機座椅，使雙腿踩在踏板上時膝蓋微彎。","背靠椅背坐好，雙腳與肩同寬。","將前腳掌置於踏板下緣，腳跟完全懸空。","解鎖安全桿，蹬直雙腿（膝蓋不鎖死）。","伸展腳踝將踏板向前推起，然後慢慢放低腳跟感受拉伸。","頂峰收縮停頓後重複。","完成指定次數後鎖定安全閥。"],"1386":["雙腳分開與肩同寬站立，腳尖朝前。","手扶牆壁或欄杆維持平衡。","單腳離地懸空，支撐腿膝蓋微彎。","利用支撐腳的小腿肌群，盡可能將腳跟抬高。","最高點停留片刻，緩緩降回。","重複所需次數，換腳重複。"],"1387":["雙腳與臀同寬站立，雙手扶牆或支撐物。","單腳抬起，用單腳保持平衡。","慢慢將腳跟抬離地面，身體由腳尖墊起。","頂端稍作停頓，慢慢降回腳跟。","重複所需次數後換腳。"],"1388":["坐在地上，雙腿向前伸直。","將毛巾或彈力帶繞在單腳腳掌前緣，雙手握住兩端。","輕輕將毛巾向後拉，勾起腳尖伸展小腿。","保持拉伸 15-30 秒。","換另一條腿重複。","重複所需次數。"],"1389":["坐在地上，雙腿向前伸直。","彈力帶套在單腳前掌，雙手握兩端。","輕拉彈力帶加深勾腳尖幅度，拉伸小腿。","保持拉伸 20-30 秒。","放鬆張力，換另一條腿重複。"],"1390":["坐在椅子邊緣，雙腳踩地。","一條腿向前伸直，腳跟著地、腳尖勾起。","上半身微向前傾，感受小腿後側拉伸。","維持 20-30 秒。","換腿重複。"],"1391":["調整推腿機椅位，踩上滑台時膝蓋微屈。","雙腳與肩同寬踩在滑台上，腳尖朝前。","解鎖安全桿，伸直雙腿推開滑台。","頂點稍作停頓，然後彎曲膝蓋緩慢收回。","重複所需次數。"],"1392":["調整推腿機座椅。","坐穩背貼椅背，雙腳踩在滑台下緣，腳跟懸空。","膝蓋維持微彎不動，僅利用腳踝活動，蹬起滑台。","頂端停頓片刻，慢慢放回腳踝至深層拉伸處。","重複所需次數。"],"1393":["平躺在史密斯機下方的地面，背對槓鈴。","前腳掌踩在踏台或高槓片邊緣。","將史密斯槓壓在小腿腳踝正上方墊好護墊。","手扶槓鈴維持穩定。","屈伸腳踝將重量向上推頂。","頂峰停頓片刻，慢慢降回腳跟。","重複所需次數。"],"1394":["將史密斯槓調整至約胸部或肩部高度。","面對槓鈴站立，雙腳與臀同寬。","前腳掌踩在踏台邊緣，腳跟懸空。","雙手扶住槓鈴作為支撐。","盡可能抬高腳跟踮起腳尖。","頂端停留片刻，緩慢放回。","重複所需次數。"],"1395":["坐在機械提踵機上，雙腳踩踏板。","單腳踩踏板，另一腳放鬆。","用小腿肌群盡可能將腳跟抬高。","頂端停留片刻，慢慢放低。","重複所需次數後換腳。"],"1396":["將史密斯槓調至適合站立扛槓的高度。","肩膀鑽入槓下扛在斜方肌上，雙腳與肩同寬。","前腳掌踩在槓片或踏台上，腳跟懸空。","正握抓槓穩定。","核心收緊背打直，小腿發力將腳跟推至最高點。","頂峰停頓片刻，慢慢降回腳跟。","重複所需次數。"],"1397":["雙腳分開與肩同寬站立，腳尖朝前。","盡可能將腳跟抬離地面，僅靠腳尖站立。","在頂點維持片刻，慢慢放回地面。","重複所需次數。"],"1398":["面對牆壁約一步距離站立。","雙手扶在與肩同高的牆面上。","一腳向後退一大步，後腳跟完全踩平在地面上。","前膝微屈身體前傾，後腿保持完全打直。","感受後腿小腿肌肉的拉伸。","保持拉伸 20-30 秒。","換另一側重複。"],"1399":["坐在重訓椅或椅子邊緣，雙手抓住椅緣，手指朝前。","臀部往前移開椅面，雙手支撐全身重量。","彎曲手肘降下身體，直到上手臂與地面平行（椅子撐體）。","手臂推直，將身體推回起始位置。","重複所需次數。"],"1400":["雙腳與肩同寬站立。","挺胸往下深蹲。","站起來並將右腿往側邊踢出。","把腳放回地面，接著做下一次深蹲。","每次動作交替換邊。"],"1401":["雙手正握抓單槓懸掛，雙臂伸直。","啟動核心，挺胸將身體拉向單槓。","上升時身體微後傾，手肘向身體兩側收攏。","拉至胸口接觸單槓且手肘充分彎曲。","最高點停頓片刻，緩慢降回。","重複所需次數。"],"1402":["坐在兩個支撐物中間或地板上，雙手放在髖部兩側。","雙手往下推，把髖部與雙腿撐離地面。","雙腿在身體前方伸直。","肩膀往下壓穩，核心收緊。","在動作標準的前提下盡量維持，接著慢慢放下。"],"1403":["站姿或坐姿挺直，雙肩放鬆。","頭慢慢倒向一側，耳朵貼近肩膀。","保持拉伸 15-30 秒。","換另一側重複。","每側進行 2-4 組。"],"1404":["站直或坐直，雙手在胸前十指交扣。","雙臂往前推，同時將上背拱起。","頭部自然輕輕垂下。","慢慢吸氣，感受背部擴張。","維持 20 到 30 秒。"],"1405":["站直，雙腳分開與肩同寬。","雙臂向前水平伸直。","雙臂在胸前交叉，右臂在左臂上方。","十指交扣，手掌向外翻轉。","慢慢將手臂向前上方抬高推離身體，感受背部與胸部拉伸。","維持 15-30 秒，然後放鬆。","換手交叉重複。"],"1406":["仰臥，雙腿伸直。","抬起一腿，雙手抱住大腿後側或小腿。","膝蓋輕輕伸直，同時將腿往身體方向拉近。","另一腿平貼地面，背部保持放鬆。","維持 20 到 30 秒，接著換腳。"],"1407":["面對牆壁站立，雙腳與臀同寬。","雙手扶牆，約與肩同高。","單腳退後一步，腳跟踩實地面，後腿打直。","前膝微彎身體前傾，感受後小腿拉伸。","保持 20-30 秒。","換腿重複。"],"1408":["仰臥平躺，雙膝彎曲，雙腳踩實地面。","將彈力帶套在膝蓋上方。","啟動臀肌與核心。","踩穩腳跟將臀部推離地面（臀橋），頂峰夾緊臀部。","頂部停頓片刻，慢慢將臀部放回地面。","重複所需次數。"],"1409":["平躺在地上，雙膝彎曲，雙腳踩實。","將槓鈴置於髖部上方，雙手抓穩槓鈴。","臀部發力將臀部推離地面，直到膝蓋、髖、肩膀成一直線。","頂端停頓片刻，強力擠壓臀大肌。","慢慢降回臀部。","重複所需次數。"],"1410":["雙腳分開與肩同寬站立，槓鈴扛在上背部。","右腳向側邊跨出一大步，左腳原處踩實。","彎曲右膝下蹲成側弓箭步，左腿保持完全伸直。","右腳發力推蹬回起始位置。","換左腳向左跨出重複。"],"1411":["坐在重訓椅上，雙腳踩實，前臂貼在大腿上，掌心朝下。","正握抓住槓鈴，握距與肩同寬。","僅彎曲手腕，將槓鈴朝向地面放低。","在底部稍作停頓，隨後向上屈腕抬起槓鈴。","重複所需次數。"],"1412":["坐在重訓椅上，前臂貼平大腿，手腕懸於膝蓋外，反握抓槓（掌心朝上）。","保持前臂固定不動，吐氣將手腕向上彎起至極限。","在頂點收縮處停留片刻，吸氣慢慢放回。","重複所需次數。"],"1413":["面對滑輪機站立，雙腳與肩同寬。","反手或正手握住把手。","手肘緊貼身側固定，前臂發力向上彎舉至胸肩前。","頂端停留片刻，緩慢放回。","重複所需次數。"],"1414":["坐在牧師椅上，胸貼斜墊，手臂延伸在斜墊上，反握單手持啞鈴。","慢慢下放啞鈴直到手臂完全伸展。","二頭肌發力將啞鈴彎舉向肩膀，上手臂維持貼在斜墊上。","最高點收縮擠壓二頭肌，慢慢降回。","重複所需次數，換手操作。"],"1415":["坐在重訓椅上，單手反握持啞鈴，掌心朝上。","前臂平放在大腿上，手腕懸在膝蓋邊緣。","前臂不動，盡可能向上屈腕抬起啞鈴。","頂端停頓片刻，慢慢放回。","重複所需次數後換手。"],"1416":["趴在抗力球上，髖部貼球，雙腿向後伸展。","雙手撐在身前地面維持平衡。","啟動臀肌與核心穩定身軀。","單腿慢慢向上抬起至與地面平行。","將抬起的腿向外側外展打開，維持骨盆穩定不翻轉。","動作末端停頓片刻，慢慢收回。","換另一條腿重複。","雙腿交替進行至指定次數。"],"1417":["仰臥平躺，雙腿伸展，腳跟踩在抗力球上。","雙手放身側貼地維持穩定。","臀部收緊向上推起成橋式，身體從肩到腳跟成一直線。","右膝彎曲拉向胸前，左腿維持在球上支撐。","將右腿向對角線斜向踢出，伸展並感受腿後肌發力。","控制穩定慢慢將右腿收回。","換左腿重複，交替進行至指定次數。"],"1418":["雙腳分開與肩同寬站立。","彎曲膝蓋下沉成深蹲。","下蹲時將雙膝抱向胸口，雙手環抱膝蓋。","維持姿勢片刻，慢慢站起回到原位。","重複所需次數。"],"1419":["平躺，雙臂向兩側水平展開貼地。","雙腿併攏伸直垂直抬向天花板。","慢慢將雙腿向一側擺動下放，盡量讓雙腳貼近地面。","保持伸展數秒，然後將雙腿帶回正中央。","換另一側下放伸展。","交替進行至所需次數。"],"1420":["膝蓋跪在地上，雙腳與臀同寬。","槓鈴扛在上背部。","收緊核心與臀肌，爆發力向上起跳，展髖伸膝使雙腳騰空轉為深蹲落地姿態。","起跳時充分展髖、展膝與展踝。","輕巧落地，屈膝緩衝衝擊。","立即銜接下一次重複。"],"1421":["從伏地挺身預備姿勢（高棒式）開始，雙手在肩膀正下方。","手肘微收彎曲降下身體。","手肘降至 90 度時，將前臂依序平放於地面轉為肘棒式。","停頓片刻，依序用手掌推地撐起回高棒式。","重複所需次數。"],"1422":["仰臥，雙膝彎曲，雙腳平放地面。","手臂放身側，掌心朝下。","啟動臀肌與核心。","骨盆後傾發力將臀部推離地面（臀橋）。","在橋式頂端維持數秒。","慢慢將臀部放回地面。","重複所需次數。"],"1423":["趴在平凳上，髖部置於長凳邊緣，雙腿懸空於外。","雙手抓緊凳緣固定身體。","保持雙腿伸直，臀部發力將雙腿向上抬向天花板（反向超人式）。","最高點用力夾緊臀部。","慢慢降回雙腿。","重複所需次數。"],"1424":["坐在地上，雙腿在身前伸直。","彎曲右膝，將右腳踝跨放在左大腿上（翹二郎腿/4字形）。","右手撐在身後地面支撐。","左手輕輕向下按壓右膝以加深臀部拉伸。","保持拉伸 30 秒至 1 分鐘。","換邊重複。"],"1425":["調整推腿機至 45 度角。","坐在推腿機上，背貼靠墊，雙腳踩在踏板上。","單腳踩在踏板中央，伸直腿將滑台推開。","慢慢彎曲膝蓋將滑台收回。","換另一條腿重複。","雙腿交替進行至所需次數。"],"1426":["坐在史密斯機前的重訓椅上，雙腳踩實。","反握抓住槓鈴，雙手與肩同寬。","前臂平放在大腿上，手腕懸空。","手腕向上彎起，將槓鈴拉向前臂。","頂端停留片刻，慢慢放回。","重複所需次數。"],"1427":["側躺在地面上，雙腿伸直疊放。","下側手臂彎曲枕在頭下。","收緊核心，保持骨盆不向後翻轉，盡可能抬高上側腿（側臥側抬腿）。","頂端稍作停頓，慢慢降回。","重複所需次數後換邊。"],"1428":["雙臂向前水平伸直。","雙手握拳。","以手腕為軸心轉圈旋轉，手臂維持不動。","持續進行指定圈數。"],"1429":["正手抓住單槓，握距比肩寬，身體完全懸掛。","啟動核心，將肩胛骨向下拉。","背肌發力將身體向上拉起，直到下巴超過單槓。","有控制地下放身體回到起始位置。","重複所需次數。"],"1430":["將雙槓調整至舒適握持高度。","雙手撐在雙槓上，雙手間距略寬於肩。","雙手推起撐住全身重量，手肘微屈不鎖死。","膝蓋彎曲，雙腳腳踝在身後交叉。","手肘彎曲下沉身體，軀幹微前傾、胸部挺起。","下沉直到肩膀略低於手肘或感到胸部拉伸。","手掌用力推槓伸直手肘，將身體推回起始位置（雙槓撐體）。","重複所需次數。"],"1431":["將輔助引體向上機調整至所需配重。","踩上輔助踏板，正握抓住上方把手，握距略寬於肩。","挺胸收腹，微屈膝蓋。","彎曲手肘將身體向上拉起。","拉至下巴超過把手高度。","頂端稍作停頓，慢慢降回。","重複所需次數。"],"1432":["調整輔助引體向上機的輔助重量。","面向機台站立，雙腳與肩同寬。","正握抓住把手，握距略寬於肩。","啟動背闊肌與二頭肌，向上拉起自己。","頂端停頓片刻，夾緊背肌。","緩緩降回起始位置。","重複所需次數。"],"1433":["將史密斯槓調整至肩部高度。","面對槓鈴站立，雙腳與肩同寬。","正握抓住槓鈴，握距略寬於肩。","將槓鈴架在鎖骨與前三角肌上（前蹲舉架槓點），手肘向上抬高。","挺胸、背打直、核心緊繃。","彎曲髖膝向下深蹲，如坐入椅子。","下蹲至大腿與地面平行或略低。","停頓片刻，踩穩腳跟蹬起回起始位置。","重複所需次數。"],"1434":["將史密斯槓設定在適合上背扛槓的高度。","雙腳分開與肩同寬，腳尖微外展。","鑽入槓下將槓鈴穩穩置於斜方肌上（高背槓位置）。","雙手握槓略寬於肩。","蹬起雙腿旋轉解鎖槓鈴。","深吸氣並收緊核心。","臀部後推屈膝開始深蹲。","下沉直到大腿平行地面或略低。","全程維持挺胸、背部平整。","腳跟發力站起，完全展髖展膝。","重複所需次數。"],"1435":["雙腳分開與肩同寬站立，槓鈴扛在上背部。","保持挺胸收腹，屈膝屈髖向後下蹲。","蹲至大腿與地面平行或略低。","底部稍作停頓，踩穩腳跟推回起始位置。","重複所需次數。"],"1436":["站姿，雙腳分開與肩同寬，腳尖微朝外。","將槓鈴扛在斜方肌上背處。","挺胸收緊核心，臀部向後坐開始深蹲。","下蹲至大腿平行地面或個人舒適極限。","腳跟推地站起，完全展開髖部與膝蓋。","重複所需次數。"],"1437":["坐在椅子或重訓椅上，背部挺直，雙腳踩實。","單手反握持啞鈴，前臂平放在大腿上，手腕懸空。","讓啞鈴緩緩向下滾動至指尖，隨後指尖收攏將啞鈴捲回掌心。","重複所需次數後換手。"],"1438":["坐在重訓椅上，背部挺直，雙腳平放。","雙手各握一壺鈴於肩膀高度，掌心朝前。","手臂完全向上推展，將壺鈴推過頭頂。","頂峰稍作停頓，慢慢將壺鈴收回肩部。","重複所需次數。"],"1439":["調整座椅高度，坐穩機台，背靠墊子。","正握抓住握把或橫桿，手臂伸直。","保持背部打直，雙肩盡可能向上聳起靠近耳朵。","在最高點維持等長收縮片刻，隨後慢慢放回肩膀。","重複所需次數。"],"1440":["進入前臂棒式或高棒式，身體保持一直線。","收緊腹部並夾緊臀肌。","單臂往前抬起，注意不要讓髖部跟著旋轉。","穩定控制放回地面，接著抬起另一隻手。","頸部保持自然中立，雙臂交替完成預定的次數。"],"1441":["坐在重訓椅上，單手正握持啞鈴，掌心朝下。","前臂平放在長凳上，手腕懸空。","手腕向上屈起，將啞鈴向上抬。","頂端停頓片刻，慢慢降回。","重複所需次數後換手。"],"1442":["握住雙槓，雙臂伸直將身體往上撐起。","身體微微前傾，肩膀往下壓穩。","保持身體不動，維持這個姿勢。","手肘靠近身體兩側。","維持 15 到 30 秒，接著下來。"],"1443":["仰臥，雙手各拿一個啞鈴，掌心向下。","雙臂往身體兩側平舉，高度約與髖部齊平。","雙臂保持伸直，全身收緊。","維持這個姿勢，不要讓啞鈴往下掉。","維持 10 到 20 秒，接著小心放下。"],"1444":["躺在長凳上，雙手在胸口上方合握一個啞鈴。","手肘微彎，將啞鈴往頭後方降下。","在感受到胸部與背闊肌拉伸的位置停住。","核心收緊，維持這個姿勢。","維持 15 到 30 秒，接著把啞鈴拉回胸口上方。"],"1445":["站姿，雙手在大腿前方拿著啞鈴。","髖部往後推，將啞鈴順著雙腿往下放。","當大腿後側感受到明顯拉伸時停住。","背部保持平直，維持這個姿勢。","維持 15 到 30 秒，接著站起來。"],"1446":["把槓鈴放在雙手手肘彎曲處。","往下深蹲，直到大腿約與地面平行。","保持挺胸，核心收緊。","穩定維持在底端姿勢。","維持 10 到 20 秒，接著站起來。"],"1447":["調整好器材，單腳前腳掌踩在踏板上，腳跟懸空。","膝蓋伸直並站挺。","讓腳跟往下沉，直到小腿感受到拉伸。","維持 20 到 30 秒，保持平穩呼吸，接著慢慢放鬆。","換腳重複動作。"],"1448":["躺在長凳上，雙手拿較輕的槓鈴舉在胸口上方，雙臂接近伸直。","將槓鈴往頭後方降下，直到背闊肌感受到深度拉伸。","核心收緊，肋骨下壓，手肘保持微彎。","維持這個姿勢 15 到 30 秒，不要讓槓鈴偏移。","穩定控制將槓鈴移回胸口上方，再安全放好。"],"1449":["將長凳設定在約 30 度，躺下後雙手各拿一個啞鈴舉在胸口上方。","手肘微彎，雙臂往兩側大幅張開，直到啞鈴與胸口同高。","肩胛骨保持往後夾並往下壓。","維持在拉伸位置 15 到 30 秒，不要讓手臂往下塌。","將啞鈴收回胸口上方合攏，再小心放下。"],"1450":["平躺在長凳上，雙手各拿一個啞鈴舉在胸口上方。","手肘微彎，雙臂往兩側大幅張開，直到啞鈴與胸口同高。","肩胛骨往後夾緊，雙腳踩穩地面。","維持這個姿勢 15 到 30 秒，不要讓啞鈴往下掉。","將啞鈴收回胸口上方合攏，再小心放下。"],"1451":["調整座椅高度，使雙腳踩平地面且膝蓋呈 90 度。","掌心朝下握住機械撐體握把，手臂完全伸直。","手肘彎曲下沉身體，直到上手臂與地面平行。","停頓片刻，手臂推直將自己推回頂端。","重複所需次數。"],"1452":["坐在腹肌訓練機上，背貼靠墊，雙腳踩穩。","雙手抓住把手維持穩定。","收緊腹肌緩緩後仰，讓靠墊隨身體微傾。","上半身約 45 度時，收縮腹肌向前捲腹，胸口朝膝蓋靠攏。","頂端停頓片刻，慢慢放回起始位置。","重複所需次數。"],"1453":["坐在器材上，調好靠墊，依器材設計擺好手臂或雙手。","坐挺，髖部朝向正前方。","平順穩定地將軀幹轉向其中一側。","短暫停頓，接著回到中間，注意不要讓配重片撞擊。","換邊重複，持續左右交替。"],"1454":["調整座椅，讓握把起點接近肩膀高度，背部貼靠背墊坐好。","握住握把，核心收緊。","將握把往上推過頭頂，直到雙臂接近伸直。","在頂端短暫停頓，注意不要聳肩。","慢慢降回肩膀高度，並重複動作。"],"1455":["調整座椅，讓握把對齊胸口中間。","往後坐好，肩胛骨貼緊背墊，雙腳平踩地面。","將握把往前推，直到雙臂接近伸直。","短暫停頓，接著慢慢收回，直到胸口感受到拉伸。","全程保持手腕打直，背部貼緊背墊。"],"1456":["雙腳分開與肩同寬站立，正握抓槓，握距略窄於肩寬。","將槓鈴提至胸肩高度，手肘微靠身體。","將槓鈴垂直推過頭頂，雙臂完全伸展。","將槓鈴降回肩部高度。","重複所需次數。"],"1457":["雙腳分開與肩同寬站立，正握抓槓，握距略寬於肩。","將槓鈴置於肩膀前側，手肘略在槓鈴前方。","將槓鈴推過頭頂，手臂完全伸展。","降回肩部高度，重複所需次數。"],"1458":["坐在重訓椅上，雙腳踩實，背部挺直。","反握抓住 EZ 槓，雙手間距與肩同寬。","上手臂貼在大腿內側或自然下垂。","上手臂維持不動，吐氣將槓鈴向上彎舉至肩膀。","頂端稍作停頓，收縮擠壓二頭肌。","吸氣並緩慢將槓鈴放回起始位置。","重複所需次數。"],"1459":["雙腳與肩同寬站立，雙手各握一啞鈴，正握。","背部維持挺直，核心收緊，進行屈髖將啞鈴降向小腿，膝蓋微彎（羅馬尼亞硬舉）。","下沉至感受大腿後側拉伸，隨後踩穩腳跟、夾緊臀大肌站回起始位置。","重複所需次數。"],"1460":["雙腳分開與肩同寬站立。","右腿向前跨出一大步，下沉身體成弓箭步。","軀幹挺直，前膝對齊腳踝。","右腳蹬地順勢將左腳向前跨出，銜接左腿弓箭步。","以受控穩定的步伐交替向前行走（弓箭步走）。","重複所需次數。"],"1461":["站姿，雙腳分開與肩同寬，腳尖微朝外。","將槓鈴扛在上背部（斜方肌或三角肌後束）。","下蹲時啟動核心，挺胸背打直。","彎曲髖關節與膝關節，向後坐入深蹲。","下蹲至大腿平行地面或略低。","膝蓋與腳尖方向一致，重心維持在腳跟。","腳跟發力推起站直。","重複所需次數。"],"1462":["站立，雙腳與肩同寬，腳尖微外展。","槓鈴扛在斜方肌上。","啟動核心，保持挺胸。","屈膝屈髖，臀部向後坐深蹲。","蹲至大腿與地面平行或略低。","膝蓋對齊腳尖，重量置於腳跟。","踩穩腳跟推起回站姿。","重複所需次數。"],"1463":["調整推腿機座椅，使雙腿踩上踏板時膝蓋呈 90 度角。","背靠椅背坐好，雙腳與肩同寬踩在踏板上。","抓住座椅兩側把手維持穩定。","雙腿推蹬踏板伸直雙腿（膝蓋不完全鎖死）。","頂端停頓片刻，慢慢屈膝將踏板放回。","重複所需次數。"],"1464":["調整推腿機座椅，使膝蓋約呈 45 度。","坐穩靠緊椅背，雙腳踩在踏板上與肩同寬。","抓穩兩側把手。","伸直雙腿推離踏板，腳跟始終踩實踏板。","在完全伸展處停留片刻。","控制速度緩緩屈膝收回踏板。","重複所需次數。"],"1465":["將靠墊設定在髖部高度，雙腳腳跟勾在滾筒下方。","雙臂在胸前交叉，身體保持打直。","背部保持平直，將軀幹往下放，直到大腿後側感受到拉伸。","往上抬起直到身體呈一直線，注意不要過度後仰。","動作放慢，並在頂端夾緊臀肌。"],"1466":["仰臥平躺，雙膝彎曲，雙腳踩地。","雙手置於體側支撐。","夾緊臀肌抬高髖部成橋式，膝蓋到肩膀成一直線。","維持臀部抬高，將下半身向右側旋轉扭動，膝蓋朝向地面。","回到中央，換向左側扭轉。","交替扭轉進行至所需次數。"],"1467":["從肘棒式姿勢開始，前臂貼地，手肘正對肩下。","收緊核心，身體從頭到腳維持一直線。","核心維持收緊，進行棒式軀幹下沉再推起（肩胛骨活動）。","在底部停頓片刻，然後推回起始位置。","重複所需次數。"],"1468":["坐在地上，雙膝彎曲，雙腳踩平。","雙手撐在身後地面，手指朝向腳部，將臀部抬離地面（螃蟹走路預備式）。","單腿向前上方踢起，同時用對側手去觸碰腳尖。","回到原位，換邊重複觸碰。","交替進行至所需次數。"],"1469":["側躺，前臂放在肩膀正下方，雙膝彎曲。","讓髖部與肩膀上下對齊。","把髖部抬離地面，直到膝蓋到頭呈一直線。","核心收緊，不要讓髖部往下掉。","維持預定的時間，接著換邊。"],"1470":["側躺，前臂放在肩膀正下方，雙腿伸直。","雙腳可以上下疊放，或前後交錯來維持平衡。","抬起髖部，讓頭到腳呈一直線。","核心收緊，不要讓髖部往下掉。","維持預定的時間，接著換邊。"],"1471":["站立姿勢開始，雙腳與臀部同寬。","向前彎腰屈髖，雙手觸碰身前地面。","雙手一步步向前爬行，直到身體成高棒式（寸蟲爬）。","停頓片刻，雙腿維持打直，雙腳一步步跟進走向雙手。","雙腳走到雙手旁後，站立起身回原位。","重複所需次數。"],"1472":["雙腳分開與肩同寬站立。","屈膝後坐進入半蹲。","雙臂後擺蓄力。","爆發力向前跳躍（立定跳遠），充分展髖、展膝與展踝。","前腳掌輕巧著地緩衝，隨後立即進行下一次跳躍。","重複所需次數。"],"1473":["雙腳分開與肩同寬站立。","微屈膝蓋，雙腳發力向後跳躍。","前腳掌輕巧著地，屈膝吸收衝擊力。","重複所需次數。"],"1476":["雙腳分開與肩同寬站立。","單腿向前抬起伸直懸空。","單腿彎曲下蹲，如同單腿坐入椅子（手槍深蹲/單腿深蹲）。","挺胸背打直。","踩穩單腳腳跟推回站立位置。","換另一條腿重複。"],"1478":["從高棒式開始，雙手在肩膀正下方。","收緊核心，保持髖部水平。","雙腳往外跳開，再跳回併攏。","上半身保持穩定，不要讓髖部往上翹起。","以穩定的節奏持續動作，直到完成預定時間。"],"1479":["調整機械推胸機座椅高度與靠背。","背靠椅墊，雙腳平踩地面。","正握抓把手，間距略寬於肩。","向前推展雙臂，手肘微屈不完全鎖死。","頂端停留片刻，慢慢彎曲手肘收回把手。","重複所需次數。"],"1480":["站挺，雙臂往背後延伸。","手肘伸直，掌心向下或雙手交扣。","將雙手稍微抬離身體，直到二頭肌感受到拉伸。","保持胸口打開，頸部放鬆。","維持 20 到 30 秒，保持平穩呼吸，接著慢慢放鬆。"],"1481":["趴在墊子上，雙臂放在身體兩側。","彎曲膝蓋，雙手往後抓住腳踝。","抬起胸口，雙腳輕輕往手的方向踢，帶動大腿抬高。","視線看向前方，保持平穩呼吸。","維持 15 到 30 秒，接著慢慢放開，在墊子上休息。"],"1482":["趴在墊子上，手掌放在肩膀下方，雙腿伸直。","雙腳腳背往下貼穩地面。","雙臂部分伸直將胸口撐起，保持髖部貼地。","肩膀遠離耳朵，拉長頸部。","維持 15 到 30 秒，接著慢慢放下。"],"1483":["坐在地板上，挺直身體並將雙腿伸直。","將一腳放到對側大腿上，再把另一腳疊到另一側大腿上。","依髖部的活動度進行即可，絕對不要硬壓膝蓋。","雙手輕放在膝蓋上，將脊椎往上延伸拉長。","保持平緩呼吸，維持 20 到 30 秒，下次練習時交換雙腿上下順序。"],"1484":["俯臥，雙臂放在身體兩側，掌心向上。","骨盆往下貼穩地面，臀肌出力收緊。","將胸口、雙臂與雙腿同時抬離地面。","視線看向斜前方，保持頸部修長。","維持 10 到 20 秒，接著慢慢放下休息。"],"1485":["仰臥，雙臂放在身體兩側。","將雙腿與髖部往上抬起並越過頭頂，需要的話可以用雙手撐住下背。","將腳趾往頭後方的地板降下。","頸部保持放鬆，不要轉動頭部。","維持 15 到 30 秒，接著一節一節慢慢將脊椎滾回地面。"],"1486":["將握把放在與肩同寬的位置，握住握把呈棒式姿勢。","從頭到腳跟保持一直線。","將胸口往下放，直到落在兩個握把之間，手肘與身體約呈 45 度。","往上推回，直到雙臂伸直。","核心收緊，不要讓髖部往下掉。"],"1487":["仰臥並將雙腿抬過頭頂，雙手撐住下背。","雙手順著背部往肩胛骨方向上移。","雙腿筆直往上延伸，讓身體在肩膀上方呈一直線。","保持頸部修長穩定，不要轉動頭部。","維持 15 到 30 秒，接著慢慢放下。"],"1488":["站挺，雙手在背後十指交扣。","雙臂伸直，將肩胛骨往中間夾緊。","將雙手輕輕抬離身體，直到感受到拉伸。","保持胸口打開，避免下背過度拱起。","維持 20 到 30 秒，保持平穩呼吸，接著慢慢放鬆。"],"1489":["雙腳分開與肩同寬站立，腳尖微朝外。","可扶著穩固物體維持平衡。","屈膝後坐，慢慢下沉身體，軀幹盡量維持直立。","蹲至大腿平行地面或舒適深度。","停頓片刻，腳跟發力推回起始位置。","重複所需次數。"],"1490":["前腳掌踩在階梯邊緣，腳跟完全懸空。","扶住扶手或牆面維持平衡。","慢慢將腳跟抬至最高點，小腿充分收縮。","頂端停頓片刻，然後慢慢放低腳跟至低於踏台面（深層拉伸）。","重複所需次數。"],"1491":["仰臥，雙臂往身體兩側打開。","將單側膝蓋抱向胸口。","引導那側膝蓋跨過身體，往對側地板方向貼近。","兩邊肩膀都貼在地面上，覺得舒服的話可以把頭轉向反方向。","維持 20 到 30 秒，接著換邊。"],"1492":["站挺或坐挺，將一隻手臂舉過頭頂。","彎曲手肘，讓手落到頭後方。","用另一隻手將手肘輕輕往後、往下壓。","保持肋骨下壓，避免拱背。","維持 20 到 30 秒，接著換手。"],"1493":["仰臥，雙膝彎曲，雙腳平踩在靠近髖部的地面。","手掌放在頭部兩側，手指朝向肩膀。","雙手與雙腳往下推，先抬起髖部，再將頭部抬離地面。","在舒適範圍內盡量伸直雙臂，保持大腿平行。","維持 5 到 15 秒，接著收下巴慢慢將身體放回地面。"],"1494":["坐在地板上，雙腿向前伸。","彎曲雙膝，將兩腳腳底併攏，雙膝自然向兩側打開（蝴蝶式）。","雙手握住腳踝或雙腳。","坐直延伸脊椎。","輕輕將膝蓋向地面下壓，感受大腿內側拉伸。","維持此姿勢數個深呼吸。","慢慢抬起膝蓋放鬆雙腿。"],"1495":["平躺，雙膝彎曲，雙腳踩實地面。","雙手置於後腦勺或交叉在胸前。","腹肌發力將肩胛骨抬離地面，同時轉動軀幹向一側（旋轉捲腹）。","頂點停頓片刻，慢慢放回肩胛骨。","換向另一側重複。","交替進行至所需次數。"],"1496":["雙腳分開與肩同寬站立，雙手握緊大鐵鎚。","啟動核心，背部維持平直。","運用核心與上半身力量，將鐵鎚高舉後重重向下砸向輪胎。","揮動時轉動髖部，將全身力量傳導至鐵鎚。","重複所需次數。"],"1497":["在長凳上就位，將彈力帶固定在深蹲架頂端並綁在槓鈴上。","躺下讓眼睛位於槓鈴正下方，夾緊肩胛骨。","有控制地將槓鈴下放到中胸位置。","將槓鈴推回手臂伸直，感受彈力帶阻力的變化。","雙腳踩穩地面，手腕維持在手肘正上方。"],"1498":["將彈力帶固定在身後，雙手在胸前握住另一端。","躺在下斜長凳上，雙腳固定好。","將軀幹捲向膝蓋，維持彈力帶的張力。","在頂點稍作停留，不要拉扯脖子。","有控制地慢慢放回。"],"1499":["雙腳踩住彈力帶，雙手在後肩位置握住兩端。","繃緊核心，頭部保持朝前。","將雙手直直往上推，直到手臂伸直。","慢慢放回腦後，回到肩膀高度。","只有在肩膀處於這個位置依然活動自如時，才執行此變化式。"],"1500":["雙腳踩在彈力帶中段站好，雙手在大腿前側握住兩端。","保持挺胸，收緊核心。","以手肘帶動，將雙手沿著身體往上拉到胸口高度。","在頂點短暫停留，不要過度聳肩。","慢慢下放回起始位置。"],"1501":["單側前臂撐地進入側棒式，請搭檔在前方拉住彈力帶。","上方手握住彈力帶，保持髖部抬高。","將手往肋骨方向拉回，同時夾緊肩胛骨。","慢慢放回，期間不要讓髖部下掉。","完成次數後換邊。"],"1502":["將彈力帶固定在高處，雙手握住兩端，手肘貼近身體兩側。","站直，身體微向前傾。","將雙手往下壓，直到手臂完全伸直。","稍作停留並收緊三頭肌。","手肘固定在身體兩側，慢慢回到起始位置。"],"1503":["雙手握住彈力帶舉在身前，高度與肩同高，手臂伸直。","肋骨下收，肩膀遠離耳朵。","雙手往兩側外展，將彈力帶拉開。","在動作末端夾緊肩胛骨。","有控制地慢慢放回。"],"1504":["將彈力帶固定在頭後方，仰躺並雙手握住兩端。","起始時雙臂在胸口正上方伸直。","只彎曲手肘，將雙手朝額頭方向下放。","對抗彈力帶阻力，將手臂推回上方。","全程保持上臂固定不動。"],"1505":["依設定方式將彈力帶固定在腳底或繞過雙肩。","站直，雙腳與髖同寬。","盡可能墊高腳尖，站上腳掌前緣。","稍作停留並收緊小腿。","慢慢下放，直到腳跟完全落回地面。"],"1506":["踩住彈力帶，雙手掌心朝上窄握 EZ 槓。","手肘貼緊身體兩側，保持挺胸站直。","將槓鈴朝肩膀方向彎舉。","在頂點收緊肌肉，身體不要晃動。","慢慢下放，直到手臂完全伸直。"],"1507":["將彈力帶固定在低處，另一端套在單側腳踝上。","站直，扶著支撐物保持平衡。","將膝蓋往前上方抬起至髖部高度。","短暫停留，接著有控制地放下。","完成次數後換腿。"],"1508":["雙腳踩住彈力帶，雙手在身體兩側握住兩端。","手肘保持微彎。","將雙臂往兩側平舉至肩膀高度。","短暫停留，注意不要聳肩。","慢慢放回身體兩側。"],"1509":["在身後放一張長凳，並在槓鈴掛上鎖鏈。","將槓鈴放在上背，雙腳與肩同寬站立。","臀部往後往下坐，直到輕觸長凳。","保持挺胸，膝蓋朝腳尖方向移動。","雙腳踩地發力站起，感受鎖鏈逐漸增加的重量。"],"1510":["站直，雙手叉腰。","單腳往另一腿的斜後方跨出一步。","往下蹲，直到雙膝都彎曲約 90 度。","保持軀幹挺直，前膝穩定。","前腳踩地推回站姿，接著重複或換邊。"],"1511":["雙腳分開與肩同寬站立。","右腳向前跨一小步，重心移至右腿。","保持背部挺直，屈髖向前俯身，雙手伸向右腳。","維持拉伸 20-30 秒，感受大腿後側伸展，回到原位。","換另一側重複。"],"1512":["四足跪姿開始，雙手在肩下方，雙膝在髖部下方。","單腿向後伸展，屈膝勾腳。","慢慢將骨盆重心沉向地面，感受大腿前側（股四頭肌）拉伸。","保持 20-30 秒。","換另一條腿重複。"],"1513":["雙腳踩住彈力帶，將另一端繞過頸後搭在雙肩上。","膝蓋保持微彎，背部打直。","臀部往後推，軀幹向前傾。","感覺大腿後側被拉緊時停住。","髖部往前推，重新站直。"],"1514":["將槓鈴扛在上背，雙腳與肩同寬站立。","繃緊核心並保持挺胸。","膝蓋與髖部稍微彎曲，下蹲約全蹲的四分之一深度。","保持膝蓋朝腳尖方向對齊。","雙腳踩地往上推，回到站姿。"],"1515":["站立讓槓鈴位於足弓正上方，雙手在膝蓋外側握槓。","背部打直、挺胸，讓肩膀位於槓鈴略前方。","雙腳推地將槓鈴拉起，讓槓鈴貼近雙腿。","完全站直，髖部與膝蓋充分伸展。","沿著相同軌跡，有控制地將槓鈴放回。"],"1516":["將槓鈴放在墊塊上，雙手在膝蓋外側握槓，背部打直。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","將身體鑽入槓鈴下方，以全蹲姿勢在前肩接住槓鈴。","站直完成動作，接著有控制地放下槓鈴。"],"1517":["在槓鈴前就位，背部打直，雙手於膝蓋外側握槓。","將槓鈴拉過膝蓋，保持貼近身體。","爆發性地伸展髖部與膝蓋，同時聳肩。","讓手肘順勢往高處拉起，但不翻腕接槓。","有控制地放下槓鈴並重新就位。"],"1518":["將槓鈴放在上背，單腳往後放在下斜長凳上。","前腳往前跨出，踩穩站姿。","保持軀幹挺直，後膝朝地面下放。","前腳踩地發力站起。","完成次數後換腿。"],"1519":["將槓鈴設在上胸高度的卡榫上，鑽到槓鈴下方。","將槓鈴扛在上背站直，膝蓋微彎。","臀部往後推，保持背部平坦。","當軀幹接近與地面平行時停住。","髖部往前推回到站姿，完成後將槓鈴放回卡榫。"],"1520":["站立將槓鈴垂握在大腿中段，雙手在雙腿外側，背部打直。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","將身體鑽入槓鈴下方，以深蹲姿勢在前肩接住槓鈴。","站直完成動作，接著有控制地放下槓鈴。"],"1521":["將槓鈴維持在膝蓋正下方，背部打直，肩膀位於槓鈴上方。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","將身體鑽入槓鈴下方，以深蹲姿勢在前肩接住槓鈴。","站直完成動作，接著有控制地放下槓鈴。"],"1522":["以抓舉寬握將槓鈴維持在大腿中段，背部打直。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","鑽入槓鈴下方，雙臂伸直鎖死，以深蹲姿勢在頭頂接住槓鈴。","站直完成動作，接著有控制地放下槓鈴。"],"1523":["以寬握將槓鈴維持在膝蓋正下方，背部打直。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","鑽入槓鈴下方，雙臂伸直鎖死，以深蹲姿勢在頭頂接住槓鈴。","站直完成動作，接著有控制地放下槓鈴。"],"1524":["將槓鈴放在上背，採抓舉寬握。","微蹲後爆發往上推蹬，將槓鈴推離肩膀。","迅速下潛進入深蹲，同時將槓鈴推向頭頂。","雙臂伸直鎖死，在足弓正上方接住槓鈴。","有控制地站起，將槓鈴放回背上。"],"1525":["將槓鈴架在前肩，雙腳與髖同寬站立。","保持軀幹挺直，收緊核心。","膝蓋彎曲，身體筆直往下微蹲一小段。","全腳掌爆發往上推蹬。","站穩回到起始姿勢並重新準備。"],"1526":["以寬握將槓鈴維持在髖部高度，肩膀位於槓鈴上方。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","手肘帶動將槓鈴往高處拉，接著翻腕並直接推至頭頂手臂伸直鎖死，期間不下蹲。","站直完成動作，接著有控制地放下槓鈴。"],"1527":["將槓鈴放在上背較高位置，雙腳約與肩同寬。","繃緊核心並保持挺胸。","腳跟踩穩，身體筆直往下蹲到最深。","保持膝蓋朝腳尖方向移動。","雙腳踩地發力推回站姿。"],"1528":["將槓鈴放在墊塊上，雙手在膝蓋外側握槓，背部打直。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","拉起並以四分之一深蹲姿勢，在前肩接住槓鈴。","站直完成動作，接著有控制地放下槓鈴。"],"1529":["將槓鈴架在前肩，手肘微朝前。","保持軀幹挺直，往下微蹲一小段。","爆發往上推蹬，將槓鈴往頭頂推起。","身體微往下沉，雙臂伸直鎖死接住槓鈴。","站直，接著有控制地將槓鈴放回肩上。"],"1530":["以寬握將槓鈴維持在小腿前側，背部打直並挺胸。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","鑽入槓下，以四分之一深蹲且雙臂鎖死的姿勢在頭頂接住槓鈴。","站直完成動作，接著有控制地放下槓鈴。"],"1531":["將槓鈴放在墊塊上，採寬握並保持背部平坦。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","鑽入槓下，以四分之一深蹲且雙臂鎖死的姿勢在頭頂接住槓鈴。","站直完成動作，接著有控制地放下槓鈴。"],"1532":["站在矮踏板上，雙手握槓置於大腿前側。","膝蓋保持微彎，背部打直。","臀部往後推，讓槓鈴沿著雙腿往下滑。","在維持背部平坦的前提下，盡量往下放。","髖部往前推，重新站直。"],"1533":["採寬握讓槓鈴位於足弓正上方，背部打直並挺胸。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","鑽入槓鈴下方，以全蹲姿勢在頭頂接住槓鈴，接著站起。","站直完成動作，接著有控制地放下槓鈴。"],"1534":["將槓鈴放在上背，採抓舉寬握。","微蹲一小段後往上推蹬。","下潛進入深蹲，同時將槓鈴推向頭頂。","雙臂伸直鎖死接住槓鈴，保持挺胸。","有控制地站起，將槓鈴放回背上。"],"1535":["站立讓槓鈴位於足弓正上方，雙手採抓舉寬握。","將背部打直並挺胸。","雙腳推地將槓鈴拉起，保持貼近身體。","站直，讓髖部與膝蓋完全伸展。","沿著相同軌跡，有控制地放下槓鈴。"],"1536":["將槓鈴放在墊塊上，採寬握並保持背部平坦。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","鑽入槓鈴下方，以全蹲姿勢在頭頂接住槓鈴，接著站起。","站直完成動作，接著有控制地放下槓鈴。"],"1537":["雙手在雙腿外側握槓，背部打直，肩膀位於槓鈴上方。","繃緊核心，讓槓鈴貼近身體。","髖部與膝蓋強力伸展，同時聳肩。","雙腳前後分開踩穩，同時在前肩接住槓鈴。","收回雙腳站直完成動作，接著有控制地放下槓鈴。"],"1538":["將槓鈴架在前肩，手肘微朝前。","保持軀幹挺直，往下微蹲一小段。","爆發往上推蹬，將槓鈴推向頭頂。","雙腳前後分開踩穩，同時雙臂伸直鎖死接住槓鈴。","將雙腳收回併攏，有控制地放下槓鈴。"],"1539":["將輕槓鈴放在上背，採前後分腿站姿。","下蹲成淺弓步。","爆發往上跳起，並在空中前後換腿。","輕柔落地，換成另一側的分腿站姿。","保持軀幹挺直，持續交替進行。"],"1540":["雙手將槓鈴托在上胸位置，手肘微朝前，雙腳與肩同寬。","保持挺胸往下深蹲，直到大腿約與地面平行。","腳跟發力往上推起，順著這股衝力將槓鈴推過頭頂。","在足弓正上方將手臂推直鎖死，接著把槓鈴放回胸前。","全程繃緊核心，避免下背過度拱起。"],"1541":["雙腳與肩同寬站立，雙手正握槓鈴置於大腿前側。","臀部往後推並下蹲，讓槓鈴順著大腿滑到膝蓋位置。","腳跟踩地發力，重新站直。","站起的同時，將槓鈴貼近身體往上拉，直到手肘達到肩膀高度。","有控制地放下槓鈴，直接進入下一次深蹲。"],"1542":["站在穩固的長凳上，雙腳與髖同寬，雙手握槓置於大腿高度。","膝蓋保持接近打直，臀部往後推。","背部打直，在大腿後側允許的範圍內盡量將槓鈴朝腳尖下放。","短暫停留，接著收緊臀肌站回原位。","全程讓槓鈴貼近雙腿，並維持穩定控制。"],"1543":["雙腳與髖同寬站立，雙手在大腿前側握住槓鈴。","膝蓋保持微彎，臀部往後推。","讓槓鈴沿著雙腿下放，直到感覺大腿後側被深度拉伸。","全程保持背部平坦並挺胸。","髖部往前推，回到站姿。"],"1544":["採寬站距、腳尖微朝外，雙手在大腿前側握住槓鈴。","膝蓋接近打直，臀部往後推。","保持背部平坦，將槓鈴往雙腿之間下放。","感覺大腿後側與大腿內側受到強烈拉伸時停住。","收緊臀肌，推回站姿。"],"1545":["雙腳分開與肩同寬站立，腳尖微外展。","將槓鈴環抱在雙手手肘彎曲處（澤奇深蹲 Zercher Squat），雙手互握抓穩。","挺胸收腹，髖部後推下蹲。","膝蓋對齊腳尖方向，重心放在腳跟。","蹲至大腿平行地面或舒適深度。","踩穩腳跟蹬起，頂峰夾緊臀部。","重複所需次數。"],"1546":["背部靠牆，雙腳往前跨出約一步距離。","順著牆面往下滑，直到大腿約與地面平行。","保持膝蓋對齊腳尖，背部平貼牆面。","腳跟踩地發力，順著牆面滑回上方。","依計畫的次數重複執行。"],"1547":["將腳踝扣環連接到低位滑輪，並綁在單側腳踝上。","面向機台站立並扶好以保持平衡，訓練腿稍微往後放。","彎曲膝蓋，將腳跟朝臀肌方向捲起。","在頂點收緊肌肉，軀幹不要晃動。","慢慢放下，完成次數後換腿。"],"1548":["坐在椅子邊緣，背部挺直，雙腳踩地。","單腿向前伸直，腳跟著地。","微向前傾，感受股四頭肌與大腿拉伸。","維持姿勢 20-30 秒。","換腿重複。"],"1549":["站直，雙腳與髖同寬，雙臂自然放鬆。","雙腳同時起跳。","在空中時，將雙腳腳跟往臀肌方向踢起。","前腳掌輕柔落地，膝蓋保持微彎。","以穩定節奏直接接著下一次跳躍。"],"1550":["雙手各握一個啞鈴，背對長凳往前站約一步距離。","將單腳腳背放在身後的長凳上。","彎曲前腿，讓後膝朝地面下放。","保持前膝對齊腳尖並挺胸。","前腳跟踩地推回站姿，完成次數後換腿。"],"1551":["雙手各握一個啞鈴，背對下斜長凳站立。","將單腳腳背放在身後的長凳上。","將髖部筆直往下放，直到前側大腿約與地面平行。","保持軀幹挺直，前膝朝腳尖方向移動。","前腳踩地站起，完成次數後換腿。"],"1552":["雙腳與肩同寬站立，雙手各握一個啞鈴垂在身體兩側。","往下深蹲，直到大腿約與地面平行。","往上爆發推蹬，盡可能跳高。","前腳掌輕柔落地，順勢直接蹲入下一次深蹲。","保持挺胸，膝蓋對齊腳尖。"],"1553":["站直，雙手各握一個啞鈴，掌心朝前。","往側邊跨出一大步並將臀部往後坐，另一腿保持伸直。","下蹲進入弓步的同時，將雙手啞鈴往上彎舉。","彎曲腿踩地推回中間，同時放下啞鈴。","左右交替執行，或單邊完成所有次數後再換邊。"],"1554":["雙手各握一個啞鈴，跨出一步進入弓步姿勢。","往下蹲，直到雙膝都彎曲約 90 度。","往上爆發跳起，並在空中前後交換雙腿位置。","輕柔落地，換成另一腿在前的弓步。","保持軀幹挺直，流暢地銜接每一次動作。"],"1555":["雙腳與肩同寬站立，雙手各握一個啞鈴垂在身體兩側。","臀部往後推並彎曲膝蓋往下蹲。","下蹲到大腿與地面平行，或再深一點。","保持挺胸，腳跟踩穩地面。","雙腳踩地發力，推回站姿。"],"1556":["站在穩固的長凳上，雙手各握一個啞鈴置於大腿前側。","膝蓋接近打直，臀部往後推。","保持背部平坦，讓啞鈴沿著雙腿下放到低於長凳表面的位置。","感覺大腿後側被深度拉伸時稍作停留。","收緊臀肌，回到站姿。"],"1557":["雙手各握一個啞鈴垂在身體兩側，站直準備。","單腿往前跨出並下蹲，直到雙膝都彎曲約 90 度。","保持軀幹挺直，前膝位於腳踝正上方。","後腳推地，直接往前跨出進入另一腿的弓步。","持續交替雙腿往前走。"],"1558":["雙手各握一個啞鈴，背部靠在牆上。","雙腳往前走，確保下蹲時膝蓋會位於腳踝正上方。","順著牆面下滑，直到大腿約與地面平行。","保持背部平貼牆面。","腳跟踩地發力，順著牆面滑回上方。"],"1559":["將抗力球放地上，跪在球前。","右腳踏在抗力球上，膝蓋呈 90 度。","左腿在身後伸展打直。","身體前傾，將髖部向前推向抗力球，感受右側髖屈肌拉伸。","保持 20-30 秒，換邊重複。"],"1560":["坐在抗力球上，雙腳踩實，雙膝呈 90 度。","雙腳向前走動使球沿背部滾動，直到上背枕在球上，雙腿在身前伸直。","雙手插腰維持支撐。","收緊核心，背部維持平直向前俯身，感受大腿後側拉伸。","感到拉伸時維持 20-30 秒。","踩穩腳跟拉回身體，回到起始坐姿。","重複所需次數。"],"1561":["坐在健身球邊緣，保持軀幹挺直。","需要的話，可以扶著穩固物保持平衡。","彎曲單膝，抓住腳踝將腳跟拉向臀肌。","保持雙膝靠攏，髖部朝正前方。","停留 20 到 30 秒，接著換腿。"],"1562":["將健身球放在下背與牆面之間。","雙腳往前走約一步，站距與肩同寬。","彎曲膝蓋往下蹲，讓球順著背部滾動。","下蹲直到大腿約與地面平行。","腳跟踩地發力，推回站姿。"],"1563":["站在牆壁或支撐物旁，單手扶穩。","外側腿膝蓋保持伸直，往前擺動。","接著往身後擺動，同時收緊臀肌。","保持軀幹挺直，避免下背過度拱起。","單邊完成所有次數後，轉身換腿。"],"1564":["站直，雙腳分開與肩同寬。","一手扶住穩固物體支撐。","右膝後彎，右腳跟靠近臀部，右手抓住毛巾或腳踝。","輕輕將腳跟拉向臀部，感受右大腿前側（股四頭肌）拉伸。","保持拉伸 20-30 秒。","放開後換左側重複。"],"1565":["雙腳與髖同寬站在壺鈴上方，髖部後推俯身握住把手。","繃緊核心並保持背部平坦。","髖部往前推，將壺鈴貼近身體往上拉起。","手掌繞著把手翻轉，在肩膀位置接住壺鈴。","有控制地放回地面並重新擺好姿勢，再進行下一下。"],"1566":["單臂將壺鈴推過頭頂，手肘伸直鎖死。","雙腳與肩同寬站立，肋骨下收。","保持挺胸往下深蹲，同時讓壺鈴穩定維持在肩膀正上方。","在能穩定控制的前提下盡量蹲低。","腳跟發力推起，完成次數後換手。"],"1567":["雙腳與肩同寬站立，將壺鈴放在身前地面。","俯身用單手握住把手。","將壺鈴往後擺入胯下，接著髖部往前推把壺鈴帶起。","手掌張開，引導壺鈴順勢停在肩膀位置。","有控制地放回並重複，完成後換邊。"],"1568":["雙腳略寬於肩站立，單手握住壺鈴。","髖部後推，將壺鈴往雙腿之間後擺。","髖部快速往前頂出，讓壺鈴順勢飄到胸口高度。","手臂保持放鬆，背部打直。","讓壺鈴自然落回並再次屈髖後擺，完成次數後換手。"],"1569":["單手握住壺鈴，對側腿膝蓋微彎單腳站立。","以髖部為軸向前傾，同時將懸空腿往後伸直。","保持背部平坦，將壺鈴朝地面下放。","當軀幹約與地面平行時停住。","收緊臀肌回到站姿，完成後換腿。"],"1570":["雙腳與肩同寬站立，雙臂預備。","往下微蹲至四分之一深蹲，同時雙臂往後擺。","往上爆發跳起，將雙膝收向胸口。","落地前再次將雙腿往下伸展。","膝蓋微彎輕柔落地，重新站穩後再進行下一次跳躍。"],"1571":["坐在機台上，調整靠墊使其剛好壓在小腿下段。","單腳放在靠墊下方，另一腳踩在地面或踏板上。","將訓練腿往上伸展到接近完全打直。","在頂點收緊股四頭肌。","慢慢下放，完成次數後換腿。"],"1572":["坐在機台內，背部貼緊靠墊，雙肩抵住肩墊下方。","單腳踩在踏板外側的寬距位置，另一腿避開負重。","彎曲訓練腿膝蓋，在舒適範圍內盡量下放。","保持膝蓋朝腳尖方向移動。","推回起始位置，完成次數後換腿。"],"1573":["坐在機台內，背部貼緊靠墊，雙肩抵住肩墊下方。","單腳踩在踏板上，位置約在與肩同寬處。","彎曲膝蓋，有控制地往下放。","腳跟踩平，保持膝蓋對齊腳尖。","往上推回，完成次數後換腿。"],"1574":["坐在機台內，背部貼緊靠墊，雙肩抵住肩墊下方。","雙腳寬距踩在踏板上，腳尖微朝外。","彎曲膝蓋下放，直到大腿約與踏板平行。","保持膝蓋朝向與腳尖一致。","腳跟發力推回起始位置。"],"1575":["坐在斜板機台內，背部平貼靠墊，雙腳併攏踩在踏板上。","解開安全扣把。","彎曲膝蓋朝胸口方向下放踏板。","在下背離開靠墊之前停住。","腳跟發力將雙腿推直，但膝蓋不要完全鎖死。"],"1576":["平躺在地上，雙腿伸直。","屈起一側膝蓋抱向胸前，雙手抱住大腿或小腿。","在舒適範圍內盡可能伸直抬起的那條腿。","保持拉伸 20-30 秒。","換另一條腿重複。"],"1577":["仰躺在長凳或床邊緣。","雙手抱住單側膝蓋貼向胸口。","讓另一腿自然垂出邊緣，膝蓋放鬆。","保持下背平貼表面，慢慢呼吸。","停留 20 到 30 秒，接著換腿。"],"1578":["單腿站立，另一腳微微抬離地面。","雙臂往前伸直以幫助平衡。","彎曲膝蓋，往下淺蹲約四分之一的深度。","保持膝蓋對齊腳尖並挺胸。","站回原位，完成次數後換腿。"],"1579":["進入哈克深蹲機台，讓背部與雙肩貼緊靠墊。","單腳踩在踏板中央，另一腳移開不出力。","解開安全扣，彎曲訓練腿膝蓋往下蹲。","在可控制的範圍內盡量蹲深。","腳跟發力往上推起，完成次數後換腿。"],"1580":["雙腳與肩同寬站立，雙手放在頭後方。","手肘往後拉開並保持挺胸。","臀部往後推並彎曲膝蓋下蹲。","下蹲到大腿約與地面平行。","腳跟發力踩地，站回原位。"],"1581":["站直，雙腳與髖同寬。","單腳往後跨出並下蹲，直到雙膝都彎曲約 90 度。","保持軀幹挺直，前腳跟踩穩地面。","前腳發力推地，回到站姿。","雙腿交替進行，或單邊完成所有次數後再換邊。"],"1582":["仰臥平躺，雙腿伸展，手臂放於身側。","將毛巾或彈力帶繞在右腳前掌，雙手握住兩端。","腿伸直慢慢將右腿拉向胸部方向，腳尖勾起。","維持伸展數秒，然後慢慢放回。","換左腿重複。","雙腿交替進行至所需次數。"],"1583":["面向哈克深蹲機台的靠墊，胸口貼緊靠墊，雙腳踩在踏板上。","握住把手並解開安全扣。","彎曲膝蓋並將臀部往後推，往下深蹲。","保持胸口貼穩靠墊。","腳跟發力推回站姿。"],"1584":["雙腳與肩同寬站立。","往下深蹲，同時雙臂往後擺。","往上爆發跳起，跳躍時雙臂往頭頂高舉。","全身像火箭一樣完全伸展。","膝蓋微彎輕柔落地，站穩後再進行下一次跳躍。"],"1585":["雙腳與臀同寬站立。","右腳向前跨出一大步，左腳原處踩實。","彎曲右膝下沉，左腿向後伸直。","雙手扶在右大腿上支撐。","保持伸展 20-30 秒感受髖屈肌拉伸，然後換邊。"],"1586":["坐在機台上，背部貼緊靠墊，將腿墊調整到腳跟上方。","單腿放在腿墊下方，另一腳放在休息踏板上。","將腳跟盡量往下、往後勾。","在底部收緊大腿後側。","慢慢放回，完成次數後換腿。"],"1587":["坐在地上，雙腿大幅度向兩側打開（坐姿分腿）。","勾起腳尖，啟動股四頭肌。","雙手撐在身後地板支撐。","背部維持挺直，從髖部向前俯身前傾。","前傾至感受到大腿內側與腿後肌群拉伸。","維持深呼吸數次。","慢慢放鬆推回原位。","重複所需次數。"],"1588":["站在矮跳箱或踏板的一側。","將靠近跳箱的那隻腳踩在箱上。","橫向跳過跳箱，讓另一腳踩上箱面、原本的腳落到另一側地面。","步伐保持輕快。","以穩定節奏持續左右來回移動。"],"1589":["單腿站立，另一腳抬起。","用支撐腳輕輕起跳。","每次跳起時，將懸空腳的腳跟往臀肌方向踢。","以前腳掌輕柔落地。","完成次數後換腿。"],"1590":["俯臥在機台上，將單腿放在腳跟上方的滾墊下。","握住把手，保持髖部貼緊墊子。","將腳跟朝臀肌方向往上勾起。","在頂點收緊大腿後側。","慢慢下放，完成次數後換腿。"],"1591":["站在矮踏板前，將單腳踩在踏板上。","身體微向前傾，收緊核心。","踏板上的腿爆發往下推蹬，同時將對側膝蓋往上帶起。","用同一隻腳輕柔落回踏板。","完成次數後換腿。"],"1592":["單腿站立，膝蓋微彎。","用力推蹬，盡可能往前跨跳出去。","用另一腿落地，膝蓋微彎吸收衝擊。","落地時稍微停頓一下，站穩平衡。","重複執行，可左右交替或先練完單邊。"],"1593":["站在椅子或長凳前方，雙腳與肩同寬。","臀部往後推，將身體朝椅面下放。","臀部輕觸椅面，但不要完全放鬆坐實。","保持挺胸，膝蓋位於腳尖上方。","腳跟踩地發力，推回站姿。"],"1594":["將槓鈴設在上胸高度，讓槓鈴架在前肩上。","雙臂像殭屍一樣往前平舉伸直，讓槓鈴固定在肩窩。","轉開槓鈴出槓，踩穩站姿。","保持挺胸與軀幹挺直往下深蹲。","腳跟發力推回站姿，完成後將槓鈴掛回。"],"1595":["將槓鈴設定在肩膀高度，架在前肩上，手肘抬高。","起槓後，雙腳微幅往前踩。","往下深蹲，直到大腿約與地面平行。","保持手肘抬高，抬頭挺胸。","腳跟發力站起，完成後將槓鈴放回架上。"],"1596":["在史密斯機槓鈴下方，將長凳放在身後。","將槓鈴架在上背並起槓。","髖部往後坐並往下蹲，直到輕觸長凳。","抬頭挺胸，膝蓋朝腳尖方向移動。","腳跟發力站起，完成後將槓鈴放回架上。"],"1597":["靠近史密斯機槓鈴站立，雙腳與髖同寬，正握槓鈴。","起槓，雙膝保持接近伸直。","髖部往後推，讓槓鈴順著雙腿往下滑。","往下直到大腿後側有明顯的伸展感。","夾緊臀肌，站直身體。"],"1598":["將槓鈴設定在腰部高度，雙臂交叉，用手肘從下方勾住槓鈴。","起槓並站好，雙腳與肩同寬。","往下深蹲，保持挺胸並讓槓鈴貼近身體。","蹲到大腿約與地面平行。","腳跟發力站起，完成後將槓鈴放回架上。"],"1599":["站直，雙腳分開與肩同寬。","雙手拉著彈力帶，中段套在單腳前掌。","腿伸直，背打直，從髖部慢慢向前俯身。","感受大腿後側與小腿肌肉拉伸。","維持 20-30 秒。","放鬆換腿重複。","重複所需次數。"],"1600":["雙腳與肩同寬，站在淨空的起跳線後。","雙臂往後擺，膝蓋彎曲。","雙臂往前擺，盡全力往遠跳。","雙腳同時落地，膝蓋彎曲吸收衝擊。","重整姿勢並重複動作。"],"1601":["站立，將一腳腳跟放在前方的健身球上，膝蓋伸直。","從髖部往前傾，直到大腿後側有伸展感。","腳跟輕壓球面約 5 秒，接著放鬆。","身體再往前傾一點，加深伸展。","維持 20 到 30 秒，然後換腿。"],"1602":["側身站在長凳或踏板旁。","將內側腳整個踩上台面。","該側腳跟發力往上踩，直到腿部伸直。","將另一隻腳也踩上來併攏。","控制速度退回地面，完成目標次數後換邊。"],"1603":["將健身球夾在下背與牆面之間。","在胸前或身體兩側拿好負重。","雙腳往前踩一步並往下蹲，讓球順著背部滾動。","蹲到大腿約與地面平行。","腳跟發力站回起始位置。"],"1604":["弓箭步預備姿勢開始，右腳前跨，左膝點地。","雙手撐在右腳兩側地面。","左膝跪地、右腿向前伸展打直。","軀幹向右旋轉，右手手臂伸向天花板。","維持數秒，回到原位。","換左腳在前重複拉伸。"],"1605":["將曲槓裝在高位滑輪上，雙手與肩同寬握住。","手肘貼緊身體兩側。","將槓往下壓，直到雙臂完全伸直。","在底部收緊三頭肌停頓一下。","讓槓慢慢回升，直到前臂略高於水平位置。"],"1606":["將曲槓裝在高位滑輪上，掌心朝上反握，雙手與肩同寬。","手肘貼緊身體兩側。","將槓往下壓，直到雙臂伸直。","在底部收緊三頭肌。","慢慢放回，別讓手肘往前跑。"],"1607":["將曲槓裝在低位滑輪上，採反握握住。","站直身體，手肘貼在身體兩側。","將槓朝肩膀方向往上彎舉。","在頂點收緊二頭肌。","慢慢放下，避免晃動身體。"],"1608":["將曲槓裝在低位滑輪上，雙手與肩同寬正握。","站直身體，手肘貼緊身體兩側。","手腕保持平直，將槓往上彎舉。","在頂點停頓一下。","慢慢放下，保持軀幹穩定。"],"1609":["將握把裝在高位滑輪上，側身站在器材旁。","用靠近配重片那側的手握住握把，手肘貼在身側。","將握把往下壓，直到手臂伸直。","在底部收緊三頭肌。","慢慢放回，完成目標次數後換手。"],"1610":["站立，雙手在背後正握槓鈴，手臂伸直。","讓槓鈴順著手掌往下滾到指尖。","手指捲起收緊，把槓鈴拉回掌心。","在頂點順勢將手腕微幅往上彎。","控制速度放下並重複動作。"],"1611":["站直身體，單手在背後拿一個輕啞鈴。","讓啞鈴往下滾，直到停在指尖。","收緊手指，將重量捲回掌心。","手腕保持穩定，手臂貼近身體。","控制速度放下並重複，完成後換手。"],"1612":["俯臥在地面，雙臂往頭頂方向伸直，雙腿打直。","胸口微幅抬起，收緊臀肌。","將一隻手與對側腿往上抬起幾吋。","控制節奏，雙側交替上下擺動。","頸部保持自然中立，平穩呼吸。"],"1614":["調整牧師椅彎舉機高度，上手臂貼墊，胸部靠著支撐板。","反握握住把手，握距略寬於肩寬。","上手臂固定不動，吐氣將把手向肩膀方向彎舉，收縮二頭肌。","在動作頂端稍作停頓，擠壓二頭肌。","吸氣，緩慢將把手放回，完全伸展雙臂。","重複所需次數。"],"1615":["調整座椅高度，坐穩槓桿彎舉機。","上手臂平放在斜墊上，胸靠支撐墊。","以中立對握（掌心相對）抓住握把。","上手臂固定，吐氣將握把拉向肩膀。","頂端停留片刻，擠壓二頭肌。","吸氣慢慢放回。","重複所需次數。"],"1616":["調整座椅坐上機台。","反握抓住把手，掌心朝上。","上手臂貼緊斜墊，手肘完全伸展。","上手臂固定不動，吐氣將把手向肩膀彎舉。","頂峰停頓片刻，收縮二頭肌。","吸氣慢慢放回，完全展肘。","重複所需次數。"],"1617":["躺在下斜椅上，單手持啞鈴置於胸前。","單臂垂直向上推直，手肘微屈。","手肘屈曲將啞鈴向肩膀方向放低，上手臂貼近身體。","將啞鈴推回起始位置。","重複所需次數後換手。"],"1618":["坐在抗力球上，雙手各持一啞鈴，掌心相對。","雙腳前移，身體滑至頭、頸、上背穩穩枕在球上。","啞鈴維持在肩部兩側，手肘彎曲朝外。","將啞鈴向上並稍微向內推起，維持掌心相對。","雙臂完全伸展，在頂端擠壓三頭肌。","慢慢將啞鈴放回肩側。","重複所需次數。"],"1619":["坐在上斜重訓椅上，單手持啞鈴置於大腿。","向後靠在斜椅上，順勢將啞鈴舉至肩膀高度。","手腕內旋使掌心朝向身體。","將啞鈴向上推離身體，手臂完全伸展。","頂峰停頓片刻，慢慢降回起始高度。","重複所需次數後換手。"],"1620":["坐在抗力球上，單手拿啞鈴。","滑動身體至頭頸上背由球體支撐。","單手持啞鈴，掌心朝內，手肘呈 90 度。","將啞鈴垂直推向天花板，手臂伸直。","放回起始位置。","重複所需次數後換手。"],"1621":["坐在抗力球上，雙腳踩平，背部挺直。","單手拿啞鈴，掌心朝內，手肘呈 90 度。","另一手叉腰維持平衡。","向上推舉啞鈴，手臂完全伸直。","頂端停頓片刻，慢慢放回。","重複所需次數後換手。"],"1622":["坐在平凳上，單手持啞鈴，掌心朝向身體。","雙腳踩穩，背部挺直。","啞鈴提至肩部，手肘貼近軀幹。","向上推舉啞鈴，手臂完全打直。","頂端停留片刻，緩慢放回。","重複所需次數後換手。"],"1623":["將重訓椅調整至 45 度上斜。","背靠椅背坐好，雙腳踩實地面。","雙手各握一啞鈴，掌心朝內。","雙臂伸展於胸前上方，手肘微屈。","慢慢將啞鈴降向肩膀兩側，手肘貼近身體。","底部停頓片刻，隨後推回起始位置。","重複所需次數。"],"1624":["平躺在重訓椅上，雙腳踩地，雙膝彎曲。","雙手各持一啞鈴，掌心朝向腳部。","雙臂垂直伸向天花板，手肘微彎。","慢慢將啞鈴降至胸前兩側，手肘自然展開。","底部停頓片刻，然後將啞鈴推回正上方。","重複所需次數。"],"1625":["將史密斯機內的重訓椅調整為下斜。","躺在椅上，雙腳扣緊固定架。","以窄握距握住槓鈴，握距略窄於肩寬。","旋轉解鎖槓鈴，緩緩降向胸口，手肘貼近軀幹。","槓鈴接近胸口時停頓片刻。","將槓鈴推回起始位置，雙臂完全伸直。","重複所需次數。"],"1626":["史密斯機設在下斜位置。","躺在下斜椅上，雙腳固定。","窄握距握槓，略窄於肩。","起槓後慢慢將槓鈴降向胸部，手肘內收。","底部停頓片刻，發力推回。","重複所需次數。"],"1627":["坐在牧師椅上，上手臂貼墊，反手握住 EZ 槓。","三頭肌靠貼在斜墊上，雙臂完全伸展，背部挺直。","慢慢將槓鈴向肩膀彎舉，收縮二頭肌。","頂峰停頓片刻，用力擠壓二頭肌。","慢慢放回起始位置，完全伸展手臂。","重複所需次數。"],"1628":["雙腳與肩同寬站立，反握抓住槓鈴，掌心朝上。","上手臂靠在牧師墊或抗力球上支撐，手肘自然下垂。","上手臂維持固定，吐氣將槓鈴向上彎舉至肩部。","頂部停頓片刻，擠壓二頭肌。","吸氣慢慢放回。","重複所需次數。"],"1629":["雙腳與肩同寬站立，反手寬握抓住槓鈴，握距寬於肩。","背部挺直，手肘貼近軀幹兩側。","吐氣將槓鈴向上彎舉向肩膀，上手臂固定不動。","頂端停頓片刻，擠壓二頭肌。","吸氣慢慢降回原位，充分伸展雙臂。","重複所需次數。"],"1630":["將直桿裝在低滑輪機上。","面對滑輪機站立，雙腳與肩同寬，膝蓋微屈。","反握握住直桿，雙手與肩同寬。","全程保持手肘貼近身側，上手臂固定不動。","吐氣將直桿向上彎舉至胸肩前，收縮二頭肌。","頂端停頓片刻，擠壓二頭肌。","吸氣慢慢放回直桿，完全伸展雙臂。","重複所需次數。"],"1631":["坐在重訓椅或椅子上，雙膝微開，雙腳平踩。","單手握住滑輪把手，手肘抵在大腿內側（集中彎舉）。","上手臂固定，吐氣將把手向肩膀彎舉。","頂峰停頓片刻，吸氣緩緩降回。","重複所需次數後換手。"],"1632":["面對滑輪機站立，雙腳與肩同寬。","單手握住握把，掌心朝上，手臂完全伸直。","上手臂固定不動，吐氣收縮二頭肌將把手彎舉向肩膀。","頂端停頓片刻，擠壓二頭肌。","吸氣慢慢放回，手臂伸直。","重複所需次數後換手。"],"1633":["調整滑輪機與牧師椅斜墊高度至胸部水平。","面對滑輪機站立，雙腳與肩同寬。","單手抓握滑輪把手，上手臂穩貼在牧師墊上。","背部打直，核心收緊。","慢慢將把手向肩膀彎舉，上手臂始終貼緊墊子。","頂峰擠壓二頭肌停頓片刻。","緩慢放回把手。","重複所需次數後換手。"],"1634":["將直桿接在低滑輪機上。","仰臥平躺在平凳上，雙腳踩實地面。","反握抓住直桿，雙手與肩同寬。","手臂完全伸展，手肘貼近身側。","上手臂固定，吐氣將直桿向上彎舉至肩前。","頂端停頓片刻，擠壓二頭肌。","吸氣慢慢放回，充分伸展手臂。","重複所需次數。"],"1635":["滑輪調至最低位置。","面對滑輪機站立，雙腳與肩同寬。","反手握住把手，上手臂靠在牧師斜墊上。","維持背部挺直、核心緊繃。","前臂發力向二頭肌彎起。","頂峰停頓片刻，收縮二頭肌。","慢慢放回把手。","重複所需次數後換手。"],"1636":["將直桿接在高滑輪機上。","面對機台站立，雙腳與肩同寬。","反握抓槓，雙手與肩同寬。","手肘緊貼身側固定。","吐氣將橫桿向額頭方向下拉彎舉。","動作底部停頓片刻，擠壓二頭肌。","吸氣，緩慢送回直桿至雙臂完全伸展。","重複所需次數。"],"1637":["坐在抗力球上，反手握住高滑輪把手。","手臂向上完全伸展，手肘貼近耳側。","將纜繩向額頭方向屈臂下拉。","底部停頓片刻，慢慢送回。","重複所需次數。"],"1638":["直桿安裝在最高位置的滑輪上。","面對滑輪機站立，雙腳與肩同寬。","反手抓槓，雙手與肩同寬。","手肘貼緊身側固定。","吐氣，慢慢將直桿向大腿方向下壓彎舉，手腕維持平直。","底部停頓片刻，擠壓二頭肌。","吸氣慢慢送回起始位置。","重複所需次數。"],"1639":["將繩索配件接在低滑輪機上。","面對機台站立，雙腳與肩同寬。","以中立對握（掌心相對）抓住繩索兩端。","上手臂靠在牧師椅墊上，手肘微屈。","上手臂固定，吐氣收縮二頭肌將繩索彎向肩膀（錘式彎舉）。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢放回。","重複所需次數。"],"1640":["單把手接在低滑輪上。","面對機台站立，雙腳與肩同寬。","反手握把，掌心朝上。","上手臂貼在牧師墊上。","背部維持挺直，核心收緊。","慢慢將把手向肩膀彎舉。","頂峰擠壓二頭肌，然後慢慢放回。","重複所需次數後換手。"],"1641":["坐在滑輪機前，雙腳踩實地面，背部挺直。","反握抓住橫桿配件，掌心朝上，雙臂伸直。","上手臂固定不動，吐氣將把手向肩膀彎舉。","頂部停頓片刻，擠壓二頭肌。","吸氣慢慢放回，手臂充分伸展。","重複所需次數。"],"1642":["坐在重訓椅上，背部打直，雙腳踩地。","單手握滑輪把手，手肘抵在大腿內側近膝蓋處。","吐氣將把手向肩部彎舉，上手臂固定不動。","頂點停頓片刻，擠壓二頭肌。","吸氣慢慢降回。","重複所需次數後換手。"],"1643":["坐在重訓椅上面向滑輪機，雙腳踩實。","反手抓把手配件，掌心朝上，握距與肩同寬。","上手臂固定，手肘貼近軀幹。","吐氣彎舉把手向肩膀，收縮二頭肌。","頂端停頓片刻，擠壓二頭肌。","吸氣慢慢送回，手臂伸展。","重複所需次數。"],"1644":["把手接在滑輪機最低端。","面對滑輪機站立，雙腳與肩同寬。","反手握把，掌心朝上，手臂完全伸直。","下沉進入深蹲姿勢，背打直，膝蓋不超過腳尖。","在深蹲同時，將滑輪把手向肩膀彎舉，手肘固定在體側。","在彎舉頂峰停頓片刻，擠壓二頭肌。","慢慢放回把手，同時伸直手臂。","重複所需次數。"],"1645":["坐在上斜重訓椅上，背靠椅背，雙腳踩實。","反手抓住滑輪握把，掌心朝上，雙臂伸展。","上手臂固定，吐氣將握把彎向肩膀。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢放回，手臂完全伸直。","重複所需次數。"],"1646":["坐在牧師椅上，雙手各持一啞鈴，掌心朝向軀幹，雙臂完全伸展。","上手臂貼緊斜墊，吐氣彎舉啞鈴收縮二頭肌。","持續舉起直到二頭肌完全收縮且啞鈴與肩同高。","在頂峰停頓片刻，收緊二頭肌。","吸氣慢慢放回啞鈴。","重複指定次數。"],"1647":["坐在牧師椅上，雙手各握一啞鈴，掌心朝上。","上手臂貼緊牧師墊，手臂自然下垂伸直。","上手臂固定，吐氣先彎舉右手啞鈴，收縮二頭肌。","持續彎舉至啞鈴與肩同高。","停頓片刻，吸氣慢慢放回。","換左手重複此動作。","雙手交替進行至所需次數。"],"1648":["坐在重訓椅上，雙手各持一啞鈴，掌心朝向身體，雙臂下垂。","背部打直，手肘貼緊軀幹。","吐氣將右手啞鈴向肩膀彎舉，上手臂固定不動。","舉至二頭肌完全收縮且啞鈴與肩同高。","停頓片刻，吸氣慢慢放回。","換左手重複。","雙手交替進行至指定次數。"],"1649":["雙腳與肩同寬站立，雙手各握一啞鈴，掌心朝前。","身後放一顆抗力球，單腳向後搭在球上維持單腳平衡。","雙臂伸展手肘貼側，單臂將啞鈴向肩膀彎舉，上手臂維持固定。","放回起始位置，換另一手彎舉。","雙臂交替進行至所需次數。"],"1650":["坐在抗力球上，雙腳踩實，背部挺直。","雙手各握一啞鈴，掌心朝前，雙臂下垂伸直。","上手臂固定，吐氣彎舉單側啞鈴，前臂微旋轉使掌心朝向肩膀。","吸氣慢慢放回。","換另一隻手臂重複彎舉。","交替進行至指定次數。"],"1651":["雙腳分開與肩同寬站立，雙手各握一啞鈴，掌心朝前。","右腳向前跨出一大步下沉成弓箭步。","向前跨步的同時，順勢將啞鈴向肩膀彎舉，手肘貼近軀幹。","在弓箭步底部，軀幹向右側微轉體（如同保齡球動作）。","反推回站姿，右腳收回，同時下放啞鈴。","換左腳前跨成弓箭步並向左轉體重複。","雙腿交替重複至所需次數。"],"1652":["坐在抗力球上，雙腳踩實，背部挺直。","雙手各握一啞鈴，掌心朝前，雙臂下垂伸展。","慢慢將啞鈴向肩膀彎舉，手肘固定在身側。","頂峰停頓片刻，緩慢降回。","進階操作時可將一條腿抬離地面維持懸空挑戰平衡。","重複所需次數後換腿。"],"1653":["雙腳與肩同寬站立，雙手各握一啞鈴，掌心朝前。","單腿向後伸展，以腳尖點地維持平衡。","上手臂固定，吐氣彎舉啞鈴收縮二頭肌。","持續舉起直到二頭肌完全收縮。","頂峰停頓片刻，收緊二頭肌。","吸氣慢慢降回啞鈴。","重複所需次數後換腿。"],"1654":["站直，雙手各持一啞鈴，掌心朝下（正握反向彎舉），雙臂完全伸展。","上手臂固定不動，吐氣將啞鈴向上彎舉，收縮二頭肌與前臂。","舉至二頭肌完全收縮且啞鈴與肩同高。","頂峰停頓片刻，用力收縮。","吸氣慢慢放回啞鈴。","重複所需次數。"],"1655":["雙腳分開與肩同寬站立，雙手各握一啞鈴，掌心朝前。","背打直手肘夾緊，吐氣將啞鈴向上彎舉至肩部。","頂峰停頓片刻，收縮擠壓二頭肌。","吸氣慢慢放回。","重複所需次數。"],"1656":["坐在 BOSU 半圓平衡球上，雙腳踩平，膝蓋呈 90 度。","雙手各持啞鈴垂於身側，掌心朝前。","上手臂維持不動，吐氣彎舉啞鈴收縮二頭肌。","舉至啞鈴與肩同高。","頂點稍作停頓。","吸氣慢慢將啞鈴放回。","重複所需次數。"],"1657":["站直，雙手各持一啞鈴，掌心朝向身體。","手肘貼緊軀幹，上手臂固定。","吐氣彎舉啞鈴，將啞鈴朝對側肩膀方向向上彎舉（交叉錘式彎舉）。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢放回。","重複所需次數。"],"1658":["雙腳與肩同寬站立，雙手各持一啞鈴，掌心朝前。","右腳向前跨步成弓箭步，右膝 90 度，左膝微離地懸空。","跨步同時將雙手啞鈴向上彎舉向肩膀，手肘貼近身體。","在弓箭步底部稍作停頓，右腳跟蹬地推回站姿，啞鈴順勢放回身側。","換左腳向前跨步重複弓箭步與二頭彎舉。","交替進行至指定次數。"],"1659":["坐在抗力球上，雙腳踩平，背部挺直。","雙手各握一啞鈴，掌心朝向身體，雙臂下垂伸直。","上手臂固定，吐氣彎舉啞鈴收縮二頭肌（錘式彎舉）。","舉至啞鈴與肩同高。","頂點停頓片刻，擠壓二頭肌。","吸氣慢慢放回啞鈴。","重複所需次數。"],"1660":["跪在地板上，身前放一顆抗力球。","將手肘靠在抗力球上，雙手各握一啞鈴，掌心朝上。","上手臂固定，吐氣將啞鈴向肩膀彎舉。","舉至二頭肌完全收縮。","頂峰停頓片刻。","吸氣慢慢放回。","重複所需次數。"],"1661":["平躺在平凳上，頭部與背部貼合，雙腳平踩。","雙手各握一啞鈴，掌心朝上，手臂下垂伸展。","上手臂固定，吐氣將啞鈴向上彎舉。","舉至啞鈴與肩同高。","頂峰停頓片刻。","吸氣慢慢降回。","重複所需次數。"],"1662":["平躺在重訓椅上，雙手各握一啞鈴，掌心朝上，雙臂充分伸展。","上手臂維持穩定不動，吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂峰稍作停頓，用力收緊二頭肌。","吸氣慢慢放回起始位置。","重複所需次數。"],"1663":["坐在牧師椅上，單手持啞鈴，上手臂靠在牧師墊上。","以中立握法握住啞鈴（掌心朝內）。","上手臂固定不動，吐氣將啞鈴向上彎舉向肩膀。","頂端停留片刻，擠壓二頭肌。","吸氣慢慢放回。","重複所需次數後換手。"],"1664":["站直，雙手各握一啞鈴，掌心朝前。","上手臂固定，盡可能將啞鈴向上彎舉，收縮二頭肌。","頂峰稍作停頓，然後慢慢降回。","重複所需次數。"],"1665":["俯臥趴在平凳上，單手持啞鈴，掌心朝下。","手臂完全垂直垂向地面。","上手臂固定不動，二頭肌發力將啞鈴向上彎舉至肩膀。","頂端停留片刻，緩緩降回。","重複所需次數後換手。"],"1666":["俯臥趴在平凳上，單手持啞鈴，掌心朝向軀幹，手臂自然伸直下垂。","上手臂維持不動，將啞鈴向肩膀彎舉收縮二頭肌。","最高點停頓片刻，慢慢放回。","重複所需次數後換手。"],"1667":["站直，單手握啞鈴，掌心朝下（反向彎舉），手臂伸展。","上手臂固定，彎曲手肘將啞鈴向肩膀方向捲起。","最高點停留片刻，慢慢降回。","重複所需次數後換手。"],"1668":["坐在抗力球上，雙腳踩平，背部挺直。","單手拿啞鈴，掌心朝上，雙臂完全伸展。","上手臂固定，二頭肌收縮將啞鈴向肩膀彎舉。","最高點停留片刻，緩慢放回。","重複所需次數後換手。"],"1669":["坐在重訓椅上，背部打直，雙腳平踩地面。","單手握啞鈴，採中立握法（掌心朝內）。","手肘抵在大腿內側近膝蓋處（集中錘式彎舉）。","上手臂維持不動，吐氣將啞鈴彎舉向肩膀。","頂端停頓片刻，擠壓二頭肌。","吸氣慢慢放回。","重複所需次數後換手。"],"1670":["站直，單手握啞鈴，掌心朝前，手臂伸展。","上手臂固定，吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂峰停頓片刻。","吸氣慢慢放回。","重複所需次數後換手。"],"1671":["站直，雙手各持一啞鈴，掌心朝向軀幹。","手肘貼近軀幹，上手臂固定。","吐氣彎舉啞鈴，收縮二頭肌（錘式彎舉）。","舉至啞鈴與肩同高。","頂峰停留片刻，用力擠壓。","吸氣慢慢放回。","重複所需次數。"],"1672":["坐在牧師椅上，單手反握拿啞鈴。","上手臂貼在斜墊上，雙臂完全伸展。","將啞鈴向肩膀彎舉，上手臂維持固定。","在彎舉頂峰旋轉手腕使掌心朝上。","慢慢降回啞鈴，手腕順勢轉回原位。","重複所需次數後換手。"],"1673":["坐在抗力球上，雙腳踩實，背部挺直。","單手反握持啞鈴，手肘靠在抗力球上支撐。","上手臂維持不動，吐氣將啞鈴向肩膀彎舉。","頂峰停頓片刻，吸氣慢慢放回。","重複所需次數後換手。"],"1674":["將重訓椅調整為 45 度上斜。","俯臥趴在斜椅上，雙手各持一啞鈴，掌心相對。","雙臂自然垂直垂向地面，手肘微屈。","上手臂維持不動，吐氣彎舉啞鈴收縮二頭肌（蜘蛛彎舉）。","舉至啞鈴與肩同高。","頂端停留片刻。","吸氣慢慢放回。","重複所需次數。"],"1675":["站直，雙手各持一啞鈴，掌心朝向身體，雙臂下垂伸直。","上手臂固定，吐氣彎舉啞鈴收縮二頭肌。","舉至啞鈴與肩同高。","頂峰停頓片刻。","吸氣慢慢降回。","重複所需次數。"],"1676":["坐在抗力球上，雙腳踩實，背部挺直。","雙手各持一啞鈴，掌心朝向身體，雙臂下垂伸直。","上手臂固定，吐氣單手將啞鈴彎向肩膀，保持掌心朝向身體（單手錘式彎舉）。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂峰停頓片刻。","吸氣慢慢放回。","換另一手重複動作。","雙手交替進行至指定次數。"],"1677":["坐在平凳上，雙腳平踩地面，雙手各握一啞鈴，掌心朝上。","背部維持挺直，手肘貼近軀幹。","吐氣將啞鈴向上彎舉向肩膀，收縮二頭肌。","頂端停頓片刻，吸氣慢慢放回。","重複所需次數。"],"1678":["坐在重訓椅上，雙手各握一啞鈴，掌心朝向軀幹，手臂伸直下垂。","上手臂固定不動，吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂峰停留片刻，用力擠壓。","吸氣慢慢降回起始位置。","重複所需次數。"],"1679":["坐在抗力球上，雙腳踩實，背部挺直。","單手拿啞鈴，掌心朝上，手臂下垂伸直。","另一手叉腰維持平衡。","慢慢將啞鈴向肩膀彎舉，上手臂固定不動。","動作頂點稍作停頓，擠壓二頭肌。","慢慢將啞鈴降回起始位置。","重複所需次數，換手重複。"],"1680":["雙腳分開與肩同寬站立，單手持啞鈴。","另一手扶在上斜重訓椅背上支撐。","上手臂維持固定，收縮二頭肌將啞鈴彎向肩膀。","最高點停留片刻，然後慢慢放回。","重複所需次數後換手。"],"1681":["坐直在健身球上，雙手各拿一個啞鈴，掌心相對。","雙腳踩寬以保持平衡，手肘貼在身體兩側。","手腕不要轉動，將兩個啞鈴同時朝肩膀方向彎舉。","在頂點收緊肌肉，再慢慢放下直到手臂完全伸直。","保持挺胸，避免晃動軀幹。"],"1682":["坐在重訓椅上，雙腳踩實，反握抓住 EZ 槓。","手肘抵在大腿內側近膝蓋處。","將槓鈴向上彎舉向肩膀，上手臂維持固定。","頂峰擠壓二頭肌，然後慢慢降回。","重複所需次數。"],"1683":["將史密斯槓調整至腰部高度。","面對史密斯機站立，雙腳與肩同寬。","反握抓槓，握距略寬於肩寬。","手肘貼緊身體兩側，上手臂固定。","吐氣將槓鈴向上彎舉向肩膀，收縮二頭肌。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢降回槓鈴。","重複所需次數。"],"1684":["站在階梯或踏台前，雙手各持一啞鈴垂於體側。","右腳踏上踏台，確保全腳掌踩實踏面。","收緊核心，右腳跟發力蹬起站上踏台，同時順勢將左膝抬向胸口。","在踏台頂峰站直的同時，手肘彎曲進行啞鈴二頭彎舉。","放低啞鈴，同時左腳向後退下回地面。","換左腳踏上重複跨步與二頭彎舉。","交替進行至所需次數。"],"1685":["雙腳分開與肩同寬站立，腳尖微外展。","彎曲膝蓋髖部後推，下沉進入深蹲。","從深蹲起身站直的同時，順勢將雙臂伸展高舉過頭頂。","放下雙臂同時屈膝再次下蹲。","重複所需次數。"],"1686":["雙腳分開與肩同寬站立，腳尖微外展。","屈膝後坐進入深蹲。","深蹲起身時，將雙臂舉過頭頂並順勢將軀幹轉向一側。","回到中央再次下蹲，起身時換轉向另一側。","每次深蹲起立時持續交替旋轉。"],"1687":["站立，雙腳與臀部同寬，雙臂垂於身側。","右腳向後退一大步，前腳掌著地。","彎曲左膝下沉成反向弓箭步。","下沉同時，雙臂順勢舉過頭頂。","在弓箭步底部停留片刻，踩穩左腳跟蹬起，收回右腳回站姿。","換左腳向後跨步重複。","交替進行至所需次數。"],"1688":["雙腳分開與肩同寬站立。","右腳向前跨出一大步成弓箭步。","弓箭步下沉同時，軀幹向右側轉體，將左手肘移向右膝外側。","稍作停頓，然後回正站回原位。","換左腳向前跨步並向左轉體重複。","雙腿交替進行至所需次數。"],"1689":["高棒式姿勢開始，雙手略寬於肩，身體呈一直線。","手肘微收彎曲，將胸部降向地面。","雙手推地伸直手臂回到頂峰。","再次彎曲手肘進行下一次伏地挺身。","推回高棒式。","重複所需次數。"],"1692":["將藥球抱在胸前，站直身體。","往前跨出成弓步，後膝朝地面放低。","站起的同時將球推過頭頂。","把球放低，並退回起始位置。","雙腿交替，完成預計的次數。"],"1693":["將藥球抱在胸前，單腳站立，膝蓋微彎。","從髖部往前傾，同時將懸空腿往後延伸。","背部保持平坦，將球朝地面放低。","夾緊臀肌，回到站姿。","完成所有次數後換腿。"],"1694":["雙手或單手將一個啞鈴舉過頭頂，站直身體。","往側面大步跨出，髖部往後坐。","保持挺胸，頭頂的手臂伸直鎖定。","彎曲側的腿發力推地，回到中間。","左右交替，完成預計的次數。"],"1695":["將健身球夾在下背與牆面之間。","抬起一隻腳，用另一條腿保持平衡。","往下深蹲，讓球順著牆面滾動。","腳跟發力站回原位。","完成目標次數後換腿。"],"1696":["雙手各拿一個啞鈴，站直身體。","往斜後方或跨過身體前側踩出弓步。","往下蹲到雙膝彎曲，保持上半身挺直。","前腳發力推地，回到起始位置。","左右交替，完成預計的次數。"],"1697":["雙腳與肩同寬站立，將藥球舉在頭頂一側。","往下深蹲，同時將球往身體對角線下方劈。","旋轉軀幹，將球帶往對側膝蓋方向。","站起的同時，將球舉回頭頂一側。","每一組換邊執行。"],"1698":["雙腳站立，膝蓋微彎。","擺動雙臂，往前跳一小段距離。","用前腳掌輕柔落地。","重整姿勢，再跳一次。","保持跳躍穩定可控，並挺起胸口。"],"1699":["側對牆壁站立，將藥球抱在髖部高度。","轉身背向牆壁，將重心蓄力在後側髖部。","爆發性轉體，將球用力砸向牆面。","接住反彈的球並重複動作。","完成預定次數後換邊。"],"1700":["雙腳與肩同寬站立，雙手各握一啞鈴置於肩上。","膝蓋微屈下沉藉力，隨後雙腿爆發性蹬直，順勢將啞鈴推過頭頂（借力推舉 Push Press）。","頂端手臂鎖定打直，然後慢慢將啞鈴收回肩部。","重複所需次數。"],"1701":["高棒式姿勢開始，雙手與肩同寬撐在抗力球上。","手肘微收彎曲，將胸部貼近抗力球。","推地將身體推回高棒式，雙臂伸展打直。","重複所需次數。"],"1702":["單腳站立，膝蓋微彎不鎖死。","從髖部折起，手往下延伸去碰腳或地面。","保持背部平坦，懸空腿向後延伸。","夾緊臀肌回到站姿。","完成所有次數後換腳。"],"1703":["單腳站立，膝蓋微彎不鎖死。","從髖部向前折起，手往身體對側延伸。","延伸時稍微旋轉軀幹。","穩定控制回到站姿。","完成次數後換腳。"],"1704":["單腳站立，雙手拿藥球舉到頭頂一側。","將球沿對角線往身體另一側下方劈。","轉動軀幹，同時轉動站立腳的腳尖。","穩定控制將球舉回頭頂。","完成次數後換腳。"],"1705":["將 BOSU 半圓平衡球平放地面。","雙腳分開與肩同寬，站上 BOSU 球頂端。","屈膝屈髖向後下蹲，如同坐入椅子。","挺胸收腹，重心落於腳跟。","下蹲至大腿與地面平行。","停頓片刻，踩穩腳跟蹬起回站姿。","重複所需次數。"],"1706":["跪在健身球後方，將前臂放在球上。","雙腳往後踩，直到身體從頭到腳跟呈一直線。","收緊腹肌並夾緊臀肌。","保持頸部中立，髖部不要下塌或抬高。","維持 20 到 40 秒，接著放低身體回到地面。"],"1707":["趴在抗力球上，雙腳與肩同寬，腳尖點地支撐。","雙手抱頭或交叉在胸前。","啟動核心挺起上半身，背部打直。","在頂點將軀幹向一側旋轉，肩膀靠近同側髖部，下盤維持穩定。","停頓片刻，回正。","換向另一側旋轉。","交替進行至所需次數。"],"1708":["平躺在地上，雙腿伸展。","彎曲一側膝蓋，腳掌踩地。","用手或毛巾套住另一隻腳腳趾，輕輕拉向身體，感受小腿拉伸。","保持拉伸 20-30 秒。","換腿重複。"],"1709":["平躺在地上，雙腿伸直。","彎曲右膝，將右腳踝跨放在左大腿膝蓋上方（仰臥4字伸展）。","雙手穿過大腿抱住左大腿後側，輕輕拉向胸前。","保持拉伸 20-30 秒感受右臀伸展。","放開後換邊重複。"],"1710":["平躺，雙腿伸展。","右膝彎曲，右腳踝跨在左大腿上。","雙手抱住左大腿，向胸部輕拉加深拉伸。","保持 20-30 秒。","換邊重複。"],"1711":["仰臥或側臥，由夥伴托住你上方的腿。","全身放鬆，讓夥伴輕柔地將腿引導跨過身體。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1712":["側躺在地面上，雙腿打直疊放。","下側腿微彎以維持穩定。","將上側腳搭在穩固台階或重訓椅上。","保持上側腿伸直，慢慢將骨盆重心沉向地面，感受大腿內側拉伸。","保持 20-30 秒。","回到原位後換邊重複。"],"1713":["趴在地上，雙腿伸直。","左膝彎曲，左手向後抓住左腳腳踝。","輕輕將左腳跟拉向臀部，感受左大腿前側（股四頭肌）拉伸。","保持 20-30 秒後放鬆。","換右腿重複。"],"1714":["俯臥趴在地上，雙腿伸直。","彎曲右膝，右手向後握住右腳踝。","輕輕將右腳拉向臀部，感受右大腿前側拉伸。","保持拉伸 20-30 秒。","放開後換另一邊重複。"],"1715":["側躺在健身球上，讓球支撐髖部，單臂往頭頂方向延伸。","身體順著球面微微滾動，讓夥伴輕柔地將延伸的手臂帶得更遠。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1716":["坐在抗力球上，雙腳踩實地面，背部挺直。","雙手抱住抗力球，雙臂向前伸展。","慢慢將球拉近胸口，感受胸大肌拉伸與收縮。","保持數秒，慢慢推回原位。","重複所需次數。"],"1717":["將繩索接在腰部高度的滑輪機上。","面對滑輪機站立，雙腳與肩同寬。","屈膝下蹲成深蹲姿勢，背部打直挺胸。","正握抓住繩索兩端。","收緊核心將繩索拉向身體，肩胛骨向內夾緊。","手肘微收貼側，持續拉至雙手抵達胸腹。","頂點稍作停頓，慢慢放回繩索。","重複所需次數。"],"1718":["坐在重訓椅上，背部挺直，雙腳踩實。","雙手握槓鈴置於頸後，掌心朝前。","手肘貼近頭部，慢慢將槓鈴放低至後頸處。","停頓片刻，手臂推直回到頭頂起始位置。","重複所需次數。"],"1719":["重訓椅調整至 45 度上斜。","躺在椅上，雙腳踩地。","窄握距抓槓鈴，握距略窄於肩寬。","慢慢將槓鈴降向胸前，手肘貼近軀幹。","輕觸胸部時停頓片刻。","發力推回起始位置，雙臂完全伸展（上斜窄握臥推）。","重複所需次數。"],"1720":["平躺在平凳上，雙腳踩實，頭枕在凳緣。","正握抓槓鈴與肩同寬，手臂垂直伸展於胸前。","上手臂垂直地面固定不動，彎曲手肘將槓鈴慢慢降至頭頂後方（碎顱者/仰臥臂屈伸）。","停頓片刻，伸展三頭肌將槓鈴推回原位。","重複所需次數。"],"1721":["平躺在平凳上，雙腳踩實，頭枕在凳端。","反握抓住槓鈴（掌心朝向臉部），握距與肩同寬。","垂直推起槓鈴於胸前，手肘微收、手腕打直。","手肘彎曲，慢慢將槓鈴降向前額上方，上手臂維持固定。","底部稍作停頓，三頭肌發力推回原位。","重複所需次數。"],"1722":["繩索接在高滑輪上，背對滑輪機站立。","雙手反握或對握抓住繩索，雙臂高舉過頭頂。","手肘貼近頭側，上手臂固定不動。","手肘彎曲，慢慢將繩索降至後腦勺下方。","停頓片刻，伸展三頭肌將手臂推直回原位（過頭三頭臂屈伸）。","重複所需次數。"],"1723":["面對滑輪機站立，安裝胸部高度的直桿。","正握抓槓，後退一步使纜繩產生張力。","雙腳與肩同寬，膝蓋微彎。","背部挺直，核心收緊。","上手臂貼緊軀幹固定，吐氣將直桿向下壓直，直到手臂完全伸展。","停頓片刻，吸氣慢慢放回。","重複所需次數後換手（如為單手）或組數。"],"1724":["繩索接在高滑輪上，調整適當配重。","背對滑輪機站立，雙腳與肩同寬。","雙手握住繩索，高舉過頭頂。","上手臂靠近頭側且垂直地面。","手肘彎曲，慢慢將繩索放低至頭後。","停頓片刻，三頭肌發力將手臂完全伸展推回。","重複所需次數。"],"1725":["繩索接在高滑輪上，可搭配斜椅背靠。","背對滑輪站立，雙腳與肩同寬。","正握抓繩索，雙臂高舉過頭頂。","上手臂貼近頭部固定。","手肘彎曲將繩索降至後腦勺，直到前臂貼近二頭肌。","稍作停頓，手臂伸直推回。","重複所需次數。"],"1726":["繩索接在低位滑輪機上。","仰臥躺在地面，頭部朝向滑輪機。","雙手抓住繩索兩端，掌心相對，手臂垂直伸向天花板。","上手臂垂直固定，彎曲手肘將繩索放低至額頭兩側。","停頓片刻，伸展手臂推回。","重複所需次數。"],"1727":["背對滑輪機站立，雙腳與肩同寬。","單手持滑輪把手，手臂伸展高舉過頭，手肘靠近耳朵。","上手臂固定不動，手肘彎曲將把手降至頭後。","底部停頓片刻，三頭肌發力將手臂推直。","重複所需次數後換手。"],"1728":["雙腳分開與肩同寬站立，膝蓋微屈。","雙手抓住滑輪手把，掌心朝內，手臂呈 90 度屈曲。","上手臂貼緊身側固定，前臂向後推伸直，直到手臂完全伸展（滑輪三頭後屈伸）。","停頓片刻，慢慢放回 90 度。","重複所需次數。"],"1729":["平躺在平凳上，雙手各握一啞鈴，掌心相對，手臂垂直於胸前。","手肘微彎，先將單側啞鈴向下屈臂降向頭部，另一臂維持伸展。","底部停頓片刻，推回起始位置。","換另一側手臂重複，雙手交替進行至指定次數。"],"1730":["坐在重訓椅上，雙手各握一啞鈴，掌心朝內。","屈髖向前俯身，背部打直與地面平行。","單臂向後推直伸展，手肘貼緊身側，直到手臂完全伸直（啞鈴三頭後屈伸）。","頂點停頓片刻，慢慢收回。","換手重複，雙手交替進行至指定次數。"],"1731":["坐在平凳上，雙手各握一啞鈴置於大腿。","用大腿輔助將啞鈴頂至肩寬高度。","轉動手腕使掌心朝前，躺上椅面。","吸氣慢慢將啞鈴降至胸旁，直到與胸口齊平。","吐氣運用胸肌與三頭肌發力將啞鈴推回正上方。","頂峰停頓收緊肌肉，重複所需次數。"],"1732":["雙腳與肩同寬站立，雙手各握一啞鈴。","右腳向前跨步成弓箭步。","背部維持挺直，挺胸。","雙臂伸直高舉過頭頂，手肘貼近耳朵。","手肘彎曲，將啞鈴降向後腦勺。","停頓片刻，手臂向上伸展推回起始位置。","重複所需次數後換腿。"],"1733":["坐在上斜重訓椅上，雙手各握一啞鈴置於大腿。","慢慢躺下，啞鈴貼近胸口。","將手臂向上推直，手肘微屈。","頂部停頓片刻，慢慢降回胸側。","重複所需次數。"],"1734":["坐在抗力球上，雙腳踩實，背部挺直。","雙手各握一啞鈴，掌心朝內，手肘彎曲呈 90 度。","將手臂向後伸直，在動作頂峰擠壓三頭肌。","稍作停頓，慢慢放回 90 度。","重複所需次數。"],"1735":["平躺在平凳上，單手持啞鈴垂直伸直於胸前。","上手臂固定不動，控制著將啞鈴降向前額上方。","在動作底部稍作停頓，然後伸展手臂推回。","重複所需次數後換手。"],"1736":["坐在抗力球上，雙腳踩實，背部挺直。","單手持啞鈴，掌心朝前，手肘呈 90 度。","將手臂垂直推向天花板，手肘打直。","慢慢降回肩部起始位置。","重複所需次數後換手。"],"1737":["坐在重訓椅上，雙腳踩實，雙手各持一啞鈴。","屈髖向前俯身，背部挺直，抬頭平視。","手肘貼緊頭側向後伸展手臂。","停頓片刻，慢慢放回。","重複所需次數。"],"1738":["坐在重訓椅上，背部打直，雙腳踩實。","反握抓住啞鈴，手臂垂直向上伸過頭頂。","手肘彎曲將啞鈴降向頭後，上手臂維持固定。","停頓片刻，手臂推直回到頭頂。","重複所需次數後換手。"],"1739":["雙腳與肩同寬站立，雙手各握一啞鈴。","膝蓋微屈，屈髖前傾，背部打直。","雙臂向後伸展推直，手肘緊貼身側。","頂峰停頓片刻，慢慢收回。","交替進行或雙臂同步進行至指定次數。"],"1740":["雙腳與肩同寬站立，單手持啞鈴。","屈髖前傾，背部平直與地面平行。","將單側手臂向後推直伸展，手肘貼身。","慢慢收回啞鈴。","重複所需次數後換手。"],"1741":["雙腳與肩同寬站立，雙手各持一啞鈴。","屈髖俯身，背部挺直，膝蓋微彎。","雙臂向後伸展打直，手肘貼身。","慢慢收回啞鈴。","重複所需次數。"],"1742":["雙腳與肩同寬站立，右手持啞鈴。","膝微屈，屈髖前傾，背部平直。","右上臂抬起貼近身側，手肘呈 90 度。","右臂向後推直伸展，擠壓三頭肌。","頂端停頓片刻，慢慢放回 90 度。","重複所需次數後換邊。"],"1743":["平躺在重訓椅上，雙腳踩實，背貼椅面。","雙手各握一啞鈴，正握，掌心背向自己。","推起啞鈴至胸口正上方，手肘微屈。","降向胸部時手肘貼身，旋轉手腕使掌心在底部朝向自己。","底部停頓片刻，推起啞鈴同時轉回手腕，使掌心再度背向自己。","重複所需次數。"],"1744":["坐在抗力球上，雙腳踩實，膝蓋呈 90 度。","雙手置於臀部旁的球面上，手指朝前。","三頭肌與手臂發力推直，將臀部抬離球體。","屈肘下沉身體貼近球前緣。","重複所需次數。"],"1745":["坐在抗力球上，雙腳踩平，背部挺直。","單手拿啞鈴，手臂向上垂直伸直。","手肘彎曲將啞鈴降向後頸，上手臂靠近耳側。","保持伸展數秒，然後推回正上方。","換另一手重複。"],"1746":["坐在抗力球上，雙腳踩平，膝蓋呈 90 度。","雙手合握一個啞鈴，垂直向上伸向天花板。","慢慢將啞鈴放低至後腦勺，手肘維持靠近耳旁。","停頓片刻，伸展三頭肌將啞鈴推回正上方。","重複所需次數。"],"1747":["坐在抗力球上，正握抓住 EZ 槓。","雙臂向上完全伸展，手肘貼近頭部。","彎曲手肘，慢慢將槓鈴降至後腦勺下方。","停頓片刻，將手臂向上推展回原位。","重複所需次數。"],"1748":["平躺在重訓椅上，頭枕在椅端，雙腳踩實。","雙手反握或正握抓住 EZ 槓，將雙臂推直於胸口上方。","上手臂垂直固定，手肘彎曲將槓鈴降向頭頂後方。","停頓片刻，手臂伸展推回。","重複所需次數。"],"1749":["雙腳與肩同寬站立，正握抓槓鈴。","將槓鈴高舉過頭頂，雙臂伸展。","上手臂貼近頭部固定，彎曲手肘將槓鈴降向後腦勺。","停頓片刻，伸直雙臂推回頭頂。","重複所需次數。"],"1750":["平躺在平凳上，雙膝彎曲雙腳踩實。","雙手抱藥球於胸前。","手肘微收，雙手爆發力向上將藥球盡可能推拋向高空。","接住落下的藥球，立即銜接下一次重複。"],"1751":["在深蹲架上將槓鈴調至胸部高度。","面對槓鈴站好，雙腳與肩同寬。","正握抓槓，握距略寬於肩寬。","起槓推直於胸部上方。","將槓鈴慢慢降向胸部，手肘適度內收。","觸胸時稍作停頓。","發力推回起始位置，雙臂完全伸展。","重複所需次數。"],"1752":["調整史密斯椅位，使槓鈴位於肩部高度。","坐在重訓椅上，背靠椅背，雙腳踩實。","正握抓槓，握距略寬於肩。","起槓推直於胸部正上方。","上手臂固定，手肘彎曲將槓鈴降向前額上方。","底部停頓片刻，三頭肌發力推回。","重複所需次數。"],"1753":["坐在重訓椅邊緣，雙手握住椅緣，手指朝前。","臀部移開椅面，雙手支撐全身重量。","屈肘下沉身體，直到上手臂平行地面。","手臂推直，將身體撐回原位（椅子雙臂撐體）。","重複所需次數。"],"1754":["坐在平凳邊緣，雙手握緊凳緣。","雙腳向前走，臀部懸空移出凳緣，手臂支撐體重。","屈肘下沉身體，背部貼近長凳。","底部停頓片刻，撐起身體回原位。","重複所需次數。"],"1755":["坐在重訓椅邊緣，雙手抓在臀部兩側。","雙腿向前伸展，臀部滑出椅面。","背部貼近長凳，手肘微屈。","手肘彎曲下沉身體至上手臂平行地面。","雙手推直將自己撐回頂端。","重複所需次數。"],"1756":["雙腳與臀部同寬站立，正握槓鈴置於大腿前。","重心轉移到左腳，右腳向後微抬懸空。","背部打直、屈髖前傾，右腿順勢向後延伸平衡（單腿羅馬尼亞硬舉）。","將槓鈴沿著左腿下放，左膝保持微彎。","在底部感受拉伸停頓片刻，臀大肌發力將身體拉回站姿。","重複所需次數後換腳。"],"1757":["雙腳與臀部同寬站立，右手持啞鈴。","重心移至左腿，右腳向後微離地。","背部打直，屈髖前傾將啞鈴降向地面。","同時右腿向後伸展打直，與軀幹呈一直線平行地面。","在拉伸極限處停頓片刻，臀肌發力站回原位。","重複所需次數後換手換腳。"],"1758":["坐在下斜板或平凳上，固定雙腳。","平躺，膝蓋微屈。","雙手放於後腦勺，手肘朝外。","腹肌發力收緊，將上半身捲離椅面，抬至約 45 度（斜板仰臥起坐/捲腹）。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"1759":["雙腳與肩同寬站立，雙臂向前平舉。","右腿向前伸直懸空。","彎曲左膝髖部後推，單腿下蹲（手槍深蹲）。","下蹲時挺胸背打直。","蹲至左大腿平行地面或舒適深度。","底部停頓片刻，踩穩左腳跟蹬起回站姿。","重複所需次數後換腿。"],"1760":["雙腳與肩同寬站立，雙手在胸前垂直托住一個啞鈴（高腳杯深蹲 Goblet Squat）。","挺胸收腹，屈髖屈膝向後下蹲。","蹲至大腿平行地面或略低。","底部停頓片刻，腳跟發力推回站姿。","重複所需次數。"],"1761":["懸掛在單槓上，手臂完全伸展，掌心朝外。","收緊核心，屈膝將雙膝抬向胸部，同時將下半身向一側轉動。","頂端停留片刻，慢慢放回中央。","換向另一側重複抬腿轉體。","交替進行至所需次數。"],"1762":["站在穩固的支撐物旁，用單手或雙手扶住。","將一腿往前抬起，用另一腿保持平衡。","髖部往後坐並屈膝，在可控範圍內盡量往下蹲。","保持腳跟貼地，膝蓋對齊腳尖方向。","腳掌踩地站起，只在必要時借用支撐物輔助，接著換腳。"],"1763":["抓握單槓，握距與肩同寬，掌心朝外（正握引體向上）。","雙臂完全伸直懸掛。","啟動背肌將身體向上拉起，直到下巴超過單槓。","頂峰停頓片刻，慢慢降回懸掛姿勢。","重複所需次數。"],"1764":["懸掛在單槓上，手臂伸直，掌心朝外。","收緊核心，屈髖屈膝抬起雙腿，直到大腿與地面平行。","頂峰停頓片刻，緩慢放回。","重複所需次數。"],"1765":["雙腳與肩同寬站立，雙手各持一啞鈴，正握。","啞鈴垂在大腿前，雙臂伸展。","背部打直核心收緊，吐氣以手肘引導將啞鈴垂直向上提拉至下巴高度（啞鈴直立划船）。","手肘始終高於手腕，在頂峰停頓片刻。","吸氣慢慢降回啞鈴。","重複所需次數。"],"1766":["趴在機械腿彎舉機上，腳踝扣在滾輪墊下方。","雙手抓緊把手維持上半身固定。","上半身放平貼墊，吐氣收縮腿後肌群，將滾輪拉向臀部。","頂峰強力收縮腿後腱片刻。","吸氣慢慢放回至膝蓋微屈。","重複所需次數。"],"1767":["雙手撐在雙槓上，雙臂伸直支撐全身重量。","彎曲手肘下沉身體，直到上手臂平行地面。","稍作停頓，雙手推直將自己推回頂端（雙槓撐體）。","重複所需次數。"],"1769":["側躺在地面上，單臂屈枕在頭下。","上臂貼緊身側，手肘彎曲，前臂向上彎舉。","頂峰停頓片刻，慢慢放回。","重複所需次數後換邊。"],"1770":["坐在重訓椅上，雙腿張開，雙腳平踩。","單手拿啞鈴，手肘抵在大腿內側近膝蓋處。","掌心朝上，將啞鈴向上彎舉向肩膀，上手臂維持不動（集中彎舉）。","頂端擠壓二頭肌，慢慢降回。","重複所需次數後換手。"],"1771":["膝蓋跪地與臀同寬。","雙手在身前撐地與肩同寬，手指朝前。","雙腿向後伸展成高棒式，身體成一直線。","手肘微收彎曲，將上半身降向地面。","底部停頓片刻，掌心推地推回起始位置。","重複所需次數。"],"1772":["俯臥趴在地上，雙腿伸展，雙手撐在肩部正下方。","收緊核心手掌推地，將上半身挺離地面，手肘貼近身側。","頂峰停留片刻，收縮上背肌群。","慢慢將身體放回地面。","重複所需次數。"],"1773":["雙腳分開與肩同寬站立，雙膝微屈，單手抓握毛巾。","屈髖前傾，背部維持平直，核心收緊。","手臂完全向前伸展垂下。","將毛巾拉向胸部，夾緊肩胛骨。","頂峰停頓片刻，慢慢放回。","重複所需次數後換手。"],"1774":["側躺，雙腿伸直疊放。","前臂撐地，手肘正對肩膀下方。","啟動核心將髖部抬離地面成側棒式，身體呈一直線。","維持側棒式穩定，將上側腿向上抬起，骨盆不翻轉。","頂峰停頓片刻，慢慢放回。","重複所需次數後換邊。"],"1775":["側躺在地上，雙腿伸直疊放。","手肘置於肩下撐起身體成側棒式。","核心收緊，骨盆抬離地面呈一直線。","維持側棒式姿勢，將上側腿朝天花板向上抬高打直。","慢慢降回。","重複所需次數後換邊。"],"1776":["俯臥，雙腿伸直，額頭枕在雙手上。","收緊腹肌與臀肌。","將一側直腿抬離地面幾吋。","在頂點短暫停留，不要讓下背過度拱起。","穩定控制放低並重複動作，接著換腿。"],"1777":["站直，十指交扣，將雙臂舉過頭頂。","雙臂稍微往後推並挺起胸口，下背不要拱起。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1778":["站直，雙臂向兩側展開，雙手高度約與肩同高或稍低。","請夥伴握住你的手腕，慢慢將雙臂往後拉，直到感覺胸口有伸展感。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1779":["在長凳或椅子上坐直，雙手抱頭後側或將手臂向兩側展開。","請夥伴站在你身後，輕柔地將你的手肘或手腕往後帶。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1780":["站在牆邊或門框旁，手肘彎曲呈 90 度，將前臂貼在牆面上。","往前踏一步並將身體轉向另一側，直到感覺胸口有伸展感。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1781":["面對牆角站立，雙手前臂分別貼在兩側牆面上，高度約與肩同高。","一腳往前踏，胸口往牆角傾靠，直到感覺有伸展感。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1782":["站直，雙臂伸直在背後十指交扣。","雙手往上抬並遠離身體，同時展開胸口。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1783":["站在肋木旁，單手握住約與肩同高的橫桿。","慢慢將身體轉向背對肋木的方向，直到感覺胸口有伸展感。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1784":["站直或坐直，雙臂在背後伸直，高度介於髖部到肩膀之間。","請夥伴握住你的手腕，輕柔地將雙臂往後且稍微往上拉。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1785":["跪在長凳或椅子前方，將前臂或雙手放在上面。","髖部往後坐，讓胸口往地面方向下沉，直到感覺有伸展感。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1786":["坐姿或站姿，雙手在頭後側交扣，手肘向兩側打開。","身體微微前傾的同時，請夥伴將你的手肘往後拉。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1787":["站直，雙腳與髖同寬，雙臂伸直往背後延伸。","雙臂稍微往上抬並展開胸口，身體不要往後仰。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1788":["站直，雙臂伸直舉過頭頂，掌心朝前。","往上並稍微往後延伸，保持肋骨下收、核心微微收緊。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1789":["仰臥，雙臂向兩側或頭頂方向伸直展開。","請夥伴輕柔地將你的手腕或手臂往地面方向下壓。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1790":["俯臥，雙臂向兩側展開，額頭輕靠在地面上。","請夥伴握住你的手腕，慢慢將雙臂往上、往後抬起。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1791":["坐直或站直，單手抓住椅面邊緣或背在身後，將該側肩膀往下固定。","將頭傾向另一側肩膀，直到感覺頸部側邊有伸展感。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1792":["站直，將一隻手臂在肩膀高度橫過胸前。","用另一隻前臂勾住它，輕柔地往胸口方向拉近。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1793":["站直，將一隻手臂伸直橫過胸前。","用另一手扶在手肘上方，將手臂往身體方向拉近。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1794":["站姿或坐姿，雙手在胸前高度交扣，或扶住前方的支撐物。","拱起上背，雙手往前推，同時讓頭自然垂在雙臂之間。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1795":["雙腳與髖同寬站立，雙臂在胸前高度往前延伸。","拱起上背，雙手往前推遠並將肩胛骨往兩側拉開。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1796":["雙腳與肩同寬站立，單臂舉過頭頂。","將上半身輕柔地往舉起手的那一側反方向旋轉，手臂往上並往側邊延伸。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1797":["站直，雙臂舉過頭頂，掌心相對。","往上延伸並稍微往後仰，保持下背放鬆、肋骨下收。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1798":["仰臥，雙臂舉過頭頂，雙腿伸直。","指尖往上延伸、腳尖往下延伸，就像要把身體拉長一樣。","保持肩膀放鬆，呼吸緩慢平穩。","維持 20 到 30 秒，不要來回彈震。","輕柔放開並重複，如果是單側伸展則換邊進行。"],"1799":["雙手抓握頭頂上方的牆梯橫桿，雙腳稍微往前走。","讓身體自然懸垂，髖部往後沉，放鬆上背與肩膀。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1800":["雙手握住約在胸口高度的滑輪配件或握把。","雙臂打直、身體後傾，髖部往後坐，直到感覺背部被拉長。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1801":["站直，單手抓住高過頭頂的柱子或架子。","身體往抓握手的反方向傾，髖部微微往後坐，感受身體側邊的伸展。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1802":["站直，雙腳與髖同寬，單手舉過頭。","身體往舉起手的反方向側傾，手臂延伸出去，軀幹不要扭轉。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1803":["坐在地板或長凳上，膝蓋微彎，雙腳平放。","拱起背部，胸口貼向大腿，讓雙手自然垂下。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1804":["坐在椅子或長凳上，挺直背部，雙腳平踩地面。","身體前彎，雙手伸向其中一腳，讓軀幹微微往該側彎曲。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1805":["坐在長凳或椅子上，雙腳平放，雙膝打開。","從髖部往前彎，讓頭與雙手自然垂在兩膝之間。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1806":["盤腿坐或雙腳平放坐直，單手放在身側地面。","另一手往上舉過頭並往側邊延伸，拉長身體側邊。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1807":["盤腿坐在地板上，背部挺直。","雙手沿著地面往前走，從髖部往前折，直到感覺到伸展。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1808":["仰躺，雙膝彎曲，雙腳平放。","將雙膝拉向胸口，雙手抱住膝蓋。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1809":["坐在地板上，雙腳腳底貼合，雙膝自然往兩側落下。","握住雙腳，脊椎保持延伸，從髖部往前彎折。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1810":["仰躺，雙腿伸直。","雙手將單側膝蓋拉向胸口，另一腿保持平貼地面。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1811":["站直，需要時可扶牆維持平衡。","抬起單側膝蓋，雙手輕輕將膝蓋拉向胸口。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1812":["採四足跪姿，雙手在肩膀正下方。","單手放在後腦勺，將手肘往天花板方向旋轉打開。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1813":["雙腳與肩同寬站立，雙手抬至胸口高度。","髖部保持朝前，將上半身轉向其中一側。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1814":["單手往前伸直，掌心朝上。","用另一手輕輕將手指往下、往後壓，直到感覺到伸展。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1815":["單手往前伸直，手肘打直，掌心朝下。","用另一手將掌心往外轉，直到感覺前臂受到伸展。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1816":["站直，雙臂筆直舉過頭。","雙臂微微往後推，指尖盡量往上延伸。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1817":["將雙手或前臂放在身後的長凳或其他穩固支撐物上。","身體稍微往下沉並往前離，直到感覺手臂前側受到伸展。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1818":["以反握、與肩同寬的握距抓住單槓。","雙臂打直讓身體懸垂，肩膀往下放鬆。","雙腳可視需要踩地分擔體重，維持舒適即可。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1819":["反握滑輪握把，手臂打直。","重心輕輕往後傾，直到感覺二頭肌與前臂受到伸展。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1820":["坐在牧師椅上，上臂貼著靠墊，雙手握住 EZ 槓。","使用輕重量，受控地讓槓鈴往下放，直到手臂完全伸直。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1821":["單手往前伸，手肘打直。","慢慢將掌心朝上與朝下轉動，在兩端盡頭用另一手輕輕加壓。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1822":["單手往前伸直，掌心朝下。","彎曲手腕，讓手指朝下。","將手掌輕輕往小指側傾斜。","用另一手輕輕加壓。","停留 20 到 30 秒，接著換手。"],"1823":["單手往前伸直，掌心朝下。","彎曲手腕，讓手指朝下。","將手掌輕輕往拇指側傾斜。","用另一手輕輕加壓。","停留 20 到 30 秒，接著換手。"],"1824":["單手往前伸直，掌心朝上。","用另一手將手指往身體方向扳。","將手掌輕輕往拇指側傾斜。","手肘保持打直，肩膀放鬆。","停留 20 到 30 秒，接著換手。"],"1825":["單手往前伸直，掌心朝上。","用另一手將手指往身體方向扳。","將手掌輕輕往小指側傾斜。","手肘保持打直，肩膀放鬆。","停留 20 到 30 秒，接著換手。"],"1826":["單手往前伸，掌心朝上或朝外。","用另一手輕輕將手指與手掌往身體方向拉。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1827":["單手往前伸，掌心朝下，手腕放鬆。","用另一手輕輕將手指與手背往下、往身體方向壓。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1828":["單手舉過頭，彎曲手肘，讓手掌落到後腦勺後方。","用另一手將手肘輕輕往後、往下壓。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1829":["站在牆邊，將彎曲的手肘貼在高過頭頂的牆面上。","身體往前並往下傾，直到感覺上臂後側受到伸展。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1830":["單手往前伸，掌心朝下並將手肘完全彎曲。","用另一手將前臂壓向上臂，接著輕輕旋轉前臂。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1831":["坐直或站直，肩膀放鬆。","在舒適範圍內，慢慢將頭轉向一側，再轉向另一側。","下巴保持水平，不要硬壓到產生疼痛。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1832":["坐直，將頭輕輕往一側轉約 45 度。","下巴往斜前方低向胸口，可用手輕輕加壓。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1833":["坐直或站直，肩膀放鬆。","下巴放鬆，慢慢將頭往後仰看向天花板。","肩膀保持放鬆，呼吸放慢且平穩。","停留 20 到 30 秒，過程不要彈震。","慢慢放開並重複，如果是單邊伸展就換邊。"],"1834":["坐直或站直，肩膀放鬆。","視線保持水平，將下巴與頭部筆直往前推。","感覺後頸受到伸展就停住。","停留 20 到 30 秒，慢慢呼吸。","將頭收回中立位置並放鬆。"],"1835":["坐在椅子上挺直背部，雙手放在大腿上。","慢慢將下巴低向胸口。","靠頭部的重量自然垂下，不要硬壓。","停留 20 到 30 秒，慢慢呼吸。","慢慢將頭抬回中立位置。"],"1836":["站直或坐直，肩膀下沉。","雙手輕放在後腦勺。","手肘往前垂下，輕輕將頭帶向胸口。","停留 20 到 30 秒，慢慢呼吸。","放開雙手並回到中立位置。"],"1837":["坐直，背部挺直。","下巴往胸口收。","單手放在後腦勺，極輕地往下加壓。","停留 20 到 30 秒，慢慢呼吸。","移開手並慢慢抬起頭。"],"1838":["坐直，肩膀放鬆。","將頭往一側轉約 45 度。","單手放在後腦勺，輕輕將鼻子帶向同側腋下。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1839":["坐直或站直，肩膀放鬆。","抬起下巴，慢慢將頭往後仰。","動作幅度保持小且舒適。","停留 20 到 30 秒，慢慢呼吸。","將頭收回中立位置。"],"1840":["坐直或站直，肩膀下沉。","將頭微微轉向一側。","下巴往上抬並往後仰，直到感覺頸部前側受到伸展。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1841":["仰躺，雙膝彎曲。","雙手交扣放在後腦勺。","輕輕抬起頭，將下巴帶向胸口。","停留 20 到 30 秒，慢慢呼吸。","慢慢將頭放回地面。"],"1842":["仰躺在長凳或床上，肩膀有支撐，頭部靠近邊緣。","慢慢讓頭往後放鬆垂出邊緣。","如果覺得頭太重，可以用雙手托著。","停留 20 到 30 秒，慢慢呼吸。","用雙手小心地把頭托回來。"],"1843":["坐直，肩膀放鬆。","在舒適範圍內將頭轉向一側。","一手扶著下巴，另一手放在後腦勺。","輕輕加壓以加深轉動幅度。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1844":["坐直或站直，肩膀下沉。","將頭微微往後仰。","單側耳朵往同側肩膀靠近。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1845":["躺在下斜長凳上，雙手抓住頭頂上方的長凳邊緣。","抬起雙腿並彎曲膝蓋。","將髖部捲離長凳，讓膝蓋靠近胸口。","慢慢放回長凳，不要擺盪。","全程保持動作受控。"],"1848":["面對牆壁站立，一腳往後踩，腳跟貼地。","後腿保持打直，身體往牆壁傾。","後腳跟往下踩，直到感覺小腿受到伸展。","髖部擺正，腳尖朝前。","停留 20 到 30 秒，接著換腳。"],"1850":["單手往前伸直，掌心朝上。","用另一手將手指往身體方向扳。","手肘保持打直，肩膀放鬆。","感受前臂內側的伸展。","停留 20 到 30 秒，接著換手。"],"1851":["設定好上斜長凳，雙手將槓鈴握在上胸位置。","雙腿微微下蹲再蹬，帶出起始動能。","雙臂順勢將槓鈴往上推。","在胸口上方推直鎖定，接著受控下放。","核心收緊，下背不要過度拱起。"],"1852":["仰躺，雙腿伸直，雙手放在身體兩側。","將雙腿抬高至與地面垂直。","將髖部捲離地面，雙腳往天花板方向推。","受控地先放下髖部，再放下雙腿。","動作保持流暢，避免擺盪。"],"1854":["仰躺，雙手墊在髖部下方。","膝蓋微彎，雙腳離地。","將雙腿抬至髖部正上方。","慢慢下放，不要讓下背拱起。","全程保持核心收緊。"],"1855":["仰躺，雙腿伸直，雙手放在身體兩側。","將頭與肩膀微微抬離地面。","將雙腿抬高至與地面垂直。","將髖部稍微推離地面，雙腳往天花板方向抬。","受控地將髖部與雙腿慢慢放回。"],"1856":["躺在器械上，雙手握住握把。","膝蓋彎曲，雙腿勾在靠墊下方。","將膝蓋捲向胸口。","在頂點短暫停留。","慢慢下放直到感覺張力，接著重複。"],"1857":["調整座椅，坐好並讓胸口貼著靠墊。","握住握把，雙腳踩穩。","收縮腹肌，將軀幹往前捲。","在底端短暫停留。","慢慢回到起始位置，不要讓重量直接掉下去。"],"1858":["躺在下斜座椅上，雙腳勾在靠墊下方。","雙手抱胸或握住握把。","將軀幹往膝蓋方向捲起。","在頂點用力收縮腹肌。","受控地慢慢往後躺回。"],"1859":["在高位滑輪裝上繩索或橫桿，背對器械跪姿。","雙手在頭頂上方握住握把，手肘彎曲置於腦後。","上臂保持固定，將手肘打直。","完全伸直時用力收縮三頭肌。","慢慢回到起始位置。"],"1860":["將靠墊設定在髖部高度，腳後跟勾在滾筒下方。","雙手抱胸，身體保持一直線。","背部打直，從髖部往前彎。","抬起軀幹，直到與雙腿呈一直線。","在頂點不要過度後仰，接著受控下放。"],"1861":["在低位滑輪裝上多功能 V 型把手，掌心朝上握住。","站直，手肘貼在身體兩側。","將把手往肩膀方向彎舉。","在頂點用力收縮二頭肌。","慢慢下放，不要讓手肘前後跑掉。"],"1862":["調整座椅，讓握把位於肩膀高度。","背部貼好坐穩，雙腳平放並握住握把。","往上推，直到手臂接近完全伸直。","在頂點短暫停留。","慢慢下放回到起始位置。"],"1863":["調整座椅，雙手握住頭頂上方的握把。","坐直並挺胸。","將握把往下拉，手肘往身體兩側帶。","在底端夾緊肩胛骨。","慢慢放回至完全伸展。"],"1864":["將下斜長凳設定到較陡的角度，雙腳勾在靠墊下方。","往後躺下，雙手抱胸。","將軀幹往上捲，直到呈坐姿。","在頂點用力收縮腹肌。","慢慢躺回原位。"],"1865":["雙手掌心相對，握住對握握把。","雙臂完全伸直懸吊。","手肘往下帶，將胸口拉向握把。","下巴超過橫桿時短暫停留。","慢慢下放至完全懸吊。"],"1866":["掌心朝前，握住寬握把。","雙臂完全伸直懸吊。","手肘往下、往後帶，將身體拉上去。","下巴超過橫桿時短暫停留。","慢慢下放至完全懸吊。"],"1867":["坐在器械上，背部貼著靠墊。","雙腿靠在已調寬的腿墊內側。","平穩地將雙腿往中間夾。","雙腿靠攏時短暫停留。","慢慢打開回到起始位置。"],"1868":["在深蹲架設定好槓鈴，將槓放在斜方肌下方的後三角肌上。","往後退一步，雙腳站距與肩同寬。","身體微前傾，髖部往後、往下坐。","下蹲到大腿至少與地面平行。","保持挺胸，腳跟發力站起。"],"1869":["背部貼著靠墊坐好，雙腿放在腿墊內側。","握住兩側握把以維持穩定。","平穩地將雙腿往外推開。","在最開的位置短暫停留。","慢慢收回，不要讓槓片互撞。"],"1870":["調整座椅，雙手握住頭頂上方的握把。","坐直並挺胸。","往下拉直到握把到胸口高度。","夾緊肩胛骨。","慢慢放回至完全伸展。"],"1871":["坐直，雙手握住身側的握把。","手肘夾緊身體兩側。","往下推直到手臂伸直。","用力收縮三頭肌。","慢慢回到起始位置。"],"1872":["調整座椅，讓上臂貼在靠墊上。","掌心朝上握住握把。","往上彎舉直到二頭肌完全收縮。","短暫停留。","慢慢下放直到手臂接近伸直。"],"1873":["背部貼著靠墊坐好，小腿前側靠在滾筒後方。","握住兩側握把。","伸直膝蓋直到雙腿打直。","在頂點用力收縮股四頭肌。","受控地慢慢下放。"],"1874":["背部貼著靠墊坐好，小腿前側靠在滾筒後方。","握住兩側握把。","將單腿踢直。","慢慢下放。","換另一腿重複，持續交替。"],"1875":["站到肩墊下方，雙腳與肩同寬。","解開安全扣並站直。","髖部往後、往下坐，直到大腿與地面平行。","腳跟發力站起。","保持挺胸，膝蓋朝腳尖方向對齊。"],"1876":["調整座椅，將雙臂貼在靠墊內側。","坐直。","雙臂往兩側抬起至約肩膀高度。","在頂點短暫停留。","慢慢下放回到起始位置。"],"1877":["站直，雙腳比髖部寬。","重心移到一腿並彎曲該側膝蓋。","另一腿保持打直，腳掌平貼地面。","將髖部往外推，直到感覺大腿內側受到伸展。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1878":["站直，需要平衡時可站在牆邊。","將一腿交叉踩到另一腿後方。","髖部往後腿那一側推出去。","感受臀部外側的伸展。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1879":["面對長凳或踏階站立。","單腳腳跟放上去，膝蓋微彎。","保持挺胸，從髖部往前折。","感受髖部與臀肌的伸展。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1880":["站在牆邊，單手扶牆。","外側腿交叉踩到內側腿後方。","將髖部往牆壁方向傾。","雙腳保持平貼地面。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1881":["站在支撐物旁，身體站直。","將一腿從另一腿後方穿過去。","將髖部輕輕往後腿那側推。","軀幹保持直立。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1882":["仰躺，雙腿伸直。","單膝抬起並跨過身體。","用對側手輕輕將膝蓋壓向地面。","雙肩保持平貼地面。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1883":["仰躺，小腿放在健身球上。","單腳腳踝跨到對側膝蓋上。","輕輕將球往身體滾，讓雙腿靠近胸口。","感受臀部外側的伸展。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1884":["仰躺在長凳上。","單腿跨過身體，讓腿垂出長凳側邊。","雙肩保持平貼。","讓地心引力帶著腿慢慢往下沉。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1885":["面對牆壁站立，一腳往前踩。","前腳掌抵住牆面，腳跟貼地。","將髖部往牆壁方向傾。","感受小腿與阿基里斯腱的伸展。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1886":["站在台階上，單腳前腳掌踩在台階邊緣。","扶著欄杆維持平衡。","將腳跟慢慢往下壓到低於台階平面。","膝蓋打直可伸展腓腸肌，微彎則針對比目魚肌。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1887":["面對牆壁站立，一腳往後退一步。","後腿保持打直，腳跟踩地。","前膝彎曲，身體往前傾。","感受後腿小腿的伸展。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1888":["站在牆壁或支撐物旁。","一腳往後退一步，腳跟踩地。","後膝微彎，集中伸展阿基里斯腱下段。","後腳尖保持朝前。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1889":["坐在地板上，單腿伸直。","將毛巾繞在前腳掌上，或直接用手抓住腳趾。","將腳趾往脛骨方向拉。","膝蓋保持打直。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1890":["蹲低，雙手扶地維持平衡。","單腿往後伸，腳跟往下踩。","將腳跟壓向地面。","保持挺胸。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1891":["跪在墊子上，腳趾往前踩地。","臀部慢慢往後坐到腳跟上。","雙手放在大腿上。","如果拉扯感太強烈就稍微退回來。","停留 20 到 30 秒，慢慢呼吸。","放開並動一動雙腳放鬆。"],"1892":["單膝跪地，另一腳踩在前方。","前腳跟保持貼地，身體往前傾。","將前膝往超過腳尖的方向推。","感受腳踝後側的伸展。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1893":["雙腳與肩同寬站立。","腳跟貼地，往下坐進深蹲。","需要時可抓住支撐物。","將重心輕輕往前移到腳尖上方。","停留 20 到 30 秒，慢慢呼吸。","慢慢站起來。"],"1894":["雙腳寬站，腳尖微微朝外。","彎曲膝蓋，雙手放在大腿上。","重心左右移動，往下沉進伸展。","保持挺胸、背部平坦。","每邊停留 20 到 30 秒。"],"1895":["站在支撐物旁，身體站直。","單腳腳踝跨到對側膝蓋上。","像要坐椅子一樣將髖部往後坐。","感受跨上去那條腿的髖部伸展。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1896":["站直，將單腳放到側邊的長凳或高台上。","支撐腿保持打直，腳尖朝前。","重心移向抬高的那條腿，直到感覺到伸展。","保持挺胸，髖部擺正。","停留 20 到 30 秒，接著換腳。"],"1897":["站在長凳或矮支撐物旁。","單腿往側邊伸，將腳放在支撐物上。","髖部保持朝前擺正。","將重心移向抬高的那條腿。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1898":["採四足跪姿，膝蓋在髖部正下方。","單腿往側邊伸直，腳掌平貼地面。","將髖部往後坐向對側腳跟。","背部與側伸腿都保持打直。","停留 20 到 30 秒，接著換腳。"],"1899":["雙腳寬站。","重心移向一側並彎曲該膝。","另一腿保持打直，腳掌平貼地面。","保持挺胸。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1900":["雙腳寬站。","彎曲單側膝蓋，身體往該側下沉。","另一腿保持打直。","用手將彎曲的膝蓋輕輕往外推。","停留 20 到 30 秒，慢慢呼吸。","換邊重複。"],"1901":["跪在墊子上，將胸口與前臂放低到地面。","雙膝往兩側滑開，髖部往後沉向腳跟，直到感覺大腿內側受到伸展。","呼吸放慢並保持放鬆，不要彈震。","停留 20 到 30 秒，維持溫和拉扯感而非疼痛。","慢慢收回並重複，如果是單邊伸展就換邊。"],"1902":["坐在地板上，雙腿盡量往兩側打開。","膝蓋保持朝上。","脊椎延伸，從髖部往前傾。","雙手往前走，直到感覺到伸展。","停留 20 到 30 秒，慢慢呼吸。","慢慢起身收回。"],"1903":["坐在地上，一腿在身前彎曲。","另一腿放到側邊。","上身往前方小腿前傾。","保持髖部貼穩地面。","停留 20-30 秒，慢慢呼吸。","換邊重複。"],"1904":["雙腳寬站，腳尖微向外。","重心移向一側並彎曲該側膝蓋，另一腿伸直，感受大腿內側的伸展。","挺胸，伸直那腿的腳掌平貼地面。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1905":["仰躺在地上，髖部靠近牆面。","雙腿伸直靠在牆上。","讓雙腿慢慢向兩側自然打開。","放鬆身體，交給地心引力帶動。","停留 20-30 秒，慢慢呼吸。","雙腿併攏完成動作。"],"1906":["仰躺在地上，雙腿伸直。","彎曲一側膝蓋，讓腿向側邊落下，需要時可用手輕推，直到大腿內側有伸展感。","保持下背與對側髖部平貼地面。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1907":["仰躺在地上，雙腿伸直。","請夥伴將你的一腿稍微抬起，並往側邊移開。","保持髖部水平。","在覺得舒適的伸展幅度時請夥伴停住。","停留 20-30 秒，慢慢呼吸。","換邊重複。"],"1908":["站姿，一腳腳跟在身前點地。","腳尖往下壓。","背部打直，從髖部往前傾。","前腿保持接近伸直。","停留 20-30 秒，慢慢呼吸。","換邊重複。"],"1909":["站直，一腳往前跨步，腳跟貼地、腳尖往回勾。","前腿伸直，後膝微彎。","背部打直從髖部前傾，直到感覺大腿後側被拉開。","胸口打開，避免拱背。","停留 20-30 秒，接著換邊。"],"1910":["面向低支撐物站立，一腳腳跟放上去並伸直腿。","背部拉長從髖部前傾，直到感覺大腿後側伸展。","腳尖朝上，支撐腿膝蓋微彎不鎖死。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1911":["將一腳腳跟放在身前的低長凳或台階上，腿伸直。","身體站直，支撐腿膝蓋微彎。","背部打直從髖部前傾，直到抬起的大腿後側有伸展感。","腳尖朝上，慢慢呼吸。","停留 20-30 秒，接著換邊。"],"1912":["站直，將一腳腳跟放在較高的支撐物上，膝蓋微彎。","背部打直，胸口朝大腿前傾，直到感覺大腿後側伸展。","身體放鬆後，可將膝蓋再稍微伸直一點。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1913":["單膝跪地，另一腿往身前伸直，腳跟貼地、腳尖往回勾。","雙手撐地或放在前側大腿上支撐。","背部打直從髖部前傾，直到伸直那腿的後側有拉扯感。","前腿膝蓋伸直但不鎖死。","停留 20-30 秒，接著換邊。"],"1914":["坐在地上，雙腿大步打開，膝蓋伸直。","坐直，腳尖朝上。","從髖部前傾，雙手在身前慢慢往前走。","感覺大腿內側與雙腿後側有伸展感時停住。","停留 20-30 秒並慢慢呼吸，接著坐回原位。"],"1915":["坐在地上，一腿在身前伸直。","背部拉長，雙手朝腳尖延伸，直到感覺大腿後側伸展。","膝蓋伸直但不鎖死，避免背部過度彎曲。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1916":["雙腳與髖部同寬站立。","從髖部前傾，雙手朝小腿或腳尖往下伸，直到感覺大腿後側伸展。","頭頸自然垂放放鬆，膝蓋保持微彎。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1917":["站直，一腳跨到另一腳前側交叉。","從髖部前傾，雙手朝地面延伸，直到大腿後側有伸展感。","雙腿保持大致伸直，頭部自然垂放放鬆。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1918":["在地上或椅子上坐直，將一腳腳踝跨在對側膝蓋上。","輕壓抬起的膝蓋，背部拉長、胸口往前傾，直到臀部有伸展感。","保持脊椎延伸，不要往前駝背塌陷。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1919":["坐在地上，一腿在身前彎曲，另一腿在身後彎曲。","胸口往前方小腿上方前傾，直到感覺髖部與臀部深處伸展。","兩側坐骨盡量保持水平。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1920":["坐在椅子或地上，一腿伸直。","在舒適範圍內將腳尖盡量往前壓。","用手輕壓腳背，加深一點點伸展感。","動作放慢，避免強壓腳踝。","停留 20-30 秒，接著換邊。"],"1921":["仰躺在地上，雙腿伸直。","將一腿朝天花板抬起，雙手扶住大腿後側或小腿。","膝蓋在舒適範圍內盡量伸直，另一腿平貼地面。","將腿輕輕拉向身體，直到大腿後側有拉扯感。","停留 20-30 秒，接著換邊。"],"1922":["仰躺，將毛巾繞過一腳的前腳掌。","雙手握住毛巾兩端，將該腿朝天花板抬起。","膝蓋保持接近伸直，另一腿平貼地面。","輕拉毛巾，直到感覺大腿後側伸展。","停留 20-30 秒，接著換邊。"],"1923":["仰躺在地上，雙腿伸直並完全放鬆。","請夥伴托住一腳腳跟將腿抬起，膝蓋保持伸直。","感覺大腿後側有拉扯感時，請夥伴停住。","另一腿與下背保持平貼地面。","停留 20-30 秒，接著換腿。"],"1924":["面向牆面或台階站立，將一腳前腳掌抵在上面，腳跟貼地。","保持該腿伸直。","髖部輕輕朝牆面靠近，直到感覺小腿伸展。","腳跟不離地，背部打直。","停留 20-30 秒，接著換邊。"],"1925":["站在台階邊緣，一腳前腳掌踩在台階上，手扶欄杆維持平衡。","將該腳腳跟慢慢往台階下方下放，直到感覺小腿伸展。","膝蓋伸直可伸展小腿表層，微彎膝蓋則能伸展更深層的比目魚肌。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1926":["坐姿，一腿伸直，用手握住腳掌。","腳尖往下壓，並將腳底稍微向外翻。","輕壓腳掌，直到腳踝前側與外側有伸展感。","動作放慢，在溫和伸展處停住。","停留 20-30 秒，接著換邊。"],"1927":["坐姿，一腿伸直，用手握住腳掌。","腳尖往下壓，並將腳底稍微向內翻。","輕壓腳掌，直到腳踝前側與內側有伸展感。","動作放慢，在溫和伸展處停住。","停留 20-30 秒，接著換邊。"],"1928":["面向肋木架站立，將一腳前段抵在低橫桿上。","身體前傾並將腳跟往地面壓，直到小腿有伸展感。","雙手握住橫桿保持平衡。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1929":["面向牆面站立，一腳往後退，腳趾抵住牆面或地面。","伸展側的膝蓋微彎。","重心往前移，直到小腿下段有伸展感。","保持腳跟貼地。","停留 20-30 秒，接著換邊。"],"1930":["蹲下，雙腳平踩，雙手撐地維持平衡。","將一腳往後移，腳跟朝地面下壓。","另一腿保持彎曲支撐體重。","感受下壓腿的小腿伸展。","停留 20-30 秒，接著換邊。"],"1931":["雙腳比肩略寬站立，腳尖微向外。","往下深蹲，用手肘抵住膝蓋內側，將髖部推開。","雙腳腳跟貼地，挺胸拉高上身。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1932":["仰躺在地上，雙腿伸直並放鬆。","請夥伴將你的一側膝蓋慢慢推向胸口。","感覺髖部與臀部有伸展感時，請對方停住。","另一腿保持平貼地面。","停留 20-30 秒，接著換腿。"],"1933":["坐在地上，一腿伸直，另一膝彎曲、腳掌平踩地面。","彎曲腿跨過直腿，上身朝立起的膝蓋方向旋轉，並用對側手臂抱住膝蓋。","坐直，從中背帶動扭轉。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1934":["坐在地上，一腿伸直，另一膝彎曲跨過直腿。","上身朝彎曲膝蓋方向旋轉，用對側手肘抵住膝蓋輔助，直到髖部有伸展感。","保持脊椎延伸，視線看往後側肩膀。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1935":["仰躺在地上，雙膝彎曲。","將一腳腳踝跨在對側膝蓋上。","雙手抱住下方腿的膝蓋或大腿後側，往胸口方向拉近。","頭與肩膀放鬆貼在地面。","停留 20-30 秒，接著換邊。"],"1936":["仰躺在地上，雙膝彎曲。","將一腳腳踝跨在對側膝蓋上。","用手將交叉的膝蓋輕輕往身體對側下方壓。","雙肩保持貼地。","停留 20-30 秒，接著換邊。"],"1937":["坐在地上，雙腿往身前伸出。","彎曲一側膝蓋，雙手抱住並輕輕拉向胸口。","拉近時保持背部挺直，避免拱背。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1938":["坐在地上，一腿在身前微彎，另一腿舒適地收折。","背部拉長從髖部前傾，直到感覺髖部與臀部伸展。","前腿膝蓋全程保持微彎放鬆。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1939":["仰躺在地上，雙膝彎曲。","將一側膝蓋拉向胸口，並稍微向外側轉開。","雙手握住小腿與腳踝，將腿拉得更靠近身體。","下背保持平貼地面。","停留 20-30 秒，接著換邊。"],"1940":["坐在地上，背部挺直，雙腿伸直。","彎曲一側膝蓋，雙手握住腳掌與小腿。","脊椎保持直立，將腳輕輕拉向胸口。","感受臀部與髖部深處的伸展。","停留 20-30 秒，接著換邊。"],"1941":["站直，一腿交叉到另一腿後方，雙腳靠攏。","上身往後腳的反方向側傾，並將髖部稍微往外推，直到感覺髖部外側伸展。","雙腳腳掌保持平貼地面。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1942":["站在牆面或支撐物旁，外側腿交叉到內側腿後方。","髖部朝牆面推過去，外側手臂舉過頭延伸，直到髖部與大腿外側有伸展感。","胸口保持朝前。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1943":["四足跪姿開始，將一側膝蓋往前滑到同側手腕後方。","另一腿往身後伸直。","髖部朝地面下沉，保持挺胸。","如果覺得舒適，可將上身往前趴在前腿上以加深伸展。","停留 20-30 秒，接著換邊。"],"1944":["仰躺在地上，雙膝彎曲。","將一腳腳踝跨在對側膝蓋上，把下方大腿拉向胸口，直到臀部有伸展感。","頭與肩膀放鬆貼在地面。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1946":["站直，手扶牆面或支撐物維持平衡。","抬起一側膝蓋，雙手握住小腿與腳踝。","將腿輕輕拉向胸口，並稍微往對側帶。","支撐腿膝蓋微彎，背部保持挺直。","停留 20-30 秒，接著換邊。"],"1947":["站在牆邊，一腿交叉到另一腿後方。","將髖部往側邊推向牆面。","上半身往髖部的反方向側傾，直到感覺髖部外側伸展。","雙腳保持平貼地面。","停留 20-30 秒，接著換邊。"],"1948":["坐在地上，雙膝彎曲，雙腳平踩。","讓雙膝倒向同一側，上身朝反方向旋轉，直到感覺髖部伸展。","雙手撐在身後輔助支撐。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1949":["站姿，一腳往前、一腳往後跨成前後分腿站姿。","骨盆後傾收緊，並夾緊後腿臀肌。","髖部稍微往前推，直到後腿髖部前側有伸展感。","保持上身直立。","停留 20-30 秒，接著換邊。"],"1951":["坐在地上，一腿彎曲讓腳掌貼在對側大腿內側。","胸口朝彎曲腿上方前傾，同時將該側膝蓋往地面輕壓，直到髖部有伸展感。","保持背部延伸拉長。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1952":["仰躺在地上並放鬆。","請夥伴托住你的一腿，並輕輕將腿伸展。","讓夥伴只帶到有溫和伸展感的幅度即可。","保持下背平貼地面。","停留 20-30 秒，接著換腿。"],"1953":["站直，手扶牆面或椅子維持平衡。","彎曲一側膝蓋，在身後握住腳踝。","將腳跟拉向臀肌，並把髖部稍微往前推。","雙膝保持靠攏。","停留 20-30 秒，接著換邊。"],"1954":["背對箱子或長凳站立，將一腳腳背放到身後的箱面或凳面上。","前腿站直，膝蓋微彎不鎖死。","骨盆後傾收緊並稍微下沉髖部，直到大腿前側有伸展感。","需要時可手扶支撐物維持平衡。","停留 20-30 秒，接著換邊。"],"1955":["雙膝跪地，接著將一腳踩到身前，讓另一腿保持折曲。","雙手撐在身後地面。","身體慢慢往後仰，直到折曲那腿的大腿前側有伸展感。","髖部保持挺起，避免下背塌陷。","停留 20-30 秒，接著換邊。"],"1956":["跪姿往後坐，讓髖部落在腳跟上。","雙手撐在身後地面。","身體慢慢後仰並稍微抬起髖部，直到雙腿大腿前側有伸展感。","若膝蓋感覺任何擠壓不適請立即停止。","停留 20-30 秒，接著慢慢回到原位。"],"1957":["站直，手扶牆面維持平衡。","將一腳放到身後，腳趾往下捲、腳背貼地。","微彎支撐腿的膝蓋，將後腳背輕輕往下壓。","感受小腿前側與腳踝前側的伸展。","停留 20-30 秒，接著換邊。"],"1958":["站在支撐物旁，將一腳放到身後，腳趾往下捲、腳背貼地。","微彎支撐腿膝蓋並輕壓後腳趾，直到腳背與小腿前側有伸展感。","力道保持輕柔且受控。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1959":["站在牆邊，將一腳往後抬到低支撐物上，腳背朝下。","保持上身直立，支撐腿膝蓋微彎。","將髖部輕輕往前推，直到小腿前側有伸展感。","動作保持緩慢且受控。","停留 20-30 秒，接著換邊。"],"1960":["跪在墊子上，腳尖朝正後方、腳背平貼地面。","慢慢往腳跟方向坐下去，直到小腿前側與腳踝有伸展感。","雙手放在身前地面以控制下壓力量。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1961":["蹲下，腳跟抬起、腳趾踩地折起。","雙手撐在身前地面輔助支撐。","臀部慢慢往腳跟方向坐，直到腳趾與腳底有伸展感。","如果拉扯感太強烈，請稍微減輕力道。","停留 20-30 秒，接著放鬆。"],"1962":["坐下，將一腳腳踝跨在對側膝蓋上。","用手握住腳背與腳趾。","將腳趾與腳掌輕輕往下捲，直到腳背有伸展感。","動作保持輕柔。","停留 20-30 秒，接著換邊。"],"1963":["坐下，將一腳腳踝跨在對側膝蓋上。","用手握住腳背與腳趾。","將腳趾往下捲，並把腳底輕輕向外翻。","感受腳背與腳掌外側邊緣的伸展。","停留 20-30 秒，接著換邊。"],"1964":["坐下，將一腳腳踝跨在對側膝蓋上。","用手握住腳背與腳趾。","將腳趾往下捲，並把腳底輕輕向內翻。","感受腳背與腳掌內側邊緣的伸展。","停留 20-30 秒，接著換邊。"],"1965":["坐下，將一腳腳踝跨在對側膝蓋上。","用手握住腳趾。","將腳趾輕輕朝小腿方向往回拉。","感受腳底的伸展。","停留 20-30 秒，接著換邊。"],"1966":["坐下，將一腳腳踝跨在對側膝蓋上。","用手握住腳趾。","將腳趾朝小腿方向往回拉，並把腳底輕輕向外翻。","感受腳底與腳掌內側邊緣的伸展。","停留 20-30 秒，接著換邊。"],"1967":["坐下，將一腳腳踝跨在對側膝蓋上。","用手握住腳趾。","將腳趾朝小腿方向往回拉，並把腳底輕輕向內翻。","感受腳底與腳掌外側邊緣的伸展。","停留 20-30 秒，接著換邊。"],"1968":["面向牆面站立，將一腳腳趾抵在牆上，腳跟貼地。","身體輕輕前傾，直到感覺腳底一路延伸到小腿的伸展。","腳跟穩穩貼在地面。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1969":["面向牆面站立，一腳在前，腳尖離牆幾吋。","前腳腳跟保持貼地。","彎曲前膝，讓膝蓋朝牆面方向推進。","回到原位並慢慢重複 10-15 次，接著換腳。"],"1970":["雙腳與髖部同寬站直。","雙手在背後交扣。","手臂伸直，輕輕將手往遠離身體的方向抬起。","胸口打開，頸部放鬆。","停留 20-30 秒。"],"1971":["站直，雙手在背後交扣。","手臂伸直，將雙手往遠離身體的上方抬起，直到肩膀與胸口有伸展感。","保持胸口打開，避免身體前傾。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1972":["坐在長凳邊緣，雙手放在身後的凳面上，手指朝後。","將髖部稍微往前移出長凳。","髖部輕輕往下沉，直到肩膀前側有伸展感。","背部靠近長凳，肩膀下沉不聳肩。","停留 20-30 秒，接著起身。"],"1973":["坐直，雙臂放到身後，掌心朝下。","請夥伴站在身後，握住你的手腕或前臂。","請對方將你的手臂慢慢往上抬，直到感覺伸展。","肩膀放鬆，胸口打開。","停留 20-30 秒，接著慢慢放下。"],"1974":["站直，雙手在背後交扣。","手臂伸直，將兩側肩胛骨往中間夾。","雙手稍微往遠離身體的方向抬起。","保持挺胸，避免下背過度拱起。","停留 20-30 秒，接著放鬆。"],"1975":["在椅子或長凳上坐直。","雙手放在身後的椅面上，手指朝後。","肩膀往下往後壓，把胸口打開。","身體稍微往前傾，直到感覺伸展。","停留 20-30 秒，接著放鬆。"],"1976":["站在牆面或柱子旁，單手伸直扶在身後的牆或柱上。","身體慢慢轉離手扶側，直到感覺肩膀前側伸展。","手臂保持伸直，肩膀放鬆。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1977":["站直或坐直。","將一隻手臂放到背後。","用另一手握住該側手腕，輕輕往身體對側拉過去。","保持雙肩水平。","停留 20-30 秒，接著換邊。"],"1978":["站直，將一隻手臂往身後伸。","另一手跨過去握住該手臂。","將手臂輕輕往後並往身體對側拉。","胸口打開，肩膀下沉。","停留 20-30 秒，接著換邊。"],"1979":["站直或坐直，將一隻手臂橫跨胸前。","用對側手將該手臂往身體方向壓，直到肩膀與上背有伸展感。","肩膀下沉遠離耳朵。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1980":["站直，將一隻手臂打直橫跨胸前。","用另一隻前臂將該手臂輕輕往身體方向壓。","肩膀保持放鬆下沉。","感受肩膀後側的伸展。","停留 20-30 秒，接著換邊。"],"1981":["站直，將一隻手臂彎曲手肘並橫跨胸前。","用另一手扶住該手肘。","將手肘輕輕拉向對側肩膀。","雙肩保持水平，頸部放鬆。","停留 20-30 秒，接著換邊。"],"1982":["站直，一側手肘在身側彎曲呈 90 度。","用另一手輔助，將前臂慢慢向外或向內旋轉，直到感覺肩膀伸展。","手肘保持貼近身體側邊。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1983":["雙腳與髖部同寬站直。","單手或雙手舉過頭盡量往上延伸，接著稍微往後壓。","往上延伸時不要拱起下背。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1984":["站直，將一隻手臂在胸口高度橫跨身體。","另一手扶在手肘上方，將手臂往內拉，直到肩膀後側有伸展感。","保持肩胛骨下沉放鬆。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1985":["站直，單手放在頭後，手肘往側邊抬起。","用另一手扶住抬起的手肘。","將手肘輕輕往後並稍微往下壓。","感受肩膀的伸展。","停留 20-30 秒，接著換邊。"],"1986":["將一隻手臂舉過頭並彎曲手肘，掌心貼在上背。","用另一手扶住該手肘。","將手肘輕輕往後並往下壓。","肋骨收穩，胸口保持打開。","停留 20-30 秒，接著換邊。"],"1987":["站直，將一隻手臂放到背後並彎曲手肘。","用另一手握住該手腕。","將手輕輕往遠離身體的方向拉，並稍微往上帶。","保持肩膀放鬆。","停留 20-30 秒，接著換邊。"],"1988":["跪在墊子上，將一隻手臂掌心朝下，在身前貼地往對側滑出。","胸口朝地面下沉並持續延伸手臂，直到肩膀與上背有伸展感。","髖部保持在膝蓋正上方。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1989":["站在雙槓之間，在髖部高度握住橫槓。","雙腳稍微往後走，讓手臂伸直。","胸口朝地面下沉，頭部壓進雙臂之間。","感受背闊肌與肩膀的伸展。","停留 20-30 秒，接著往前走開放鬆。"],"1990":["站在門框旁，手肘彎曲呈 90 度，前臂貼在門框上。","身體慢慢轉離手臂側，直到感覺肩膀前側伸展。","手肘保持與肩膀同高。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1991":["站直，將單手手肘彎曲放到下背後方。","用另一手或毛巾輔助，將背後的掌心沿著背部輕輕往上拉，直到肩膀後側有伸展感。","保持雙肩水平，身體不要扭轉。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"1992":["雙肩抵住肩墊，雙腳與肩同寬踩在踏板上。","解開安全扣並伸直雙腿。","將髖部慢慢往下放，直到大腿低於平行位置。","背部平貼背墊，膝蓋朝腳尖方向移動。","全腳掌發力踩踏站回起始位置。"],"2071":["上背靠在長凳上，一腳平踩地面。","另一腿伸直或抬起懸空。","腳跟發力將髖部往上推，直到身體呈一直線。","在頂點夾緊臀肌，接著受控下放。","完成目標次數後換腿。"],"2072":["坐在地上，上背靠住長凳，雙膝彎曲。","雙腳平踩地面，與髖部同寬。","腳跟發力將髖部往上推，直到軀幹呈水平。","在頂點夾緊臀肌。","慢慢下放並重複。"],"2087":["站直，將一隻手臂橫跨胸前。","另一手扶在該手臂的手肘上方。","輕輕往內拉，同時將上背稍微往前拱。","保持頸部放鬆。","停留 20-30 秒，接著換邊。"],"2088":["單手握住毛巾，將該手臂舉過頭並彎曲手肘。","另一手從背後往上伸，抓住毛巾下段。","用下方的手將毛巾輕輕往下拉。","保持頭部直立。","停留 20-30 秒，接著換邊。"],"2089":["將一隻手臂往身前伸出，手肘伸直。","用另一手將手指輕輕往回扳，直到手掌與前臂有伸展感。","手指保持伸直並放鬆。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"2090":["站直或坐直，雙手手指交扣。","掌心向外翻，雙臂在身前伸直。","雙手輕輕往前推遠，直到感覺前臂伸展。","保持肩膀放鬆。","停留 20-30 秒，接著放鬆。"],"2091":["將一隻手臂往身前伸出，掌心朝下。","彎曲手腕，讓手指朝向地面。","用另一手將手背輕輕往身體方向壓。","手肘保持伸直。","停留 20-30 秒，接著換邊。"],"2092":["面向牆面站立，將單手掌心貼在牆上，手指朝下。","保持手臂伸直。","身體慢慢轉離手扶側，直到感覺前臂伸展。","手指保持平貼牆面。","停留 20-30 秒，接著換邊。"],"2093":["坐直，一隻手臂往前伸出，掌心朝上。","用另一手將手腕往回扳，並朝拇指側傾斜，直到前臂有伸展感。","手肘保持伸直。","停留 20-30 秒，感受溫和拉扯而非疼痛。","慢慢放鬆並重複，單側動作請換邊。"],"2094":["伸出一隻手臂，掌心朝上。","用另一手握住該手拇指。","將拇指輕輕往後並往遠離手掌的方向拉。","在溫和伸展處停住。","停留 20-30 秒，接著換邊。"],"2095":["將一隻手臂往身前伸出，掌心朝上。","用另一手握住手指。","將手指輕輕朝自己方向往回扳。","手肘保持伸直，手腕放鬆。","停留 20-30 秒，接著換邊。"],"2096":["將一隻手臂往身前伸出，掌心朝下。","用另一手將伸出那手的手指輕輕往下壓。","伸出那側的手肘保持伸直，雙肩放鬆。","有溫和拉扯感就停住，切勿壓到疼痛。","停留 20-30 秒。","放鬆並換手重複。"],"2097":["將一隻手舉在身前，掌心朝向自己。","在舒服的範圍內，盡量將手指張開。","如果想加強伸展，可以用另一隻手壓進指縫。","手腕保持打直，肩膀放鬆。","維持 20 到 30 秒。","放鬆手掌，換邊進行。"],"2098":["身體站直，一隻手臂往前伸出，手肘保持打直。","轉動手掌，讓拇指朝上。","用另一隻手抓住該手，輕輕往小指方向傾斜。","手肘維持鎖直，肩膀下沉。","維持 20 到 30 秒。","放鬆，換另一隻手重複。"],"2099":["仰臥，雙膝彎曲，雙腳平放地面。","將一腳腳踝跨在對側膝蓋上，再將雙腿拉向胸口，直到臀部有伸展感。","頭與肩膀放鬆貼在地面上。","維持 20 到 30 秒，感受溫和的拉伸而非疼痛。","慢慢放開並重複，單側動作請換邊進行。"],"2100":["側坐在長凳或穩固的椅子上，讓一隻腳懸在側邊。","彎曲懸空那側的膝蓋，將腳跟往臀肌方向收。","用手抓住腳掌或腳踝，輕輕將腳跟拉近。","軀幹保持直立，雙膝盡量靠攏。","維持 20 到 30 秒。","放開並換腿。"],"2101":["身體站直，將一腿交叉跨到另一腿前方。","後腳腳趾尖頂住地面，輕輕彎曲膝蓋，直到小腿前側與腳踝有伸展感。","手扶牆面或椅子保持平衡。","維持 20 到 30 秒，感受溫和的拉伸而非疼痛。","慢慢放開並重複，單側動作請換邊進行。"],"2102":["坐在地上，一腿在身前伸直。","身體往前伸，抓住該腿的腳趾或前腳掌。","膝蓋保持打直，輕輕將腳趾往脛骨方向拉。","坐直身體，避免拱背。","維持 20 到 30 秒。","放開並換腿。"],"2103":["舒服坐好，將一隻腳抬起放在對側膝蓋上。","用手扶住腳掌。","將手指穿入腳趾縫，輕輕把腳趾撐開。","動作保持緩慢輕鬆。","維持撐開 15 到 20 秒。","放開並換腳。"],"2104":["面向牆壁站立，雙手貼牆放在約胸口高度。","一腳往後退一步，腳跟保持踩在地面。","雙膝微微彎曲，身體前傾，直到後腳小腿下段有拉緊感。","後腳跟平貼地面，腳尖朝前。","維持 20 到 30 秒。","換腿進行。"],"2105":["俯臥，雙手放在肩膀下方。","雙手推地撐起上半身，讓髖部下沉貼近地面，直到下腹部有伸展感。","髖部貼在地面，肩膀放鬆。","維持 20 到 30 秒，感受溫和的拉伸而非疼痛。","慢慢放開並重複，單側動作請換邊進行。"],"2106":["採四足跪姿，雙手在肩膀正下方，雙膝在髖部正下方。","下巴微收，骨盆後傾，同時雙手推地。","像貓一樣將背部往天花板方向拱起。","維持拱背姿勢幾秒鐘。","慢慢回到中立的起始位置。","緩慢重複 8 到 10 次。"],"2107":["採四足跪姿，雙手在肩膀正下方，雙膝在髖部正下方。","吸氣，讓腹部朝地面方向下沉。","抬起胸口與尾骨，視線微微往前看。","雙臂保持打直，肩膀遠離耳朵。","維持幾秒鐘，再回到中立位置。","緩慢重複 8 到 10 次。"],"2108":["身體站直，雙手扶在髖部上。","身體輕輕後仰，髖部微微往前推，直到腹部有伸展感。","動作幅度保持小一點，避免過度擠壓下背。","維持 20 到 30 秒，感受溫和的拉伸而非疼痛。","慢慢放開並重複，單側動作請換邊進行。"],"2109":["雙膝與髖同寬跪立，雙手放在下背。","髖部往前推、身體後仰，直到腹肌有伸展感。","下巴微收，避免頭完全往後仰。","維持 20 到 30 秒，感受溫和的拉伸而非疼痛。","慢慢放開並重複，單側動作請換邊進行。"],"2110":["身體站直，雙腳與髖同寬，雙臂放鬆。","雙手扶在髖部或向兩側平舉。","髖部保持朝前，上半身慢慢轉向一側。","視線越過肩膀看向後方，保持平穩呼吸。","維持 20 到 30 秒。","回到正面，再轉向另一側。"],"2111":["俯臥，用前臂或手掌將上半身撐起。","髖部貼在地面，抬起胸口。","慢慢將頭與肩膀轉向一側。","保持放鬆，避免勉強推到下背疼痛。","維持 20 到 30 秒。","回到中間，再轉向另一側。"],"2112":["仰臥，雙膝彎曲，雙腳平放地面。","雙臂放在身體兩側作為支撐。","腳跟推地，抬起髖部直到身體呈一直線。","在頂點夾緊臀肌，不要過度拱起下背。","有控制地將髖部放回地面。","重複 10 到 12 次。"],"2113":["站立，雙腳略寬於髖部。","一手扶在髖部，另一手高舉過頭。","將髖部微微往高舉手的對側推。","從腰部向側邊彎曲，不要前傾或後仰。","維持 20 到 30 秒。","回到直立姿勢並換邊。"],"2114":["盤腿或雙腳平放，在地面或椅子上坐直。","一手高舉過頭，身體往對側彎曲，直到腰側有伸展感。","兩側髖部保持穩穩貼緊座位，避免前傾。","維持 20 到 30 秒，感受溫和的拉伸而非疼痛。","慢慢放開並重複，單側動作請換邊進行。"],"2115":["在軟墊上跪立，雙膝與髖同寬，大腿保持直立。","雙手放在髖部或骨盆後側。","夾緊臀肌，將髖部往前推。","肋骨下收，避免過度拱起下背。","維持一下，再回到起始位置。","重複 8 到 12 次。"],"2116":["仰臥，雙臂向兩側展開，雙膝彎曲。","雙肩保持平貼地面。","慢慢將雙膝放低倒向一側。","如果覺得舒服，頭可以轉向相反方向。","維持 20 到 30 秒。","將雙膝帶回中間，再倒向另一側。"],"2117":["身體站直，雙腳與髖同寬。","一手高舉過頭，身體往對側彎曲，直到身體側邊有伸展感。","胸口保持打開，髖部維持水平。","維持 20 到 30 秒，感受溫和的拉伸而非疼痛。","慢慢放開並重複，單側動作請換邊進行。"],"2118":["盤腿或雙腳平放地面，坐直身體。","一手高舉過頭，身體往對側側傾，另一手撐地輔助。","兩側坐骨保持穩穩貼地。","維持 20 到 30 秒，感受溫和的拉伸而非疼痛。","慢慢放開並重複，單側動作請換邊進行。"],"2119":["身體站直，雙腳與髖同寬。","一手高舉過頭，掌心朝內。","軀幹往高舉手臂的對側側傾。","兩側髖部保持水平，胸口朝前。","維持 20 到 30 秒。","回到直立姿勢，換另一側重複。"],"2120":["雙腳與肩同寬站立，雙手握住長棍高舉過頭。","雙臂保持打直，肩膀放鬆。","軀幹慢慢向一側傾，不要扭轉身體。","髖部保持穩定，胸口朝前。","維持 20 到 30 秒。","回到直立姿勢，再傾向另一側。"],"2121":["仰臥，雙腿併攏，雙臂高舉過頭伸直。","將雙腳與雙手滑向同一側，讓身體呈現柔和的弧線。","髖部與雙肩保持貼在地面。","緩慢呼吸，放鬆融入這個弧度。","維持 20 到 30 秒。","回到中間，再彎向另一側。"],"2122":["身體站直，雙腳與肩同寬，一隻手高舉過頭。","請夥伴站在你身後，一手扶住你的髖部，另一手扶住你舉起的手臂。","在夥伴輕柔引導下向側邊傾身。","感覺到輕微拉伸時，請夥伴停住。","維持 20 到 30 秒。","回到直立姿勢並換邊。"],"2123":["身體站直，雙腳與肩同寬。","一手高舉過頭，同時由夥伴穩住你的髖部。","往舉起手臂的對側傾身，同時由夥伴輕柔引導你的手臂。","胸口保持打開，避免身體前傾。","維持 20 到 30 秒。","回到直立姿勢並換邊。"],"2124":["跪在瑜珈墊上，一隻手臂沿著地面向側邊延伸。","雙手往一側爬行，同時將髖部往反方向下沉，直到腰側有伸展感。","髖部保持在膝蓋上方。","維持 20 到 30 秒，感受溫和的拉伸而非疼痛。","慢慢放開並重複，單側動作請換邊進行。"],"2125":["仰臥，雙臂高舉過頭延伸。","將雙腳與上半身移向同一側，彎成柔和的香蕉弧線，直到對側身體有伸展感。","雙肩與兩側髖部保持貼在地面。","維持 20 到 30 秒，感受溫和的拉伸而非疼痛。","慢慢放開並重複，單側動作請換邊進行。"],"2127":["站上羅馬椅，前臂靠在護墊上，背部貼緊靠墊。","用雙腳夾穩重物，或在腳踝上配戴負重。","收緊核心，將雙膝或雙腿往胸口方向抬起。","在頂點時將骨盆微微往上捲。","慢慢放下雙腿，避免晃動。","依計畫次數重複。"],"2130":["躺在下斜長凳上，雙腳勾住固定墊。","雙手將槓片或啞鈴抱在胸前。","收縮腹肌，將上半身往上捲起。","在頂點短暫停留，不要拉扯脖子。","有控制地放回原位。","依計畫次數重複。"],"2133":["站直，雙手各握一啞鈴垂於體側（農夫走路 Farmer\'s Walk）。","背部挺直，雙肩後收下沉。","步伐穩定受控向前邁步走，維持軀幹完全直立不晃動。","持續行走至指定距離或時間。","停步並小心將啞鈴放回地面。"],"2135":["俯臥趴在地上。","前臂貼地，手肘正對肩膀下方。","雙腿向後伸直，腳尖點地。","啟動核心將身體撐離地面（肘棒式）。","身體從頭到腳跟保持成一直線。","維持此姿勢至指定時間。","放鬆降回地面。","重複所需次數。"],"2136":["雙腳與肩同寬站立，雙手各握一啞鈴置於肩前，手腕旋轉掌心朝向自己。","核心收緊背打直，將啞鈴向上推舉過頭頂，同時手腕向外旋轉（阿諾推舉 Arnold Press）。","頂端手臂打直時掌心朝前。","慢慢將啞鈴降回肩部，同時手腕旋轉回掌心朝向自己。","重複所需次數。"],"2137":["坐在有靠背的重訓椅上，手持啞鈴於肩前，手肘彎曲，掌心朝向自己。","向上推舉啞鈴，手臂完全伸直，推舉過程中旋轉手腕使掌心轉向正前方。","在最高點稍作停頓，慢慢將啞鈴放回肩部並將手腕轉回原位。","重複所需次數。"],"2138":["調整飛輪車或健身車的座椅高度與把手。","腳掌踏入踏板，拉緊腳套固定。","以舒適踩踏節奏開始熱身踩踏。","維持穩定踏頻，視訓練需求增加阻力。","收緊核心維持軀幹穩定與良好騎姿。","踩踏至指定時間。","逐漸降低阻力與踏頻緩衝，直至完全停止。","下車進行腿部伸展放鬆。"],"2139":["調整手搖自行車（手臂測力計）的座椅高度與把手距離。","坐直，雙腳踩實地面。","雙手握住手柄，雙臂呈 90 度。","以受控的旋轉動作推拉把手開始手搖踩踏。","持續進行至指定時間或圈數。"],"2140":["踏上器材，雙手輕握把手。","雙腿開始以流暢的步行節奏踩動。","身體站直，核心輕微收緊。","選擇能維持平穩呼吸的配速。","依個人體能持續 10 到 30 分鐘。","下器材前的最後 1 分鐘放慢速度。"],"2141":["調整橢圓機的阻力與坡度至預設值。","踩上踏板，雙手握緊活動手柄。","雙腳向下踩踏，同時雙手交替推拉握把。","維持手腳協調交替，模擬自然跑步滑行動作。","全程保持均勻節奏與核心收緊。","持續進行有氧訓練至指定時間。","結束前逐步調低阻力與步頻以緩和心率。"],"2142":["調整機台座椅高度與踏板。","正握抓把手，掌心朝下。","坐直，雙腳踩在腳踏板上。","雙臂伸展於身前，手肘微屈。","收緊三頭肌將把手向下推向大腿。","在底部停頓片刻，慢慢送回。","重複所需次數。"],"2143":["雙腳分開與肩同寬站立，雙手各持一啞鈴。","手臂向兩側平舉與肩同高，掌心朝下。","手臂維持打直，以肩膀為軸心畫圓旋轉，將啞鈴經身前旋轉至頭頂。","持續旋轉回到起始位置。","重複所需次數。"],"2144":["調整滑輪推胸機座椅高度與把手位置。","背靠椅背坐直，雙腳踩實地面。","正握握把於肩部高度。","向前推動把手充分伸展雙臂。","頂峰停頓片刻，慢慢降回把手。","重複所需次數。"],"2146":["坐在器材上，上背靠緊護墊，安全帶繫過髖部。","雙腳平踩踏板，約與髖同寬。","腳跟發力推蹬，將髖部抬起，直到軀幹與大腿呈一直線。","在頂點夾緊臀肌停留一下。","下巴微收，有控制地放低身體並重複。"],"2147":["坐在器材上，上背靠緊護墊，將彈力帶套在膝蓋上方的大腿處。","雙腳平踩，雙膝輕輕往外推開彈力帶。","腳跟發力推蹬，將髖部抬起，直到軀幹與大腿呈一直線。","在頂點夾緊臀肌。","雙膝保持往外撐，慢慢放低身體並重複。"],"2148":["坐在器材上，上背靠緊護墊，安全帶繫過髖部。","一腳平踩，另一腿抬離地面。","踩地腳跟發力推蹬，將髖部抬起直到軀幹呈水平。","在頂點夾緊臀肌，兩側髖部保持水平。","有控制地放低，完成設定次數後換腿。"],"2149":["將彈力帶固定在低處，一端套在一隻腳上，接著採四足跪姿。","背部保持平坦，收緊核心。","膝蓋保持彎曲，將套著彈力帶的腳往天花板方向推。","在頂點夾緊臀肌，不要拱起下背。","慢慢放下，完成設定次數後換腿。"],"2150":["將環狀彈力帶套在膝蓋正上方，側躺並彎曲雙膝。","兩側髖部上下疊齊，雙腳併攏。","像蚌殼打開一樣，將上方膝蓋往外打開遠離下方膝蓋。","骨盆保持穩定，身體不要往後翻。","慢慢將膝蓋放回。","完成設定次數後換邊。"],"2151":["將彈力帶固定在手肘高度，側身站立面對固定點。","用離固定點較遠的那隻手握住把手。","手肘彎曲成 90 度，貼在身體側邊。","前臂往外旋轉，遠離腹部。","慢慢回到起始位置。","完成設定次數後換手。"],"2152":["將彈力帶套在雙腳或腳踝上，進入前臂棒式或高棒式。","收緊核心，讓身體呈一直線。","髖部不歪斜，將一腿對抗彈力帶往後上方踢。","有控制地將腿收回。","雙腿交替進行，全程保持髖部水平。"],"2153":["雙腳與肩同寬踩住彈力帶，雙手在肩膀高度握住把手。","挺胸，收緊核心。","髖部往後往下坐，進入全深蹲。","膝蓋朝腳尖方向對齊，腳跟踩穩地面。","雙腳推地站直身體。"],"2154":["仰臥，雙膝彎曲，將彈力帶套在膝蓋正上方的大腿處。","雙腳平放地面，與髖同寬。","雙膝輕輕往外推開彈力帶。","腳跟推地，抬起髖部直到身體呈一直線。","夾緊臀肌，再慢慢放下並重複。"],"2155":["將彈力帶套在大腿上，側躺並彎曲雙膝。","手肘放在肩膀正下方。","抬起髖部，讓膝蓋到頭部呈一直線。","上方膝蓋輕輕往外推開彈力帶。","維持 20 到 30 秒，再換邊進行。"],"2157":["將彈力帶套在大腿或腳踝上，側躺並將雙腿伸直。","頭靠在手臂上，兩側髖部上下疊齊。","對抗彈力帶將上方腿抬起，身體不要往後翻。","在頂點短暫停留。","慢慢放下，完成設定次數後換邊。"],"2158":["仰臥，大腿套上彈力帶，一膝彎曲、腳掌平踩。","另一腿伸直，與支撐側大腿維持同高。","踩地腳跟發力推蹬，抬起髖部。","兩側髖部保持水平，在頂點夾緊臀肌。","慢慢放下，完成設定次數後換腿。"],"2159":["仰臥，將環狀彈力帶套在膝蓋上方，雙膝彎曲。","一隻腳抬離地面並將腿伸直。","另一腳跟推地，抬起髖部。","在頂點夾緊臀肌，並保持髖部水平。","有控制地放低身體。","完成設定次數後換腿。"],"2161":["將彈力帶套在雙腳踝上，或將彈力帶固定後套在一隻腳上。","手扶支撐物站立，或採四足跪姿，並收緊核心。","膝蓋保持打直，將一腿對抗彈力帶往後踢。","夾緊臀肌，避免拱起下背。","慢慢收回，完成設定次數後換腿。"],"2162":["將環狀彈力帶套在大腿或腳踝上，進入前臂棒式或高棒式。","從頭到腳跟維持一直線。","對抗彈力帶將一側膝蓋往胸口方向抬起。","輕輕放回，再抬起另一側膝蓋。","保持髖部穩定，不要左右晃動。","依計畫時間或次數交替進行。"],"2163":["俯臥在長凳或跳箱上，將彈力帶固定在靠近雙腳的位置。","雙手抓穩長凳邊緣，將彈力帶套在腳踝上。","夾緊臀肌，抬起雙腿直到與身體呈一直線。","避免甩動或過度拱起下背。","慢慢放下雙腿。","依計畫次數重複。"],"2164":["將彈力帶套在大腿上，側躺並將雙腿伸直。","手肘放在肩膀正下方。","抬起髖部，讓頭到腳呈一直線。","上方腿輕輕往上推開彈力帶。","維持 20 到 30 秒，再換邊進行。"],"2165":["將彈力帶套在大腿或腳踝上，雙腳與髖同寬站立。","雙膝微彎，呈四分之一深蹲姿勢。","前導腳往側邊跨出一步，維持彈力帶張力。","後腳跟上收回，但雙腳不要碰在一起。","往同一方向走 10 到 15 步，再往反方向走回來。"],"2166":["仰臥，將彈力帶套在大腿上，雙膝彎曲。","抬起髖部進入臀橋姿勢，夾緊臀肌。","一腳抬離地面，將膝蓋往胸口方向收。","放回地面後抬起另一腳，全程保持髖部水平。","以穩定節奏持續交替，最後放下髖部。"],"2186":["躺在下斜長凳上，頭低腳高，雙腳固定。","正握抓住 EZ 槓，雙手與肩同寬。","雙臂完全伸展，手肘貼近頭部。","手肘彎曲將槓鈴慢慢放低至額頭上方。","停頓片刻，手臂伸展推回起始位置。","重複所需次數。"],"2187":["平躺在平凳上，雙腳踩實，背部緊貼椅面。","反握抓住槓鈴，握距與肩同寬。","起槓將槓鈴垂直推在胸口正上方。","慢慢將槓鈴降向胸部，手肘貼近身體。","槓鈴接近胸部時停頓片刻。","發力推回起始位置，雙臂伸展。","重複所需次數。"],"2188":["坐在重訓椅上，背部打直，雙腳踩實。","雙手合握一個啞鈴，高舉過頭頂。","手肘彎曲將啞鈴放低至後頸，上手臂貼近耳側。","停頓片刻，手臂伸展推回原位。","重複所需次數。"],"2189":["坐在重訓椅上，背部挺直，雙腳平踩。","雙手正握啞鈴高舉過頭。","手肘彎曲將啞鈴放至腦後，上手臂固定貼近耳側。","三頭肌發力將啞鈴推回頭頂。","重複所需次數。"],"2192":["踏上踏板並握住把手。","以流暢的節奏開始往前踩踏。","身體站直，肩膀保持放鬆。","設定能維持平穩呼吸的阻力與配速。","持續 15 到 45 分鐘。","下器材前先放慢速度踩 1 分鐘。"],"2193":["坐上臥式腳踏車，調整座椅，讓腿踩到底時膝蓋仍保持微彎。","雙腳放在踏板上，雙手握住把手。","以像散步一樣輕鬆的配速踩踏。","背部貼緊靠墊，保持平穩呼吸。","持續 15 到 30 分鐘。","逐漸放慢踩踏速度進行緩和。"],"2197":["踏上跑帶，將安全夾夾在衣服上。","先從步行開始，再逐漸提高速度到舒適的慢跑。","挺胸，雙臂在身體兩側自然輕鬆擺動。","腳步輕柔落在髖部正下方，維持輕快步頻。","以能維持平穩呼吸的配速跑 10 到 30 分鐘。","最後放慢成步行幾分鐘作為緩和。"],"2198":["調整座椅高度並坐好，將上臂貼在護墊上。","手肘彎曲，握住把手。","伸直手肘往下壓。","在底部夾緊三頭肌。","慢慢回到起始位置，肩膀不要聳起。","依計畫次數重複。"],"2200":["仰臥，雙腳腳跟放在健身球上，雙臂放在身體兩側。","收緊核心，腳跟往下壓穩球面。","抬起髖部，直到肩膀到膝蓋呈一直線。","在頂點夾緊臀肌停留 1 秒。","慢慢放下髖部，不要讓球滾走。","保持球體穩定，依計畫次數重複。"],"2202":["坐在地上，雙腿向前伸展。","將滾筒置於臀部下方。","雙手撐在身後地面支撐體重。","在滾筒上前後滾動按摩臀部肌肉，感受深層筋膜放鬆。","痛點處稍作停留加強按壓。","慢慢滾動維持均勻呼吸。","重複所需時間。"],"2203":["坐在平坦地面上，雙腿向前伸直。","雙手握住健腹輪手柄，置於大腿上。","稍微前傾，推動健腹輪向前滾出，雙臂伸展。","稍作停頓，然後手臂與核心發力將健腹輪拉回大腿處。","重複所需次數。"],"2204":["從棒式姿勢開始，前臂靠在滾筒上，身體成一直線。","啟動核心慢慢向前滾動滾筒，在受控範圍內盡可能向前伸展身軀。","在最遠延伸點停頓片刻，核心發力將滾筒拉回起始位置。","重複所需次數。"],"2205":["雙膝跪地，將滾筒置於大腿前側髖部下方。","雙手撐地支撐體重。","前後滾動放鬆髖屈肌與股四頭肌。","維持深層拉伸數秒後放鬆。","重複所需次數。"],"2206":["平躺在地上，雙臂伸過頭頂，雙腿向前伸直。","雙腳夾住滾筒。","收緊腹肌將雙腿抬離地面，屈膝將滾筒帶向胸前。","頂峰停頓片刻，慢慢伸展雙腿將滾筒推離身體。","重複所需次數。"],"2207":["雙腳與肩同寬站立，雙手在身前持滾輪。","屈膝屈髖前傾，背部維持打直。","手臂向前伸展推動滾輪向前，感受背闊肌拉伸。","保持拉伸數秒，緩慢拉回。","重複所需次數。"],"2208":["坐在地上，雙腿向前伸展。","將滾筒橫放在下背部下方。","慢慢向後躺倒，雙腳推地讓滾筒沿著背部向上滾動。","持續滾動至上背部與肩胛骨處。","停頓片刻，緩緩滾回。","重複所需次數。"],"2209":["坐在平坦地面上，雙腿向前伸直。","雙手正握滾輪手柄置於大腿前。","微向後傾收緊核心。","雙臂伸直將滾輪抬高至肩部高度。","慢慢放回大腿前。","重複所需次數。"],"2224":["坐在座椅上，背部與頭部平貼靠墊。","雙腳與肩同寬，踩在踏板中央。","鬆開安全扣把，放低雪橇直到膝蓋彎曲約 90 度。","下放過程中，下背保持貼緊靠墊。","全腳掌發力將雙腿推直，但膝蓋不要鎖死。","有控制地放低並重複。"],"2234":["身體站直，雙手各持一顆啞鈴放在身體兩側，掌心朝內。","手肘保持微彎，收緊核心。","雙臂往兩側抬起，直到與肩同高。","由手肘帶動上抬，避免聳肩。","在頂點短暫停留。","慢慢放回起始位置並重複。"],"2249":["將 V 型把手裝在高位滑輪上，面向配重片站立。","握住把手，雙肘固定在身體兩側。","將把手往下壓，直到雙臂完全伸直。","在底部夾緊三頭肌停留一下。","讓把手回升，直到前臂略高於水平位置。","整組動作中，上臂保持不動。"],"2258":["身體站直，肩膀放鬆，視線看向前方。","以自然的步幅開始行走。","雙臂與雙腿方向相反，自然輕柔擺動。","腳跟輕柔落地，再順勢滾動到腳尖推離。","維持能自在呼吸的配速。","持續步行 20 到 60 分鐘。"],"2259":["踏上跑帶，雙手握住扶手並以慢速開始。","提高到舒適的步行速度。","放開扶手，讓雙臂自然擺動。","抬頭挺胸，步伐保持均勻。","想增加挑戰時，可以調高一點坡度。","步行 20 到 45 分鐘，下跑步機前先放慢速度。"],"2265":["調整座椅與胸墊位置，坐好並讓胸口貼緊胸墊。","雙臂伸直握住把手。","手肘往後帶，將把手拉向軀幹。","將兩側肩胛骨往中間夾緊。","慢慢放回，直到雙臂再次伸直。","依計畫次數重複。"],"2266":["調整器材並坐好，讓背部靠在護墊上。","依器材設計將雙臂交叉抱胸或握住把手。","從髖部與下背伸展發力，將身體往後推。","軀幹回到直立中立的位置時即停住。","慢慢回到起始位置。","依計畫次數重複。"],"2267":["調整座椅並坐好，背部平貼靠墊。","雙腳踩在踏板上，約與肩同寬。","腳跟發力推蹬，直到雙腿接近伸直。","膝蓋不要鎖死。","慢慢彎曲膝蓋回到原位。","依計畫次數重複。"],"2268":["坐在器材上，調整座椅高度讓雙手能搆到護墊。","雙手放在護墊上，雙腳踩穩固定。","收縮腹肌，將軀幹往前捲。","在底部短暫停留。","慢慢回到直立的起始位置。","依計畫次數重複。"],"2269":["跪在軟墊上，雙手握住滾輪放在膝蓋前方。","下背微微拱起，收緊腹肌。","髖部保持穩定，將滾輪往前推一小段距離。","將肋骨往髖部方向捲，把滾輪拉回膝蓋前方。","捲腹時吐氣，避免塌腰拱背。","流暢且有控制地重複動作。"],"2271":["雙腳分開與肩同寬站立，膝蓋微彎採格鬥站姿。","左手抬起護頭，右手護於下巴。","轉動髖部以左腳為軸心旋轉，同時向前打出左直拳。","旋轉軀幹，運用核心與下盤力量爆發出拳。","快速將手臂收回防守姿勢，重複所需次數。"],"2272":["採拳擊站姿，前腳在前，雙手抬高護在下巴旁。","前手朝目標方向直直打出。","擊中目標瞬間旋轉拳頭，讓掌心朝下。","下巴微收，後手保持防守。","快速將手收回防守位置。","重複動作，想換架勢時可換邊。"],"2273":["採拳擊站姿，雙手抬高防守。","後腳蹬地，同時旋轉髖部與肩膀。","將後手朝目標方向直直打出。","前手保持抬高，保護下巴。","沿著原本的路線將手收回。","回到拳擊站姿並重複。"],"2274":["採拳擊站姿，雙手抬高防守。","雙膝微彎，身體右側稍微下沉。","雙腿往上推蹬，同時旋轉髖部。","掌心朝向自己，將右拳往上打出。","左手保持護住下巴。","回到拳擊站姿並重複。"],"2275":["採拳擊站姿，雙手抬高防守。","雙膝微彎，身體左側稍微下沉。","雙腿往上推蹬，同時旋轉髖部。","掌心朝向自己，將左拳往上打出。","右手保持護住下巴。","回到拳擊站姿並重複。"],"2276":["仰躺在器材上，依器材指示放好雙手或雙臂。","雙腳勾住固定墊或握住把手以維持穩定。","收縮腹肌，將軀幹往上捲起。","在頂點短暫停留。","慢慢放低回到起始位置。","依計畫次數重複。"],"2277":["調整座椅高度，讓把手對齊胸口中央。","向後坐穩，將兩側肩胛骨往後收緊。","將把手往前推，直到雙臂接近伸直。","手肘不要鎖死。","慢慢放回，直到胸口有伸展感。","依計畫次數重複。"],"2278":["調整座椅並坐好，背部貼緊靠墊。","手肘彎曲，握住把手。","將把手往前下方推，直到雙臂接近伸直。","肩膀保持下沉，挺起胸口。","有控制地慢慢放回。","依計畫次數重複。"],"2279":["調整座椅高度，讓踏板踩到底時膝蓋仍保持微彎。","握住把手，坐直身體。","先以輕鬆的配速開始踩踏熱身。","將速度提高到能持續維持的輕快節奏。","上半身保持放鬆。","持續 10 到 30 分鐘，最後放慢速度緩和。"],"2282":["設定較輕的重量，調整護墊使其貼在後腦勺。","坐直身體，下巴微收。","後腦勺頂住護墊，慢慢往後推。","只在舒服的活動範圍內移動。","慢慢回到起始位置。","有控制地依計畫次數重複。"],"2283":["設定較輕的重量，將護墊調到頭部左側。","坐直身體，肩膀放鬆。","對抗阻力將頭往左側傾斜。","動作幅度保持小而流暢。","慢慢回到中間位置。","有控制地依計畫次數重複。"],"2284":["設定較輕的重量，將護墊調到頭部右側。","坐直身體，肩膀放鬆。","對抗阻力將頭往右側傾斜。","動作幅度保持小而流暢。","慢慢回到中間位置。","有控制地依計畫次數重複。"],"2285":["調整機械滑輪下拉機的座椅與把手。","坐上機台，背靠支撐墊，正握抓住把手。","手臂微屈，核心收緊。","慢慢將把手拉向胸前，擠壓背闊肌。","在頂峰收縮處停頓片刻，緩緩回到原位。","重複所需次數。"],"2286":["調整機台以符合身形，背靠椅背坐好。","雙腳踩在腳踏板上，握緊把手固定。","啟動臀肌與腿後肌群，踩動踏板蹬展髖部向後推。","頂端停留片刻，慢慢收回雙腿。","重複所需次數。"],"2287":["調整推腿機的座椅與踏板。","背靠椅背坐穩，雙腳踩在踏板上。","雙手握住兩側把手維持穩定。","單腳用力推蹬踏板，直到腿部接近打直（不鎖死）。","停頓片刻，慢慢屈腿收回。","換另一條腿重複。","雙腿交替進行至所需次數。"],"2288":["調整座椅高度，握住握力機手柄。","背部挺直，雙腳平踩。","吐氣用力擠壓捏緊握把，收縮前臂肌肉。","用力維持收縮一秒，慢慢放鬆放開。","重複所需次數。"],"2289":["調整小腿訓練機座椅，使肩膀與肩墊貼合。","前腳掌踩在踏台邊緣，腳跟懸空。","握住把手維持穩定。","蹬展腳踝收縮小腿將重量推起。","頂點稍作停頓。","放低腳跟至低於踏板，感受深層拉伸後再次推起。","重複所需次數。"],"2290":["雙手各拿一個啞鈴，站在長凳前方約一步的距離。","將後腳腳背放在長凳上。","身體垂直往下蹲，直到前腿大腿約與地面平行。","保持軀幹挺直，前膝對齊腳尖方向。","前腳腳跟踩地發力，站回起始位置。","做完預定次數後換腳。"],"2291":["坐在下拉機上，將大腿固定在護墊下方。","雙手以寬握正握橫桿。","身體微微後傾，將橫桿拉到上胸位置。","手肘往下、往後帶，夾緊肩胛骨。","控制速度讓橫桿回到上方，直到雙臂完全伸直。","過程中避免晃動軀幹。"],"2292":["雙腳分開與肩同寬站立，雙手各握一啞鈴，掌心朝向身體。","微屈膝蓋，屈髖前傾，背部維持打直。","手肘微彎，將手臂向兩側抬起至平行地面（俯身側平舉）。","頂端稍作停頓，然後慢慢降回。","重複所需次數。"],"2293":["站直，雙手各持一啞鈴，掌心朝前。","上手臂貼在牧師斜墊上，手肘微屈。","將啞鈴向上彎舉向肩膀，上手臂固定。","在彎舉最高點旋轉手腕使掌心朝下。","慢慢將啞鈴放回，同時將手腕轉回掌心朝前。","重複所需次數。"],"2294":["坐在牧師椅上，手持啞鈴掌心朝上，手肘靠在墊上。","上手臂固定，將啞鈴向上彎舉至肩前。","在動作頂端旋轉手腕使掌心朝下（旋腕彎舉）。","控制著將啞鈴放回，同時旋轉回掌心朝上。","重複所需次數。"],"2296":["跪在健身球前方，將前臂放在球上。","收緊腹肌，讓身體從膝蓋到頭部呈一直線。","雙臂與身體往前延伸，把球向前滾出去。","感覺核心用力緊繃時就停住，不要讓腰部塌陷。","收縮腹肌，把球拉回原位。","放慢速度重複動作。"],"2297":["坐在抗力球上，雙腳踩實，膝蓋呈 90 度。","雙手放於後腦勺，手肘朝外展開。","收緊腹肌向前捲動上半身，使胸部靠近膝蓋（抗力球捲腹）。","頂點停頓片刻，慢慢降回上半身。","重複所需次數。"],"2298":["擺放一張高度適合身體懸掛於下方的重訓椅或單槓。","仰臥躺在地面，頭部朝向長凳。","向上伸手正握抓住重訓椅邊緣或橫槓，握距略寬於肩。","腳跟著地身體伸展打直。","核心收緊，肩胛骨向內夾緊，將胸口拉向長凳（澳洲引體向上/仰臥懸垂划船）。","頂點停頓片刻，慢慢放回身體。","重複所需次數。"],"2300":["在腰部高度架設橫槓，仰臥躺在槓下。","正握抓住槓鈴，握距略寬於肩寬。","腳跟著地，身體維持一條直線。","兩側肩胛骨向後夾緊，挺胸將胸口拉向槓鈴。","頂端停頓片刻，緩慢降回。","重複所需次數。"],"2301":["雙手舉高，採格鬥站姿。","將重心移到前腳。","抬起後膝，把腿往目標方向伸展。","腳跟畫弧勾踢出去。","穩定控制將腿收回。","回到格鬥站姿並重複，接著換邊。"],"2302":["雙手舉高，採格鬥站姿。","抬起前膝，指向前方。","伸展腿部，用腳跟勾踢越過目標。","支撐腳踩穩地面，核心收緊。","穩定控制將腿收回。","回到格鬥站姿並重複，接著換邊。"],"2303":["雙手舉高，採格鬥站姿。","將膝蓋往身前抬起。","小腿快速往前方低處彈踢出去。","保持軀幹挺直與平衡。","迅速將腿收回。","回到格鬥站姿並重複，接著換腿。"],"2304":["雙手舉高，採格鬥站姿。","將後腿往身前直直往上擺起。","踢到最高點時腿部保持伸展。","將腳跟俐落地往下劈落。","支撐腿保持微彎並維持平衡。","回到格鬥站姿並重複，接著換邊。"],"2305":["雙手舉高，採格鬥站姿。","將膝蓋往胸口方向抬起。","小腿朝目標快速往前彈踢。","沿著原本的路線迅速收腿。","支撐腳踩穩地面。","回到格鬥站姿並重複，接著換腿。"],"2306":["雙手舉高，採格鬥站姿。","轉動頭部與肩膀看向後方。","以支撐腳的前腳掌為軸旋轉。","揮出踢擊腿，用腳跟勾掃越過目標。","落地時回到平穩的站姿。","重複動作，接著換邊。"],"2307":["身體側向，雙手舉高採格鬥站姿。","將膝蓋往胸口方向抬起。","腿往側面伸展，把腳跟朝目標蹬出去。","支撐腳腳尖微微朝外轉開。","把腿收回並踩回地面。","重複動作，接著換腿。"],"2308":["雙手舉高，採格鬥站姿。","以支撐腳為軸旋轉，把髖部翻轉過來。","抬起膝蓋，讓腿畫弧橫掃目標。","在末端將小腿延伸踢出。","把腿收回，回到格鬥站姿。","重複動作，接著換腿。"],"2309":["雙手舉高，採格鬥站姿。","抬起膝蓋，腳尖朝上勾起。","身體微微後傾，將腳跟筆直往前推蹬。","支撐腳踩穩地面。","將腿收回並踩回地面。","重複動作，接著換腿。"],"2310":["雙手舉高，採格鬥站姿。","轉動頭部與肩膀看向後方。","以支撐腳為軸旋轉身體。","腳跟帶動，把腿筆直往後蹬出。","軀幹微微前傾以維持平衡。","回到格鬥站姿並重複，接著換邊。"],"2311":["調整踏步機至適合的步頻與阻力。","站上踏板，雙手扶在扶手上保持平衡。","雙腳交替踩踏踏板，模擬爬樓梯動作。","維持抬頭挺胸直立騎姿，收緊核心。","持續踩踏至指定時間或步數。","適應後可逐漸提高速度或阻力。","運動結束後記得進行小腿與大腿伸展放鬆。"],"2312":["平躺，雙膝彎曲，雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","腹肌發力抬起上半身，右肘轉向靠攏左膝。","同時右腿向前水平伸直懸空（腳踏車捲腹 Bicycle Crunch）。","停頓片刻，換左肘碰右膝、左腿伸直。","雙側交替進行踩踏動作至所需次數。"],"2314":["仰躺在器械上，依器械設計固定雙腳或雙手。","輕握握把，讓下背貼穩靠墊。","將肋骨往髖部方向捲起，完成捲腹。","在頂點吐氣並收緊腹肌。","慢慢放低身體，不要讓配重片完全放回底座。","重複預定的次數。"],"2315":["調整座椅高度，使膝蓋微彎，雙腳平放踏板。","前腳掌踩在踏板邊緣，腳跟懸空。","手握把手維持穩定。","前腳掌發力將腳跟推至最高點。","頂峰停頓片刻，慢慢降回。","重複所需次數。"],"2317":["坐在重訓椅上，背部打直，雙腳平放。","雙手各握一啞鈴，掌心朝向身體，手肘呈 90 度。","保持手肘 90 度屈曲，將雙臂向兩側抬起至平行地面（側平舉）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"2318":["調整機械推肩機座椅高度與靠背。","坐上機台，背靠椅背，雙腳踩實。","正握抓把手，間距略寬於肩。","向上前方推動把手，手臂伸直（不鎖死）。","頂端停留片刻，慢慢降回。","重複所需次數。"],"2321":["站直，雙手各持一啞鈴，掌心朝向軀幹。","手肘貼緊軀幹，向上旋轉前臂使掌心朝前。","上手臂維持不動，彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂峰停頓片刻。","吸氣慢慢放回啞鈴。","重複指定次數。"],"2323":["雙腳站得比肩寬，腳尖朝外。","雙手在身前拿著一或兩個啞鈴。","挺胸，髖部往後往下坐。","下蹲到大腿約與地面平行。","腳跟踩地發力，夾緊臀肌站起。","膝蓋保持對齊腳尖方向。"],"2324":["將繩索裝在低滑輪上，背對配重塔站立。","雙手從雙腿之間往後伸去抓握繩索，接著往前走一步讓滑輪拉緊。","雙腿保持接近打直，從髖部往前俯身。","髖部往前推、站直身體，讓繩索從雙腿之間穿過。","在頂點夾緊臀肌。","穩定控制往後俯身，重複動作。"],"2325":["雙手正握啞鈴，背部打直，從髖部往前俯身。","雙臂自然垂在肩膀正下方。","將啞鈴往髖部方向拉起，同時轉動手腕讓掌心相對。","在頂點夾緊肩胛骨。","慢慢放低啞鈴，同時將掌心轉回朝下。","保持軀幹穩定不晃動。"],"2326":["雙手各拿一個啞鈴，背部打直往前俯身。","雙臂自然下垂，掌心朝向雙腿。","將啞鈴拉向下肋骨位置。","手肘貼近身體，並夾緊肩胛骨。","慢慢放低，直到雙臂伸直。","避免用軀幹猛力拉扯。"],"2327":["雙腳分開與肩同寬站立，膝蓋微彎。","雙手各持一啞鈴，正握，掌心朝向身體。","屈髖前傾，背部維持挺直，核心收緊。","手臂自然下垂伸直，手肘微屈。","將啞鈴拉向胸腹兩側，肩胛骨用力夾緊。","頂端停留片刻，慢慢降回。","重複所需次數。"],"2328":["將抗力球放地上，擺出高棒式姿勢，雙手撐在球面上，間距略窄於肩。","收緊核心維持軀幹穩定成一直線。","手肘微收彎曲，將胸口沉向抗力球。","底部停頓片刻，手臂推直回到高棒式。","重複所需次數。"],"2329":["坐在地上，雙腿向前伸展。","彎曲膝蓋雙腳踩實，與臀部同寬。","雙手輕扶後腦勺，手肘展開。","收緊腹肌，軀幹慢慢向右旋轉，右肘朝向左膝。","轉到底部稍作停頓，回到中央。","換向左旋轉，左肘朝向右膝。","交替進行至所需次數。"],"2330":["坐在滑輪下拉機上，大腿固定在大腿護墊下方。","正握抓握橫桿，握距略寬於肩。","身體微後傾挺胸，下背維持自然微弓。","將長桿向下拉向上胸鎖骨處，肩胛骨向內夾緊。","動作底部停頓片刻，慢慢放回橫桿。","重複所需次數。"],"2331":["調整座椅高度，坐穩飛輪交叉訓練機。","雙腳踩入踏板並握緊手把。","以平穩受控的節奏開始踩踏。","維持均勻步頻並視需要調整阻力。","持續踩踏至有氧訓練指定時間。"],"2333":["懸掛在單槓上，手臂完全伸直，雙腿下垂。","啟動核心，保持雙腿打直，將雙腿抬至身前與地面平行（懸垂 L 抬腿）。","在水平頂端維持片刻，慢慢降回雙腿。","重複所需次數。"],"2334":["調整推腿機至適當重量。","背貼靠墊坐穩，雙腳踩在平台上。","前腳掌踩在踏板下邊緣，腳跟懸空。","伸展腳踝將踏板向前推起，膝蓋保持微屈。","持續用力直到小腿完全收縮。","頂峰停頓片刻，慢慢放低腳跟。","重複所需次數。"],"2335":["調整座姿提踵機，使大腿墊壓在大腿遠端近膝處。","前腳掌踩在踏板下緣，腳跟懸空。","雙手握住兩側把手。","伸展腳踝將墊子頂起，盡可能抬高腳跟。","頂峰停留片刻，慢慢降回。","重複所需次數。"],"2336":["躺在長凳上，雙眼位於槓鈴正下方，雙腳踩穩地面。","雙手握槓，握距略寬於肩。","槓鈴降到胸口時，前臂要保持垂直地面。","穩定控制將槓鈴放到中胸位置。","往上推到雙臂伸直，手肘不要過度往外張開。","重複預定的次數。"],"2337":["躺在長凳上，雙手各拿一個啞鈴舉在胸口上方。","手肘保持微微彎曲。","雙臂畫大弧線往兩側放低。","感覺胸口有溫和的伸展感時就停住。","將啞鈴往胸口上方合攏。","重複預定的次數。"],"2338":["躺在長凳上，雙眼位於槓鈴下方，雙腳平踩地面。","對照錯誤與正確示範：臀部應全程貼緊椅墊，絕不離墊抬起。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2339":["躺在長凳上，以適中的寬度握住槓鈴。","對照錯誤與正確示範：降到最低點時前臂應垂直地面，雙手位置略寬於肩。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2340":["躺在長凳上，起槓前先將肩胛骨往後夾緊。","對照錯誤與正確示範：肩胛骨應全程往後收、往下壓，貼緊長凳。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2341":["躺在長凳上，將槓鈴起槓至肩膀正上方。","對照錯誤與正確示範：雙臂移動軌跡穩定受控，槓鈴會落向下胸位置。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2342":["躺在長凳上，將槓鈴起槓撐在胸口上方。","對照錯誤與正確示範：手肘與軀幹約呈 45 度角，而不是往兩側大幅外張。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2343":["握住槓鈴，膝蓋微彎，從髖部往前俯身。","對照錯誤與正確示範：脊椎保持延伸打直，不圓背。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2344":["仰躺在地上，雙膝彎曲，雙手放在頭部兩側。","對照錯誤與正確示範：下背輕貼地面，只有上背往上捲起。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2345":["將背部與肩膀貼緊靠墊，雙腳踩在踏板上。","對照錯誤與正確示範：膝蓋對齊腳尖方向，雙腳平貼在踏板上。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2346":["坐在長凳邊緣，雙手在髖部兩側握住凳緣，將臀部移出長凳。","對照錯誤與正確示範：背部保持貼近長凳，手肘朝正後方彎曲。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2347":["前臂撐在地面，手肘位於肩膀正下方。","雙腿往後伸直，腳尖點地。","將身體撐起，從頭到腳跟呈一直線。","避免把臀部往上翹高，或讓髖部往下塌陷。","收緊腹肌與臀肌以維持直線。","維持 20 到 40 秒，保持平穩呼吸。"],"2348":["坐在牧師椅前，將上臂平貼在靠墊上。","對照錯誤與正確示範：手腕保持中立打直，不要往後折或往內勾。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2349":["側躺，前臂貼地，手肘位於肩膀正下方。","雙腳疊放，將髖部撐離地面。","讓身體從頭到腳呈一直線。","避免臀部往後突出或髖部往下掉。","收緊腹肌與臀肌以保持身體筆直。","維持 20 到 30 秒，接著換邊。"],"2350":["雙手撐在肩膀正下方的地面，雙腿往後伸直。","對照錯誤與正確示範：身體從頭到腳跟呈一直線，雙手位於肩膀正下方。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2351":["從高棒式開始，穩定控制將身體放低。","對照錯誤與正確示範：胸口接近地面，手肘斜向後方，髖部維持在同一直線上。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2352":["站直，雙手各拿啞鈴垂在身體兩側，掌心朝前。","對照錯誤與正確示範：手肘固定在身體兩側，軀幹不前後晃動。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2353":["坐在長凳上，身體前傾，將手肘抵在大腿內側。","對照錯誤與正確示範：上臂貼穩大腿內側，只有前臂移動。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2354":["站立讓槓鈴位於腳掌中段上方，往下俯身，在雙腿外側握槓。","對照錯誤與正確示範：從離地到站直鎖定，背部全程保持中立且核心繃緊。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2355":["懸掛在單槓上，雙臂完全伸展，膝蓋彎曲 90 度。","收緊核心將膝蓋抬向胸口，盡可能靠近手肘（懸垂屈膝抬腿）。","慢慢將雙腿降回起始位置。","重複所需次數。"],"2357":["站立讓槓鈴位於腳掌中段上方，握槓前將髖部設定在適中高度。","對照錯誤與正確示範：起拉時髖部高於膝蓋，且與肩膀同步上升。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2358":["前臂放在地面，手肘在肩膀正下方，雙腿往後伸直。","對照錯誤與正確示範：臀部與肩膀保持齊平，不往上翹起也不往下塌陷。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2359":["將槓鈴扛在上背，往下蹲到底。","對照錯誤與正確示範：膝蓋順著腳尖方向往外推，不往內夾。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2360":["雙腳與肩同寬站立，開始往下蹲。","對照錯誤與正確示範：下蹲與站起的過程中，膝蓋始終對齊腳尖方向。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2361":["將槓鈴扛在上背，往下蹲到足夠深度。","對照錯誤與正確示範：站起時髖部與胸口同步上升，髖部不會先單獨往上衝。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2362":["將槓鈴扛在上背，收緊核心並往下蹲。","對照錯誤與正確示範：背部保持平坦穩定，在最低點也不會圓背。","用輕重量放慢速度執行，全程維持正確姿勢。","利用鏡子或從側面錄下影片，檢查自己的姿勢。","先修正動作要領再加重，組間也要充分休息以維持動作標準。"],"2363":["雙手撐在雙槓上，雙臂伸直，身體懸空支撐。","身體微前傾，彎曲手肘下沉身體，直到胸部略高於把手高度。","停頓片刻，手臂推直將身體撐回頂端。","重複所需次數。"],"2364":["調整雙槓輔助機台配重，膝蓋跪在輔助墊上。","寬握抓住把手，手肘微屈。","手肘彎曲下沉身體至上手臂平行地面。","雙臂用力推直將身體推回。","重複所需次數。"],"2365":["上背靠在長凳上，雙手拿啞鈴舉在胸口上方。","雙臂接近打直，手肘保持微微彎曲。","將啞鈴畫弧往頭頂後方放低，直到感覺肌肉伸展。","肋骨下壓，保持髖部穩定。","用背闊肌發力，把啞鈴拉回胸口上方。","穩定控制並重複動作。"],"2367":["雙手各拿一個啞鈴，站在矮踏階上。","一腳往後跨下踏階。","軀幹保持挺直，後膝往地面方向放低。","前膝維持在腳踝正上方。","前腳腳跟踩地發力，站回起始位置。","做完預定次數後換腳。"],"2368":["雙腳分開與肩同寬站立。","單腳向前跨出一大步（約兩步長）。","屈膝下沉成弓箭步，背部挺直。","下沉至前大腿與地面平行，後膝接近貼地。","稍作停頓，踩穩前腳跟蹬回起始站姿。","重複所需次數後換腿。"],"2371":["坐在地上，雙膝彎曲，雙腳平踩。","雙手抱住槓片或藥球於胸前。","微向後傾斜啟動核心肌群。","軀幹向右旋轉，將重物移向身體右側地面（俄羅斯轉體）。","稍作停頓，轉向左側將重物移向左側地面。","兩側交替進行至所需次數。"],"2375":["站在穩固的支撐物旁，單手輕扶。","將一腳往身前微微抬離地面。","髖部往後坐，用站立腿往下蹲。","膝蓋保持對齊腳尖方向。","腳跟踩地發力，站回起始位置。","做完預定次數後換腳。"],"2381":["單手將啞鈴舉在肩膀高度，掌心朝前。","站直或坐直，收緊核心。","將啞鈴往上推過頭，直到手臂完全伸直。","避免身體往側面傾斜。","慢慢將啞鈴放回肩膀高度。","做完預定次數後換手。"],"2393":["背部打直往前俯身，一手扶在長凳或膝蓋上支撐。","另一手拿啞鈴，手臂自然下垂。","手肘貼近身體，將啞鈴往髖部方向拉起。","將肩胛骨往脊椎方向夾緊。","慢慢放低，直到手臂伸直。","做完預定次數後換手。"],"2394":["俯臥在地面，雙臂往前伸直或放在頭部兩側。","夾緊臀肌，將胸口與雙腿微微抬離地面。","頸部保持中立，視線看向地面。","在頂點停留 1 秒。","慢慢放回地面。","重複動作，不要勉強過度反折腰部。"],"2395":["仰躺在地面，雙手放在腦後。","抬起肩膀，並將雙膝抬起。","一側手肘轉向對側膝蓋，同時將另一腿伸直。","像踩腳踏車一樣流暢地左右交替。","下背保持貼緊地面。","持續執行預定的次數或時間。"],"2396":["仰躺在地面、腳朝向滑輪配重塔，掌心朝上握住橫桿或握把。","上臂保持固定，貼穩地面。","將握把往肩膀方向彎舉，在頂點收緊二頭肌。","慢慢放低，直到雙臂接近伸直。","背部平貼地面，彎舉時避免聳起肩膀。"],"2397":["坐在重訓椅上，雙手各握一啞鈴置於肩部，掌心朝前。","手肘微向前收，將啞鈴向上推舉過頭頂，手臂完全伸直。","頂端停頓片刻，緩慢降回肩部。","重複所需次數。"],"2398":["四足跪姿開始，雙手在肩下方，雙膝在髖部下方（跪姿伏地挺身）。","手肘彎曲，胸部貼向地面，手肘微收貼側。","胸部快貼地時稍作停頓。","掌心推地推直手臂回到起始位置。","重複所需次數。"],"2399":["坐在滑輪機前，雙腳踩實，雙膝微屈。","雙手握住滑輪手把，手臂在身前伸展。","收緊核心，慢慢將軀幹向一側旋轉，拉動滑輪橫越身體。","轉體到底停頓片刻，慢慢旋轉回正。","換向另一側重複。","交替進行至所需次數。"],"2400":["滑輪機調整至最低位並扣上腳踝套。","俯臥趴在平凳上，雙腿伸展，腳踝套固定在雙腳。","抓穩重訓椅把手維持穩定。","彎曲膝蓋將雙腿向臀部拉近，擠壓腿後肌群。","頂端停頓片刻，緩慢放回。","重複所需次數。"],"2401":["站直，雙手各握一啞鈴，掌心朝前。","手肘貼緊軀幹，上手臂固定。","吐氣彎舉啞鈴收縮二頭肌。","舉至啞鈴與肩同高。","頂峰擠壓二頭肌停頓片刻。","吸氣慢慢降回。","重複所需次數。"],"2402":["站直，雙手各持一啞鈴垂於體側。","旋轉前臂使掌心朝前。","上手臂維持不動，吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂端停留片刻，用力擠壓。","吸氣慢慢放回。","重複指定次數。"],"2403":["站直，雙腳分開與肩同寬，雙手各持啞鈴，掌心朝前。","使用二頭肌隔離板（Arm Blaster）扣在胸腹固定上手臂。","上手臂緊貼隔離板維持不動，吐氣單手將啞鈴彎向肩膀。","舉至二頭肌完全收縮。","頂峰停頓片刻。","吸氣慢慢降回。","換另一手重複，交替進行至指定次數。"],"2404":["站直，雙腳與肩同寬，反手握住 EZ 槓，掌心朝上。","上手臂固定在二頭肌隔離板上。","手肘貼身，吐氣將槓鈴向上彎舉至肩部。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢放回，手臂充分伸展。","重複所需次數。"],"2405":["將 V 型握把接在高滑輪機上。","面對滑輪機站立，雙腳與肩同寬。","正握抓住 V 型桿，掌心朝下。","手肘緊貼身側固定。","收緊三頭肌吐氣向下推直，手臂完全伸展（滑輪下壓）。","底部停頓片刻，擠壓三頭肌。","吸氣慢慢控制放回 90 度。","重複所需次數。"],"2406":["直桿接在滑輪機最高處。","面對機台站立，雙腳與肩同寬。","反手抓直桿，掌心朝上，握距與肩同寬。","手肘貼緊身體兩側。","啟動三頭肌慢慢向下壓直橫槓。","底部停頓片刻，慢慢送回。","重複所需次數。"],"2407":["站直，雙腳與肩同寬，反握抓槓鈴，掌心朝上。","手臂固定在二頭肌隔離板上。","上手臂固定，吐氣彎舉槓鈴收縮二頭肌。","舉至槓鈴與肩同高。","頂端停留片刻，擠壓收縮。","吸氣慢慢降回。","重複所需次數。"],"2408":["俯臥在長凳上，頭部懸出邊緣並戴好負重頭帶。","起始時下巴往胸口微收。","慢慢將頭抬起，直到臉部朝向正前方。","稍作停留，再穩定控制放低。","使用輕重量並平穩執行，千萬不要猛力甩動脖子。"],"2409":["仰躺在長凳上，頭部懸出邊緣並戴好負重頭帶。","在舒適範圍內讓頭部微微往後仰。","慢慢將下巴往胸口方向捲起。","在頂點短暫停留。","穩定控制放低，使用輕重量並保持動作平順。"],"2410":["戴好頭帶，讓輕重量垂在身前。","站立並往前俯身，雙手撐在大腿上。","讓下巴往胸口方向自然垂下。","將頭抬起，直到視線朝向正前方。","慢慢放低，保持動作幅度小而受控。"],"2411":["戴好頭帶，面對滑輪坐下，將滑輪調整至頭部高度。","起始時頭部微微前傾。","將頭往後拉，直到回到直立位置。","稍作停留，再對抗滑輪拉力慢慢回放。","保持輕重量，肩膀放鬆。"],"2412":["戴好頭帶，背對滑輪坐下，將滑輪調整至頭部高度。","起始時頭部微微後仰。","將下巴往胸口方向收。","稍作停留，再穩定控制慢慢回放。","保持輕重量，肩膀放鬆。"],"2413":["站立，雙手以寬握反握槓鈴。","手肘朝後，讓槓鈴貼近身體。","手肘往後拉，帶動槓鈴貼著軀幹往上滑動。","在頂點收緊二頭肌。","沿著相同路徑慢慢放低。","保持軀幹挺直。"],"2414":["雙腳分開與肩同寬站立，單手反握抓槓鈴，掌心朝上。","另一手扶在大腿上支撐。","上手臂固定，吐氣將重量向上彎舉至肩部。","頂端停留片刻，擠壓二頭肌。","吸氣慢慢放回。","重複所需次數後換手。"],"2415":["單手握住支撐物，身體往外傾斜。","空著的手拿啞鈴垂在身側。","將啞鈴往側面舉起，直到與肩同高。","手肘保持微微彎曲。","慢慢放回起始位置。","做完預定次數後換手。"],"2417":["將環狀彈力帶套在大腿或膝蓋周圍。","挺胸往下蹲到半蹲位置。","跨大步往側邊或前方踏出。","維持彈力帶張力，膝蓋往外推開。","保持低蹲，將另一隻腳收回。","走完預定距離後再走回來。"],"2418":["採四足跪姿，將彈力帶套在大腿周圍。","核心收緊，背部保持平直。","單腳維持屈膝，對抗彈力帶往側邊抬起。","大腿抬到約與髖部同高時稍作停留。","軀幹不扭轉，慢慢往下放。","完成預定次數後換腳。"],"2419":["將環狀彈力帶套在腳踝或大腿周圍。","採四足跪姿，或扶著支撐物站立。","對抗彈力帶，將單腳往後或往側邊抬起。","在頂點夾緊臀肌。","慢慢放下，下背不要拱起。","完成預定次數後換腳。"],"2420":["仰躺在地上，將彈力帶套在雙腳上。","雙手抓住彈力帶兩端，或將手放在頭側。","抬起肩膀，雙膝往上抬。","雙腳交替踩踏，同時轉動手肘去靠近對側膝蓋。","下背貼平地面。","持續做到預定次數。"],"2423":["俯臥在地上，將彈力帶壓在雙手下或繞過上背固定。","夾緊臀肌，將胸口微微抬離地面。","頸部保持自然中立。","在頂點停留約 1 秒。","慢慢放回地面。","重複動作，避免過度拱背。"],"2424":["雙腳踩在彈力帶中段，雙手將兩端拉到肩膀高度。","往前跨出一步進入弓步。","後膝朝地面往下放。","前膝維持在腳踝正上方，軀幹挺直。","前腳跟發力推地回到原位。","雙腳交替做到預定次數。"],"2425":["坐著或站著，將彈力帶踩在前腳掌下方。","雙手握緊彈力帶兩端。","對抗彈力帶，踮起腳尖往上推。","在頂點停留並收緊小腿。","慢慢放下腳跟。","重複做到預定次數。"],"2429":["平躺在地上，雙膝彎曲，雙腳踩實。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，將上半身捲離地面至約 45 度（捲腹）。","在最高點稍作停頓，慢慢放回。","重複所需次數。"],"2431":["雙腳採寬站距，左右腳下各放一張長凳。","雙手在身前握住一顆啞鈴。","將髖部往下坐到兩張長凳之間。","往下蹲到感覺髖部充分伸展。","腳跟發力推地站起。","全程保持挺胸。"],"2432":["平躺在平凳上，雙腳踩實，背部緊貼椅面。","雙手窄握抓住槓鈴（與肩同寬），掌心朝前。","起槓推直於胸部上方。","慢慢將槓鈴降向胸口，手肘貼近軀幹。","輕觸胸部時停頓片刻。","三頭肌與胸肌發力推回原位（窄握臥推）。","重複所需次數。"],"2434":["坐在地面面向低位滑輪，雙手握住把手。","身體微微後傾，可以的話將雙腳抬離地面。","將軀幹往左右兩側轉動。","手臂保持穩定，核心收緊。","動作放慢，不要猛力甩動。","持續做到預定次數。"],"2458":["面向牆壁站立，在胸前抱住一顆藥球。","挺胸往下深蹲。","用力往上蹬起，將球拋向牆上的目標點。","球彈回時接住。","順勢直接進入下一次深蹲。","維持穩定的節奏。"],"2459":["雙腳分開與肩同寬站立，面對大型輪胎。","屈膝下蹲屈髖前傾，雙手從輪胎下緣深處扣緊抓牢。","啟動腿部與臀部肌群，爆發力蹬腿向上抬起輪胎。","當輪胎升至腰部時，向前換手推頂完成輪胎翻轉（翻輪胎 Tire Flip）。","輪胎翻倒後迅速調整腳步站位。","重複所需次數。"],"2461":["側躺屈膝，雙腳交疊，頭枕在手臂上。","髖部上下對齊不歪斜，核心輕輕收緊。","雙腳貼合，將上方膝蓋往上抬起。","在頂點稍作停留，再慢慢放下。","完成單邊所有次數後換邊。"],"2462":["雙手撐在雙槓上，雙臂完全伸展。","膝蓋微彎，雙腳腳踝交叉。","手肘彎曲下沉身體，直到肩膀低於手肘。","雙手推直撐回頂端。","重複所需次數。"],"2463":["仰躺在地上，將彈力帶套在雙腳上。","雙腿朝天花板抬起。","雙手握住彈力帶兩端，朝腳趾方向延伸。","將肩膀捲離地面。","控制速度慢慢下放。","重複做到預定次數。"],"2464":["單手握把接在低滑輪上，面向機台坐穩，雙腳踩實。","右手握把，手臂完全向前伸展，手肘微屈。","屈髖微前傾，背部打直收腹。","肩胛後收屈肘，將把手拉向腰腹側邊。","頂峰擠壓背肌，緩緩放回。","重複所需次數後換左手操作。"],"2465":["將環狀彈力帶套在大腿或腳踝周圍站立。","膝蓋保持微彎，核心收緊。","雙腳往外跳開，同時雙手舉過頭頂。","落地時雙腿向外推開對抗彈力帶。","跳回起始位置，同時雙手放下。","維持穩定的節奏。"],"2466":["高棒式姿勢開始，雙手在肩膀正下方，身體呈一直線。","收緊核心，右腳離地，將右膝快速提向左手肘（登山者式 Mountain Climber）。","右腳收回同時，換左膝提向右手肘。","雙腿交替加速推進，保持節奏。","維持骨盆水平不上下晃動。","維持均勻呼吸，重複所需次數或時間。"],"2468":["雙手各握一顆啞鈴，站在長凳側面。","將靠近長凳的那隻腳踩上凳面。","腳跟發力踩穩，將身體推上長凳。","另一隻腳跟著踩上來維持平衡。","控制速度走下長凳。","完成預定次數後換邊。"],"2469":["仰躺在健身球上，讓下背獲得支撐。","雙腳腳底貼合，膝蓋往外打開。","雙手輕放在頭側。","往上捲腹，同時將膝蓋拉向胸口。","收緊腹肌。","慢慢下放並重複。"],"2470":["俯臥趴在地上，雙手各持一啞鈴，掌心相對。","雙臂向前伸展，手肘微屈。","三角肌發力將雙臂向上並向兩側抬起，夾緊肩胛骨。","頂端停頓片刻，慢慢降回地面。","重複所需次數。"],"2471":["仰躺在地上，雙膝彎曲，雙腳平放地面。","雙手放在身體兩側。","腳跟發力推地，將髖部往上抬起。","讓肩膀到膝蓋呈一直線。","在頂點夾緊臀肌。","慢慢下放並重複。"],"2473":["仰躺在地上，一隻腳踩在長凳上，另一隻腳伸直。","收緊核心。","支撐腳的腳跟發力推，將髖部往上抬起。","保持兩側髖部水平。","在頂點夾緊臀肌。","完成預定次數後換腳。"],"2474":["仰躺在地上，一腳屈膝踩地，另一腳伸直朝上。","雙手放在身體兩側。","踩地腳的腳跟發力推，將髖部往上抬起。","保持兩側髖部水平。","在頂點夾緊臀肌。","完成預定次數後換腳。"],"2475":["仰躺在地上，一腳踩地，另一腳屈膝往上拉近胸口。","雙手放在身體兩側。","踩地腳的腳跟發力推，將髖部往上抬起。","保持骨盆水平。","在頂點夾緊臀肌。","完成預定次數後換腳。"],"2485":["站立，雙手各握一顆啞鈴垂在身體兩側，掌心朝內相對。","手肘貼近軀幹。","將啞鈴朝肩膀方向往上彎舉。","手腕保持平直。","在頂點收緊肌肉。","慢慢下放並重複。"],"2487":["背部打平、髖部往後推俯身，雙手在胸口下方握住啞鈴。","手肘保持微彎。","將啞鈴往身體兩側平舉打開。","將兩側肩胛骨往中間夾緊。","慢慢下放回到起始位置。","頸部保持自然中立。"],"2500":["俯臥在上斜長凳上，雙手各握一顆啞鈴。","雙臂自然下垂，手肘保持微彎。","將啞鈴往身體兩側平舉打開。","在頂點夾緊肩胛骨。","慢慢放下。","胸口全程貼著靠墊。"],"2509":["胸口貼著上斜長凳俯臥，雙手反握槓鈴。","雙臂自然伸直下垂。","將槓鈴拉向肋骨下方。","將兩側肩胛骨往中間夾緊。","慢慢下放直到手臂伸直。","胸口全程貼著靠墊。"],"2511":["胸口貼著上斜長凳俯臥，雙手反握啞鈴。","雙臂自然伸直下垂。","將啞鈴拉向肋骨下方。","將兩側肩胛骨往中間夾緊。","慢慢下放直到手臂伸直。","胸口全程貼著靠墊。"],"2515":["背對低位滑輪站立，單手握住把手放在大腿前方。","手肘保持微彎。","將手臂往前平舉到肩膀高度。","身體避免往後傾。","慢慢放下。","完成預定次數後換手。"],"2523":["躺在下斜長凳上，雙腳固定好。","雙手輕放在腦後。","坐起身時將軀幹轉向一側。","在頂點稍作停留。","控制速度慢慢下放。","每一下交替轉向不同邊。"],"2525":["站上震動板，雙腳與肩同寬。","膝蓋保持微彎。","身體站直，收緊核心。","重心平均落在雙腳上。","維持 30-60 秒。","小心走下器材。"],"2526":["將前臂或雙手放在震動板上。","雙腿往後伸直。","從頭到腳跟呈一直線。","收緊腹肌並夾緊臀肌。","維持 20-40 秒。","小心放下身體。"],"2527":["一隻腳踩在震動板上，另一隻腳往後跨。","軀幹保持直立，往下蹲成弓步。","前膝維持在腳踝正上方。","在最低點短暫停留。","往上推回原位。","完成預定次數後換腳。"],"2544":["坐在下拉機上，將大腿固定好。","雙手採寬握正握握桿。","身體微微前傾，將握桿從頭後方往下拉到頸部根部。","將兩側肩胛骨往中間夾緊。","控制速度讓握桿往上回放。","動作放輕柔，頸部保持自然中立。"],"2555":["仰躺在地上，將環狀彈力帶套在大腿周圍。","雙膝彎曲，雙腳平放地面。","膝蓋往外推開對抗彈力帶。","將髖部往上抬起，直到身體呈一直線。","在頂點夾緊臀肌。","慢慢下放並重複。"],"2560":["站在長凳前方，雙腳與肩同寬。","保持挺胸。","髖部往後推並往下坐，直到臀部輕觸長凳。","短暫停留，但肌肉不要放鬆。","腳跟發力推地站起。","重複做到預定次數。"],"2561":["站在穩固的長凳側面。","屈膝並將雙手往後擺。","往上方與側邊跳起，落到長凳上。","屈膝緩衝，輕柔落地。","小心走下長凳。","左右交替重複動作。"],"2562":["站在矮階梯側面。","將靠近階梯的那隻腳踩上去。","往上蹬起並帶一個小跳躍。","輕柔落回階梯上。","控制速度走下來。","完成預定次數後換邊。"],"2563":["將繩索或把手連接到負重雪橇上。","雙膝微彎，握住繩索。","用划船的動作將雪橇拉向自己。","夾緊肩胛骨。","背部保持平直。","重複拉完預定距離。"],"2564":["雙手撐在藥球上，呈棒式姿勢。","收緊腹肌，身體保持一直線。","雙腳往外跳開。","雙腳跳回併攏。","保持兩側髖部水平。","持續做到預定次數。"],"2566":["仰躺在長凳或地面上，屈膝、雙腳踩平，雙手在胸口上方共握一顆啞鈴。","手肘微彎並固定這個角度。","將啞鈴沿弧線慢慢往頭頂後方下放，直到胸口感覺伸展。","沿同樣的弧線將重量拉回胸口上方。","肋骨下壓，下背不要拱起。"],"2567":["坐在地上，雙腿向前伸直。","右膝彎曲，將右腳跨放在左膝外側地面。","左手肘抵在右膝外側，輕輕將軀幹向右旋轉。","保持拉伸 20-30 秒，感受臀大肌與脊椎伸展，換邊重複。"],"2569":["雙腳站得比肩寬很多，腳尖微微朝外。","重心移向一側並彎曲該側膝蓋，髖部往下往後坐。","另一隻腳保持伸直，腳跟貼地、腳尖朝上。","彎曲側的腿發力推地，將身體移回中間。","換邊重複，全程保持挺胸。"],"2570":["採四足跪姿，雙手在肩膀正下方。","單腳維持屈膝往側邊抬起。","用膝蓋在空中慢慢畫圈。","保持髖部水平，脊椎穩定不動。","換方向畫圈，接著換腳重複。"],"2571":["四足跪姿開始，雙膝分開與臀同寬。","雙手在身前撐地。","重心前移至雙手，雙腿向後伸展成下犬式/倒 V 姿態。","將臀部向後上方推向天花板，背部打平，感受腿後與肩膀拉伸。","維持數秒，慢慢跪回原位。","重複所需次數。"],"2572":["坐姿屈膝，雙手往前延伸。","身體往後滾，雙腿往上抬並越過頭頂方向。","控制速度往前滾回，同時將雙腿伸直。","穩定停在 V 字坐姿，雙手朝雙腳延伸。","動作保持流暢，用腹肌帶動整個過程。"],"2589":["仰躺在長凳上，雙手各握一顆啞鈴舉在胸口上方，掌心朝內相對。","上臂保持不動，彎曲手肘將重量下放到頭部兩側。","感覺三頭肌充分伸展時停住。","將手臂伸直推回起始位置。","手肘全程朝向天花板。"],"2611":["調整推腿機座椅，使雙腿踩上踏板時膝蓋呈 90 度。","背靠椅背坐好，雙腳與肩同寬踩在踏板上。","手握兩側把手維持穩定。","單腿發力推開踏板，手臂與背靠緊椅墊。","完全推直處停頓片刻（膝蓋不鎖死），慢慢屈腿收回。","重複所需次數後換腿。"],"2612":["雙手握住跳繩握把，掌心朝內。","站立雙腳與肩同寬，膝蓋微彎。","手腕搖繩甩過頭頂，當繩子甩至腳前時輕巧起跳越過。","前腳掌輕盈著地，連續搖繩跳躍。","持續進行至指定次數或時間。"],"2616":["坐在滑輪下拉機上，正握抓住 V 型桿把手。","調整護墊夾緊大腿。","背部挺直微向後仰。","將 V 型把手向下拉向上胸部，手肘貼近軀幹。","底部大力收縮背肌。","慢慢送回 V 型桿，重複所需次數。"],"2656":["面向滑輪站立，將把手設在低位，單手掌心朝上握住。","手肘貼緊身體側面。","將把手朝肩膀方向彎舉，並收緊二頭肌。","慢慢下放直到手臂接近伸直。","完成所有次數後換手。"],"2658":["踏上橢圓機並握住兩側把手。","以流暢的滑雪節奏開始踩踏，雙手配合雙腿擺動。","保持身體直立，核心收緊。","在設定的時間內維持穩定配速。","結束前逐漸放慢速度。"],"2659":["調整座椅高度，讓把手對齊上胸。","往後坐穩並握住把手，雙腳平踩地面。","往前推直到手臂接近伸直。","收緊胸肌，接著慢慢回放。","背部貼緊靠墊，肩膀下沉不聳肩。"],"2660":["調整座椅高度，讓上臂平貼在靠墊上。","掌心朝上握住把手。","將把手朝肩膀方向彎舉。","在頂點收緊肌肉，再慢慢下放。","手肘不要離開靠墊，也不要讓重量直接掉下去。"],"2661":["坐在滑輪划船機上，雙腳踩穩踏板，膝蓋微彎。","握住 V 型把手，手臂伸直並坐挺。","將把手拉向肋骨下方，並夾緊肩胛骨。","慢慢回放直到手臂伸直。","保持挺胸，身體不要前後晃動。"],"2662":["調整座椅與胸墊位置，讓雙手伸直時剛好握住把手。","身體坐挺，胸口貼著靠墊。","將把手往下往後拉，手肘朝髖部方向帶。","將兩側肩胛骨往中間夾緊。","慢慢回放，肩膀保持下沉。"],"2663":["調整座椅與胸墊位置，讓雙手伸直時剛好握住把手。","身體坐挺，胸口貼著靠墊。","將把手往下往後拉，手肘朝髖部方向帶。","將兩側肩胛骨往中間夾緊。","慢慢回放，肩膀保持下沉。"],"2664":["調整座椅高度，讓把手對齊中胸位置。","坐好讓胸口貼著靠墊，握住把手。","手肘往後拉，並夾緊肩胛骨。","短暫停留，再慢慢回放。","軀幹全程貼緊靠墊。"],"2665":["調整座椅與腿部靠墊，接著握住兩側寬把手。","身體坐挺並挺胸。","以手肘帶動，將把手往下拉向上胸。","收緊背闊肌，再讓把手慢慢往上回放。","避免大幅度後仰或借力甩動。"],"2666":["坐好並將前腳掌踩在踏板上，大腿上方壓緊靠墊。","解開安全扣，將腳跟往下放直到感覺伸展。","前腳掌發力往上推到最高點。","稍作停留並收緊小腿。","慢慢下放到完全伸展。"],"2671":["將槓鈴設定在膝蓋高度，雙手靠近握住槓鈴。","膝蓋微彎，背部打平、髖部往後推俯身。","手肘貼近身體，將槓鈴拉向肋骨下方。","在頂點收緊背部肌群。","控制速度將槓鈴下放到手臂完全伸直。"],"2683":["坐姿，雙手掌心朝下握住槓鈴，前臂貼在大腿或長凳上。","手腕放鬆下垂，讓槓鈴自然垂下。","手腕往上翹起，將槓鈴儘量抬高。","在頂點短暫停留。","慢慢放下，前臂保持貼穩不動。"],"2689":["背對低位滑輪站立，單手握住把手。","手臂保持接近伸直，往前平舉到肩膀高度。","在頂點短暫停留。","控制速度慢慢下放。","完成預定次數後換手。"],"2690":["站立，單手握住啞鈴垂在身體側面。","手肘保持微彎。","將手臂往側邊平舉到肩膀高度。","慢慢下放，身體不要晃動借力。","完成單邊所有次數後換邊。"],"2705":["俯臥趴在地上，雙臂向前伸直，雙手各握一啞鈴。","手腕向下旋轉使掌心朝下。","保持雙臂伸直，收縮前臂手腕將啞鈴抬離地面。","盡可能向上伸展手腕。","維持收縮片刻，慢慢放回地面。","重複所需次數。"],"2706":["仰臥平躺，雙腿伸展，雙手各持一啞鈴放於身側。","手腕轉動使掌心朝上，手肘貼側。","手腕向上屈起，擠壓前臂肌肉。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"2707":["雙腳與肩同寬跨站在原木槓上方，雙手握緊把手。","背部打平，先將原木槓拉到大腿上，再將髖部往前推。","手肘抬高，將原木槓翻到胸前架好。","微蹲屈膝，接著用力往上蹬並將原木槓推過頭頂。","手臂伸直鎖死，再控制速度下放。","先從輕重量開始，全程收緊核心。"],"2708":["與搭檔面對面坐下，雙腳互抵，雙手握住同一根木棍。","收緊核心。","握緊木棍，用力拉向自己。","背部保持平直，抵抗搭檔的拉力。","維持穩定發力，並在每次拉動結束時控制好動作。"],"2709":["面向重物，雙腳寬站，雙手握住繩索。","核心收緊，身體微微後傾。","雙手一前一後交替拉動繩索。","維持穩定的節奏。","背部保持平直，流暢地伸手抓繩並往回拉。"],"2710":["背對卡車站立，將繩索拉過身體前方握好。","身體前傾，雙腳踩穩地面。","雙腿用力蹬地，邁開短而有力的步伐。","核心收緊，繩索貼近身體。","拉完預定距離後休息。"],"2711":["在身前抱住重物，往下蹲到全深蹲位置。","保持挺胸。","維持低蹲姿勢，邁開小步往前走。","核心收緊，膝蓋對齊腳尖方向。","走完預定距離後站起休息。"],"2712":["將沙袋從地面抱起，緊緊抱在胸前。","身體站直，收緊核心。","以穩定的節奏邁小步往前走。","保持軀幹直立，不要過度後仰。","抵達終點時控制速度將沙袋放下。"],"2713":["將鐵塊翻到肩膀高度，雙腳與髖部同寬站穩。","收緊核心並夾緊臀肌。","將鐵塊推過頭頂，直到手臂伸直鎖死。","在頂點稍作停留。","控制速度將鐵塊放回肩膀。"],"2714":["雙手各拿起一個重物並站直。","將雙臂往兩側平舉到肩膀高度。","收緊核心，維持這個姿勢。","肩膀下沉，避免聳肩。","撐越久越好，接著控制速度放下。"],"2715":["將木頭扛上單側肩膀並抓穩平衡。","身體站直，收緊核心。","邁開短而穩定的步伐行走。","維持重物平衡，身體不要偏向一側。","控制速度放下，接著換邊肩膀。"],"2716":["抱起橫桿重物並貼緊身體。","收緊核心並保持挺胸。","以穩定的步伐繞圈行走。","維持身體平衡，不要往後歪斜。","結束時控制速度將重物放下。"],"2717":["雙手各拿起一個重物並站直。","將雙臂往兩側抬高到與肩膀平行。","收緊核心，維持姿勢不動。","肩膀保持下沉，手腕打直。","撐越久越好，接著控制速度放下。"],"2718":["拿起重物並站直。","將雙臂往前平舉到肩膀高度。","收緊核心維持姿勢。","肩膀保持下沉，身體避免往後仰。","撐越久越好，接著控制速度放下。"],"2719":["走進推舉架內並握住把手。","將把手抬到肩膀高度，雙腳站穩。","收緊核心並將把手推過頭頂。","手臂完全伸直鎖死。","控制速度放回肩膀高度。"],"2720":["雙腳與肩同寬站立，將負重平台扛在肩膀上。","收緊核心。","挺胸往下深蹲，膝蓋對齊腳尖方向。","腳跟發力往上推回原位。","站直並在頂點鎖死關節。"],"2721":["雙腳與肩同寬跨站在第一個重物上方。","髖部往後推，背部打平並抱緊重物。","靠髖部往前推的力量將重物抱起。","抱著重物走到高台前並放上去。","走回起點換下一個重物重複，全程收緊核心。"],"2722":["跨站在巨石上方，往下深蹲將巨石抱住。","髖部往前推，將巨石拉到大腿上。","將巨石沿著胸口往上滾動。","完全伸展髖部，將巨石放上高台。","控制速度將巨石放下並重新準備。"],"2723":["握住獨輪車把手，背部打平將車尾抬起。","收緊核心。","邁開有力的步伐往前推。","手臂保持伸直，身體維持穩定對齊。","抵達終點時控制速度放下。"],"2724":["跨站在圓石上方，往下深蹲並用雙臂環抱圓石。","髖部往前推，將圓石拉到大腿上。","將圓石沿著胸口往上滾動。","完全伸展髖部，將圓石放上高台。","控制速度將圓石放回地面並重新準備。"],"2725":["抱起重物並貼在胸前。","收緊核心並站直。","一步一階往上走。","全腳掌發力踩穩，保持挺胸。","到達頂端後控制速度將重物放下。"],"2726":["抓起兩側重物握把並站直。","雙臂往兩側伸展撐住。","收緊核心，肩膀保持下沉。","盡力維持這個姿勢越久越好。","結束時控制速度放下重量。"],"2727":["將盾牌重物抱起，穩定貼在身前。","身體站直，收緊核心。","以穩定的配速往前走。","保持軀幹直立。","結束時控制速度將重物放下。"],"2728":["手肘抬高，將重物緊緊抱在胸前。","雙腳與肩同寬站立。","保持挺胸往下深蹲。","腳跟發力往上推起。","在頂點將髖部完全推直鎖死。"],"2729":["雙腳與髖部同寬站立，槓鈴位於足弓正上方。","髖部往後推往下俯身，雙手在膝蓋外側握槓，保持挺胸、背部平直。","收緊核心，雙腳用力踩地，讓槓鈴貼近雙腿往上拉。","髖部往前推站直身體，接著控制速度將槓鈴放回地面。"],"2730":["靠近輪胎站立並往下深蹲，手指扣進輪胎底部邊緣。","胸口貼緊輪胎，背部打平，髖部壓低。","雙腿與髖部爆發力往上蹬，隨身體站起將輪胎抬高。","雙手與肩膀用力將輪胎往前推倒，接著往前跨步準備下一次翻輪胎。"],"2731":["雙腳與肩同寬，雙手在身前低處握住重物。","髖部往後推，同時將重物往雙腿之間後擺。","髖部與雙腿猛力往上蹬伸，將重物往上擺過頭頂。","鬆手讓重物飛過高桿，接著退後一步準備下一次拋擲。"],"2732":["雙腳與肩同寬跨站在啞鈴上方，單手握住啞鈴。","靠髖部推進的爆發力將啞鈴拉上肩膀，身體順勢微蹲承接。","微蹲屈膝，接著用力往上蹬，將啞鈴推過頭頂直到手臂伸直鎖死。","控制速度將啞鈴先放回肩膀再放到地面，接著換手。"],"2733":["雙腳與肩同寬跨站在粗槓上方，雙手握緊槓身。","背部打平，將粗槓沿著大腿往上拉並翻到胸前。","雙腿微蹲再用力往上蹬，將粗槓推過頭頂直到手臂鎖死。","控制速度將粗槓先放回胸前，再放回地面。"],"2734":["站在負重農夫槓內側並握緊把手，站起讓重量垂在身體兩側。","保持挺胸、肩膀往後收穩，核心收緊。","邁開短促快速的步伐，往前走完設定距離。","停下腳步，背部保持平直將重量放回地面，接著休息。"],"2735":["走進軛架下方，讓橫樑壓在上背，雙手握住兩側立柱。","收緊核心並往上站起，讓軛架離開地面支撐。","軀幹保持直立，邁開快速且受控的步伐往前走。","抵達終點時，小心地將軛架放回地面。"],"2736":["調整座椅高度，坐穩機台，膝蓋卡在護墊下，雙腳踩實。","正握抓把手，握距略寬於肩寬。","坐直挺胸雙肩後展，下背自然微弓。","手肘引導將握把向下拉向胸前，肩胛骨向內夾緊。","底部停頓片刻，慢慢放回握把。","重複所需次數。"],"2737":["身體站直，手扶支撐物維持平衡。","支撐腳的膝蓋保持微彎。","將另一隻腳保持伸直往後抬起，下背不要拱起。","在頂點夾緊臀肌。","控制速度放下，完成預定次數後換腳。"],"2738":["仰躺在地板上，雙膝彎曲，雙手各拿一個啞鈴舉在胸前。","上臂保持不動，彎曲手肘把重量往頭部方向下放。","在啞鈴快碰到地板前停住。","伸直手臂，把重量推回上方。","全程保持手肘朝上。"],"2740":["面對牆壁站立，雙手貼牆，間距比肩膀寬。","雙腳往後退，讓身體傾斜呈一直線。","彎曲手肘，讓胸口靠近牆壁。","推回起始位置。","保持髖部與肩膀呈一直線。"],"2741":["站直，雙腳分開與肩同寬，反手握住槓鈴，握距寬於肩。","手肘緊貼軀幹固定，上手臂不動。","收縮二頭肌將槓鈴向上彎舉向肩膀。","頂端停頓片刻，慢慢降回槓鈴。","重複所需次數。"],"2742":["坐在器材上，雙腳踩在踏箱上，靠墊壓在髖部上方。","收緊核心，腳跟出力往下踩。","抬起髖部，直到肩膀到膝蓋呈一直線。","在頂點夾緊臀肌。","慢慢下放回到起始位置。"],"2743":["坐在器材上，背部靠墊，雙腳平踩地面。","將髖部靠墊固定在大腿上方。","腳跟出力推地，抬起髖部。","在頂點夾緊臀肌。","穩定控制下放，不要讓重量撞擊。"],"2744":["將腰帶或綁帶扣在低位滑輪上，背對配重塔站立。","雙腳與肩同寬，雙手把滑輪配件扶在髖部。","髖部微幅往後推，接著用力往前頂出。","在頂點夾緊臀肌。","慢慢回到起始位置，全程保持肋骨下壓。"],"2745":["趴在長凳上，髖部貼齊邊緣，雙腿自然垂下。","如果史密斯槓調在低位，用腳跟勾住槓鈴。","伸展髖部把雙腿往上抬，直到與身體呈一直線。","在頂點夾緊臀肌。","慢慢下放，不要甩動。"],"2746":["調整好器材後走進去，讓靠墊壓在肩膀上。","抬頭挺胸，穩定控制往下蹲。","雙腳出力往上推起。","起身時膝蓋微微往外推。","全程收緊核心。"],"2747":["坐在器材上，依器材設定把靠墊夾在雙腿之間或外側。","收緊核心。","髖部往上頂起的同時，雙腿用力往內夾。","在頂點稍微停留夾緊。","穩定控制下放。"],"2748":["跪在器材軟墊上，雙手握住把手。","將訓練腿的後側貼在槓桿靠墊上。","把腿往後上方推，直到髖部完全伸展。","在頂點夾緊臀肌。","慢慢下放，完成後換腳。"],"2749":["坐在器材上，雙腳踩在踏板上，約與肩同寬。","解開安全扣手把。","彎曲膝蓋下放踏板，直到膝蓋呈約 90 度。","腳跟出力將雙腿推直。","膝蓋不要完全鎖死。"],"2750":["站在牆邊，一手拿啞鈴，另一手扶牆保持平衡。","單腳往後抬起。","髖部往後推，將啞鈴順著站立腿往下放。","保持背部平直。","夾緊臀肌站直身體，完成後換腳。"],"2751":["雙腳寬距站在踏箱上，腳尖朝外。","雙手在身前拿著一個壺鈴或啞鈴。","抬頭挺胸，臀部往雙腿之間下坐。","在舒適範圍內盡量蹲低。","雙腳出力推地站起。"],"2752":["雙腳前後跨出一大步站立。","後腳膝蓋朝地板方向下放。","前腳膝蓋保持在腳踝正上方。","前腳腳跟出力推地起身。","完成所有次數後換腳。"],"2753":["站在低平台上，雙腳踩住彈力帶，胸前抱著一個壺鈴。","在可控制的範圍內蹲到最低。","腳跟踩穩，抬頭挺胸。","雙腳出力推地站起。","起身過程保持彈力帶緊繃。"],"2754":["坐在地板上，上背靠著長凳，將重量放在髖部上方。","雙腳平踩地面，膝蓋彎曲。","腳跟出力推地，抬起髖部。","在頂點夾緊臀肌。","慢慢下放並重複動作。"],"2755":["將腳踝扣環接在低位滑輪上，側對配重塔站立。","手扶支撐物保持平衡。","腳尖微微朝外轉。","將訓練腿往側邊抬起。","慢慢放回，完成後換腳。"],"2756":["將腳踝扣環接在低位滑輪上，側對配重塔站立。","手扶支撐物保持平衡。","腳尖微微朝內轉。","將訓練腿往側邊抬起。","慢慢放回，完成後換腳。"],"2757":["仰躺，雙腳腳底貼合，膝蓋自然往兩側打開。","腳跟靠近髖部。","雙腳出力推地，抬起髖部。","在頂點夾緊臀肌。","慢慢下放並重複動作。"],"2758":["雙手把滑輪把手抱在胸前，臀部往後坐進入深蹲。","保持挺胸。","腳跟出力完全站直。","在頂點夾緊臀肌。","穩定控制往下蹲。"],"2760":["上背靠著長凳坐好，彈力帶跨過髖部並固定在兩側。","雙腳平踩地面。","對抗彈力帶阻力，將髖部往上推。","在頂點夾緊臀肌。","慢慢下放。"],"2761":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","坐姿，單腿伸出，腳跟輕放在地板上。","在舒適範圍內，將腳趾與腳背盡量往脛骨方向勾起。","稍微停留，再慢慢把腳放回原位。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2762":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","坐姿，單腿伸出，腳部放鬆。","像踩油門一樣，將腳趾往前往下壓。","在末端稍微停留，再回到中立位置。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2763":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","上臂保持固定，手肘彎曲。","慢慢伸直手臂，直到接近完全伸展。","稍微停留，保持肩膀放鬆、上臂固定不動。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2764":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","手臂自然垂在身體側邊，掌心朝前。","彎曲手肘，將手往肩膀方向抬起。","稍微停留，再慢慢下放，不要甩動。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2765":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","手肘貼近身體側邊並彎曲呈 90 度，掌心朝上。","旋轉前臂，讓掌心轉為朝向地板。","手肘保持不動，在末端稍微停留。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2766":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","手肘貼近身體側邊並彎曲呈 90 度，掌心朝下。","旋轉前臂，讓掌心轉為朝向天花板。","手肘保持不動，在末端稍微停留。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2767":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","手扶支撐物站直，重心放在單腳上。","另一腿打直往側邊抬起，腳尖朝前。","稍微停留，再慢慢下放，軀幹不要歪斜。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2768":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","手扶支撐物站直，重心放在單腳上。","另一腿先微微往側邊抬起。","將腿往內收回並跨過站立腿前方，稍微停留。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2769":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","手扶支撐物站直，重心放在單腳上。","另一腿保持大致伸直，往正後方擺動。","在頂點夾緊臀肌，避免下背過度拱起。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2770":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","手扶支撐物站直，重心放在單腳上。","將另一腳膝蓋在身前抬起，接近髖部高度。","稍微停留，再慢慢下放，背部不要駝起。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2771":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","挺胸坐在長凳或椅子上，單腳膝蓋彎曲呈 90 度。","大腿保持不動，將小腿往內擺動，帶動髖關節外旋。","稍微停留，再穩定控制回到起始位置。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2772":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","挺胸坐在長凳或椅子上，單腳膝蓋彎曲呈 90 度。","大腿保持不動，將小腿往外擺動，帶動髖關節內旋。","稍微停留，再穩定控制回到起始位置。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2773":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","挺胸坐在長凳或椅子上，雙腳離地。","將單腳膝蓋伸直，直到腿部接近完全伸展。","在頂點收緊大腿，再慢慢下放。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2774":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","手扶支撐物站直，重心放在單腳上。","彎曲另一腳膝蓋，將腳跟往臀肌方向抬起。","雙腿大腿保持並攏，稍微停留後慢慢下放。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2775":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","站直，雙臂自然垂在身體兩側。","單手往側邊抬起，直到約與肩同高。","慢慢下放，不要聳肩。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2776":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","站直，單手往側邊平舉至肩膀高度。","穩定控制，將手臂往下拉回身體側邊。","軀幹保持不動，結束時手臂貼近身體。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2777":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","站直，手臂自然垂在身體側邊。","手臂保持伸直，往身體後方擺動。","避免身體前傾，稍微停留後回到起始位置。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2778":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","站直，雙臂垂在身體兩側，掌心朝內。","單手往前往上抬起，至肩膀高度或略高位置。","保持肋骨下壓，再慢慢下放。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2779":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","站姿，手肘貼在身體側邊並彎曲呈 90 度，前臂朝前。","手肘貼緊身體側邊，將前臂往外旋轉。","稍微停留，再慢慢回到原位。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2780":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","站姿，手肘貼在身體側邊並彎曲呈 90 度，前臂朝前。","手肘貼緊身體，將前臂往腹部方向內旋。","稍微停留，再慢慢回到原位。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2781":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","站直，單手在身前平舉至肩膀高度。","在舒適範圍內，將手臂沿水平弧線往外往後展。","手臂維持在肩膀高度，稍微停留後回到原位。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2782":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","站直，單手往側邊平舉至肩膀高度。","將手臂沿水平弧線往前帶，跨過身體前方。","手臂維持在肩膀高度，稍微停留後回到原位。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2783":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","站直，手臂在身前抬至肩膀高度。","保持水平，將手臂往後往外拉。","輕輕夾緊肩胛骨，再慢慢回到原位。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2784":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","站直，手臂往側邊平舉至肩膀高度。","保持水平，將手臂往前帶到胸前。","稍微停留，再慢慢回到側邊。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2785":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","雙腳與髖同寬站立，雙手叉腰。","在舒適範圍內輕輕往後仰，讓下背微拱。","稍微停留，再回到直立姿勢。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2786":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","雙腳與髖同寬站立，膝蓋微彎。","下背往前拱圓，下巴與骨盆向內收。","稍微停留，再回到直立姿勢。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2787":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","雙腳與髖同寬站立，雙臂垂在身體兩側。","身體往側邊彎曲，同時單手順著大腿外側往下滑。","保持髖部水平，回到直立姿勢後再往另一側彎。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2788":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","雙腳與髖同寬站立，雙手交叉抱胸。","髖部保持朝前，將軀幹往單側旋轉。","回到中間，再往另一側旋轉。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2789":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","前臂平放在桌面上，手掌懸空在桌緣外，大拇指朝上。","將手掌往小指方向下壓傾斜。","稍微停留，再穩定控制回到中立位置。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2790":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","前臂平放在桌面上，手掌懸空在桌緣外，掌心朝下。","手腕往後折，將手背往上抬起。","稍微停留，再慢慢下放。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2791":["抬頭挺胸站立或坐好，身體放鬆，關節保持在自然的起始位置。","前臂平放在桌面上，手掌懸空在桌緣外，掌心朝上。","手腕往內彎，將手掌朝前臂方向捲起。","稍微停留，再慢慢下放。","流暢重複 10 到 15 次，若單邊操作則完成後換邊。"],"2792":["從高棒式開始，雙手在肩膀正下方。","雙腳同時往外跳開。","雙腳跳回併攏。","保持髖部水平、核心收緊。","以穩定節奏持續動作。"],"2793":["從前臂撐地的肘撐棒式開始。","雙手依序貼地推起，轉換成高棒式。","雙手前臂依序放回地板。","保持髖部穩定不晃動。","每次交替先動的手臂。"],"2795":["雙手各拿一個啞鈴，面對穩固的跳箱或踏箱站立。","單腳踩上踏箱，出力往上推直到站上箱面。","同一隻腳往後踩下地面，直接退入後弓步。","推地回到起始位置，全程保持軀幹直立。","單腳完成所有次數後換邊。"],"2796":["站在階梯或踏台前，雙手各持一啞鈴垂於體側。","右腳踏上踏台，確保全腳掌踩實。","踩穩右腳跟蹬起身體，將左腳抬上踏台併攏。","雙腳站穩後，左腳先向後退下踏台，右腳留在台上。","換腳踩踏重複操作。","交替進行至指定次數。"],"2797":["將槓鈴扛在上背，雙腳與肩同寬站立。","往下深蹲，接著輕輕往上跳起並輕柔落地。","單腳往後退一步進入後弓步，後膝朝地板下放。","前腳出力推地回到站姿。","每次交替雙腳，全程保持挺胸。"],"2798":["雙腳分開與肩同寬站立，槓鈴扛在上背部。","屈膝屈髖下沉成深蹲。","向上爆發力起跳，雙腳騰空。","雙腳輕巧著地順勢單腿向後退一步成反向弓箭步。","下沉至前大腿平行地面，背部打直。","踩穩前腳跟蹬回起始站姿。","換另一側重複深蹲跳接反向弓箭步。","交替進行至所需次數。"],"2799":["坐在重訓椅上，背部挺直，槓鈴置於大腿近髖處。","保持腿部伸直，單腿盡可能向上抬高，另一腳踩地。","抬起的腿放回，換另一腿重複。","雙腿交替進行至指定次數。"],"2800":["坐在重訓椅上，背打直，槓鈴置於大腿。","雙手扶在長凳兩側支撐。","保持雙腿伸展，單腿向上抬至與地面平行。","放回，換另一腿重複抬起。","雙腿交替重複至所需次數。"],"2801":["平躺，雙腿伸展，雙手放身側。","雙膝彎曲抬離地面抱向胸前。","抬腿同時將臀部向一側扭轉，雙膝朝向對側肩膀（反向扭轉捲腹）。","頂點停頓片刻，慢慢放回。","換向另一側扭轉重複。","雙側交替進行至所需次數。"],"2802":["平躺，雙腿伸展，雙臂貼地。","雙手墊在臀部下方支撐下背。","收緊腹肌將雙腿打直抬離地面。","將臀部向一側旋轉，直腿朝向對側肩膀上提。","頂峰停頓片刻，慢慢降回。","換另一側扭轉重複。","交替進行至所需次數。"],"2803":["雙腳分開與肩同寬站立，雙手各持一啞鈴垂於體側。","挺胸收腹，屈膝屈髖向後下蹲。","蹲至大腿平行地面或略低。","底部停頓片刻，踩穩腳跟推回站姿。","重複所需次數。"],"2804":["一手拿啞鈴，另一手扶在穩固的支撐物上。","雙腳與肩同寬站立，腳尖微微朝外。","髖部往後往下坐，直到大腿約與地面平行。","保持挺胸，腳跟出力推地站起。","視需要可在做到一半時換手拿啞鈴。"],"2805":["雙腳與臀部同寬站立，右手持啞鈴。","左腳向後搭在後方踏台或矮凳上（單腿保加利亞分腿硬舉）。","背部打直，收緊核心，屈髖向前俯身下放啞鈴。","下沉同時感受右側大腿後側拉伸，保持頭脊成一直線。","拉伸至極限處，臀肌發力站回原位。","重複所需次數後換邊。"],"2806":["手持啞鈴，單腳腳尖輕放在身後的踏箱上。","前膝微彎，髖部往後推，將啞鈴順著腿部往下放。","保持背部平直，在大腿後側活動度允許的範圍內下放。","髖部往前推，站直身體。","完成所有次數後換腳。"],"2807":["雙腳寬距站立、腳尖朝外，雙手合握一個啞鈴。","髖部往後推，將啞鈴往後擺盪到雙腿之間。","保持背部平直、抬頭挺胸。","髖部往前推並站直，讓啞鈴擺盪至髖部高度。","在頂點夾緊臀肌。"],"2808":["雙腳分開寬於肩寬，腳尖朝外（相撲站姿）。","雙手在身前垂握一個啞鈴，手臂伸展。","屈膝下蹲將臀部沉下，背部打直。","啞鈴垂在兩腿之間。","腳跟發力向前展髖，將啞鈴向上拉至骨盆前。","頂峰夾緊臀部，隨後下蹲放回兩腿間。","重複所需次數。"],"2809":["將槓鈴扛在上背，雙腳前後跨出呈分腿站姿。","保持軀幹直立、核心收緊。","身體垂直往下蹲，直到後膝接近地面。","前腳出力推地起身。","完成所有次數後換腳。"],"2810":["雙腳分開與肩同寬站立，槓鈴扛在上背部。","右腳向前跨出一大步，軀幹維持直立。","屈膝屈髖下沉，直到右大腿與地面平行。","停頓片刻，踩穩右腳跟蹬回起始位置。","換左腿前跨重複，交替進行至所需次數。"],"2811":["雙手將槓鈴托在肩膀高度，雙腳與肩同寬站立。","單腳往外跨出，髖部與軀幹跟著轉向，蹲入旋轉弓步。","出力推地站起的同時，將槓鈴往頭頂上方推舉。","將槓鈴放回肩膀位置。","每次交替左右邊。"],"2812":["站在跳箱或長凳前，雙手各持一啞鈴垂於體側。","右腳踏上長凳，全腳掌踩實。","右腳跟蹬地站上長凳，順勢將左膝抬向胸口。","在最高點停頓片刻，慢慢將左腳退回地面，右腳留在長凳上。","換左腳踏上重複跨步抬膝。","雙腳交替進行至指定次數。"],"2814":["雙腳與肩同寬站立，單手拿重量自然垂在身前低處。","利用髖部推力搭配身體微幅旋轉，將重量上拉到肩膀。","膝蓋微蹲的同時，雙腳與髖部轉回正前方。","將重量往頭頂推舉，直到手臂完全伸直。","穩定控制下放並重複，完成後換邊。"],"2815":["仰躺，雙臂伸直在頭頂上方拿著健身球。","雙手與雙腿同時往上抬起，身體捲成 V 字形。","將健身球從手上交接到雙腳之間。","雙腳夾住球，慢慢下放回到地面。","重複動作，把球傳回手上。"],"2828":["雙手各握一端繩頭，呈微蹲站姿。","收緊核心，手肘保持微彎不鎖死。","雙臂快速且受控地往兩側抬起至肩膀高度。","下放並以穩定的快節奏重複動作。","以 20 到 30 秒為一組進行間歇訓練。"],"2830":["雙手握住雪橇把手，雙腳併攏站直。","單腳往後退一步進入弓步，後膝朝地板方向下放。","保持軀幹直立，前腳膝蓋對齊腳踝上方。","前腳出力推地回到站姿。","每次交替雙腳。"],"2831":["雙腳放在長凳上，雙手撐地，髖部高抬呈倒 V 字形。","雙腿保持伸直，收緊核心。","彎曲手肘，將頭部朝地板方向下放。","往上推回，直到手臂伸直。","保持手肘與身體夾約 45 度角。"],"2834":["軀幹加上負重，雙手握住懸吊把手，身體往後傾斜呈一直線。","手臂伸直，腳跟踩在地板上。","將胸口往把手方向拉起，夾緊肩胛骨。","在頂點稍微停留。","慢慢下放直到手臂完全伸直。"],"2835":["坐在椅子上，雙手把滑輪把手抱在胸前。","雙腳靠攏。","身體微微前傾。","腳跟出力推地站起。","穩定控制坐回椅子上。"],"2836":["面對低位滑輪站在踏箱上，雙手握住把手。","雙膝保持接近伸直。","髖部往後推，同時下放把手。","保持背部平直。","夾緊臀肌站直身體。"],"2837":["面對滑輪站在踏箱上，雙手握住把手。","單腳往後踩下踏箱進入弓步。","後腳膝蓋朝地板方向下放。","前腳出力推地回到箱上。","完成所有次數後換腳。"],"2838":["仰躺，雙手輕扶頭後。","抬起雙腿，並將肩膀往上捲起。","單腿伸直，同時將對側手肘往另一腳膝蓋靠近。","以緩慢踩腳踏車的節奏交替換邊。","保持下背貼緊地面。"],"2839":["仰躺，雙膝彎曲，雙手輕扶頭後。","將頭部與肩膀往上捲起。","軀幹往單側旋轉。","轉回中間並下放。","左右交替進行。"],"2840":["仰躺，將雙腿往頭頂後方翻過去。","雙手握住單腳腳踝。","另一腿往上方伸直。","穩定控制交替換腿。","慢慢將身體滾回地面。"],"2841":["仰躺，雙臂放在身體兩側，雙腿往上抬起。","稍微抬起髖部，將雙腿往單側擺動。","雙腿往下畫一圈繞回。","將雙腿帶回起始位置。","換反方向重複。"],"2842":["雙腿交叉盤坐，雙手抓握雙腳。","往後滾動到肩膀位置。","雙腿互換上下交叉方向。","往前滾回坐姿。","保持動作流暢。"],"2843":["仰躺，將頭部與肩膀往上捲起。","雙手抱膝靠近胸口。","雙臂往頭頂延伸，同時將雙腿伸直。","雙臂畫圈收回，同時將膝蓋抱回胸前。","保持下背貼地。"],"2844":["俯臥，雙臂往前伸直。","拉長頸部線條。","將雙臂、胸口與雙腿抬離地面。","稍微停留。","慢慢下放。"],"2845":["坐姿，雙手在身後撐地，雙腿抬起。","保持挺胸開肩。","將髖部往單側旋轉。","雙腿畫圈帶回中間。","換邊進行。"],"2846":["仰躺，抬起頭部與肩膀。","雙腿抬成桌面姿勢或直接伸直。","雙臂小幅度上下快速拍動。","吸氣拍 5 下，吐氣拍 5 下。","目標完成 100 下拍動。"],"2848":["從單手撐地的側棒式開始。","保持身體呈一直線。","將上方腿往上抬起。","稍微停留。","下放並換邊進行。"],"2849":["從高棒式開始。","收緊核心。","將單腿往上抬起幾公分。","下放並換腿。","保持髖部水平。"],"2850":["仰躺，雙臂放在身體兩側。","彎曲雙膝。","抬起雙腿，直到大腿與地面垂直。","慢慢下放，下背不要拱起。","全程保持下背貼穩地板。"],"2851":["俯臥，雙手在背後交扣。","雙腳腳跟朝臀肌方向踢動。","抬起胸口，同時雙臂往後延伸。","下放回到地面。","流暢重複動作。"],"2852":["側躺，雙腿上下疊放。","用手臂支撐頭部。","將上方腿往上抬起。","慢慢下放。","完成所有次數後換邊。"],"2853":["仰躺，雙手輕扶頭後。","將頭部與肩膀往上捲起。","捲起身體直到坐直。","身體往前延伸。","穩定控制往後躺回地面。"],"2854":["仰躺，單腿往上伸直。","保持骨盆穩定不動。","用抬起的那隻腳畫小圈。","換反方向畫圈。","換腳進行。"],"2855":["俯臥，用前臂撐起上半身。","保持胸口挺起。","單腳腳跟朝臀肌方向連踢兩下。","下放並換腳。","保持髖部貼穩地面。"],"2856":["坐姿，雙腿打開呈 V 字形，雙手抓住腳踝。","在尾骨上找到平衡。","往後滾動到肩膀位置。","往前滾回並再次停住平衡。","全程保持背部拱圓。"],"2857":["俯臥，雙手往後抓住腳踝。","抬起胸口與雙腿。","身體前後搖擺。","保持動作流暢。","下放身體完成動作。"],"2858":["仰臥，雙手伸過頭頂。","抬起雙手，將頭與胸口捲起。","脊椎一節一節向上捲起。","雙手越過雙腿向前延伸。","慢慢躺回地板。"],"2859":["坐姿屈膝收攏，雙手抱住小腿脛骨。","將背部拱圓。","向後滾動到肩膀著地。","滾回坐姿並保持平衡。","全程保持下巴內收。"],"2860":["仰臥，雙腿抬起。","將雙腿往頭頂後方翻過去。","雙腿打開至與髖部同寬。","慢慢滾回地板。","雙手持續往下壓穩地板。"],"2861":["坐姿，雙腿打開，雙手向兩側平舉。","將軀幹轉向一側。","手伸向對側腳的外側。","回到中間。","換邊重複。"],"2862":["仰臥，抬起髖部並用雙手撐住。","將雙腿往上抬。","一腿往下放，另一腿留在上方。","雙腿交替。","保持動作穩定。"],"2863":["仰臥，雙膝彎曲。","抬起髖部呈橋式。","將一條腿往上伸直。","放下後換腿。","慢慢將脊椎滾回地板。"],"2864":["側坐挺直，下側手壓穩墊子，雙腿交疊。","抬起髖部，讓身體呈一直線斜角。","上側手往頭頂延伸，身體越過支撐手向側邊彎曲。","保持髖部抬高，回到斜線位置。","有控制地放下並重複，接著換邊。"],"2866":["採側撐姿勢，單手撐在墊上，雙腳交疊。","抬起髖部，上側手伸向天花板。","轉動軀幹，將上側手穿過身體下方。","再次打開胸口，手伸向天花板。","全程保持髖部抬高，完成後換邊。"],"2868":["坐姿挺直，雙腿伸直，雙手向兩側平舉。","勾起腳尖，頭頂向上延伸拉長。","軀幹轉向一側，輕輕脈動再多轉一點點。","回到中間，胸口不要塌陷。","轉向另一側並重複。"],"2869":["俯臥，雙手放在肩膀下方，雙腿併攏。","推起身體呈天鵝式，讓胸口離開墊子。","雙手向前浮起，同時讓胸口與雙腿帶動身體向上搖擺。","以流暢且受控的節奏前後搖擺。","保持頸部拉長，腹部輕輕內收。"],"2870":["俯臥，雙手向頭頂延伸，雙腿伸直。","將雙手、胸口與雙腿稍微抬離墊子。","對側手腳以小幅度快速上下交替擺動。","保持腹部內收，頸部拉長。","持續 20 到 30 秒，然後休息。"],"2871":["仰臥，雙腿伸直，雙手伸過頭頂。","向上捲起同時抬起雙腿，讓身體呈 V 字形。","雙手往前伸與雙腿平行，在坐骨上保持平衡。","背部打直繃緊，短暫停留。","有控制地慢慢躺回，然後重複。"],"2872":["仰臥，將頭與肩膀捲離墊子。","一膝拉向胸口，雙手扶住該側小腿脛骨。","另一腿往低角度伸直延伸。","以穩定的節奏交替雙腿。","保持下背貼穩墊子。"],"2873":["坐姿挺直，雙腿伸直與髖部同寬，雙手向前平舉。","腹部內收，勾起腳尖。","想像越過一顆大球，脊椎一節一節向前捲曲。","在最低點停留一個呼吸。","一節一節捲回坐姿挺直，然後重複。"],"2874":["從高棒式開始，雙手在肩膀正下方。","從頭到腳跟保持一直線。","單腿抬起幾吋，髖部不要偏移。","放下後換另一腿重複。","保持腹部收緊，頸部拉長。"],"2875":["單膝跪地，另一腿向側邊伸直。","下側手撐在墊上，上側手輕放頭後。","上側腿向前踢，再有控制地向後擺。","保持軀幹穩定挺直。","完成設定次數後換邊。"],"2876":["坐姿挺直，雙腿伸直並在腳踝處交叉。","向後滾並將雙腿抬過頭頂，接著交換雙腳交叉位置。","向上滾起呈 V 字平衡，雙腿保持抬高。","雙手在身後交握，接著越過雙腿向前延伸。","動作保持流暢，用腹部控制每次滾動。"],"2877":["在尾骨上保持平衡坐姿，雙膝打開，雙手從內側穿過抓握腳踝。","收下巴，將背部拱成球狀。","向後滾到肩膀位置，雙腳互拍。","滾回平衡坐姿，雙腳再拍一下。","保持滾動流暢，避免壓到脖子。"],"2878":["俯臥，雙手放在胸口兩側，雙腿併攏。","恥骨壓向墊子，收緊臀肌。","雙手推地將胸口抬起。","保持頸部拉長，肩膀遠離耳朵。","有控制地慢慢放下並重複。"],"2879":["坐姿，雙腿舒適地摺向同一側。","單手放在身體旁邊的墊上。","另一手伸過頭頂，越過支撐手向側邊彎曲。","停留一個呼吸，感受側邊的伸展。","回到坐姿挺直，然後換邊。"],"2880":["四足跪姿，雙手在肩膀下方，雙膝在髖部下方。","一手向前延伸，對側腿向後伸直。","手腳小幅度快速上下擺動。","保持脊椎中立，髖部水平不歪斜。","換邊重複。"],"2887":["腳踝扣上滑輪配件，雙手懸掛在單槓上。","保持雙手伸直，身體穩定不晃動。","將雙腿在身前抬起至髖部高度或更高。","在頂點將骨盆稍微向上捲。","慢慢放下，避免身體擺盪。"],"2889":["仰臥，手腳向四周大大張開。","核心出力繃緊，下背貼緊地板。","向上捲腹，同時將手腳往中間靠攏。","慢慢張開回到海星姿勢。","保持動作受控並重複。"],"2890":["從前臂棒式開始，手肘在肩膀正下方。","一手掌撐地推起，接著另一手也推起。","雙手伸直進入高棒式。","雙手依序放回前臂撐地。","每次交替先推起的手，並保持髖部水平。"],"2891":["仰臥，雙手墊在髖部下方。","頭與肩膀稍微抬離地板。","雙腿抬離地面幾吋。","雙腿以小幅度交替上下踢動。","保持下背壓穩地板，穩定呼吸。"],"2892":["仰臥，雙手放在身體兩側。","雙腿稍微抬離地板。","雙腿打開，接著一腿交叉疊在另一腿上方。","每次重複時交替上方的腿。","保持下背平貼地板。"],"2894":["採前臂棒式，手肘在肩膀正下方。","夾緊臀肌，從頭到腳跟保持一直線。","單手向前抬起，不讓髖部扭轉。","放回原位，換另一手抬起。","以緩慢受控的節奏交替進行。"],"2895":["從高棒式開始，雙手在肩膀正下方。","雙腳稍微踩寬以維持平衡。","單手抬起向前延伸，髖部不要扭轉。","放下後換手。","全程保持核心繃緊。"],"2897":["從高棒式開始，雙手在肩膀正下方。","同時抬起一隻手與對側腿。","手腳與身體維持一直線，短暫停留。","有控制地放回地板。","換另一組對側手腳重複。"],"2899":["側躺屈膝，手肘在肩膀正下方。","雙側髖部與膝蓋上下對齊交疊。","前臂推地，將髖部抬離地板。","從膝蓋到頭頂保持一直線。","停留 20 到 30 秒，然後換邊。"],"2900":["面對牧師椅靠墊站立，反握 EZ 槓。","上臂貼在靠墊上，雙手伸直。","將槓鈴往肩膀方向彎舉。","在頂點用力收縮二頭肌。","慢慢放下直到手臂幾乎伸直。"],"2901":["面對雪橇站立，反握把手或拉帶。","手肘貼近身體兩側。","雙手往肩膀方向彎舉，帶動雪橇移動。","在頂點收縮二頭肌。","慢慢放下，保持軀幹穩定不動。"],"2902":["雙腳併攏，雙手伸直握住雪橇把手。","向後跨出成後弓步，後膝往下放。","站起的同時將把手拉向肋骨，夾緊肩胛骨。","回到站姿並將雙手伸直。","每次交替雙腿進行。"],"2903":["握住雪橇把手，雙腳併攏站直。","單腳向後跨出成弓步，後膝往地板方向下放。","保持軀幹挺直。","前腳推地回到站姿。","每次交替雙腿進行。"],"2904":["握住雪橇把手，髖部微微向後推。","保持背部平坦，膝蓋微彎。","將把手像翅膀一樣往後往兩側拉開。","用力夾緊肩胛骨。","慢慢回到起始位置。"],"2905":["雙手在身前握住雪橇把手，髖部微微向後推。","手肘保持微彎。","雙手向兩側外展，夾緊肩胛骨。","短暫停留。","慢慢放回。"],"2906":["面對雪橇，握住把手或拉帶，身體微微後傾。","挺胸並繃緊核心。","步伐穩定地向後走，將雪橇拉向自己。","膝蓋保持微彎，靠雙腿發力推進。","完成設定距離後休息。"],"2907":["站在雪橇後方並握住把手。","繃緊核心，身體微微傾向負重。","大步有力地向前走，推動雪橇。","保持步伐穩定並控制呼吸。","完成設定距離後休息。"],"2908":["設定較輕的重量，側對拉力方向站立，在胸口高度握住把手。","繃緊腹肌，保持髖部與肩膀朝向正前方。","步伐受控地向前走，不讓軀幹被拉歪扭轉。","走完設定距離後重設並重複。","換邊完成相同距離。"],"2909":["面對雪橇站立，雙手伸直握住把手或繩索。","背部打直，髖部微微向後推。","髖部向前推，順勢將把手拉向胸口，手肘抬高。","在頂點短暫停留。","有控制地放下並重複。"],"2910":["維持挺直繃緊的姿勢，單手拿起一顆啞鈴放在身體側邊。","保持雙肩水平，肋骨對齊髖部上方。","步伐穩定地行走，身體不要傾向負重側。","走完設定距離後安全放下重量。","換手重複。"],"2911":["一手將啞鈴舉過頭頂並打直穩定手臂，另一手將啞鈴提在體側。","站直，收肋骨並繃緊腹肌。","步伐穩定地行走，上方手臂保持對齊肩膀正上方。","走完設定距離後小心地放下重量。","雙手交換位置並重複。"],"2912":["站在六角槓中央，髖部後推往下握住把手。","背部打直站起，肩膀後收並挺胸。","以小而快的步伐行走，保持槓鈴穩定不晃動。","走完設定距離，期間不要歪斜或聳肩。","有控制地將槓鈴放回地板。"],"2913":["將啞鈴推過頭頂，手肘打直鎖定，二頭肌靠近耳朵。","繃緊腹肌並收肋骨。","步伐穩定地行走，不讓手臂往前飄移。","走完設定距離後，有控制地放下重量。","換手重複。"],"2914":["握距略寬於肩，將槓鈴推過頭頂。","夾緊臀肌並收肋骨。","以小而穩定的步伐行走，讓槓鈴維持在足弓正上方。","走完設定距離，期間背部不要過度反弓。","將槓鈴放回肩膀，再安全放下。"],"2915":["將槓鈴放在手肘彎處，緊緊抱在胸前。","挺胸站直，繃緊腹肌。","步伐受控地行走，保持槓鈴貼近身體。","走完設定距離，期間不要往前駝背。","小心地將槓鈴放回架上或地板。"],"2916":["雙手握住壺鈴兩側把手角，貼近胸口，手肘內收。","站直，收肋骨並繃緊腹肌。","步伐穩定地行走，身體不要後仰。","走完設定距離，保持壺鈴位置高且穩定。","背部打直將壺鈴放下。"],"2917":["雙手在體側各握一顆啞鈴，身體站直。","肩膀向後向下收，並繃緊腹肌。","以輕快受控的步伐行走，不要讓啞鈴晃動。","走完設定距離後安全放下啞鈴。"],"2918":["槓鈴放在身體側邊，單手握在槓鈴的重心平衡點附近。","站起提鈴，保持軀幹挺直與水平。","步伐穩定地行走，抵抗身體往負重側傾斜。","走完設定距離後小心地放下槓鈴。","換手重複。"],"2919":["躺在史密斯機槓鈴下方的長凳上，可視需要在手掌間夾一片槓片。","窄握起槓，將槓鈴停在胸口上方。","雙手用力向內擠壓，同時將槓鈴下放到中胸位置。","持續向內擠壓並將槓鈴推回。","完成後將槓鈴掛回架上。"],"2920":["單腳站立，雙手向前延伸。","支撐腿膝蓋微彎。","從髖部折起，懸空腿順勢向後抬起。","保持背部平坦，身體呈一直線。","回到站姿並重複，接著換腿。"],"2921":["從伏地挺身姿勢開始，雙腳往前走並抬高髖部，讓身體呈倒 V 字形。","保持手臂與背部伸直。","彎曲手肘，將頭頂往地板方向下放。","推回直到雙手伸直。","全程保持核心收緊。"],"2922":["站直，雙腳與髖部同寬。","一手放在另一手的手腕上方提供阻力。","訓練手往肩膀方向彎舉，另一手同時往下壓。","在頂點收縮二頭肌。","慢慢放下，完成次數後換手。"],"2924":["側躺在低位滑輪旁，用上側手握住把手。","保持手臂伸直，手肘微彎。","將手臂往側邊抬起，直到接近肩膀高度。","在頂點短暫停留。","慢慢放下，完成次數後換邊。"],"2925":["雙手各握一顆啞鈴，面對跳箱或長凳站立。","單腳掌完整踩上箱面。","前腳跟出力推，將身體站直。","有控制地放回地面，地面腳不要借力彈起。","完成次數後換腿。"],"2926":["將彈力帶交叉成 X 形，套在雙腳或小腿處，並視需要握住兩端。","呈四分之一深蹲姿勢，保持挺胸。","向側邊跨步，保持彈力帶的張力。","後腳跟上，但雙腳不要併攏碰在一起。","走完設定距離後，往反方向走回。"],"2927":["雙膝跪地，在肩膀高度將壺鈴倒握，壺底朝上。","握緊把手，保持手腕打直。","將壺鈴筆直推過頭頂。","保持壺鈴平衡，慢慢下放回肩膀。","完成次數後換手。"],"2928":["寬握將槓鈴舉過頭頂並打直鎖定。","保持雙手伸直，收肋骨。","將肩膀往耳朵方向向上聳起。","在頂點短暫停留。","手肘不要彎曲，慢慢放下肩膀。"],"2929":["跪在固定好的戰繩前，雙手各握一端。","繃緊腹肌並保持挺胸。","雙手交替上下揮動以製造波浪。","保持波浪快速且穩定。","持續設定時間後休息。"],"2930":["在胸口高度雙手握住彈力帶，掌心朝上，手肘彎曲 90 度。","保持手肘貼近身體兩側。","前臂向外旋轉，將彈力帶拉開。","短暫夾緊肩胛骨。","慢慢放回並重複。"],"2931":["站立，讓背部、頭與髖部貼著牆面。","雙手放在身體兩側，手肘伸直。","在不拱背的前提下，將雙手盡量往前往上舉過頭頂。","在頂點停留。","慢慢放下並重複。"],"2932":["雙膝跪地，將壺鈴架在肩膀位置。","夾緊臀肌並繃緊腹肌。","將壺鈴推過頭頂直到手臂伸直。","慢慢將壺鈴放回肩膀。","完成次數後換手。"],"2933":["站立，雙腳與髖部同寬，雙手握住戰繩末端。","單腳向後跨出成弓步，同時甩動戰繩製造波浪。","前腳跟推地回到站姿。","雙腿交替進行，戰繩波浪不中斷。","持續設定時間後休息。"],"2934":["單膝跪地，另一腳踩在前方，將壺鈴架在肩膀位置。","繃緊腹肌，並夾緊跪地側的臀肌。","將壺鈴筆直推過頭頂。","有控制地放回原位。","完成次數後換邊。"],"2935":["單膝跪地，一手握住塑膠管或長棍，另一手向外伸展。","將訓練側的前臂靠在牆面或柱子上。","將軀幹輕輕往反方向轉開，直到感覺胸口有伸展感。","停留 20 到 30 秒。","換邊。"],"2936":["單膝跪地，前腳掌平貼地板。","保持前腳跟貼地不離地。","將前膝往腳尖方向前推，直到感覺有伸展感。","慢慢前後搖擺 20 到 30 秒。","換腿。"],"2937":["跪在健身球前方，前臂放在球頂上。","背部稍微拱圓，骨盆後傾內收。","延伸雙手將球向前滾出。","用腹肌的力量將球拉回。","保持髖部不塌陷，緩慢移動。"],"2938":["仰臥，雙手在頭頂上方拉住彈力帶，雙膝抬起呈 90 度。","將下背壓緊地板。","維持彈力帶張力，同時放下對側的手與腳。","回到起始位置並換邊。","保持收肋骨，緩慢移動。"],"2939":["在胸口高度雙手握住壺鈴兩側把手角。","站直並繃緊腹肌。","將壺鈴貼近頭部繞圈。","保持髖部與肋骨穩定不動。","完成次數後換反方向繞圈。"],"2940":["俯臥，單手自然垂下或向頭頂延伸，大拇指朝上。","額頭貼著，頸部放鬆。","將肩胛骨往下往後收，帶動手臂沿 Y 字軌跡抬起。","在頂點停留。","慢慢放下，完成次數後換手。"],"2941":["面對牆壁站立，前臂貼在牆上，手肘與肩同高。","身體微微前傾並繃緊腹肌。","將前臂沿著牆面向上滑動延伸。","在頂點停留，背部不要反弓。","滑回原位並重複。"],"2942":["將壺鈴架在肩膀位置並站直。","繃緊腹肌並夾緊臀肌。","將壺鈴沿著斜角往上且微微往外推起。","打直手臂鎖定，身體不要後仰。","有控制地放下，完成次數後換手。"],"2943":["將彈力帶套在大腿上，從伏地挺身姿勢開始。","繃緊核心。","向前爬行的同時，將一側膝蓋往同側手肘方向帶。","保持彈力帶張力，左右交替進行。","爬完設定距離後休息。"],"2944":["俯臥，雙手放在肩膀下方，雙腿伸直。","雙手推地將上半身推起，如海豹姿勢。","保持髖部貼地，核心收緊。","慢慢放回地板。","以流暢受控的節奏重複。"],"2945":["背部平貼牆面站立，手肘彎曲放在身體兩側。","前臂與頭部輕貼牆面。","保持肩胛骨下壓，將雙手沿著牆面向上滑動。","在背部準備反弓前停住。","慢慢滑下並重複。"],"2946":["從棒式開始，單手撐地，另一手放在背後或髖部上。","保持手肘打直鎖定。","讓胸口在肩胛骨之間稍微下沉。","單手推地，讓上背稍微向上拱起。","完成次數後換手。"],"2947":["跪在地板上，將滾筒放在小腿脛骨前側下方。","雙手撐地支撐身體。","沿著脛骨旁肌肉慢慢上下滾動。","在緊繃的點停留幾秒鐘。","換腿進行，力道保持舒適即可。"],"2948":["俯臥，將滾筒放在單側胸口下方。","將該側手臂向旁延伸。","慢慢左右與上下滾動。","在緊繃的點停留幾秒鐘。","換邊進行，力道保持舒適即可。"],"2949":["側躺，將滾筒放在腋下區域下方，該側手臂向上延伸。","用下側手臂與雙腿支撐身體。","沿著身體側邊往肋骨方向慢慢滾動。","在緊繃的點停留幾秒鐘。","換邊進行，力道保持舒適即可。"],"2950":["套上腰帶並站上踏板，讓腰帶穩固貼合在髖部上。","站直並繃緊腹肌。","往下深蹲直到大腿約略與地面平行。","腳跟推地站回原位。","保持挺胸，膝蓋朝向腳尖方向。"],"2951":["坐在器械上，背部平貼靠墊，雙腳踩在踏板上。","雙腳打開約與肩同寬。","將踏板推開直到雙腿接近伸直。","膝蓋不要鎖死。","慢慢放回直到膝蓋彎曲約 90 度，然後重複。"],"2952":["採四足跪姿，單腳掌底抵住史密斯機槓鈴，可視需要請搭檔幫忙穩住。","繃緊核心。","伸展髖部將槓鈴往上推。","在頂點夾緊臀肌。","慢慢放下，完成次數後換腿。"],"2954":["面對低位滑輪站立，雙手正握直槓。","保持手肘貼在身體兩側。","將直槓往肩膀方向彎舉，身體不要晃動。","在頂點用力收縮。","慢慢放下直到雙手伸直。"],"2956":["胸前抱著一顆啞鈴，前腳踩在低踏板上。","後腳向後踩在地板上。","保持軀幹挺直，將後膝往地板方向下放。","前腳跟推地站起。","完成次數後換腿。"],"2957":["雙手各握一顆啞鈴，前腳踩在低踏板上。","後腳向後跨出。","保持軀幹挺直，將後膝往地板方向下放。","前腳跟推地站起。","完成次數後換腿。"],"2960":["雙手各握一顆啞鈴，前後跨出大步，一腳在前。","保持軀幹挺直。","將後膝往地板方向下放。","前腳跟推地站起。","完成次數後換腿。"],"2961":["雙手各握一顆啞鈴呈棒式，雙腳踩寬。","保持身體呈一直線，做一下伏地挺身。","將一顆啞鈴拉向肋骨，髖部不要扭轉。","放下後換另一側划船。","有控制地重複整套動作。"],"2962":["坐下，背部貼緊靠墊，握住對握把手。","雙腳平貼地板。","將把手推過頭頂直到雙手幾乎伸直。","短暫停留。","慢慢放回肩膀高度並重複。"],"2963":["使用垂直提膝椅（隊長椅 Captain\'s Chair），背靠椅背，前臂穩穩壓在扶手墊上。","上半身維持穩定，背部打直。","收緊腹肌，將雙腿向前上方伸直抬起（直腿抬腿）。","抬至雙腿平行地面或更高位置。","頂點稍作停頓，慢慢降回雙腿。","重複所需次數。"],"2964":["坐在地板上，將槓鈴橫放在髖部上，可視需要加軟墊。","向後躺下，踩穩雙腳，雙手握住槓鈴。","腳跟推地將髖部抬起。","在頂點夾緊臀肌。","慢慢放下並重複。"],"2966":["雙手各握一顆啞鈴放在肩膀位置，手肘朝前。","站立，雙腳與肩同寬。","往下深蹲直到大腿約略與地面平行。","保持挺胸，膝蓋朝向腳尖方向。","腳跟推地站起。"],"2968":["將啞鈴舉在肩膀位置，雙腳與肩同寬站立。","保持挺胸往下深蹲。","腳跟用力推地站起，一氣呵成將啞鈴推過頭頂。","在頂點將雙手打直鎖定。","將啞鈴放回肩膀，直接接著做下一次。"],"2969":["雙手各握一顆啞鈴放在肩膀位置。","保持挺胸往下深蹲，膝蓋朝向腳尖方向。","腳跟用力推地站起。","順著站起的動能將啞鈴推過頭頂。","將啞鈴放回肩膀，直接進入下一次深蹲。"],"2970":["雙腳踩住彈力帶，雙手在肩膀位置握住兩端。","保持挺胸往下深蹲。","用力站起，一氣呵成將雙手推過頭頂。","在頂點將雙手打直鎖定。","雙手放回肩膀並重複。"],"2972":["站直，雙腳併攏，雙手放在胸前。","向側邊跨出一大步。","彎曲跨出側的膝蓋，髖部往後坐，另一腿保持伸直。","彎曲腿推地回到起始位置。","左右交替進行。"],"2974":["坐在器械上，背部貼緊靠墊，單手握住把手。","雙腳平貼地板。","將把手向前推直到手臂接近伸直。","短暫停留。","慢慢放回，完成次數後換手。"],"2976":["雙手在胸前握住地雷管槓鈴末端。","站立，雙腳與肩同寬。","保持挺胸往下深蹲。","用力站起並將槓鈴向外推，直到雙手伸直。","將槓鈴放回胸前並重複。"],"2978":["從前臂棒式開始，身體保持一直線。","單手掌撐地，推起身體成高棒式。","另一手掌也撐地。","雙手依序放回前臂撐地。","交替先推起的手，並保持髖部穩定不晃動。"],"2980":["雙手各握一顆啞鈴呈高棒式，雙腳踩寬。","繃緊核心。","將一顆啞鈴拉向肋骨，髖部不要扭轉。","有控制地放下。","換另一側重複。"],"2982":["躺在地板上，雙膝彎曲，雙手各握一顆啞鈴。","將兩顆啞鈴推到胸口上方。","放下一顆啞鈴，直到上臂碰到地板。","推回原位，再放下另一側。","持續左右交替。"],"2984":["站在箱子前方，一腳往前伸直。","核心收緊，雙手往前伸以保持平衡。","支撐腳慢慢往後往下坐，直到臀部碰到箱子。","腳跟發力站起來。","完成規定次數後換腳。"],"2986":["穿戴負重腰帶或背心，雙手對握抓住雙槓架握把。","雙臂伸直懸吊，核心收緊。","將胸口往上拉，直到下巴超過握把。","短暫停留一下。","慢慢下放回到完全懸吊的姿勢，然後重複動作。"],"2987":["站在單槓下，反握抓槓，雙手間距與肩同寬。","雙臂完全伸直懸掛，身體打直離地。","啟動背肌將身體向上拉起，手肘貼緊身側。","持續向上拉直到下巴超過單槓，停頓片刻。","緩慢降回起始位置，雙臂充分伸展。","重複所需次數。"],"2988":["站立，雙腳略寬於肩。","往下蹲至深蹲姿勢，腳跟踩穩地面。","用手肘輕輕向外推開膝蓋。","挺直上半身，左右輕輕搖晃。","停留 30-45 秒，接著站起來。"],"2989":["站立，雙腳略寬於肩，腳尖稍微朝外。","往下蹲至深蹲底部，腳跟貼穩地面。","用手肘推開膝蓋以打開髖部，並停留一下。","重心輕輕左右移動，接著再前後搖晃。","站直身體，重複這套動作 6-8 趟。","全程保持挺胸、背部延伸。"],"2990":["將輕槓鈴放在上背，雙手扶穩槓鈴。","站直並收緊核心，墊起腳尖。","以小步且受控的方式往前走，過程腳跟不落地。","保持腳踝穩定，髖部維持水平。","走 10-15 公尺後休息，接著重複幾趟。","使用輕重量即可，確保腳尖能維持墊高。"],"2991":["坐在健身球上挺直身體，雙腳踩地。","將一腳稍微抬離地面，保持平衡。","雙臂往前平舉，接著將肩膀往下壓，遠離耳朵。","將肩胛骨往後收並夾緊，注意背部不要過度拱起。","慢慢回到起始位置，完成規定次數。","換腳，在另一側重複動作。"],"2992":["坐在地板上，將一邊小腿放在槓鈴上。","雙手撐在身體後方支撐體重。","將小腿在槓鈴上慢慢前後滾動。","在痠痛點停留幾個呼吸。","換另一隻腳。"],"2993":["雙手握住壺鈴兩側把角，貼在胸前。","站立，雙腳寬於肩膀，腳尖稍微朝外。","保持挺胸，在舒適範圍內盡量蹲低。","用手肘將膝蓋往外推開，並在底部停留。","左右輕輕搖晃以打開髖部。","雙腳踩地發力站起來。"],"2994":["跪在瑜珈墊上，將泡棉滾筒放在脛骨下方。","雙手撐在身體前方支撐。","移動重心，沿著小腿前側來回滾動。","動作放慢，在緊繃部位停留一下。","每隻腳滾動 30-60 秒。"],"2996":["雙腳與髖同寬踩住彈力帶，單手握住另一端停在肩膀高度。","核心收緊，肋骨下壓。","將手往正上方推高，直到手臂接近伸直。","有控制地慢慢放回肩膀高度。","完成規定次數，過程身體不要往側邊歪斜。","換手重複動作。"],"2997":["將彈力帶繞過單槓，把一隻腳或膝蓋套進彈力帶裡。","雙手正握單槓，握距略寬於肩膀。","雙臂伸直懸吊，肩膀出力穩定。","手肘往下拉動，將胸口拉向單槓。","慢慢下放，直到雙臂再次伸直。","隨著肌力進步，可以改用阻力較細的彈力帶。"],"2998":["坐在椅子或地板上，一腳往前伸直。","腳尖往下壓，拉長腳背。","慢慢轉動或下壓腳掌，直到感覺舒適的伸展感。","停留 20-30 秒，不要勉強用力。","放鬆並換腳。","每側重複 2-3 次。"],"2999":["將彈力帶繞在後腳的前腳掌上。","雙手握住彈力帶兩端，站直身體。","將該腳往後踩一步，腳跟貼緊地面。","輕輕拉動彈力帶，讓腳尖朝小腿方向勾起。","後腳保持接近伸直，停留 20-30 秒。","換邊重複動作。"],"3000":["將彈力帶繞在前腳的前腳掌上。","雙手握住彈力帶兩端，站直身體。","前腳腳跟踩地，腳尖翹起。","拉動彈力帶讓腳尖朝自己勾起，身體稍微往前傾。","維持舒適的伸展感，停留 20-30 秒。","換腳重複動作。"],"3001":["站立，雙腳與肩同寬，腳尖稍微朝外。","核心收緊並挺胸。","彎曲髖部與膝蓋，往下進入深蹲。","將膝蓋往外推，使其順著腳尖的方向移動。","在能穩定控制的範圍內盡量蹲低。","全腳掌踩穩發力站起來。"],"3002":["採跪姿，單手撐在肩膀正下方，另一手放在背後。","雙膝稍微張開一點以保持平衡。","從頭到膝蓋維持一直線。","有控制地將胸口往地板方向下放。","往上推起身體，過程保持髖部不旋轉。","換手重複動作。"],"3004":["站直身體，肩膀放鬆。","用比平常散步更快的速度開始走。","手肘微彎，自然擺動雙臂。","腳跟先著地，再順勢滾動到腳尖推地。","保持平穩呼吸，維持在還能說話的強度。","持續走 20-45 分鐘。"],"3006":["坐在椅子或重訓椅上，背打直，雙腳踩地。","彈力帶套在膝蓋上方大腿處。","雙手扶在椅子兩側支撐。","啟動臀中肌與外展肌群，對抗彈力帶阻力慢慢將雙膝向外張開。","外展到底停頓片刻，緩慢收回。","重複所需次數。"],"3007":["阻力帶固定在穩固錨點，另一端套在腳踝上。","面對錨點站立，雙腳與肩同寬。","核心收緊、骨盆穩定，單腿向前上方踢伸。","頂峰停頓片刻，慢慢放回。","重複所需次數後換腿。"],"3009":["站在樓梯底部，身體挺直。","一腳往上踩上階梯，全腳掌踩穩。","腳跟發力，將另一隻腳帶上來。","上半身保持挺直，雙臂自然擺動。","以穩定速度持續往上走，並交替帶頭的腳。"],"3010":["平躺在平凳上，雙腳踩實地面。","正握抓住 EZ 槓，雙手間距與肩同寬。","將手臂推直於胸部上方，手肘微屈。","以弧線動作將槓鈴降向頭頂後方（仰臥套頭）。","停頓片刻，胸肌與背肌發力拉回胸前起始位置。","重複所需次數。"],"3011":["重訓椅調整至 45 度上斜。","雙手撐在椅面上，間距略寬於肩（上斜伏地挺身）。","雙腳踩地與臀同寬，身體成一直線。","手肘微收彎曲，將胸部降向椅面。","下沉時兩側肩胛骨向內夾緊。","掌心推地伸直手臂回到原位。","重複所需次數。"],"3012":["站立雙腳與肩同寬，雙臂向前伸直。","膝蓋微彎屈髖前傾，背部打直。","手肘彎曲肩胛後縮夾緊，如同兩肩胛骨中間夾一隻鉛筆。","底部停頓片刻，手掌推展伸直手臂回原位。","重複所需次數。"],"3013":["平躺，雙膝彎曲，雙腳踩實地面。","雙臂貼在身側，掌心朝下。","啟動臀肌與核心，將臀部推離地面直到膝、髖、肩成一直線（臀橋）。","頂峰停頓片刻，用力收縮臀肌。","慢慢將臀部放回地面。","重複所需次數。"],"3016":["平躺，雙膝彎曲，雙腳踩實。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，將上半身捲離地面至約 45 度（捲腹）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"3017":["雙腳分開與肩同寬站立，膝蓋微屈。","屈髖前傾，背部平直挺胸。","正握抓住槓鈴，握距略寬於肩寬。","將槓鈴拉向上腹部，肩胛骨向內夾緊（俯身槓鈴划船）。","控制速度放回槓鈴。","重複所需次數。"],"3018":["站直身體，雙腳與髖同寬。","用前腳掌發力，盡可能將腳跟墊高。","在最高點停留 1 秒。","將腳跟慢慢放回地面。","需要時可扶牆保持平衡。"],"3019":["仰臥躺在胸部高度的單槓下方。","正握抓槓，握距略寬於肩寬。","腳跟著地，身體維持一條直線。","兩側肩胛骨夾緊屈肘，將胸口拉向單槓（仰臥懸垂划船）。","拉至下巴超過橫槓。","有控制地下放身體回到起始位置。","重複所需次數。"],"3021":["高棒式姿勢開始，雙手在肩膀正下方，身體呈一直線。","胸部降向地面，手肘貼身微收。","下沉時肩胛骨向後夾緊、挺胸。","底部停頓片刻，推回高棒式。","重複所需次數。"],"3023":["仰臥，將彈力帶套在小腿上，另一端固定在身體側邊。","雙膝彎曲，雙腳踩地。","小腿對抗彈力帶往外轉開，使髖部做出內旋。","慢慢回到起始位置。","完成規定次數後換腳。"],"3030":["將槓鈴放在上背，一腳往前跨出。","前後腳跨出較大步幅，上半身保持挺直。","雙膝彎曲，後膝朝地面下放。","前腳跟踩穩地面，前膝對齊腳掌上方。","前腳踩地發力站起。","完成規定次數後換腳。"],"3034":["採四足跪姿，雙手在肩膀正下方。","核心收緊，背部保持平坦。","抬起一隻腳，膝蓋保持彎曲 90 度。","將腳底往天花板方向推，並夾緊臀肌。","慢慢下放，過程背部不要拱起或塌陷。","完成規定次數後換腳。"],"3035":["採四足跪姿，背部保持平坦。","膝蓋保持彎曲約 90 度。","將彎曲的腿往側邊抬高至髖部高度。","在最高點收緊髖部外側，上半身不要跟著旋轉。","有控制地慢慢下放。","完成規定次數後換腳。"],"3037":["站直身體，雙臂彎曲放在身體兩側。","原地慢跑或慢慢往前跑動。","將腳跟輪流往臀肌方向踢起。","用前腳掌著地，膝蓋保持朝下。","雙臂配合節奏擺動。","持續動作 20-40 秒。"],"3040":["將橫桿接在高位滑輪上，背對器材站立。","雙手在頭後方握住橫桿，手肘朝前。","往前踏出一步，雙腳成前後站姿。","伸直雙臂將橫桿往頭頂上方推。","慢慢下放回原位，過程保持手肘位置固定。"],"3048":["將腳踝扣環接在低位滑輪上，綁在外側腳踝。","側對器材站立，單手扶住支撐物。","上半身保持挺直，支撐腳膝蓋微彎。","將綁扣環的腿往側邊抬起。","在最高點停留一下，再慢慢下放。","完成規定次數後換腳。"],"3068":["將繩索接在低位滑輪上，雙手各握一端。","站直身體，手肘貼在身體兩側。","將繩索往肩膀方向彎舉上來。","在最高點收緊二頭肌。","有控制地慢慢下放，身體不要晃動。"],"3075":["躺在長凳上，雙手各持一個啞鈴在胸前互相貼緊。","掌心彼此相對。","手肘收近身體，將啞鈴下放到胸口。","保持啞鈴貼合，往上推回起始位置。","手腕保持打直。"],"3083":["坐在長凳上，雙手各拿一個啞鈴。","雙臂自然垂在身體兩側，掌心朝前。","將啞鈴往肩膀方向彎舉上來。","在最高點用力收緊，手肘固定在身體兩側。","慢慢下放直到手臂完全伸直。"],"3084":["坐在牧師椅上，將上臂貼平在靠墊上。","單手拿啞鈴，掌心朝上。","將重量往肩膀方向彎舉上來。","在最高點用力收緊。","慢慢下放至手臂接近伸直，完成後換手。"],"3086":["站直身體，雙手放在頭後方。","將一邊膝蓋往上並往對側抬起。","轉動上半身，用對側手肘去碰膝蓋。","回到站立姿勢。","以穩定速度左右交替。","保持挺胸並平穩呼吸。"],"3088":["雙腳站得比肩膀寬，往下進入深蹲。","手指尖輕點在雙腳之間的地板上。","擺動雙臂，往前上方跳出。","輕柔落地並直接回到深蹲姿勢。","重整姿勢後馬上接著跳下一下。","保持膝蓋對齊腳尖方向。"],"3091":["站直身體並保持放鬆。","往前跳步，同時將一邊膝蓋高高抬起。","另一隻腳輕巧地在地面彈跳。","每次抬膝時，對側手臂跟著往前擺動。","以流暢的節奏交替雙腿。","保持挺胸並輕柔落地。"],"3092":["站立，雙腳與肩同寬。","保持挺胸往下深蹲。","雙腳踩地發力站起來。","站到頂點時，將一邊膝蓋往胸口抬高。","放下腳掌，直接進入下一次深蹲。","每次重複時交替抬起的膝蓋。"],"3094":["雙腳併攏站立，雙臂垂在身體兩側。","雙腳往外跳開，同時雙臂往頭頂上方揮動。","跳回起始位置。","以前腳掌輕柔落地。","維持穩定的節奏。","持續動作 30-60 秒。"],"3095":["單腳站立，膝蓋微彎。","用力蹬地往側邊跳出。","用另一隻腳落地，彎曲膝蓋吸收衝擊。","落地時停留 1 秒以維持平衡。","接著往反方向跳回去。","保持挺胸，膝蓋對齊腳尖方向。"],"3096":["坐好並將胸口貼穩靠墊，握住窄距握把。","單手將握把往後拉，手肘往身體後方帶。","在末端夾緊該側肩胛骨。","慢慢放回，換另一隻手拉動。","左右交替進行，保持上半身穩定不動。"],"3102":["坐好並將胸口貼穩靠墊，雙手握住窄距握把。","將兩邊握把同時往身體方向拉。","在末端將兩側肩胛骨夾緊。","短暫停留一下。","有控制地慢慢放回。"],"3108":["雙腳併攏站立。","雙腳往外跳寬，落地時蹲至四分之一深蹲。","落地同時雙臂往外擺開。","雙腳跳回併攏位置。","每次都輕柔落地。","維持快速且受控的節奏。"],"3109":["單腳站立，膝蓋微彎。","往側邊跳向另一隻腳。","輕柔落地，後腳順勢往身體後方擺動。","雙臂在身前橫向擺動以保持平衡。","馬上往反方向跳回去。","保持髖部壓低、胸口朝前。"],"3110":["坐在地上，上背靠著長凳，史密斯槓鈴橫跨在髖部上方。","在槓鈴上裝好護墊，滾到髖部摺痕處。","雙腳與髖同寬踩穩地面，旋轉解開槓鈴鎖扣。","腳跟發力，將髖部往上推高直到身體呈水平線。","在最高點夾緊臀肌。","慢慢下放並重複動作。"],"3113":["站直身體，雙臂放在身體兩側。","一腳往前跳、另一腳往後跳，同時擺動對側手臂。","膝蓋保持微彎，輕柔落地。","再次起跳並前後換腳。","上半身保持挺直。","以穩定速度持續 30-45 秒。"],"3114":["採四足跪姿，背部保持平坦。","核心收緊。","將一隻腳往後伸直。","將腿抬高至髖部高度，並夾緊臀肌。","下放時注意背部不要塌陷拱起。","完成規定次數後換腳。"],"3116":["將彈力帶固定在頭頂高處錨點。","面對錨點站立，雙腳與肩同寬。","反手抓彈力帶，間距略寬於肩。","退後一步使彈力帶緊繃，雙臂伸展。","收緊核心，肩胛骨向內夾緊。","手肘引導將彈力帶向下拉向胸口。","底部停頓片刻感受背闊肌收縮。","緩慢釋放張力回原位。","重複所需次數。"],"3117":["彈力帶固定在高處單槓或橫樑。","坐在面對彈力帶的椅子上，雙腳踩地。","反握抓住彈力帶，掌心朝向自己。","背打直，核心收緊。","將彈力帶向下拉向胸口，肩胛骨用力夾緊。","底部停留片刻，收縮背闊肌。","控制速度慢慢送回彈力帶。","重複所需次數。"],"3119":["雙腳分開與肩同寬站立，腳尖微朝外。","屈膝屈髖向後下蹲，如同坐入椅子。","全程維持挺胸背打直。","下蹲至大腿平行地面或舒適極限。","底部稍作停頓，腳跟推地站回。","重複所需次數。"],"3120":["站立並扶著牆壁或欄杆保持平衡。","雙腳與髖同寬踩穩。","盡可能墊高腳尖。","停留一下並收緊小腿。","慢慢下放。"],"3121":["坐在地板上雙腿伸直，將彈力帶繞在腳底。","雙手握住彈力帶兩端，手臂伸直。","坐直身體，背部保持平坦。","將彈力帶往腰部拉動，同時夾緊肩胛骨。","慢慢放回。"],"3122":["坐在椅子或重訓椅上，背部挺直，雙腳踩地。","雙手握阻力帶於肩部高度，掌心朝前。","向上推舉過頭頂，雙臂完全伸展。","頂端停留片刻，慢慢降回肩部。","重複所需次數。"],"3123":["坐在椅子上，背部挺直，雙腳踩地。","反手握彈力帶，掌心朝上，雙臂下垂。","上手臂固定不動，吐氣將彈力帶向上彎舉至肩部。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢放回。","重複所需次數。"],"3124":["坐在椅子上，雙腳踩實，背部挺直。","雙手握阻力帶把手，掌心朝下，手肘呈 90 度。","雙臂向前推展，將阻力帶推離胸口。","頂峰停頓片刻，緩慢收回。","重複所需次數。"],"3125":["坐姿單腳伸出，將彈力帶繞在前腳掌上。","將另一端固定在內側的固定物上。","腳跟固定在地面不動。","前腳掌對抗彈力帶往外轉開。","慢慢回到起始位置。","完成規定次數後換腳。"],"3126":["坐姿將腿伸直，把彈力帶繞在前腳掌上。","雙手握住彈力帶兩端。","腳尖對抗彈力帶阻力往下壓。","在活動範圍末端停留一下。","慢慢放回。","完成規定次數後換腳。"],"3127":["坐姿將腿伸直，把彈力帶繞在前腳掌上。","將彈力帶固定在腳掌內側方向。","保持腿部穩定不動。","腳底對抗彈力帶往外翻起。","慢慢放回。","完成規定次數後換腳。"],"3128":["坐姿將腿伸直，把彈力帶繞在前腳掌上。","將彈力帶固定在腳掌外側方向。","保持腿部穩定不動。","腳底對抗彈力帶往內翻起。","慢慢放回。","完成規定次數後換腳。"],"3129":["站直或坐直，雙臂在肩膀高度往前平舉。","將背後的肩胛骨往中間夾緊。","停留一下。","接著雙手往前推伸，讓肩胛骨往兩側張開。","在兩個位置之間慢慢來回移動。","保持頸部放鬆，肋骨下壓。"],"3130":["站直或坐直，雙臂自然垂在身體兩側。","將肩膀往耳朵方向聳起。","停留 1 秒。","將肩膀往下壓，遠離耳朵。","在完整活動範圍內慢慢移動。","保持雙臂放鬆，頭部穩定不動。"],"3132":["雙腳與肩同寬站立，腳尖微外展。","扶著椅子或牆壁以維持平衡。","屈膝屈髖向後下蹲。","全程維持挺胸背平。","底部停頓片刻，踩穩腳跟蹬起。","重複所需次數。"],"3141":["採四足跪姿，脊椎保持中立。","將一隻手臂往前伸，同時對側腿往後伸直。","保持髖部水平，避免背部過度拱起。","短暫停留一下。","收回到起始位置並換邊。"],"3142":["史密斯槓調整在臀部高度。","雙腳開立寬於肩寬，腳尖朝外（相撲深蹲）。","鑽入槓下將槓鈴扛在斜方肌上。","收緊核心挺胸，屈膝屈髖向後下蹲。","下蹲至大腿與地面平行或略低。","底部稍作停頓，踩穩腳跟推回站姿。","重複所需次數。"],"3144":["坐在地上，雙腿伸展，阻力帶套在腳掌上。","雙手抓住阻力帶兩端，掌心相對。","背部挺直微後傾，啟動核心。","將阻力帶拉向胸口，肩胛骨向內夾緊。","頂端停留片刻，慢慢放回。","重複所需次數。"],"3145":["高棒式開始，雙手略寬於肩，身體成一直線。","手肘微收彎曲，將身體降向地面。","快貼地時雙手推直撐起上半身。","在頂點胸椎向上推展，將肩胛骨向外展開推圓（推頂肩胛伏地挺身 Push-up Plus）。","停頓片刻，收回肩胛骨並將身體放回起始伏地挺身姿勢。","重複所需次數。"],"3147":["平躺，雙膝彎曲，雙腳踩實。","雙手置於體側。","腹肌發力收縮，進行骨盆後傾，將下背完全壓平貼向地面。","維持此後傾姿勢數秒，專注收縮下腹肌群。","放鬆骨盆回正。","重複所需次數。"],"3149":["坐直或站直，視線看向前方水平處。","有幫助的話可以把一根手指放在下巴上。","將下巴往正後方水平收回，像是擠出雙下巴一樣。","頭部保持水平，不要抬頭或低頭。","停留 3-5 秒。","放鬆並重複 8-10 次。"],"3150":["坐直或站直，視線看向前方水平處。","將兩根手指放在下巴上。","輕輕引導下巴往正後方收回。","頭部保持水平，肩膀放鬆。","停留 3-5 秒。","放鬆並重複 8-10 次。"],"3153":["站立，雙腳與肩同寬。","雙手撐地，雙腳往後跳成棒式。","做一下伏地挺身，接著雙腳跳回手掌旁。","站起來，同時將一隻腳往側邊踢出。","落地後直接進入下一次動作。","每次交替踢腿的側邊。"],"3156":["雙腳分開與肩同寬站立，膝蓋微彎，單手持啞鈴採中立對握。","屈髖前傾，背部維持平直，核心收緊。","將啞鈴向上拉向胸側，手肘貼身，肩胛骨向後夾緊。","頂端停頓片刻，慢慢降回。","重複所需次數後換邊。"],"3158":["雙腳與肩同寬站立，膝蓋微屈。","屈髖前傾，背打直，核心收緊。","雙臂在身前伸展，緊握拉桿或把手。","將把手拉向軀幹，肩胛骨向內用力夾緊。","頂點稍作停頓，緩慢放回。","重複所需次數。"],"3161":["雙腳與肩同寬站立，膝微屈，單手握毛巾。","屈髖前傾，背部打直收腹。","將毛巾向上拉向胸口，肩胛骨向內夾緊。","頂端停頓片刻，慢慢放回。","重複所需次數後換手。"],"3162":["雙腳與肩同寬站立，雙膝微屈，單手握啞鈴。","屈髖前傾，背部挺直，核心收緊。","啞鈴垂直垂於身前，手臂完全伸展。","將啞鈴向上拉向胸側，手肘貼緊軀幹。","動作頂點用力夾緊肩胛骨。","慢慢放回啞鈴。","重複所需次數後換手。"],"3165":["雙腳分開與肩同寬站立，雙手在身前拉住毛巾兩端。","膝蓋微彎，屈髖前傾，背部打直。","雙手用力向兩側拉緊毛巾同時拉向胸口，肩胛骨向內夾緊。","頂點停頓片刻，慢慢放回。","重複所需次數。"],"3166":["雙腳與肩同寬站立，雙膝微屈。","正握抓槓或把手，掌心朝下。","背部維持挺直，核心收緊。","將把手拉向軀幹，肩胛骨用力向內夾緊。","頂端停頓片刻。","緩慢放回雙臂至伸直。","重複所需次數。"],"3167":["雙腳分開與肩同寬站立，雙手握毛巾置於身前。","屈膝下沉成深蹲，背部打直挺胸。","下蹲同時將毛巾拉向胸口，肩胛骨向內夾緊。","深蹲底部稍作停頓，慢慢站起同時伸展手臂放回。","重複所需次數。"],"3168":["雙腳與肩同寬站立，雙手抓住穩固物體或 TRX 懸吊繩。","下沉進入深蹲，背部打直，膝蓋不超過腳尖。","從深蹲起身同時，背肌發力將身體拉近錨點，夾緊肩胛骨。","頂端停留片刻，慢慢降回。","重複所需次數。"],"3171":["採拳擊站姿，雙手抬高護頭。","右手肘彎曲約 90 度。","後腳掌旋轉，帶動髖部與上半身轉動。","將拳頭畫弧線揮向目標。","快速收回防守姿勢。","保持下巴內收，左手維持抬高。"],"3174":["躺在長凳上，抬起雙腳使膝蓋彎曲呈 90 度。","雙手握槓，握距略寬於肩膀。","將槓鈴起槓並停在胸口正上方。","有控制地將槓鈴下放到中胸位置。","將槓鈴往上推回，直到手臂伸直。","全程保持下背貼平長凳。"],"3175":["躺在長凳上，雙手拿啞鈴舉在胸口上方。","抬起雙腳，讓膝蓋彎曲呈 90 度。","手肘保持微彎。","雙臂往兩側打開，直到感覺胸部有伸展感。","將啞鈴在胸口上方收回靠攏。","動作放慢，並保持背部貼平。"],"3176":["躺在長凳上，雙腳抬起、膝蓋彎曲呈 90 度。","雙手合握一個啞鈴，舉在胸口上方。","雙臂保持接近伸直。","將啞鈴畫弧線往頭後方下放。","將啞鈴拉回胸口上方。","保持肋骨下壓，背部貼平。"],"3178":["俯臥，將髖部壓在健身球上，雙手撐在地板上。","抓穩長凳或健身球以維持穩定。","將雙腿往上抬，直到與身體呈一直線。","在最高點夾緊臀肌。","有控制地慢慢下放。"],"3180":["俯臥在上斜長凳上，髖部靠在長凳邊緣。","雙手抓住長凳兩側。","將雙腿往上抬，直到與上半身呈一直線。","在最高點夾緊臀肌。","慢慢下放並重複動作。"],"3181":["仰臥，雙腳腳底貼合，雙膝自然往兩側打開。","將腳跟拉近髖部。","夾緊臀肌，將髖部往上推高。","在最高點停留一下。","下放並以輕快節奏重複推起。"],"3182":["仰臥，雙腳腳底貼合，雙膝往兩側打開。","將重物放在髖部上。","夾緊臀肌，將髖部往上推高。","在最高點停留一下。","下放並重複動作。"],"3183":["站立，雙手正握槓鈴，讓槓鈴懸垂在膝蓋下方。","髖部往後推，背部保持平坦，肩膀在槓鈴上方。","髖部往前猛力推展並爆發向上跳。","聳肩並將手肘往高處拉起。","身體快速下潛到槓鈴下方，用肩膀接住槓鈴。","站直身體，接著有控制地放下槓鈴。"],"3184":["用彈力帶將壺鈴或槓片懸掛在槓鈴兩端。","將槓鈴扛在上背並往後退出槓架。","站立，雙腳與肩同寬。","核心收緊，往下深蹲。","雙腳踩地發力站起。","使用較輕的重量，並放慢動作速度。"],"3185":["用彈力帶將重物懸掛在槓鈴兩端。","躺在長凳上並將槓鈴起槓。","將槓鈴穩在胸口正上方。","將槓鈴慢慢下放到中胸位置。","往上推起，並保持槓鈴穩定不晃。","使用比平常臥推更輕的重量。"],"3186":["用彈力帶將重物懸掛在槓鈴兩端。","將槓鈴架在肩膀高度，站直身體。","核心收緊並夾緊臀肌。","將槓鈴往正上方推過頭頂。","慢慢將槓鈴放回肩膀位置。","使用較輕的重量，並保持槓鈴穩定。"],"3187":["雙手將壺鈴捧在胸前。","保持挺胸往下深蹲。","往上爆發跳起。","膝蓋微彎輕柔落地。","重整姿勢後進入下一次深蹲。"],"3188":["用彈力帶將重物懸掛在啞鈴上。","躺在長凳上，雙臂伸直將啞鈴舉在胸口上方。","將啞鈴畫弧線往頭後方下放。","慢慢將啞鈴拉回胸口上方。","保持肋骨下壓、核心收緊。","使用輕重量以維持動作受控。"],"3193":["調整臀腿挺身機（GHD 機台）至符合身高。","雙腳踝卡緊固定墊，趴在機台上。","雙手交叉抱胸。","腿後腱與臀肌強烈收縮發力，將上半身挺起成一直線。","持續挺起至軀幹與雙腿成一直線。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"3194":["雙腳與肩同寬站立，雙臂伸直將槓鈴平舉於身前。","背部打直，屈膝屈髖下蹲，如坐入椅子。","蹲至大腿平行地面或略低。","停頓片刻，踩穩腳跟推回站姿。","重複所需次數。"],"3195":["調整腿彎舉機符合身材，坐在機台上背靠椅背。","雙腿小腿後側卡在滾輪墊上方。","抓緊兩側把手支撐。","上手臂與軀幹固定，吐氣收縮腿後肌群將小腿向後下方彎曲。","頂端停頓片刻，吸氣慢慢放回。","重複所需次數。"],"3196":["站直，膝蓋微彎。","用最快的速度在原地小碎步跑。","用前腳掌著地。","前後擺動雙臂。","保持挺胸。","持續 20 到 30 秒。"],"3197":["自然站直並放鬆。","帶著彈性往前小跑。","每一步都輕快地將膝蓋往上抬。","用前腳掌著地。","雙臂跟著節奏擺動。","持續 30 到 60 秒。"],"3198":["站姿，膝蓋微彎。","向斜前方一側跳出。","雙腳輕柔落地。","再向斜前方另一側跳出。","保持跳躍輕快敏捷。","持續 20 到 30 秒。"],"3199":["自然站直並放鬆。","往前跨一步，並用同一隻腳輕跳一下。","換腳跨出並輕跳。","每跨一步，對側手跟著往前擺。","前腳掌保持輕盈著地。","維持穩定的節奏。"],"3200":["調整座椅高度，面對機械划船機坐好。","正握抓 V 型握把，背部打直，膝微屈。","將 V 型握把拉向腹部，兩側肩胛骨向內夾緊。","頂端稍作停頓，慢慢放回原位。","重複所需次數。"],"3201":["平躺，雙膝彎曲，雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，將上半身捲離地面至約 45 度。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"3202":["平躺，雙膝彎曲，雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，將上半身捲離地面至約 45 度。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"3203":["平躺，雙膝彎曲，雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，將上半身捲離地面至約 45 度。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"3204":["平躺，雙膝彎曲，雙腳平踩。","雙臂伸過頭頂，維持伸直。","腹肌發力收緊，將上半身完全捲起坐直（仰臥起坐）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"3211":["跪在地上，雙手撐地與肩同寬，手指朝前。","雙腿向後伸展成高棒式，身體成一直線。","手肘微收彎曲，將身體降向地面。","胸部快貼地時推直手臂回到高棒式。","重複所需次數。"],"3212":["雙腳與肩同寬站立，雙臂垂於身側。","向前彎腰屈髖，背部維持平直，膝微彎。","雙手向下伸展觸碰腳尖，感受腿後肌群拉伸。","底部停頓片刻，緩慢站直回原位。","重複所需次數。"],"3213":["雙腳分開與肩同寬站立，雙臂向兩側水平展開。","軀幹向右側屈，右手伸向右腳踝，左臂向上延伸。","回到中央，換向左側屈伸展，左手伸向左腳。","左右交替側屈重複至指定次數。"],"3214":["雙腳與肩同寬站立，雙臂水平展開。","保持腿部伸直，向前屈髖，右手向下觸碰左腳尖（風車式）。","觸碰同時左腿向後上方伸直抬起維持平衡。","回正後換左手觸碰右腳尖、右腿向後抬起。","交替進行至所需次數。"],"3215":["雙腳與肩同寬站立，雙臂展開。","屈髖前傾，背打直膝微彎。","雙手向下伸並在雙腿後方交扣。","慢慢將雙手畫圓舉過頭頂，雙腿伸直。","持續畫圓下落觸碰腳尖。","反向動作將手帶回起始位置。","重複所需次數。"],"3216":["高棒式姿勢開始，雙手略寬於肩，身體成一直線。","彎曲手肘降下身體進行伏地挺身。","推起時順勢右手離地拍打胸口。","降下進行下一次伏地挺身。","推起時換左手拍打胸口。","交替進行至所需次數。"],"3217":["伏地挺身姿勢開始，雙手略寬於肩，雙腳與臀同寬。","手肘彎曲下沉身體，同時重心後推將臀部推向天花板成倒 V 字形（下犬式推回）。","胸部貼地滑過，隨後伸直手臂推起成眼鏡蛇式/上犬式。","逆向將臀部再次推向天花板成倒 V 字形。","收回成高棒式，重複此流程（印度伏地挺身 Dive Bomber）。"],"3218":["雙腳與肩同寬站立，雙手在胸前合十。","膝微屈，屈髖前傾，背打直。","雙手向腳尖方向畫圓延伸，在舒適範圍內拉伸。","底部停頓片刻，慢慢站回原位。","重複所需次數。"],"3219":["雙腳與肩同寬站立。","向上輕跳，在空中將右腿交叉在左腿前。","落地時快速換腿起跳，將左腿交叉在右腿前。","持續快速交替交叉跳躍。","重複所需次數。"],"3220":["雙腳與肩同寬站立。","屈膝下蹲進入深蹲。","雙腿爆發性起跳騰空，雙腿雙臂向外展開成星形。","雙腳開立輕巧著地緩衝，隨即沉入深蹲。","重複所需次數。"],"3221":["雙腳分開與肩同寬站立。","屈膝屈髖下沉，如坐入椅子（徒手深蹲 Air Squat）。","挺胸背打直，重心落於腳跟。","底部稍作停頓，踩穩腳跟推回站姿。","重複所需次數。"],"3222":["雙腳與肩同寬站立。","屈膝下沉進入深蹲。","雙臂後擺順勢起跳，爆發性向上騰空（深蹲跳 Jump Squat）。","前腳掌輕盈著地緩衝，隨即順勢沉入下一次深蹲。","重複所需次數。"],"3223":["雙腳與肩同寬站立，雙臂垂於體側。","微屈膝蓋，爆發性向上起跳。","在空中雙腿向兩側張開，雙臂斜上方伸展成星形（星形跳 Star Jump）。","膝蓋微屈輕巧落地緩衝。","重複所需次數。"],"3224":["雙腳併攏站立，雙臂放身側。","向上輕跳雙腳分開，雙臂向上在頭頂拍手（開合跳 Jumping Jack）。","落地隨即輕跳雙腳併攏，雙臂放回身側。","重複所需次數。"],"3225":["俯臥，雙臂向兩側張開成 T 字形。","額頭貼近地板。","大拇指朝向天花板。","夾緊肩胛骨，將雙臂往上抬起。","在最高點停頓一下。","慢慢放下並重複動作。"],"3226":["俯臥，雙手掌心放在大腿下方。","頸部自然延伸，眼睛看地板。","用背部肌群的力量將胸口抬離地面。","夾緊臀肌。","維持 15 到 30 秒。","慢慢放下並休息。"],"3227":["俯臥，雙臂向前延伸。","將胸口與雙腿稍微抬離地板。","雙腿快速、小幅度地交替上下踢動。","保持頸部自然延伸。","保持穩定呼吸。","持續 20 到 30 秒。"],"3228":["俯臥，雙手放在頭部兩側。","雙腿伸直，雙腳貼地。","用下背的力量將胸口抬起。","在最高點稍微停頓。","慢慢放下。","頸部與脊椎保持一直線。"],"3229":["俯臥，雙手放在肩膀附近。","將胸口抬離地板。","雙臂往身體前方推出。","將雙臂拉回肩膀旁。","慢慢放下胸口。","全程保持頸部自然延伸。"],"3230":["俯臥，雙手在下背交扣。","頸部自然延伸，眼睛看地板。","將胸口抬離地板。","雙手往雙腳方向延伸。","維持 15 到 30 秒。","慢慢放下並休息。"],"3231":["雙腳與肩同寬站立，雙臂向兩側水平展開。","屈髖向前俯身，背部打直，膝蓋微彎。","雙手向下伸展摸向腳尖，保持雙腿打直。","底部停頓片刻，慢慢站直回原位。","重複所需次數。"],"3232":["將繩索安裝在胸口高度的滑輪上。","握住繩索兩端並往後退一步。","站立，膝蓋微彎。","手肘抬高並往外張，將繩索拉向臉部。","夾緊後三角肌。","慢慢回放。"],"3233":["坐在滑輪划船機上，雙腳踩穩。","掌心朝上握住握把。","坐直並挺胸。","將握把拉向下肋骨處。","夾緊肩胛骨。","慢慢回放，背部不要拱起。"],"3234":["平躺在平凳上，雙手各握一啞鈴，掌心相對。","雙臂垂直伸展於胸前，手肘微屈。","手肘維持微彎，將雙臂以弧線向兩側打開，感受胸大肌拉伸（啞鈴飛鳥）。","停頓片刻，胸肌發力將啞鈴夾回胸前正上方。","重複所需次數。"],"3235":["滑輪調至最低位並扣上腳踝套。","俯臥趴在平凳上，雙腿伸展，腳踝套固定在腳踝。","抓穩椅身維持穩定。","上半身貼平，吐氣收縮腿後腱將小腿拉向臀部。","頂峰停頓片刻，擠壓腿後肌群。","吸氣慢慢放回。","重複所需次數。"],"3236":["跪姿於地面，雙膝與臀同寬，腳尖點地。","彈力帶套在膝蓋上方大腿處。","雙手叉腰或向前平舉平衡。","啟動臀肌與核心。","骨盆向前推直挺起身軀，大腿垂直地面，頂峰夾緊臀部。","稍作停頓，緩慢降回腳跟。","重複所需次數。"],"3237":["站立雙腳與肩同寬，膝蓋微屈。","正握抓槓鈴置於肩部前側。","核心收緊背打直，將槓鈴向上前方斜推推至肩高。","頂端停頓片刻，慢慢降回肩前。","重複所需次數。"],"3238":["跪姿，前臂放在地板上，手肘對齊肩膀下方。","抬起髖部，讓身體從膝蓋到頭部呈一直線。","收緊核心並夾緊臀肌。","保持頸部中立。","維持 20 到 45 秒。","放下身體並休息。"],"3239":["高棒式姿勢開始，雙手在肩膀正下方，雙腳與臀同寬。","核心收緊，骨盆維持水平穩定不晃動。","抬起右手輕拍左肩，放回地面。","抬起左手輕拍右肩，放回地面（棒式拍肩 Plank Shoulder Taps）。","兩側交替進行至所需次數。"],"3240":["背靠牆站立，將抗力球夾在下背部與牆面之間。","雙腳與肩同寬微前站。","雙手各握一啞鈴垂於體側。","雙膝之間夾一顆網球加強內收肌群收縮。","小腿發力抬起腳跟踮起腳尖。","頂端停頓片刻，慢慢降回腳跟。","重複所需次數。"],"3241":["面對牆壁站立，雙手扶牆。","抗力球夾在下背與牆壁間。","雙手各持一啞鈴垂於體側。","兩腳踝間夾一顆網球。","收縮小腿盡可能抬高腳跟踮腳尖。","頂端停留片刻，慢慢放回。","重複所需次數。"],"3242":["仰臥，雙膝彎曲。","雙手將單側膝蓋拉向胸口。","下背放鬆貼平地板。","維持 20 到 30 秒。","換腳重複。"],"3243":["仰臥。","將雙膝拉向胸口。","雙臂環抱小腿前側。","維持 20 到 30 秒。","慢慢放開。"],"3244":["俯臥，雙手放在肩膀下方。","雙手推地，將胸口抬起。","髖部貼在地板上。","直視前方並放鬆。","維持 20 到 30 秒。"],"3245":["坐姿，雙腿往前伸直。","腳跟貼在地板上。","將雙腳慢慢往外側翻轉。","接著再往內側翻轉。","持續 20 到 30 秒。"],"3248":["站立，雙腳與髖部同寬。","髖部折起往前傾，雙手伸向腳趾。","頭部自然放鬆下垂。","慢慢站起。","以穩定的節奏重複。"],"3249":["站立，雙腳寬站。","髖部折起往前傾，雙臂一起往下延伸。","觸碰地板或腳趾。","慢慢站起。","重複執行直到完成該組。"],"3250":["站立，雙腳寬站。","單手伸向對側腳。","另一隻手往身後延伸。","站起並換邊。","以輕鬆的節奏交替進行。"],"3251":["站立，雙腳寬站。","上半身稍微轉向一側。","雙手一起伸向該側的腳。","站起，接著轉向另一側。","以穩定的節奏重複。"],"3253":["站立，雙腳與肩同寬。","單臂舉過頭頂。","身體往側邊彎曲，手臂向對側延伸。","回到直立姿勢。","換邊重複。"],"3254":["站立，雙腳與肩同寬。","雙手在頭頂上方交扣。","身體往一側彎曲，髖部保持不動。","回到中間。","往另一側彎曲並重複。"],"3256":["站立，雙腳與肩同寬。","雙手放在腦後，手肘往外張開。","身體往一側彎曲，不要扭轉。","回到中間。","往另一側彎曲並重複。"],"3257":["站直，雙腳與肩同寬。","單臂向側邊平舉延伸。","慢慢畫圈，幅度逐漸變大。","反方向畫圈。","換手進行。"],"3258":["站直，雙腳與肩同寬。","雙臂向兩側平舉延伸。","慢慢往前畫圈。","接著反方向畫圈。","保持肩膀放鬆。"],"3259":["站直，雙腳與髖部同寬，雙臂自然垂放在身體兩側。","單臂往前、往上再往後擺動，畫出一個平順的大圈。","當這隻手快畫完時，換另一隻手開始畫同樣的圈。","肋骨下收，頸部保持放鬆。","持續交替 20 到 30 秒，接著反方向進行。"],"3260":["站直，雙腳與肩同寬，雙臂在胸前平舉。","雙臂向兩側大幅甩開，同時夾緊肩胛骨。","將雙臂擺回胸前，讓一隻手交叉疊在另一隻手上方。","動作保持放鬆且受控，背部不要拱起。","重複擺動 15 到 20 次。"],"3263":["仰臥，雙腿伸直，雙手放在髖部下方或身體兩側。","將下背輕輕壓向地板。","雙腿併攏往上抬，直到指向天花板。","慢慢放下雙腿，在快碰到地板前停住。","保持雙腿伸直，且背部不要拱起。"],"3264":["側躺，用單側前臂撐起身體，手肘對齊肩膀下方。","抬起髖部，讓身體呈一直線。","將上方腿抬到約與髖部同高，腳趾朝前。","稍微放下腿，同時髖部不要往下掉。","完成次數後換邊。"],"3265":["四足跪姿開始，雙手略比肩寬。","胸口朝地板下放，手肘與身體夾約 45 度。","推起身體回到起始位置。","將髖部往後坐到腳跟上，雙臂向前延伸進入嬰兒式。","回到起始位置並重複。"],"3266":["從肘撐棒式開始，身體呈一直線。","先用單手推起，另一隻手跟上，推成高棒式。","接著一次一隻手，慢慢放回前臂撐地。","保持髖部穩定，避免左右搖晃。","每次交替由不同隻手先帶動。"],"3268":["仰臥，雙臂向兩側展開，雙腿往上伸直抬起。","肩膀貼穩地板。","雙腿併攏往一側下放，在快碰到地板前停住。","將雙腿帶回中間上方。","換往另一側重複，並持續左右交替。"],"3269":["站直，雙腳在髖部正下方。","以穩定的節奏原地跑，同時擺動雙臂。","每跑幾步就用單腳往上跳一下，並輕柔落地。","前腳掌保持輕盈著地。","以能維持的節奏持續 30 到 60 秒。"],"3270":["站直並開始原地慢跑。","跑幾步後，雙腳往外跳開，同時雙臂舉過頭頂。","雙腳跳回併攏，同時放下雙臂。","繼續原地跑並重複這個模式。","保持輕柔落地，持續 30 到 60 秒。"],"3271":["站直，雙腳與髖部同寬。","原地慢跑幾步。","停下來做一個淺屈膝，髖部往後推並保持挺胸。","站直並立刻接回原地跑步。","重複 30 到 60 秒。"],"3272":["站直並原地跑幾步。","往下蹲成半蹲姿勢，保持挺胸。","往上跳起，同時擺動雙臂。","雙膝微彎輕柔落地，接著繼續原地跑。","重複 30 到 60 秒。"],"3279":["仰臥，小腿放在長凳上，膝蓋彎曲約 90 度。","雙手輕放在腦後或交叉於胸前。","收緊腹肌，將肩膀捲離地板。","在最高點稍微停頓。","慢慢放下並重複，過程中不要硬拉頸部。"],"3280":["仰臥，小腿放在長凳上，雙膝彎曲。","雙手輕放在腦後。","往上捲起並轉動軀幹，讓單側肩膀朝對側膝蓋靠近。","受控地慢慢放下。","每次交替換邊。"],"3281":["史密斯槓調整在肩部高度。","雙腳與肩同寬站立，腳尖微外展。","鑽入槓下將槓鈴扛在斜方肌上。","握槓略寬於肩寬。","旋轉解鎖槓鈴後退站穩。","挺胸收腹，屈膝屈髖深蹲。","下蹲至大腿平行地面或略低。","底部稍作停頓，腳跟推地站回。","重複所需次數。"],"3282":["仰臥，小腿放在長凳上，雙膝彎曲。","將槓片或啞鈴抱在胸前。","收緊腹肌，將肩膀捲離地板。","在最高點停頓一下。","慢慢放下並重複。"],"3283":["仰臥，小腿放在長凳上，雙膝彎曲。","雙手將輕重量抱在胸前。","往上捲起並轉動單側肩膀朝對側膝蓋靠近。","受控地慢慢放下。","每次交替換邊。"],"3286":["正握抓單槓懸掛，握距略寬於肩寬。","啟動核心，挺胸將身體拉向單槓。","拉到頂峰時迅速變換握法為反握（掌心朝向自己）。","持續向上拉直到胸口觸碰單槓，停頓片刻。","控制速度緩慢降回起始位置。","重複所需次數。"],"3287":["坐在椅子或重訓椅邊緣，雙手抓緊臀部兩側椅緣。","臀部向前滑離椅面，雙腿伸直，腳跟著地。","手肘彎曲下沉身體貼近椅緣。","底部停頓片刻，手臂推直將身體撐回（直腿椅子撐體）。","重複所需次數。"],"3288":["雙手撐在雙槓上，雙臂伸展支撐全身重量。","彎曲手肘下沉身體，直到上手臂平行地面。","停頓片刻，手臂推直撐回頂端。","重複所需次數。"],"3289":["雙手撐在雙槓上，雙臂伸直支撐全身重量。","膝蓋彎曲，雙腳腳踝交叉。","彎曲手肘下沉身體，直到上手臂平行地面。","停頓片刻，手臂推直將自己撐回頂端。","重複所需次數。"],"3290":["正握抓單槓，握距略寬於肩。","雙臂伸展懸掛，身體維持直線。","手肘向下向後拉，背肌發力將身體拉向單槓。","持續拉至下巴超過單槓。","有控制地下放身體回到起始位置。","重複所需次數。"],"3291":["站立雙腳與肩同寬，雙臂高舉過頭頂。","膝微屈，收緊核心。","下蹲進入深蹲，雙臂維持高舉過頭（過頭深蹲 Overhead Squat）。","下蹲時雙臂向後下壓伸展三頭肌。","底部停頓片刻，腳跟發力站起，雙臂再次舉過頭頂。","重複所需次數。"],"3292":["雙腳與肩同寬站立，膝蓋微屈。","雙手叉腰或交叉抱胸。","背部維持挺直，屈髖前傾將上半身降向地面（早安式 Good Morning）。","底部感受大腿後側拉伸停頓片刻，臀大肌發力站回。","重複所需次數。"],"3293":["正握抓單槓懸掛，握距略寬於肩。","收緊核心，肩胛骨下沉後收。","單臂彎曲手肘將身體拉向單側，另一臂打直輔助（弓箭手引體向上 Archer Pull-up）。","拉至下巴過槓且彎曲手臂完全屈曲。","有控制地降回，換拉向另一側。","兩側交替進行。"],"3294":["高棒式姿勢開始，雙手略寬於肩。","單手向側邊水平打直伸出（弓箭手伏地挺身 Archer Push-up）。","彎曲支撐側手肘下沉身體，背部打直。","推回高棒式。","換另一側手臂向側邊伸直重複。","兩側交替進行至所需次數。"],"3295":["正握抓單槓，掌心朝外。","啟動核心，肩胛骨向下拉。","雙腿併攏完全打直，抬高至與地面平行（懸垂 L 撐體）。","盡可能維持此姿勢 10-20 秒。","慢慢降回雙腿。","重複所需次數。"],"3296":["正握抓單槓，雙手與肩同寬。","啟動核心，肩胛骨向下拉。","屈膝將雙膝抱向胸前。","同時將雙腿向前踢直，讓身體由垂直轉為水平平行地面（前水平 Front Lever）。","盡可能長時間維持前水平姿勢。","慢慢降回雙腿回懸掛姿勢。","重複所需次數。"],"3297":["正握抓單槓，握距略寬於肩。","收緊核心，肩胛後收下沉。","屈膝帶向胸前。","慢慢將雙腿向前上方伸直抬起，直到身體與地面平行。","維持此水平姿勢數秒，慢慢放回雙腿。","重複所需次數。"],"3298":["伏地挺身預備姿勢，雙手與肩同寬，雙腳分開。","核心收緊，重心前移使肩膀超過雙手腕關節（俄式挺身預備式 Pseudo Planche Push-up）。","手肘貼緊身側彎曲下沉身體。","底部停頓片刻，推直雙臂推回頂端。","重複所需次數。"],"3299":["高棒式開始，雙手在肩下方，手指朝前。","核心緊繃，重心大幅度前移，腳尖逐漸離地懸空。","持續前移重心直到身體平行地面，僅靠雙手支撐平衡（俄式挺身 Planche）。","盡可能維持身體平直一條線。","慢慢降回雙腳至地面。","重複所需次數。"],"3300":["高棒式開始，雙手與肩同寬，身體打直。","啟動核心，重心前移使雙肩超過雙手。","身體前傾時手肘微屈，身體維持直線。","維持前傾姿勢數秒，慢慢回正。","重複所需次數。"],"3301":["高棒式開始，雙手間距與肩同寬，雙腳併攏。","手肘彎曲下沉身體，背部打直。","下沉時雙腳離地，雙膝收向胸口（空中懸浮）。","維持數秒，雙腿向後蹬直推回高棒式。","重複所需次數。"],"3302":["在寬敞空地或牆壁前進行倒立（倒立撐體 Handstand Push-up）。","雙手撐地與肩同寬，手指朝前抓地。","雙腿蹬起靠牆成倒立姿勢，核心收緊肩膀發力。","手臂與肩膀支撐全身重量，手肘彎曲下沉頭部靠近地面。","三頭肌與三角肌發力推直手臂回到倒立頂端。","緩慢收腿落回地面。","重複所需次數。"],"3303":["雙手抓垂直立柱，雙臂完全伸展（人體國旗 Human Flag）。","收緊核心，雙腿伸直抬離地面。","運用核心與上半身側向推拉力量，將身體抬至與地面水平平行。","盡可能維持身體成一水平直線。","慢慢降回雙腿。","重複所需次數。"],"3304":["抓單槓完全懸掛放鬆。","收緊核心抬腿屈膝靠近胸部。","雙腿持續穿過雙臂之間向後翻轉（穿越翻轉 Skin the Cat）。","穿過頭頂後完全向後伸展吊掛拉伸肩膀。","核心發力依反向路徑翻轉回正面懸掛姿勢。","重複所需次數。"],"3305":["雙腳分開與肩同寬站立，正握槓鈴置於肩前。","屈膝屈髖向後下蹲成深蹲。","在深蹲底部踩穩腳跟爆發力蹬起，順勢將槓鈴推過頭頂（火箭推 Thruster）。","槓鈴降回肩部同時順勢下蹲進行下一次深蹲。","重複所需次數。"],"3306":["將器材在身前擺好。","雙手緊緊握住器材。","收緊核心，背部保持平坦。","用雙腿與髖部的力量將器材抬起。","穩定維持一下。","受控地將器材放下。"],"3307":["雙腳寬站，啤酒桶放在雙腿之間，雙手在低處抓穩桶身。","髖部折起，保持挺胸與背部平坦。","髖部用力往前推，同時將啤酒桶沿著身體往上拉。","全身完全伸展，將啤酒桶往後上方拋過橫桿。","重新準備，退回起始位置並受控地重複動作。"],"3308":["站立，雙腳與髖部同寬，槓鈴對齊足弓上方。","髖部折起往下，雙手在雙腿外側握槓，並收緊核心。","雙腳推地站起，過程中讓槓鈴貼近身體。","站直鎖死，髖部與膝蓋完全伸展，肩膀往後收。","背部保持平坦，讓槓鈴沿著雙腿下放回地板。"],"3309":["將槓鈴架在肩膀前側，手肘抬高，雙手扶穩槓鈴。","站立，雙腳與肩同寬，收緊核心。","往雙髖之間坐下去，保持挺胸。","下蹲到大腿至少與地板平行。","全腳掌推地站起，全程保持手肘抬高。"],"3310":["仰臥在長凳上，眼睛在槓鈴正下方，雙腳踩穩地板。","握距略比肩寬，將槓鈴起槓移到胸口上方。","受控地將槓鈴下放到中胸位置。","將槓鈴往上推回，直到雙臂伸直。","全程保持肩胛骨夾緊、雙腳踩穩。"],"3311":["將槓鈴設定在墊塊或深蹲架上，高度對齊肩膀前側。","往前走進槓下，將槓鈴架在肩膀前側並抬高手肘。","起槓並站直，雙腳與肩同寬。","保持挺胸往下深蹲，直到大腿低於水平面。","雙腳推地站起，接著將槓鈴放回架上。"],"3312":["正握抓單槓懸掛，握距略寬於肩寬。","收緊核心肩胛後收。","手肘彎曲將胸部拉向單槓。","胸口貼近單槓時，手腕向下翻轉、手肘向後翻上，順勢將上半身撐上單槓上方（暴力上槓 Muscle-up）。","在槓上頂端撐直手臂稍作停頓，控制速度緩慢下放回到懸掛。","重複所需次數。"],"3313":["雙手撐在雙槓上，雙臂伸展打直，身體呈直線。","手肘彎曲下沉身體，直到上手臂平行地面。","停頓片刻，手臂推直將自己撐回頂端。","重複所需次數。"],"3314":["吊環完全伸直懸掛，身體呈一直線。","雙腿張開成分腿跨坐姿態。","收緊核心慢慢降下身體，直到雙臂平行地面（十字懸吊 Iron Cross）。","維持姿勢數秒，發力推回頂端。","重複所需次數。"],"3315":["雙腳分開與肩同寬站立，雙臂向兩側水平展開。","慢慢向前俯身，手臂維持展開打直，直到上半身平行地面（T 字平衡）。","核心收緊維持數秒。","腳跟發力站起回原位。","重複所需次數。"],"3316":["槓鈴裝上輕到中等的重量，雙腳與髖部同寬站在槓鈴上方。","先做組合裡的第一個動作，例如硬舉。","不把槓鈴放下，直接接著做下一個動作。","核心收緊、背部打平，每一下都做得俐落。","完成一輪的所有動作後，放下槓鈴休息，再開始下一輪。"],"3317":["在車體邊緣蹲低，背部打平，雙手伸進車底。","收緊核心，挺起胸口。","雙腿用力蹬地，把車緣抬到髖部高度。","換手調整位置，用雙腿和雙手往上往前推。","讓車體完全翻過去，接著退後一步，準備翻下一次。"],"3318":["雙腳與肩同寬站立，膝蓋微彎。","雙臂向前水平伸直。","啟動核心，雙臂畫大圓擺動，同時順勢旋轉軀幹。","維持均勻呼吸，持續進行指定圈數。"],"3319":["仰躺在地板上，雙膝彎曲，雙手各拿一顆啞鈴，掌心朝內相對。","起始時上臂貼在地板上。","將啞鈴往胸口正上方直直推起。","在頂點短暫停頓，手肘不要死鎖。","慢慢下放，直到三頭肌碰到地板，再重複動作。"],"3320":["將長凳調成低角度上斜，胸口貼著椅墊趴好，雙手各拿一顆啞鈴。","雙臂自然下垂，掌心相對。","手肘帶動，將兩顆啞鈴往髖部方向拉起。","在頂點夾緊肩胛骨。","慢慢下放到手臂完全伸直，再重複動作。"],"3321":["雙手握住彈力帶，手臂在身前打直。","站直，膝蓋微彎，核心收緊。","雙手在肩膀高度往兩側拉開。","拉到底時夾緊肩胛骨。","慢慢回到起始位置，不要讓彈力帶直接彈回去。"],"3322":["雙腳與髖部同寬站立，壺鈴放在兩腳之間。","髖部往後推、膝蓋彎曲，雙手握住壺鈴把手。","挺胸，背部打平。","雙腳踩穩往上站直，同時夾緊臀肌。","以髖部後推的方式往下把壺鈴放回地板，再重複動作。"],"3323":["仰躺，單手將壺鈴往天花板推直，同側膝蓋彎曲踩地。","視線盯著壺鈴，手臂保持垂直地面。","身體轉向對側，先用手肘撐地，再改用手掌撐起。","坐起並挺直軀幹，持鈴的手臂依然在頭頂鎖定伸直。","依相反順序慢慢躺回地板，接著換邊。"],"3324":["將彈力帶固定在身後低處，雙手在胸口高度握住把手。","採前後分腿站姿，核心收緊。","單手往前上方推出，同時微微扭轉軀幹。","穩定收回，接著換另一隻手推出。","保持髖部穩定，整組動作左右交替進行。"],"3325":["將彈力帶固定在身前低處，雙手握住把手。","採前後交錯站姿，雙臂向前伸直。","單手將把手往髖部方向拉回，同時扭轉軀幹。","夾緊該側肩胛骨，再慢慢放回。","換另一隻手重複，持續左右交替。"],"3326":["將彈力帶固定在身前高處，雙手握住把手並高舉過頭。","採前後交錯站姿，身體站直。","單手將把手往肋骨方向拉下，同時扭轉軀幹。","手肘收近身體，肩膀下沉不聳肩。","慢慢放回起始位置，再換另一隻手。"],"3327":["伏地挺身姿勢開始，雙手略寬於肩。","收緊核心，手肘貼身彎曲下沉身體。","下沉同時重心大幅前移，雙腳離地，僅靠雙手平衡支撐。","胸部接近地面。","手掌用力推地伸直手臂回到原位。","全程身體保持成一直線。","重複所需次數。"],"3328":["正握輕槓鈴站立，槓鈴貼在大腿高度。","膝蓋微彎、背部打平，讓槓鈴順著雙腿往下放。","站起同時爆發力往上拉起槓鈴，翻到肩膀前側接住。","槓鈴架在肩上，穩定往前跨出一步。","退回原位，放下槓鈴，開始下一輪。"],"3329":["坐在羅馬椅上，雙腳勾在固定墊下方。","雙臂交叉抱胸，身體微微往後傾。","捲起軀幹往上，直到胸口靠近大腿。","在頂點短暫停頓，頸部保持放鬆。","穩定控制速度慢慢躺回，再重複動作。"],"3330":["仰躺，雙手放在頭側，雙膝彎曲。","同時抬起肩膀與雙膝。","扭轉軀幹，讓單側手肘朝對側膝蓋靠近。","短暫停留，再穩定下放。","整組動作左右交替進行。"],"3331":["仰躺，雙腿打直抬高，雙手放在頭側。","將肩膀抬離地板。","扭轉軀幹，讓單側手肘朝對側髖部靠近。","雙腿保持穩定，下背貼緊地面。","慢慢回到原位，左右交替進行。"],"3332":["坐在健身球上，雙腳往前走，直到背部靠在球面上。","雙手把重物抱在胸前。","讓軀幹順著球面往後仰，完全伸展腹肌。","往上捲腹，直到上背離開球面。","慢慢躺回伸展位置，再重複動作。"],"3333":["仰躺在長凳上，單手拿啞鈴舉在胸口上方。","空著的手放在腹部或伸向身體側面。","手肘往外打開、慢慢下放啞鈴，直到感覺胸肌拉伸。","將啞鈴推回胸口上方。","過程中保持軀幹端正不歪斜，做完一組再換手。"],"3334":["仰躺在地板上，雙膝彎曲，單手拿啞鈴舉在胸口上方。","手肘保持微彎。","手臂往側面打開下放，直到上臂碰到地板。","胸肌用力夾回，把啞鈴帶回身體上方。","做完所有次數後換手。"],"3335":["仰躺，雙膝彎曲，雙腳平踩地板。","雙手扶著一顆啞鈴橫放在髖部上。","腳跟用力踩地，將髖部往天花板方向頂起。","在頂點用力夾緊臀肌。","慢慢下放髖部，再重複動作。"],"3336":["平躺，雙腿伸直，雙手拿一顆啞鈴伸直舉在頭頂上方。","收緊核心。","手臂與雙腿同時往上抬起，讓身體呈 V 字形。","讓啞鈴往小腿前側靠近。","慢慢下放回原位，雙腿不要直接掉回地面。"],"3337":["側躺，手肘在肩膀正下方撐地，雙腿交疊。","另一隻手把啞鈴扶在上方髖部。","抬起髖部，讓身體呈一直線。","撐住 20 到 30 秒，腰部不要往下塌。","放下身體，再換邊重複。"],"3338":["單腳站立，對側手或雙手拿啞鈴。","站立腿的膝蓋保持微彎。","上半身從髖部往前傾，同時懸空腿往後延伸。","背部打平，將啞鈴朝地板方向下放。","夾緊臀肌站回起始位置，完成後換腳。"],"3339":["站直，單手拿啞鈴自然垂在身側。","往前跨出一大步。","後腳膝蓋朝地板下蹲，軀幹保持直立。","前腳用力推地，站回起始位置。","雙腳交替進行，做到一半時換手拿啞鈴。"],"3340":["雙腳與髖部同寬站立，雙手拿啞鈴放在大腿前側。","膝蓋保持微彎，背部打平。","髖部往後推，讓啞鈴貼著雙腿往下滑。","感覺大腿後側充分拉伸時停住。","髖部往前推，站回直立姿勢。"],"3341":["站直，雙手各拿一顆啞鈴垂在身側。","往前跨出一大步。","雙膝彎曲下蹲，直到後腳膝蓋接近地板。","前腳膝蓋對齊腳踝上方，軀幹保持直立。","推地回到起始位置，接著換腳。"],"3342":["將滑輪調到低位，雙手各握一個把手，手臂在身前交叉。","站直，身體微微前傾。","雙臂往斜上方舉起，張開成 Y 字形。","大拇指朝上，肩膀下沉不聳肩。","慢慢下放回起始位置。"],"3343":["調整座椅高度，讓肩膀對齊器械的旋轉軸心。","坐直，雙臂貼靠在軟墊上。","雙臂往兩側抬高到肩膀高度。","在頂點短暫停頓。","慢慢下放，不要讓配重片完全放到底。"],"3344":["調好座椅高度，手肘微彎握住把手。","坐直，背部貼緊椅背。","雙臂往胸前畫弧合攏。","在中間位置夾緊胸肌。","慢慢放回，直到感覺胸肌拉伸。"],"3345":["坐姿，單側前臂平放在大腿或長凳上，掌心朝上。","該手握住彈簧握力器。","彎曲手腕與手指，用力將握把壓合。","完全壓緊時短暫停留。","慢慢放開，做完預定次數後換手。"],"3347":["站直，雙手各拿一顆啞鈴，掌心朝前。","身體不晃動，將兩顆啞鈴彎舉到肩膀高度。","手腕順勢轉正，將啞鈴往頭頂上方推起。","先下放回肩膀高度，再放下到身體兩側。","全程收緊核心，肋骨往下收不外翻。"],"3348":["雙手撐在長凳或跳箱上，雙腳往後伸直呈棒式。","雙腳稍微踩寬一點以維持平衡。","抬起一隻手，輕碰對側肩膀。","保持髖部水平不搖晃，身體呈一直線。","以穩定節奏左右交替。"],"3349":["將滑輪調到低位，雙手把把手抱在胸前。","往後退一步拉出張力，雙腳與肩同寬站立。","挺胸，髖部往下往後坐進深蹲。","下蹲到大腿與地面平行。","腳跟用力推地站起。"],"3350":["側對滑輪機站立，雙手將低位滑輪把手抱在胸前。","往外側跨出一大步，髖部往後坐進該側腿。","另一隻腳保持打直，雙腳腳掌平貼地面。","彎曲腿用力蹬地，推回中間起始位置。","做完預定次數後換邊。"],"3351":["雙手在胸口高度握住滑輪把手，離配重塔退開一步。","往前跨出一大步。","後腳膝蓋朝地板方向下放。","軀幹保持直立，前腳腳跟踩穩地面。","推地站回原位，雙腳交替進行。"],"3352":["背對低位滑輪跪立，雙手從雙腿之間握住繩索。","背部打平，髖部往後坐。","順著繩索拉力，讓雙手往後退到雙膝之間。","髖部用力往前推，回到高跪姿。","在頂點夾緊臀肌，再重複動作。"],"3353":["背對高位滑輪，單手在頭頂上方握住把手。","採前後分腿站姿，手肘朝上。","將前臂往前上方伸展，直到手臂完全打直。","上臂保持固定不動。","慢慢放回，做完一組後換手。"],"3354":["將滑輪調到低位，雙手把把手貼在胸前。","雙腳與肩同寬站立。","挺胸，往下坐進深蹲。","膝蓋朝腳尖方向對齊。","腳跟用力踩地，推回站姿。"],"3355":["側對滑輪機站立，雙手在胸口高度握住滑輪把手。","往側面跨出一大步並彎曲該側膝蓋。","髖部往後推，保持挺胸。","彎曲腿用力推地回到原位。","做完預定次數後換邊。"],"3356":["背對滑輪機站立，雙手將低位滑輪把手抱在胸前。","往前跨出一大步。","後腳膝蓋朝地板下沉。","前腳膝蓋穩定對齊腳踝上方。","推地回到起始位置，接著換腳。"],"3357":["面對低位滑輪坐在地板上，雙腿往前伸，雙手握住繩索。","坐直，背部打直。","將繩索往胸口下緣拉近，拉到底時雙手往兩側拉開。","用力夾緊肩胛骨。","慢慢伸直手臂，再重複動作。"],"3358":["在高位滑輪下方跪坐或坐在地板上，雙手握住平行對握把手。","坐直，身體微微後傾。","將把手拉到上胸位置。","手肘往下、往後帶動。","慢慢放回，直到手臂完全伸直。"],"3359":["將兩側滑輪調到胸口高度，雙手各握一個把手。","往前跨一步，採前後分腿站姿。","雙手往前推出，直到手臂打直。","推到底時用力夾緊胸肌。","穩定控制速度慢慢放回。"],"3360":["四足跪姿開始，雙手在肩膀正下方，雙膝在髖部正下方。","雙膝稍微抬離地面 2-3 公分，背部維持平平如桌面，核心收緊（熊爬 Bear Crawl 預備式）。","右手與左腳同時向前邁一步，接著換左手與右腳前進。","維持核心緊繃、骨盆穩定不晃動，交替爬行。","持續向前爬行至指定距離或時間。"],"3361":["雙腳分開與肩同寬站立。","雙膝微屈，向右側跳躍，右腳單腳著地緩衝。","落地時左腿順勢向右後方擺動，左腳尖輕點地面（滑冰者跳 Skater Jump）。","隨即發力向左側蹬跳，左腳著地，右腿向左後方擺動。","左右交替流暢跳躍至指定次數。"],"3362":["仰躺在長凳上，滑輪在頭頂後方，雙手採窄握握住把手。","起始時手肘彎曲，把手停在胸口上方。","往上推起，直到手臂打直。","手肘保持貼近身體兩側。","慢慢下放，再重複動作。"],"3363":["將滑輪調到胸口高度，雙手採窄握握住把手。","採前後分腿站姿，收緊核心。","往前推出，直到手臂完全打直。","手肘保持收在身體兩側。","慢慢放回起始位置。"],"3364":["背對胸口高度的滑輪，坐在長凳上。","雙手採窄握握住把手。","往前推出，直到手臂打直。","背部貼緊椅背。","慢慢放回，再重複動作。"],"3365":["雙腳略寬於肩站立，腳尖微朝外。","收緊核心並保持挺胸。","髖部往下往後坐，蹲進深蹲位置。","在底部短暫停頓，背部不要拱起。","雙腳用力踩地站起。"],"3366":["單腳站立，另一腳膝蓋彎曲，用手在身後拉住該側腳背。","空著的手往前伸以維持平衡。","慢慢下蹲，直到後腳膝蓋輕觸地板。","前腳用力踩地站起。","做完預定次數後換腳。"],"3367":["單腳站立，另一腳膝蓋彎曲、腳掌在身後抬離地面。","雙臂往前擺以維持平衡。","髖部往後坐，單靠站立腿往下蹲。","讓後腳膝蓋輕點地板附近。","前腳用力踩地站起，做完預定次數後換腳。"],"3368":["雙腳站得比髖部略寬，雙手合握一顆啞鈴。","髖部往後推，將啞鈴擺到雙腿之間。","髖部快速往前頂，把啞鈴盪到胸口高度。","雙臂保持放鬆不刻意拉舉。","順勢帶回雙腿間，直接進入下一次髖鉸鏈。"],"3369":["雙手各握一端繩頭，雙腳與肩同寬站立。","往下坐進深蹲姿勢。","雙臂上下交替甩動戰繩。","保持挺胸，膝蓋穩定不內夾。","以穩定節奏持續設定的時間。"],"3370":["雙手握住繩頭，站成深蹲姿勢。","雙臂開始交替上下甩出繩浪。","爆發力往上跳起，再輕柔落地。","落地後直接連貫進入下一個深蹲。","在設定時間內持續進行，需要時再休息。"],"3371":["雙膝微彎採運動預備站姿，雙手握住繩頭。","將兩條戰繩一起甩向身體一側。","接著流暢地甩向另一側。","讓軀幹順勢微微跟著旋轉。","在設定時間內維持穩定節奏。"],"3372":["雙手握住繩頭，雙腳併攏站立。","往側面跨出一大步，坐進側弓步。","雙臂交替上下甩動戰繩。","推地回到中間位置。","左右交替跨步，過程中持續甩出繩浪。"],"3373":["雙膝微彎站立，雙手各握一端繩頭。","雙臂朝內側方向畫圈轉動。","保持兩邊圓圈大小一致且幅度飽滿。","收緊核心並保持挺胸。","持續設定的時間後再休息。"],"3374":["雙膝微彎站立，雙手各握一端繩頭。","雙臂朝外側方向畫圈轉動。","保持動作流暢、兩邊幅度平均。","收緊核心。","持續進行設定的時間。"],"3375":["雙膝微彎站立，雙手各握一端繩頭置於身前。","雙臂往兩側大幅張開並微微上抬。","再將雙臂在身前合攏收回。","維持穩定的動作節奏。","持續進行設定的時間。"],"3376":["雙腳併攏，雙手握住繩頭。","雙腳往外跳開，同時雙臂上舉甩出繩浪。","跳回起始位置。","落地時保持輕柔緩衝。","在設定時間內維持穩定節奏。"],"3377":["坐在地板上，雙膝彎曲，上半身微微後傾。","雙手在身前握住繩頭。","軀幹轉向一側並將戰繩甩過去。","接著轉向另一側甩動。","保持挺胸，持續進行設定的時間。"],"3378":["雙手握住繩頭，採前後分腿站姿。","雙臂開始上下甩出繩浪。","往上跳起，在空中前後換腳。","輕柔落地成弓步姿勢。","在設定時間內持續跳躍換腳。"],"3379":["雙腳與肩同寬站立，雙手各握一端繩頭。","雙膝微彎。","雙臂高舉過頭，再用力將戰繩往下砸。","快速重複以打出大幅度的繩浪。","在設定時間內全程收緊核心。"],"3380":["雙手各握一端繩頭，站成四分之一深蹲。","收緊核心並保持挺胸。","快速上下甩動戰繩，讓繩浪貼著地板低處推進。","保持繩浪均勻，髖部穩定不晃。","以高強度節奏持續 20 到 30 秒。","休息一下，再重複數輪。"],"3381":["躺在穩固的桌子下方，雙手抓住桌緣。","雙腿伸直、腳跟點地，讓身體呈一直線。","夾緊肩胛骨，將胸口拉向桌緣。","穩定控制速度下放，直到手臂打直。","全程保持髖部抬高不往下掉。"],"3382":["躺在穩固的桌子下方，雙手抓住桌緣。","雙膝彎曲，雙腳平踩地板。","抬起髖部，讓膝蓋到肩膀呈一直線。","夾緊肩胛骨，將胸口拉向桌緣。","慢慢下放，再重複動作。"],"3383":["雙腳踩在長凳上，雙手撐地，髖部高高頂起。","雙手往後走近，直到身體呈倒 V 字形。","彎曲手肘，讓頭部朝地板方向下放。","手肘與身體保持約 45 度夾角。","往上推回，直到手臂打直。","全程收緊核心。"],"3384":["雙手各握一端繩頭，採運動預備站姿。","雙臂將戰繩高舉過頭，同時踮起腳尖。","用力將戰繩往下砸，同時下蹲。","背部打平，核心收緊。","回到預備姿勢，以穩定有力的節奏重複。","每次全力衝刺 15 到 30 秒。"],"3385":["坐在器械上，背部緊貼椅背。","雙腳踩在踏板上，約與肩同寬。","解開安全扣，下放重量直到膝蓋彎曲約 90 度。","全腳掌用力推蹬，將雙腿伸直。","在膝蓋完全死鎖前停住。","穩定控制下放，再重複動作。"],"3386":["坐在器械上，背部貼緊椅背。","小腿下緣勾在滾筒下方，讓膝蓋對齊器械轉軸。","往上伸展雙腿，直到接近完全打直。","在頂點短暫用力收縮股四頭肌。","慢慢下放回起始位置。","避免甩動身體或讓髖部抬離椅墊。"],"3387":["將兩張穩固的椅子面對面放好，並靠牆抵住防滑。","雙手扶住椅面，撐起身體並打直手臂。","彎曲手肘下放身體，直到上臂約與地面平行。","手肘朝後，保持挺胸。","往上推起，直到手臂打直。","務必確認椅子不會滑動。"],"3388":["在兩張穩固的椅子之間架好堅固長桿或桌板，仰躺在下方。","雙手握住橫桿、手臂打直，身體維持棒式一直線。","將胸口朝橫桿方向拉起。","在頂點夾緊肩胛骨。","慢慢下放，直到手臂打直。","全程保持髖部抬高不掉下去。"],"3389":["仰躺，雙膝彎曲，將小腿平放在椅面上。","雙臂交叉抱胸，或雙手輕放耳側。","將軀幹往膝蓋方向捲起。","在頂點短暫停頓。","慢慢躺回地板。","雙手不要硬扳脖子。"],"3390":["前腳掌踩在台階邊緣，手扶椅子維持平衡。","讓腳跟往下低於台階，充分伸展小腿。","盡可能往上踮高腳尖。","在最高點停留 1 秒。","慢慢下放回深度伸展的位置。","膝蓋保持接近打直。"],"3391":["雙腳寬站，背部打平從髖部往前俯身。","雙臂往兩側平舉張開。","扭轉軀幹，單手朝對側腳掌延伸。","回到中間，再轉向另一側。","動作保持穩定受控，髖部擺正不歪斜。","每側做 10 到 12 次。"],"3392":["腳跟踩在矮平台上，雙腳靠攏站立。","雙臂往前平舉以維持平衡。","往下深蹲，膝蓋朝腳尖方向推進。","保持挺胸，在舒適範圍內盡量蹲深。","雙腳用力踩地推起。","站直即可，膝蓋不要死鎖。"],"3393":["仰躺，雙臂放在身體兩側，或雙手抓住頭頂後方的固定物。","將雙腿往上抬到垂直地面。","把髖部抬離地板，雙腳朝天花板方向往上頂。","慢慢下放髖部。","接著下放雙腿，過程中下背不要拱起。","動作保持流暢，不要靠慣性甩動。"],"3394":["仰躺，雙膝彎曲，雙腳平踩地面。","抬起髖部呈臀橋姿勢。","單腳膝蓋往胸口抬起，過程中髖部不要往下掉。","放回該腳，換抬起另一腳。","全程持續夾緊臀肌。","左右交替進行 10 到 20 次。"],"3395":["仰躺在光滑地板上，雙腳腳跟踩在毛巾上。","抬起髖部呈臀橋姿勢。","腳跟往前滑開，直到雙腿接近打直。","用力將腳跟往髖部方向拉回。","全程保持髖部抬高。","放慢速度，維持動作穩定受控。"],"3396":["仰躺，雙腿伸直。","雙手抱住一邊膝蓋，往胸口方向拉近。","停留 20 到 30 秒。","再次將腿伸直，並往下壓向地板。","換另一條腿重複。","慢慢呼吸，保持身體放鬆。"],"3397":["雙手合握一顆啞鈴，雙腳與肩同寬站立。","髖部往後推，將啞鈴擺到雙腿之間。","髖部用力往前推，把啞鈴一路盪到頭頂上方。","順勢讓啞鈴落下，再次後推髖部。","保持背部打平，手臂放鬆不緊繃。","全程抓穩並控制好啞鈴。"],"3398":["雙手各拿一顆啞鈴，舉在肩膀高度。","往前跨出一大步。","後腳膝蓋朝地板下放。","保持軀幹直立，前腳膝蓋對齊腳踝上方。","推地回到起始位置。","每一下左右腳交替進行。"],"3399":["將槓鈴架在前肩上，手肘抬高。","往前跨出一大步。","後腳膝蓋朝地板下放。","保持挺胸，核心收緊。","前腳用力推地回到原位。","可左右交替，或單邊做完所有次數再換腳。"],"3400":["站在兩顆啞鈴上方，背部打平俯身握住啞鈴。","爆發力將啞鈴往上拉起，在肩膀高度翻腕接住。","膝蓋微蹲後用力往上蹬，將啞鈴推過頭頂。","手臂在頂點完全打直鎖定。","先下放回肩膀，再穩定放回地板。","過程中讓啞鈴盡量貼近身體。"],"3401":["雙腳放在一張長凳上，雙手撐在地板或另一張長凳上。","抬高髖部呈倒 V 字形屈體姿勢。","頭部朝雙手之間往下放。","手肘保持約 45 度夾角。","往上推回，直到手臂打直。","全程收緊核心。"],"3402":["將兩張穩固的椅子擺成與肩同寬，雙手握住椅面。","雙腳往後走並抬高髖部，呈倒 V 字形屈體姿勢。","彎曲手肘，將頭部往兩張椅子之間下放。","背部打平，手肘微微往內收。","往上推回原位。","務必確認椅子穩固不滑動。"],"3403":["站直，雙臂垂在身側，大拇指朝上。","雙臂往斜上方舉起，呈 Y 字形。","將肩胛骨往下、往後收緊。","短暫停頓，再慢慢下放。","保持頸部修長放鬆，避免聳肩。"],"3404":["站直，雙臂在胸口高度往前平舉。","雙臂往兩側打開，呈 T 字形。","用力夾緊肩胛骨。","短暫停頓，再慢慢放回。","肋骨往下收，避免身體往後仰。"],"3405":["站直，手肘彎曲，雙手放在胸前。","手肘往後、往下拉，讓雙臂呈 W 字形。","夾緊肩胛骨，同時將雙手往外旋轉。","短暫停頓。","慢慢放回，再重複動作。"],"3407":["雙腳略寬於髖部站立，膝蓋微彎放鬆。","雙手放在腰前。","將髖部與軀幹一起轉向一側。","回到中間，再轉向另一側。","流暢地進行，每側做 10 到 15 次。"],"3408":["雙腳與髖部同寬站立，雙手在胸前十指交扣。","保持髖部朝向正前方。","在舒適範圍內，將上半身盡量轉向一側。","回到中間，再轉向另一側。","保持動作流暢，每側做 10 到 15 次。"],"3409":["站直，雙腳與肩同寬。","雙臂往前、往上畫大弧線擺起。","接著往下經過髖部、往身後擺去。","保持動作放鬆且有節奏。","持續進行 20 到 30 秒。"],"3410":["雙腳與髖部同寬站立，雙手在身前交握。","軀幹轉向一側，同時雙手跟著扭轉過去。","回到中間，再轉向另一側。","髖部盡量保持朝向正前方。","每側持續做 10 到 15 次。"],"3411":["雙腳與肩同寬站立，雙手叉腰。","將髖部推向一側，接著往前、往後繞一圈。","畫出又大又流暢的圓圈。","保持肩膀穩定不動。","畫 10 圈後，換反方向繞圈。"],"3412":["仰躺，雙膝彎曲，雙腳平踩地板。","夾緊臀肌，將髖部微微抬離地面。","維持夾緊狀態 2 秒。","下放髖部，但臀肌不要完全放鬆。","重複 12 到 15 次。"],"3413":["仰躺，雙臂往身體兩側平放伸直。","雙臂貼地往上畫弧線，朝頭頂方向合攏。","在舒適範圍內，盡量讓手臂貼近地板。","沿著相同軌跡滑回原位。","放慢速度，做 10 到 12 次。"],"3414":["側躺，雙膝彎曲，雙臂在身前伸直合掌。","雙膝保持交疊不移位。","抬起上方手臂，往對側地板打開翻轉，視線跟著手移動。","將手臂帶回起始位置。","做完 10 次後換邊。"],"3415":["跪姿並固定好腳踝，軀幹保持直立。","依需求握住或拉住輔助器材。","用大腿後側出力抵抗，身體慢慢往前傾。","在你能控制的範圍內盡量往下放。","靠大腿後側出力拉回身體，需要時可用雙手推地輔助。","全程保持髖部伸直不折腰。"],"3416":["站直，雙臂自然垂放在身體兩側。","將肩膀往上提起，再往後畫大圈轉動。","頸部保持放鬆。","畫 10 圈後，換反方向繞圈。"],"3417":["四足跪姿，雙手在肩膀正下方。","單手貼地向前延伸。","手臂往上並橫向翻開，同時轉動胸口。","手往天花板舉高，視線跟著手移動。","回到起始位置並重複，接著換手。"],"3418":["正握抓單槓，握距略寬於肩寬。","雙臂完全伸直懸掛，身體打直。","背闊肌與二頭肌發力，挺胸將身體拉向單槓，手肘貼近身體。","持續拉至下巴超過單槓。","頂端停頓片刻，慢慢降回懸掛。","重複所需次數。"],"3419":["坐在地上，雙腿向前伸直併攏。","雙手置於臀部兩側地面，手指朝前。","手掌用力推地，核心收緊將雙腿與臀部完全抬離地面（L 撐體 L-Sit）。","使雙腿平行於地面，身體呈 L 字形。","盡可能維持此懸浮姿勢。","慢慢放回地面。","重複所需次數。"],"3420":["坐在地上，雙腿向前伸展。","稍微向後傾斜，雙腿打直抬離地面。","同時上半身捲腹抬起，雙臂向前伸向小腿（V 字捲腹 V-Up）。","在頂點維持數秒，慢慢放回上半身與雙腿。","重複所需次數。"],"3422":["仰臥屈膝，雙手把藥球抱在胸前。","捲起上半身，讓肩膀離開地板。","在頂點收緊腹肌。","慢慢放下身體。","下巴不要貼胸。","向上捲起時吐氣。"],"3428":["站直，雙手各拿一個啞鈴放在大腿前側。","收緊核心，手肘保持微彎。","將啞鈴往前舉到肩膀高度。","短暫停留。","慢慢放下，身體不要晃動。"],"3433":["俯臥趴在墊子上，雙臂伸過頭頂。","收緊核心與背肌，同時將胸部與雙腿抬離地面（超人式）。","雙腿與雙臂如同游泳打水般交替上下快速拍打（俯臥打水 Swimmers）。","持續拍打至指定時間或次數。","慢慢降回墊上放鬆。"],"3435":["仰臥，單膝彎曲、腳掌平貼地面。","另一隻腳伸直。","腳跟踩地發力，將髖部抬高。","保持骨盆水平。","有控制地放下。","做完一組後換腳。"],"3436":["俯臥，雙手往前伸直。","將雙手、胸口與雙腿同時抬離地板。","收緊臀肌與下背。","停留 1 到 2 秒。","慢慢放下。","頸部保持自然中立。"],"3438":["躺在下斜長凳上，雙手抓住頂端邊緣。","將雙腿往上抬到髖部上方。","把髖部往天花板方向抬起。","先放下髖部。","再有控制地放下雙腿。","避免靠慣性擺盪。"],"3439":["站立，雙手拿藥球放在兩腿之間。","微蹲後用力向上爆發。","將球往上並往頭頂後方甩出。","身體完全延伸時將球往後拋出。","去把球撿回來。","重新站好姿勢並重複。"],"3440":["面對跳箱呈弓步站姿。","擺動雙臂並向上跳起。","雙腳輕柔地落在箱面上。","站直身體。","小心地走下來。","換另一隻腳在前並重複。"],"3441":["坐直，肩膀放鬆。","下巴輕輕往胸口方向收。","短暫停留。","慢慢抬頭，視線微微往上看。","只在舒適的範圍內活動。","流暢地重複 8 到 10 次。"],"3442":["雙腳與肩同寬站立，雙手將球舉過頭頂。","身體微微往後仰。","用力將球往前下方砸出。","雙臂順勢完成延伸。","把球撿起來。","重設姿勢並重複。"],"3443":["坐在地板上，雙手撐在身後的椅子上。","將髖部抬離地板。","彎曲手肘，放低身體。","手肘保持朝向後方。","將身體推回上方。","先把椅子靠牆抵住以策安全。"],"3444":["面對一張穩固的椅子。","將一隻腳完全踩在椅面上。","透過腳跟發力站起。","將另一隻腳也帶上來。","有控制地踩回地面。","單邊做完所有次數後換腳。"],"3448":["雙手各拿一個啞鈴。","往側邊跨出一大步。","髖部往後坐，並彎曲跨出去那側的膝蓋。","另一隻腳保持伸直。","蹬地推回中間。","左右交替進行。"],"3449":["坐姿屈膝，身體微微後傾。","雙手在身前握住一個啞鈴。","將軀幹轉向一側。","再轉向另一側。","保持挺胸。","有控制地移動。"],"3452":["站立，雙掌在身前垂直夾住一個啞鈴。","將啞鈴維持在胸口高度。","雙掌用力往中間擠壓。","將重量往正前方推直。","收回胸前。","全程保持雙掌擠壓的力道。"],"3454":["俯臥，雙手握住輕啞鈴並往前伸直。","抬起胸口、雙手與雙腿。","收緊臀肌。","短暫停留。","有控制地放下。","頸部保持自然中立。"],"3457":["站立，雙腳與肩同寬。","蹲下並將雙手放在地板上。","雙腳往後跳成棒式。","做一下伏地挺身。","雙腳跳回手邊並向上跳起。","以穩定的節奏重複。"],"3458":["坐姿或站姿，將雙腿張開到舒適的最大寬度。","腳趾保持朝上或朝前。","慢慢往下進入劈腿姿勢。","背部保持延伸。","停留 20 到 30 秒。","輕柔地收回雙腿。"],"3459":["仰臥，雙腿朝天花板舉起。","雙手放在身體兩側。","用小幅度的脈衝將髖部微微抬起。","放下並重複。","動作幅度保持小而集中。","做 15 到 20 下脈衝。"],"3460":["下方膝蓋彎曲，擺好側棒式。","身體保持一直線。","抬起髖部。","將下方的腿往上方腿的方向抬起。","有控制地放下。","換邊進行。"],"3461":["站直，雙腳與髖同寬，收緊核心。","有控制地跨入此變化式的弓步姿勢。","前膝對齊腳踝上方，軀幹保持直立。","流暢地走完完整活動範圍，不要彈震。","回到站姿，換邊重複。","作為熱身，每邊慢速做 8 到 10 次。"],"3462":["站直，雙腳與髖同寬，收緊核心。","有控制地跨入此變化式的弓步姿勢。","前膝對齊腳踝上方，軀幹保持直立。","流暢地走完完整活動範圍，不要彈震。","回到站姿，換邊重複。","作為熱身，每邊慢速做 8 到 10 次。"],"3463":["站直，雙腳與髖同寬，收緊核心。","有控制地跨入此變化式的弓步姿勢。","前膝對齊腳踝上方，軀幹保持直立。","流暢地走完完整活動範圍，不要彈震。","回到站姿，換邊重複。","作為熱身，每邊慢速做 8 到 10 次。"],"3464":["站直，雙腳與髖同寬，收緊核心。","有控制地跨入此變化式的弓步姿勢。","前膝對齊腳踝上方，軀幹保持直立。","流暢地走完完整活動範圍，不要彈震。","回到站姿，換邊重複。","作為熱身，每邊慢速做 8 到 10 次。"],"3465":["站直，雙腳與髖同寬，收緊核心。","有控制地跨入此變化式的弓步姿勢。","前膝對齊腳踝上方，軀幹保持直立。","流暢地走完完整活動範圍，不要彈震。","回到站姿，換邊重複。","作為熱身，每邊慢速做 8 到 10 次。"],"3466":["站直，雙腳與髖同寬，收緊核心。","有控制地跨入此變化式的弓步姿勢。","前膝對齊腳踝上方，軀幹保持直立。","流暢地走完完整活動範圍，不要彈震。","回到站姿，換邊重複。","作為熱身，每邊慢速做 8 到 10 次。"],"3467":["站直，雙腳與髖同寬，收緊核心。","有控制地跨入此變化式的弓步姿勢。","前膝對齊腳踝上方，軀幹保持直立。","流暢地走完完整活動範圍，不要彈震。","回到站姿，換邊重複。","作為熱身，每邊慢速做 8 到 10 次。"],"3468":["單腳腳跟往前點地，腳趾朝上。","該側腿保持伸直。","背部打直，從髖部往前傾。","感受大腿後側的伸展。","停留 20 到 30 秒。","換腳進行。"],"3469":["四足跪姿開始。","腳趾踩地，將髖部往後上方推高。","胸口往大腿方向壓。","雙臂保持伸直。","停留 20 到 30 秒。","輕柔地放低身體。"],"3470":["雙腳與臀部同寬站立，雙手叉腰。","右腳向前跨出一大步成弓箭步。","彎曲右膝約呈 90 度，膝蓋對齊腳尖方向。","右腳蹬地推回起始站姿。","換左腿向前跨步重複，交替進行至所需次數。"],"3471":["前後跨出大步站立。","前膝彎曲對齊腳踝上方。","舉起雙臂。","後腿保持伸直。","停留 20 到 30 秒。","換邊進行。"],"3472":["仰臥在地板上。","將單側膝蓋往胸口拉。","另一隻腳保持放鬆。","停留 20 到 30 秒。","慢慢放開。","換腳進行。"],"3473":["在支撐物旁站直。","將一腳腳踝跨在對側膝蓋上。","臀部微微往後坐。","感受髖部外側的伸展。","停留 20 到 30 秒。","換邊進行。"],"3474":["仰臥，雙臂往頭頂方向伸直。","將單側膝蓋往胸口拉。","手臂保持延伸。","停留 20 到 30 秒。","慢慢放開。","換腳進行。"],"3475":["仰臥在地板上。","雙手將雙膝抱向胸口。","覺得舒適的話可以輕輕左右搖晃。","停留 20 到 30 秒。","肩膀放鬆。","慢慢放開。"],"3476":["仰臥並將雙膝往內收。","將雙膝倒向同一側。","雙肩保持貼地。","停留 20 到 30 秒。","回到中間。","換邊進行。"],"3477":["仰臥並將雙膝收起。","將雙膝放低到右側。","雙肩保持貼地。","停留 20 到 30 秒。","緩慢呼吸。","回到中間。"],"3478":["仰臥並將雙膝收起。","將雙膝放低到左側。","雙肩保持貼地。","停留 20 到 30 秒。","緩慢呼吸。","回到中間。"],"3479":["站立，雙腳與髖同寬。","往下深蹲。","站起並將一隻腳往側邊踢出。","用手碰觸腳跟。","再次深蹲。","左右交替進行。"],"3480":["站直。","往後跨步進入深弓步。","像短跑選手一樣用力擺動雙臂。","推回站姿。","雙腿交替進行。","軀幹保持直立。"],"3481":["跨出大步進入弓步。","將後膝放低至接近地面。","軀幹保持挺直。","在低位短暫停留。","向上推起。","換腳進行。"],"3482":["站直，單腳往後跨一大步呈前後分腿站姿。","雙膝彎曲下蹲成弓步，後腳跟抬起。","像短跑一樣，前腳對側的手臂往前擺，另一手往後擺。","軀幹保持直立，前膝對齊腳踝上方。","前腳踩地推起身體，重複做完所有次數。","換腳並做相同次數。"],"3483":["俯臥，雙臂往頭頂方向伸直，雙腿打直。","將雙臂、胸口與雙腿抬離地面幾公分。","雙臂往兩側畫大弧線，一路往髖部方向掃。","沿著相同路徑將雙臂掃回頭頂上方。","全程保持頸部中立、雙腿離地。","做完一組後有控制地放下身體。"],"3484":["仰臥屈膝，雙手放在頭後方。","捲起上半身並轉動軀幹，讓單側手肘靠近對側膝蓋。","在頂點短暫停留。","有控制地將背部放回地板。","換邊重複，左右交替。","避免用手硬拉脖子。"],"3485":["將穩固的長槓架在兩張平穩的椅子上，人躺在下方。","雙手正握長槓，手臂伸直，屈膝且腳掌平踩地面。","從肩膀到膝蓋保持一直線。","將胸口往長槓方向拉起，同時夾緊肩胛骨。","慢慢放下直到手臂再次伸直。","確認椅子不會滑動。"],"3486":["將穩固的長槓架在兩張平穩的椅子上，人躺在下方。","雙手反握長槓，手臂伸直，膝蓋彎曲。","抬起髖部，讓身體保持一直線。","手肘靠近身體並彎曲，將自己往上拉起。","有控制地放下，直到手臂伸直。","每組開始前先確認椅子穩固。"],"3487":["將穩固的長槓架在兩張平穩的椅子上，高度要夠讓人坐在下方。","坐在或躺在長槓下方，雙手握距略寬於肩。","保持屈膝、雙腳踩地，提供輕微輔助。","手肘往下拉，將胸口拉向長槓。","慢慢放下直到手臂伸直。","盡量減少雙腿出力的輔助。"],"3488":["從伏地挺身姿勢開始，雙手在肩膀正下方。","手肘內收，將胸口放低至貼近地面。","往上推起並順勢讓髖部往前下沉。","抬起胸口、視線微往上看，呈眼鏡蛇式。","將髖部往後抬高，回到棒式。","動作保持流暢且有控制。"],"3489":["跪在墊子上，雙手放在肩膀正下方。","從頭到膝蓋保持一直線。","手肘貼近身體，將胸口放低至地面。","往上推起並讓髖部前沉，抬起胸口進入眼鏡蛇式。","將髖部往後移回起始位置。","流暢地重複動作。"],"3490":["在身前放一個穩固的箱子，雙膝跪在地板上。","雙手撐在箱子邊緣，握距略寬於肩。","從頭到膝蓋呈一直線。","手肘約呈 45 度，將胸口放低至箱面。","往上推回，直到手臂伸直。","避免髖部下塌。"],"3491":["雙手撐地，雙腳往身後的牆面踩上去。","雙手在肩膀正下方，身體保持一直線。","手肘內收，將胸口往地板方向放低。","往上推回直到手臂伸直。","收緊核心，保持髖部穩定。","做完後雙腳慢慢走下來。"],"3492":["從跪姿伏地挺身開始，雙手在肩膀正下方。","將胸口往地板方向放低。","往上推起並轉動軀幹，單手往天花板方向舉高。","視線短暫看向舉高的手。","把手放回地面，接著往下做下一次。","每次左右交替。"],"3493":["單腳站在低箱或長凳前方。","另一隻腳往前伸，雙臂舉起維持平衡。","髖部往後坐並往下蹲，直到輕觸箱面。","保持挺胸，膝蓋朝腳趾方向對齊。","腳跟發力站起。","做完所有次數後換腳。"],"3494":["單腳站立，另一隻腳微微離地。","髖部往後坐並屈膝下蹲。","伸手往下碰觸站立腳的腳跟。","盡量保持挺胸。","腳掌踩地推起身體。","做完所有次數後換腳。"],"3495":["仰臥屈膝，腳掌平貼地面。","雙手伸直抓住穩固的固定點，例如繞在柱子上的毛巾。","手肘往後帶，將身體往雙手方向拉起。","用力夾緊肩胛骨。","慢慢放下直到手臂伸直。","髖部保持貼地或靠近地面。"],"3496":["仰臥，雙手放在身體兩側。","下背輕輕貼緊地板。","將一隻腳伸直往天花板抬起。","放下的同時抬起另一隻腳。","以緩慢穩定的節奏持續交替。","避免下背拱起。"],"3497":["在光滑地板上跪姿或俯臥，雙手放在毛巾上。","開始時雙臂往頭頂方向伸直。","手往下壓並將雙臂往髖部方向拉回，帶動毛巾滑行。","在末端收緊背闊肌。","有控制地將雙手滑回頭頂上方。","保持核心收緊。"],"3498":["仰臥在光滑地板上，雙腳腳跟放在毛巾上。","抬起髖部進入橋式。","將腳跟往外滑出，直到雙腿接近伸直。","將腳跟往臀肌方向拉回。","全程保持髖部抬高。","最後放下髖部完成這一組。"],"3499":["將穩固的長槓設在髖部或更低高度，雙手正握懸吊在下方。","雙腳踩地，視需要提供輔助。","將胸口拉向長槓，同時讓髖部抬起。","在活動度允許範圍內，繼續將軀幹往上轉過長槓、靠近雙手。","順著原路慢慢回到起始位置。","雙腿只在必要時出力輔助。"],"3500":["站立，雙腳略寬於肩，腳趾微朝外。","往下進入深蹲，腳跟保持貼地。","雙手合十，用手肘頂開膝蓋內側。","在底部停留並輕輕左右移動重心。","保持挺胸。","慢慢站起。"],"3501":["擺好前臂棒式，手肘在肩膀正下方。","身體保持一直線。","在不轉動髖部的情況下，將單腿抬高幾吋。","放下後換抬另一隻腳。","收緊核心並保持髖部水平。","穩定呼吸。"],"3502":["在牆壁或支撐物旁站直，單手扶著維持平衡。","將重心移到內側腿上。","外側腿以受控的弧度前後擺動。","軀幹保持直立。","逐漸加大擺動幅度。","做完設定次數後換腳。"],"3503":["以前臂撐起側棒式，上方的手放在頭後方。","抬起髖部，讓身體呈一直線。","收緊腹肌，將上方手肘與膝蓋往中間靠攏。","延伸回到側棒式。","全程保持髖部抬高。","做完所有次數後換邊。"],"3504":["站直，需要時可扶牆維持平衡。","單膝彎曲，在身後抓住腳踝。","雙膝併攏，將腳跟往臀肌方向拉。","骨盆微收並保持挺胸。","停留 20 到 30 秒。","放開並換腳。"],"3505":["跪姿，雙膝與髖同寬，雙手扶在下背。","將髖部往前推並抬起胸口。","身體往後傾，覺得舒適的話雙手可往後抓腳跟。","頭部輕輕往後放鬆。","停留 20 到 30 秒，保持均勻呼吸。","由胸口帶動，慢慢回到直立姿勢。"],"3506":["站在門框中間，雙手牢牢抓住門框兩側。","雙腳靠近門框，手臂伸直讓身體往後傾。","身體保持一直線。","將胸口拉向門框，同時夾緊肩胛骨。","有控制地放回。","請使用穩固的門框並確保雙手不滑脫。"],"3507":["跪姿，將腳踝固定在穩固物體下方。","從膝蓋到頭部保持一直線。","用大腿後側出力抵抗，將軀幹慢慢往前放低。","接近地面時用雙手撐住自己。","雙手輕推輔助，同時用大腿後側出力拉回起始位置。","保持髖部延伸不折曲。"],"3508":["坐在地板上，彈力帶固定在前方並套在一隻腳上。","伸直該腿，讓彈力帶保持微緊。","抵抗彈力帶阻力，將腳跟往臀肌方向勾起。","短暫收緊大腿後側。","有控制地放回。","做完所有次數後換腳。"],"3509":["坐在地板上，雙手撐在身後輔助。","身體微後傾，雙腿伸直並抬離地面。","將雙膝往胸口方向收。","將雙腿往外伸直，不要碰地。","背部保持延伸，收緊核心。","穩定呼吸。"],"3510":["仰臥，雙手與雙腿伸直。","將肩膀與雙腿微微抬離地板。","雙膝往內收，同時雙手往小腿方向延伸。","收緊腹肌。","往外延伸打開，但不要放回地面休息。","下背保持貼緊地面。"],"3511":["四足跪姿，將彈力帶一端壓在單手下，另一端套在對側腳上。","收緊核心，背部保持平直。","抵抗彈力帶阻力，將該手往前伸、對側腿往後踢直。","短暫停留，接著有控制地收回。","做完所有次數後換邊。"],"3512":["仰臥，雙膝彎曲抬至髖部上方，雙手在胸前握住彈力帶。","將下背貼緊地板。","單手往頭頂方向拉開彈力帶。","收回手臂並換手交替。","肋骨下收並收緊核心。","動作放慢。"],"3513":["站直，雙手在背後握住彈力帶。","手臂保持伸直，雙手握距放寬。","輕輕將雙手往遠離背部的方向抬起。","胸口打開，肋骨保持下收。","停留 20 到 30 秒。","慢慢放開。"],"3514":["仰臥在光滑地板上，單腳腳跟放在毛巾上。","另一隻腳往上伸直抬起。","抬起髖部進入橋式。","將腳跟往外滑出，直到腿接近伸直。","將腳跟往臀肌方向拉回。","做完所有次數後換腳。"],"3515":["側臥，雙腿併攏，單臂往頭頂方向伸直。","同時抬起雙腿與上半身。","上方的手往雙腳方向延伸。","有控制地放下，中間不完全放鬆休息。","保持動作流暢。","做完設定次數後換邊。"],"3516":["站直，雙腳與髖同寬。","雙手在背後十指交扣。","將雙臂在身後往上抬，打開胸口。","覺得舒適的話可以微微往後仰。","停留 20 到 30 秒。","慢慢放開。"],"3517":["站直，雙腳與髖同寬。","雙手扶在下背。","收緊臀肌，將髖部往前推。","抬起胸口，身體輕輕往後仰。","停留 20 到 30 秒。","慢慢回到直立姿勢。"],"3518":["坐在椅子上，彈力帶固定在後方並套在單側腳踝上。","開始時膝蓋彎曲呈 90 度。","將腿往前伸直。","在頂點收緊股四頭肌。","有控制地放下。","做完所有次數後換腳。"],"3522":["仰臥，單腳平踩地面，另一隻腳抬起。","雙手握住壺鈴把手兩側，舉在胸口上方。","抬起髖部進入橋式。","將壺鈴畫弧線往頭頂後方放低。","維持橋式的同時將壺鈴拉回胸前上方。","放下髖部，接著換腳。"],"3523":["坐在重訓椅邊緣，雙腳踩地。","雙手扶在臀部旁的椅緣支撐。","夾緊臀肌與腿後腱，將臀部抬離長凳，直到膝、髖、肩成一直線（反向橋式）。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"3524":["將彈力帶固定在胸口高度，側對固定點站立，雙手把彈力帶抱在胸前。","往下深蹲，軀幹保持挺直。","站起並將彈力帶往正前方推直。","抵抗彈力帶把身體拉轉過去的力量。","將雙手收回胸前。","做完所有次數後換邊。"],"3525":["面對地雷管槓鈴末端採跪姿。","單手將槓鈴末端握在肩膀高度。","收緊核心，軀幹保持直立。","將槓鈴末端往前上方推，直到手臂伸直。","有控制地放下。","做完所有次數後換手。"],"3526":["採四足跪姿。","單手放在頭後方。","將手肘往對側手臂方向轉。","接著展開胸口，將手肘往天花板方向轉。","視線跟著手肘移動。","做完設定次數後換邊。"],"3527":["從下犬式開始，髖部抬高。","將胸口往大腿方向壓。","單手往後伸去碰對側的腳。","手回到原位並換邊。","保持髖部抬高。","配合穩定呼吸，慢慢移動。"],"3528":["從下犬式開始。","雙膝交替彎曲，像踩踏板一樣輕輕活動。","將髖部左右移動。","讓脊椎順勢微微扭轉。","雙手保持推穩地面。","緩慢呼吸。"],"3529":["雙手將地雷管槓鈴末端抱在胸前。","雙腿發力，從深蹲姿勢站起。","站起的同時將單側膝蓋高高抬起。","放下腳並再次深蹲。","槓鈴保持貼近胸口。","每次交替換腳。"],"3530":["將彈力帶安裝在深蹲架與槓鈴上。","將槓鈴扛在上背。","站立，雙腳與肩同寬。","保持挺胸往下深蹲。","透過腳跟發力往上推起。","全程收緊核心。"],"3531":["前後分腿站立，雙手握拳舉起。","單手往前出拳，同時微微轉動軀幹。","收拳的同時換另一手出拳。","保持核心收緊。","維持穩定節奏持續 30 到 60 秒。","短暫休息後重複。"],"3532":["雙腳與肩同寬站立，膝蓋微彎保持彈性。","將重心在兩腳之間來回轉移。","以前腳掌著地。","雙手舉高保持防禦姿勢。","保持輕快節奏持續 30 到 60 秒。","短暫休息後重複。"],"3533":["雙腳分開與肩同寬站立。","屈膝屈髖向後下蹲，如同坐入椅子。","全程維持挺胸背打直。","下蹲至大腿平行地面。","腳跟蹬地推回站姿。","重複所需次數。"],"3534":["雙腳與髖同寬站立，手扶支撐物維持平衡。","墊起腳尖，以前腳掌支撐。","做小幅度的上下脈衝。","膝蓋保持伸直。","結束時將腳跟完全放下。","保持動作受控。"],"3535":["站立，雙腳與肩同寬。","往下深蹲直到大腿與地面平行。","上下小幅脈衝幾公分。","保持挺胸，膝蓋朝腳趾方向對齊。","重心放在腳跟上。","完全站直以結束動作。"],"3536":["將長槓架在兩張平穩的椅子上，並在腳邊放第三張椅子。","躺在長槓下方，雙手正握長槓。","將雙腳腳跟放在第三張椅子上。","將胸口拉向長槓。","慢慢放下直到手臂伸直。","身體保持一直線。"],"3537":["將長槓架在兩張平穩的椅子上，並在腳邊放第三張椅子。","躺在長槓下方，雙手反握長槓。","將雙腳腳跟放在第三張椅子上。","手肘靠近身體，將胸口拉向長槓。","慢慢放下直到手臂伸直。","身體保持挺直。"],"3538":["將長槓架在兩張平穩的椅子上。","躺在下方並以反握抓住長槓。","雙腿伸直，腳跟踩在地板上。","將胸口拉向長槓。","慢慢放下。","身體保持一直線。"],"3539":["側臥屈膝，雙臂往前伸。","抬起上方的手臂，往另一側打開。","視線跟著手移動。","停留 20 到 30 秒。","回到起始位置。","換邊進行。"],"3540":["四足跪姿。","單手放在頭後方。","將手肘朝天花板方向旋轉打開。","停留 20 到 30 秒。","回到起始位置。","換邊重複。"],"3541":["重訓椅調整至 45 度上斜，雙手各握一啞鈴，掌心朝內，胸貼椅背趴好。","手臂微屈自然下垂。","將雙臂向兩側斜上方舉起成「Y」字形，直到平行地面。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"3542":["重訓椅調整至 45 度斜角，胸貼椅背趴好，手持啞鈴。","手臂垂直垂向地板。","手肘微屈，將雙臂向兩側平舉成「T」字形，直到與地面平行。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"3543":["雙腳分開與肩同寬站立。","屈膝屈髖下沉成深蹲。","雙腿爆發力向上起跳。","在空中快速將雙腳併攏。","前腳掌輕巧著地隨即分開沉入深蹲。","重複所需次數。"],"3544":["側躺，雙腿伸展疊放。","前臂撐地，手肘正對肩下方，手肘呈 90 度。","啟動核心將髖部抬離地面成側棒式，身體成一直線。","維持此姿勢至指定時間。","降回髖部，換邊重複。"],"3545":["坐在上斜重訓椅上，手持啞鈴置於大腿。","躺上椅背，用大腿將啞鈴頂至肩高，掌心朝前。","胸大肌與三角肌發力，單手向上推舉過頭頂，手臂完全伸直。","降回肩部起始高度，換另一手推舉。","雙手交替進行推舉至指定次數。"],"3546":["坐在重訓椅上，背打直雙腳踩實。","雙手各握一啞鈴置於肩高，掌心朝內。","單手將啞鈴推過頭頂，另一手維持在肩部高度。","降回推舉的手臂，同時將另一手推過頭頂。","交替進行推舉至所需次數。"],"3547":["坐在重訓椅上，背部打直雙腳踩實。","雙手各握一啞鈴垂於體側，掌心朝前。","手肘貼側將啞鈴向上彎舉至肩部。","前臂垂直後旋轉手腕使掌心朝前。","順勢向上推舉啞鈴至手臂完全伸展。","沿反向軌跡放回肩部並降回身側。","重複所需次數。"],"3548":["站直，雙腳分開與肩同寬，單手持啞鈴。","將啞鈴推舉高過頭頂，手臂完全打直鎖定。","收緊核心維持軀幹垂直，單臂高舉啞鈴向前行走（過頭農夫走/侍者行走 Waiter\'s Walk）。","持續行走至指定距離或時間。","換手重複操作。"],"3550":["將橫桿架在兩張穩固的椅子上。","坐在橫桿下方的地板上並握住橫桿。","雙腿屈膝，提供輕微輔助。","將胸口朝橫桿方向拉起。","穩定控制速度下放。","雙腿出力越少越好。"],"3551":["雙膝微彎，採運動預備站姿。","以快速小碎步向單側移動。","手觸地或直接轉換方向。","快速往反方向移動回去。","保持挺胸。","維持速度持續 30 到 60 秒。"],"3552":["雙腳分開與肩同寬站立，雙臂放身側。","前腳掌快速在原地交替碎步踏步（快速碎步 Fast Feet）。","步伐輕盈快速，重心微放低。","持續進行至指定時間。"],"3553":["從伏地挺身的起始位置開始。","將胸口放低至貼近地板。","推起身體同時轉體，單手朝天花板延伸。","將手放回地板。","再次下放身體，進行下一次動作。","左右換邊交替。"],"3554":["雙手各拿一個裝滿水的瓶子，掌心相對。","手肘貼近身體兩側。","將水瓶朝肩膀方向彎舉。","在頂點收緊肌肉。","穩定控制速度下放。","避免身體晃動。"],"3555":["面向牆壁站立，雙臂伸直身體前傾靠牆。","用力將身體推離牆面。","雙手向後收的同時夾緊肩胛骨。","穩定控制速度回到牆面。","保持核心收緊。","每次動作之間重新站好。"],"3556":["身體站直，雙腳與髖部同寬。","原地跑動，將膝蓋向上抬到腰部高度。","雙臂跟隨節奏擺動。","以前腳掌輕柔著地。","保持挺胸。","持續 30 到 60 秒。"],"3557":["跪在墊子上，雙手撐地比肩更寬。","頭到膝蓋保持一直線。","將胸口朝地板方向放低。","推起身體直到雙臂伸直。","保持核心收緊。","不要讓髖部往下掉。"],"3558":["仰臥，雙手握住毛巾，雙臂伸直。","將毛巾拉緊，雙手朝肩膀方向彎舉。","上臂保持固定，手肘貼近身體兩側。","在頂點用力收縮，再慢慢放回起始位置。","依設定的次數重複。"],"3559":["俯臥，雙臂向頭頂延伸並拉緊毛巾。","將胸口與雙臂稍微抬離地面。","將毛巾往下拉向上胸位置，同時夾緊肩胛骨。","穩定控制，再次將雙臂向前伸直。","保持頸部中立並重複動作。"],"3560":["站直，雙手各持一啞鈴垂於體側。","手肘貼緊軀幹，背部挺直。","吐氣將右手啞鈴向肩膀彎舉。","舉至二頭肌完全收縮，吸氣放回。","換左手重複彎舉並放回。","接著吐氣將右手啞鈴推過頭頂，完全伸展手臂。","吸氣慢慢放回肩部。","換左手重複推舉並放回。","循環交替進行彎舉與推舉至指定次數。"],"3561":["平躺，雙膝彎曲，雙腳踩實地面。","收緊臀肌抬高臀部成橋式，膝髖肩成一直線。","維持臀部抬高，單腳離地將膝蓋拉向胸前（橋式行進 Bridge March）。","放回踩地，換另一隻腳抬膝。","在橋式姿勢下雙腿交替行進抬膝。","重複所需次數。"],"3562":["上背部靠在平凳邊緣，雙腳踩實地面，與臀同寬。","槓鈴置於髖部上方，雙手抓牢固定。","啟動臀肌與核心，踩穩腳跟將骨盆推起至大腿與軀幹成一直線（槓鈴臀推 Hip Thrust）。","頂端停頓片刻，強力擠壓臀大肌。","慢慢放低臀部回起始高度。","重複所需次數。"],"3563":["單手把接在高滑輪機上。","面對滑輪機站立，雙腳與肩同寬。","正握抓住把手，手臂伸展。","背部維持挺直，核心收緊。","單手將把手向下拉至側邊胸前，手肘貼緊身側。","底部停頓片刻，擠壓背闊肌。","慢慢送回把手。","重複所需次數後換手。"],"3564":["坐在地板上，單膝彎曲，另一腿自然擺放。","雙手放在身後地板上，手指朝後。","保持挺胸，慢慢將髖部往前移。","感受肩膀前側的伸展。","保持平穩呼吸，停留 20 到 30 秒。","慢慢放鬆，有需要再換邊重複。"],"3565":["仰臥，雙膝彎曲，雙腳平放靠近髖部。","雙手放在頭部兩側，掌心朝下，手指朝向肩膀。","雙手雙腳用力推地，將髖部與胸口抬起。","在舒適範圍內盡量伸直雙臂，並放鬆頸部。","停留 15 到 30 秒，再慢慢放下身體。"],"3566":["坐姿將泡棉滾筒放在上背處，接著往後躺上去。","雙臂在胸前交叉，抬起髖部。","在肩胛骨與中背之間慢慢滾動。","遇到痠痛點時停留幾個呼吸。","避開下背，持續滾動約 1 分鐘。"],"3567":["仰臥，雙膝彎曲，雙腳平貼地面。","將一側腳踝跨在對側膝蓋上。","雙手抱住下方大腿，拉向胸口。","頭與肩膀放鬆平貼在地板上。","保持平穩呼吸，停留 20 到 30 秒。","慢慢放鬆，有需要再換邊重複。"],"3568":["坐在地板上，將小球放在單側臀部下方。","將該側腳踝跨到對側膝蓋上，讓球能按得更深。","移動重心找到痠痛點並停留。","緩慢呼吸 20 到 30 秒，再輕輕滾動。","換邊重複。"],"3569":["將小球夾在胸口與牆面之間，位置在鎖骨正下方。","身體往牆面靠，直到感覺胸肌受到按壓。","慢慢畫小圈或上下滾動。","在痠痛點停留幾個呼吸。","約 30 到 60 秒後換邊。"],"3570":["背對牆壁站立，將小球放在單側肩膀上方。","身體靠向牆面，讓球壓進肌肉裡。","透過彎曲膝蓋來慢慢移動身體。","在痠痛點停留並保持呼吸。","換另一側肩膀。"],"3571":["雙腳與肩同寬站立，壺鈴放在正前方地板上。","屈髖向後推，雙手握住壺鈴把手。","將壺鈴往雙腿間向後擺，接著髖部往前推，將壺鈴擺盪過頭。","再次屈髖，讓壺鈴順勢落回雙腿之間。","保持背部平直，以流暢節奏重複動作。"],"3572":["將壺鈴架在肩膀高度的架姿位置。","身體站直，收緊臀肌與腹肌。","將壺鈴筆直往上推過頭，直到手臂完全伸直。","穩定控制，將壺鈴放回肩膀位置。","完成次數後換手。"],"3573":["將壺鈴架在胸前架姿位置，往下蹲至全深蹲。","保持挺胸，腳跟平貼地面。","維持深蹲姿勢，將壺鈴往上推過頭。","穩定控制，將壺鈴放回肩膀位置。","整組推完後站起，再重複下一組。"],"3574":["將壺鈴抱在胸前或拿在身體側邊。","單腳往前跨出一大步。","身體下蹲，直到雙膝都彎曲約 90 度。","前腳踩地推回站姿。","雙腳交替完成整組動作。"],"3575":["將壺鈴抱在胸前或拿在身體側邊。","單腳往後跨步，將後膝朝地板放低。","前腳小腿保持垂直，軀幹挺直。","前腳腳跟踩地推回站姿。","雙腳交替完成整組動作。"],"3576":["站在兩個壺鈴中間，保持背部平直將壺鈴提起。","身體站直，肩膀往後收，雙臂自然伸直。","以短而穩定的步伐向前走。","收緊核心，避免身體歪斜。","走完設定距離後，小心將重量放下。"],"3577":["站姿開始，單手自然垂握一個壺鈴。","單腳向後跨成弓步，同時將壺鈴上搏到肩膀位置。","從弓步站起的同時，將壺鈴推過頭頂。","將壺鈴放回肩膀，再放回身體側邊。","雙腳交替進行，完成一組後換手。"],"3578":["雙腳與肩同寬站立，單手握住壺鈴。","將壺鈴從背後傳給另一隻手。","順著腰部繞到身體前方。","保持髖部朝前不歪斜，核心收緊。","往同一方向重複數次，再換方向。"],"3579":["把壺鈴抱在胸前並往下深蹲。","順勢往後坐並滾躺到背部，壺鈴貼近胸口。","利用動能往前滾回雙腳踩地。","從深蹲姿勢站起。","雙手握緊壺鈴，流暢地重複動作。"],"3580":["將兩個壺鈴放得與肩同寬，雙手握住把手。","身體打直呈棒式姿勢。","手肘約呈 45 度，將胸口下放到低於雙手的位置。","推起身體直到雙臂伸直。","全程保持身體呈一直線。"],"3581":["身體站直，單腳往前跨成弓步。","往下蹲直到雙膝都彎曲約 90 度。","推起身體，同時將後腿往後或往側邊抬起。","核心收緊，短暫停留。","放下腿重複動作，完成後換邊。"],"3582":["雙腳分開與肩同寬站立。","右腳向前跨步成弓箭步。","右腳發力推地跳向空中，在空中快速換腳。","輕巧落地成左腳在前的弓箭步（剪刀跳/交換跳弓箭步 Jumping Lunges）。","持續在空中跳躍換腿進行弓箭步至指定次數。"],"3583":["仰臥，雙膝彎曲，雙腳平放地面。","將一側膝蓋抬向胸口。","另一隻腳踩地用力，將髖部抬起。","保持髖部水平，避免過度拱腰。","慢慢放下，完成一組後換邊。"],"3584":["側躺，以前臂撐起身體。","抬起髖部，讓身體呈一直線。","抬起上方的腿與手臂。","穩定控制，將手與腳朝彼此方向擺動靠近。","保持髖部抬高不掉下來，完成後換邊。"],"3585":["單腳站立，膝蓋微彎。","上半身從髖部往前傾，另一腿同步向後延伸。","收緊臀肌帶動身體回到直立。","順勢將懸空腿的膝蓋往胸口方向抬高。","完成次數後換腳。"],"3586":["仰臥，雙腿伸直，雙手墊在髖部下方。","將頭、肩膀與雙腿稍微抬離地面。","雙腿一上一下像剪刀般交叉擺動。","以穩定的節奏左右交替。","保持下背貼緊地面。"],"3587":["戴上腳踝負重，採四足跪姿或俯臥。","收緊核心，保持髖部水平。","將負重腿抬起，過程避免甩動。","在最高點停留並收緊臀部。","慢慢放下，完成後換腳。"],"3588":["雙腳與髖部同寬站立，膝蓋放軟微彎。","雙臂在胸前交叉擺動，再往兩側大幅打開。","保持軀幹直立並放鬆。","逐漸加快擺動速度。","持續 30 到 60 秒。"],"3589":["身體站直，雙臂彎曲放在身體兩側。","抬起膝蓋，在原地輕快跑動。","以前腳掌輕柔著地。","每一步都配合擺臂。","維持節奏持續 30 到 60 秒以上。"],"3590":["仰臥，雙腿伸直，雙臂放在身體兩側。","將下背壓向地板。","將單腿抬起至約 90 度。","慢慢放下，接著抬起另一腿。","雙腿交替進行，過程不要拱腰。"],"3591":["將彈力帶固定在胸口高度，雙手握住握把。","側對固定點站立，雙臂伸直。","將軀幹往遠離固定點的方向旋轉。","穩定控制回到原位。","完成次數後換邊。"],"3593":["將槓鈴架在上背，雙腳與肩同寬站立。","收緊核心並保持挺胸。","髖部往後往下坐，直到大腿約與地面平行。","保持膝蓋朝腳尖方向對齊。","雙腳用力踩地站直。"],"3606":["坐在健身球上，雙腳往前走直到背部貼在球上獲得支撐。","雙手輕放在頭後方。","向上捲腹的同時將一腿伸直。","慢慢躺回並彎曲膝蓋。","雙腳交替完成整組動作。"],"3616":["坐在腿推機上，背部平貼靠墊，雙腳在踏板上靠攏。","解開安全扣把。","下放踏板直到膝蓋彎曲約 90 度。","雙腳用力將腿推直，但膝蓋不要鎖死。","保持髖部貼在坐墊上。"],"3617":["坐在腿推機上，背部平貼靠墊，雙腳在踏板上踩寬，腳尖微朝外。","解開安全扣把。","下放踏板，保持膝蓋對齊腳尖方向。","往上推回，膝蓋不要鎖死。","保持髖部貼在坐墊上。"],"3621":["仰臥，雙膝彎曲，雙臂往上伸直。","將肩膀抬離地面。","轉動軀幹，雙手往單側延伸。","回到中間，再往另一側轉體。","保持下背貼在地板上。"],"3622":["平躺，雙臂向頭頂延伸。","同時抬起雙腿與軀幹。","雙手朝腳尖方向延伸。","穩定控制下放，但雙手雙腳不碰地。","雙腿盡量保持伸直。"],"3623":["雙臂伸直在雙槓上撐起身體，肩膀下壓不聳肩。","雙腿併攏自然下垂。","將雙腿往前抬起，直到約與地面平行或更高。","慢慢放下，避免身體晃動。","保持軀幹穩定不動。"],"3630":["身體站直，雙腳與髖部同寬。","保持脊椎延伸，從髖部往前彎。","讓雙臂自然垂向地板。","膝蓋放軟不鎖死。","保持平穩呼吸，停留 20 到 30 秒。","慢慢起身放鬆，有需要再重複。"],"3631":["坐在地板上，雙腿往兩側盡量打開。","保持背部挺直，腳尖朝上。","從髖部帶動身體往前傾。","雙手放在身體前方的地板上。","停留 20 到 30 秒，再慢慢回到起始位置。"],"3632":["坐姿雙腿打開，背部挺直。","將軀幹向右旋轉。","雙手朝右腳方向延伸。","保持兩側髖部貼穩地面。","保持平穩呼吸，停留 20 到 30 秒。","慢慢放鬆，有需要再換邊重複。"],"3633":["坐姿雙腿打開，背部挺直。","將軀幹向左旋轉。","雙手朝左腳方向延伸。","保持兩側髖部貼穩地面。","保持平穩呼吸，停留 20 到 30 秒。","慢慢放鬆，有需要再換邊重複。"],"3634":["坐姿雙腿大幅打開，背部挺直。","雙臂高舉過頭。","從髖部慢慢往前傾。","保持雙臂延伸並打開胸口。","停留 20 到 30 秒，再坐直身體。"],"3635":["雙腳與肩同寬站立，雙手各持一啞鈴垂於體側。","右腳向前跨一大步，背部挺直核心收緊。","屈膝下沉至右大腿平行地面。","踩穩右腳跟推回站姿。","換左腿向前跨步重複。","雙腿交替進行至所需次數。"],"3636":["面對牆壁站立，雙腳與臀同寬。","雙手扶牆支撐。","啟動核心將右膝快速抬向胸前，左腳踩地。","雙腳快速切換，左膝抬高同時右腳落地（扶牆高抬膝）。","保持快節奏的原地高抬膝跑。","全程上半身維持穩定。","持續進行至指定時間或次數。"],"3637":["從棒式姿勢開始，雙手握住健腹輪手柄，身體呈一直線。","啟動核心，手臂向前推動滾輪向前滾出。","滾動至身體完全伸展且手臂越過頭頂。","核心與雙臂發力將滾輪拉回身下。","重複所需次數。"],"3638":["高棒式姿勢開始，雙手與肩同寬，身體成一直線。","手肘微收彎曲降下身體進行伏地挺身。","推回高棒式。","隨即快速將單膝拉向胸口，換另一腳拉向胸口進行登山者動作。","快速交替雙膝跑步數次。","重複伏地挺身接登山者的組合至指定次數。"],"3639":["平躺，雙膝彎曲，雙腳踩平。","雙臂向兩側水平展開貼地。","雙膝併攏，慢慢將雙腿向一側倒向地面（仰臥雨刷式）。","停頓片刻，核心發力將雙膝帶回中央。","換向另一側倒地重複。","雙側交替進行至所需次數。"],"3640":["平躺，雙膝彎曲，雙腳踩實。","雙手輕扶後腦勺，手肘朝外。","腹肌發力抬起肩胛骨，右手伸向左膝。","放回，換左手伸向右膝。","交替進行至所需次數。"],"3641":["高跪姿開始，雙膝與臀同寬，背部挺直。","雙手各握一啞鈴垂於身前。","收緊核心，雙臂伸直將啞鈴向上平舉推過頭頂。","慢慢放回起始位置。","重複所需次數。"],"3642":["雙腳與肩同寬站立。","右腳向前跨出一大步，背部挺直。","彎曲雙膝下沉至右大腿平行地面。","踩穩右腳跟推回站姿。","換左腿前跨重複。","雙腿交替進行至所需次數。"],"3643":["雙腳分開明顯寬於肩寬，腳尖朝外。","雙手在胸前握住槓片或壺鈴。","重心移向右側，彎曲右膝下沉成側深蹲（側深蹲/哥薩克深蹲 Cossack Squat），左腿維持打直。","下沉至舒適深度，挺胸維持平衡。","踩穩右腳跟推回中央。","換向左側下沉重複。"],"3644":["雙腳與肩同寬站立，雙手各握一啞鈴。","右腳向前跨步成弓箭步。","跨步同時手臂伸直向前上方擺動啞鈴。","右腳蹬地推回站姿，啞鈴順勢向下放回。","換左腳跨步重複。","雙腿交替進行至所需次數。"],"3645":["平躺，雙膝彎曲，雙腳踩地。","單腿向前伸直懸空。","單腳發力將骨盆推離地面成單腿臀橋。","頂端停留片刻，慢慢降回。","重複所需次數後換腿。"],"3650":["面向穩固的跳箱站立，雙腳與肩同寬。","雙臂向後擺，同時髖部微蹲蓄力。","往上跳起，輕柔落在跳箱頂部。","完全站直身體。","小心走下跳箱，重新站好。"],"3651":["雙手在身體兩側持啞鈴，身體站直。","往前跨出一步後，以單腿支撐屈髖前傾。","保持背部平直，後腿順勢抬起。","站直身體，接著跨出下一步做下一下動作。","雙腳交替持續往前推進。"],"3652":["站在六角槓中央，一腳稍微往後踩呈分腿站姿。","保持背部平直，從髖部往後推並前傾。","順著雙腿將六角槓往下放。","將髖部往前推，回到站姿。","完成次數後，前後換腳。"],"3653":["將彈力帶固定在身後，套在腰部。","身體前傾進入衝刺預備姿勢。","快速抬膝並大幅擺動雙臂。","保持腳步輕快。","以短時間衝刺的方式重複進行。"],"3654":["將槓鈴架在蹲舉架上，高度設定為躺下時雙手能握到的位置。","躺在槓鈴下方，以正握握住槓鈴。","將胸口朝槓鈴方向拉起。","夾緊肩胛骨。","慢慢下放直到雙臂完全伸直。"],"3655":["雙腳與臀部同寬站立。","右膝高抬向胸口，左腿單腳站立平衡。","右腳順勢向前跨出一大步成弓箭步，雙膝呈 90 度。","右腳蹬地順勢將左膝抬向胸口。","左腳向前跨步成弓箭步。","持續向前行進弓箭步抬膝邁步。","重複所需次數。"],"3656":["在跑步機或空地上進行訓練。","站直，雙腳與臀部同寬。","原地輕鬆慢跑，微抬膝蓋擺動手臂。","數秒後開始小步向前跑，維持快頻率碎步。","持續進行至指定時間或距離。"],"3657":["在地板或長凳上放一塊靠墊。","仰臥，讓頭部獲得支撐。","保持脊椎中立。","雙臂放鬆放在身體兩側。","維持姿勢並自然呼吸。"],"3658":["坐在椅墊上，背部貼著靠墊。","雙腳平貼地面。","將背部輕輕貼穩靠墊。","保持肩膀放鬆。","維持姿勢並自然呼吸。"],"3659":["雙腳與髖部同寬站立。","膝蓋放軟不鎖死。","肋骨對齊在髖部正上方，肩膀自然往後收。","雙臂自然下垂。","維持姿勢並平穩呼吸。"],"3660":["俯臥在墊子上。","雙腿伸直，額頭輕靠地面。","雙臂放在身體兩側。","保持髖部放鬆。","維持姿勢並自然呼吸。"],"3661":["身體坐直，雙腳平放地面。","保持背部挺直。","雙手放在大腿上。","放鬆肩膀。","維持姿勢並自然呼吸。"],"3662":["高棒式姿勢開始，雙手略寬於肩，雙腳併攏。","將臀部向後上方推起成下犬式（倒 V 字形）。","彎曲手肘，將胸口緊貼地面向前滑行鑽過。","手臂推直挺起胸部過渡到上犬式/眼鏡蛇式。","手肘微屈胸部貼地，反向將臀部推回倒 V 字形。","順勢回到高棒式。","重複所需次數（印度伏地挺身）。"],"3663":["坐在地上，雙腿向前伸展，雙手撐在身後地板，手指朝前。","手掌用力推地將臀部推離地面成反向棒式（Reverse Plank）。","收緊核心，單腿向上踢直指向天花板。","維持數秒，慢慢放下。","換另一條腿向上踢伸。","雙腿交替進行至所需次數。"],"3664":["側躺，雙腿伸直疊放。","前臂撐地，手肘正對肩下成側棒式預備。","上手持啞鈴垂於身前。","收緊核心將髖部抬離地面成側棒式。","維持側棒式穩定，將啞鈴垂直舉向天花板，夾緊肩胛骨。","慢慢放回啞鈴。","重複所需次數後換邊。"],"3665":["高棒式開始，雙手在肩膀正下方，身體成一直線。","核心收緊、臀肌夾緊維持身軀穩定。","依序將手臂降下以前臂撐地轉為肘棒式。","維持肘棒式姿勢數秒。","依序手掌推地撐起回到高棒式（棒式上下上下 Plank Up-Downs）。","重複所需次數。"],"3666":["調整跑步機坡度至目標強度。","站在跑步機上，雙腳與肩同寬。","以舒適穩定的步伐開始步行，維持正確體態。","全程收緊核心肌群，背部維持平直。","在坡度跑步機上持續健走至指定時間。","結束前逐步調低坡度與速度進行緩和收操。"],"3667":["側躺在地面上，雙腿打直疊放。","下側手枕在頭下支撐。","啟動大腿內收肌群，將下側腿或上側腿向上抬起，骨盆不晃動。","頂端停留片刻，慢慢降回。","重複所需次數後換邊。"],"3668":["仰臥在地板上，雙手持啞鈴舉在胸口上方。","將啞鈴下放，直到上臂碰到地板。","短暫停頓。","將啞鈴推回直到雙臂伸直。","保持手腕平直。"],"3669":["雙腳分開與肩同寬站立，膝蓋微彎。","雙臂向前水平伸出，與肩同高。","軀幹向右旋轉，右臂向前伸、左手肘向後拉，如同拉弓射箭動作。","維持拉弓姿勢片刻，回正。","換向左旋轉，左臂前伸、右手向後拉重複。","交替進行至所需次數。"],"3670":["躺在下斜長凳上，雙腳扣緊固定架。","雙手抱頭或交叉胸前。","腹肌發力收緊，將上半身捲離椅面，直到軀幹垂直於地面（下斜仰臥起坐）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"3671":["雙腳分開與肩同寬站立。","微屈膝蓋，背部打直。","向右側跳躍，右腳著地，左腿順勢向右後方擺動。","隨即向左側跳躍，左腳著地，右腿向左後方擺動（滑雪跳 Skier Hops）。","左右交替輕盈彈跳，模擬滑雪擺動。","重複所需次數。"],"3672":["雙腳分開與肩同寬站立。","右腳向前跨步成弓箭步。","右腳蹬地退回起始站姿。","換左腳向前跨步成弓箭步。","步伐流暢交替向前邁出再退回。","持續進行至指定時間或次數。"],"3673":["雙腳與髖部同寬站立。","膝蓋放軟微彎，保持兩側髖部水平。","肩膀對齊在髖部正上方。","視線看向前方。","對照標準站姿檢查自己的體態。"],"3674":["雙腳與髖部同寬站立。","讓耳朵、肩膀與髖部呈一直線對齊。","下背維持自然的生理弧度。","雙臂自然放鬆。","對照標準站姿檢查自己的體態。"],"3675":["雙手握住跳繩握把，身體站直。","將跳繩甩過頭頂。","雙腳左右跳動越過跳繩。","以前腳掌輕柔著地。","維持穩定的跳躍節奏。"],"3679":["平躺，雙膝彎曲，雙腳踩實地面。","雙臂交叉抱於胸前。","腹肌發力將上半身捲離地面靠近膝蓋。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"3697":["繩索把手接在低滑輪上，面對滑輪機跪姿。","對握抓緊繩索，雙臂向前伸直。","背打直核心收緊，後收肩胛骨將繩索拉向身體。","動作末端將肩胛骨向內夾緊停留片刻。","慢慢放回繩索。","重複所需次數。"],"3698":["站姿開始，雙腳與臀同寬。","向前彎腰屈髖，雙手在身前撐地。","雙手向前爬行至高棒式，身體成一直線。","雙腿打直，雙腳一步步跟進走向雙手，臀部推向天花板。","雙手再次向前爬行，重複進行（寸蟲爬）。"],"3699":["高棒式姿勢開始，雙手在肩膀正下方，身體呈一直線。","收緊核心，右手離地輕拍左肩。","右手放回，換左手離地輕拍右肩（高棒式拍肩）。","維持骨盆穩定不晃動，交替拍肩。","重複所需次數。"],"3758":["調整座椅高度，坐穩推胸機，雙腳踩實。","正握抓把手，雙手置於胸部高度。","向前推展把手，手臂伸展（手肘不鎖死）。","停頓片刻，慢慢控制放回胸前。","重複所需次數。"],"3759":["調整座椅高度，使髖部略高於膝蓋。","坐穩羅馬椅挺身機，背靠墊子，雙腳踩實踏板。","抓緊把手維持穩定。","背部維持挺直，從髖部向前俯身前傾至上半身平行地面。","停頓片刻，臀肌與腿後肌群發力挺回原位。","重複所需次數。"],"3760":["坐在機械捲腹機上，雙腳扣緊腳架。","手握把手維持支撐。","收緊腹肌，向前捲動胸口靠近膝蓋。","最高點停頓片刻，用力擠壓腹肌。","緩慢放回起始位置。","重複所需次數。"],"3769":["雙腳分開與肩同寬站立。","右腳向斜後方跨出一步，交叉在左腿後方（屈膝禮弓箭步 Curtsy Lunge）。","雙膝彎曲下沉身體如行屈膝禮。","軀幹維持直立，重心在前腳。","前腳蹬地推回站姿。","換左腳向斜後方跨步重複。"],"3785":["雙手撐在跳箱或高平台邊緣，間距略寬於肩寬。","雙腿向後伸展成高棒式，身體呈一直線。","手肘微收彎曲，將胸部降向箱體（上斜伏地挺身）。","底部停頓片刻，手臂推直回到原位。","重複所需次數。"],"3888":["雙腳與肩同寬站立，單手正握持啞鈴。","膝微屈，屈髖前傾，背部打直挺胸。","啞鈴垂在身前膝蓋高度。","爆發性展髖、展膝與展踝，將啞鈴沿身體直線向上拉起。","當啞鈴到達胸肩高度時，快速轉腕鑽入啞鈴下方並向上將其推直過頭頂（啞鈴單手抓舉 Dumbbell Snatch）。","膝蓋微屈接住啞鈴並站直。","有控制地將啞鈴放回身前。","重複所需次數後換手。"],"5201":["站直，雙手各握一啞鈴，掌心朝前。","上手臂貼緊身體兩側，手肘微收。","慢慢將啞鈴向上彎舉向肩膀，手腕打直。","頂峰停頓片刻，慢慢降回。","重複所需次數。"],"10003":["坐在地上雙腿伸直，將彈力帶套在一隻腳的腳背上。","握住彈力帶兩端或固定好，維持輕微張力。","將腳趾往小腿前側勾。","稍微停頓，再慢慢回放。","做完所有次數後換腳。"],"10014":["仰臥，雙膝彎曲，在膝蓋之間夾一顆球。","雙臂放在身體兩側，下背保持放鬆。","用大腿內側用力夾球。","維持一下，再慢慢放鬆。","全程保持髖部水平。"],"10031":["伸出一隻手，掌心張開。","拇指往側邊伸展並保持伸直。","將其餘四指慢慢往掌心捲曲。","再次張開手指。","重複 10 到 15 次，然後換手。","動作保持流暢，以不痛為原則。"],"10032":["手放在桌面上，掌心朝上。","手指保持放鬆伸直。","慢慢將拇指往遠離掌心的方向移開。","在活動末端停頓一下。","慢慢回到起始位置。","做 10 到 15 次，然後換手。"],"10038":["坐下，將前臂靠在大腿或長凳上，手部懸空。","握住輕啞鈴，掌心朝下。","旋轉前臂，讓掌心轉為朝上。","在頂點停頓一下。","慢慢轉回起始位置。","完成所有次數後換手。手肘保持不動。"],"10040":["站直，雙手各握一個啞鈴垂在身體兩側。","手肘微彎，將一隻手臂往身體前側斜上方舉向對側肩膀。","在頂點停頓一下。","有控制地放下。","換另一隻手重複，左右交替。","軀幹保持穩定，避免晃動。"],"10041":["側躺，手肘在肩膀正下方，上方的手握住啞鈴。","抬起髖部，讓頭到腳呈一直線。","將啞鈴貼在身側，或舉向天花板。","維持 15 到 30 秒。","有控制地放下，然後換邊。","髖部保持抬高，不要翻轉身體。"],"10042":["仰臥在地板上，雙手各握一個啞鈴，在胸口上方互相貼緊。","將兩個啞鈴用力對夾。","往下放，直到上臂碰到地板。","維持對夾並往上推回。","手腕保持打直，手肘內收。","每次下放都要放慢。"],"10043":["坐在地板上，雙腿往前伸直，背部挺直。","單手將啞鈴握在肩膀高度。","將啞鈴推過頭頂，直到手臂伸直。","有控制地放回肩膀高度。","完成次數後換手。","收緊腹肌，不要往後仰。"],"10044":["站姿，單手握住啞鈴垂在大腿前側，髖部微屈。","髖部往前推並聳肩。","將啞鈴貼近身體往上拉。","順勢往上推過頭頂，手臂伸直定住啞鈴。","站直，再將啞鈴放回懸垂位置。","換手進行，重量要夠輕以維持速度。"],"10045":["俯臥，雙臂放在身體兩側，雙腿併攏。","將胸口與雙臂稍微抬離地面。","雙臂往外畫弧線舉過頭頂，同時打開雙腿。","沿著相同弧線收回起始位置。","以流暢的節奏重複。","頸部保持延伸，視線看向地板。"],"10046":["仰臥，雙臂放在身體兩側，雙腿併攏。","將下背貼向地面。","雙臂畫弧線舉過頭頂，同時打開雙腿。","沿著相同弧線收回併攏。","以穩定節奏重複。","腹肌保持收緊，下背貼平。"],"10047":["雙手握住槓鈴放在大腿前，一腳往前跨一步站立。","將大部分重心放在前腳。","從髖部屈髖，讓槓鈴沿著前腿往下滑。","下放到感覺大腿後側被拉伸。","髖部往前推，回到站直姿勢。","完成所有次數後換腳。"],"10048":["面向跳箱或長凳站立，雙手握住滑輪握把。","將一隻腳完整踩上跳箱。","透過該側腳跟往下踩，帶動身體登階。","在跳箱上站直。","有控制地退回地面。","完成所有次數後換腳。"],"10049":["坐在地板上，雙腿往前伸直，將槓鈴放在上胸高度。","採寬握距，收緊腹肌。","將槓鈴推過頭頂，直到雙臂伸直。","有控制地將槓鈴放回上胸。","背部保持挺直，避免拱腰。","一開始先用輕重量。"],"10050":["俯臥，雙臂往前伸直。","將雙臂、胸口與雙腿抬離地面，短暫停留。","放下四肢，將雙手放到肩膀下方。","往上推起做一下伏地挺身。","將胸口放回地面。","重複動作，全程保持身體呈一直線。"],"10051":["雙腳併攏站立，雙手插腰或放在身前。","一腳往後退並下蹲成弓步，雙腳維持在窄線上。","後膝往地面方向下放。","前膝對齊腳踝上方，挺胸。","前腳跟往下踩，推回站姿。","換腳重複。"],"10052":["雙腳寬站，將地雷管尾端握在胸前。","重心移向一側，該側膝蓋深蹲下去。","另一腿保持伸直，腳尖朝上。","彎曲腿往下踩，推回中心位置。","重心移往另一側。","保持挺胸，發力側的腳跟貼穩地面。"],"10053":["坐在穩固的跳箱或長凳上，雙腳平放地面。","身體微向前傾，雙臂準備好。","擺動雙臂，爆發力往上跳起。","雙腳同時輕柔落地，膝蓋微彎緩衝。","坐回箱上並重新準備。","每次之間短暫停頓後重複。"],"10054":["將槓鈴放在上背。","一腳往前跨成前後分腿站姿。","垂直往下蹲，直到後膝接近地面。","保持挺胸，軀幹直立。","前腳跟往下踩，推起身體。","完成所有次數後換腳。"],"10055":["雙腳靠攏站立，雙手各握一個啞鈴垂在身側。","一腳往後退並下蹲成弓步，雙腳維持在窄線上。","後膝往地面方向下放。","前膝對齊腳踝上方，挺胸。","前腳跟往下踩，推回站姿。","換腳重複。"],"10056":["架好地雷管並綁上彈力帶，將槓鈴尾端握在肩膀高度。","雙腳前後站立，收緊核心。","將槓鈴往斜上方推，直到手臂伸直。","有控制地將槓鈴放回肩膀。","完成所有次數後換手。","肋骨下壓，避免身體往後仰。"],"10057":["坐姿雙手撐在身後，膝蓋彎曲並抬起髖部呈桌面橋姿勢。","夾緊臀肌，讓髖部保持抬高。","雙腳往外跳開。","雙腳跳回併攏。","以穩定節奏持續動作。","保持髖部抬高，不要往下掉。"],"10058":["雙膝跪地，上半身挺直。","一腳往前跨出，呈半跪姿。","停頓一下，保持軀幹挺直。","退回雙膝跪姿。","換另一隻腳重複。","動作放慢，需要時可用雙臂維持平衡。"],"10065":["坐在器械上，將軀幹固定在靠墊上。","握住握把。","髖部保持不動，將軀幹轉向一側。","在末端停頓一下。","回到中心，再轉向另一側。","動作放慢，避免靠慣性甩動。"],"10092":["將槓鈴放在上背，雙腳與肩同寬站立。","深吸一口氣，收緊腹肌。","往下深蹲，直到大腿約與地面平行。","軀幹保持繃緊並挺胸。","雙腳往下踩，推回站姿。","在頂點吐氣，每次下蹲前重新收緊核心。"],"10093":["採半跪姿，雙手握住啞鈴放在後腳髖部外側附近。","收緊腹肌，軀幹保持直立。","將啞鈴往身體斜上方舉起，越過胸前。","結束時啞鈴停在對側肩膀上方。","沿著相同路徑放回。","完成次數後換邊。"],"10094":["站姿，單手握住啞鈴垂在大腿前，髖部微屈。","髖部往前推並聳肩。","將啞鈴往上拉並橫越身體前方。","在對側肩膀位置接住啞鈴。","將啞鈴放回懸垂位置。","完成次數後換手。"],"10095":["將滑輪設定在胸口高度，採前後分腿站姿。","單手握住握把，收緊核心。","手肘微彎，將手臂往身體前側橫掃過去。","在動作末端夾緊胸肌。","慢慢回到起始位置。","完成次數後換手。"],"10096":["單手將啞鈴握在肩膀高度，身體站直。","一腿往後跨成弓步。","前腳往下踩，推回站姿。","站起的同時，將啞鈴推過頭頂。","將啞鈴放回肩膀並重複。","每組換手或換腳進行。"],"10097":["雙手將槓片抱在胸前。","雙腳與肩同寬站立。","往下深蹲，直到大腿與地面平行。","保持挺胸，手肘內收。","腳跟往下踩，推回站姿。","全程讓槓片貼近身體。"],"10106":["正握槓鈴停在大腿中段，髖部微屈。","髖部用力往前推並順勢聳肩。","手肘抬高，將槓鈴拉到胸口高度。","穩定槓鈴後，放回大腿位置。","重新調整好站姿。","全程讓槓鈴貼近身體。"],"10107":["正握槓鈴，停在膝蓋正上方。","從髖部屈髖，背部保持平直。","雙腿爆發往上蹬並順勢聳肩。","手肘抬高，將槓鈴拉到胸口高度。","放回懸垂位置。","重設姿勢並重複。讓槓鈴貼近身體。"],"10108":["站立，雙手將藥球舉過頭頂。","雙手稍微往後帶，收緊腹肌。","用力將球往前拋出。","雙臂順勢延伸完成拋投。","撿起球並重新準備。","背部保持自然中立。"],"10109":["站立，雙手將藥球拿在大腿前側。","往下蹲，將球擺盪到雙腿之間。","往上蹬地並伸展髖部。","將球往上並越過頭頂往後拋出。","取回藥球並重新準備。","雙臂保持延伸，並確認身後空間淨空。"],"10110":["雙手正握粗槓鈴。","站立，手肘貼在身體兩側。","將槓鈴往肩膀方向彎舉。","在頂點用力收縮。","慢慢放下。","手腕保持打直。"],"10112":["坐在滑輪機前踩穩雙腳，單手握住握把。","坐直，讓手臂往前延伸，感覺背闊肌微微拉伸。","以手肘帶動，將手肘往下、往後拉向髖部。","收縮背闊肌停頓一下，再慢慢放回握把。","軀幹保持不動，肩膀下壓。完成所有次數後換手。"],"10113":["將器械靠墊調整在雙膝外側。","往下蹲成半蹲姿勢，保持挺胸。","雙膝往外用力推頂靠墊。","穩定維持姿勢直到目標時間結束。","放鬆並慢慢站起。"],"10114":["站直，雙手握住槓片停在大腿高度。","將槓片往外、往上畫大弧線舉到約頭頂高度。","短暫停頓，肋骨下壓並收緊核心。","有控制地沿相同路徑將槓片放回。","使用輕槓片，並避免往後仰。"],"10115":["躺在下斜長凳上，雙手約與肩同寬握住槓鈴。","起槓後雙臂伸直，將槓鈴停在下胸上方。","手肘貼近身體，將槓鈴下放到下胸。","將槓鈴往上推回，直到雙臂伸直。","手腕保持在手肘正上方，並請旁人護槓。"],"10116":["將上斜長凳放在史密斯機槓鈴下方，躺下讓眼睛對齊槓鈴下方。","以略窄於肩的握距握槓並解鎖起槓。","手肘貼近身體兩側，將槓鈴下放到上胸。","將槓鈴往上推，直到雙臂伸直。","雙腳踩穩地面，肩胛骨往後收緊。"],"10117":["單膝跪地，將啞鈴放在前腳旁的地上並握住。","順暢地一氣呵成將啞鈴拉到肩膀，同時轉動手腕。","將啞鈴推過頭頂，直到手臂伸直。","將啞鈴放回肩膀，再有控制地放回地面。","軀幹保持直立。完成次數後換邊。"],"10118":["雙腳與肩同寬站立，雙手將藥球舉過頭頂。","膝蓋開始微彎時，將球往一側畫圈繞一圈。","用力將球砸向身前的地面。","趁球彈起時接住或從地上撿起，重新舉回頭頂。","每組交替畫圈方向，並保持核心收緊。"],"10119":["側向站在跳箱旁，雙手將滑輪握把握在胸前。","靠近跳箱的那隻腳踩上去，用腳跟往下踩。","往上登階直到腿部伸直，在箱上站直。","有控制地慢慢放回地面。","同一側做完所有次數，再轉身換邊。"],"10120":["面向跳箱站立，將滑輪握把握在胸前或身側。","將一隻腳完整踩在跳箱上。","該側腳跟往下踩，在跳箱上站直。","將後腳慢慢放回地面。","膝蓋對齊腳尖方向。完成次數後換腳。"],"10126":["站在牆邊，手背與牆面之間夾一條毛巾。","手肘貼在身側並彎曲呈 90 度。","手背往外用力壓向毛巾。","維持出力 10 到 20 秒。","放鬆，然後換邊。"],"10138":["站直，雙腳與髖同寬，手肘貼在身體兩側。","手肘彎曲約 90 度，掌心朝上。","握緊拳頭，用力收緊二頭肌。","維持姿勢 20 到 30 秒，保持平穩呼吸。","肩膀放鬆、手肘固定不動，接著休息並重複。"],"10139":["坐在地上雙腿伸直，將健身球放在雙腳腳跟下方。","身體微後傾，雙手撐在身後。","腳跟往下壓球並往內滾動，直到膝蓋彎曲。","穩定維持這個姿勢。","慢慢將雙腿再次伸直。"],"10160":["站在穩固的跳箱上，腳尖靠近邊緣。","一腳跨出跳箱落下，不要往上跳。","雙腳同時著地，膝蓋微彎保持柔軟。","順勢下蹲約四分之一深蹲來吸收衝擊，並穩定停住。","走回跳箱上並重複。膝蓋保持對齊腳尖。"],"10168":["在身後放一個跳箱，雙腳略寬於肩站立。","髖部往後推並彎曲膝蓋，往跳箱方向下蹲。","臀部輕觸跳箱，不要直接重重坐下。","腳跟往下踩，推回站姿。","保持挺胸，膝蓋對齊腳尖方向。"],"10182":["站在平放於地面的啞鈴旁。","下蹲並將雙手撐地，雙腳往後跳做一下伏地挺身。","雙腳往前跳回髖部下方。","往上並側向跳過啞鈴，輕柔落地。","轉身或直接往反方向重複，保持穩定節奏。"],"10183":["雙腳與肩同寬站立，雙手握住一個啞鈴停在大腿高度。","將啞鈴往身前舉到胸口高度。","髖部朝前，從肋骨帶動軀幹轉向一側。","轉回中心，有控制地放下啞鈴。","每一下交替轉向不同側，並使用輕重量。"],"10184":["將彈力帶固定在胸口高度，側向固定點採前後分腿站姿。","雙手將握把握在胸前。","將彈力帶往正前方推出，不要讓軀幹被拉轉。","維持 1 秒，再將雙手收回到胸前。","每組或每一下交換前後腳，並保持髖部擺正。"],"10185":["四足跪姿開始，雙手各握一個啞鈴，雙膝微抬離地。","收緊核心，背部保持平直。","將一邊啞鈴拉向肋骨，髖部不要翻轉。","有控制地將啞鈴放回地面。","換另一隻手划船，以穩定節奏持續交替。"],"10186":["仰臥，雙膝彎曲，雙手在胸口上方握住一個啞鈴。","腳跟往下踩，抬起髖部呈橋式。","將啞鈴畫弧線往頭頂後方下放做拉舉。","將啞鈴拉回胸口上方，再垂直往上推。","有控制地放下髖部並重複，全程肋骨下壓。"],"10187":["雙腳與髖同寬站立，膝蓋微彎。","擺動雙臂帶動，垂直往上跳起。","輕柔落地後，立刻往側邊跳一步。","雙腳同時落地、膝蓋微彎緩衝，重新站穩。","每次交替側跳方向，維持穩定節奏。"],"10188":["站直，雙腳比髖部寬，雙臂往兩側平伸。","往前屈髖並轉體，用一隻手去碰對側的腳。","回到站姿，雙臂往兩側張開。","換另一隻手去碰對側的腳。","背部保持平直，以輕快節奏進行。"],"10189":["站立，雙手將槓片拿在大腿前側。","從髖部屈髖，將槓片往小腿方向下放，接著站起。","一腳往後退成後弓步，同時將槓片推過頭頂。","收回後腳，將槓片放回大腿前側。","背部保持平直並重複，雙腳交替做弓步。"],"10190":["面向地雷管尾端站立，單手將槓鈴握在肩膀高度。","膝蓋微彎，往下淺蹲幾吋。","雙腿用力往上蹬，順勢將槓鈴往斜上方推直到手臂伸直。","有控制地將槓鈴尾端放回肩膀。","肋骨下壓並收緊核心。完成次數後換手。"],"10191":["雙手將啞鈴抱在胸前，想像腳下周圍有個時鐘。","往 12 點鐘方向跨一步，保持挺胸往下深蹲。","站起並退回中心點。","往下一個鐘點方向跨出並再次深蹲。","有控制地繞完一圈時鐘，下一組換方向進行。"],"10192":["雙腳略寬於肩站立，雙手握住壺鈴。","從髖部屈髖，將壺鈴往雙腿之間向後擺盪。","髖部快速往前推，將壺鈴往斜側方擺盪到胸口高度。","背部保持平直，讓壺鈴順勢往下擺回。","同一側完成所有次數後換邊。"],"10193":["站在負重雪橇後方，往下趴做一下胸口貼地的波比跳。","爆發力往上跳起站立。","雙臂伸直握住雪橇握把，身體前傾。","以短促有力的步伐往前推雪橇一段設定距離。","回到起點並重複，推雪橇時背部保持平直。"],"10194":["坐姿，雙腳腳底相對，雙膝往兩側打開。","雙手握住腳掌或腳踝。","沿著脊椎慢慢往後滾動。","往前滾動回到坐姿。","流暢地重複 8 到 10 次。"],"10195":["單膝跪地，雙手將地雷管槓鈴尾端握在髖部附近。","收緊核心，上半身保持挺直。","將槓鈴往身體斜上方舉起，朝向對側肩膀。","慢慢將槓鈴放回起始位置。","髖部保持擺正。完成次數後換邊。"],"10196":["站立，雙手各握一個輕啞鈴垂在身體兩側。","先做一組側平舉，接著直接進入前平舉。","不放下啞鈴，直接接著做一組過頭推舉。","有控制地放下啞鈴並休息。","全程使用輕重量，並保持軀幹穩定不動。"],"10197":["側向站在牆面或反彈面旁，雙手將藥球抱在胸口高度。","將球稍微往遠離目標的一側帶動蓄力。","轉體並用雙手將球用力砸向牆面。","接住反彈球，重設站姿後再做一次。","運用髖部發力並收緊核心。完成次數後換邊。"],"10198":["坐在腿推機上，雙腳踩穩踏板並解開安全扣。","用雙腿將踏板往上推起，膝蓋輕微打直但不鎖死。","將重量移到單腿，花 3 到 4 秒慢慢往下放。","再用雙腿將踏板推回上方。","每一下交替負責下放的腿，全程絕對不要讓下背拱起。"],"10199":["雙手各拿一個啞鈴站立，膝蓋微彎。","將髖部往後推，讓啞鈴順著雙腿往下放。","保持背部平坦，將一邊的啞鈴往對側腳尖方向延伸。","髖部往前推，回到站直姿勢。","每次交替延伸的方向。"],"10200":["身體跪直，雙手握住啞鈴兩端放在胸前。","讓啞鈴貼近頭部繞一圈。","保持肋骨下壓，髖部穩定不動。","繞完一圈回到胸前。","先往同一方向做幾次，再反方向進行。"],"10294":["身體站直，雙臂自然垂放身側。","將腳尖與前腳掌離地，只用腳跟保持平衡。","以小步伐穩定往前走。","全程保持腳尖往上勾。","走 20 到 30 秒後休息。"],"10326":["從高棒式開始，雙手在肩膀正下方。","雙腳往前跳，落在雙手外側呈寬站距深蹲。","可依喜好稍微站起或往上輕跳，接著雙手撐回地面。","雙腳往後跳回棒式。","保持核心收緊，落地時放輕動作。"],"10327":["坐在地上，膝蓋彎曲，身體微微後傾。","雙手將壺鈴抱在胸前。","轉動軀幹，將壺鈴帶到一側髖部旁。","流暢地轉向另一側。","保持挺胸，想增加難度可將雙腳抬離地面。"],"10328":["在腰帶深蹲機上準備好，將後腳放在身後的長凳上。","身體站直，前腳往前跨出足夠距離。","身體筆直往下蹲，直到前腿大腿與地面平行。","前腳跟發力站起。","保持軀幹直立。做完次數後換腿。"],"10329":["站在長凳旁，單手與單膝撐在凳上，另一手拿重啞鈴。","讓啞鈴自然下垂，感受背闊肌的伸展。","利用受控的身體慣性，將啞鈴拉向髖部。","慢慢放下，直到完全伸展。","保持背部平坦。做完次數後換手。"],"10330":["側躺在長凳上，上方的手拿一個輕啞鈴。","起始時手臂垂在身體前方。","將手臂往外並往後畫弧線舉起，直到與軀幹呈一直線。","稍微停頓一下，再穩定控制放下。","使用輕重量，做完一組後換邊。"],"10331":["踩住彈力帶，手握握把，掌心朝向側面。","往上彎舉握把，同時旋轉手腕。","完成時掌心朝向自己，並用力收縮二頭肌。","慢慢放下並轉回起始位置。","保持手肘貼近身體。做完次數後換手。"],"10345":["俯臥在地面，雙臂往前伸直。","將雙臂、胸口與雙腿抬離地面幾吋。","上下進行小幅度的脈衝動作。","保持頸部自然中立。","做完一組後放下休息。"],"10366":["坐在地上雙腿伸直，將固定在正前方的彈力帶套在腳上。","保持腿部伸直，腳跟貼地。","抵抗彈力帶阻力，將腳尖往小腿方向勾起。","稍微停留一下，再慢慢放開。","單腳做完所有次數後換腳。"],"10367":["坐在長凳或跳箱上，將壺鈴掛在單腳腳背上。","腳跟踩穩地面。","將腳尖往小腿方向勾起，把壺鈴抬高。","停頓一下，再慢慢放下。","使用輕重量。做完次數後換腳。"],"10383":["雙腳與髖同寬，站在沙袋上方。","從髖部屈曲、彎曲膝蓋並抓緊沙袋。","繃緊核心，雙腳發力推地，抱著沙袋站直。","將髖部往後推，把沙袋放回地面。","全程保持背部平坦。"],"10384":["以熊抱方式將沙袋緊抱在胸前。","雙腳與肩同寬站立。","保持挺胸，臀部往後往下坐進深蹲。","腳跟發力站起。","讓沙袋緊貼身體。"],"10385":["站在沙袋上方，雙手牢牢抓緊沙袋。","雙腿與髖部發力，將沙袋拉起。","先拉到大腿上，接著順勢甩上一側肩膀。","穩定控制將沙袋放回地面。","每次交替不同邊肩膀。"],"10386":["將沙袋扛上雙肩並扶穩。","身體站直，繃緊核心。","以穩定受控的步伐往前走。","保持肋骨對齊在髖部正上方。","走完設定的距離或時間後，小心地把沙袋放下。"],"10387":["抱起沙袋並緊貼在胸前。","身體站直，繃緊核心。","以穩定的步伐往前走。","雙臂持續用力抱緊沙袋。","走完設定的距離或時間後，小心地放下沙袋。"],"10388":["將沙袋抱在上胸或肩膀高度。","雙腳與髖同寬站立，繃緊核心。","將沙袋筆直推過頭頂。","手臂完全伸直後，再穩定控制放下沙袋。","保持肋骨下壓，避免身體後仰。"],"10389":["站在沙袋上方，從髖部俯身並用雙手抓住沙袋。","保持背部平坦，膝蓋微彎。","將沙袋拉向肋骨下緣。","用力夾緊肩胛骨。","慢慢放回，直到手臂完全伸直。"],"10410":["將戰錘放在肩膀上，雙手握住固定。","雙腳約與肩同寬站立。","臀部往後往下坐，直到大腿約與地面平行。","保持挺胸，膝蓋朝向腳尖方向。","雙腳發力站回原位。"],"10411":["身體站直，雙腳與肩同寬，在胸前將戰錘直立握好。","繃緊核心並保持肋骨下壓。","將戰錘繞著頭部畫出流暢受控的弧線。","保持手肘貼近，頭部穩定不動。","做完所有次數後，換反方向進行。"],"10427":["雙腳與肩同寬，站在沙袋上方。","屈髖往下，抓住沙袋並保持背部平坦。","髖部往前推，將沙袋順著身體前側往上拉。","身體完全伸展，將沙袋往後拋過肩膀。","保持面向同一方向，重整姿勢後重複動作。"],"10437":["將繩索裝在低位滑輪上，面向機台坐好並踩穩雙腳。","單手握住繩索，手臂伸直。","手肘順著身側往後拉，用力夾緊肩胛骨。","停頓一下，再讓手臂慢慢伸直。","做完所有次數後換邊。"],"10438":["以正握抓住單槓，雙手約與肩同寬。","手臂伸直自然懸垂，身體放鬆。","將重心移向其中一隻手，讓該側自然伸展。","再移向另一側，持續左右交替。","總共維持懸垂 20 到 30 秒。"],"10439":["雙手各抓一條繩索，手臂伸直懸掛。","單臂往上拉，同時手肘彎曲貼近身體。","另一隻手往更高處抓，再次往上拉。","保持核心收緊，雙腿穩定。","爬到安全高度後，穩定控制往下回到地面。"],"10462":["坐在椅子前緣。","一腿往前伸直，腳跟踩地、腳尖朝上。","保持背部平坦，從髖部往前俯身，直到感覺有伸展感。","保持平穩呼吸，維持 20 到 30 秒。","換腿重複動作。"],"10463":["在椅子上坐直，雙腳平放地面。","雙手往後伸，十指交扣或抓住椅背。","將肩胛骨往內夾緊並挺胸。","維持 20 到 30 秒，不要拱起下背。","放鬆後重複動作。"],"10503":["坐在下拉機上並固定好大腿。","以窄握、反握抓住橫桿。","身體稍微後傾，將橫桿拉到上胸處。","保持手肘貼近身體兩側。","慢慢放回，直到手臂完全伸直。"],"10517":["站在椅子旁並扶著椅子保持平衡。","將一腿稍微抬離地面。","用腿部緩慢且受控地畫圈。","先往同一方向做一半次數，再反方向進行。","換腿重複動作。"],"10534":["坐在椅子上，雙腳平放地面。","將一隻腳往椅子下方滑，同時彎曲膝蓋。","在動作末端稍微停頓一下。","將腳慢慢滑回起始位置。","做完次數後換腿。"],"10535":["坐好，一腳平放地面，另一腿跨在上面。","將下方腳的腳趾勾在上方腳底下，製造輕微阻力。","將腳趾與前腳掌往小腿方向抬起。","在頂點停頓一下，再慢慢放下。","做完次數後換腳。"],"10536":["將彈力帶固定在身後，套在單腳腳踝或膝蓋後側。","身體站直，需要時可扶著支撐物保持平衡。","抵抗彈力帶阻力將膝蓋伸直。","在腿部伸直時停頓一下。","慢慢彎曲放回，做完次數後換腿。"],"10537":["在椅子上坐直，雙腳平放。","慢慢將單側膝蓋伸直，把腳抬起來。","在頂點收緊大腿約 1 秒。","穩定控制將腳放回地面。","做完次數後換腿。"],"10538":["在椅子上坐直，雙手扶住椅墊邊緣支撐。","將單側膝蓋伸直，直到腿部呈水平。","收緊大腿並維持 1 秒。","慢慢放回起始位置。","做完次數後換腿。"],"10539":["綁上輕量腳踝負重，在椅子上坐直。","雙手扶住椅墊邊緣支撐。","將膝蓋伸直，直到腿部呈水平。","維持 1 秒並用力收縮大腿。","慢慢放下，做完次數後換腿。"],"10540":["仰躺在地面，膝蓋彎曲，雙腳平放。","將一隻腳滑到另一腳下方以提供輕微阻力。","將下方腳的腳尖往小腿方向抬起。","在頂點停頓一下，再慢慢放下。","做完次數後換腳。"],"10541":["在椅子上坐直，雙腳平放。","抬起一側膝蓋，雙手環抱小腿。","輕輕將膝蓋往胸口拉，讓膝蓋彎曲。","停留一下再放開。","做完次數後換腿。"],"10542":["在椅子上坐直，將毛巾繞在一側小腿上。","雙手抓住毛巾兩端。","輕輕將膝蓋往胸口拉，讓膝蓋彎曲。","停留一下再放開。","做完次數後換腿。"],"10543":["扶住椅背，在軟墊上單膝跪地。","保持軀幹直立。","臀部慢慢往腳跟方向坐，讓膝蓋彎曲。","停留在舒適的活動範圍內即可。","回到起始位置，做完次數後換邊。"],"10547":["站在牆邊單腳站立，扶牆保持平衡。","將重心往後移到腳跟，同時翹起腳尖。","再將重心往前滾動到前腳掌。","保持動作平順受控。","做完次數後換腿。"],"10548":["單腳站立，手輕扶牆面或欄杆。","將腳跟稍微往下放以伸展小腿。","盡量踮高腳尖，用力收縮小腿。","在頂點停頓 1 秒。","慢慢放下，做完次數後換腿。"],"10549":["仰躺在地面，單腳放在長凳或踏板上。","另一腿往正上方伸直。","腳跟發力將髖部往上推。","在頂點收緊臀肌，不要拱起下背。","慢慢放下，做完次數後換腿。"],"10550":["仰躺在地面，雙手掌心在胸前夾住一片槓片。","用力夾緊槓片。","將槓片筆直往上推，直到手臂伸直。","維持夾緊的力道，將槓片慢慢放回胸前。","穩定控制並重複動作。"],"10551":["雙腳站距略寬於肩。","在舒適範圍內盡量往下深蹲。","手肘輕推膝蓋內側，並保持挺胸。","身體輕輕左右搖晃。","停留 20 到 30 秒後站起。"],"10552":["採分腿站姿，在胸口高度抱著一顆藥球。","繃緊核心。","保持髖部穩定，將軀幹轉向一側。","回到中間，再轉向另一側。","完成所有次數後，前後腳互換。"],"10553":["將彈力帶固定在高處，雙手握住握把。","採前後分腿站姿，雙臂高舉過頭。","穩定控制力道，將握把往前下方拉下。","在動作末端繃緊核心。","慢慢放回並重複動作。"],"10554":["從直臂棒式開始，在身體前方放一顆球。","收緊核心與臀肌。","抬起一隻手輕拍一下球。","放回手掌，換另一隻手輕拍。","盡量保持髖部穩定不晃動。"],"10555":["在椅子上坐直，肩膀放鬆。","慢慢將下巴往胸口放低。","輕輕抬起頭，視線微微往上看。","保持動作平順且不產生疼痛。","緩慢重複幾次。"],"10556":["在椅子上坐直，肩膀放鬆。","慢慢轉動頭部，看向一側肩膀。","回到中間。","轉向另一側。","緩慢重複幾次。"],"10557":["在椅子上坐直，肩膀放鬆。","慢慢傾斜頭部，讓耳朵靠近一側肩膀。","回到中間。","往另一側肩膀傾斜。","緩慢重複幾次。"],"10558":["仰躺在地面，膝蓋彎曲，雙手將藥球舉過頭頂。","一氣呵成坐起，同時將球往前帶。","將球用力砸向雙腳前方的地面。","在球彈起時接住或將球撿起。","穩定控制躺回地面並重複動作。"],"10559":["身體站直，雙手握住一個啞鈴放在大腿前側。","將啞鈴從身前筆直往上舉過頭頂。","在頂點穩定控制，並保持核心繃緊。","慢慢將啞鈴放回原位。","使用適中重量，避免拱起背部。"],"10560":["躺在長凳上，請人護槓或設定好安全護槓。","起槓並將槓鈴穩定在胸口上方。","穩定控制將槓鈴往胸口下放。","在胸口正上方瞬間停住，接著往上推起。","保持雙腳踩穩，肩胛骨往後夾緊。"],"10561":["單腳站立，單手拿著壺鈴。","從髖部屈曲，將壺鈴往地面延伸。","在膝蓋下方將壺鈴換到另一隻手。","利用臀肌與大腿後側的力量站回原位。","做完次數後換腿。"],"10562":["單手拿著壺鈴並站直。","將拿壺鈴同側的那條腿往後跨。","往下蹲成弓步。","發力站起，同時將後腿膝蓋往高處抬起。","做完次數後換邊。"],"10563":["將一隻腳平放在距離跳箱或踏板一小段距離處。","保持腳跟貼地。","將膝蓋往前推去碰觸跳箱。","維持 20 到 30 秒，感受小腿的伸展。","換腿重複動作。"],"10564":["坐在椅子上，將一隻腳稍微抬離地面。","將腳底往內翻。","在舒適範圍內盡量將腳底往外翻。","保持小腿穩定不動。","做完次數後換腳。"],"10565":["坐在地上，雙膝皆彎曲呈 90 度，一腿在前、一腿在側邊。","上半身坐直。","保持背部平坦，從髖部往前方小腿上方俯身。","維持 20 到 30 秒。","換邊重複動作。"],"10566":["單膝跪地，另一腳踩在前方。","雙臂交叉抱在胸前。","將上半身轉向前腿方向。","回到中間，全程保持髖部朝向正前方。","做完次數後換邊。"],"10588":["仰躺在長凳上，雙臂伸直將槓鈴拿在大腿上方。","保持手臂伸直，手肘微彎不鎖死。","將槓鈴畫弧線舉起，直到位於胸口正上方。","慢慢將槓鈴放回原位。","使用輕重量並保持背部平貼。"],"10589":["仰躺在地面，以正握拿著一根木棍。","保持雙臂伸直。","在舒適範圍內盡量將木棍舉過頭頂。","慢慢放回大腿上方。","全程保持肋骨下壓。"],"10590":["站立並往前俯身，將雙手放在地面上。","雙手往身體前方走開。","臀部往後坐，將胸口往下壓。","維持 20 到 30 秒。","雙手走回原位並站起。"],"10591":["在椅子上坐直，將彈力帶繞在單腳腳底。","雙手握住彈力帶兩端。","將膝蓋往上拉並彎曲靠近胸口。","停留一下，再慢慢放回。","做完次數後換腿。"],"10592":["單膝跪地，另一腿往前伸直，腳跟貼地。","保持腳尖朝上。","保持背部平坦，從髖部往前俯身。","維持 20 到 30 秒。","換腿重複動作。"],"10593":["雙手撐在長凳上，呈上斜棒式。","繃緊核心，保持身體呈一直線。","雙腳往外跳開。","再將雙腳跳回併攏。","保持髖部穩定，維持固定節奏。"],"10594":["將彈力帶固定在身側與胸同高處，把把手握在胸前。","站穩挺直，收緊核心。","快速且有控制地將把手往前並橫跨身體推出。","慢慢收回到胸前，不要被彈力帶拉著轉動。","全程保持髖部擺正。","完成所有次數後換邊。"],"10595":["仰臥屈膝，雙手拿藥球舉過頭頂。","將球拉過胸前，往上拋給夥伴或砸向牆面。","球落下時手肘微彎緩衝接住。","有控制地讓球沿弧線回到頭頂上方。","下背保持貼平地面。","以穩定節奏重複動作。"],"10597":["將滑輪設定在肩膀高度，側對機器站立。","上臂往側邊抬起，手肘彎曲 90 度。","讓滑輪帶動前臂往後做外旋。","煞住動作後，流暢地將前臂往前往下轉動。","保持上臂固定且水平。","完成次數後換手。"],"10598":["仰臥屈膝，雙手將藥球拿在胸口上方。","雙手靠近，快速將球往上推拋。","球落下時手肘微彎緩衝接住。","將球下放到胸口正上方。","保持背部平貼、肋骨下沉。","以俐落且受控的節奏重複次數。"],"10639":["雙腳固定在器材上，坐在襯墊上支撐髖部。","身體往後躺，直到軀幹與髖部齊平或略低於髖部。","雙臂在胸前交叉。","往上捲起身體，直到胸口靠近大腿。","收緊核心，慢慢往後躺回。","避免用力拉扯脖子。"],"10646":["胸口朝下趴在上斜襯墊上，握住把手。","讓雙臂完全伸直。","手肘往髖部方向帶，將把手往後拉。","將肩胛骨往中間夾緊。","慢慢下放直到手臂伸直。","頭部保持自然中立。"],"10650":["將彈力帶繞過上背，兩端壓在手掌下方。","擺好伏地挺身姿勢，身體呈一直線。","有控制地將胸口下放到地面。","用力往上推，讓雙手短暫離開地面。","手肘微彎輕柔落地。","保持髖部與身體呈一直線。"],"10651":["將彈力帶套在腳踝上，單腳站上波速球。","收緊核心並站直。","對抗彈力帶張力，將騰空腿往側邊抬起。","在頂點短暫停頓。","慢慢放回，身體不要歪斜。","完成次數後換腿。"],"10654":["躺在滑車上，用腳尖踩在腳踏桿上。","保持脊椎中立並彎曲膝蓋。","將滑車推開，直到雙腿伸直。","有控制地滑回。","保持髖部穩定不動。"],"10655":["躺在滑車上，雙腳踩在腳踏桿上。","彎曲膝蓋。","往外推直到雙腿伸直。","慢慢滑回。","保持下背穩定。"],"10656":["躺在滑車上，腳跟放在腳踏桿上。","彎曲膝蓋。","透過腳跟往外推，直到雙腿伸直。","慢慢滑回。","保持髖部水平。"],"10657":["躺在滑車上，雙腿伸直，前腳掌踩在腳踏桿上。","將腳跟往下壓。","踮起腳尖。","慢慢放回。","膝蓋保持伸直但不死鎖。"],"10658":["躺在滑車上，雙手握住繩帶。","抬起頭部與雙腿。","雙臂做小幅度的上下拍動。","吸氣數五拍，吐氣數五拍。","持續拍動 100 下。"],"10660":["將彈力帶繞過單槓，把腳或膝蓋放進彈力帶中。","單手抓槓懸垂，另一手握住自己的手腕或抓住彈力帶。","手肘往下帶，將下巴拉向單槓。","在頂點稍作停頓。","有控制地放回完全懸垂。","每組結束後換手。"],"10661":["將彈力帶掛在吊環或單槓上，把腳踩進彈力帶。","單手握住一個吊環，另一手輕扶另一個吊環或放開。","將胸口拉向吊環。","保持身體繃緊，避免晃動。","慢慢放回完全懸垂。","重複動作，完成後換邊。"],"10662":["雙臂伸直懸垂於吊環下，肩膀出力穩定。","將胸口往上拉向吊環。","到頂點時，將吊環往髖部方向下壓。","雙臂貼近身側並短暫停頓。","回到頂點位置，再慢慢下放。","全程收緊核心。"],"10663":["牢牢握住吊環懸垂。","收起膝蓋，將髖部往頭頂上方抬。","身體往後翻轉，讓雙腿穿過雙臂之間。","雙腳往地面方向放低，直到感覺肩膀伸展。","稍作停頓，再有控制地原路翻回。","動作放慢，若感覺關節夾擠就立刻停下。"],"10664":["從深度前傾支撐開始，雙手撐在肩膀下方。","肩胛骨前引並夾緊臀肌。","身體重心前移，將雙腳抬離地面。","雙手推地並維持俄式挺身姿勢。","有控制地放下。","開始前先充分暖開手腕。"],"10665":["雙手撐地，將手肘向內頂在腰側。","身體重心往雙手上方前傾。","雙腳一前一後抬離地面。","收緊核心，保持身體水平。","肩膀持續往前推撐。","維持支撐後慢慢放下。"],"10667":["將滑輪設定在胸口高度，面對器材跪下。","單手握住把手並收緊核心。","將手肘沿著身側往後拉。","把肩胛骨往脊椎方向夾。","慢慢伸直手臂。","完成次數後換手。"],"10668":["將彈力帶固定在胸口高度，面對固定點跪下。","單手握住彈力帶，保持軀幹挺直。","將手肘往後拉過肋骨。","把肩胛骨往內夾緊。","對抗張力慢慢放回。","整組完成後換手。"],"10669":["調整座椅，讓把手位於上胸高度。","往後坐穩，雙腳平踩，肩胛骨往後夾緊。","將把手往前上方推，直到手臂接近伸直。","短暫停頓。","慢慢放回，直到胸口感覺伸展。","背部保持貼緊靠墊。"],"10670":["坐在器材上，單手握住上胸高度的把手。","收緊核心避免身體扭轉。","將把手往前上方推出。","停頓一下，再慢慢放回。","保持肩膀往後收穩。","完成所有次數後換手。"],"10671":["調整座椅，讓把手對齊中胸高度。","往後坐穩，將肩胛骨往中間夾緊。","將把手往前推，直到手臂接近伸直。","稍作停頓，手肘不要死鎖。","慢慢放回，讓胸口獲得溫和伸展。","雙腳保持平踩地面。"],"10672":["背部貼緊靠墊坐好，單手握住把手。","收緊核心並保持軀幹擺正。","將把手沿著平順軌跡往前推。","停頓一下，再慢慢放回。","保持肩膀下沉。","完成次數後換手。"],"10673":["在胸前握住壺鈴兩側把手。","雙腳站立與肩同寬。","保持挺胸，將髖部往後往下坐。","下蹲到大腿平行地面或更低。","透過腳跟發力站起。","手肘保持貼近身體。"],"10674":["雙手在頸後握住壺鈴，讓壺鈴靠在上背。","雙腳站立與肩同寬。","收緊核心，髖部往後往下坐。","保持挺胸，下蹲到大腿與地面平行。","透過腳跟發力站起。","手肘保持朝下。"],"10675":["在胸前握住地雷管槓袖末端。","雙腳站立與肩同寬。","保持挺胸往下深蹲。","雙腳爆發力往上跳起。","膝蓋微彎輕柔落地。","重新站穩後重複。"],"10676":["背上背包並將背帶拉緊調穩。","站直並將肩膀往後收。","在平地上以穩定步調行走。","步伐自然並保持平穩呼吸。","核心微微收緊。","依體能狀況行走 10-30 分鐘。"],"10677":["背上裝有適度重量的背包，並將背帶束緊。","先在平地上以輕鬆慢跑開始。","保持軀幹挺直、步伐輕盈。","維持能平穩呼吸的配速。","如果姿勢開始走樣就減輕負重。","持續跑 10-20 分鐘。"],"10710":["仰臥並彎曲雙膝。","將槓片抱在胸前。","將肩膀往上捲起。","停頓並收縮腹肌。","慢慢躺回。"],"10729":["站在水深及胸的水中，手扶泳池邊緣。","雙膝交替抬起。","以穩定節奏踩動。","保持核心收緊。","持續數分鐘。"],"10730":["雙手抓牢沙袋，放在大腿前側。","雙腳與髖同寬站立，膝蓋微彎。","將髖部往後推，讓沙袋順著雙腿往下滑。","下放到感覺大腿後側被拉伸。","將髖部往前推，回到站直姿勢。","全程保持背部平直。"],"10731":["抓牢繩子懸垂，將雙腿在身前平舉抬起。","雙腿保持伸直並併攏。","維持 L 字形姿勢，雙手交替往上拉。","持續往上抓並重複拉起。","有控制地往下放回。","如果雙腿掉下來就先停下。"],"10732":["雙腳併攏站在低跳箱旁。","彎曲膝蓋並擺動雙臂。","往側邊跳過跳箱。","雙腳輕柔落地。","立刻往反方向跳回。","保持快速但受控的節奏。"],"10733":["為了安全，將平衡板放在靠近牆壁的平坦地面上。","單腳踩上平衡板並找到重心。","將另一腳抬離地面。","穩定維持 20-30 秒。","保持髖部水平。","換腿重複。"],"10734":["將平衡墊放在平坦地面上。","單腳踩上去並站直。","將另一腳抬離地面。","維持 20-30 秒。","視線注視固定一點。","換腿重複。"],"10735":["雙臂伸直懸垂在單槓上。","收緊核心並保持身體穩定。","將單側膝蓋往胸口抬起。","慢慢放下，再抬起另一側膝蓋。","避免身體晃動。","雙腿交替完成目標次數。"],"10736":["雙腳與髖同寬站立，雙手放在頭後。","膝蓋微微放鬆。","保持背部平直，從髖部往前折。","微微點頭，接著回到站姿。","以流暢的步調移動。","保持頸部放鬆。"],"10738":["面對穩固的跳箱站立。","雙臂往後擺並彎曲膝蓋。","將雙臂往前帶出，同時跳上跳箱。","雙腳輕柔落地。","在箱上站直。","走下跳箱並重新準備。"],"10739":["仰臥並彎曲雙膝。","抬起一隻手臂並彎曲手肘，手伸向頭後。","用另一隻手將該側手肘輕輕往地面方向壓。","維持 20-30 秒。","保持肋骨下沉。","換手重複。"],"10740":["仰臥，雙手握住一根棍棒。","彎曲一隻手臂，將那隻手帶到頭後。","用另一隻手推動棍棒，將彎曲側的手肘往下壓。","維持 20-30 秒。","保持頸部放鬆。","換手重複。"],"10741":["站直，一隻手在背後低處握住彈力帶。","另一隻手臂舉過頭頂並彎曲手肘，握住彈力帶上端。","下方的手輕輕往下拉。","感受上臂後側的伸展。","維持 20-30 秒。","換手重複。"],"10742":["俯臥，雙臂在頭頂前方呈 Y 字形。","將一隻手臂稍微抬離地面。","往外往下滑動到 T 字形位置。","短暫停留。","滑回 Y 字形位置。","每組結束後換手。"],"10743":["在穩固的跳箱前雙膝跪地。","雙臂往後擺，接著將髖部往前推。","從跪姿瞬間彈起成雙腳站姿。","一氣呵成跳上跳箱。","輕柔落地並站直。","走下跳箱並重新準備。"],"10744":["坐直，一腿伸直並將彈力帶繞在該腳腳底。","雙手握住彈力帶兩端。","保持腿部伸直，輕輕將腳尖往身體方向拉。","從髖部往前傾，直到感覺被拉伸。","維持 20-30 秒。","換腿重複。"],"10745":["在地板上坐直，雙手撐在身後輔助。","膝蓋伸直，將一腿稍微抬起。","用腳從一側到另一側畫出半圓。","保持軀幹穩定。","重複目標次數。","換腿重複。"],"10746":["坐在長凳上，將彈力帶固定在一側腳踝。","將彈力帶另一端固定在身後。","對抗彈力帶將膝蓋伸直。","在頂點收縮大腿前側。","慢慢放下。","換腿重複。"],"10747":["雙腳併攏站直。","原地慢跑。","雙腳快速往外與往內開合移動。","用前腳掌保持輕快彈性。","持續設定的時間。"],"10748":["單腳站立。","另一腳腳尖往前點地。","接著往側邊點地，再往後點地。","保持身體平衡。","換腿重複。"],"10749":["身體站直。","往前踏出一步，同時將對側腿往上踢。","雙腿交替進行。","自然擺動雙臂。","持續設定的時間。"],"10750":["雙膝跪地，保持軀幹挺直。","一腳往前踩成弓箭步。","前腳發力將身體推起站立。","後腳往前收攏併齊。","倒回動作步驟，退回跪姿。","交替帶頭的前腳。"],"10751":["身體站直。","膝蓋保持接近伸直。","利用腳踝發力跳起。","輕柔落地。","快速重複。"],"10752":["雙腳與髖同寬站直。","收下巴，脊椎一節一節往下捲。","讓雙臂自然往地面垂下。","下探到自己覺得舒適的幅度即可。","慢慢一節一節捲回站姿。","全程保持控制，若負重請用輕重量。"],"10753":["坐直在長凳或椅子上，將固定在低處的彈力帶套在腳上。","雙手扶住椅面邊緣並收緊核心。","對抗彈力帶，將單側膝蓋往胸口抬起。","在頂點短暫停頓。","有控制地慢慢放下腳。","完成所有次數後換腿。"],"10754":["單腳站立，膝蓋微彎，雙臂放鬆。","前腳掌發力，主要用腳踝往上跳起。","騰空時膝蓋保持接近伸直。","用同一隻腳的前腳掌輕柔落地。","落地後立刻彈起接下一次跳躍。","完成次數後換腿。"],"10755":["站在踏箱旁，單手輕扶箱面幫助平衡。","將一腳抬離地面。","主要用腳踝與小腿發力往上跳。","用前腳掌輕柔落地。","保持小幅度且快速的連續跳躍。","整組完成後換腿。"],"10756":["雙腳併攏站直，膝蓋微微放鬆。","前腳掌推地，往前跳一小段距離。","膝蓋保持接近伸直。","用前腳掌輕柔落地。","往後跳回，或轉身重複。","整組保持輕盈快速的節奏。"],"10757":["雙腳併攏站直，膝蓋微微放鬆。","腳尖彈起，往一側跳過去。","用前腳掌輕柔落地。","立刻往另一側跳回去。","保持挺胸與髖部水平。","持續左右交替完成整組。"],"10758":["將藥球抱在胸前。","往側邊單腳跳出。","膝蓋彎曲輕柔落地。","短暫停頓後，推地跳向另一側。","保持挺胸。","左右交替完成目標次數。"],"10759":["站直，雙臂自然放鬆。","將單側膝蓋往胸口抬高。","往前踏出並踩回地面。","換另一側重複。","保持軀幹挺直。","每腿走 10-20 步。"],"10760":["將彈力帶套在前腳掌或腳踝處。","踮起腳尖站到前腳掌上。","以受控的小步伐往前走。","全程保持高踮腳尖。","保持髖部水平。","往前走 20-30 步。"],"10761":["將彈力帶套在雙腳腳踝。","膝蓋微彎，踮起腳尖。","以小步伐往側邊移動。","讓彈力帶維持張力。","不要讓腳跟掉下來。","先往一邊走，再往回走。"],"10762":["站直並踮起腳尖。","膝蓋微微彎曲。","以受控的小步伐往側邊走。","全程保持高踮腳尖。","保持髖部水平。","先往一邊走，再走回來。"],"10763":["坐在器材上，將滾墊調在腳踝上方。","握住把手，背部貼緊椅背。","單腿往下並往後彎起。","在底部收縮大腿後側。","慢慢放回。","完成次數後換腿。"],"10764":["仰躺在雪橇機上，單腳踩在踏板上。","握住把手並收緊核心。","彎曲膝蓋，讓雪橇往身體方向下放。","在下背離開靠墊前停住。","透過腳跟發力將腿推直。","完成所有次數後換腿。"],"10780":["仰臥並彎曲雙膝。","放鬆雙肩。","收下巴，將頭稍微抬離地面。","停留一秒。","慢慢放回。","動作幅度保持小而平順。"],"10781":["俯臥，讓額頭懸在長凳邊緣或稍微離地。","保持雙肩放鬆。","微收下巴，將頭抬高幾公分。","短暫停頓。","慢慢放下。","以小幅度且受控的方式完成次數。"],"10817":["坐姿，將前臂靠在大腿或長凳上。","掌心朝上握住輕啞鈴。","轉動前臂讓掌心朝下。","稍作停頓，再轉回原位。","有控制地慢慢移動。","換手重複。"],"10818":["單腳站立，膝蓋保持微彎。","往前跳並輕柔落地。","跳回起始位置，接著往側邊跳出再跳回。","往第四個方向跳出並跳回。","每次落地都確實站穩。","換腿重複。"],"10819":["前後分腿站立，前腳平踩，後腳腳尖輕點地面。","將大部分重心放在前腿。","前腳踮起站到前腳掌上。","在頂點稍作停頓。","慢慢放下腳跟。","完成次數後換邊。"],"10820":["將彈力帶套在腳踝或膝蓋處。","單腳站立平衡，支撐膝微彎。","另一腿屈膝並往側邊抬起。","保持軀幹挺直。","慢慢放回。","完成次數後換腿。"],"10847":["躺在核心床上，雙腳套進繩帶或踩在腳踏桿上。","彎曲膝蓋並往外打開，腳跟併攏呈蛙腿姿勢。","將雙腿推直。","雙腿往外分開畫圈，再收回併攏。","做幾次後換反方向畫圈。","背部穩穩貼在墊上。"],"10848":["躺在核心床上，前腳掌踩在腳踏桿上。","將雙腿伸直。","一邊壓低單腳腳跟，一邊彎曲另一側膝蓋。","流暢地交替雙腳。","保持骨盆穩定不動。","維持平穩呼吸。"],"10849":["仰臥，雙腳踩在腳踏桿上且雙膝彎曲。","雙臂壓穩床墊。","將脊椎一節一節往上捲，抬起髖部。","在頂點停留。","慢慢一節一節往下放回。","保持肋骨放鬆不外翻。"],"10850":["一腳踩在滑車上，另一腳踩在固定平台上站立。","收緊核心。","將滑車往外推開，加寬站距。","稍作停頓。","用大腿內側發力，有控制地將滑車拉回。","保持髖部擺正。"],"10851":["雙腳分別踩在滑床與固定平台上。","站直並收緊核心。","彎曲膝蓋往下深蹲。","抬起胸口，膝蓋對齊腳趾方向。","往上推回站姿。","順暢地配合滑床移動。"],"10852":["一腳踩在滑床上，另一腳踩在固定平台上。","站直並收緊核心。","滑床往後推開，同時往下蹲成分腿蹲。","稍微停頓。","推回起始位置。","做完一組後換邊。"],"10853":["仰躺，雙腳抵住肩靠。","雙腿往上伸直推起。","將髖部捲離床墊。","將髖部抬到肩膀上方。","一節一節慢慢將脊椎捲回床墊。","避免把壓力放在脖子上。"],"10854":["仰躺，雙手握住拉繩並往上舉。","彎曲膝蓋，收緊核心。","雙臂向兩側放下。","以流暢的弧線往下再往上畫圈。","做幾次後換反方向畫圈。","肋骨保持下收。"],"10855":["面向拉繩呈跪姿，軀幹保持直立。","雙臂伸直握住拉繩。","將拉繩往身體後方拉。","頭部輕輕轉向左右兩側。","慢慢回到起始位置。","保持挺胸，肋骨下收。"],"10856":["在滑床上坐著或跪著，雙手握住拉繩舉過頭頂。","收緊核心。","穩定控制，將拉繩沿著弧線往前並往下壓。","回到頭頂上方的位置。","脊椎保持延伸挺直。","配合呼吸順暢移動。"],"10857":["站立，雙手在大腿前側握住很輕的槓鈴。","收下巴，脊椎一節一節往下捲。","讓槓鈴貼近雙腿自然下垂。","下放到自己能穩定控制的深度即可。","慢慢一節一節捲回站姿。","膝蓋保持微彎不鎖死。"],"10858":["站直，雙手各拿一個輕啞鈴垂在身體兩側。","雙臂向兩側平舉至肩膀高度，手肘彎曲呈 90 度。","將前臂往上旋轉，讓啞鈴朝向天花板。","停頓一下，接著沿原路徑穩定放回。","保持肋骨下收，避免聳肩。"],"10859":["背部與髖部貼牆站立，雙腳往前站一小步。","雙腿保持伸直，腳跟踩穩地面。","將腳趾盡量往小腿方向勾起來。","在最高點稍微停頓。","慢慢放下腳趾並重複動作。"],"10860":["將腳踝束帶扣在低位滑輪上，綁在一隻腳踝。","側對機器站立，手扶機台維持平衡。","將訓練腿往外側偏後方踢出，膝蓋大致保持伸直。","停頓一下，接著慢慢收回，別讓配重片完全放到底。","軀幹保持穩定不動。完成所有次數後換腳。"],"10861":["俯臥在 GHD 上，髖部靠在軟墊邊緣，雙腳之間夾住一顆球。","雙手握住前方握把或軟墊。","抬起雙腿，直到與軀幹呈一直線。","在頂端夾緊臀肌。","慢慢放下雙腿。","不要利用慣性甩動。"],"10862":["面向牆壁站立，單手把球壓在牆上。","一隻腳稍微抬離地面。","髖部往後推做鉸鏈動作，懸空的腿同時往後延伸。","背部保持平坦。","回到站姿。","做完一組後換腳。"],"10863":["在史密斯機槓鈴下方放一張長凳，坐直並讓背部靠穩椅背。","單手以對握方式握住槓鈴並解開安全扣。","將槓鈴往頭頂上方推，直到手臂接近完全伸直。","慢慢將槓鈴下放到約下巴高度。","軀幹保持穩定。完成所有次數後換手。"],"10864":["面向高箱站立。","一隻腳整個腳掌踩上箱面。","透過那隻腳的腳跟發力站上跳箱。","另一隻腳跟著踩上來。","穩定控制步伐往下踩回地面。","換另一隻腳帶頭進行。"],"10865":["雙手拿啞鈴，後腳背靠在長凳上。","前腳膝蓋保持微彎。","從髖部折起讓身體前傾。","順著腿部放下啞鈴。","夾緊臀肌站回原位。","做完一組後換腳。"],"10866":["調整好器械，背部打平從髖部向前傾。","單手握住握把，讓手臂自然往前延伸。","將手肘往後並往下拉向髖部。","拉到底時收緊背闊肌。","慢慢放回原位，完成所有次數後換邊。"],"10867":["俯臥在上斜軟墊上，讓胸口貼穩軟墊。","握住對握握把並伸直雙臂。","將手肘往後拉過軀幹，同時夾緊肩胛骨。","稍微停頓一下。","讓握把慢慢回到原位，直到雙臂伸直。"],"10868":["站在波速球上，雙腳與肩同寬。","雙臂往前平舉。","臀部往後坐並彎曲膝蓋。","保持挺胸。","站回直立姿勢。","膝蓋保持對齊腳趾方向。"],"10869":["單腳站在波速球上。","雙臂伸展以維持平衡。","穩定控制往下深蹲。","膝蓋保持對齊腳趾方向。","往上推回站姿。","做完一組後換腳。"],"10870":["仰躺，將彈力帶套在膝蓋上方，雙腳踩平。","抬起髖部呈臀橋姿勢。","雙腳往外側跨開再往內收回。","保持彈力帶緊繃。","髖部保持抬高。","做完一組後再放下身體。"],"10871":["仰躺，膝蓋彎曲，雙腳踩平。","雙手拿著槓片，將手臂往頭頂方向伸直。","將肩膀與上背捲離地面，雙手拿槓片往上推。","在最高點停頓並收緊腹肌。","慢慢放下，頭部不要直接重重落回地面。"],"10873":["仰躺，膝蓋彎曲，雙腳踩平。","雙手直握一個啞鈴，將手臂往頭頂方向伸直。","將肩膀捲離地面，把啞鈴朝天花板方向推。","停頓並收緊腹肌。","慢慢放下並重複動作。"],"10875":["側身站上 45 度羅馬椅或背部伸展架，將雙腳固定好。","雙手將槓片抱在胸前。","穩定控制，讓軀幹往側邊下放。","側彎往上拉起，直到身體呈一直線。","避免扭轉軀幹。完成次數後換邊。"],"10877":["仰躺，膝蓋彎曲，雙腳踩穩。","雙臂伸直在頭頂上方拿著槓片。","往上捲腹，讓肩胛骨離開地面。","起身時雙臂保持貼近耳朵兩側。","慢慢放回地面並重複動作。"],"10879":["仰躺，膝蓋彎曲，雙腳踩平。","雙手握住啞鈴的一端，手臂往頭頂上方伸直。","往上捲腹，讓啞鈴沿著弧線朝膝蓋方向移動。","在最高點收緊腹肌。","穩定控制下放並重複動作。"],"10882":["呈跪姿伏地挺身姿勢，雙手在肩膀正下方。","膝蓋到頭部維持一直線。","胸口朝地面下放。","爆發往上推，讓雙手推離地面。","手肘微彎輕柔落地。","直接接著做下一次。"],"10890":["雙腳併攏站在彈跳床上。","踮起腳尖。","利用腳踝的力量跳躍。","以前腳掌輕柔落地。","保持快速輕巧的節奏。","持續跳完這一組。"],"10899":["將彈力帶套在雙腿膝蓋正上方，身體側躺。","兩側髖部上下疊齊，膝蓋微彎。","對抗彈力帶的阻力，將上方的膝蓋或整隻腿往上抬起。","在最高點停頓一下。","慢慢放下。完成次數後換邊。"],"10901":["站直，單手在身體側邊拿一個啞鈴。","手臂保持伸直，肩膀放鬆。","將肩膀筆直朝耳朵方向聳起。","在最高點停留一下。","慢慢放下。完成次數後換手。"],"10902":["先來到引體向上的頂端位置，單手握槓，另一手輔助或放開。","放開輔助的手，把體重移到訓練手。","盡可能慢慢下放身體，直到手臂完全伸直。","身體保持繃緊，避免晃動。","踩回頂端位置並重複，完成後換手。"],"10903":["將彈力帶掛在單槓上，把一隻腳或膝蓋放進圈環裡。","單手握住單槓，另一隻手貼在胸前。","手肘往下拉，將下巴拉向單槓。","在頂端停頓一下。","穩定控制下放。完成次數後換手。"],"10904":["仰躺，膝蓋彎曲，腳跟踩地，雙腳離臀部稍微遠一點。","透過雙腳腳跟往下踩。","抬起髖部，直到肩膀到膝蓋呈一直線。","在頂端收緊大腿後側與臀肌。","慢慢放下並重複動作。"],"10905":["仰躺，膝蓋彎曲，雙腳腳跟踩地。","抬起髖部呈橋式。","將一隻腳往前伸直，兩側髖部保持水平。","將腳放回地面，過程中髖部不要往下掉。","雙腿交替進行，或先做完同一邊。"],"10906":["一腳往前跨一大步，另一腳往後踩呈分腿姿勢。","降低髖部，直到前腳膝蓋彎曲約 90 度。","軀幹保持直立，前腳腳跟踩穩地面。","維持 20 到 30 秒，保持平穩呼吸。","站回原位並換腳。"],"10907":["單膝跪地，另一隻腿往前伸直，腳跟點地。","臀部往後坐向後腳腳跟。","前腿保持伸直，背部延伸拉長。","維持 20 到 30 秒。","換腳進行。"],"10908":["在椅子上坐直，將一隻腳稍微抬離地面。","小腿保持不動。","用腳趾慢慢畫圈，在舒適範圍內盡量畫大一點。","一半次數順時針畫圈，接著換逆時針。","換另一隻腳重複動作。"],"10909":["在椅子上坐直，雙腳抬離地面。","膝蓋保持不動。","雙腳朝同一個方向畫圈，在舒適範圍內盡量畫大。","轉幾圈後換反方向。","呼吸保持放鬆。"],"10910":["坐直，將一隻腳稍微抬離地面。","小腿保持不動。","將腳掌順暢地往內翻，再往外翻。","在舒適的活動範圍內進行。","重複做完設定次數後換腳。"],"10911":["坐在椅子上，雙腳平放地面。","所有腳趾往下彎曲，就像要抓住地面一樣。","用力抓緊維持幾秒鐘。","放鬆並將腳趾盡量張開。","順暢地重複動作。"],"10912":["坐在椅子上，將一隻腳平放地面。","腳趾往下彎曲並用力抓緊。","維持 1 到 2 秒。","放鬆並張開腳趾。","完成所有次數後換腳。"],"10913":["仰躺，一隻腳膝蓋彎曲並踩平地面。","另一隻腿伸直，收緊大腿肌肉。","將伸直的腿抬高到與彎曲膝蓋同高。","稍微停頓一下。","慢慢放下。完成次數後換腳。"],"10914":["站立，雙腳與肩同寬。","臀部往後推，膝蓋稍微彎曲下蹲。","保持挺胸，腳跟踩穩。","雙腳往下踩，站回直立姿勢。","以穩定的節奏重複動作。"],"10915":["單腳站立，膝蓋微彎。","從髖部向前傾，另一隻腿同時往後延伸。","背部保持平坦，直到軀幹接近與地面平行。","維持幾秒鐘，兩側髖部保持水平。","回到直立姿勢並換腳。"],"10916":["單腳站立，膝蓋微彎。","身體向前傾，懸空的腿同時往後抬起。","雙手朝站立腳的腳趾方向延伸。","背部保持平坦，髖部擺正不歪斜。","穩定控制站回原位。完成次數後換腳。"],"10917":["坐在椅子上，一腳平踩地面，另一腳跨在它上方。","下方的腳往上勾，對抗上方腳壓住的阻力。","感受小腿前側發力。","維持 1 秒鐘。","放鬆並重複，完成後換腳。"],"10918":["坐著，將一隻腳平放在地面上。","腳趾往下彎曲抓緊並維持住。","腳跟保持貼穩地面。","放開並將腳趾張開。","完成所有次數後換腳。"],"10919":["坐直，將一隻腳稍微抬離地面。","腿部保持不動。","將腳掌往內側擺，再往外側擺。","動作保持順暢且不產生疼痛。","重複動作，完成後換腳。"],"10920":["坐在椅子上，一隻腳放在地面。","腳跟稍微抬起，將腳趾往下壓向地面。","稍微維持一下。","將腳跟放回地面。","完成所有次數後換腳。"],"10921":["坐在椅子上，將彈力帶固定在身後並套在一隻腳踝上。","對抗彈力帶阻力將膝蓋伸直。","維持腿部伸直 10 到 20 秒。","大腿保持收緊，背部挺直。","慢慢放下並換腳。"],"10922":["面向牆壁站立，一隻腳往後退一步。","後腳腳跟踩穩地面，膝蓋稍微彎曲。","身體向前傾，直到感覺小腿下半部有伸展感。","維持 20 到 30 秒。","換腳進行。"],"10925":["站立，雙腳與髖同寬。","往下做四分之一深蹲，雙臂同時往後擺。","往上跳起，並以單腳落地。","膝蓋彎曲緩衝落地衝擊，並站穩維持平衡。","重新站好，交替更換落地的腳。"],"10926":["背部靠牆站立，雙腳稍微往前站。","順著牆面往下滑，直到膝蓋彎曲約四分之一的深度。","背部保持貼平牆面。","維持 15 到 30 秒。","順著牆面滑回站姿。"],"10927":["面向牆壁站立，將毛巾墊在手掌下貼著牆面。","手肘彎曲，手掌高度在胸口附近。","手臂伸直，將毛巾沿著牆面往前推滑。","慢慢滑回原位。","完成所有次數後換手。"],"10928":["面向牆壁站立，將毛巾墊在前臂下方貼著牆面。","手肘彎曲，身體保持直立。","將手臂沿著牆面往上滑動。","滑到頂端時保持不聳肩。","慢慢滑回原位並換手。"],"10929":["側對牆壁站立，前臂下方墊一條毛巾貼牆。","手肘彎曲呈 90 度並貼在身體側邊。","將手沿著牆面往身體內側滑動。","慢慢回到原位。","完成所有次數後換手。"],"10930":["側對牆壁站立，前臂下方墊一條毛巾貼牆。","手肘維持 90 度並貼緊身體側邊。","將手沿著牆面往外側滑動。","慢慢回到原位。","完成所有次數後換手。"],"10931":["站直，雙手在背後拉住一條毛巾。","下方的手保持不動，上方的手往外拉開。","將上方那側的肩膀往外旋轉。","稍微停留一下再放鬆。","完成所有次數後換手。"],"10932":["一手從肩膀上方、另一手從下背握住毛巾兩端。","用下方的手輕輕將毛巾往上拉(或上方的手往上帶)。","保持胸口打開，脖子放鬆。","維持 20 到 30 秒。","換邊進行。"],"10933":["側躺，上方的手肘彎曲呈 90 度並貼著肋骨。","前臂橫放在腹部前方。","手肘固定不動，將前臂往上旋轉。","慢慢放下。","完成所有次數後換邊。"],"10934":["側躺，在上方手肘與身體之間墊一條小毛巾。","手肘彎曲呈 90 度。","將前臂朝天花板方向往上旋轉。","停頓一下，接著慢慢放下。","完成所有次數後換邊。"],"10935":["站直，在背後握住一根長棍。","一手在下方握、另一手在上方握。","用下方的手推動長棍，引導上方的手臂往外並往上抬。","只在舒適的範圍內移動。","慢慢回到原位並換邊。"],"10936":["雙手寬握長棍，放在大腿前側。","雙臂保持伸直，將長棍舉過頭頂。","在舒適範圍內繼續沿著弧線往背後繞過去。","沿著原本的路徑繞回前方。","隨著活動度進步，可以慢慢縮小握距。"],"10937":["面向牆壁站立，將前臂貼在牆面上。","手肘彎曲呈 90 度。","前臂貼著牆面往上與往下旋轉。","肩膀保持放鬆。","做完設定次數後換手。"],"10948":["雙臂伸直懸掛在單槓上。","手肘不彎曲，將肩胛骨往下拉。","讓身體以小弧度前後擺盪。","保持動作穩定受控。","放回完全懸掛姿勢並重複動作。"],"10949":["站立，雙手各拿一個啞鈴，掌心朝前。","雙臂保持接近完全伸直。","穩定控制，將啞鈴沿著弧線往前並往上擺起。","將啞鈴放回原位。","軀幹保持不動，避免用慣性甩動。"],"10950":["將吊環調低，雙手握住吊環呈棒式姿勢。","雙臂保持伸直，將吊環夾近身體兩側。","收緊臀肌與腹肌。","維持 15 到 30 秒。","降回地面休息。"],"10951":["坐在地面上，雙手握住平行地面小雙槓或平貼在身體兩側地面。","雙手往下推，把髖部撐離地面。","雙腿在身前伸直。","將雙腿往更高處抬起，再放回 L 坐姿的高度。","雙臂保持伸直，肩膀下壓。"],"10977":["將軟墊調整至髖部高度，雙手把啞鈴抱在胸前。","背部保持平坦，將軀幹往下放。","往上抬起身體，直到身體呈一直線。","夾緊臀肌。","慢慢放下。","不要過度後仰。"],"10987":["站在穩固的跳箱前，雙手各拿一個啞鈴。","往下做四分之一深蹲，雙臂同時往後擺。","跳上跳箱，膝蓋微彎輕柔落地。","在箱上站直。","小心地走下來並重新準備。"],"10988":["在跳箱前呈雙膝跪姿，雙手在身體兩側拿著啞鈴。","擺動雙臂並爆發往上跳成雙腳站姿。","順勢跳上跳箱，輕柔落地。","在箱上站直。","小心地走下來並回到跪姿。"],"10989":["雙手握住平行小雙槓並蹲下。","手臂保持伸直，身體重心往前移到雙手上方。","雙腳離地，將膝蓋往胸口方向收緊。","維持幾秒鐘，上背稍微拱起。","輕輕將雙腳放回地面。"],"10995":["坐姿，雙手在身後撐地，雙腳踩平，接著抬起髖部。","保持胸口打開，髖部抬高。","手腳交替往前走。","接著以同樣方式往後走。","核心保持收緊。"],"10997":["踢上牆呈倒立姿勢，雙腳腳跟輕靠牆面。","收緊核心，雙臂保持伸直。","慢慢將身體重心往前移並往下放。","進入俄式挺身位置時，將膝蓋收向胸口。","穩定控制下放過程，接著重新準備。"],"10998":["踢上牆呈面牆倒立姿勢。","雙臂保持伸直，用力把地面推開。","將一隻腳離開牆面。","穩定控制並維持 10 到 20 秒。","將腿放回牆面，並安全地下來。"],"11006":["在椅子上坐直。","雙臂在胸前交叉，抱住自己。","將雙臂大大張開，並把胸口往前推出來。","維持擴胸姿勢 5 到 10 秒。","重複動作。"],"11010":["仰躺，雙腿朝天花板方向抬起。","雙臂往下壓穩地面。","抬起髖部，讓下背離開地面。","穩定控制慢慢放下。","避免利用慣性晃動。"],"11014":["站立，雙手各拿一個啞鈴，掌心朝前。","手肘保持微彎不鎖死。","將雙臂在身前往上舉到肩膀高度。","在最高點停頓一下。","慢慢放下，並避免身體往後傾。"],"11015":["以正握握住單槓懸掛，雙臂伸直。","讓肩膀自然往上放鬆靠近耳朵。","將肩胛骨往下拉並往內夾，把身體往上帶起幾公分。","全程保持手肘伸直不彎曲。","稍微停頓一下，接著慢慢放回完全懸掛的位置。"],"11016":["單膝跪地，另一隻腳在前方踩平，單手將啞鈴拿在肩膀高度。","收緊核心，並夾緊跪地那側的臀肌。","將啞鈴筆直往頭頂上方推，直到手臂伸直。","穩定控制將啞鈴放回肩膀位置。","完成所有次數後換邊。"],"11017":["雙膝跪地，髖部挺直，單手將啞鈴拿在肩膀高度。","收緊腹肌並將肋骨下收。","將啞鈴往頭頂上方推，直到手臂伸直。","慢慢將啞鈴放回肩膀高度，過程中身體不要往側邊歪斜。","完成所有次數後換手。"],"11047":["側躺，雙腿伸直並上下疊齊。","頭部枕在下方的手臂上，兩側髖部保持垂直疊齊。","將上方的腿往上並稍微往後抬起，過程中軀幹不要翻轉。","在最高點停頓一下，接著穩定控制放下。","完成所有次數後翻身換另一邊。"],"11048":["坐直，膝蓋彎曲，雙腳踩在地面上。","雙手放在膝蓋外側。","雙膝用力往外推，對抗雙手的阻力。","稍微維持一下。","慢慢放鬆。","背部保持挺直。"],"11049":["坐直，將雙腳抬離地面。","雙手抓住椅面邊緣。","將雙膝往外打開。","稍微停頓。","慢慢合攏雙膝。","背部保持挺直。"],"11050":["彈力帶套在大腿上，坐直，雙腳離地。","雙手抓穩椅緣。","對抗彈力帶將雙膝往外打開。","停頓一下。","慢慢合回。","背部保持打直。"],"11051":["兩邊滑輪調高，站在中間，掌心相對握住握把。","雙手在胸前交叉，手肘夾在身體兩側。","將握把往下往外推，直到手臂打直。","收緊三頭肌停一下。","手肘不動，讓握把慢慢回升。"],"11053":["上背靠在長凳上坐好，槓鈴放在髖部上方。","雙腳前後錯開，一腳稍微在前。","腳跟推地發力。","將髖部往上頂到完全伸展。","收緊臀肌。","慢慢放下，再換腳前後位置。"],"11054":["坐在器械內，軟墊壓在髖部上方。","雙腳前後錯開。","腳跟推地發力。","將髖部完全往上推起。","收緊臀肌。","慢慢放下，再換腳前後位置。"],"11055":["在踏板上寬站，腳尖朝外，握住 V 型槓。","髖部往後坐，挺胸，雙臂保持打直。","腳跟推地，完全站直。","在頂點收緊臀肌。","控制速度下放，讓膝蓋順著腳尖方向移動。"],"11056":["胸口貼著靠墊坐好，雙臂打直握住握把。","讓肩胛骨稍微往前帶開。","手肘不彎曲，直接將肩胛骨往後夾緊。","夾緊停留 1 秒。","慢慢回到起始位置。"],"11057":["坐在低位滑輪機前，雙腳踩穩，雙臂打直握住握把。","坐直，讓肩胛骨往前延展。","手臂保持打直，把肩胛骨往後夾在一起。","稍微停頓收緊。","慢慢回到起始位置。"],"11058":["髖部輕靠支撐物站立，雙手拿啞鈴放在大腿前側。","膝蓋微彎，背部打平。","髖部往後推，讓啞鈴貼著雙腿往下滑。","感覺大腿後側被拉緊時停住。","髖部往前推，站直身體。"],"11059":["固定彈力帶並套在一隻腳上，接著跪上長凳，雙手撐在前方。","核心收緊，背部打平。","作用腿往後往上踢，直到髖部完全伸展。","在頂點收緊臀肌停一下。","控制速度慢慢放回，別讓彈力帶猛拉回腿部。","完成次數後換腿。"],"11060":["將繩索設定在上胸高度，雙手握住，手臂伸直。","手肘抬高，將繩索拉向臉部。","在動作末端將拳頭往上轉，讓雙手最後停在手肘上方。","收緊後三角肌停留 1 秒。","原路轉回並慢慢放回。"],"11077":["側躺、雙腿疊放，雙手在胸前舉起一顆啞鈴。","兩側髖部上下對齊，核心收緊。","軀幹不旋轉，將上方腿抬起。","在頂點停頓一下。","控制速度放下，完成次數後換邊。"],"11088":["站直，雙臂自然垂放身體兩側。","單腿往後跨成弓步，同時雙臂往頭頂上方延伸。","軀幹朝前腿方向扭轉。","轉回正面，前腳推地站起。","整組雙腿交替進行。"],"11089":["坐在地上，雙腿在舒適範圍內盡量往兩側打開。","坐直，雙臂往前延伸。","拱起脊椎，一節一節慢慢往下捲。","再慢慢捲回直到坐直。","重複 8 到 10 次慢速動作，不要硬壓。"],"11090":["懸垂在單槓上，把身體往上拉，讓髖部與雙腿在身體上方。","身體打直，雙臂鎖直。","身體維持一直線，慢慢往下放到接近水平。","無法維持直線時就停住，屈膝收腿回到上方。","休息一下，小心重複幾次。"],"11091":["單手懸垂在單槓上，肩膀保持出力穩定。","核心收緊，雙腿併攏。","將腳尖往上抬向單槓。","雙腿慢慢放下，不要晃動。","完成次數後換手。"],"11092":["面向地雷管跪立，雙手在胸前握住槓鈴末端。","髖部擺正，核心收緊。","轉動軀幹，將槓鈴往一側畫弧線擺動。","受控地畫弧線擺向另一側。","整組維持穩定節奏。"],"11093":["雙腳與髖同寬站立，槓鈴在足弓上方。","握槓，核心收緊，背部打平。","雙腳推地站起。","控制速度將槓鈴放回地面方向。","每次重設姿勢，維持背部中立。"],"11095":["在椅子上坐直，雙手放膝蓋，雙腳平踩地面。","吸氣，拱起背部並挺胸。","吐氣，圓背並收下巴。","在兩個姿勢之間慢慢切換。","配合呼吸重複 8 到 10 次。"],"11250":["兩邊滑輪設定在肩膀高度，雙手各握一個握把。","往前跨出成前後站姿，身體微微前傾。","手肘微彎，將雙手在胸前合攏。","收緊胸肌停一下。","雙臂慢慢打開，直到感覺胸口被拉伸。"],"11251":["滑輪調高，側對器械跪立，雙手握住握把。","髖部擺正，核心收緊。","將握把斜跨身體往下拉向對側髖部。","靠軀幹旋轉發力，而不是只用手臂拉。","慢慢放回，完成次數後換邊。"],"11252":["滑輪調低，雙臂打直將握把舉過頭，身體站直。","核心收緊，肋骨下收。","髖部往後推、彎曲膝蓋往下深蹲。","握把維持在頭頂上方，保持挺胸。","腳跟推地站起。"],"11253":["面向高位滑輪跪立，雙臂伸直握住橫桿或握把。","坐直，核心收緊。","手肘往下帶，將握把拉向胸口。","在底部收緊背闊肌。","讓握把慢慢回升到完全伸展。"],"11254":["滑輪設定在肩膀高度，雙臂交叉握住對側握把。","站直，手肘微彎。","雙手往外往後拉開成大弧線。","夾緊肩胛骨。","慢慢回到雙手交叉的起始位置。"],"11255":["側對低位滑輪站立，將握把握在胸前。","往側邊大步跨出，髖部往後坐。","另一腿保持打直，挺胸。","彎曲腿推地回到站姿。","完成次數後換邊。"],"11256":["躺在兩個低位滑輪之間的長凳上，雙手在胸口高度各握一個握把。","雙腳踩穩，肩胛骨往後收。","將握把往上推，直到雙臂打直。","在頂點收緊胸肌。","慢慢下放，直到感覺胸肌伸展。"],"11257":["坐在滑輪機前，滑輪調高，握住握把。","坐直並挺胸。","手肘微微外展，將握把拉向上胸。","夾緊肩胛骨。","慢慢放回直到手臂完全伸直。"],"11258":["在兩組滑輪之間採前後錯位站姿，雙手各握一個握把。","核心收緊，髖部擺正。","一手往前推，同時另一手往後拉向肋骨。","慢慢交換兩手動作。","整組完成後換邊進行。"],"11259":["腳踝扣環接上低位滑輪，面向器械站立並扶穩。","核心收緊，軀幹保持直立。","將作用腿往正後方推。","在頂點收緊臀肌，下背不要凹陷。","慢慢放回，完成次數後換腿。"],"11260":["跪在兩個低位滑輪之間，雙手在肩膀高度握住握把。","夾緊臀肌並收緊腹肌。","將兩邊握把直直推過頭頂。","手肘推直，身體不要後仰。","控制速度放回肩膀高度。"],"11261":["低位滑輪接上繩索，掌心相對握住。","站直，手肘貼在身體兩側。","將繩索往上彎舉到肩膀方向。","在頂點收緊二頭肌。","慢慢放下，身體不要晃動借力。"],"11262":["仰臥，雙腳連接低位滑輪，雙手放在身體兩側。","下背貼緊地面。","單膝彎曲拉向胸口。","慢慢放回並換腿。","維持受控的交替節奏。"],"11263":["面向胸口高度的滑輪站立，單手握住握把。","採前後錯位站姿，核心收緊。","將握把拉向肋骨，同時微微轉動軀幹。","在終點收緊背部。","慢慢放回，完成次數後換手。"],"11264":["在兩個低位滑輪之間放好上斜長凳，雙手各握一個握把。","雙腳踩穩，肩胛骨往後收。","將握把往上推並稍微向內靠攏。","在頂點收緊上胸。","慢慢下放到舒適的伸展位置。"],"11265":["腳踝扣環接上低位滑輪，背對器械站立並扶穩。","站直，核心收緊。","將作用腳膝蓋往前往上提。","在頂點停頓一下。","慢慢放下，完成次數後換腿。"],"11266":["靠近滑輪這一側的腳裝上腳踝扣環並接低位滑輪，手扶穩保持平衡。","站直，核心收緊。","將外側腿往側邊抬起。","在頂點停一下，身體不要歪斜。","慢慢放回，完成次數後換邊。"],"11267":["離滑輪較遠那側的腳裝上腳踝扣環並接低位滑輪，手扶穩保持平衡。","站直，核心收緊。","將作用腿從支撐腿前方橫掃過去。","收緊大腿內側。","慢慢放回，完成次數後換邊。"],"11268":["在胸前握住滑輪握把，雙腳與肩同寬站立。","核心收緊，保持挺胸。","髖部往後往下坐，直到大腿約與地面平行。","膝蓋對齊腳尖方向。","腳跟推地站起。"],"11269":["面向低位滑輪，背部打平俯身，單手握住握把。","核心收緊，髖部往後推。","將握把拉向髖部。","在頂點收緊背部。","慢慢放回，完成次數後換手。"],"11270":["跪在高位滑輪下方，雙手在頭兩側握住繩索。","髖部保持固定不動。","軀幹往下捲，讓手肘靠近膝蓋。","在底部收緊腹肌。","慢慢回到直立的起始位置。"],"11271":["側對胸口高度的滑輪站立，雙手握住握把。","雙臂打直，雙腳踩穩。","軀幹往遠離器械的方向旋轉。","停頓一下，再慢慢轉回。","完成次數後換邊。"],"11272":["掌心朝前握住低位滑輪握把，雙臂自然下垂。","將握把彎舉到肩膀高度。","準備往上推時，先將掌心轉向自己。","往上推過頭，同時把掌心轉回朝前。","原路反方向動作，控制速度放回。"],"11273":["躺在兩個低位滑輪之間的長凳上，雙手各握握把舉在胸口上方。","手肘保持微彎。","雙臂畫大弧線往兩側下放。","在舒適的伸展位置停住。","將握把在胸口上方合攏。"],"11274":["採前後錯位站姿，雙手各握一個高位滑輪握把。","收緊核心。","單手往前下方斜推。","慢慢收回，換另一手推。","整組交替進行，髖部不要扭轉。"],"11275":["擺出側棒式，上方手握住低位滑輪握把。","抬起髖部，讓身體呈一直線。","將握把拉向肋骨。","髖部保持高挺穩定。","慢慢伸直手臂，完成次數後換邊。"],"11276":["俯臥，腳踝扣環連接低位滑輪。","髖部貼穩地面。","將腳跟往臀肌方向勾起。","在頂點收緊大腿後側。","慢慢放回，完成次數後換腿。"],"11277":["背對低位滑輪站立，手在雙腿之間握住握把。","核心收緊，手臂接近打直。","將握把往前平舉到肩膀高度。","稍微停頓。","慢慢放下，完成次數後換手。"],"11278":["側對低位滑輪站立，單手在體側握住握把。","保持挺胸。","往遠離器械的一側彎曲身體。","收縮腹斜肌將身體拉回直立。","完成次數後換邊。"],"11279":["單手將低位滑輪握把舉過頭，手肘彎曲，上臂貼近頭部。","收緊核心。","將手臂往頭頂上方伸直。","在頂點收緊三頭肌。","慢慢放回，完成次數後換手。"],"11282":["在臀腿訓練椅上固定雙腳，髖部靠在軟墊上。","雙臂往頭頂方向延伸，身體後仰。","捲起身體，同時雙臂往前帶。","軀幹往前延伸超過膝蓋。","控制速度慢慢躺回。"],"11283":["站直，雙腳與肩同寬。","往上跳起，將雙膝拉向胸口。","在空中交叉雙腳。","前腳掌輕柔落地。","下一次跳起時解開並換腳交叉。","保持穩定快速的節奏。"],"11284":["仰臥，單手在胸口上方舉起一顆壺鈴。","手肘保持微彎。","將壺鈴畫弧線往側邊下放。","再帶回胸口上方。","換手交替進行。"],"11285":["仰臥，將彈力帶壓在上背下方，雙手各握一端握把。","雙手從胸口高度開始。","雙手直直往上推，直到手臂伸直。","收緊胸肌。","慢慢放回起始位置。"],"11286":["從半跪姿開始，雙手在胸前抱住壺鈴。","重心往後移，同時將前腿往側邊伸直。","感受大腿內側的伸展。","回到起始位置。","完成次數後換邊。"],"11287":["雙腳與髖同寬，雙手在背後握住一顆壺鈴。","膝蓋微彎，核心收緊。","背部打平，髖部往後推並俯身。","感覺大腿後側拉緊時停住。","髖部往前推，站直身體。"],"11288":["站直，雙臂直直舉過頭頂。","肋骨下收，核心收緊。","將肩膀往上聳向耳朵。","稍微停頓。","慢慢放下並重複。"],"11289":["站直，雙腳與髖同寬。","將重心移到單腳上。","順暢地畫圈轉動腳踝與髖部。","上半身保持穩定。","慢速做 8 到 10 次後換邊。"],"11303":["在身後放一張長凳，將槓鈴扛在上背。","出槓，雙腳稍微往前站。","往下坐，直到輕觸長凳。","保持挺胸，膝蓋對齊腳尖方向。","腳跟推地站起。"],"11309":["坐在器械上，單手以反握握住握把。","坐直並收緊核心。","將握把往下拉，手肘往身體側邊帶。","在底部收緊背闊肌。","慢慢放回，完成次數後換手。"],"11315":["將椅子抵住牆壁，雙手靠近放在椅面上。","雙腳往後走，直到身體呈一直線。","手肘貼近身體，將胸口降向椅子。","往上推回直到雙臂打直。","髖部與身體維持一直線。"],"11316":["背靠牆站立，雙腳稍微往前踩。","順著牆往下滑，直到膝蓋彎曲約 45 度。","背部平貼牆面。","腳跟推地站起。","重複完成整組。"],"11317":["在羅馬椅上固定雙腳，雙手在胸前抱住一片槓片。","背部打直，身體呈一直線。","控制速度將軀幹往下放。","往上抬起，直到身體回到一直線。","在頂點收緊臀肌，不要過度後仰。"],"11374":["側躺，下方手臂放在身前，手肘彎曲成 90 度。","兩肩上下對齊，上臂維持在胸口高度。","用上方手輕輕將下方前臂往地面壓。","感覺肩膀後側有溫和伸展感就停住。","維持 20 到 30 秒後換邊。"],"11383":["單臂在身前伸直，手肘打直、掌心朝下。","彎曲手腕，讓手指指向地面。","用另一隻手輕輕把該手手背往身體方向拉。","保持溫和伸展，肩膀放鬆。","維持 20 到 30 秒後換手。"],"11436":["在低位滑輪裝上繩索或對握握把，背對配重片站立。","雙手舉過頭握住，手肘彎曲朝前，一腳稍微往前跨。","上臂貼近耳朵，肋骨下收。","伸展手肘，直到雙臂在頭頂上方打直。","慢慢放回到深度伸展的位置並重複。"],"11450":["面向樓梯站立，雙腳與髖部同寬。","一腳踩上第一階，腳跟推地往上爬。","接著踩上第二階，再有控制地退回地面。","保持軀幹挺直，膝蓋朝腳尖方向移動。","每一下交替前導腳，或單邊完成所有次數再換腳。"],"11451":["背靠牆站立，雙腳往前站約一步距離。","順著牆面往下滑，直到膝蓋彎曲約 45-60 度。","保持背部平貼牆面，膝蓋在腳踝上方。","全腳掌踩穩地面，保持平穩呼吸。","維持 20-45 秒，再順著牆面滑回站姿。"],"11452":["面向牆壁站立，雙手在胸口高度扶牆。","一腳往後退，腳跟平貼地面，腳尖朝前。","彎曲前膝、身體往前傾，直到感覺後腳小腿被拉開。","保持後腿伸直且腳跟不離地。","維持 20-30 秒後換腳。"],"11529":["繫好腰帶，單腳站在踏板上，膝蓋微彎。","從髖部折起並往後推，同時降低軀幹。","騰空腿往身後延伸以維持平衡。","背部保持平直，下放到感覺大腿後側拉緊。","髖部往前推站直身體，完成次數後換腳。"],"11567":["面朝下趴在器材上，小腿後方抵住靠墊。","將腳跟朝臀肌彎舉，再有控制地放下。","轉換成反向背部伸展姿勢，雙腿後方抵住靠墊。","夾緊臀肌將雙腿抬起，直到與軀幹呈一直線。","慢慢放下，避免甩動。"],"11568":["將槓鈴扛在上背，前腳踩在低槓片或踏板上。","後腳腳背放在身後的長凳上。","垂直往下蹲，直到前側大腿約與地面平行或更低。","保持軀幹直立，前膝朝腳尖方向移動。","前腳腳跟推地站起，完成後換腳。"],"11569":["將彈力帶套在腳踝或膝蓋上方並站直。","需要的話可以扶著支撐物保持平衡。","膝蓋保持伸直，將單腿往側邊抬起。","在頂點短暫停頓，身體不要歪斜。","慢慢放下。","完成次數後換腳。"],"11570":["將彈力帶套在腳踝或固定在低處，站直身體。","手扶支撐物維持平衡。","保持核心收緊。","將單腿往正後方踢出，下背不要拱起。","在末端夾緊臀肌。","慢慢收腿回原位，完成後換腳。"],"11571":["坐在地面，雙腿伸直，雙臂抱胸。","身體微微後傾。","重心移向一側，將另一側髖部往前推。","左右交替往前移動。","保持軀幹直立。","往後退回到原點。"],"11572":["仰躺，將泡棉滾筒放在上背下方。","雙手托住頭部。","保持臀部貼地、雙膝彎曲。","順著滾筒輕輕往後仰。","回到中立位置，將滾筒往上或往下移一格。","緩慢移動，往後延伸時吐氣。"],"11644":["側躺，將彈力帶套在大腿或腳踝。","雙腿保持伸直並上下疊齊。","將上方腿抬起，骨盆不要往後翻。","在頂點短暫停頓。","慢慢放下。","完成次數後換邊。"],"11645":["坐著或躺著，將一腿在身前伸直。","放鬆上半身。","收緊大腿前側，將膝蓋往下壓。","維持 5-10 秒。","完全放鬆。","重複數次後換腳。"],"11646":["仰躺或站立，身體放鬆。","將兩側臀肌用力夾緊。","雙腿與背部保持不動。","維持夾緊 5-10 秒。","完全放鬆。","重複數次。"],"11647":["單腳站立，膝蓋微彎，雙臂自然垂放兩側。","膝蓋保持接近伸直，以前腳掌推地垂直往上跳。","用同一腳的前腳掌輕柔落地，並立刻反彈跳起。","彈跳保持小幅且快速，髖部水平、核心收緊。","依設定的時間或次數跳完後換腳。"],"11648":["面朝下趴著，手肘彎曲並往兩側打開。","額頭輕靠在地面。","夾緊肩胛骨，將雙臂與胸口微微抬起。","雙臂比出 W 字形並停留 1 秒。","慢慢放下並重複。"],"11649":["面向牆壁站立，雙手扶牆，一腳往後退。","雙膝彎曲，後腳腳跟平貼地面。","身體前傾，直到感覺後腳小腿下段有伸展感。","保持髖部擺正並挺胸。","維持 20-30 秒後換腳。"],"11650":["坐在椅子上，單腳平貼地面，膝蓋彎曲呈 90 度。","將另一腳抬離地面或勾在後方。","訓練腳的前腳掌往下壓，將腳跟抬起。","在頂點短暫停頓，再慢慢放下。","完成次數後換腳。"],"11651":["在椅子或長凳上坐直，單腿伸直並放鬆大腿肌肉。","用指腹或掌根輕放於膝蓋骨邊緣。","以小幅度慢速將膝蓋骨輕輕左右、上下推滑。","股四頭肌保持放鬆，在舒適且無刺痛的範圍內進行。","持續移動 30-60 秒後換腳。"],"11652":["坐在椅子前緣並坐直，雙手扶椅面或放腿上。","慢慢伸直一側膝蓋，同時將下巴收向胸口。","彎曲膝蓋收回，同時抬頭往上看。","動作保持流暢輕柔，不要勉強推到強烈拉扯或發麻。","慢速重複 10-15 次後換腳。"],"11653":["站直，雙腳與髖部同寬，雙臂放鬆。","輕輕收緊腹肌，讓肋骨維持在髖部正上方。","在舒適範圍內盡量用力夾緊臀肌。","維持 3-5 秒，不要往後仰或過度捲尾骨。","完全放鬆，重複 10-15 次。"],"11654":["在地板或長凳上坐直，腳底相對或單腿盤起。","讓一側膝蓋慢慢往旁朝地面下沉。","膝蓋下放時保持背部平直並挺胸。","在舒適範圍末端短暫停頓，再將膝蓋抬回。","每邊重複 8-12 次。"],"11656":["站在齊腰到齊胸深的水中，雙腳與髖部同寬。","將一側膝蓋往身前抬起，放下後再抬另一腳。","手臂自然擺動，保持身體挺直。","以輕鬆穩定的配速踏步，身體不要前傾。","以輕鬆到中等強度持續 2-5 分鐘。"],"11657":["雙臂伸直，將槓片舉在頭頂上方。","站直，雙腳與髖部同寬。","一腳往後退並下蹲，直到雙膝都呈約 90 度。","保持肋骨下收，槓片穩穩維持在頭頂。","前腳推地回到原位，雙腿交替進行。"],"11714":["雙臂伸直懸吊在兩條繩索上，雙腿併攏。","收緊核心並將肩胛骨下壓。","將身體往上拉，直到雙手來到胸口或下巴高度。","保持手肘朝下並貼近身體。","有控制地放回完全懸吊。"],"11715":["將繩索設在約腰部高度，躺在下方握住繩尾。","雙腳腳跟踩地，保持腳跟到頭部呈一直線。","夾緊肩胛骨，將胸口拉向雙手。","保持手肘貼近身體。","慢慢放下直到雙臂伸直。"],"11716":["將石頭抱到胸前並緊貼身體。","雙腳與髖部同寬站立，收緊核心。","微蹲後用雙腿用力往上推。","將石頭推過頭頂直到手臂完全鎖定。","有控制地將石頭放回胸前。"],"11717":["從高棒式開始，雙手在肩膀正下方。","有控制地將胸口朝地面下放。","爆發力往上推，讓雙手推離地面。","手肘微彎輕柔落地。","重新穩住身體直線並重複。"],"11718":["胸口貼著上斜靠墊坐好，握住握把。","雙臂在身前微彎作為起始。","雙臂畫大弧線往外、往後展開。","在末端夾緊肩胛骨。","慢慢回放，不要讓槓片撞擊。"],"11762":["將上斜長凳放在槓鈴下方，胸口朝下趴在凳上。","雙手握槓，略寬於肩。","將槓鈴拉向下肋骨位置。","在頂點將肩胛骨夾緊。","慢慢放下直到雙臂伸直。"],"11763":["將長凳調成上斜，並將低位滑輪設在身後。","往後靠坐，雙臂自然下垂並握住握把。","手肘保持在後，將握把朝肩膀彎舉。","在頂點收緊二頭肌。","慢慢放回完全伸展的位置。"],"11764":["將滑輪設在胸口高度，掌心朝上握住握把。","背對器材採前後站姿。","將握把往前推直到手臂伸直。","保持軀幹穩定，抵抗身體扭轉。","慢慢回放，完成次數後換手。"],"11781":["面向跳箱站立，雙腳與髖部同寬。","微蹲成四分之一蹲，雙臂往後擺。","爆發力往上跳上跳箱，膝蓋微彎輕柔落地。","在箱上站直，接著一腳一腳踩回地面。","重設姿勢並重複，保持動作迅速且受控。"],"11782":["雙腳站立，膝蓋微彎，雙臂預備。","用力推地往側邊跳出舒適的距離。","雙腳輕柔落地，膝蓋朝腳尖方向對齊。","立刻跳回起始側。","保持挺胸，依設定的次數或時間重複。"],"11783":["將雙手伸到身前。","雙手用力握緊成拳。","快速張開雙手，手指盡量撐到最開。","快速重複 20-30 次。","保持手腕放鬆。"],"11784":["雙臂伸直懸吊在單槓上，膝蓋微彎。","下蹲進入深蹲位置。","雙腿爆發力往上推。","輕柔緩衝落地並回到起始位置。","保持核心收緊並重複。"],"11785":["站直或坐直，單側手肘彎曲呈 90 度貼在身側。","將前臂往腹部前方轉過去。","在舒適範圍內緩慢移動。","回到起始位置，重複 8-12 次。","換手進行。"],"11786":["坐直，單臂垂放身側，掌心朝後。","肩膀微微下壓，並將手臂往內轉。","輕輕彎曲手腕，同時將頭往對側傾。","緩慢移動，感覺微緊就停，絕不做到疼痛。","重複 8-10 次後換手。"],"11787":["坐直，單臂往側邊抬起，掌心朝上。","將手腕與手指往後伸展。","頭部微微傾向遠離該側手臂的方向。","慢慢回正，重複 8-10 次。","維持在輕微伸展感即可，完成後換手。"],"11788":["坐直，單臂往側邊抬起。","彎曲手肘，將手像戴面具一樣移向臉部。","頭部微微傾向對側。","輕柔地將手臂重新往外伸直。","重複 8-10 次後換手。"],"11789":["雙手持槓鈴置於大腿前側，一腳退在另一腳斜後方，後腳以前腳掌輕點地。","將大部分重心放在前腳，前膝微彎。","背部保持平直，從髖部折起，讓槓鈴順著雙腿往下滑。","下放到感覺大腿後側強烈拉伸，接著將髖部往前推回站姿。","完成所有次數後換腳前後交換。"],"11790":["單腳站立，膝蓋微彎，雙手插腰。","騰空腳先往身前輕點地面，再往側邊輕點。","保持軀幹直立，將腳往身後輕點。","有控制地收回中間並重複整套順序。","完成所有次數後換腳。"],"11791":["單手掌心握著一顆小球。","用手指往下壓球。","保持手腕中立，有控制地張開並擠壓。","維持按壓 2-3 秒。","重複設定次數後換手。"],"11792":["跪姿挺直身體，手肘彎曲約 90 度。","雙手掌心朝上置於身前。","保持手肘貼緊身體兩側。","收緊二頭肌並維持姿勢。","維持 20-30 秒後休息。"],"11793":["站直，手肘彎曲貼在身側。","將前臂往遠離身體的外側推。","在舒適範圍末端短暫停留。","慢慢收回，重複 8-12 次。","換手進行。"],"11794":["將球放在桌面上壓在單手下方，或握在掌心中。","手指張開包覆在球面上。","往下壓並維持 2-3 秒。","有控制地放鬆。","重複設定次數後換手。"],"11795":["站直，雙臂垂放身體兩側。","保持手肘伸直，將單臂往後推。","在舒適範圍內移動。","慢慢收回，重複 8-12 次。","換手進行。"],"11796":["站直，手肘彎曲呈 90 度貼在身側。","將前臂往遠離腹部的方向外旋。","保持手肘貼緊身側。","慢慢轉回，重複 8-12 次。","換手進行。"],"11797":["站直，手肘彎曲置於身前。","將手臂往前推直到伸直。","保持肩膀放鬆。","慢慢收回，重複 8-12 次。","換手進行。"],"11798":["背部打直，從髖部往前俯身，雙臂自然下垂。","將雙臂往髖部後方掃過去。","接著往兩側大幅展開，抬至肩膀高度。","繼續沿弧線往前移直到雙臂指向前方，再原路折返。","保持頸部中立，流暢地完成設定次數。"],"11799":["雙手持輕啞鈴，背部保持平直從髖部往前俯身。","雙臂從髖部後方開始。","將啞鈴往兩側掃出，抬到肩膀高度。","繼續沿弧線往前移，再有控制地原路折返。","使用輕重量，避免晃動軀幹。"],"11800":["仰躺在地板上，雙膝彎曲，單手持啞鈴舉在胸口上方。","另一隻手臂平放在身側地面。","將啞鈴往上推直到手臂伸直，肩膀順勢往前送。","有控制地放回，直到上臂輕觸地面。","完成次數後換手。"],"11801":["側躺或趴躺，雙腿伸直。","彎曲一側膝蓋，將腳跟帶向臀肌，需要時可手抓腳踝。","以緩慢受控的節奏反覆彎曲與伸展膝蓋。","保持髖部平穩，維持在舒適範圍內。","重複 10-15 次後換腳。"],"11864":["站立，單手持啞鈴於身側，掌心朝前。","將啞鈴往上彎舉，直到手肘呈 90 度。","在該位置維持 2-3 秒。","繼續彎舉到頂，再慢慢放下。","完成次數後換手。"],"11877":["雙臂伸直懸吊在單槓上。","將雙腿在身前伸直抬起，直到與地面平行。","腳尖壓直，膝蓋鎖直。","避免身體晃動。","維持 10-20 秒後放下。"],"11878":["雙臂伸直懸吊在肋木架上。","收緊核心，保持身體穩定。","將雙腿往身前抬起。","在不晃動的前提下盡量抬高。","慢慢放下並重複。"],"11879":["將槓鈴扛在上背，站在長凳前方。","將一腳踩上長凳。","該腳腳跟用力往下推，直到身體完全站直。","有控制地退回地面。","完成次數後換腳。"],"11880":["站在踏板上，胸口貼穩支撐墊。","手臂伸直，握住窄握把手。","手肘貼近身體，將把手往軀幹方向拉。","將兩側肩胛骨往中間夾緊。","慢慢放回，直到手臂完全伸展。"],"11903":["站直，單手扶牆或穩固物以維持平衡。","彎曲一邊膝蓋，手抓住腳踝，將腳跟往臀肌方向拉近。","骨盆稍微後傾，將髖部輕輕往前推。","雙膝保持靠攏，上半身挺直。","維持 20-30 秒後換腳。"],"11904":["採單膝跪姿，膝蓋下方墊軟墊，另一隻腳踩在前方。","上半身保持直立，將骨盆稍微後傾收好。","重心往前移，直到感覺後腳的髖部前側有伸展感。","前腳膝蓋保持在腳踝正上方，同時收緊核心。","維持 20-30 秒後換邊。"],"11954":["側躺，兩側髖部上下疊好，下方的腿彎曲放在身前。","彎曲上方的膝蓋，將腳往臀肌方向收，並用手抓住腳背。","輕輕將上方的膝蓋往後帶，同時讓胸口朝向地面轉開。","慢慢呼吸，維持 20-30 秒。","換邊重複動作。"],"12018":["雙腳與髖同寬站立，單手握住壺鈴把手。","將壺鈴繞到背後，在腰後換另一隻手接住。","接著繞回身體前方，讓畫圈動作保持流暢。","收緊核心，保持髖部穩定不晃動。","繞幾圈之後，換反方向進行。"],"0001":["平躺，雙膝彎曲，雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，將上半身捲離地面至約 45 度（捲腹）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"0002":["雙腳分開與肩同寬站立，雙臂垂於體側。","背打直核心收緊，慢慢將軀幹向一側側屈，手沿大腿向下滑向膝蓋。","底部稍作停頓，慢慢回正。","換向另一側側屈。","交替進行至所需次數。"],"0003":["平躺，雙手抱頭。","雙腿抬離地面，膝蓋彎曲成 90 度。","右肘帶向左膝，同時右腿向前踢直伸展。","回正，換左肘碰右膝，同時左腿伸直（腳踏車捲腹）。","雙腿交替踩踏重複至指定次數。"],"0005":["站在彈力帶中段，兩手各握一端。","手肘貼在身體兩側，掌心朝前。","一手往肩膀方向彎舉。","慢慢放下這一手，同時彎舉另一手。","上臂保持不動，身體不要往後仰。","左右交替完成次數。"],"0006":["平躺，雙膝彎曲，雙腳踩實地面。","雙臂伸直放於身側，平行於地面。","腹肌收緊抬起肩胛骨，右手向側邊滑動去碰右腳跟。","回正，換左手向側邊滑動去碰左腳跟（企鵝點腳跟）。","交替進行至所需次數。"],"0007":["坐在滑輪划船機上，背部挺直，雙腳踩實。","正握抓把手，握距略寬於肩。","微向後仰，將把手拉向胸口，肩胛骨用力夾緊。","頂端停留片刻，慢慢放回把手。","重複所需次數。"],"0009":["調整雙槓輔助機配重，雙膝跪在墊上。","掌心朝下握住把手，雙臂伸直支撐。","手肘彎曲下沉身體，直到上手臂平行地面。","停頓片刻，推直雙臂推回頂端。","重複所需次數。"],"0010":["懸掛在單槓上，手臂完全伸直，掌心朝外。","收緊核心將雙膝抬向胸部，雙腿併攏。","雙膝至胸部高度時，爆發力將雙腿向下甩動伸展。","順勢擺回再次提膝。","重複所需次數。"],"0011":["懸掛在單槓上，雙臂伸直，掌心朝外。","核心發力收縮，屈髖屈膝將雙膝抬向胸前（懸垂提膝）。","頂峰停頓片刻，擠壓腹肌。","慢慢放回雙腿。","重複所需次數。"],"0012":["平躺，雙腿伸展，雙臂貼地。","雙手墊在臀部下方支撐下背。","收緊腹肌，雙腿打直抬離地面。","雙腿併攏，向一側慢慢放下至接近地面。","停頓片刻，將雙腿抬回中央。","換向另一側下放。","交替進行至所需次數。"],"0013":["平躺，雙腿伸展，雙臂放身側。","雙手置於臀部下方支撐。","收緊核心將雙腿抬離地面，維持伸展打直。","抬起雙腿直到垂直於地面（仰臥抬腿）。","慢慢放回地面上方懸空。","重複所需次數。"],"0014":["坐在地上，雙膝彎曲，雙腳踩地。","雙手抱藥球於胸前。","微向後傾，收緊腹肌背打直。","軀幹向右旋轉，將藥球移向身體右側地面。","停頓片刻，轉向左側將藥球移向左側（俄羅斯轉體）。","交替進行至所需次數。"],"0015":["調整雙槓輔助機重量。","雙手對握抓住雙槓，雙臂伸直支撐。","雙腳離地身體懸掛。","背肌發力向上拉起身體，手肘貼近軀幹。","拉至下巴超過把手高度。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0016":["俯臥趴在平凳上，雙腿完全伸展。","夥伴按住或用彈力帶固定雙腳腳踝。","收緊腿後肌群，將小腿向上彎向臀部（北歐腿彎舉 Nordic Curl 概念）。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0017":["調整引體向上輔助機配重。","正握抓住把手，握距略寬於肩。","雙臂伸展身體懸掛。","背肌發力挺胸將身體拉向上方把手。","持續拉至下巴超過把手。","頂端停頓片刻，緩慢降回。","重複所需次數。"],"0018":["雙腳與肩同寬站立，雙手在後腦勺抓緊毛巾。","手肘靠近耳側，上手臂固定。","前臂發力向上伸展打直，頂端擠壓三頭肌。","停頓片刻，慢慢放回。","重複所需次數。"],"0019":["調整輔助機台重量。","面向機台跪在墊上，雙手握把手。","手肘彎曲下沉身體，背部打直貼近機台。","底部停頓片刻，推回頂端。","重複所需次數。"],"0020":["將平衡板放在平坦地面上。","單腳踩在平衡板中心。","重心轉移到平衡板上的腳，收緊核心。","維持平衡站立至指定時間。","換另一隻腳重複。"],"0021":["坐在健身球上，雙腳往前走，直到下背靠在球上。","雙手放在頭側，或交叉在胸前。","捲起上身，讓肋骨往髖部靠近。","在頂端夾緊腹肌。","慢慢往後躺回球上。","雙腳踩穩，脖子放鬆。"],"0022":["平躺在平凳上，雙腳平踩。","正握抓住槓鈴（掌心朝外），雙臂伸直於胸前。","手臂維持打直微彎，將槓鈴呈弧線降向頭後，直到感受背部拉伸。","停頓片刻，反向將槓鈴推回胸部上方。","重複所需次數。"],"0023":["站直雙腳與肩同寬，雙手各握一啞鈴置於體側，掌心朝前。","上手臂固定不動，吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂峰停頓片刻，強力收縮。","吸氣慢慢放回。","交替手臂進行至指定次數。"],"0024":["站立雙腳與肩同寬，將槓鈴架在鎖骨前側（前蹲舉 Front Squat 架槓）。","正握抓槓，手肘抬高，上手臂平行地面。","屈膝屈髖下蹲成深蹲，挺胸背打直。","深蹲底部稍作停頓，腳跟推地站回。","重複所需次數。"],"0025":["平躺在平凳上，雙腳踩實，背部緊貼椅面。","正握抓住槓鈴，握距略寬於肩寬（平板槓鈴臥推 Bench Press）。","起槓推直於胸口正上方。","吸氣慢慢將槓鈴降向胸部，手肘微扣。","輕觸胸部時停頓片刻。","吐氣發力將槓鈴推回起始位置。","重複所需次數。"],"0026":["深蹲架上將槓鈴調至胸部高度。","背對深蹲架站立，雙腳與肩同寬。","下蹲鑽入槓下扛槓，正握握距略寬於肩。","起槓後退兩步站穩，雙腳與肩同寬。","深蹲下沉，膝蓋對齊腳尖方向。","底部停頓片刻，踩穩腳跟推回站姿。","重複所需次數。"],"0027":["雙腳分開與肩同寬站立，膝蓋微彎。","屈髖前傾，背部維持平直挺胸。","正握抓住槓鈴，雙手間距略寬於肩寬。","肩胛後收夾緊，將槓鈴拉向下胸腹部（俯身槓鈴划船 Bent-over Row）。","頂端停留片刻，緩慢降回。","重複所需次數。"],"0028":["雙腳與肩同寬站立，槓鈴置於身前地面。","屈膝屈髖下沉，正握抓槓，握距略寬於肩。","腳跟蹬地伸膝展髖將槓鈴拉離地面。","過膝後爆發力挺髖展體，聳肩將槓鈴向上提拉。","槓鈴升至胸高時快速鑽入槓下翻腕架槓成前蹲姿態（上膊 Clean）。","隨即雙腿蹬直並借力將槓鈴垂直推過頭頂（上挺推舉 Jerk/Press）。","有控制地下放槓鈴回地面，重複動作（上膊與推舉 Clean and Press）。"],"0029":["槓鈴置於前肩鎖骨處，手肘向前抬高（前蹲舉）。","屈膝屈髖向後下蹲，如同坐入椅子。","下沉時維持挺胸背打直，膝蓋不超過腳尖。","蹲至大腿平行地面或略低。","底部停頓片刻，腳跟發力推起站直。","重複所需次數。"],"0030":["平躺在平凳上，雙腳踩實，背部貼緊椅面。","窄握距握槓，握距略窄於肩寬（窄握臥推 Close-grip Bench Press）。","起槓慢慢降向胸部，手肘緊貼軀幹兩側。","輕觸胸部時停頓片刻。","三頭肌發力將槓鈴推回頂端，雙臂完全伸展。","重複所需次數。"],"0031":["站直，雙腳分開與肩同寬，反手握住槓鈴，掌心朝前。","手肘貼緊軀幹，吐氣彎舉槓鈴收縮二頭肌。","舉至二頭肌完全收縮、槓鈴與肩同高。","頂端停頓片刻，收縮二頭肌。","吸氣慢慢放回槓鈴。","重複所需次數。"],"0032":["雙腳分開與肩同寬站立，槓鈴放在身前的地面上。","屈髖屈膝俯身，正握抓住槓鈴，握距略寬於肩寬（傳統硬舉）。","挺胸背打直，腳跟推地伸膝展髖拉起槓鈴，槓鈴沿著小腿大腿向上滑行。","站直時夾緊臀部並保持核心收緊。","屈髖屈膝將槓鈴放回地面，全程保持背部挺直。","重複所需次數。"],"0033":["躺在下斜臥推椅上，雙腳固定，頭部低於臀部。","正握抓住槓鈴，握距略寬於肩寬。","起槓後慢慢將槓鈴降向胸部，手肘適度內收。","在最低點稍作停頓，然後將槓鈴推回起始位置。","重複所需次數。"],"0034":["躺在下斜臥推椅上，頭部低於臀部，雙腳固定。","正握抓住槓鈴（掌心朝外），雙臂伸直於胸部上方。","有控制地將槓鈴以弧線降向頭後方，手肘微屈。","停頓片刻，背闊肌與胸肌發力將槓鈴拉回胸前。","重複所需次數。"],"0035":["躺在下斜重訓椅上，頭低腳高，抓穩槓鈴。","手肘彎曲將槓鈴降向前額上方，上手臂維持垂直固定。","停頓片刻，三頭肌發力將雙臂推直回起始位置。","重複所需次數。"],"0036":["躺在下斜椅上，雙腳固定，頭部低於臀部。","寬握距抓握槓鈴，握距略寬於肩。","將槓鈴降向胸部，手肘向兩側自然展開。","將槓鈴推回起始位置，雙臂完全伸展。","重複所需次數。"],"0037":["躺在下斜椅上，頭部低於臀部，雙腳固定。","寬握距握住槓鈴，將雙臂垂直推展於胸部上方。","控制速度將槓鈴向頭後下方放低，手臂微屈打直。","停頓片刻，胸背發力將槓鈴拉回起始位置。","重複所需次數。"],"0038":["雙腳與肩同寬站立，反手握住槓鈴，掌心朝上。","雙臂自然下垂，槓鈴置於大腿前側。","上手臂固定不動，收縮二頭肌將槓鈴彎舉向胸前。","在頂端稍作停頓，慢慢放回。","重複所需次數。"],"0039":["站立雙腳與肩同寬，腳尖微朝外。","槓鈴架在鎖骨前側，手肘抬高向前，雙手與肩同寬。","收緊核心挺胸，屈髖屈膝下蹲成深蹲。","下蹲至大腿平行地面或舒適深度。","底部稍作停頓，踩穩腳跟推回站姿。","重複所需次數。"],"0040":["雙腳與肩同寬站立，正握抓住槓鈴，掌心朝下。","手臂伸直，將槓鈴向前上方平舉至肩高。","頂端停頓片刻，放回大腿前。","接著順勢將槓鈴推舉過頭頂，手臂伸直。","頂端停頓片刻，再有控制地放回大腿前。","重複所需次數。"],"0041":["雙腳分開與肩同寬站立，正握抓槓置於大腿前。","手臂打直，將槓鈴向前上方平舉至肩部高度。","在頂峰停頓片刻，慢慢降回。","重複所需次數。"],"0042":["站立雙腳與肩同寬，腳尖微外展。","槓鈴架在鎖骨與前三角肌上，手肘向上抬平。","挺胸收緊核心，臀部向後坐下蹲進入深蹲。","下蹲至大腿與地面平行或略低。","底部稍作停頓，踩穩腳跟推回站直。","重複所需次數。"],"0043":["站立雙腳與肩同寬，腳尖微朝外。","將槓鈴扛在上背部（斜方肌或三角肌後束）。","下沉時啟動核心，挺胸背打直。","彎曲膝蓋與髖關節，向後坐深蹲。","下蹲至大腿平行地面或略低。","膝蓋與腳尖方向一致，重心維持在腳跟。","踩穩腳跟發力站起，完全展開髖與膝。","重複所需次數。"],"0044":["雙腳與肩同寬站立，槓鈴扛在上背部。","背部打直核心收緊，屈髖將臀部向後推（槓鈴早安式）。","俯身至上半身接近平行地面，感受大腿後側拉伸。","停頓片刻，夾緊臀肌挺髖站回原位。","重複所需次數。"],"0045":["平躺在平凳上，雙腳踩實，背部緊貼椅面。","正握抓住槓鈴，握距略寬於肩寬。","慢慢將槓鈴降向鎖骨與頸部上方（斷頭台臥推），手肘朝外展開。","槓鈴接近頸部時停頓片刻。","胸大肌發力將槓鈴推回正上方。","重複所需次數。"],"0046":["雙腳分開與肩同寬站立，腳尖微外展。","將槓鈴置於身後大腿與臀部下方（哈克深蹲 Hack Squat）。","屈膝屈髖下蹲，挺胸背打直。","蹲至大腿與地面平行或略低。","稍作停頓，踩穩腳跟發力推回站姿。","重複所需次數。"],"0047":["將重訓椅調整至約 45 度上斜角度。","躺在斜椅上，雙腳踩實地面。","正握抓槓，握距略寬於肩。","起槓慢慢降向胸部上方，手肘呈約 45 度。","底部停頓片刻，將槓鈴推回起始位置。","重複所需次數。"],"0048":["重訓椅調整至約 45 度上斜。","躺在椅上，反握抓住槓鈴，握距略寬於肩寬。","起槓慢慢降向上胸部，手肘保持內收。","底部停頓片刻，發力推回。","重複所需次數。"],"0049":["將重訓椅調整至 45 度上斜。","胸部靠在椅背上俯臥趴好，雙腳踩實地面。","正握抓槓，握距略寬於肩。","背部維持挺直，核心收緊。","將槓鈴拉向胸部，肩胛骨向內夾緊。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0050":["將重訓椅調整為 45 度上斜。","背靠椅背坐好，雙腳平踩。","正握抓槓，握距略寬於肩。","將槓鈴置於肩高，手肘微屈。","慢慢將槓鈴推過頭頂，雙臂完全伸展。","頂端停頓片刻，降回肩部。","重複所需次數。"],"0051":["雙腳開立與肩同寬，腳尖微外展。","正握抓住槓鈴置於身前腰部高度。","左腳前跨、右腳後退，站成前後分腿姿勢。","屈膝下沉進入分腿蹲，背部打直挺胸。","腳跟發力蹬起站回起始位置。","交替前腳重複進行。"],"0052":["平躺在平凳上，雙腳踩實，背貼椅面。","正握抓住槓鈴，握距略寬於肩寬。","槓鈴慢慢降向胸部，手肘貼近軀幹。","發力推回起始位置，雙臂完全伸直。","重複所需次數。"],"0053":["雙腳分開與肩同寬站立，槓鈴扛在上背部。","屈膝屈髖向後下蹲成深蹲。","在深蹲底部踩穩腳跟爆發力向上起跳。","展髖、展膝與展踝，前腳掌蹬地騰空。","輕巧落地緩衝隨即沉入深蹲，重複進行。"],"0054":["雙腳與肩同寬站立，槓鈴扛在上背部。","右腳向前跨出一大步，軀幹維持直立。","彎曲右膝下沉至右大腿平行地面。","踩穩右腳跟推回起始站姿。","換左腿前跨重複，雙腿交替進行至所需次數。"],"0055":["平躺在平凳上，雙腳踩實地面。","以窄握距握槓（與肩同寬），掌心朝向腳部。","起槓將槓鈴推至胸部正上方。","慢慢降向胸部，手肘貼緊身側。","輕觸胸口時停頓片刻，發力推回。","重複所需次數。"],"0056":["平躺在平凳上，雙腳踩實，頭枕在凳緣。","窄握抓住槓鈴，掌心朝上。","雙臂完全伸展，槓鈴垂直於胸前。","上手臂維持垂直不動，手肘彎曲將槓鈴降向前額上方（法式推舉/碎顱者）。","底部稍作停頓，伸展手臂推回。","重複所需次數。"],"0057":["平躺在平凳上，雙腳踩實，頭枕在凳端。","正握抓槓鈴與肩同寬，推直於胸口正上方。","上手臂垂直地面固定，彎曲手肘將槓鈴降向前額上方。","停頓片刻，手臂伸直推回。","重複所需次數。"],"0058":["仰臥躺在平凳或地面上，雙膝彎曲雙腳踩實。","槓鈴橫置於髖部上方，雙手抓穩槓鈴。","臀大肌收縮發力，將臀部推離椅面，直到膝、髖、肩成一直線（槓鈴臀推/臀橋）。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0059":["坐在牧師椅上，胸靠支撐墊，手臂向前伸在斜墊上，反握抓住槓鈴。","上手臂維持貼緊斜墊，吐氣將槓鈴向上彎舉向肩膀。","舉至二頭肌完全收縮、槓鈴與肩同高。","頂峰停頓片刻，強力擠壓二頭肌。","吸氣慢慢放回槓鈴。","重複所需次數。"],"0060":["平躺在平凳上，雙腳踩實，頭枕在凳端。","正握抓槓鈴與肩同寬，雙臂伸展於胸前。","上手臂固定不動，手肘彎曲將槓鈴慢慢放至前額上方。","在額頭上方稍作停頓，隨後將手臂向後推展回原位。","重複所需次數。"],"0061":["平躺在平凳上，雙腳踩實，頭枕在椅緣。","正握抓槓鈴與肩同寬，手臂垂直於胸前。","上手臂垂直固定，手肘彎曲將槓鈴降向前額。","底部稍作停頓，三頭肌發力推回。","重複所需次數。"],"0062":["以窄距反握或對握握住槓鈴，從髖部前屈，背部打直。","讓槓鈴自然垂在胸口下方，手臂伸直。","把槓鈴拉向下肋，手肘貼近身體兩側。","在頂端夾緊肩胛骨。","有控制地放下槓鈴，直到手臂伸直。","脖子保持中立，不要用下背猛甩。"],"0063":["雙腳分開與肩同寬站立，腳尖微外展。","槓鈴扛在上背部（斜方肌或三角肌後束）。","收緊核心挺胸，屈膝屈髖向後下蹲。","蹲至大腿平行地面或略低。","底部稍作停頓，踩穩腳跟推回站姿。","重複所需次數。"],"0064":["雙腳與肩同寬站立，膝微屈，單手正握抓住槓鈴中央。","屈髖前傾，背部維持平直，頸椎中立。","手肘引導將槓鈴向上拉向胸腹側，夾緊肩胛骨。","控制速度將槓鈴放回起始位置。","重複所需次數後換手。"],"0065":["仰臥平躺在地面上，雙膝彎曲，雙腳踩實。","單手握住槓鈴中央，掌心朝上，推直於胸前。","慢慢將槓鈴降向胸側，手肘貼近軀幹（地板臥推 Floor Press）。","在底部稍作停頓，推回頂端。","重複所需次數後換手。"],"0066":["雙腳分開與肩同寬站立，單手正握提住槓鈴置於身側（提箱硬舉 Suitcase Deadlift）。","保持背部挺直，核心極力對抗側向傾斜。","屈髖屈膝將槓鈴沿體側下放，手臂打直挺胸。","在維持良好體態的前提下盡可能下沉。","稍作停頓，踩穩腳跟站直回原位。","重複所需次數後換邊。"],"0067":["雙腳與肩同寬站立，腳尖微朝外。","正握抓槓，雙手間距略寬於肩。","屈膝下沉臀部進入深蹲預備姿，背部打直挺胸。","爆發性展髖、展膝與展踝，將槓鈴向上拉起。","槓鈴達胸高時快速翻轉手腕，將槓鈴垂直推過頭頂並鎖定手肘（單臂抓舉）。","控制速度將槓鈴降回。","重複所需次數後換手。"],"0068":["雙腳與肩同寬站立，槓鈴扛在上背部。","單腳向前抬起伸直懸空。","單腿屈膝後坐下沉（槓鈴手槍深蹲），挺胸背打直。","蹲至大腿平行地面，腳跟推地站回。","重複所需次數後換腿。"],"0069":["雙腳分開與肩同寬站立，腳尖微朝外。","寬握抓槓將槓鈴推舉過頭頂，手臂完全伸直鎖定（過頭深蹲 Overhead Squat）。","收緊核心，下蹲進入深蹲，維持胸部挺起、槓鈴維持在腳心垂直上方。","底部稍作停頓，腳跟推地站回。","重複所需次數。"],"0070":["坐在牧師椅上，上手臂貼墊，胸部靠著支撐板。","反握抓住槓鈴，握距略寬於肩。","上手臂固定不動，吐氣將槓鈴向上彎舉向肩膀。","頂端停頓片刻，擠壓二頭肌。","吸氣慢慢放回槓鈴。","重複所需次數。"],"0071":["平躺在墊子上，雙膝彎曲雙腳踩地。","正握抓槓鈴置於胸前。","腹肌發力將上半身捲離地面至 45 度（負重捲腹）。","頂端稍作停頓，慢慢降回。","重複所需次數。"],"0072":["重訓椅調整至 45 度上斜。","胸腹貼緊椅背俯臥趴好。","反握抓槓，握距與肩同寬。","手臂自然下垂伸展，槓鈴垂直垂向地板。","上手臂固定，吐氣彎舉槓鈴收縮二頭肌（蜘蛛彎舉）。","舉至槓鈴與肩同高，頂端稍作停頓。","吸氣慢慢放回。","重複所需次數。"],"0073":["平躺在平凳上，雙腳踩實地面。","握距與肩同寬抓槓，雙臂垂直推展於胸口上方。","保持手臂微屈伸展，有控制地將槓鈴降向頭頂後方，直到感受背闊肌拉伸（仰臥套頭）。","停頓片刻，背肌與胸肌發力將槓鈴拉回胸前。","重複所需次數。"],"0074":["深蹲架上將槓鈴調至膝蓋高度（架上拉 Rack Pull）。","雙腳分開與肩同寬站立，腳尖微朝外。","屈髖屈膝俯身，正握抓槓，握距略寬於肩。","伸膝展髖發力拉起槓鈴，雙肩後展，頂峰夾緊臀部。","屈髖將槓鈴穩穩放回安全槓架上。","重複所需次數。"],"0075":["雙腳分開與肩同寬站立，正握抓槓，掌心朝下。","膝微屈，屈髖前傾，背部維持打直。","手臂打直，將槓鈴向兩側舉起至平行地面。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0076":["雙腳與肩同寬站立，膝蓋微彎。","正握抓槓，握距略寬於肩寬。","屈髖前傾，背部打直挺胸。","將槓鈴拉向胸前，肩胛骨向內用力夾緊（俯身槓鈴划船）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"0077":["雙腳分開與肩同寬站立，槓鈴扛在上背部。","右腳向後退一大步成反向弓箭步。","雙膝彎曲下沉至左大腿平行地面。","踩穩左腳跟推回站姿。","換另一條腿重複。"],"0078":["雙腳與肩同寬站立，槓鈴扛在上背部。","右腳向後退一步，前腳掌點地。","彎曲雙膝下沉身體，直到左大腿平行地面（反向弓箭步）。","踩穩左腳跟蹬回起始位置。","換另一條腿重複。"],"0079":["坐在重訓椅上，雙腳平放，膝蓋彎曲。","正握抓槓鈴，掌心朝下，雙手與肩同寬。","前臂平放在大腿上，手腕懸空於膝蓋外。","前臂固定不動，吐氣將手腕向上屈起至極限。","在頂點停留片刻，吸氣慢慢放回。","重複所需次數。"],"0080":["站直雙腳與肩同寬，正握抓住槓鈴，掌心朝下（反向槓鈴彎舉）。","上手臂維持貼緊身側固定，吐氣將槓鈴向上彎舉向肩膀。","舉至二頭肌與前臂完全收縮。","頂峰停頓片刻，用力擠壓。","吸氣慢慢將槓鈴放回起始位置。","重複所需次數。"],"0081":["坐在牧師椅上，胸貼支撐墊，雙臂向前伸展，正握抓住槓鈴（掌心朝下）。","上手臂固定在斜墊上，吐氣將槓鈴向上彎舉向肩膀。","舉至頂端完全收縮，停留片刻。","吸氣慢慢將槓鈴降回。","重複所需次數。"],"0082":["坐在重訓椅上，雙腳踩實，正握抓槓，掌心朝下。","前臂平貼在大腿上，手腕懸空。","手腕向上屈起，將槓鈴抬高。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0083":["雙膝跪在地面，將槓鈴置於身前的重訓椅面上。","正握抓槓，握距略寬於肩。","核心收緊背打直，慢慢向前推滾槓鈴。","滾動至身體完全伸展，手臂舉過頭頂。","在完全伸展點停留片刻，慢慢拉回身前。","重複所需次數。"],"0084":["雙膝跪在地板上，雙手間距與肩同寬正握槓鈴兩側。","向前推滾槓鈴，手臂伸展，核心強烈收縮緊繃。","持續向前推滾，直到身體完全伸展成一直線（槓鈴滾輪滾出 Barbell Rollout）。","停頓片刻，腹肌與背肌發力將槓鈴拉回膝蓋前方。","重複所需次數。"],"0085":["站立雙腳與肩同寬，腳尖朝前。","正握抓槓，握距略寬於肩。","屈髖將臀部向後推，背部平直，膝微屈（羅馬尼亞硬舉 RDL）。","將槓鈴沿著大腿小腿向下放，感受大腿後側拉伸。","感受到極限拉伸後，腳跟推地向前挺髖站直。","頂端用力夾緊臀部。","重複所需次數。"],"0086":["坐在重訓椅上，背部挺直，雙腳平踩。","正握抓槓，握距略寬於肩。","起槓將槓鈴降至頸後肩部高度。","向上推舉槓鈴直到手臂完全伸直。","慢慢降回頸後起始高度。","重複所需次數。"],"0087":["坐在重訓椅上，背部挺直雙腳踩實。","正握抓槓，握距略寬於肩寬。","槓鈴提至鎖骨前肩部高度，手肘微朝前。","將槓鈴垂直推過頭頂，雙臂完全伸展。","慢慢降回肩部高度，重複所需次數。"],"0088":["坐在重訓椅上，槓鈴置於大腿近膝處，雙腳踩實。","前腳掌踩在踏台或槓片上，腳跟完全懸空。","手扶好槓鈴維持穩定。","小腿發力蹬起腳踝，盡可能抬高腳跟（坐姿提踵）。","頂峰停頓片刻，慢慢放低腳跟。","重複所需次數。"],"0089":["坐在重訓椅上，反握抓槓，握距與肩同寬。","上手臂靠在大腿內側近膝處，槓鈴垂在身前。","上手臂固定不動，吐氣將槓鈴向上彎舉至肩部。","頂峰停頓片刻收縮二頭肌，吸氣慢慢放回。","重複所需次數。"],"0090":["坐在重訓椅上，槓鈴扛在上背部，雙腳踩實。","背部維持打直挺胸。","慢慢以臀部為軸心向前屈髖俯身（坐姿早安式）。","底部停頓片刻，臀背發力挺身回原位。","重複所需次數。"],"0091":["坐在重訓椅上，背部挺直，雙腳平踩。","正握抓槓，握距略寬於肩寬。","槓鈴起槓置於肩前，掌心朝前。","雙臂完全伸展，將槓鈴推過頭頂。","頂端停留片刻，慢慢放回肩部。","重複所需次數。"],"0092":["坐在重訓椅上，背部打直雙腳踩實。","正握抓槓，雙手與肩同寬，將槓鈴推過頭頂。","手肘彎曲將槓鈴降向後頸，上手臂靠近頭部。","停頓片刻，雙臂向上推展伸直回頂端。","重複所需次數。"],"0093":["坐在健身球上，槓鈴橫放在上背，雙腳打開。","坐直，核心收緊。","髖部不動，上身轉向一側。","轉回正中。","再轉向另一側。","動作保持緩慢、有控制。"],"0094":["坐在平凳上，雙腳踩平雙膝微彎。","雙手持槓鈴於胸前，手肘微屈。","啟動核心，慢慢將軀幹向一側旋轉，背部打直。","轉體到底停頓片刻，慢慢旋轉回正。","換向另一側旋轉重複。","交替進行至所需次數。"],"0095":["雙腳分開與肩同寬站立，正握抓槓鈴。","手臂伸直，背部維持平直。","雙肩垂直向上聳向耳朵，在最高點擠壓斜方肌（槓鈴聳肩 Barbell Shrug）。","維持收縮片刻，慢慢放回肩膀。","重複所需次數。"],"0096":["雙腳與肩同寬站立，手持槓鈴垂於大腿前。","全程背部挺直，核心收緊。","慢慢將軀幹向右側屈，槓鈴向右膝下滑動。","停頓片刻，拉回正中。","換向左側屈重複。","交替進行至所需次數。"],"0097":["站立雙腳開立寬於肩，腳尖微朝外。","槓鈴扛在上背部。","右腳向側邊跨出一大步，左腳踩平地面。","屈右膝下沉進入側深蹲，挺胸背打直。","右腳跟蹬地推回站姿。","換左腳向左跨出重複。","交替進行至所需次數。"],"0098":["站立雙腳開立寬於肩寬，腳尖朝外（相撲深蹲）。","槓鈴扛在上背部斜方肌上。","收緊核心挺胸，屈膝屈髖向後下蹲。","下蹲時雙膝向兩側推開，重心維持在腳跟。","蹲至大腿平行地面，腳跟蹬地推回站姿。","重複所需次數。"],"0099":["雙腳與肩同寬站立，槓鈴扛在上背部。","單腿向前跨出一大步成弓箭步，軀幹維持直立。","前膝屈曲下沉，後腿微屈打直。","下沉至前大腿平行地面。","停頓片刻，前腳跟蹬地推回站姿。","換腿重複操作。"],"0100":["雙腳與肩同寬站立，正握抓槓置於大腿前。","膝微屈，屈髖前傾，挺胸背打直。","爆發力展髖蹬腿將槓鈴向上提拉至胸肩處，腳後跟微離地（高拉 High Pull）。","達最高點後迅速順勢降回大腿前。","重複所需次數。"],"0101":["站立雙腳與肩同寬，腳尖微外展。","槓鈴扛在上背部斜方肌上。","收緊核心挺胸，臀部向後坐深蹲。","蹲至大腿與地面平行或略低。","腳跟發力站直，頂峰夾緊臀部。","重複所需次數。"],"0102":["跪姿於地面，雙膝與臀同寬，腳尖朝後。","槓鈴扛在肩膀上，正握抓槓略寬於肩。","收緊核心挺胸，屈膝向後下沉臀部（跪姿深蹲 Kneeling Squat）。","下沉至大腿與地面平行或接近腳跟。","停頓片刻，臀大肌收縮挺髖回頂端。","重複所需次數。"],"0103":["站直雙腳與肩同寬，手持槓鈴置於大腿前。","收緊核心，慢慢將槓鈴向下向前推滾（站姿滾輪進階式）。","身體完全向前展開延伸，直到手臂舉過頭頂。","稍作停頓，腹肌與背肌發力將槓鈴拉回身前站直。","重複所需次數。"],"0104":["站直雙腳與肩同寬，雙手在身後抓握槓鈴（身後腕彎舉 Behind-the-back Wrist Curl）。","槓鈴置於指尖，掌心朝後。","上手臂維持不動，吐氣將手腕向上屈起捲槓。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0105":["雙腳與肩同寬站立，正握抓槓置於鎖骨前。","雙臂完全伸展，將槓鈴推過頭頂（肩推 Overhead Press）。","有控制地將槓鈴降回鎖骨起始高度。","重複所需次數。"],"0106":["站直雙腳與肩同寬，反手窄握抓住槓鈴（兩手間距約一拳）。","手肘貼緊軀幹，上手臂固定不動。","吐氣彎舉槓鈴收縮二頭肌，舉至槓鈴與肩同高。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢放回槓鈴。","重複所需次數。"],"0107":["雙腳與肩同寬站立，正握抓槓置於大腿前。","背打直核心收緊。","雙臂伸直，慢慢將槓鈴向前上方平舉至肩高以上。","頂端停頓片刻，慢慢降回大腿前。","重複所需次數。"],"0108":["雙腳與肩同寬站立，槓鈴扛在上背部。","小腿發力將腳跟盡可能抬高，前腳掌點地（站姿槓鈴提踵）。","頂峰停頓片刻，慢慢降回腳跟。","重複所需次數。"],"0109":["雙腳與肩同寬站立，正握抓槓。","將槓鈴推過頭頂，手臂伸展。","上手臂貼近頭側，手肘彎曲將槓鈴降向後腦勺下方。","停頓片刻，三頭肌發力推回頭頂。","重複所需次數。"],"0110":["站直雙腳與肩同寬，反手抓槓，掌心朝上。","手肘貼緊身側，上手臂固定。","吐氣將槓鈴向上彎舉向肩膀，盡可能收縮二頭肌。","頂端停留片刻，強力擠壓。","吸氣慢慢放回。","重複所需次數。"],"0111":["雙腳與肩同寬站立，槓鈴扛在上背部。","盡可能將腳跟抬離地面，用前腳掌維持平衡。","慢慢放低腳跟回地面。","重複所需次數。"],"0112":["雙腳與肩同寬站立，雙手在胸前握槓鈴，掌心朝下。","收緊核心背部打直。","以腳踝與髖為軸心，慢慢將軀幹向右旋轉。","轉體到底停頓片刻，回到中央。","換向左旋轉重複。","交替進行至所需次數。"],"0113":["站直雙腳與肩同寬，正握寬握抓槓，握距明顯寬於肩。","雙臂伸展槓鈴垂於大腿前。","上手臂固定不動，吐氣收縮二頭肌向上彎舉槓鈴。","舉至二頭肌完全收縮、槓鈴與胸同高。","頂峰停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0114":["站在踏台或長凳前，槓鈴扛在上背部。","單腳踏上踏台，確保全腳掌踩實。","踩穩腳跟蹬起身體，完全展開髖與膝站直在台上。","在頂峰短暫站穩，然後原腳退回地面。","換另一腿踏上重複。","雙腿交替進行至所需次數。"],"0115":["雙腳與肩同寬站立，膝蓋微彎。","槓鈴扛在斜方肌上。","背部維持平直，屈髖將臀部向後推。","俯身至上半身接近平行地面，感受大腿後側拉伸（早安式）。","臀肌與腿後肌群發力挺身站回。","重複所需次數。"],"0116":["站立雙腳與肩同寬，腳尖朝前。","正握抓槓，握距略寬於肩。","屈髖俯身將槓鈴沿腿下放，背部打直膝微彎。","降至感受大腿後側緊繃拉伸。","臀肌與腿後腱發力將槓鈴拉回站姿。","重複所需次數。"],"0117":["站立雙腳開立寬於肩寬，腳尖外展約 45 度（相撲硬舉 Sumo Deadlift）。","槓鈴置於雙腳之間的地面。","屈髖下蹲，背部打直挺胸，雙手在雙腿內側正握抓住槓鈴。","核心收緊，腳跟推地蹬直雙腿，槓鈴貼身拉起。","站直時向前挺髖，強力收緊臀大肌。","頂端停頓片刻，有控制地屈髖屈膝放回地面。","重複所需次數。"],"0118":["雙腳與肩同寬站立，膝微屈。","正握抓住槓鈴，掌心朝下，握距略寬於肩。","屈髖前傾挺胸背打直，直到軀幹幾乎平行地面。","肩胛後收夾緊，將槓鈴拉向下胸部/肚臍。","頂峰停留片刻，慢慢放回。","重複所需次數。"],"0119":["雙腳分開與肩同寬站立，正握抓槓，握距略寬於肩寬。","槓鈴垂在大腿前，雙臂伸展。","背部打直，吐氣將槓鈴向上提拉至下巴高度，手肘帶動。","頂端停頓片刻，吸氣慢慢降回。","重複所需次數。"],"0120":["雙腳與肩同寬站立，正握抓槓，握距略寬於肩寬。","槓鈴垂於大腿前方，雙臂伸展。","背部挺直核心收緊，吐氣以手肘引導向上提拉槓鈴至鎖骨高度（槓鈴直立划船）。","手肘始終高於手腕，在頂峰停頓片刻。","吸氣慢慢降回大腿前。","重複所需次數。"],"0121":["雙腳與肩同寬站立，正握抓槓，握距略寬於肩寬。","槓鈴自然垂在大腿前。","核心收緊背打直，吐氣將槓鈴向上提拉至胸前，手肘朝外展開。","頂峰停頓片刻，吸氣緩緩降回。","重複所需次數。"],"0122":["平躺在平凳上，雙腳踩實，背部緊貼椅面。","寬握距抓握槓鈴，握距明顯寬於肩寬（寬握臥推）。","起槓將槓鈴推至胸部正上方。","慢慢將槓鈴降向胸部，手肘自然展開。","輕觸胸部時停頓片刻，發力推回頂端。","重複所需次數。"],"0123":["雙腳分開與肩同寬站立，正握抓槓，握距寬於肩。","雙臂伸直將槓鈴垂在大腿前。","背打直，吐氣以手肘引領向上提拉槓鈴至胸高。","頂端停留片刻，吸氣慢慢放回。","重複所需次數。"],"0124":["雙腳開立寬於肩寬，腳尖微外展。","槓鈴扛在上背部斜方肌上。","挺胸收腹，屈膝屈髖下蹲成相撲深蹲。","下蹲至大腿平行地面或略低。","底部稍作停頓，踩穩腳跟推回站姿。","重複所需次數。"],"0125":["坐在重訓椅上，雙腳踩實，反手抓槓（掌心朝上），握距與肩同寬。","前臂平放在大腿上，手腕懸空。","手腕向上屈起，將槓鈴捲向前臂。","頂峰停頓片刻，慢慢放回。","重複所需次數。"],"0126":["坐在重訓椅上，前臂平放在大腿上，反手抓槓。","手腕放鬆讓槓鈴順勢向下滾動至指尖（槓鈴指屈伸）。","手指發力收攏捲回掌心，隨後手腕向上屈起將槓鈴捲向前臂。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0127":["雙腳分開與肩同寬站立，腳尖微外展。","將槓鈴夾在雙手手肘內彎處（澤奇深蹲 Zercher Squat），雙手互握抓穩。","挺胸收腹，屈髖後坐進入深蹲。","維持膝蓋對齊腳尖方向，重心落在腳跟。","深蹲底部稍作停頓，踩穩腳跟蹬起回站姿。","重複所需次數。"],"0128":["雙腳分開與肩同寬站立，膝蓋微屈。","雙手各握戰繩一端，掌心相對。","雙臂抬至腰肩之間，手肘微屈。","雙手交替快速上下拍打，使戰繩形成持續起伏的交替波浪（戰繩交替波浪 Battle Rope Waves）。","持續進行至指定時間或次數。"],"0129":["坐在重訓椅或椅子邊緣，雙手抓緊臀部兩側椅緣。","臀部滑出椅面，雙腿向前伸直，腳跟著地。","手肘彎曲下沉身體貼近長凳。","底部停頓片刻，手臂推直將自己撐回頂端（椅子撐體）。","重複所需次數。"],"0130":["背靠在重訓椅邊緣，雙腳踩實地面。","雙手扶在長凳兩側支撐。","夾緊臀肌與腿後腱，將骨盆推離地面直到軀幹與大腿成一直線（反向臀推）。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0131":["上背靠在健身球上仰躺，雙膝彎曲呈 90 度。","雙臂向兩側平伸以維持平衡。","將膝蓋與髖部慢慢轉向一側。","稍微停頓一下。","帶回中間，再轉向另一側。","保持雙肩平穩朝向天花板。"],"0133":["側躺並彎曲雙膝，手肘置於肩膀正下方。","讓兩側髖部與膝蓋上下疊齊。","抬起髖部，使身體從膝蓋到頭部呈一直線。","維持 20-30 秒。","有控制地放下髖部。","換邊重複動作。"],"0134":["從屈膝伏地挺身姿勢開始，雙手置於肩膀正下方。","將膝蓋與髖部稍微轉向一側。","手肘張開約 45 度，將胸口放低至貼近地面。","推回起始位置。","保持核心收緊，避免髖部下榻。","組與組之間換邊轉動膝蓋。"],"0136":["坐在地板上，雙膝彎曲，腳掌平貼地面。","身體微微後傾，同時保持挺胸。","雙腳離地，如果可以就將雙腿伸直。","雙臂沿著膝蓋兩側向前平伸。","維持 20-30 秒，保持平穩呼吸。","輕輕放下雙腳休息。"],"0137":["雙手撐在上斜雙槓或高平台上，掌心朝下手指朝前。","雙腿向前伸展打直，腳跟踩地，身體成一直線。","手肘微收彎曲降下身體，直到上手臂平行地面。","停頓片刻，手掌發力推直手臂撐回頂端。","重複所需次數。"],"0138":["平躺在地上，雙腿伸展，手臂放身側。","雙膝彎曲抬腿懸空，使雙腳離地。","腹肌發力收緊，將臀部捲離地面朝向頭部（仰臥反向捲腹）。","頂端停頓片刻，慢慢放回臀部。","重複所需次數。"],"0139":["雙手反握（掌心朝向自己）抓單槓，握距與肩同寬（反手引體向上 Chin-up）。","啟動核心，二頭肌與背肌發力將身體拉向單槓。","頂端下巴過槓停頓片刻，慢慢降回懸掛。","重複所需次數。"],"0140":["正握抓單槓，雙手與肩同寬，掌心朝外。","啟動核心，屈肘挺胸將身體拉向單槓。","頂端停頓片刻，控制速度緩緩降回。","重複所需次數。"],"0142":["跪在瑜珈墊上，身體前傾靠在前臂上。","將手肘對齊肩膀正下方。","抬起髖部，使身體從膝蓋到頭部呈一直線。","收緊腹肌並夾緊臀肌。","維持 20-30 秒。","輕輕放下身體休息。"],"0143":["從雙手置於肩膀正下方的高棒式開始。","雙腿向後伸直，腳尖踩地。","夾緊臀肌並收緊腹肌。","保持身體呈一直線。","維持 20-30 秒。","放下膝蓋休息。"],"0145":["仰躺在地面，雙膝彎曲，雙腳平踩且與髖部同寬。","雙臂放在身體兩側。","腳跟踩地發力，將髖部朝天花板方向抬起。","在頂點夾緊臀肌。","慢慢放低回到地面。","保持肋骨下壓，避免下背過度拱起。"],"0147":["仰躺，雙手扶在腦後，雙腿抬起。","一側膝蓋帶向胸口，同時轉動身體讓對側手肘碰觸膝蓋。","另一腿則向前伸直。","像踩腳踏車一樣交替換邊。","保持下背貼緊地面。","以穩定節奏動作，不要硬拉脖子。"],"0148":["雙腳與肩同寬站立，正握抓滑輪機雙把手。","雙手維持在胸肩高度，掌心朝前。","核心收緊背打直。","單臂向前推直把手，手臂完全伸展。","頂端停留片刻，慢慢放回肩前。","換另一手推展，雙手交替進行至指定次數。"],"0149":["面對滑輪機站立，雙腳與肩同寬。","右手抓滑輪握把，抬起手臂使上手臂平行地面，手肘呈 90 度。","上手臂固定不動，前臂向後推直伸展（滑輪三頭後屈伸）。","停頓片刻，慢慢放回 90 度。","換左手重複，雙手交替進行至所需次數。"],"0150":["高位滑輪調高並安裝下拉直桿。","坐在坐墊上面向機台，雙腳踩實，膝微彎。","正握抓槓，握距略寬於肩寬。","身體微後傾挺胸，下背自然微弓。","手肘引導將直桿向下拉向鎖骨胸前，肩胛骨向內夾緊。","底部停頓片刻，慢慢送回直桿。","重複所需次數。"],"0151":["滑輪調至胸部高度並接上握把。","背對滑輪機站立，雙腳與肩同寬。","正握抓把手向前邁步拉出張力。","雙腳踩穩，收緊核心。","手肘屈曲呈 90 度將雙手置於胸前。","向前推展把手，雙臂完全在身前伸直。","停頓片刻，控制速度慢慢收回胸前。","重複所需次數。"],"0152":["坐在椅子上，膝蓋彎曲雙腳平踩。","右手抓滑輪握把，右肘抵在右大腿內側（滑輪集中彎舉）。","完全伸展手臂，上手臂固定不動。","頂端收縮二頭肌停頓片刻，慢慢降回。","重複所需次數後換手。"],"0153":["雙側滑輪把手安裝在肩部高度。","站在機台正中央，雙腳與肩同寬。","正握把手後退拉出張力。","屈髖微前傾，背部打直挺胸。","手肘微彎，雙手向下拉過身前交叉夾胸。","底部停頓片刻，慢慢張開回起始位置。","重複所需次數。"],"0154":["D 型握把接在低滑輪上，站在交叉滑輪機中央。","掌心朝下抓住握把，向前邁出一步，雙腳與肩同寬。","膝微屈，屈髖前傾，背部打直收腹。","手肘微屈，雙臂向兩側斜後方拉開夾緊肩胛骨（低位滑輪反向飛鳥）。","頂峰收縮停留片刻，吸氣慢慢放回。","重複所需次數。"],"0155":["滑輪調至胸部高度。","站在滑輪機中央，採前後弓箭步站姿。","掌心朝下抓住把手，手臂向兩側展開。","往前跨一步拉出張力，手肘微屈。","胸大肌發力將雙手向胸前合攏夾胸（站姿滑輪夾胸 Cable Flye）。","稍作停頓，慢慢張開手臂回原位。","重複所需次數。"],"0157":["面對滑輪機站立，雙腳與肩同寬。","屈髖屈膝俯身，軀幹接近平行地面。","正握抓滑輪把手，手臂伸展，雙肩後展。","臀肌與腿後腱發力拉起滑輪，挺髖站直（滑輪硬舉 Cable Deadlift）。","頂端停頓片刻，慢慢放回地面高度。","重複所需次數。"],"0158":["滑輪調至低位。","背對機台站立，雙腳與肩同寬。","抓握把手掌心朝前，雙臂伸於身前。","手肘微彎，有控制地向兩側張開雙臂。","完全拉開時停頓片刻，胸肌發力夾回身前。","重複所需次數。"],"0159":["坐在下斜板上面向滑輪機，雙腳踩在固定架上。","寬握正手抓把手，掌心朝下。","身體微後傾，背部挺直核心收緊。","將滑輪拉向下胸部，肩胛骨向內夾緊。","頂端停留片刻，慢慢送回。","重複所需次數。"],"0160":["坐在地板上，雙腿伸直，背部挺直。","低位滑輪接上長把手，放在身後。","寬握抓把手，掌心朝下。","身體微後傾，挺胸背平。","將把手拉向腰間，肩胛骨夾緊。","頂端停頓片刻，慢慢送回。","重複所需次數。"],"0161":["雙腳分開與肩同寬站立，膝蓋微屈。","正握抓滑輪把手，掌心朝下，雙臂在身前伸直。","手臂打直，將滑輪向上平舉至肩部高度（滑輪前平舉）。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0162":["雙腳與肩同寬站立，正握抓住滑輪把手。","背部維持打直，核心收緊。","雙臂伸直將滑輪把手向前平舉，掌心朝下。","平舉至手臂平行地面。","頂端停頓片刻，緩慢降回。","重複所需次數。"],"0163":["坐在滑輪划船機上，雙腳踩穩踏板，雙膝微彎。","雙手握住握把，挺直身體坐好。","將握把拉向下肋骨，同時將肩胛骨向內夾緊。","在末端稍微停頓一下。","慢慢放回，直到雙臂伸直。","保持挺胸，避免身體前後搖晃。"],"0164":["雙腳分開與肩同寬站立，正握抓把手。","背部打直，啟動核心。","雙臂打直將把手向前平舉，掌心朝下。","平舉至手臂平行地面。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0165":["站直雙腳與肩同寬，膝微屈。","抓住纜繩配件，掌心相對，手臂完全伸展。","上手臂固定不動，吐氣彎舉把手收縮二頭肌（滑輪錘式彎舉）。","舉至繩索與肩同高，頂峰擠壓二頭肌。","吸氣慢慢放回。","重複所需次數。"],"0166":["將繩索或握把裝在低位滑輪上，掌心相對握住。","站直身體，手肘貼近身體兩側。","將握把朝肩膀方向彎舉上來。","在頂點收緊肌肉。","慢慢放下，直到雙臂伸直。","保持上臂固定不動，避免甩動身體。"],"0167":["直桿接在胸部高度的滑輪機上。","跪在滑輪機前，正握抓直桿，雙手與肩同寬。","坐於腳跟上，背部挺直核心收緊。","將直桿拉向上腹部，肩胛骨向內夾緊。","頂峰停頓片刻，慢慢送回直桿。","重複所需次數。"],"0168":["腳踝套套在腳踝上，側面或面向滑輪機站立。","離機台適當距離使纜繩保持緊繃。","手扶機台維持平衡。","腿部伸直，慢慢將單腿向身體中線內收拉動（滑輪髖內收）。","動作末端停頓片刻，慢慢放回。","重複所需次數後換腳。"],"0169":["將重訓椅調整為 45 度上斜。","把手接在高滑輪上。","坐在椅上面向滑輪機，雙腳平踩。","正握抓把手提至肩前。","向前上方推發展手臂（上斜滑輪推胸）。","停頓片刻，慢慢降回肩部。","重複所需次數。"],"0170":["將抗力球斜靠在重訓椅上。","把手接在高位滑輪上。","背對機台坐在抗力球上，雙腳踩實地面。","正握抓住滑輪把手，掌心朝前。","微向前傾挺胸，核心收緊。","手肘微屈，慢慢將手臂向兩側展開至平行地面。","停頓片刻，胸肌收縮夾回身前。","重複所需次數。"],"0171":["滑輪調至低位並接上單把手。","坐在上斜重訓椅上，背靠椅背，雙腳踩實。","正握抓把手，雙臂伸於胸前。","手肘微彎，控制著向兩側張開手臂（上斜滑輪飛鳥）。","展開到底停頓片刻，胸肌發力夾回胸前。","重複所需次數。"],"0172":["將直桿接在高滑輪上。","背對滑輪機站立，雙腳與肩同寬。","正握抓直桿，雙手間距略寬於肩。","微向前傾，背部維持平直。","伸展手肘將直桿向下拉向大腿（高位滑輪三頭下壓/直臂下拉）。","底部停頓片刻，慢慢送回。","重複所需次數。"],"0173":["將直桿接在低滑輪機上。","背對機台站立，雙腳與肩同寬。","正握抓桿並將手臂舉過頭頂。","微向前傾挺胸，核心收緊。","手肘彎曲將直桿降向後腦勺，上手臂靠近耳側。","停頓片刻，手臂向上伸展推直（滑輪過頭三頭伸展）。","重複所需次數。"],"0174":["面對滑輪機站立，雙腳與肩同寬。","雙手在胸前抓握滑輪把手，掌心朝下。","收緊核心將軀幹向右旋轉，拉動纜繩橫跨身體。","轉體時轉動後腳前腳掌，髖部自然順轉。","雙臂完全伸展拉動滑輪至對側肩膀（滑輪伐木轉體 Cable Woodchopper）。","反向動作慢慢旋轉回正。","換向另一側重複。","雙側交替進行至所需次數。"],"0175":["繩索把手接在高滑輪上，背對滑輪機跪姿。","雙手抓住繩索放於後腦勺兩側，手肘展開。","骨盆固定，腹肌發力向下彎曲軀幹，捲腹使手肘貼向大腿（高位滑輪跪姿捲腹）。","底部停頓片刻，慢慢放回。","重複所需次數。"],"0176":["繩索接在高滑輪上，面向機台跪姿。","對握抓緊繩索兩端置於頭側。","手肘貼近頭部固定，上手臂不動。","收縮三頭肌將前臂向下推直伸展。","停頓片刻，慢慢屈肘放回。","重複所需次數。"],"0177":["繩索配件安裝在滑輪機高位。","面對機台站立，雙腳分開與肩同寬。","正握抓繩索，掌心相對。","背打直微向後仰。","手肘向下向外拉，將繩索拉向臉部/頸部兩側（滑輪面拉 Face Pull）。","動作末端夾緊肩胛骨停留片刻。","緩慢釋放張力送回。","重複所需次數。"],"0178":["雙腳與肩同寬站立，正握抓住滑輪把手。","手臂維持打直，核心收緊。","將手臂向兩側平舉至平行地面（滑輪側平舉）。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0179":["低滑輪接上握把，站在機台中央，雙腳與肩同寬膝微屈。","正握抓把手，雙臂向兩側展開，手肘微屈。","胸大肌發力將雙手向前上方呈大弧線收攏交叉（低位滑輪夾胸）。","動作頂峰感受胸肌收縮停頓片刻。","控制速度慢慢張開手臂回到原位。","重複所需次數。"],"0180":["坐在划船機上，雙腳踩在腳踏板上，膝蓋微彎。","正握抓住把手，掌心朝下。","背部挺直，微向前傾，手肘微屈。","將把手拉向軀幹，肩胛骨向內用力夾緊。","頂端停留片刻，慢慢送回把手。","重複所需次數。"],"0181":["在低位滑輪裝上短桿，仰躺在地面，雙腳朝向配重片。","以窄距反握抓握短桿，雙臂伸直。","保持上臂固定不動，將短桿朝肩膀方向彎舉。","在頂點收緊二頭肌停頓一下。","慢慢放下短桿，直到雙臂再次伸直。","不要讓手肘離開身體兩側。"],"0182":["直桿接在低滑輪機上。","仰臥躺在平凳上，雙腳踩實地面。","反握抓住直桿，雙手與肩同寬。","雙臂伸展，手肘貼緊身側。","上手臂固定不動，二頭肌發力將直桿向上彎舉向胸前。","頂端停頓片刻，擠壓二頭肌。","慢慢放回直桿，完全伸展雙臂。","重複所需次數。"],"0183":["仰躺在墊子上，頭部朝向低位滑輪，雙手在頭頂上方握住短桿。","從雙臂伸直的姿勢開始。","將短桿朝額頭或胸口方向彎舉。","在頂點收緊二頭肌。","有控制地放回，直到手臂完全伸直。","保持手肘朝上，背部平貼地面。"],"0184":["繩索接在滑輪機最高位。","平躺在平凳上，頭朝向滑輪機。","雙手握住繩索，雙臂垂直推展於胸前。","雙臂打直微屈，有控制地將繩索向頭頂後方放低（仰臥套頭）。","底部停頓片刻，胸背發力拉回胸前。","重複所需次數。"],"0185":["把手接在滑輪上，平躺在重訓椅上，雙腳踩實。","掌心相對抓握把手，雙臂伸於胸口正上方。","手肘微彎，向兩側呈大弧線展開放低，直到感受胸肌拉伸（仰臥滑輪飛鳥）。","停頓片刻，胸肌發力夾回正上方。","重複所需次數。"],"0186":["繩索接在低滑輪機上。","仰臥躺在平凳上，頭朝向滑輪機。","雙手對握抓繩索兩端，伸直於胸前。","上手臂垂直固定，手肘彎曲將繩索降向前額上方。","底部停頓片刻，三頭肌發力推回。","重複所需次數。"],"0187":["將低位滑輪裝上直桿或繩索，仰躺在長凳上，頭部靠近配重片。","雙手握住握把，雙臂在胸口上方伸直。","保持上臂固定不動，只彎曲手肘將握把朝額頭方向放低。","等到前臂超過與地面平行的位置時稍微停頓。","伸直雙臂將握把推回上方。","保持手肘朝向天花板，不要往外張開。"],"0188":["雙側滑輪調至胸部高度。","站在機台中央，採前後弓箭步站姿。","正握抓握把，手臂向兩側展開。","手肘微屈，身體微前傾。","胸肌發力將雙手向前合攏（滑輪夾胸）。","頂端稍作停頓，慢慢張開回原位。","重複所需次數。"],"0189":["面對滑輪機站立，雙腳與肩同寬。","膝微屈，屈髖前傾，背部打直。","單手抓握滑輪把手，掌心朝內，手臂向前伸展。","手肘貼緊身側，將把手拉向腰腹側邊。","停頓片刻，慢慢送回手臂。","重複所需次數後換手。"],"0190":["面對滑輪機站立，雙腳與肩同寬。","反手抓滑輪握把，掌心朝上。","手肘貼緊身側，前臂向上彎舉至肩前。","頂峰停頓片刻，慢慢放回。","重複所需次數。"],"0191":["雙腳分開與肩同寬站立，面向滑輪機。","單手抓把手後退拉出張力。","屈髖前傾，背打直核心收緊。","單臂向側邊展開至平行地面，手肘微屈（單臂俯身飛鳥）。","慢慢將手臂放回身前。","重複所需次數後換邊。"],"0192":["雙腳與肩同寬站立，側向面向滑輪機。","單手持把手掌心朝下，拉出張力。","手臂打直，向外側平舉至平行地面（單臂滑輪側平舉）。","頂端稍作停頓，慢慢放回。","重複所需次數後換邊。"],"0193":["把手接在腰部高度的滑輪機上。","面向滑輪機單膝跪地，單手抓把手。","背打直核心收緊。","手肘貼身將把手拉向胸肋側邊，肩胛骨夾緊。","頂端停留片刻，慢慢放回。","重複所需次數後換手。"],"0194":["繩索接在高位滑輪上。","背對滑輪機站立，雙腳與肩同寬。","對握抓繩索高舉過頭。","上手臂貼近耳側，手肘朝前。","手肘彎曲將繩索降向後腦勺。","停頓片刻，三頭肌發力推回頭頂。","重複所需次數。"],"0195":["滑輪與牧師椅斜墊調至胸部高度。","坐在牧師椅上，上手臂貼墊，反手抓滑輪配件。","背打直手肘固定在墊上。","慢慢將把手向肩膀彎舉，頂峰擠壓二頭肌。","停頓片刻，緩慢放回。","重複所需次數。"],"0196":["背對滑輪機站立，雙腳與肩同寬。","雙手在身後抓繩索，向前跨步拉出張力。","屈髖將臀部向後推，上半身前傾至平行地面，背部打直（滑輪早安式）。","臀肌與腿後腱發力挺身站回。","重複所需次數。"],"0197":["調整座椅高度，大腿固定於護墊下，雙腳踩平。","正握背闊肌長桿，握距略寬於肩。","坐穩微後仰，挺胸背打直。","手肘引導將長桿拉向下胸部，夾緊肩胛骨。","底部停留片刻，緩慢放回。","重複所需次數。"],"0198":["調整滑輪下拉機座椅與大腿護墊。","坐穩背部挺直，雙腳踩平。","正握抓長桿，握距略寬於肩寬。","微後仰挺胸，收緊核心。","將長桿向下拉向鎖骨胸前，肩胛骨向內夾緊。","底部停頓片刻，慢慢放回橫桿。","重複所需次數。"],"0199":["直桿接在高滑輪機上。","面對滑輪機站立，雙腳與肩同寬膝微屈。","正握抓直桿，手臂打直，掌心朝下。","核心收緊背打直，直臂將橫桿向下拉向大腿前側（滑輪直臂下拉 Straight-arm Pulldown）。","底部停留片刻收緊背闊肌，慢慢放回頭頂上方。","重複所需次數。"],"0200":["繩索配件接在高滑輪上。","面對機台站立，雙腳與肩同寬膝微屈。","正握/對握抓緊繩索兩端。","手肘貼緊身側固定。","吐氣將繩索向下推開至大腿兩側，雙臂完全伸直（繩索三頭下壓）。","停頓片刻，吸氣慢慢放回 90 度。","重複所需次數。"],"0201":["直桿接在高滑輪上。","面對滑輪機站立，雙腳與肩同寬，膝微屈。","正握抓直桿，雙手與肩同寬。","手肘貼緊身側，上手臂固定不動。","吐氣將直桿向下壓直，雙臂完全伸展（滑輪三頭下壓）。","停頓片刻，吸氣慢慢屈肘放回 90 度。","重複所需次數。"],"0202":["單手握把接在低滑輪上，面向機台站立。","左手握把，右腳後退一步站成前後站姿。","屈髖前傾，背部打直核心收緊。","左臂向前伸展，肩胛後收屈肘將把手拉向軀幹側。","頂端夾緊肩胛骨停頓片刻。","慢慢放回把手，重複所需次數後換手。"],"0203":["繩索把手接在低滑輪上。","面對機台站立，雙腳與肩同寬。","對握抓住繩索兩端。","膝微屈，屈髖前傾，背部打直。","手肘微屈，將繩索拉向胸前，肩胛骨用力夾緊。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0204":["把手接在低滑輪上，背對機台站立。","正握抓把手，雙臂在身前向前伸展。","手肘固定，手臂向後下方推直，頂端擠壓三頭肌。","慢慢放回把手，重複所需次數。"],"0205":["滑輪調至最高位置。","坐在機台前，雙腳踩實，膝蓋微彎。","正握抓握把，雙手間距略寬於肩。","身體微後傾，挺胸背打直。","將把手向下拉向胸前，肩胛骨夾緊。","底部稍作停頓，慢慢放回。","重複所需次數。"],"0206":["直桿接在低滑輪機上。","面對機台站立，雙腳與肩同寬，膝蓋微屈。","反握抓住直桿，雙手與肩同寬。","手肘貼緊身側，上手臂固定不動。","吐氣將直桿向上彎舉向肩膀，收縮二頭肌。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢放回，充分伸展手臂。","重複所需次數。"],"0207":["直桿接在高滑輪機上。","面對滑輪機站立，雙腳與肩同寬。","反手握直桿（掌心朝上），握距與肩同寬。","手肘貼緊身側，上手臂固定不動。","三頭肌發力將直桿向下推直，手臂完全伸展。","停頓片刻，慢慢送回 90 度。","重複所需次數。"],"0208":["坐在面對滑輪機的座椅上，雙腳踩實踏板。","反握抓住把手，掌心朝上，雙手與肩同寬。","背部打直，從髖部微向前傾。","肩胛後收夾緊背肌，將把手拉向軀幹。","頂端收縮處停頓片刻，慢慢送回。","重複所需次數。"],"0209":["滑輪與牧師椅調至胸部高度。","坐在牧師椅上，上手臂貼墊，手肘伸展。","反握抓住滑輪把手，雙手與肩同寬。","上手臂固定不動，吐氣將把手向肩膀彎舉。","頂峰停留片刻，擠壓二頭肌。","吸氣慢慢放回，完全展肘。","重複所需次數。"],"0210":["把手接在低滑輪上，坐在面對滑輪機的重訓椅上。","正握抓把手，掌心朝下。","前臂平放在大腿上，手腕懸空於膝前。","前臂固定不動，吐氣將手腕向上屈起。","頂峰停留片刻，吸氣慢慢降回。","重複所需次數。"],"0211":["坐在抗力球上，雙腳踩實，膝蓋呈 90 度。","雙手握滑輪把手，雙臂向前伸直。","微向後仰，背部打直核心收緊。","軀幹向右旋轉，將把手拉向右髖部。","停頓片刻，換轉向左側將把手拉向左髖部。","交替進行至所需次數。"],"0212":["坐在滑輪機前，雙腳踩實，膝蓋彎曲。","雙手抓住繩索把手放在後腦勺。","收緊腹肌，向前捲動上半身使胸口靠近膝蓋（坐姿滑輪捲腹）。","頂端停頓片刻，慢慢回正。","重複所需次數。"],"0213":["坐在坐姿划船機上，雙腳踩實踏板，雙膝微屈。","對握抓握 V 型把手，雙手與肩同寬。","背打直挺胸，從髖部稍微前傾。","收縮肩胛骨夾緊背肌，將 V 型把手拉向腹部。","頂峰停頓片刻，控制張力慢慢放回。","重複所需次數。"],"0214":["坐在面對划船機的長凳上，雙腳踩實，膝微彎。","單手抓握把，手臂完全向前伸展。","手肘貼身，肩胛後縮將把手拉向軀幹側。","頂端停留片刻，擠壓背肌。","慢慢放回把手，換另一手操作。","雙手交替進行至所需次數。"],"0215":["坐在重訓椅上面向滑輪機，雙腳踩平。","正握抓把手，雙臂向前伸展。","手臂打直，向兩側平舉至平行地面。","頂端停頓片刻，慢慢放回身前。","重複所需次數。"],"0216":["坐在重訓椅上面向滑輪機，雙腳平踩。","手握滑輪把手，手臂向前平舉，手肘彎曲 90 度。","肩胛骨下沉後收，手肘固定在身側。","慢慢將前臂向內側旋轉拉向腹部（滑輪肩內旋 Cable Internal Rotation）。","動作末端停頓片刻，慢慢旋轉回原位。","重複所需次數後換手。"],"0218":["坐在坐姿划船機上，雙腳踩實踏板，膝微屈。","寬握抓住長握把，掌心朝下。","背部維持挺直，微向前傾。","將握把拉向下胸部，肩胛骨向內用力夾緊。","頂峰停留片刻。","緩慢放回把手，雙臂充分伸展。","重複所需次數。"],"0219":["滑輪把手調至肩部高度。","背對滑輪機站立，雙腳與肩同寬。","正握抓把手舉至肩高，手肘朝外展開。","向上推舉把手，手臂在頭頂伸直。","頂端停留片刻，慢慢降回肩部。","重複所需次數。"],"0220":["面對滑輪機站立，雙腳與肩同寬。","正握抓把手垂於身前。","手臂維持打直，雙肩向上聳向耳朵。","頂端擠壓斜方肌停頓片刻，慢慢降回。","重複所需次數。"],"0221":["雙腳與肩同寬站立，單手握滑輪把手。","另一手叉腰。","收緊核心，慢慢向握把手側側屈，背部維持平直。","底部停頓片刻，慢慢回正。","重複所需次數後換邊。"],"0222":["雙腳與肩同寬站立，單手握滑輪把手。","背打直核心收緊。","慢慢將腰部向單側側屈，將把手沿腿下滑向膝蓋。","停頓片刻，慢慢回正。","換向另一側重複。","交替進行至所需次數。"],"0223":["把手接在低滑輪上，側對滑輪機站立。","用外側手抓住握把，內側手叉腰。","雙腳與肩同寬，膝微屈。","腹肌收緊，腰部向外側屈，手肘向下拉向臀部。","底部停頓片刻，慢慢回正。","重複所需次數後換邊。"],"0224":["面對滑輪機站立，雙腳與肩同寬。","正握抓滑輪把手，掌心朝下。","手臂伸直，手肘貼近身體兩側。","手腕向上屈起，將把手拉向身體。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0225":["兩側滑輪把手調至肩高。","站在交叉滑輪機中央，雙腳與肩同寬。","正握抓住把手，雙臂向兩側展開，掌心朝前。","手肘微彎，背部打直。","三角肌與胸肌發力，將雙手向前合攏交叉。","頂端停頓片刻，慢慢張開回原位。","重複所需次數。"],"0226":["滑輪把手接在高位，背對機台站立。","雙手抓住握把置於後腦勺，手肘彎曲。","雙腳與肩同寬，膝微屈。","腹肌收緊，吐氣向前下方捲腹，手肘拉向大腿。","底部停留片刻，慢慢回正。","重複所需次數。"],"0227":["把手安裝在滑輪機胸部高度。","背對滑輪機站立，雙腳與肩同寬。","正握抓住握把，掌心朝前。","微向前跨步拉出張力。","全程背部挺直，核心收緊。","手肘微屈，慢慢將雙臂向前合攏於胸前（滑輪夾胸）。","頂端收緊擠壓胸肌。","慢慢反向張開手臂回原位。","重複所需次數。"],"0228":["腳踝套接在低滑輪上，背對滑輪機站立。","腳踝套固定在單側腳踝，雙腳與肩同寬。","全程核心收緊，骨盆維持穩定。","腿部打直慢慢向後踢出，頂峰收縮臀大肌（滑輪後踢腿 Cable Glute Kickback）。","停頓片刻，慢慢收回。","重複所需次數後換腳。"],"0229":["面對滑輪機站立，雙腳與肩同寬。","反手抓滑輪握把，掌心朝上。","手肘貼緊身側，上手臂固定不動。","吐氣將把手向肩膀彎舉，收縮二頭肌。","頂峰停頓片刻，強力擠壓二頭肌。","吸氣慢慢放回。","重複所需次數。"],"0230":["面對滑輪機站立，雙腳與肩同寬。","雙手在腰部高度握住滑輪把手。","核心收緊背部打直。","雙臂伸直，吐氣將把手向對側肩膀斜向上提拉，同時順勢旋轉軀幹（低向高伐木）。","頂端停頓片刻，吸氣慢慢放回腰間。","重複所需次數後換邊。"],"0231":["雙腳與肩同寬站立面向滑輪機。","右手抓滑輪握把掌心朝下，上手臂抬起與地面平行。","手肘固定在身側上方。","手肘彎曲，慢慢將把手降向後腦勺。","動作底部停頓片刻，三頭肌發力推回。","重複所需次數後換左手操作。"],"0232":["繩索接在滑輪機最高位置。","面對機台站立，雙腳與肩同寬。","正握抓繩索，掌心朝下。","背打直核心收緊。","將繩索向下直臂拉向大腿，擠壓二頭與背部。","底部停頓片刻，慢慢放回。","重複所需次數。"],"0233":["面對滑輪機站立，雙腳與肩同寬。","對握抓滑輪配件，後退拉出張力。","背部挺直，核心收緊。","將把手拉向軀幹，肩胛骨向內夾緊。","頂端停留片刻，慢慢送回。","重複所需次數。"],"0234":["面對機台站立，雙腳與肩同寬。","正握抓 V 型握把，掌心朝下。","背部挺直核心收緊。","將 V 型把手拉向身體，肩胛骨夾緊。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0235":["雙腳與肩同寬站立，膝微屈。","手臂向前伸平握住滑輪把手。","手肘維持 90 度微屈貼身。","慢慢將手臂向外側旋轉展開（滑輪肩外旋 Cable External Rotation）。","動作末端停頓片刻，慢慢旋轉回正。","重複所需次數。"],"0236":["V 型把手接在胸高滑輪上。","面對機台站立，雙腳與肩同寬。","正握抓 V 型把手，掌心朝下，後退拉出張力。","背打直核心收緊。","手肘微收彎曲，將 V 型把手拉向軀幹。","拉動時順勢旋轉軀幹向一側，肩胛骨夾緊。","頂峰停頓片刻，感受上背收縮。","緩慢放回把手回正。","交替旋轉方向重複至指定次數。"],"0237":["繩索接在最高滑輪處。","面對機台站立，雙腳與肩同寬。","雙手抓住繩索兩端，掌心朝下。","雙臂在身前向前伸展，手肘微屈。","收緊背闊肌，將繩索直臂向下拉向大腿兩側。","底部停頓片刻，慢慢送回。","重複所需次數。"],"0238":["直桿接在高滑輪上。","面對滑輪機站立，雙腳與肩同寬。","正握抓直桿，手臂伸展，掌心朝下。","背闊肌發力將直桿向下壓向大腿前側，全程手臂伸直微屈（直臂下拉）。","底部停留片刻，慢慢放回頭頂上方。","重複所需次數。"],"0239":["坐在划船機上，雙腳踩在腳踏板上，膝微屈。","正握抓把手，掌心朝下。","背部打直，從髖部稍微前傾。","將把手拉向身體，肩胛骨夾緊。","頂峰停頓片刻，慢慢放回。","重複所需次數。"],"0240":["D 型握把接在低滑輪上，俯臥趴在平凳上。","雙手各握一握把，掌心朝下，手臂向前伸直。","手臂打直，將雙臂向兩側抬起至平行地面（俯臥滑輪反向飛鳥）。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0241":["V 型把手接在滑輪機最高處。","面對機台站立，雙腳與肩同寬。","正握抓住 V 型桿，手肘貼緊身側。","吐氣收縮三頭肌，將 V 型桿向下壓直，手臂完全伸展。","底部停頓片刻，擠壓三頭肌。","吸氣慢慢放回 90 度。","重複所需次數。"],"0242":["纜繩接在低滑輪上，仰臥平躺在墊子上。","雙手握住纜繩，手臂垂直伸展於胸前。","屈膝將雙腿抬起抱向胸口。","骨盆向胸部捲起，將臀部抬離地面（反向捲腹）。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0243":["雙腳與肩同寬站立面向滑輪機。","雙手在胸前握住把手，雙臂微屈。","啟動核心，將軀幹向右旋轉，拉動滑輪橫越身體（水平伐木轉體）。","轉體到底停頓片刻，感受腹斜肌收縮。","控制張力慢慢轉回中央。","換向左側旋轉重複。","交替進行至所需次數。"],"0244":["把手接在低滑輪上，面對機台站立。","左手握把，後退伸直手臂拉出張力。","雙腳與肩同寬，膝微屈。","背部維持打直，核心收緊。","將把手拉向身體，同時軀幹順勢向右旋轉。","動作末端夾緊背肌。","慢慢放回把手回正。","重複所需次數後換右手操作。"],"0245":["調整滑輪下拉機，使長桿位於頭頂高度。","反握抓住下拉長桿，雙手間距約與肩同寬（反手滑輪下拉）。","背打直微向後仰。","手肘向下向後拉，將橫桿拉向上胸鎖骨處，肩胛骨夾緊。","底部停頓片刻，慢慢送回橫桿。","重複所需次數。"],"0246":["雙腳與肩同寬站立，膝微屈，正握抓住滑輪直桿。","背打直核心收緊。","手肘引導將滑輪配件筆直向上提拉至鎖骨高度（滑輪直立划船）。","頂端停頓片刻，夾緊肩胛骨。","慢慢降回大腿前。","重複所需次數。"],"0247":["直桿接在低滑輪機上。","面對滑輪機站立，雙腳與肩同寬。","反手抓直桿，掌心朝上，握距與肩同寬。","前臂平放在重訓椅上，手腕懸空。","前臂固定不動，吐氣將手腕向上屈起。","頂端停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0248":["地板放置槓鈴，俯臥趴在平凳上，胸部略探出凳緣（海豹划船 Seal Row）。","向下伸手正握抓槓，握距略寬於肩。","雙腿伸直，雙臂垂直懸空提離槓鈴。","背肌發力將槓鈴向上拉向椅背下緣，肩胛骨用力夾緊。","慢慢降回槓鈴至手臂完全伸展。","重複所需次數。"],"0250":["坐直或站直，雙肩放鬆。","慢慢把頭往後仰，看向天花板。","嘴巴微張，放鬆下巴。","感受頸部前側的伸展感。","停留 15 到 20 秒。","慢慢回到自然回正的位置。"],"0251":["雙手撐在雙槓上，雙臂伸展撐起身體。","屈肘下沉身體，直到肩膀略低於手肘。","雙手推直，撐回頂端（雙槓撐體）。","重複所需次數。"],"0253":["以窄對握握距（掌心相對）懸掛在引體向上握把上。","收縮背肌挺胸，將身體向上拉起，手肘貼緊身側。","持續向上拉至下巴超過握把高度。","頂端停頓片刻，慢慢降回懸掛。","重複所需次數。"],"0255":["面對牆壁站立，單手把球壓在牆上，高度約與肩同高。","手臂打直但保持放鬆。","在牆上將球滾動畫小圈。","順著同一方向畫幾圈。","換反方向畫圈。","肩膀保持下沉不聳肩，接著換手。"],"0256":["站直，指尖輕放在肩膀上。","將手肘向兩側抬起。","用手肘畫大圈。","往前畫幾圈。","反過來往後畫圈。","頸部保持放鬆，呼吸維持平穩。"],"0257":["雙腳與肩同寬站立，雙手放在膝蓋上。","膝蓋微彎，前腳掌點地。","以順時針方向緩慢繞圈轉動雙膝，隨後換逆時針方向繞圈。","各旋轉指定圈數。"],"0258":["高棒式姿勢開始，雙手在肩膀正下方，身體呈一直線。","手肘彎曲下沉身體進行伏地挺身。","推起時身體順勢向左旋轉，左臂向上垂直伸向天花板成側棒式。","降回高棒式再進行一次伏地挺身。","推起時換向右旋轉，右臂垂直伸向天花板。","兩側交替進行至所需次數。"],"0259":["高棒式開始，雙手併攏置於胸部正下方（窄距伏地挺身 Close-grip Push-up）。","收緊核心，手肘貼緊身體兩側彎曲下沉。","掌心推地伸直雙臂推回起始位置。","重複所需次數。"],"0260":["平躺，雙膝彎曲，雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，將上半身捲離地面至約 45 度（捲腹）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"0261":["從高棒式開始，雙手在肩膀正下方撐地。","胸口往地板下放，同時將髖部稍微轉向一側。","推起身體，回到中間位置。","換轉向另一側重複動作。","核心收緊，雙腿併攏。","動作保持流暢，不要讓髖部下塌。"],"0262":["平躺，雙膝彎曲雙腳平踩。","雙手扶在後腦勺，手肘朝外。","收緊腹肌將上半身捲離地面，同時轉體使右肘靠近左膝。","頂端停頓片刻，慢慢放回。","換邊使左肘靠近右膝重複。","交替進行至所需次數。"],"0263":["仰躺，雙膝彎曲，雙手放在腦後。","抬起肩膀，將軀幹轉向一側。","讓手肘朝對側膝蓋靠近。","往下躺回，換另一側重複。","下背貼穩地板。","不要用手硬拉脖子。"],"0264":["站立，雙腳併攏，雙臂自然垂在身體兩側。","雙腳往外跳開，同時雙臂高舉過頭。","往回跳時，雙臂與其中一腿在身前交叉。","下一次換另一條腿在前交叉。","用前腳掌輕柔落地。","維持穩定的節奏跳 30 到 60 秒。"],"0267":["平躺，雙膝彎曲雙腳踩地。","雙臂伸直高舉過頭頂。","腹肌發力收緊，將上半身捲離地面向前向膝蓋靠攏（直臂捲腹）。","頂端稍作停頓，慢慢降回。","重複所需次數。"],"0268":["仰躺，雙手放在頭部兩側，雙腿抬起。","保持雙腿抬高，將肩膀捲離地板。","收緊腹肌。","慢慢放下肩膀。","在頂點時可把雙腿再往上抬一點，增加刺激。","下背保持往下壓穩地板。"],"0269":["仰躺，將小腿放在健身球上，雙膝彎曲呈 90 度。","雙手輕放頭部兩側或交叉於胸前。","將肩膀捲離地板。","在頂點收緊腹肌。","慢慢下放。","頸部保持放鬆，並穩住健身球。"],"0271":["坐在抗力球上，雙腳踩實，膝蓋呈 90 度。","向後仰躺使下背貼合球面，上半身平行地面。","雙手抱頭或交叉胸前。","收緊腹肌，向前捲動上半身靠近膝蓋（抗力球捲腹）。","頂端稍作停頓，慢慢放回球面。","重複所需次數。"],"0272":["坐在抗力球上，雙腳踩實，膝呈 90 度。","身體後滑至下背靠在球面上。","雙手抱頭或胸前交疊。","腹肌發力收縮，將肩膀捲向骨盆。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0273":["仰躺，雙腿筆直舉向天花板。","雙臂朝雙腳方向伸直。","將肩膀捲離地板，雙手往腳尖方向延伸。","在頂點收緊腹肌。","慢慢下放。","雙腿保持穩定不動，頸部放鬆。"],"0274":["平躺，雙膝彎曲雙腳踩地。","雙手輕扶後腦勺，手肘展開。","腹肌發力將肩胛骨抬離地面，捲向膝蓋。","頂峰停頓片刻，慢慢降回。","重複所需次數。"],"0275":["仰躺，雙膝彎曲，雙腳平踩地面。","雙手輕放在頭部兩側或交叉於胸前。","將肩膀捲離地板。","稍微停留並收緊腹肌。","有控制地慢慢下放。","下巴不要貼胸，下背維持貼地。"],"0276":["平躺在墊子上，雙臂垂直伸向天花板。","雙腿抬起屈膝呈 90 度（死蟲式 Dead Bug）。","核心收緊，下背緊貼地面。","右手與左腿同時慢慢放低，貼近地面懸空。","停頓片刻，收回原位。","換左手與右腿放低伸展。","交替進行至所需次數。"],"0277":["躺在下斜板上，雙腳固定，雙膝彎曲 90 度。","雙手抱頭或交叉胸前。","收緊腹肌將上半身捲起向膝蓋靠攏（下斜捲腹）。","頂端停留片刻，慢慢降回椅面。","重複所需次數。"],"0278":["將小腿或雙腳放在健身球上，雙手在肩膀正下方撐地。","從頭到腳跟呈一直線。","將胸口往地板方向下放。","推起身體，注意不要讓髖部下塌。","收緊核心以穩住健身球。","手肘與身體保持約 45 度。"],"0279":["雙手撐地略寬於肩，雙腳放在後方長凳或踏台上（下斜伏地挺身 Decline Push-up）。","身體從頭到腳呈一直線，核心收緊。","手肘微收彎曲，將胸口沉向地面。","掌心推地推直雙臂回到起始位置。","重複所需次數。"],"0281":["躺在下斜長凳上，雙腳勾住固定墊。","雙臂在身前打直，與地面平行。","將軀幹往上捲，一節一節離開長凳。","坐起身時，雙手朝膝蓋方向延伸。","有控制地慢慢躺回長凳。","下巴不要貼胸，也不要甩動手臂借力。"],"0282":["躺在下斜椅上，雙腳固定，雙膝彎曲。","雙手抱頭或交叉在胸前。","腹肌發力將上半身捲離椅面。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"0283":["高棒式姿勢開始，雙手大拇指與食指在胸下相扣成菱形（鑽石伏地挺身 Diamond Push-up）。","核心臀肌收緊，身體維持一直線。","屈肘下沉胸部貼向雙手間的菱形區域，手肘微收。","底部停頓片刻，三頭肌發力推回頂端。","重複所需次數。"],"0284":["前腳掌踩在踏台邊緣，腳跟完全懸空。","手扶牆壁或欄杆維持平衡。","盡可能將腳跟抬高，小腿強烈收縮。","頂峰停頓片刻，慢慢將腳跟放低至踏台水平面以下。","重複所需次數。"],"0285":["站直，雙手各握一啞鈴，掌心朝前，雙臂完全伸展。","上手臂固定不動，吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂端停留片刻，擠壓二頭肌。","吸氣慢慢放回，交替雙手進行至指定次數。"],"0286":["雙腳分開與肩同寬站立，雙手持啞鈴置於肩高。","單手將啞鈴推過頭頂，另一手維持在肩部。","放回推舉的手臂，同時將另一手推過頭頂。","交替推舉進行至指定次數。"],"0287":["坐在有靠背的重訓椅上，手持啞鈴於肩前，手肘彎曲，掌心朝向自己。","向上推舉啞鈴，手臂完全伸直，推舉過程中旋轉手腕使掌心轉向正前方（阿諾推舉 Arnold Press）。","頂端稍作停頓，慢慢將啞鈴放回肩部並轉回掌心朝內。","重複所需次數。"],"0288":["平躺在平凳上，雙腳踩實。","雙手合握一個啞鈴，推直於胸口正上方。","手臂微屈伸展，慢慢將啞鈴呈弧線放向頭頂後方（仰臥套頭）。","底部停頓片刻，胸背發力拉回胸前正上方。","重複所需次數。"],"0289":["平躺在平凳上，雙腳踩實，背部貼緊椅面。","雙手各持一啞鈴，掌心朝前，推直於胸前上方。","慢慢將啞鈴降至胸部兩側，手肘呈約 90 度。","稍作停頓，胸大肌發力將啞鈴推回頂端。","重複所需次數。"],"0290":["坐在重訓椅上，雙手各握一啞鈴置於大腿。","向後躺平，啞鈴置於胸前兩側，掌心朝前。","向上推舉啞鈴，手臂完全伸直。","最高點稍作停頓，慢慢降回胸側。","重複所需次數。"],"0291":["將啞鈴放在身後平凳前的地面上。","背對平凳站立，雙腳與肩同寬。","屈膝屈髖下蹲，如同坐入長凳（啞鈴箱式深蹲 Dumbbell Box Squat）。","臀部輕碰凳面即踩穩腳跟蹬起，回到起始站姿。","重複所需次數。"],"0292":["雙腳與肩同寬站立，單手持啞鈴，掌心朝內。","膝微屈，屈髖前傾，背部維持打直。","啞鈴自然垂直下垂。","手肘貼身將啞鈴拉向腰腹側邊，肩胛骨向內夾緊。","頂端停頓片刻，慢慢降回。","重複所需次數後換手。"],"0293":["雙腳與肩同寬站立，膝微屈，雙手各持一啞鈴，掌心相對。","屈髖前傾，背部維持平直，核心收緊。","雙臂自然下垂，手肘微屈。","背肌發力將啞鈴拉向胸腹兩側，肩胛骨向內夾緊。","頂端停留片刻，慢慢降回。","重複所需次數。"],"0294":["站直雙手各握一啞鈴，掌心朝前，雙臂伸展。","上手臂固定不動，吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂峰停頓片刻，強力擠壓二頭肌。","吸氣慢慢降回啞鈴。","重複所需次數。"],"0295":["雙腳與肩同寬站立，雙手各握一啞鈴垂於大腿前。","屈膝屈髖下沉成半蹲。","雙腿爆發力蹬地展髖，順勢聳肩將啞鈴向上拉起。","迅速鑽入啞鈴下方翻腕接住啞鈴成站姿架槓（啞鈴上膊 Dumbbell Clean）。","沿反向軌跡放回大腿前，重複進行。"],"0296":["坐在平凳上，雙手持啞鈴置於大腿。","用大腿將啞鈴頂至肩寬高度，向後躺平在凳面上。","旋轉手腕使掌心朝前。","吸氣慢慢將啞鈴降至胸側與胸口齊平。","吐氣運用胸肌與三頭肌發力推回正上方。","重複所需次數。"],"0297":["坐在重訓椅上，雙腿張開，單手持啞鈴，手肘抵在大腿內側（集中彎舉 Concentration Curl）。","反手握啞鈴，手臂完全下垂伸直。","上手臂固定不動，吐氣將啞鈴向上彎舉至肩前。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢降回，重複所需次數後換手。"],"0298":["站直，雙手各持一啞鈴，掌心朝向軀幹。","手肘貼緊軀幹，上手臂固定。","吐氣將啞鈴朝對側肩膀斜向彎舉（交叉錘式彎舉）。","舉至二頭肌完全收縮。","頂峰停留片刻，吸氣慢慢放回。","重複所需次數。"],"0299":["雙腳與肩同寬站立，手持啞鈴於肩前，掌心朝向自己。","核心收緊手肘微收，將啞鈴向上推舉過頭頂，推舉時旋轉手腕。","推至頂端手臂打直時掌心朝前。","慢慢放回肩部，手腕順勢轉回原位。","重複所需次數。"],"0300":["雙腳與肩同寬站立，腳尖朝前。","雙手各握一啞鈴垂於大腿兩側。","屈髖屈膝將啞鈴沿腿向下放低，背部維持平直挺胸（啞鈴硬舉）。","踩穩腳跟伸膝挺髖將啞鈴拉回站姿。","重複所需次數。"],"0301":["躺在下斜長凳上，雙腳固定，頭部低於臀部。","雙手持啞鈴推直於胸部上方，掌心朝前。","慢慢將啞鈴降至胸部兩側，手肘呈 90 度。","胸肌發力推回起始位置，雙臂伸展。","重複所需次數。"],"0302":["躺在下斜椅上，雙腳固定，頭低於臀。","雙手各握一啞鈴，掌心相對，雙臂伸直於胸前。","手肘微彎，將雙臂以弧線向兩側展開（下斜啞鈴飛鳥）。","停頓片刻，胸肌發力夾回正上方。","重複所需次數。"],"0303":["躺在下斜椅上，雙腳固定。","雙手握啞鈴推直於胸前，掌心相對。","將啞鈴慢慢降向胸側，手肘微屈。","胸肌發力推回頂端。","重複所需次數。"],"0304":["將重訓椅調整為 45 度下斜。","胸腹貼墊趴好，雙手各握一啞鈴，掌心相對。","手臂打直，雙肩向上後方提拉，兩側肩胛骨向內夾緊。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0305":["重訓椅調整至約 45 度下斜。","胸腹貼緊斜墊趴好，雙腳固定。","雙手持啞鈴垂直下垂伸向地面。","保持手臂打直，雙肩向上聳向耳朵（俯臥啞鈴聳肩）。","頂峰停頓片刻，慢慢降回。","重複所需次數。"],"0306":["躺在下斜椅上，頭低腳高，手持啞鈴掌心相對。","雙臂伸直於胸前，手肘靠近頭部。","手肘彎曲將啞鈴慢慢放低至額頭兩側。","停頓片刻，三頭肌發力推回起始位置。","重複所需次數。"],"0307":["躺在下斜椅上，頭部低於臀部。","手持啞鈴垂直推展於胸前，掌心相對。","手肘微屈，將啞鈴向兩側展開放低。","展開時旋轉手腕使掌心在底部朝向腳尖方向。","胸肌發力夾回胸前，手腕順勢轉回掌心相對。","重複所需次數。"],"0308":["平躺在平凳上，雙手各握一啞鈴，掌心相對。","雙臂垂直伸展於胸前，手肘微屈。","手肘維持微彎，向兩側呈大弧線展開，感受胸大肌拉伸（平板啞鈴飛鳥）。","停頓片刻，胸肌發力夾回起始位置。","重複所需次數。"],"0309":["雙腳與肩同寬站立，雙手各握一啞鈴置於大腿前。","背打直核心收緊。","慢慢向前平舉啞鈴至手臂平行地面。","頂端稍作停頓，慢慢放回大腿前。","重複所需次數。"],"0310":["雙腳與肩同寬站立，雙手持啞鈴垂於大腿前，掌心朝後。","手臂打直，吐氣將啞鈴向前上方平舉至肩高。","頂端停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0311":["雙腳分開與肩同寬站立，雙手各握一啞鈴垂於體側。","背部挺直，核心收緊。","手肘微彎，將雙臂向兩側平舉至平行地面（站姿啞鈴側平舉）。","頂端稍作停頓，慢慢放回身側。","重複所需次數。"],"0312":["站直，雙手持啞鈴垂於身側。","上手臂固定，掌心轉向正前方。","吐氣向上彎舉啞鈴，收縮二頭肌。","舉至啞鈴與肩同高，頂峰擠壓二頭肌。","吸氣慢慢放回，重複所需次數。"],"0313":["站直，雙手各持一啞鈴垂於體側。","手肘貼緊身側，旋轉前臂使掌心朝前。","上手臂維持不動，吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂端停留片刻，吸氣慢慢放回。","重複指定次數。"],"0314":["將重訓椅調整至約 45 度上斜。","背靠椅背坐好，雙腳踩實地面。","手持啞鈴舉至肩前，掌心朝前。","慢慢將啞鈴降至胸部兩側，手肘呈約 90 度。","胸大肌發力將啞鈴推回頂端（上斜啞鈴臥推 Incline Dumbbell Press）。","重複所需次數。"],"0315":["坐在上斜椅上，雙手各持一啞鈴垂於身側，掌心朝前。","上手臂垂直固定，吐氣彎舉啞鈴收縮二頭肌。","舉至啞鈴與肩同高。","頂端停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0316":["重訓椅調整至 45 度上斜。","背靠椅墊坐好，雙手正握持啞鈴。","推起啞鈴垂直於地面。","慢慢降至胸部兩側，手肘呈 90 度。","底部停頓片刻，推回頂端。","重複所需次數。"],"0317":["坐在上斜椅上，手持啞鈴垂於身側，掌心朝前。","上手臂垂直地面固定，吐氣彎舉啞鈴。","舉至二頭肌完全收縮，頂峰擠壓。","吸氣慢慢放回，重複所需次數。"],"0318":["重訓椅調至 45 度上斜，雙手持啞鈴掌心朝前。","上手臂靠在上斜墊上，手臂完全伸展。","上手臂固定，吐氣彎舉啞鈴收縮二頭肌。","舉至啞鈴與肩同高，頂端停頓片刻。","吸氣慢慢放回，重複所需次數。"],"0319":["將重訓椅調整至 45 度上斜。","手持啞鈴仰臥在斜椅上，掌心相對。","將啞鈴推至胸部正上方。","手肘微彎，呈弧線向兩側展開放低感受胸肌拉伸（上斜啞鈴飛鳥）。","停頓片刻，胸肌發力夾回胸前。","重複所需次數。"],"0320":["坐在上斜椅上，手持啞鈴垂於體側，掌心朝向軀幹。","背靠椅背雙腳踩實。","上手臂固定不動，吐氣彎舉啞鈴收縮二頭肌（上斜啞鈴錘式彎舉）。","舉至啞鈴與肩同高，頂端停頓片刻。","吸氣慢慢降回。","重複所需次數。"],"0321":["上斜椅調至 45 度，手持啞鈴置於大腿。","仰臥躺下，推起啞鈴至胸前上方，掌心相對（對握上斜推胸）。","將啞鈴推離胸部至手臂伸展。","頂端停頓片刻，慢慢降回胸前。","重複所需次數。"],"0322":["坐在上斜椅上，雙手各握一啞鈴，掌心相對。","上手臂靠在椅背斜面上，手肘下垂，掌心朝前。","上手臂固定，吐氣彎舉啞鈴收縮二頭肌。","舉至啞鈴與肩同高。","頂端停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0323":["坐在上斜椅上，單手持啞鈴置於大腿。","身體前傾，上手臂抵在大腿內側。","手肘微屈，將啞鈴向側方平舉至平行地面。","頂端停頓片刻，慢慢放回。","重複所需次數後換手。"],"0324":["重訓椅調整為 45 度上斜。","背靠椅背坐好，雙手持啞鈴置於肩前，掌心相對。","雙腳踩實地面，背部貼緊靠墊。","將啞鈴向上推舉過頭，手臂完全伸展。","最高點停頓片刻，慢慢降回肩部。","重複所需次數。"],"0325":["坐在上斜椅上，雙手持啞鈴置於大腿。","仰臥靠在椅背上，將啞鈴舉至肩高，掌心朝前。","吐氣將啞鈴垂直推過頭頂，手臂伸展（上斜啞鈴肩推）。","頂端停頓片刻，吸氣慢慢降回肩部。","重複所需次數。"],"0326":["重訓椅調整至 45 度斜角。","胸貼椅背俯臥趴好，雙手各握一啞鈴。","雙臂伸直垂直垂向地面，掌心相對。","手肘微屈，向兩側抬起手臂至平行地面（俯臥上斜反向飛鳥）。","頂峰停頓片刻，慢慢降回。","重複所需次數。"],"0327":["重訓椅調整至 45 度上斜。","胸部靠在斜面上趴好，雙手握啞鈴垂於肩下。","手臂伸直垂直下垂。","肩胛後收夾緊，將啞鈴向上拉向胸側（胸貼上斜啞鈴划船）。","頂峰停頓片刻，慢慢降回。","重複所需次數。"],"0328":["重訓椅調整至 45 度上斜，手持啞鈴置於大腿。","靠在椅背上，用大腿輔助將啞鈴頂至肩部高度。","手腕旋轉使掌心朝前。","吐氣將啞鈴推過頭頂，手臂伸直手肘微屈。","頂端停頓片刻，吸氣降回肩部。","重複所需次數。"],"0329":["上斜椅調整至 45 度，雙手握啞鈴趴在斜椅上。","雙腳踩實地面，雙臂垂直自然下垂。","手臂維持打直，雙肩向上聳向耳朵。","頂端收縮片刻，慢慢放回肩膀。","重複所需次數。"],"0330":["坐在上斜椅上，雙手握啞鈴，掌心朝內。","雙臂伸展高舉過頭頂，手肘貼近頭部。","手肘彎曲將啞鈴降向後腦勺，上手臂維持固定。","停頓片刻，三頭肌發力推回頂端。","重複所需次數。"],"0331":["上斜椅調整至 45 度，手持啞鈴推直於胸前，掌心相對。","手肘微彎，向兩側呈大弧線展開放低。","展開時旋轉手腕使掌心在底部朝向腳尖。","胸肌發力夾回胸前，同時轉回掌心相對。","重複所需次數。"],"0332":["雙腳與肩同寬站立，手持啞鈴垂於體側。","雙臂向兩側水平舉起成 T 字形，直到與地面平行。","稍作停頓，慢慢降回體側。","重複所需次數。"],"0333":["雙腳分開與肩同寬站立，雙手各握一啞鈴。","膝微屈，屈髖前傾，背部維持平直。","上手臂貼緊身側，手肘彎曲呈 90 度。","前臂向後推直伸展，頂峰擠壓三頭肌（啞鈴三頭後屈伸）。","停頓片刻，慢慢收回 90 度。","重複所需次數。"],"0334":["雙腳與肩同寬站立，雙手握啞鈴垂於體側。","背打直核心收緊。","手肘微彎，將手臂向兩側平舉至平行地面（站姿側平舉）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"0335":["雙腳與肩同寬站立，雙手各握一啞鈴。","背部維持挺直，核心收緊。","先將雙臂向兩側平舉至平行地面，停頓片刻放回。","隨後將雙臂向前平舉至平行地面，停頓片刻放回。","交替進行側平舉與前平舉。"],"0336":["雙腳與肩同寬站立，雙手持啞鈴垂於體側。","右腳向前跨出一大步成弓箭步。","下沉時背部打直挺胸。","踩穩右腳跟推回站姿。","換左腿前跨重複。","雙腿交替進行至所需次數。"],"0337":["平躺在平凳上，雙腳踩實，頭枕在椅端。","雙手握啞鈴推直於胸前，掌心相對。","上手臂垂直固定，以弧線動作將啞鈴慢慢降向頭後方。","停頓片刻，三頭肌發力拉回胸前正上方。","重複所需次數。"],"0338":["平躺在平凳上，雙手持啞鈴垂直於胸前，掌心相對。","彎曲手肘將啞鈴降向肩膀兩側，上手臂固定不動。","底部停頓片刻，三頭肌發力推回頂端。","重複所需次數。"],"0339":["平躺在地上，雙腿伸展，啞鈴置於下腹部。","腹肌發力收縮將下身向上微捲，帶動啞鈴上提。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0340":["平躺在平凳上，雙手握啞鈴垂直伸直於胸前，掌心相對。","慢慢將啞鈴降至胸部兩側，手肘呈 90 度。","胸肌發力推回頂端，雙臂完全伸展。","重複所需次數。"],"0341":["俯臥趴在平凳上，單手持啞鈴，掌心朝內。","手臂向下伸向地板，貼近身體。","背肌發力向上後方拉起手臂，肩胛骨向脊椎靠攏夾緊。","頂端停頓片刻，慢慢放回。","重複所需次數後換手。"],"0342":["平躺在平凳上，背部貼合，雙腳踩平。","單手握啞鈴，掌心朝向腳部。","雙臂伸直手肘微屈。","慢慢將啞鈴降向胸側，手肘貼身。","底部停頓片刻，推回頂端。","重複所需次數後換手。"],"0343":["平躺在平凳上，單手持啞鈴置於肩旁，雙腳踩實。","掌心朝前，單手將啞鈴垂直推向上方。","最高點稍作停頓，慢慢降回肩部。","重複所需次數後換手。"],"0344":["平躺在平凳上，單手持啞鈴垂直伸展於肩上。","上手臂垂直地面固定，彎曲手肘將啞鈴降向前額上方。","底部停頓片刻，三頭肌發力推回頂端。","重複所需次數後換手。"],"0345":["俯臥趴在平凳上，單手持啞鈴垂向地面。","手臂維持打直微彎，將啞鈴向側邊平舉抬起至平行地面。","頂端停頓片刻，慢慢降回。","重複所需次數後換手。"],"0346":["平躺在平凳上，單手反握持啞鈴伸展於肩上。","上手臂固定，手肘彎曲將啞鈴放低至額頭兩側。","底部停頓片刻，伸展三頭肌推回。","重複所需次數後換手。"],"0347":["俯臥趴在平凳上，手臂垂直垂向地板，掌心朝上。","上手臂固定不動，手腕屈起進行反向腕彎舉。","頂峰停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0348":["俯臥趴在平凳上，雙手各握一啞鈴，掌心相對。","雙臂垂直垂向地面，手肘微屈。","後三角肌發力，將雙臂向兩側抬起至平行地面（俯臥啞鈴反向飛鳥）。","頂端稍作停頓，慢慢降回。","重複所需次數。"],"0349":["平躺在平凳上，雙手握啞鈴放於身側，掌心朝上。","手肘貼緊身側固定。","手腕向上屈起，擠壓前臂肌肉。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0350":["平躺在平凳上，雙手各握一啞鈴，掌心朝上，手臂自然伸展。","上手臂維持貼凳固定，吐氣彎舉啞鈴收縮二頭肌。","舉至啞鈴與肩同高。","頂峰擠壓二頭肌停留片刻。","吸氣慢慢放回，重複所需次數。"],"0351":["平躺在平凳上，雙手握啞鈴推直於胸前，掌心相對。","上手臂垂直固定，手肘彎曲將啞鈴降向前額兩側。","停頓片刻，三頭肌發力推回。","重複所需次數。"],"0352":["平躺在平凳上，雙腳踩實，背貼椅面。","雙手握啞鈴採中立對握（掌心相對），推直於胸前。","慢慢降向胸側，手肘貼身。","底部稍作停頓，推回頂端。","重複所需次數。"],"0353":["坐在抗力球上，雙腳踩平，膝呈 90 度。","單手拿啞鈴，手肘抵在大腿內側近膝蓋處。","上手臂固定不動，吐氣將啞鈴向上彎舉至肩前。","頂峰停頓片刻，吸氣慢慢放回。","重複所需次數後換手。"],"0354":["雙腳與肩同寬站立，右手握啞鈴。","膝微屈屈髖前傾，背部打直。","右上臂抬起貼身，手肘呈 90 度。","右臂向後推直伸展，在頂峰擠壓三頭肌。","慢慢放回 90 度。","重複所需次數後換手。"],"0355":["雙腳分開與肩同寬站立，單手握啞鈴垂於體側。","全程背部維持挺直，核心收緊。","手肘微彎，單臂向外側平舉至平行地面（單臂側平舉）。","頂端停頓片刻，慢慢降回身側。","重複所需次數後換手。"],"0356":["雙腳與肩同寬站立，單手握啞鈴，另一手扶牆支撐。","背打直核心收緊。","單臂向外側平舉至平行地面。","頂端停留片刻，慢慢放回。","重複所需次數後換手。"],"0357":["手持啞鈴坐在健身球上，雙腳往前走，直到上背靠在球上。","抬起髖部讓身體像長凳一樣平直，雙腳踩寬以維持平衡。","將啞鈴停在胸口高度，接著往肩膀上方推起。","慢慢將啞鈴放回胸口高度。","完成目標次數後換手。","全程保持髖部抬高，不要讓身體扭轉。"],"0358":["坐在重訓椅上，單手正握持啞鈴，掌心朝下。","前臂平放在大腿上，手腕懸空於膝前。","手腕向上屈起，收縮前臂肌肉。","頂端停頓片刻，慢慢放回。","重複所需次數後換手。"],"0359":["坐在重訓椅上，雙腳踩實，背部打直。","單手持啞鈴，另一手扶椅面支撐。","俯身前傾，手肘微彎，將啞鈴向側邊抬起至平行地面。","頂端停頓片刻，慢慢降回。","重複所需次數後換手。"],"0360":["雙腳與肩同寬站立，單手握啞鈴於肩前，掌心朝前。","核心收緊，單臂垂直向上推舉過頭頂。","頂端停留片刻，慢慢降回肩部。","重複所需次數後換手。"],"0361":["雙腳與肩同寬站立，單手持啞鈴於肩高，掌心朝前。","向上推舉啞鈴，直到手臂完全伸直過頭頂。","頂峰稍作停頓，慢慢放回肩部。","重複所需次數後換手。"],"0362":["坐在重訓椅上，背打直雙腳踩平。","單手持啞鈴推過頭頂，另一手扶椅支撐。","上手臂靠近頭部固定，手肘彎曲將啞鈴降向後腦勺。","三頭肌發力將啞鈴推回頭頂。","重複所需次數後換手。"],"0363":["雙腳分開與肩同寬站立，單手正握持啞鈴。","啞鈴垂在大腿前側，手臂伸直。","背打直核心收緊，吐氣以手肘引領垂直向上提拉至胸前（單臂直立划船）。","頂端停頓片刻，吸氣慢慢降回。","重複所需次數後換手。"],"0364":["坐在重訓椅上，單手反握持啞鈴，前臂平放在大腿上。","手腕放鬆讓啞鈴向下滾動至指尖。","手指收縮捲起啞鈴，隨後手腕屈起。","重複所需次數後換手。"],"0365":["坐在平凳上，雙手反握持啞鈴，掌心朝上。","前臂平放在長凳上，手腕懸空。","手腕向上屈起，擠壓前臂肌肉。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0366":["坐在牧師椅上，單手握啞鈴伸在斜墊上，掌心朝上。","上手臂固定不動，將啞鈴向上彎舉至肩前。","頂峰停留片刻，慢慢降回。","重複所需次數後換手。"],"0367":["坐在重訓椅上，單手正握持啞鈴，掌心朝下。","前臂平放在長凳上，手腕懸空。","手腕向上屈起，將啞鈴向上抬。","頂端停頓片刻，慢慢放回。","重複所需次數後換手。"],"0368":["坐在重訓椅上，雙手正握持啞鈴，掌心朝下。","前臂平放在凳面上，手腕懸空。","手腕向上屈起抬起啞鈴。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0369":["坐在平凳上，前臂平放在凳面上，手腕懸空。","手腕向上屈起，頂端擠壓前臂。","停頓片刻，慢慢放回。","重複所需次數。"],"0370":["站直，雙手各持一啞鈴垂於體側。","上手臂固定在身側，掌心朝向前方。","吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂端停頓片刻，用力擠壓。","吸氣慢慢降回。","重複建議次數。"],"0371":["雙腳分開與肩同寬站立，雙手持啞鈴垂於體側。","屈膝下蹲進入深蹲。","在深蹲底部爆發力向上起跳。","在空中快速換腳成前後分腿。","輕巧落地緩衝隨即順勢再次起跳換腳。","持續跳躍換腳至指定次數。"],"0372":["坐在牧師椅上，雙手各持一啞鈴，手臂完全伸在斜墊上。","上手臂固定不動，吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢降回。","重複所需次數。"],"0373":["坐在重訓椅上，背部挺直，雙手合握一個啞鈴推過頭頂。","上手臂靠近頭部固定，手肘彎曲將啞鈴慢慢降至後腦勺。","停頓片刻，雙手推直回頭頂。","重複所需次數。"],"0374":["重訓椅調整至 45 度上斜。","胸腹貼緊椅背趴好，雙手正握抓啞鈴，掌心朝下。","上手臂固定不動，吐氣彎舉啞鈴（蜘蛛彎舉）。","舉至二頭肌完全收縮。","頂峰停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0375":["平躺在平凳上，雙腳踩實地面。","雙手合握一個啞鈴推直於胸前。","手肘微彎，慢慢將啞鈴呈弧線放低至頭後，直到感受胸背拉伸（仰臥套頭）。","停頓片刻，發力拉回胸前正上方。","重複所需次數。"],"0376":["雙腳分開與肩同寬站立，雙手各握一啞鈴垂於體側。","背打直核心收緊。","手肘微彎，將雙臂向兩側平舉至平行地面（站姿側平舉）。","頂端稍作停頓，慢慢降回。","重複所需次數。"],"0377":["雙腳與肩同寬站立，膝微屈。","手持啞鈴垂於大腿前，屈髖前傾，背部維持平直。","手肘微屈，雙臂向兩側抬起，兩側肩胛骨向內夾緊（俯身啞鈴反向飛鳥）。","頂峰停頓片刻，慢慢降回。","重複所需次數。"],"0378":["雙腳與肩同寬站立，手持啞鈴。","膝微屈屈髖前傾，背部平直。","雙臂垂直垂向地面，掌心相對。","手肘微彎，向兩側抬起手臂夾緊肩胛骨。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0379":["雙腳與肩同寬站立，雙手握啞鈴。","屈髖前傾，背部平直。","手肘微屈將雙臂向兩側抬起至平行地面。","頂端停留片刻，慢慢降回。","重複所需次數。"],"0380":["雙腳與肩同寬站立，雙手持啞鈴。","膝微屈屈髖前傾，背部打直核心收緊。","手肘微屈，將手臂向兩側平舉至平行地面。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0381":["雙腳與肩同寬站立，手持啞鈴垂於體側。","右腳向後退一大步成反向弓箭步。","彎曲左膝下沉至左大腿平行地面。","停頓片刻，踩穩左腳跟蹬回起始站姿。","換另一腿後跨重複。"],"0382":["站直，雙手正握抓啞鈴（掌心朝下），雙臂伸直。","上手臂固定不動，吐氣彎舉啞鈴收縮前臂與二頭肌（反向彎舉）。","舉至啞鈴與肩同高。","頂峰停頓片刻，吸氣慢慢降回。","重複所需次數。"],"0383":["雙腳與肩同寬站立，手持啞鈴。","膝微屈，屈髖前傾，背打直。","雙臂在身前垂直下垂，掌心相對。","手肘微屈，向兩側展開手臂至平行地面。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0384":["坐在牧師椅上，手臂伸在斜墊上，雙手反握持啞鈴。","上手臂固定不動，吐氣將啞鈴向肩膀彎舉。","持續彎舉至二頭肌完全收縮。","頂峰停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0385":["坐在重訓椅上，前臂平放在大腿上，正握抓住啞鈴（掌心朝下）。","手腕懸空於膝前。","手腕向上屈起，收縮前臂伸肌。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0386":["雙腳分開與肩同寬站立，雙手持啞鈴。","膝微屈屈髖前傾，挺胸背打直。","手肘微彎向兩側平舉至平行地面。","在頂端將手臂內旋使大拇指朝下。","慢慢降回原位，重複所需次數。"],"0387":["坐在重訓椅上，背部挺直雙腳踩平。","雙手持啞鈴垂於體側。","雙臂打直，交替單臂向前平舉至平行地面（坐姿交替前平舉）。","頂端稍作停頓，慢慢降回。","雙手交替進行至指定次數。"],"0388":["坐在重訓椅上，雙手持啞鈴置於肩高，掌心朝前。","單臂將啞鈴推過頭頂，手臂完全伸直。","放回肩部高度，換另一手推舉。","雙臂交替推舉進行至所需次數。"],"0389":["坐在重訓椅上，背打直雙腳踩平。","雙手合握一個啞鈴推過頭頂。","慢慢將啞鈴降向後腦勺，手肘靠近耳朵。","停頓片刻，三頭肌發力推回頭頂。","重複所需次數。"],"0390":["坐在抗力球上，雙腳踩實，背部打直。","雙手握啞鈴垂於身側，掌心朝前。","上手臂固定，吐氣彎舉啞鈴收縮二頭肌。","舉至啞鈴與肩同高。","頂峰停頓片刻，吸氣慢慢降回。","重複所需次數。"],"0391":["坐在平凳上，雙腳踩實地面，手持啞鈴垂於身側，掌心朝前。","背部維持打直，手肘貼緊軀幹。","吐氣將啞鈴向上彎舉向肩膀，收縮二頭肌。","頂峰停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0392":["坐在重訓椅上，雙手持啞鈴垂在大腿兩側。","背打直核心收緊。","雙手正握將啞鈴向前平舉至肩高，掌心朝下。","頂端停留片刻，慢慢放回大腿前。","重複所需次數。"],"0393":["坐在重訓椅上，手持啞鈴，上手臂靠在大腿上。","手臂完全下垂伸展。","二頭肌發力將啞鈴彎舉向肩膀，上手臂固定不動。","頂端停留片刻，慢慢降回。","重複所需次數。"],"0394":["坐在重訓椅上，手持啞鈴。","膝微屈，從髖部向前俯身，背部平直。","上手臂貼緊身側，手肘彎曲呈 90 度。","前臂向後推直伸展，頂峰擠壓三頭肌（坐姿三頭後屈伸）。","停頓片刻，慢慢放回 90 度。","重複所需次數。"],"0395":["坐在重訓椅上，手持啞鈴垂於身側。","背部打直，雙肩放鬆。","手肘微彎向兩側平舉至平行地面。","頂端稍作停頓，慢慢降回。","重複所需次數。"],"0396":["坐在重訓椅上，雙手持啞鈴垂於身側。","背部挺直，核心收緊。","手肘微彎，將啞鈴向兩側平舉至平行地面（坐姿側平舉）。","頂端停留片刻，慢慢放回身側。","重複所需次數。"],"0397":["坐在重訓椅上，雙手各握一啞鈴，採中立對握（掌心相對）。","上手臂固定在身側。","保持手腕中立，將啞鈴向上彎舉至肩前（坐姿錘式彎舉）。","頂峰停頓片刻，慢慢降回。","重複所需次數。"],"0398":["坐在重訓椅上，單手持啞鈴。","向前俯身，背部平直與地面平行。","上手臂貼身，前臂向後推直伸展。","頂峰停留片刻，慢慢收回。","重複所需次數後換手。"],"0399":["坐在重訓椅上，背打直，單手握啞鈴。","手肘貼緊身側呈 90 度屈曲。","上手臂貼身固定，將前臂慢慢向外側旋轉展開（坐姿單臂肩外旋）。","頂端停留片刻，慢慢旋轉回原位。","重複所需次數後換手。"],"0400":["坐在重訓椅上，啞鈴放在右大腿近膝處。","左腿向前伸直腳尖勾起。","右前腳掌踩在踏台上，腳跟懸空。","小腿發力將右腳跟推至最高點（坐姿單腿提踵）。","頂峰停頓片刻，慢慢放回腳跟。","重複所需次數後換腳。"],"0401":["坐在重訓椅上，雙手反手握住啞鈴（掌心朝上）。","前臂平放在大腿上，手腕懸空。","手腕向上屈起，頂端擠壓前臂肌肉。","停頓片刻，慢慢放回。","重複所需次數。"],"0402":["坐在牧師椅上，雙腳踩實地面。","單手反握持啞鈴，上手臂靠在牧師斜墊上。","上手臂固定不動，吐氣將啞鈴向肩膀彎舉。","頂峰停頓片刻，吸氣慢慢降回。","重複所需次數後換手。"],"0403":["坐在重訓椅上，單手反握持啞鈴。","手肘抵在大腿內側近膝蓋處（集中彎舉）。","上手臂維持固定，吐氣將啞鈴向上彎舉向肩膀。","頂峰停留片刻，擠壓二頭肌。","吸氣慢慢放回，重複所需次數後換手。"],"0404":["坐在重訓椅上，雙手握啞鈴置於肩高，掌心相對。","將啞鈴向上推舉過頭頂，手臂伸展。","頂端停留片刻，慢慢降回肩前。","重複所需次數。"],"0405":["坐在重訓椅上，雙手持啞鈴置於肩高，掌心朝前。","向上推舉啞鈴，手臂完全伸展過頭頂。","頂峰停留片刻，慢慢降回肩部。","重複所需次數。"],"0406":["雙腳與肩同寬站立，手持啞鈴垂於體側。","雙臂伸直自然下垂。","雙肩垂直向上聳向耳朵，頂峰強力收縮斜方肌（站姿啞鈴聳肩）。","維持收縮一秒，慢慢放回肩膀。","重複所需次數。"],"0407":["站直，雙腳分開與肩同寬，單手持啞鈴垂於體側。","背打直核心收緊，慢慢向持啞鈴的對側側屈，感受體側拉伸。","停頓片刻，慢慢回正。","重複所需次數後換邊。"],"0408":["側躺在地面上，雙腿打直。","上手握啞鈴，掌心朝下。","手臂維持打直微彎，將啞鈴向側上方舉起至平行地面（側臥啞鈴側平舉）。","頂端停頓片刻，慢慢放回。","重複所需次數後換邊。"],"0409":["前腳掌踩在踏台邊緣，腳跟完全懸空。","單手握啞鈴，另一手扶牆支撐。","單腿前腳掌發力將腳跟推至最高點。","頂峰停頓片刻，慢慢將腳跟放低至踏面以下。","重複所需次數後換腳。"],"0410":["雙腳與肩同寬站立，雙手持啞鈴垂於體側。","單腳向後抬起，將腳尖搭在身後長凳上（啞鈴保加利亞分腿蹲）。","前腿屈膝下沉，後膝自然彎曲接近地面。","下沉至前大腿平行地面，前腳跟蹬地推回站姿。","重複所需次數後換腿。"],"0411":["雙腳與肩同寬站立，雙手各持一啞鈴。","單腿向前伸直懸空。","單腿彎曲下蹲如坐入椅子（手槍深蹲）。","挺胸背打直。","在底部停頓片刻，腳跟推地站回。","重複所需次數後換腿。"],"0412":["將健身球放在下背與牆面之間，雙手各拿一顆啞鈴。","雙腳往前跨一步，與肩同寬。","彎曲膝蓋往下蹲，讓球順著背部往上滾動。","下蹲到大腿約與地面平行。","腳跟推地站回起始位置。","保持膝蓋朝向腳尖方向。"],"0413":["雙腳分開與肩同寬站立，雙手持啞鈴垂於體側。","挺胸收腹，屈膝屈髖下沉進入深蹲（啞鈴深蹲）。","下沉至大腿平行地面或略低。","底部停頓片刻，腳跟蹬地推回站姿。","重複所需次數。"],"0414":["雙腳與肩同寬站立，雙手持啞鈴於肩高，掌心朝前。","單手將啞鈴推過頭頂，手臂伸展。","降回肩部，換另一手推舉。","雙手交替推舉進行至所需次數。"],"0415":["雙腳與肩同寬站立，手持啞鈴垂於身側。","背打直核心收緊。","單手向側邊平舉至平行地面，停頓片刻降回。","換另一手側平舉重複。","雙手交替進行至指定次數。"],"0416":["站直雙腳與肩同寬，手持啞鈴垂於體側，掌心朝前。","上手臂固定不動，吐氣雙手同時彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢降回。","重複所需次數。"],"0417":["雙腳與肩同寬站立，雙手持啞鈴垂於體側。","小腿發力盡可能將腳跟抬高踮起腳尖（站姿啞鈴提踵）。","頂峰停頓片刻，慢慢降回腳跟。","重複所需次數。"],"0418":["雙腳與肩同寬站立，單手持啞鈴垂於身前，掌心朝內。","另一手叉腰或扶大腿支撐。","上手臂固定不動，吐氣收縮二頭肌將啞鈴彎向肩膀。","舉至啞鈴與肩同高，頂端停頓片刻。","吸氣慢慢降回，重複所需次數後換手。"],"0419":["雙腳與肩同寬站立，雙手正握持啞鈴。","手臂維持打直，將啞鈴向前上方舉過頭頂。","頂峰停頓片刻，慢慢放回大腿前。","重複所需次數。"],"0420":["雙腳與肩同寬站立，手持啞鈴。","膝微屈屈髖前傾，背部平直。","雙臂向後推直伸展，在頂峰擠壓三頭肌。","停頓片刻，慢慢收回 90 度。","重複所需次數。"],"0421":["站直雙腳與肩同寬，單手握啞鈴，掌心朝前。","另一手扶大腿支撐。","上手臂固定，吐氣收縮二頭肌將啞鈴彎向肩前。","頂峰停留片刻，擠壓二頭肌。","吸氣慢慢降回，重複所需次數後換手。"],"0422":["雙腳與肩同寬站立，單手持啞鈴，另一手扶在斜凳上支撐。","上手臂固定，吐氣彎舉啞鈴收縮二頭肌。","頂端停留片刻，吸氣慢慢降回。","重複所需次數後換手。"],"0423":["雙腳分開與肩同寬站立，單手持啞鈴推過頭頂。","上手臂靠近頭部固定。","手肘彎曲將啞鈴慢慢降向後腦勺。","停頓片刻，三頭肌發力推回頭頂。","重複所需次數後換手。"],"0424":["雙腳與肩同寬站立，單手持啞鈴於肩高，掌心朝內（中立對握）。","收緊核心背打直。","向上推舉啞鈴至手臂完全伸展。","最高點稍作停頓，慢慢放回肩部。","重複所需次數後換手。"],"0425":["站直雙腳與肩同寬，單手正握持啞鈴（掌心朝下）。","手臂貼身自然下垂。","上手臂固定不動，手腕前臂發力將啞鈴彎向肩膀。","頂端停留片刻，慢慢降回。","重複所需次數後換手。"],"0426":["雙腳分開與肩同寬站立，雙手持啞鈴於肩高，掌心朝前。","向上推舉啞鈴，手臂完全伸展過頭頂（站姿啞鈴肩推）。","頂端停頓片刻，慢慢降回肩部。","重複所需次數。"],"0427":["雙腳與肩同寬站立，手持啞鈴置於肩高，掌心相對。","核心收緊背打直，向上推舉啞鈴過頭頂。","頂端停頓片刻，慢慢放回肩前。","重複所需次數。"],"0428":["站直雙腳與肩同寬，背靠在牆面或斜板上，手持啞鈴掌心朝前。","上手臂貼緊靠板固定，吐氣彎舉啞鈴收縮二頭肌。","舉至二頭肌完全收縮、啞鈴與肩同高。","頂峰停留片刻，吸氣慢慢放回。","重複所需次數。"],"0429":["站直雙腳與肩同寬，雙手持啞鈴垂於體側，掌心朝向軀幹。","上手臂固定在身側，吐氣彎舉啞鈴（站姿啞鈴錘式彎舉）。","舉至啞鈴與肩同高，頂峰擠壓二頭肌。","吸氣慢慢降回體側。","重複所需次數。"],"0430":["雙腳與肩同寬站立，單手握啞鈴推過頭頂。","手肘彎曲將啞鈴降向後頸，上手臂固定不動。","三頭肌發力將啞鈴推回頭頂。","重複所需次數後換手。"],"0431":["站在踏台或長凳前，雙手持啞鈴垂於體側。","右腳踏上長凳，全腳掌踩實。","踩穩右腳跟蹬起身體，完全展開右腿髖膝站直在台上。","左腳踏上併攏，隨後左腳先退下回地面。","重複所需次數後換腿。"],"0432":["雙腳與肩同寬站立，雙手正握持啞鈴置於大腿前。","背部打直核心收緊，屈髖將臀部向後推，膝微彎下放啞鈴（啞鈴羅馬尼亞硬舉）。","下沉至感受大腿後側拉伸，臀肌發力蹬直站回。","重複所需次數。"],"0433":["平躺在平凳上，雙手合握一個啞鈴推直於胸前。","手臂微屈打直，呈弧線將啞鈴慢慢降向頭後。","停頓片刻，胸背發力拉回胸前正上方。","重複所需次數。"],"0434":["雙腳與肩同寬站立，雙手正握持啞鈴。","背打直核心收緊，屈髖向前俯身，膝蓋維持微屈打直（啞鈴直腿硬舉）。","啞鈴沿著腿部下放至感受大腿後側極度拉伸。","在底部稍作停頓，臀大肌與腿後肌發力挺身站回。","重複所需次數。"],"0435":["將健身球靠在牆上，下背貼著球。","雙手在身前握住啞鈴，雙腳寬站，腳尖朝外。","往下深蹲，讓球順著背部往上滾動。","蹲到大腿約與地面平行。","腳跟推地站起。","膝蓋保持對齊腳尖方向。"],"0436":["坐在平凳上，雙手持啞鈴於肩高，掌心相對。","推起時旋轉手腕使掌心朝前。","推至頂端手臂打直，然後慢慢降回肩部。","手腕轉回掌心相對，重複所需次數。"],"0437":["雙腳分開與肩同寬站立，雙手正握持啞鈴垂於大腿前。","手臂自然伸直。","背打直核心收緊，吐氣以手肘引導將啞鈴垂直提拉至下巴高度（啞鈴直立划船）。","手肘高於手腕，在頂峰停頓片刻。","吸氣慢慢降回大腿前。","重複所需次數。"],"0438":["坐在重訓椅上，雙手持啞鈴置於肩高，掌心朝前。","手肘微朝前收，向上推舉啞鈴過頭頂。","降回肩部高度，重複所需次數。"],"0439":["站直雙手持啞鈴垂於體側。","手肘貼身旋轉前臂使掌心朝前。","二頭肌發力將啞鈴彎舉至肩前。","在頂端旋轉手腕使掌心朝外。","慢慢放回啞鈴，手腕順勢轉回原位。","重複所需次數。"],"0443":["平躺在墊子上，雙膝彎曲雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","腹肌發力將上半身捲離地面，同時轉體右肘碰左膝。","左膝同時向胸口靠攏（對角線捲腹）。","頂端停頓片刻，慢慢放回。","換左肘碰右膝重複，交替進行至指定次數。"],"0445":["雙腳與肩同寬站立，正握抓槓置於鎖骨前。","槓鈴維持在肩部高度，手肘微屈向前。","將槓鈴推過頭頂，雙臂完全伸展（槓鈴肩推）。","慢慢降回肩部高度，重複所需次數。"],"0446":["站直雙腳與肩同寬，反手抓槓，握距與肩同寬。","手肘貼緊軀幹，上手臂固定不動。","將槓鈴向上彎舉向肩膀，收縮二頭肌。","頂端停頓片刻，慢慢降回槓鈴。","重複所需次數。"],"0447":["站直雙腳分開與肩同寬，反手握住 EZ 槓，掌心朝上。","手肘緊貼身體兩側，上手臂固定。","吐氣將槓鈴向上彎舉向肩膀，收縮二頭肌。","頂峰停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0448":["躺在下斜長凳上，頭低腳高。","窄握抓住 EZ 槓，掌心朝向腳部。","手臂垂直伸展於胸前，手肘貼身。","手肘彎曲將槓鈴降向前額上方（下斜 EZ 槓碎顱者）。","停頓片刻，三頭肌發力推回頂端。","重複所需次數。"],"0449":["重訓椅調整至 45 度上斜。","背靠椅背坐好，正握抓 EZ 槓推過頭頂。","手肘靠近頭部固定，手肘彎曲將槓鈴降向後腦勺。","停頓片刻，伸展三頭肌推回頭頂。","重複所需次數。"],"0450":["平躺在平凳上，雙腳踩實，背貼椅面。","正握抓槓鈴，握距略窄於肩寬（窄握臥推）。","慢慢將槓鈴降向胸部，手肘貼近軀幹。","三頭肌發力推回頂端，手臂伸展。","重複所需次數。"],"0451":["站直雙腳與肩同寬，反手抓握 EZ 槓。","手肘貼緊軀幹，上手臂固定。","吐氣收縮二頭肌將槓鈴向上彎舉。","舉至二頭肌完全收縮、槓鈴與肩同高。","頂峰停頓片刻，吸氣慢慢降回。","重複所需次數。"],"0452":["坐在牧師椅上，胸靠支撐墊，雙腳踩實。","反手抓握 EZ 槓，握距與肩同寬。","上手臂貼在斜墊上，雙臂伸展。","上手臂固定不動，吐氣將槓鈴向上彎舉至肩前。","頂端停頓片刻，吸氣慢慢降回。","重複所需次數。"],"0453":["坐在重訓椅上，背部挺直，雙腳平踩。","正握抓握 EZ 槓，握距與肩同寬，推過頭頂。","上手臂固定，手肘彎曲將槓鈴降向後頸。","停頓片刻，手臂向上伸直推回頂端。","重複所需次數。"],"0454":["雙腳與肩同寬站立，反手握槓，掌心朝上。","上手臂靠在抗力球或牧師墊上支撐。","上手臂固定，吐氣彎舉槓鈴向肩膀。","頂端停頓片刻，擠壓二頭肌。","吸氣慢慢放回。","重複所需次數。"],"0455":["坐在重訓椅上，雙腳踩實，反手握槓，掌心朝上。","前臂平放在大腿上，手腕懸空。","手腕放鬆讓槓鈴滾向指尖，隨後指尖收攏將槓鈴捲回掌心並屈腕。","頂端收縮片刻，慢慢放回。","重複所需次數。"],"0456":["平躺，雙膝彎曲雙腳平踩。","雙手抱頭手肘朝外。","收緊腹肌，將上半身捲離地面至 45 度。","同時雙腿抬離地面，屈膝拉向胸部。","頂峰停頓片刻，慢慢降回上半身與雙腿。","重複所需次數。"],"0457":["平躺，雙腿伸直，雙臂伸直高舉過頭頂。","收緊腹肌，同時將上半身與雙腿向天花板抬起（V 字折刀捲腹 V-Up）。","雙手伸向腳尖碰觸。","在頂點呈 V 字形停頓片刻，慢慢降回地面。","重複所需次數。"],"0458":["平躺在地面上，雙膝彎曲雙腳踩地。","正握抓槓，推直於胸口正上方。","慢慢將槓鈴降向胸部兩側，手肘微屈展開。","大臂觸地時停頓片刻（地板臥推 Floor Press），胸肌發力推回正上方。","重複所需次數。"],"0459":["平躺在墊子上，雙腿伸展，雙手墊在臀部下方。","收緊核心，雙腿打直抬離地面約 15 公分。","雙腿維持完全伸直，快速交替上下踢動（剪刀腳打水 Flutter Kicks）。","持續進行至指定次數或時間。"],"0461":["雙腳站得比肩寬，腳尖朝外。","往下深蹲，雙手放在兩膝之間。","用力往上跳起。","輕柔落地並直接回到深蹲姿勢。","保持挺胸，膝蓋朝外打開。","組間短暫休息。"],"0462":["坐姿或站姿保持挺直，肩膀放鬆。","下巴慢慢往胸口靠，直到感覺脖子後側有伸展感。","停留 20 到 30 秒。","抬起頭，慢慢往後仰看向天花板。","在舒適的範圍內停留 20 到 30 秒。","動作放慢，維持自然呼吸。"],"0463":["俯臥，用前臂撐起身體，手肘在肩膀正下方。","腳尖點地，將髖部與膝蓋抬離地面。","從頭到腳跟保持一直線。","收緊腹肌與臀肌。","維持平穩呼吸，撐住 20 到 60 秒。","髖部不要往下掉或往上翹。"],"0464":["高棒式姿勢開始，雙手在肩膀正下方，身體呈一直線。","核心收緊，骨盆維持水平。","將軀幹向右旋轉，抬起右臂垂直伸向天花板成側棒式。","停頓片刻，放回高棒式。","換向左旋轉，左臂伸向天花板。","兩側交替進行至所需次數。"],"0466":["面向單槓站立，雙手正握抓槓，握距略寬於肩寬。","身體懸掛伸展，挺胸將胸骨直接拉向單槓（胸骨引體向上 Sternum Chin-up）。","拉起時上半身大幅後仰，使胸口接觸橫槓。","頂端停留片刻，慢慢降回懸掛。","重複所需次數。"],"0467":["雙腳與肩同寬站立，正握抓單槓，握距略寬於肩寬。","完全懸掛雙臂伸直，掌心朝外。","收緊核心，背肌發力挺胸將身體拉向單槓，直到下巴超過橫槓。","頂峰停頓片刻，慢慢降回懸掛。","重複所需次數。"],"0468":["從高棒式開始，雙手在肩膀正下方。","胸口朝地面下放，同時將單腳膝蓋往對側手肘靠近。","往上推起身體，同時將腿收原位。","換另一隻腳重複。","核心保持收緊。","維持穩定的節奏。"],"0469":["平躺在地上，雙膝彎曲雙腳踩實。","雙手輕扶後腦勺，手肘展開。","腹肌發力收緊，雙膝彎曲拉向胸前，將下背捲離地面。","頂端停頓片刻，慢慢放回雙腳。","重複所需次數。"],"0470":["仰臥屈膝，雙手放在腦後。","抬起肩膀，同時抬起一側膝蓋。","將對側手伸向抬起的膝蓋。","放下身體，換邊重複。","下背保持貼地。","不要用手拉扯脖子。"],"0471":["在牆壁前雙手撐地與肩同寬。","雙腳蹬牆成倒立姿勢，身體打直。","手肘微收彎曲，將頭頂向地面放低（倒立伏地挺身 Handstand Push-up）。","肩膀與三頭肌發力推地伸直手臂回到倒立頂端。","重複所需次數。"],"0472":["正握抓住單槓懸掛，雙臂完全伸展。","收緊核心，雙腿伸直併攏抬向身前（懸垂直腿抬腿 Hanging Leg Raise）。","持續抬起直到雙腿與地面平行或更高。","頂端停頓片刻，慢慢放回雙腿。","重複所需次數。"],"0473":["正手抓單槓懸掛，雙臂伸展。","收緊核心，保持雙腿伸直，將雙腿抬至腳尖觸碰單槓（腳尖碰槓 Toes to Bar）。","頂峰停頓片刻，有控制地慢慢放回。","重複所需次數。"],"0474":["懸掛在單槓上，雙臂伸直，掌心朝外。","啟動核心，雙腿打直抬至平行地面。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0475":["懸掛在單槓上，手臂完全伸展。","收緊核心將雙腿向前打直抬起至平行地面。","頂端停頓片刻，緩慢降回。","重複所需次數。"],"0476":["懸掛在單槓上，雙臂伸直雙腿下垂。","收緊核心將雙腿向前抬至平行地面。","隨後將骨盆向一側轉動，雙腿擺向側邊（懸垂雨刷式）。","回正，換向另一側擺動。","交替進行至所需次數。"],"0479":["站在穩固的長凳或階梯前。","單腳整個腳掌踩上去。","踩穩的腳用力推，站上平台並將另一腳膝蓋高高抬起。","控制速度慢慢踩回地面。","軀幹保持挺直。","重複動作，完成後換腳。"],"0480":["站直，雙手放在腦後。","單腳高抬膝，同時扭轉軀幹讓對側手肘碰到膝蓋。","放下並換邊進行。","保持輕快穩定的節奏。","用前腳掌輕柔落地。","持續做 30 到 60 秒。"],"0481":["站直，雙手準備配合擺動。","原地跑並將膝蓋高高抬起。","切換成腳跟往後踢向臀部。","兩種動作交替進行。","步伐保持輕盈。","持續做 30 到 60 秒。"],"0482":["仰臥屈膝，雙腿抬起至髖部上方。","雙手放在身體兩側。","將膝蓋往胸口帶，把髖部捲離地面。","在頂點稍作停留。","慢慢放回起始位置。","用腹肌發力，不要靠甩腿。"],"0484":["平躺，雙膝彎曲，雙腳踩實地面。","手臂置於身側，掌心朝下。","啟動臀肌與核心，將臀部推離地面直到膝髖肩成一直線（臀橋）。","頂峰停頓片刻，慢慢放回。","重複所需次數。"],"0485":["仰臥屈膝，雙腳踩平。","雙手放在身體兩側。","腳跟推地，將髖部朝天花板抬起。","在頂點夾緊臀肌。","慢慢放回地面。","肋骨下壓，避免過度拱腰。"],"0486":["仰臥屈膝，雙腳踩平。","雙手放在身體兩側。","腳跟推地將髖部抬起。","在頂點夾緊臀肌。","慢慢放下。","肋骨下壓，脖子保持放鬆。"],"0487":["仰臥，雙腿抬起並保持屈膝。","雙手放在身體兩側或墊在髖部下方。","將膝蓋往胸口帶，把髖部捲離地面。","在頂點短暫停留。","控制速度放下。","避免借用慣性。"],"0488":["調整羅馬椅機台，髖部平貼靠墊，雙腳卡緊固定。","雙手交叉抱胸或輕扶後腦勺。","慢慢向前俯身下沉，背部維持平直。","在最低點停頓片刻，隨後背肌發力挺起上半身至與雙腿成一直線。","重複所需次數。"],"0489":["調整羅馬椅伸展機（挺背機），使大腿貼在靠墊上，雙腳固定。","雙臂交叉抱胸或抱頭。","背部維持平直，從髖部向前俯身下沉。","底部感受拉伸停頓片刻，臀大肌與豎脊肌發力挺起至身體成一直線。","重複所需次數。"],"0490":["雙手撐在跳箱或踏台上，間距略寬於肩寬（上斜伏地挺身）。","雙腿向後伸展，前腳掌點地，身體成一直線。","手肘微收彎曲，將胸部降向支撐面。","底部停頓片刻，手臂推直回到起始位置。","重複所需次數。"],"0491":["躺在上斜板上，背部貼緊椅面，雙腿在身前伸直。","雙手握住頭頂上方固定架維持穩定。","腹肌發力收緊，將雙腿打直向上抬起（上斜仰臥抬腿）。","頂端稍作停頓，慢慢降回雙腿。","重複所需次數。"],"0492":["雙手撐在跳箱或長凳邊緣，間距與肩同寬。","身體打直退後成高棒式。","手肘彎曲進行一次伏地挺身。","推起瞬間爆發力推離跳箱落地，再跳上跳箱。","重複進行指定次數。"],"0493":["雙手撐在踏台或長凳邊緣，握距略寬於肩。","雙腿向後伸直成高棒式，身體成一直線。","手肘微收彎曲降下胸部貼近踏台。","底部停頓片刻，手臂推直將自己撐回頂端。","重複所需次數。"],"0494":["雙手撐在跳箱邊緣，間距略寬於肩寬。","身體呈一直線，手肘貼近軀幹彎曲下沉。","底部停留片刻，推直雙臂推回起始位置。","重複所需次數。"],"0495":["重訓椅調整至 45 度上斜。","躺在椅上，雙腳扣緊固定架。","雙手抱頭或交叉胸前。","收緊腹肌將上半身捲離椅面，同時轉體將手肘拉向對側膝蓋。","頂端停頓片刻，慢慢放回。","換向另一側旋轉捲腹重複。","交替進行至所需次數。"],"0496":["趴在重訓椅上，髖部置於凳緣，雙腿向後伸直懸空。","雙手抓緊凳身固定。","大腿維持打直，收縮腿後肌群將小腿向上彎曲向臀部（俯臥腿彎舉）。","頂峰停頓片刻，慢慢放回。","重複所需次數。"],"0497":["史密斯槓調整在腰部高度。","面對槓鈴站立正握抓槓，雙手與肩同寬。","雙腳向前走，身體向後傾斜躺下成斜板懸掛。","背肌發力挺胸將胸部拉向槓鈴，肩胛骨夾緊。","最高點停頓片刻，慢慢降回。","重複所需次數。"],"0498":["TRX 懸吊繩調整在胸部高度。","面對錨點站立，正握抓把手。","雙腳向前走身體向後仰躺成適當斜度。","收緊核心維持軀幹平直。","肩胛後縮屈肘將胸部拉向把手。","頂端停留片刻，緩慢降回。","重複所需次數。"],"0499":["腰部高度架設橫槓或使用 TRX 懸吊繩。","仰臥躺在橫槓下方，正握抓槓，握距略寬於肩寬。","腳跟著地，身體維持一條直線。","兩側肩胛骨夾緊屈肘，將胸口拉向橫槓（澳洲引體向上）。","頂端停留片刻，慢慢降回。","重複所需次數。"],"0500":["平躺在墊子上，雙臂向兩側水平展開貼地。","收緊核心，雙腿打直併攏垂直抬向天花板。","慢慢將雙腿向一側倒向地面，在受控範圍內盡可能貼近地面（鐘擺擺腿）。","停頓片刻，核心發力將雙腿拉回正中。","換向另一側倒地重複。","雙側交替進行至所需次數。"],"0501":["站立姿勢開始，雙腳與肩同寬。","下沉進入深蹲，雙手在身前撐地。","雙腳向後蹬跳成高棒式。","完成一次標準伏地挺身。","雙腳向前跳回雙手後方成深蹲。","雙腿蹬地爆發力向上起跳，雙手在頭頂拍手（波比跳 Burpee）。","輕巧落地順勢沉入深蹲，重複進行。"],"0502":["仰臥，雙腿伸直，雙手往頭頂方向延伸。","收緊腹肌，下背貼緊地面。","雙手與雙腿同時抬起，從髖部對摺身體。","在頂點讓雙手盡量碰到腳尖。","控制速度放下，直到手腳懸空略高於地面。","動作保持流暢，不要靠甩動借力。"],"0503":["採伏地挺身姿勢，將小腿或雙腳放在健身球上。","雙手在肩膀正下方，身體保持一直線。","將球往雙手方向滾動，同時把髖部朝天花板抬高。","雙腿盡量保持伸直，用腹肌出力帶動。","在頂點短暫停留。","將球滾回原本的棒式位置，下背不要往下掉。"],"0504":["站直，雙手各拿一個啞鈴舉在肩膀高度。","雙腳往外跳開，同時將啞鈴推舉過頭。","手臂伸直但不要拱腰。","雙腳跳回併攏，同時將啞鈴放回肩膀。","用前腳掌輕柔落地。","整組動作保持穩定節奏。"],"0505":["仰臥，雙手往頭頂延伸，雙腿併攏。","往上捲腹時同時抬起肩膀與雙腿。","雙腿往兩側大步張開，雙手往前伸向雙腿之間。","躺回時將雙腿併攏。","下背保持貼地。","以平穩流暢的節奏重複。"],"0507":["平躺，雙腿伸展，雙臂高舉過頭頂。","啟動核心，上半身與雙腿同時向上抬起，雙手觸碰腳尖（V 字折刀捲腹）。","頂端停頓片刻，慢慢降回地面。","重複所需次數。"],"0508":["平躺，雙膝彎曲雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，將上半身捲離地面至 45 度（捲腹）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"0510":["站直，雙腳併攏準備。","跨出成弓步，後腳膝蓋朝地面下放。","往上跳起並在空中換腳，落地時換邊成弓步。","再次跳起，落地時雙腳張開、雙手擺過頭頂，做成開合跳。","雙腳跳回併攏，回到起始位置。","輕柔落地並保持挺胸。"],"0513":["雙腳分開與肩同寬站立。","屈膝屈髖下沉成深蹲。","爆發力向上起跳，完全展髖展膝。","前腳掌輕盈著地，隨即下沉回到深蹲。","重複所需次數。"],"0514":["雙腳與肩同寬站立。","屈膝屈髖向後下蹲進入深蹲。","在深蹲底部踩穩腳跟，爆發力向上起跳騰空（深蹲跳 Jump Squat）。","前臂向前平舉維持平衡。","前腳掌輕巧著地緩衝，順勢沉入下一次深蹲。","重複所需次數。"],"0517":["雙腳分開寬於肩寬，腳尖微外展。","右手持壺鈴推直過頭頂，掌心朝前。","左腳微轉向右側，重心移至左腿。","眼睛注視壺鈴，屈髖前傾，軀幹慢慢向左下方側屈下沉（壺鈴風車 Kettlebell Windmill）。","右臂始終垂直於地面，左手沿左腿向下摸向地面。","感受左大腿後側拉伸，停頓片刻。","核心發力挺身站回原位。","重複所需次數後換邊。"],"0518":["雙腳與肩同寬站立，雙手各持一壺鈴垂於身前。","膝微屈屈髖前傾，挺胸背打直。","手臂伸直，壺鈴垂在雙腿之間。","爆發力展髖挺身，聳肩將壺鈴向上提拉。","壺鈴升至胸高時翻轉手腕，穩穩將壺鈴架在肩胸前成架槓姿勢（壺鈴上架 Kettlebell Clean）。","放回身前，交替手臂重複進行。"],"0519":["仰臥平躺在地板上，雙膝彎曲雙腳踩地。","雙手各握一壺鈴推直於胸前，掌心朝前。","單手將壺鈴降向胸側，另一臂維持推直固定。","胸肌發力推起降下的壺鈴，同時將另一手放低（地板交替壺鈴推胸）。","雙手流暢交替進行推胸。"],"0520":["雙腳與肩同寬站立，雙手各持一壺鈴置於肩前架槓位置。","單手將壺鈴推過頭頂，手臂完全伸展。","放回肩前，換另一手推舉。","雙手交替推舉進行至所需次數。"],"0521":["高棒式姿勢開始，雙手各抓一壺鈴握把撐地，雙腳與臀同寬。","核心收緊，骨盆維持水平穩定。","背肌發力將單側壺鈴向上拉向胸側，手肘貼身（壺鈴叛逆划船 Renegade Row）。","放回地面，換另一手向上划船。","雙側交替進行至所需次數。"],"0522":["雙腳與肩同寬站立，膝微屈，雙手持壺鈴垂於身前。","屈髖前傾，背部維持平直，核心收緊。","背肌發力將單側壺鈴拉向胸側，肩胛骨向內夾緊。","放回身前，換另一側手臂拉起。","雙手交替進行至所需次數。"],"0523":["雙腳分開與肩同寬站立，雙手持壺鈴於肩前，掌心朝向自己。","啟動核心將壺鈴向上推舉過頭頂，推舉時旋轉手腕使掌心轉向正前方。","動作頂點稍作停頓，慢慢放回肩前轉回原位。","重複所需次數。"],"0524":["雙腳與肩同寬站立，右手握壺鈴推直過頭頂鎖定。","軀幹微向左側旋轉，重心移向左腳。","屈左膝下沉，維持右臂伸直垂直天花板。","視線注視壺鈴，挺胸下沉至左手觸地。","左腳蹬地伸膝展髖站起，挺髖回正。","重複所需次數後換邊。"],"0525":["雙腳與肩同寬站立，單手握壺鈴垂在雙腿之間。","膝微屈屈髖前傾，挺胸背打直。","爆發力展髖伸膝，將壺鈴向上提拉。","翻轉壺鈴時手掌扣緊，使壺底垂直朝天花板保持平衡（底朝上抓上架 Bottoms-up Clean）。","在肩部高度穩住平衡片刻，放回身前。","重複所需次數後換手。"],"0526":["雙腳與肩同寬站立，雙手握壺鈴垂於大腿前。","膝微屈屈髖前傾，背部打直挺胸。","爆發力展髖蹬腿，聳肩將壺鈴向上高拉。","達最高點後翻腕將壺鈴接在胸肩架槓處。","放回身前，重複所需次數。"],"0527":["雙腳與肩同寬站立，雙手持壺鈴置於肩部架槓位置。","膝微屈下沉藉力，隨後雙腿爆發性蹬直，順勢將壺鈴推過頭頂（壺鈴挺舉 Jerk）。","在頂端快速屈膝鑽入壺鈴下方鎖定雙臂。","雙腿蹬直站穩在頂端。","慢慢將壺鈴收回肩前，重複進行。"],"0528":["雙腳與肩同寬站立，手持壺鈴於肩高。","膝蓋微屈啟動核心。","爆發力展髖蹬腿將壺鈴推過頭頂（借力推舉 Push Press）。","頂端雙臂打直鎖定。","屈肘將壺鈴降回肩部，重複進行。"],"0529":["雙腳與肩同寬站立，雙手持壺鈴垂於大腿前。","膝微屈屈髖前傾，背部平直挺胸。","爆發力展髖蹬腿，手臂打直將壺鈴向上拉起。","達肩高時翻轉手腕，將壺鈴直接擊向頭頂並鎖定手肘（壺鈴抓舉 Snatch）。","控制著放回身前，重複所需次數。"],"0530":["雙腳與肩同寬站立，右手握壺鈴高舉過頭。","眼睛注視壺鈴，維持右臂垂直地面。","左腳轉向 45 度，右腳轉向 90 度。","屈髖向左俯身下沉，右手維持伸直推向天花板。","右手指向天花板，左手向下摸向左腳踝（壺鈴風車）。","停頓片刻，核心發力挺身站回原位。","重複所需次數後換邊。"],"0531":["仰臥平躺在地板上，雙膝彎曲雙腳踩地。","單手持壺鈴垂直推向天花板，手腕打直鎖定。","控制速度將壺鈴慢慢降回胸側。","底部停頓片刻，推回頂端。","重複所需次數後換手。"],"0532":["雙腳與肩同寬站立，單手持壺鈴垂於身前。","屈膝屈髖下蹲前傾，背部打直。","將壺鈴穿過胯下繞至身後換手接住。","經身側繞回前方再穿過另一側胯下交接（壺鈴跨下繞八字 Figure 8）。","流暢維持均勻節奏，重複指定次數。"],"0533":["雙腳分開與肩同寬站立，腳尖微朝外。","雙手托住壺鈴置於胸前（高腳杯深蹲 Goblet Squat）。","挺胸收腹，屈髖後坐下蹲進入深蹲。","下蹲至大腿與地面平行或略低。","踩穩腳跟蹬起，頂峰夾緊臀部。","重複所需次數。"],"0534":["雙腳與肩同寬站立，雙手抱壺鈴緊貼胸口。","挺胸收腹，屈膝屈髖下沉成深蹲。","蹲至大腿平行地面或略低。","底部停頓片刻，腳跟推地站回。","重複所需次數。"],"0535":["雙腳與肩同寬站立，壺鈴置於身前大腿高度。","屈膝屈髖前傾，將壺鈴向後擺過胯下。","爆發力展髖挺身，將壺鈴向上擺起至肩高。","順勢翻腕將壺鈴接在肩前架槓位置（壺鈴上架）。","放回胯下擺盪，重複進行。"],"0536":["雙腳與肩同寬站立，雙手持壺鈴於胸前。","右腳向前跨步成弓箭步。","下沉時將壺鈴從右大腿下方穿過交給左手。","右腳蹬地推回站姿，壺鈴順勢收回。","換左腳前跨成弓箭步，壺鈴穿過左大腿下方交給右手。","雙腿交替進行至所需次數。"],"0537":["雙腳與肩同寬站立，單手抓握壺鈴。","屈膝屈髖，將壺鈴向後擺入胯下蓄力。","爆發力展髖、展膝與展踝，將壺鈴向上強力擺動。","達肩高時翻腕向上出拳將壺鈴鎖定在頭頂上方（單手抓舉 Snatch）。","控制著降回胯下，重複所需次數後換手。"],"0538":["雙腳與肩同寬站立，單手持壺鈴於肩前架槓。","膝微屈下沉蓄力，收緊核心。","雙腿蹬直並爆發力將壺鈴垂直推過頭頂。","隨後快速屈膝鑽入壺鈴下方鎖定手臂。","雙腿伸直站起，完全挺髖。","慢慢放回肩部，重複進行。"],"0539":["雙腳與肩同寬站立，單手持壺鈴於肩前。","核心收緊背打直。","單臂將壺鈴垂直推過頭頂，手臂完全伸展。","頂端停頓片刻，慢慢放回肩前。","重複所需次數後換手。"],"0540":["雙腳與肩同寬站立，單手握壺鈴於肩前。","膝蓋微屈下沉蓄力，隨後蹬腿借力將壺鈴推過頭頂（單手借力推舉 Push Press）。","慢慢降回肩部，順勢屈膝吸收衝擊力。","重複所需次數後換手。"],"0541":["雙腳與肩同寬站立，單手正握持壺鈴。","屈膝屈髖前傾，背部維持平直，核心收緊。","背肌發力將壺鈴拉向胸側，手肘貼身，肩胛骨向內夾緊。","頂端停頓片刻，慢慢放回身前。","重複所需次數後換手。"],"0542":["雙腳與肩同寬站立，單手握壺鈴置於雙腿間。","膝微屈屈髖下放壺鈴。","爆發力展髖伸腿，順勢將壺鈴拉向肩膀。","向上翻腕將壺鈴推直過頭頂鎖定（單臂高拉上挺）。","放回雙腿間，重複進行。"],"0543":["雙腳與肩同寬站立，單手持壺鈴於體側。","屈膝屈髖，背部維持平直。","將壺鈴提至肩高，手肘貼身。","雙臂完全伸展推過頭頂。","降回肩部高度，重複所需次數後換手。"],"0544":["雙腳與肩同寬站立，雙手在胸前托住壺鈴。","左腿向前打直懸空。","單腿屈膝下沉進入深蹲（壺鈴手槍深蹲 Pistol Squat），右腳踩平。","深蹲底部稍作停頓，右腳跟蹬地推回站姿。","重複所需次數後換腿。"],"0545":["高棒式姿勢開始，雙手各抓一壺鈴握把撐地。","手肘微收彎曲，將胸部降向兩壺鈴之間。","雙手爆發力推地撐起，使雙手短暫推離壺鈴握把。","輕巧穩穩抓回壺鈴上，隨即沉入下一次伏地挺身。","重複所需次數。"],"0546":["坐在重訓椅上，背部挺直雙腳踩平。","雙手持壺鈴於肩高，掌心朝前。","向上推舉壺鈴過頭頂，手臂伸展。","降回肩部高度，重複所需次數。"],"0547":["雙腳與肩同寬站立，雙手持壺鈴於肩前。","單手將壺鈴推過頭頂，另一手維持在肩部。","降回推舉的手臂，同時將另一手推過頭頂（站姿壺鈴蹺蹺板推舉 Seesaw Press）。","流暢交替進行推舉動作至指定次數。"],"0548":["雙腳開立寬於肩寬，腳尖朝外（相撲站姿）。","雙手垂握壺鈴於雙腿間，雙臂伸展。","屈膝下蹲將臀部沉下，背部打直。","腳跟蹬地爆發力展髖伸膝，將壺鈴垂直拉向上胸鎖骨處，手肘抬高外展（壺鈴相撲硬舉高拉 SDHP）。","放回兩腿間，重複所需次數。"],"0549":["雙腳分開與肩同寬站立，腳尖微外展。","雙手合握一個壺鈴垂於身前。","微屈膝蓋，屈髖將臀部向後推，將壺鈴後擺穿過胯下。","利用臀大肌與大腿後側爆發力向前挺髖，將壺鈴擺盪至胸肩高度（雙手壺鈴擺盪 Kettlebell Swing）。","讓壺鈴順勢下落擺回胯下，流暢銜接重複進行。"],"0550":["雙腳與肩同寬站立，雙手在胸前托住壺鈴。","挺胸收腹，屈膝屈髖下蹲成深蹲。","在深蹲底部踩穩腳跟爆發力蹬起，順勢將壺鈴垂直推過頭頂（火箭推 Thruster）。","頂端雙臂完全伸展鎖定。","壺鈴放回胸前同時順勢沉入下一次深蹲。","重複所需次數。"],"0551":["仰臥平躺，右手持壺鈴垂直推向天花板鎖定（土耳其起立 Turkish Get-up）。","右膝彎曲右腳踩地，左臂向外側展開撐地。","右腳推地轉體，用左前臂撐起上半身，隨後撐上左手掌。","抬高臀部挺髖成橋式，將左腿穿過身體向後收成跪姿。","軀幹直立成單膝跪姿，始終注視上方壺鈴。","雙腿蹬起站立直立。","依反向軌跡慢慢跪回、坐回並躺回地面。","換左手持壺鈴重複操作。"],"0552":["雙腳與肩同寬站立，雙手持壺鈴垂於大腿前。","膝微屈屈髖前傾，壺鈴降至膝蓋下方。","爆發力展髖挺身，將壺鈴拉向肩部。","快速翻腕將壺鈴接在肩前架槓位置（雙手壺鈴上架）。","放回身前，重複所需次數。"],"0553":["雙腳分開與肩同寬站立，雙手握壺鈴於肩高，掌心朝前。","收緊核心將壺鈴向上推舉過頭頂，手臂伸展。","頂端停頓片刻，慢慢降回肩部。","重複所需次數。"],"0554":["雙腳與肩同寬站立，右手握壺鈴高舉過頭。","左腳轉向 45 度，右腳朝前。","軀幹向左側側屈，右手手臂維持垂直天花板，眼睛看著壺鈴。","盡可能側向下沉摸向地面，維持右臂伸直。","停頓片刻，側腹與臀肌發力挺身回原位。","重複所需次數後換邊。"],"0555":["坐在椅子邊緣，雙腿向前伸直懸空。","雙手扶在椅子兩側支撐。","收縮腿後肌群，屈膝將小腿向後彎向座椅下方。","頂端停頓片刻，慢慢伸直雙腿。","重複所需次數。"],"0556":["採四足跪姿，雙手在肩膀正下方，雙膝在髖部正下方。","核心收緊，背部保持平直。","抬起一腿，膝蓋維持彎曲 90 度。","將腳底往天花板方向推，直到大腿與背部呈一直線。","在最高點夾緊臀肌。","穩定放下，完成該側所有次數後換邊。"],"0558":["正握抓單槓懸掛，雙手略寬於肩寬。","啟動核心前後輕微擺盪蓄力。","向前擺時用力挺胸將身體拉向單槓。","胸口貼近單槓時，手腕向下翻轉，將手肘翻上單槓上方，順勢將身體撐過單槓（暴力上槓 Muscle-up）。","在單槓上方推直雙臂鎖定，隨後控制速度緩慢下放回到懸掛。","重複所需次數。"],"0559":["仰臥，雙腿伸直。","彎曲一側膝蓋，雙手環抱小腿前側或大腿後側。","輕輕將膝蓋拉向胸口。","另一腿放鬆平貼地面。","停留 20 到 30 秒，保持緩慢呼吸。","放開並換邊。"],"0560":["單膝跪地，另一腳平踩在前方。","需要的話，在後側膝蓋下方墊軟墊。","骨盆後傾，並夾緊後腿的臀肌。","將髖部輕輕往前推，直到感覺髖部前側有伸展感。","停留 20 到 30 秒。","換腳重複。"],"0561":["跪在地板上，手掌貼地，手指朝向膝蓋。","手掌平貼地面，雙臂打直。","將髖部慢慢往後坐，加深伸展感。","感覺前臂內側有拉扯感時停住。","停留 20 到 30 秒。","輕輕放開，甩一甩雙手放鬆。"],"0562":["站立雙腳與肩同寬，雙手在胸前握住槓鈴套筒一端（地雷管轉體 Landmine Twist）。","膝微屈，將槓鈴向右側腰際下方斜向擺落。","達底部後反向發力向左上方揮轉，越過身體劃出圓弧帶向左側腰際。","持續以核心扭轉發力在兩側間流暢擺動。","重複所需次數。"],"0564":["站在穩固的跳箱或踏板旁。","雙膝微彎，雙臂往後擺。","往上並往側邊跳起，雙腳同時落在跳箱上。","屈膝輕柔落地，接著站直。","小心走下跳箱。","重複動作，完成後換邊起跳。"],"0565":["採微蹲的運動準備站姿，雙膝微彎。","靠對側腳蹬地，快速往側邊跨出一步。","後腳跟上收回，再往反方向跨出。","全程保持前腳掌著地。","抬頭挺胸，雙臂自然擺動。","以快速但受控的節奏完成這一組。"],"0567":["面對穩固的跳箱站立，雙腳與肩同寬。","下蹲約四分之一深蹲高度，雙臂往後擺。","往上跳起並轉動髖部，以側身姿勢落在跳箱上。","屈膝輕柔落地。","走下跳箱，重新站好。","每次交替旋轉方向。"],"0568":["側躺，將上方腿放在長凳上。","前臂貼地，置於肩膀正下方。","抬起髖部，讓身體呈一直線。","髖部保持上下對齊，核心收緊。","停留 20 到 30 秒。","放下身體，換邊重複。"],"0569":["仰臥，雙腿伸直，腳跟放在健身球上。","將髖部往上推，讓身體呈一直線。","彎曲膝蓋，將球拉向臀肌。","過程中保持髖部抬高。","在頂點稍作停留。","慢慢將球往外推回原位。"],"0570":["坐在平凳邊緣，雙腿向前伸直懸空。","雙手扶在臀部旁的凳緣支撐。","腹肌發力收緊，屈膝將雙腿拉向胸前（坐姿屈腿收腹 Seated In-and-Outs）。","頂端停頓片刻，慢慢伸展雙腿回到原位。","重複所需次數。"],"0571":["調整划船機座椅與踏板。","坐直背部挺直，雙腳踩在踏板上。","雙手抓握把手，掌心相對。","挺胸雙肩後展。","單側手把拉向軀幹，另一手維持前伸固定（坐姿機械交替划船）。","頂端夾緊肩胛骨，慢慢送回。","換另一手重複，交替進行至指定次數。"],"0572":["將引體向上輔助機調整至目標阻力。","站上輔助踏板，正握抓把手，握距略寬於肩。","雙臂伸展身體打直。","背肌發力挺胸將身體拉向上方把手。","持續拉至下巴超過把手高度。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0573":["調整機械挺背機至符合身材。","坐在機台上，背貼靠墊，雙腳踩實固定。","雙手握住兩側把手。","背部維持自然弧度，向前微俯身前傾。","底部感受下背拉伸，豎脊肌發力向後挺身挺起軀幹。","重複所需次數。"],"0574":["雙腳與肩同寬站立，膝微屈。","正握抓槓，握距略寬於肩寬。","屈髖前傾，背部維持平直挺胸。","背肌發力將槓鈴拉向下胸部，肩胛骨向內夾緊（俯身槓鈴划船）。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0575":["調整座椅高度，坐穩機台背靠椅墊。","反握抓住二頭彎舉機把手，掌心朝上，手肘貼緊襯墊。","吐氣收縮二頭肌將把手彎舉向上。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢放回，手臂伸展。","重複所需次數。"],"0576":["調整推胸機座椅高度，背貼靠墊。","正握抓把手，手肘呈 90 度。","吐氣向前推動把手至雙臂完全伸展。","頂峰停頓片刻，吸氣慢慢收回。","重複所需次數。"],"0577":["調整機械推胸機座椅高度，背貼靠墊。","正握抓住握把，手肘呈 90 度。","吐氣向前推展握把，直到手臂完全伸直（不鎖死）。","動作末端稍作停頓，吸氣慢慢放回胸前。","重複所需次數。"],"0578":["調整機械臀腿推蹬機座椅與踏板。","背靠靠墊坐穩，雙腳踩在腳踏板上。","手握把手維持穩定。","臀大肌與大腿發力推開踏板，手臂與背靠緊。","完全推伸處停頓片刻（膝蓋不鎖死）。","控制速度慢慢屈膝收回。","重複所需次數。"],"0579":["調整座椅高度，大腿卡入護墊下，雙腳踩實。","正握抓把手，握距略寬於肩寬。","坐直挺胸雙肩後展，下背自然微弓。","背闊肌發力將把手向下拉向胸前，肩胛骨夾緊。","底部停頓片刻，慢慢放回握把。","重複所需次數。"],"0580":["調整機械聳肩機座椅高度。","雙手對握抓住兩側把手，雙臂伸展。","背打直，吐氣將雙肩盡可能向上聳向耳朵。","頂峰收縮片刻，吸氣慢慢放回。","重複所需次數。"],"0581":["調整坐姿划船機座椅與踏板。","胸貼靠墊坐穩，雙腳踩實踏台。","正握抓把手，握距略寬於肩。","背部挺直核心收緊。","將把手拉向軀幹，肩胛骨向內用力夾緊。","頂端停留片刻，慢慢放回把手。","重複所需次數。"],"0582":["調整機械腿彎舉機，雙膝跪在墊上，腳踝卡在滾輪下。","雙手抓把手維持穩定。","上半身固定不動，吐氣收縮腿後肌群將小腿向臀部拉近。","頂峰停頓片刻，擠壓腿後腱。","吸氣慢慢放回，膝蓋充分伸展。","重複所需次數。"],"0583":["調整座椅高度，坐上軀幹旋轉機（Torso Rotation Machine）。","雙手抓緊把手維持上半身穩定。","核心肌群發力，慢慢將軀幹向一側旋轉至極限。","停頓片刻，慢慢旋轉回正。","換向另一側旋轉。","雙側交替進行至所需次數。"],"0584":["調整機械側平舉機座椅，背靠靠墊。","正握抓住握把，手臂維持伸展。","吐氣將雙臂向兩側抬起至平行地面。","頂端停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0585":["調整機械腿伸展機（Leg Extension）椅背與滾輪墊位置。","背靠椅背坐穩，小腿前側抵在滾輪墊後方。","雙手握緊兩側把手維持骨盆穩定。","股四頭肌發力伸膝蹬起滾輪墊，直到雙腿完全伸直。","頂端停頓片刻，強力收縮大腿前側。","慢慢屈膝放回起始位置。","重複所需次數。"],"0586":["調整俯臥腿彎舉機（Lying Leg Curl），趴在機台上，腳後跟卡在滾輪墊下方。","雙手抓握把手固定骨盆。","骨盆貼緊墊面，吐氣收縮腿後肌群將滾輪向上拉向臀部。","頂峰停留片刻，強力擠壓大腿後側。","吸氣慢慢降回滾輪墊。","重複所需次數。"],"0587":["調整機械肩推機座椅高度。","背靠靠背坐穩，正握抓握把，雙手間距略寬於肩。","向上推動握把至手臂完全伸展（手肘不鎖死）。","頂峰停頓片刻，慢慢放回肩部高度。","重複所需次數。"],"0588":["調整坐姿划船機座椅與踏板。","坐直，雙腳踩在腳踏板上，膝微彎。","抓緊把手掌心相對。","背打直微向前傾。","將把手拉向軀幹，肩胛骨向內夾緊。","頂端稍作停頓，慢慢放回把手。","重複所需次數。"],"0589":["雙腳與肩同寬站立，膝微屈正握抓槓。","屈髖前傾，挺胸抬頭。","槓鈴垂在身前手臂完全伸展。","手肘貼身將槓鈴拉向胸腹，肩胛骨向內夾緊。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0590":["調整座椅高度，坐穩機台背貼靠墊。","單手抓住推舉握把，手肘呈 90 度。","向上推展把手，直到手臂在頭頂伸直。","頂端停頓片刻，慢慢降回。","重複所需次數後換手。"],"0591":["調整雙槓撐體機台配重與高度。","正握抓住把手，雙臂打直支撐全身重量。","屈肘下沉身體，上手臂貼近身側。","下沉至上手臂平行地面。","稍作停頓，三頭肌發力推直雙臂撐回頂端。","重複所需次數。"],"0592":["調整座椅高度，坐上機械牧師椅彎舉機。","上手臂平放在斜墊上，反手握住把手。","背部維持打直，手肘固定在墊上。","吐氣將前臂向肩膀彎舉，收縮二頭肌。","頂端停留片刻，擠壓二頭肌。","吸氣慢慢放回把手。","重複所需次數。"],"0593":["調整羅馬椅伸展機，雙腳卡緊腳墊。","俯臥趴在機台上，髖部置於墊緣，雙手抱頭或交叉胸前。","腿後腱與臀肌發力，將雙腿向上抬起至與地面平行（反向超人式）。","頂峰停頓片刻，慢慢降回。","重複所需次數。"],"0594":["調整座椅高度，膝微屈，雙腳平踩踏板。","前腳掌踩在踏台邊緣，腳跟完全懸空。","手握把手維持穩定。","小腿發力蹬起前腳掌，盡可能抬高腳跟。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0595":["調整機械捲腹機座椅與胸部護墊位置。","背貼靠墊坐穩，雙腳踩平。","雙手抓住把手或扶桿。","腹肌發力收縮，向前捲動胸口靠向大腿。","頂峰用力收縮腹肌停留片刻。","慢慢放回起始位置。","重複所需次數。"],"0596":["調整蝴蝶機（Pec Deck）座椅高度，背貼靠墊坐穩。","手前臂貼在護墊上或握住把手，手肘微屈。","吐氣胸大肌發力將兩側把手向身前合攏夾胸。","在胸前合攏處用力擠壓胸肌停留片刻。","吸氣慢慢向兩側張開，感受胸部拉伸。","重複所需次數。"],"0597":["調整機械髖外展機（Hip Abduction）座椅，膝蓋呈 90 度。","背靠靠背坐穩，雙腳踩在腳踏板上。","抓住兩側把手維持骨盆穩定。","臀中肌發力將雙膝向外張開，對抗阻力。","外展到底停頓片刻，慢慢收回。","重複所需次數。"],"0598":["調整機械髖內收機（Hip Adduction）座椅。","坐穩靠緊椅背，雙腳踩在踏板上。","大腿內收肌群發力，慢慢將雙腿向內夾攏。","頂端用力夾緊大腿內側停頓片刻。","控制阻力慢慢向兩側張開。","重複所需次數。"],"0599":["調整坐姿腿彎舉機（Seated Leg Curl），背靠椅背坐穩。","小腿後側卡在滾輪墊上方，調整上方大腿固定墊壓緊。","抓住兩側把手支撐。","吐氣收縮腿後腱，屈膝將滾輪向後下方踩拉至大腿下方。","頂峰停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0600":["坐在機械收腹機上，雙腳踩在踏板上。","抓緊把手維持支撐。","收緊腹肌，同時將雙腿向胸部收起並向前捲動軀幹。","頂端停留片刻，慢慢放回雙腿與軀幹。","重複所需次數。"],"0601":["調整機台座椅，胸貼靠墊，雙腳踩平。","對握抓把手（掌心相對），手肘微屈。","吐氣兩側肩胛骨夾緊，將把手向後向外拉開（蝴蝶機反向飛鳥）。","頂峰收縮停頓片刻，吸氣慢慢放回。","重複所需次數。"],"0602":["調整反向飛鳥機座椅高度，胸部貼靠胸墊，雙腳踩平。","正握抓住把手，手肘微屈。","後三角肌發力將肩胛骨夾緊，向後向外張開手臂。","動作末端停頓片刻，慢慢放回。","重複所需次數。"],"0603":["調整座椅高度，坐穩機台背靠椅背。","正握抓把手置於肩部高度。","向上推動握把至手臂伸展（不鎖死手肘）。","頂端停頓片刻，慢慢放回肩部。","重複所需次數。"],"0604":["調整機械聳肩機座椅，背靠靠墊。","正握抓住握把，手臂維持伸展。","保持背部打直，雙肩向上聳向耳朵。","頂端收縮片刻，慢慢降回肩膀。","重複所需次數。"],"0605":["調整站姿提踵機肩墊高度，站上踏台。","肩膀鑽入肩墊下方扛起重量，手握把手。","伸展腳踝將腳跟盡可能抬高，小腿強烈收縮。","頂峰停頓片刻，慢慢放低腳跟至深層拉伸處。","重複所需次數。"],"0606":["調整機械划船機座椅與踏板。","胸貼靠墊坐穩，雙腳踩實踏板。","正握抓握把，握距略寬於肩寬。","背部維持挺直，核心收緊。","將把手拉向軀幹，肩胛骨向內用力夾緊。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0607":["調整機台座椅，坐穩背靠椅墊。","正握抓把手，雙臂在身前向前伸展。","上手臂固定不動，手肘彎曲將把手降向前額方向。","底部停頓片刻，伸展三頭肌推回。","重複所需次數。"],"0608":["坐在器材上，調整靠墊固定好軀幹。","握住握把，髖部保持朝向正前方。","穩定將軀幹轉向一側。","在動作底端稍作停留。","回到中間，再轉向另一側。","動作放慢，避免靠慣性甩動。"],"0609":["高位纜繩接上長繩。","背對錨點站立，雙腳與肩同寬。","正握抓繩索，掌心朝下。","身體微前傾，背部維持平直。","將繩索拉向身體，肩胛骨向內夾緊。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"0610":["從半蹲姿勢開始，雙手放在胸前。","身體保持壓低，雙腳往外跳開。","雙腳跳回併攏，膝蓋維持彎曲。","抬頭挺胸，重心放在腳跟。","全程維持在深蹲高度。","以穩定節奏持續 30 到 60 秒。"],"0611":["站直，雙腳併攏。","單腳往後跨出成弓步，後膝朝地面放低。","雙手撐地，前腳往後退成棒式。","身體下壓做一下伏地挺身，再推回原位。","單腳往前踩回弓步姿勢，接著站起。","每次交替跨步的腿。"],"0612":["站直，雙腳與髖同寬。","單腳往前跨出一大步。","放低髖部，直到雙膝都彎曲約 90 度。","軀幹保持直立，前膝對齊腳踝上方。","前腳跟踩地發力，推回站姿。","重複動作並換腳。"],"0613":["側躺在地面上，雙腿打直。","彎曲上側腿，手向後抓住腳踝。","輕輕將腳踝拉向臀部，感受大腿前側（股四頭肌）拉伸。","保持拉伸 20-30 秒。","放鬆換邊重複。"],"0614":["俯臥，雙臂放在身體兩側或墊在額頭下方。","雙腿伸直，髖部貼平地面。","夾緊臀肌，將一腿抬離地面。","穩定放下。","抬起另一腿，左右交替。","避免過度拱起下背。"],"0615":["仰臥，雙臂往兩側平放。","彎曲一側膝蓋，跨過身體。","讓膝蓋朝對側地面自然下沉。","雙肩保持平貼地面。","停留 20 到 30 秒。","換邊。"],"0616":["仰臥在長凳或床沿。","將一側膝蓋拉向胸口抱住。","讓另一腿在邊緣外自然放鬆垂下。","下背保持平貼。","停留 20 到 30 秒。","換腳。"],"0617":["側躺，雙腿伸直並上下疊放。","頭靠在手臂上，核心保持收緊。","將上方腿往天花板方向抬起。","腳尖保持朝向正前方。","慢慢放下，不要碰到下方腿。","完成所有次數後換邊。"],"0619":["仰臥，雙腿伸直。","收緊腹肌，將下背往下壓平。","將一腿伸直抬起到約略髖部高度。","慢慢往地面放下。","另一腿保持平貼。","完成設定次數後換腳。"],"0620":["平躺在平凳上，背部緊貼椅面。","雙手墊在臀部下方支撐下背。","保持雙腿伸直併攏，將雙腿抬向天花板（平凳仰臥抬腿）。","頂峰停留片刻，慢慢降回至接近水平懸空。","重複所需次數。"],"0621":["仰臥，雙手放在頭後方。","將雙腿抬離地面幾吋。","將雙肩往上捲起。","雙腿做剪刀式交叉，一腿跨在另一腿上方。","下背保持壓緊地面。","每次交替哪一腿在上方。"],"0622":["仰臥，雙手墊在髖部下方。","將雙腿抬離地面幾吋。","一腿抬高，另一腿保持壓低。","以順暢的剪刀式動作交替雙腿高低。","下背保持緊貼地面。","全程保持穩定呼吸。"],"0623":["仰臥，雙臂放在身體兩側。","一腿往天花板方向抬起，另一腿懸空靠近地面。","雙腿同時上下交換位置。","雙腿大致保持伸直。","將下背壓緊地面。","以受控的節奏移動。"],"0624":["背靠牆站立，雙腳分開與臀同寬。","背部沿牆面下滑下蹲，直到膝蓋呈 90 度（靠牆靜蹲 Wall Sit）。","維持靜蹲姿勢，右腳離地抬膝拉向胸前。","放回右腳，換左腳離地抬膝拉向胸前。","雙腿交替抬膝進行至指定次數。"],"0625":["面對牆壁坐在地板上，雙膝彎曲，手持藥球。","身體後傾，將背部放低到地面。","坐起並將球擲向牆壁。","接住反彈回來的球。","穩定躺回地面。","重複設定的次數。"],"0627":["反手抓握單槓（掌心朝向自己），握距略寬於肩寬。","雙臂伸展懸掛，雙腳離地。","啟動背肌與二頭肌，挺胸將身體拉向單槓。","持續拉至下巴超過橫槓。","頂端停頓片刻，控制速度慢慢降回懸掛。","重複所需次數。"],"0628":["阻力帶套在腳踝上。","雙腳與肩同寬站立，膝蓋微彎呈半蹲。","右腳向右側邁出一大步，拉緊阻力帶。","左腳跟進向右跨步，維持阻力帶張力（螃蟹步/彈力帶側跨步走）。","持續側向邁步至指定距離後換邊。"],"0629":["從棒式開始，雙手在肩膀正下方。","單腳往前踩到手掌外側。","放低髖部，感受弓步伸展。","將腳退回棒式位置。","換腳。","核心保持收緊，以穩定節奏進行。"],"0630":["高棒式姿勢開始，雙手在肩膀正下方，身體呈一直線。","收緊核心將右膝快速提向胸前，隨後快速換左膝提向胸前（登山者式 Mountain Climbers）。","如同跑步般流暢交替雙腿，核心收緊骨盆不上下顛簸。","全程維持均勻呼吸與穩定快頻率。","持續進行至指定次數或時間。"],"0631":["抓握單槓懸掛，雙臂完全伸展。","啟動核心挺胸將身體拉向單槓。","拉到頂峰時迅速變換握法為反握（掌心朝向自己）。","持續向上拉直到胸口觸碰單槓。","控制速度緩慢下放回到懸掛。","重複所需次數。"],"0632":["仰臥，雙腳併攏放在長凳上。","雙膝彎曲，雙臂放在身體兩側。","腳跟發力往下踩，抬起髖部。","在頂點夾緊臀肌。","稍作停留。","慢慢放下。"],"0633":["跪在瑜珈墊上，身體前傾讓頭頂輕靠地面。","雙手撐地輔助支撐。","身體慢慢前後微幅搖動，讓頸部承受一點重量。","動作幅度保持小且受控。","回到起始位置，組間充分休息。","切勿彈震，初期讓雙手分擔大部分重量。"],"0634":["平躺，雙膝彎曲，雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，將上半身捲離地面至約 45 度（捲腹）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"0635":["仰臥平躺，雙膝彎曲雙腳平踩。","雙手抱頭或交叉在胸前。","腹肌發力收縮將肩胛骨抬離地面，同時轉動軀幹向一側（旋轉捲腹）。","稍作停頓，慢慢放回地板。","換向另一側重複，交替進行。"],"0636":["站直雙腳與肩同寬，正手抓握奧林匹克槓鈴，垂於大腿前。","手臂自然下垂伸直。","上手臂固定不動，吐氣彎舉槓鈴收縮二頭肌。","舉至二頭肌完全收縮、槓鈴與肩同高。","頂峰停頓片刻，吸氣慢慢降回。","重複所需次數。"],"0637":["雙腳與肩同寬站立，正握抓槓推過頭頂。","雙臂伸直，上手臂靠近頭部。","手肘彎曲將槓鈴慢慢降至後腦勺下方。","停頓片刻，三頭肌發力推回頭頂。","重複所需次數。"],"0638":["面對單槓站立，雙腳與肩同寬。","單手反握抓槓，另一手抓住該側手腕提供輔助支撐（單手輔助引體向上）。","完全伸展手臂懸掛，核心收緊身體打直。","背肌與二頭肌發力將身體向上拉起。","拉至下巴過槓，慢慢降回懸掛。","重複所需次數後換手。"],"0639":["背對椅子或重訓椅站立，雙腳與肩同寬。","單手撐在身後椅子邊緣，另一手叉腰。","雙腿向前伸展，腳跟著地。","手肘彎曲下沉身體貼近椅緣（單手椅子撐體）。","底部停頓片刻，單手發力推直回頂端。","重複所需次數後換手。"],"0640":["雙腳與肩同寬站立，單手持藥球於腰前。","膝微屈收緊核心。","單手將藥球高舉過頭頂。","運用全身力量將藥球重重砸向地面（單手藥球砸地）。","接住彈起的藥球，重複所需次數後換手。"],"0641":["平躺，雙膝彎曲，雙腳踩實。","雙手扶後腦勺手肘朝外。","收緊腹肌，將上半身捲離地面至 45 度。","頂端停留片刻，慢慢降回。","重複所需次數。"],"0642":["高棒式姿勢開始，雙手略寬於肩，雙腳併攏。","手肘彎曲下沉身體進行伏地挺身，同時單側腿向外踢出展開。","推回高棒式同時收回腿。","再次下沉伏地挺身，換另一腿向外踢出。","伏地挺身結合側踢腿交替進行。"],"0643":["站姿或坐姿挺直，雙腳分開與肩同寬。","單臂向上伸過頭頂，屈肘將手伸向對側肩胛骨。","另一手扶在屈曲的手肘上，輕輕向頭部後方加壓，拉伸三頭肌。","保持拉伸 15-30 秒，然後放鬆。","換另一側手臂重複。"],"0647":["背靠牆面站立，雙腳與肩同寬。","往下蹲成靠牆坐姿，讓大腿平行地面。","雙腳用力踩地，向上爆發跳起。","膝蓋微彎，輕柔落地。","直接蹲回靠牆坐姿並重複動作。","保持挺胸，落地時放輕聲音。"],"0648":["槓鈴置於身前地面，雙腳與肩同寬。","屈髖屈膝俯身，正握抓槓略寬於肩。","伸膝展髖拉起槓鈴，槓鈴貼身滑動。","達大腿中部時，爆發性展髖挺身，聳肩高拉槓鈴。","槓鈴達最高點時快速鑽入槓下翻腕接槓，成前蹲姿勢架在肩前（爆發力翻鈴 Power Clean）。","蹬腿站直完全展髖。","控制速度放回地面，重複所需次數。"],"0649":["側躺，將上方腿的膝蓋彎曲。","把下方腳拉向臀肌。","將上方膝蓋往身後的地面方向轉。","保持肩膀放鬆。","停留 20 到 30 秒。","換邊重複。"],"0650":["坐在抗力球上，雙膝呈 90 度雙腳踩平。","雙手扶在抗力球兩側支撐。","腹肌發力收緊，雙腿離地將膝蓋抱向胸前。","頂端停留片刻，慢慢伸展雙腿放回。","重複所需次數。"],"0651":["以中立握法（掌心相對）抓住引體向上握把，雙臂伸展懸掛。","啟動核心，肩胛骨向內夾緊。","手肘向下向後拉，將身體向上拉向握把。","持續拉至下巴超過握把高度。","頂端停頓片刻，慢慢降回懸掛。","重複所需次數。"],"0652":["懸掛在單槓上，手臂完全伸展，掌心朝外。","啟動核心，肩胛骨夾緊。","手肘彎曲挺胸將身體拉向單槓。","頂端停頓片刻，慢慢降回懸掛。","重複所需次數。"],"0653":["將 BOSU 半圓平衡球平放地面，平坦面朝上。","雙手抓住 BOSU 球外緣，擺出高棒式姿勢。","手肘微收彎曲下沉身體，核心收緊。","雙臂推直，撐回頂端。","重複所需次數。"],"0654":["以棒式姿勢開始，雙手在肩膀正下方。","身體下放做伏地挺身。","推起身體回到原位。","將單邊膝蓋拉向胸口。","把腳退回棒式位置。","每次交替換腿。"],"0655":["抗力球放地上，雙手與肩同寬撐在球面上。","雙腿向後伸展成高棒式，腳尖點地支撐。","手肘微收彎曲，將胸部降向抗力球，維持身體一直線。","底部停頓片刻，手臂推直推回高棒式。","重複所需次數。"],"0656":["抗力球放地上，雙手撐在球面上與肩同寬。","雙腿後伸打直成高棒式。","手肘彎曲下沉胸部貼球。","底部停留片刻，推直手臂回到原位。","重複所需次數。"],"0657":["擺好伏地挺身姿勢，一手放健身球上、一手撐地。","身體保持一直線。","胸口朝地面下放。","將身體推回原位。","核心保持收緊。","完成設定次數後，換另一手放球上。"],"0658":["面對牆壁站立約一臂遠。","雙手撐在牆面上與肩同高，略寬於肩。","雙腳向後退一步，身體打直。","核心收緊維持身體成一直線。","手肘彎曲下沉胸部貼近牆壁。","停頓片刻，推回起始站姿。","重複所需次數。"],"0659":["面對牆壁約一步距離站立。","雙手撐在與肩同高的牆面上，間距略寬於肩。","雙腳向後退兩步，身體成一斜直線。","手肘彎曲將胸部降向牆面（推牆伏地挺身 Wall Push-up）。","推回起始位置，雙臂伸展。","重複所需次數。"],"0660":["雙手各握一啞鈴置於肩下撐地，擺出高棒式。","手肘微收貼身彎曲，將胸部降向地面。","掌心推地伸直手臂回到頂端。","重複所需次數。"],"0661":["高棒式姿勢開始，雙手間距略寬於肩，雙腳併攏。","手肘彎曲下沉進行伏地挺身。","推起時順勢將單側腿向上向外踢出伸展。","放回腳尖再進行下一次伏地挺身，換另一腿踢出。","伏地挺身結合交替側踢腿進行。"],"0662":["高棒式姿勢開始，雙手間距略寬於肩，雙腳併攏。","手肘微收彎曲，將胸口沉向地面，身體呈一直線。","胸部快貼地時稍作停頓，掌心推地推回起始位置。","重複所需次數。"],"0663":["高棒式姿勢開始，雙手在肩下方撐在抗力球上。","手肘微收彎曲，背部打直核心收緊，胸部沉向球體。","掌心推地伸直雙臂推回頂端。","重複所需次數。"],"0664":["高棒式姿勢開始，雙手與肩同寬，身體成一直線。","手肘彎曲下沉進行伏地挺身。","推起回高棒式後，重心移至左手，身體向右旋轉成側棒式，右臂垂直伸向天花板。","維持側棒式數秒，轉回高棒式。","再次伏地挺身後換向左旋轉成側棒式。","交替進行至所需次數。"],"0665":["進入棒式，雙手擺成 W 字形。","從頭到腳跟保持一直線。","胸口朝地面下放。","手肘微向外開。","將身體推回原位。","重複動作，過程別讓髖部下塌。"],"0666":["伏地挺身預備姿勢開始，雙手略寬於肩，雙腳併攏。","單臂向側邊水平打直伸出（弓箭手伏地挺身）。","彎曲支撐側手肘下沉身體，背部打直。","胸肌發力推回頂端。","換另一臂向側邊打直重複。"],"0667":["以伏地挺身姿勢開始。","將一腿抬離地面。","胸口朝地面下放。","將身體推起，保持髖部不扭轉。","身體維持一直線。","每組換抬另一條腿。"],"0668":["平躺在地上，雙腳踩實地面，雙膝彎曲。","雙臂放於身側，掌心朝下。","收緊臀肌與腿後腱，將骨盆推離地面直到膝髖肩成一直線（臀橋）。","頂峰維持數秒，慢慢放回地面。","重複所需次數。"],"0669":["站直雙腳與肩同寬。","將右臂橫越胸前，左手扶在右肘處（十字交叉拉伸）。","輕輕將右臂拉向左胸，感受右後三角肌與肩部拉伸。","保持拉伸 15-30 秒，然後放鬆。","換另一側手臂重複。"],"0670":["正握抓住單槓，握距略寬於肩寬。","雙臂伸直懸掛，身體成一直線。","背肌發力挺胸將身體拉向單槓，手肘貼身。","持續拉至下巴超過橫槓。","頂端停留片刻，慢慢降回懸掛。","重複所需次數。"],"0672":["雙手撐在雙槓上，雙臂伸展支撐全身重量。","手肘彎曲下沉身體，直到上手臂平行地面。","停頓片刻，手臂推直撐回頂端（雙槓撐體）。","重複所需次數。"],"0673":["調整座椅高度，坐穩下拉機，雙膝卡在大腿護墊下。","反手抓把手（掌心朝向自己），握距略寬於肩寬。","坐直挺胸雙肩後展。","手肘向下拉，將握把拉向上胸鎖骨處，肩胛骨夾緊。","底部停頓片刻，慢慢送回握把。","重複所需次數。"],"0674":["雙手與肩同寬反握抓住單槓（反手引體向上）。","雙臂完全伸展懸掛，身體維持直線。","背肌與二頭肌發力，挺胸將身體向上拉起。","拉至下巴超過單槓。","頂端停頓片刻，慢慢降回起始懸掛。","重複所需次數。"],"0675":["趴在抗力球上，髖部貼球，雙腿向後伸直。","雙手撐在身前地面維持穩定。","臀肌與腿後腱發力，將雙腿向天花板方向盡可能抬高（反向超人式）。","頂端停留片刻，慢慢降回。","重複所需次數。"],"0676":["站直，雙腳與髖部同寬。","單腿往後跨出，蹲入弓步。","前腳跟出力踩地站起。","將後腿往前踢出。","把腳放回身後，準備做下一次。","完成設定次數後換腿。"],"0677":["雙手撐在吊環上，雙臂完全伸展支撐全身重量。","手肘彎曲下沉身體，直到肩膀略低於手肘（吊環撐體 Ring Dips）。","三頭肌與胸肌發力推直手臂回到頂端。","重複所需次數。"],"0678":["站在單槓下，雙腳與肩同寬。","向上伸手正握抓單槓，握距略寬於肩寬。","完全伸展手臂懸掛，身體打直。","背闊肌發力將身體向上拉起。","頂端停頓片刻，緩慢降回。","重複所需次數。"],"0679":["仰臥，膝蓋彎曲，雙腳平踩地面。","骨盆往上捲，將脊椎一節一節抬離地面。","抬高至橋式位置。","在頂端稍作停留。","脊椎一節一節慢慢滾回地面。","動作放慢並保持呼吸。"],"0680":["面對攀爬繩站立，雙腳與肩同寬。","雙手抓緊繩索，掌心朝向自己。","膝微屈，啟動核心。","雙手交替向上抓握攀爬，雙腿夾繩蹬起輔助（攀繩訓練 Rope Climb）。","攀爬至目標高度。","下落時雙手交替向下滑動，受控降回地面。","重複所需次數。"],"0681":["以雙膝著地的伏地挺身姿勢開始。","胸口朝地面下放。","將身體推回原位。","轉動軀幹，將單手朝天花板舉起。","把手放回地面。","左右交替進行。"],"0683":["站直，雙腳併攏，雙手放在身體兩側。","雙腳跳開，同時將軀幹轉向一側。","雙腳跳回併攏。","重複動作並轉向另一側。","膝蓋保持微彎不鎖死。","維持穩定的節奏。"],"0684":["站直雙腳與臀同寬。","放鬆雙肩收緊核心。","原地輕鬆慢跑，抬起雙膝，雙臂前後擺動。","維持均勻步頻與呼吸，持續慢跑至指定時間。"],"0685":["站直雙腳與臀部同寬。","核心收緊，上半身放鬆。","原地慢跑，快速交替將膝蓋抬向胸前，前腳掌輕巧著地（原地高抬膝跑）。","維持穩定節奏，持續進行至指定時間。","全程維持深呼吸與挺胸體態。"],"0686":["上背靠在健身球上仰臥。","抬起髖部，讓身體像桌面一樣平坦。","雙手在胸前向上伸直。","將軀幹轉向一側。","回到中間，再轉向另一側。","全程保持髖部抬高。"],"0687":["坐在地上，雙膝彎曲，雙腳平踩地面。","身體微向後傾，背部打直核心收緊。","雙手在胸前抱拳或握藥球。","雙腳離地懸空以坐骨平衡。","軀幹向右旋轉將重物移向身體右側地面（俄羅斯轉體）。","稍作停頓，轉向左側將重物移向左側地面。","雙側交替進行至所需次數。"],"0688":["正握抓住單槓懸掛，雙臂完全伸展。","手臂維持完全打直，單靠肩胛骨下沉後收將身體微幅拉起（肩胛引體向上 Scapular Pull-up）。","頂端停留片刻感受中下斜方肌收縮，隨後放鬆降回完全懸掛。","重複所需次數。"],"0689":["坐在平凳上，背部挺直雙腳平踩。","雙手抓緊長凳兩側邊緣支撐。","保持雙腿伸直併攏，慢慢向前上方抬起至平行地面（平凳坐姿抬腿）。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0690":["坐在椅子邊緣，雙腳踩實。","雙手扶在大腿上支撐。","從髖部向前俯身前傾，背部維持打直。","感受下背伸展，維持 20-30 秒。","慢慢挺身坐直，重複所需次數。"],"0691":["坐在地上背靠牆面，雙腿向前伸展。","雙膝彎曲雙腳平踩地面。","雙手抱頭手肘朝外。","收緊腹肌向一側側屈，手肘靠近骨盆側邊。","停頓片刻，慢慢回正。","換向另一側側屈，交替進行至指定次數。"],"0692":["坐在地面，一腿伸直、另一腿彎曲。","背部保持延伸拉長。","從髖部往前傾，雙手朝腳趾延伸。","感覺到伸展感就停住。","停留 20 到 30 秒。","換腿重複。"],"0693":["坐在地面，單腿伸直。","用毛巾繞過前腳掌，或直接抓住腳趾。","將腳趾往身體方向拉。","膝蓋保持伸直。","停留 20 到 30 秒。","換腿重複。"],"0694":["在健身球上坐直，雙腳平踩地面。","雙手舉在胸前。","將軀幹轉向一側。","保持髖部朝向正前方。","回到中間，再轉向另一側。","動作放慢並保持穩定控制。"],"0696":["平躺在地上，雙腿伸展，腳跟踩在抗力球上。","收緊臀肌將骨盆推離地面成橋式。","維持臀部懸空，屈膝將抗力球向臀部方向勾拉（抗力球橋式腿彎舉）。","頂端擠壓腿後腱停頓片刻，慢慢伸腿推回球體。","降回臀部，重複所需次數。"],"0697":["平躺在平凳或墊子上，雙腿伸展。","雙手抓住頭頂凳緣或墊在臀部下方。","屈膝將大腿拉向胸前，抬起雙腳。","頂端停留片刻，慢慢伸展放回。","重複所需次數。"],"0698":["雙腳踩住彈力帶，與肩同寬。","雙手在肩膀高度握住彈力帶。","將雙手推過頭頂，直到手臂伸直。","核心保持收緊。","慢慢下放回到肩膀位置。","避免身體往後仰。"],"0699":["高棒式姿勢開始，雙手略寬於肩，身體呈一直線。","手肘微收彎曲下沉進行伏地挺身。","推起時右手離地輕拍左肩。","右手放回再進行一次伏地挺身，推起時左手離地輕拍右肩（伏地挺身拍肩 Push-up Shoulder Tap）。","全程核心收緊維持骨盆穩定。","交替進行至所需次數。"],"0700":["側躺在健身球上，雙腳抵穩固定。","雙手放在頭後。","順著球面將上半身往下放。","收縮腹斜肌將身體抬起。","保持髖部穩定。","完成設定次數後換邊。"],"0701":["側躺並將膝蓋彎曲。","前臂放在肩膀正下方。","將髖部抬離地面。","從膝蓋到頭部保持一直線。","停留 20 到 30 秒。","放下身體並換邊。"],"0702":["以前臂支撐的側棒式開始。","將上方腿稍微抬起。","把上方膝蓋拉向胸口。","將腿往後伸直。","保持髖部抬高。","完成設定次數後換邊。"],"0703":["以前臂支撐的側棒式開始。","身體保持一直線。","將上方腿朝天花板抬起。","短暫停留。","穩定控制將腿放下。","完成設定次數後換邊。"],"0705":["側躺在地上，雙腿打直疊放。","前臂撐地，手肘正對肩下方呈 90 度。","啟動核心將髖部抬離地面成側棒式，身體成一直線。","維持此姿勢至指定時間。","降回骨盆，換邊重複。"],"0706":["側躺，雙腿疊放。","手肘放在肩膀正下方。","抬起髖部，讓身體呈一直線。","收緊腹肌。","停留 20 到 30 秒。","放下身體並換邊。"],"0707":["側躺並將膝蓋彎曲。","雙手輕放在頭後。","將上半身與雙腿同時往中間抬起靠近。","收緊側腰。","慢慢下放。","完成設定次數後換邊。"],"0708":["仰臥，膝蓋彎曲並倒向一側。","雙手放在頭後。","向上捲腹，將肩膀抬離地面。","收緊側腰。","穩定控制下放。","完成設定次數後換邊。"],"0709":["站在雙槓之間，雙手撐在槓上撐起身體。","手臂伸直支撐全身重量。","收緊腹肌，雙腿打直慢慢向一側側向抬起。","頂端停頓片刻，慢慢放回。","重複所需次數後換向另一側。"],"0710":["雙腳與肩同寬站立，雙手叉腰。","重心移至單腿，另一腿向外側平舉抬起（站姿側抬腿）。","頂端停留片刻，慢慢放回。","換另一條腿重複，交替進行至所需次數。"],"0711":["雙腳寬距站立。","重心移向一側並彎曲該側膝蓋。","另一腿保持伸直。","保持挺胸。","停留 20 到 30 秒。","換邊重複。"],"0712":["側躺，雙腿伸直。","用下方手臂支撐頭部。","雙腳併攏同時抬離地面。","短暫停留。","慢慢放下。","完成設定次數後換邊。"],"0713":["坐直或站直，雙肩放鬆。","將頭傾倒，讓耳朵靠近單側肩膀。","對側肩膀保持往下壓。","停留 20 到 30 秒。","回到中間，換另一側重複。","不要用力拉扯頭部，輕放手掌的重量就夠了。"],"0714":["側躺並以前臂撐起身體。","雙腳疊放或前後交錯。","抬起髖部讓身體呈一直線。","核心保持收緊。","停留 20 到 30 秒。","換邊重複。"],"0715":["側躺，手肘在肩膀正下方，雙腿疊放。","抬起髖部，讓身體從頭到腳呈一直線。","髖部保持抬高，頸部維持自然中立。","停留 20 到 45 秒。","穩定下放身體並換邊。","別讓髖部下掉或往前翻。"],"0716":["站姿或坐姿挺直，雙肩放鬆。","頭慢慢倒向右側，右耳靠近右肩。","右手輕輕放在頭頂左側加壓拉伸。","保持拉伸 15-30 秒。","換左側重複拉伸，每側進行 2-3 組。"],"0717":["側躺在地上，雙腿打直疊放。","下方手掌撐在肩膀正下方。","手掌推地撐起身體成側棒式，雙腿伸直核心收緊。","上方手臂垂直伸向天花板成一直線。","有控制地下放身體回到地面。","重複所需次數後換邊。"],"0718":["仰臥，膝蓋彎曲。","雙手放在頭後。","起身時將單側手肘朝對側膝蓋延伸。","慢慢下放。","雙腳保持貼地。","左右交替進行。"],"0719":["側躺，下方手臂過頭延伸。","上方手放在頭後。","拉長側腰進行伸展。","捲起身體，讓上方手肘靠近髖部。","回到伸展位置。","換邊重複。"],"0720":["雙腳分開與肩同寬站立，膝微屈。","正握抓住單槓，雙手間距略寬於肩寬。","雙臂完全伸展懸掛，身體放鬆。","手肘向下彎曲將下巴拉向單槓，身體維持直線。","下巴過槓後控制速度慢慢降回懸掛。","重複所需次數。"],"0721":["雙腳與肩同寬站立，雙臂向前伸展。","右臂向前伸平，手腕向下屈曲使指尖朝下。","左手握住右手背，輕輕向內拉向身體，拉伸前臂伸肌。","保持拉伸 15-30 秒，然後放鬆。","換左手重複拉伸。"],"0722":["仰臥，膝蓋彎曲。","抬起髖部進入橋式。","雙腳往一側跨步或橫移。","回到中間。","左右交替進行。","保持髖部抬高。"],"0723":["仰臥，雙腿向上伸直。","雙手放在身體兩側。","將髖部抬離地面。","雙腿稍微傾向一側。","穩定控制下放。","左右交替進行。"],"0724":["仰臥，雙腿向上伸直。","雙手壓穩地面。","抬起髖部並往一側旋轉。","慢慢下放。","換往另一側重複。","雙腿保持伸直。"],"0725":["伏地挺身預備姿勢，一手間距正常，另一手向外放寬（偏重心伏地挺身）。","手肘彎曲下沉身體，背部打直。","下沉時重心偏向寬距側，另一臂微伸展打直。","推回高棒式，交替雙手位置進行。"],"0726":["仰臥，膝蓋彎曲。","將一腿伸直。","踩地腳的腳跟用力往下推，抬起髖部。","在頂端收緊臀肌。","穩定控制下放。","完成設定次數後換腿。"],"0727":["雙腳與臀同寬站立，單手持啞鈴。","單腳離地懸空，用另一腳單腳維持平衡。","小腿發力盡可能將腳跟抬高（單腳啞鈴提踵）。","頂峰停頓片刻，慢慢降回。","重複所需次數後換腳。"],"0728":["坐在健身球上，雙腳平踩地面。","保持軀幹挺直。","將一條腿往前伸直。","短暫停留。","把腳放回地面。","完成設定次數後換腿。"],"0730":["單腳踩在滑盤上，另一腳踩實地面。","支撐腳膝蓋微彎，滑盤腳向後平滑滑出成弓箭步（滑盤弓箭步）。","全程核心收緊，身軀直立。","前腳發力將後腳滑回起始位置。","重複所需次數後換腿。"],"0731":["背靠牆面往下滑，進入靠牆坐姿。","將重心移到單腳上。","抬起另一腿並在身前伸直。","背部平貼牆面，停留 10 到 30 秒。","放下腿休息，接著換邊。","支撐腿的膝蓋保持在腳踝正上方。"],"0733":["站在穩固的台階前。","將一隻腳完整踩上台階。","腳跟用力踩穩，將身體站起。","把另一隻腳也帶上台階。","慢慢往下退回地面。","完成設定次數後換腿。"],"0734":["背靠牆站立，雙腳往前走開。","身體順著牆面下滑，直到膝蓋彎曲約 90 度。","背部平貼牆面，重心放在腳跟。","維持姿勢並穩定呼吸。","停留 20 到 60 秒，再順著牆面滑回站姿完成動作。"],"0735":["平躺，雙膝彎曲，雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，將上半身捲離地面至約 45 度（捲腹）。","頂端稍作停頓，慢慢放回。","重複所需次數。"],"0736":["仰臥，膝蓋彎曲，雙腳平踩地面。","雙手抱胸，或將指尖輕放頭側。","將軀幹向上捲起，直到胸口靠近大腿。","穩定控制，慢慢躺回地面。","別用力拉扯脖子，以胸口帶動起身。"],"0738":["調整推腿機至 45 度角。","前腳掌踩在推腿滑台邊緣，腳尖朝前，腳跟完全懸空。","小腿發力蹬伸腳踝將滑台推開（45度推腿機提踵）。","頂端停頓片刻，慢慢放低腳跟感受深層拉伸。","重複所需次數。"],"0739":["調整推腿機座椅與踏板。","背靠椅背坐穩，雙腳與肩同寬踩在踏板中央。","握緊兩側把手維持穩定。","伸展雙腿推開踏板，腳跟始終踩實踏板（膝蓋不完全鎖死）。","頂端停頓片刻，慢慢屈膝將滑台收回。","重複所需次數。"],"0740":["調整推腿機至 45 度角。","坐穩靠緊椅背，雙腳開立寬於肩寬踩在踏板上（相撲寬距腿推）。","雙腿發力蹬開滑台伸直膝蓋。","頂端停留片刻，慢慢屈膝收回。","重複所需次數。"],"0741":["調整斜躺推腿機配重，背貼靠墊坐穩。","雙腳與肩同寬踩在平台上，腳尖微外展。","握住兩側安全把手維持穩定。","屈膝屈髖下沉身體，背部打直貼墊。","下沉至大腿平行踏板或略深。","底部停頓片刻，踩穩腳跟蹬腿推回頂端。","重複所需次數。"],"0742":["調整倒蹬機配重，前腳掌踩在平台下緣，腳跟懸空。","手握把手支撐。","小腿發力蹬起腳踝將平台推起。","動作最高點稍作停頓，慢慢降回腳跟。","重複所需次數。"],"0743":["調整哈克深蹲機（Hack Squat）高度與肩墊。","雙腳與肩同寬踩在踏板上，腳尖微朝外。","握住把手維持穩定。","屈膝屈髖向後下蹲，背部緊貼靠墊挺胸。","下沉至大腿與踏板平行或略深。","停頓片刻，踩穩腳跟發力推回頂端。","重複所需次數。"],"0744":["調整推腿機至舒適重量。","仰臥躺在推腿機上，雙腳踩在踏板上與肩同寬，腳尖微外展。","握住把手維持穩定。","收緊核心與臀肌，腳跟推地伸直雙腿推開滑台。","慢慢屈膝將滑台收回。","重複所需次數。"],"0746":["雙腳分開與肩同寬站立，膝蓋微屈。","正握抓住槓鈴，握距略寬於肩寬。","手臂伸直槓鈴垂於大腿前。","雙肩垂直向上聳向耳朵，在最高點擠壓斜方肌（槓鈴聳肩）。","維持收縮一秒，慢慢放回肩膀。","重複所需次數。"],"0747":["調整史密斯機座椅，使槓鈴位於肩部高度。","雙腳分開與肩同寬站立，膝微屈。","正握抓槓略寬於肩。","起槓將槓鈴降至後頸斜方肌上方。","垂直將槓鈴向上推過頭頂，雙臂完全伸展。","頂端停頓片刻，慢慢降回頸後。","重複所需次數。"],"0748":["史密斯槓調整在胸部高度。","平躺在平凳上，雙腳踩實地面。","正握抓槓，握距略寬於肩寬。","旋轉解鎖槓鈴降向胸部，手肘適度內收。","輕觸胸口時停頓片刻。","發力推回起始位置，雙臂完全伸展（史密斯臥推）。","重複所需次數。"],"0749":["雙腳與肩同寬站立，腳尖朝前。","史密斯槓架在上背部斜方肌上。","膝微屈，屈髖將臀部向後推，背部平直俯身（史密斯早安式）。","俯身至上半身平行地面，感受大腿後側拉伸。","臀肌與腿後腱發力挺身站回。","重複所需次數。"],"0750":["史密斯槓調整在肩部高度。","雙腳分開與肩同寬，腳尖微朝外。","槓鈴扛在斜方肌上背處。","屈膝屈髖下沉深蹲，挺胸收腹。","下蹲至大腿平行地面或略低。","停頓片刻，踩穩腳跟推回站姿（史密斯深蹲）。","重複所需次數。"],"0751":["調整重訓椅，使槓鈴在胸口上方。","窄握抓住史密斯槓，握距略窄於肩寬。","慢慢降向胸部，手肘貼身內收。","底部停頓片刻，三頭肌發力推回頂端（史密斯窄握臥推）。","重複所需次數。"],"0752":["史密斯槓調至約臀部/膝蓋高度。","雙腳與肩同寬站立，腳尖微外展。","屈髖屈膝俯身，正握抓槓略寬於肩。","伸膝展髖拉起槓鈴，槓鈴沿腿部直線上升（史密斯硬舉）。","站直時完全挺髖夾緊臀部。","慢慢屈髖將槓鈴放回起始高度。","重複所需次數。"],"0753":["調整重訓椅至下斜角度。","躺在下斜椅上，雙腳固定在腳墊下。","正握抓槓，握距略寬於肩。","解鎖槓鈴慢慢降向胸下緣，手肘微收。","底部停頓片刻，胸肌發力推回頂端（史密斯下斜臥推）。","重複所需次數。"],"0754":["史密斯機調整至下斜位置。","躺在下斜椅上，雙腳固定。","反握抓住槓鈴，握距略寬於肩。","解鎖槓鈴降向胸部，手肘內收。","底部稍作停頓，推回頂端。","重複所需次數。"],"0755":["調整史密斯槓高度至上背扛槓位置。","雙腳開立與肩同寬，腳尖微外展。","鑽入槓下扛在斜方肌上，握距略寬於肩。","旋轉解鎖槓鈴，核心收緊挺胸。","雙腳分開略寬於肩。","屈膝屈髖下蹲，挺胸背打直。","蹲至大腿平行地面或略低。","底部停頓片刻，踩穩腳跟推回站姿。","重複所需次數。"],"0756":["坐在史密斯機前的地面上，上背靠在平凳邊緣，雙腳踩實。","將槓鈴壓在髖部上方，雙手抓穩槓鈴。","啟動臀肌與核心，踩穩腳跟將骨盆推起直到膝髖肩成一直線（史密斯臀推）。","頂峰停頓片刻強力夾緊臀大肌，慢慢放回。","重複所需次數。"],"0757":["重訓椅調整為 30-45 度上斜。","躺在椅上，背貼椅背雙腳踩實。","正握抓槓略寬於肩。","解鎖槓鈴慢慢降向上胸部，手肘微收。","底部停頓片刻，胸肌發力推回頂端（史密斯上斜臥推）。","重複所需次數。"],"0758":["重訓椅調整至舒適上斜角度。","坐穩機台背貼靠墊，雙腳平踩。","正握抓槓，握距略寬於肩。","解鎖槓鈴慢慢降向胸前，手肘內收。","槓鈴接近胸部時停頓片刻。","胸大肌發力推回起始位置，雙臂伸展。","重複所需次數。"],"0759":["史密斯機調整至上斜推胸位置。","面對機台站立，雙腳與肩同寬。","正握抓槓，握距略寬於肩。","背部維持打直，核心收緊。","手肘引導將槓鈴向上推展。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0760":["調整史密斯椅位與踏板至舒適位置。","坐穩背貼椅背，雙腳與肩同寬踩在腳踏板上。","雙手抓住兩側把手維持穩定。","伸展雙腿，背靠椅墊，將踏板推離身體（史密斯倒蹬推腿）。","在完全伸展處停頓片刻（膝蓋不鎖死）。","慢慢彎曲膝蓋將踏板朝身體方向收回。","重複所需次數。"],"0761":["調整座椅高度，雙腳踩實地面。","正握抓把手，握距略窄於肩寬。","將把手拉向軀幹時挺胸背打直，兩側肩胛骨向內夾緊。","在動作頂端停留片刻，慢慢送回把手。","重複所需次數。"],"0762":["調整座椅高度，胸部貼靠胸墊，雙腳踩平。","正握抓住把手，握距略寬於肩。","將把手拉向胸口，肩胛骨向內用力夾緊，背部挺直收腹。","頂端停留片刻，慢慢放回握把。","重複所需次數。"],"0763":["史密斯槓調整至約膝蓋到臀部高度。","面對槓鈴站立，雙腳與臀部同寬，腳尖朝前。","前腳掌踩在踏台邊緣，腳跟完全懸空。","手扶槓鈴維持穩定支撐，背部打直核心收緊。","小腿發力盡可能將腳跟抬高（史密斯站姿提踵）。","頂峰停頓片刻，慢慢降回腳跟。","重複所需次數。"],"0764":["史密斯槓調至胸部高度。","面對槓鈴站立，雙腳與肩同寬。","正握抓槓略寬於肩寬，雙腳後退一步站成斜傾高棒式。","全程維持挺胸、身體成一直線。","手肘微收彎曲，將胸口沉向槓鈴（史密斯上斜伏地挺身/推胸）。","底部停頓片刻，推直雙臂推回頂端。","重複所需次數。"],"0765":["調整座椅高度，使把手位於肩部高度。","坐穩背貼靠墊，雙腳平踩。","正握抓把手推離固定架，手臂完全伸展。","慢慢將把手降至肩部高度，手肘微屈。","三角肌發力將把手推過頭頂，手臂伸展。","頂端停留片刻，慢慢降回肩部。","重複所需次數。"],"0766":["調整史密斯機座椅，雙腳與肩同寬踩實。","正握抓住槓鈴，握距略寬於肩。","起槓將槓鈴置於肩高鎖骨前，手肘朝前。","將槓鈴推過頭頂，手臂完全伸展（史密斯坐姿肩推）。","頂端稍作停頓，慢慢降回肩部高度。","重複所需次數。"],"0767":["雙腳與肩同寬站立，膝微屈。","正握抓槓，握距略寬於肩寬。","手臂伸直，雙肩放鬆。","雙肩垂直向上聳向耳朵，在頂峰擠壓斜方肌（史密斯聳肩）。","維持收縮片刻，慢慢放回肩膀。","重複所需次數。"],"0768":["站在史密斯槓前，雙腳與肩同寬。","單腳向後抬起，將腳尖搭在身後的橫槓或踏台上（史密斯保加利亞分腿蹲）。","手扶把手維持穩定。","前腿屈膝下沉成弓箭步，背部打直。","底部停頓片刻，前腳跟蹬地推回站姿。","重複所需次數後換腿。"],"0769":["史密斯槓調整在臀部高度。","背對機台站立，雙腳與肩同寬。","右腳向後退一步，將腳尖搭在史密斯槓上。","彎曲左膝下沉成弓箭步，背部挺直。","踩穩左腳跟蹬回站姿。","換另一側重複後跨步，交替進行至所需次數。"],"0770":["將史密斯槓調至適合上背扛槓的高度。","雙腳開立與肩同寬，腳尖微外展。","鑽入槓下將槓鈴穩穩置於斜方肌上，握距略寬於肩。","核心收緊，旋轉解鎖槓鈴。","挺胸背打直，屈膝屈髖下蹲深蹲。","下蹲至大腿平行地面或略低。","底部稍作停頓，踩穩腳跟蹬起回站姿（史密斯深蹲）。","重複所需次數。"],"0771":["面對史密斯機站立，雙腳與肩同寬。","正握抓槓（或反握），雙手與肩同寬。","上手臂貼身固定。","手腕向上屈起將槓鈴捲向前臂（史密斯腕彎舉）。","頂端停留片刻，慢慢放回。","重複所需次數。"],"0772":["調整史密斯座椅高度，使槓鈴位於肩部高度。","雙腳與肩同寬站立，膝微屈。","正握抓槓，握距略寬於肩。","起槓後將槓鈴置於後頸斜方肌上方。","全程收緊核心挺胸。","雙臂推直，完全將槓鈴推過頭頂（史密斯頸後肩推）。","頂端停留片刻，慢慢放回頸後。","重複所需次數。"],"0773":["史密斯槓調整至肩膀站立鑽入時的高度。","肩膀鑽入槓下扛槓，雙腳與肩同寬，腳尖朝前。","雙手扶槓維持穩定。","小腿發力將腳跟盡可能抬高，前腳掌點地（史密斯站姿提踵）。","頂峰停頓片刻，慢慢放回腳跟。","重複所需次數。"],"0774":["雙腳與肩同寬站立，膝蓋微彎。","正握抓槓，握距略寬於肩。","起槓置於胸肩高度，掌心朝前。","向上推舉槓鈴過頭頂，手臂伸展。","頂端停頓片刻，慢慢降回肩部。","重複所需次數。"],"0775":["雙腳與肩同寬站立，面對史密斯機。","正握抓槓，雙手間距略寬於肩寬。","背部挺直核心收緊。","手肘引導將槓鈴垂直向上提拉至鎖骨高度（史密斯直立划船）。","手肘高於手腕，頂端停留片刻，慢慢降回大腿前。","重複所需次數。"],"0776":["雙腳與肩同寬站立，槓鈴置於身前地面。","屈膝屈髖下蹲俯身，正握抓槓（寬握抓舉握距）。","蹬腿拉起槓鈴貼身滑動。","達大腿中段時爆發力挺髖展體，聳肩高拉。","迅速鑽入槓下深蹲，雙臂伸展在頭頂上方接住槓鈴（槓鈴抓舉 Snatch）。","在頭頂支撐槓鈴並蹬腿站直。","沿反向軌跡有控制地下放槓鈴回地面。","重複所需次數。"],"0777":["雙腳與肩同寬站立，單手持啞鈴。","膝微屈，屈髖前傾，背部打直。","啞鈴向下伸向對側腳踝，同時順勢旋轉軀幹（啞鈴轉體摸腳）。","回正，換邊重複進行。","雙側交替進行至所需次數。"],"0778":["伏地挺身預備姿勢，雙手略寬於肩，雙腳併攏。","將右膝向外向前提向右手肘（蜘蛛人伏地挺身 Spiderman Push-up）。","手肘彎曲下沉胸口貼地，同時維持右膝靠近手肘。","推回高棒式並收回右腿，換左膝提向左手肘重複。","雙腿交替進行至所需次數。"],"0781":["前後跨出一大步站立，一腳在前、一腳在後。","保持軀幹挺直，核心收緊。","雙膝彎曲往下蹲，直到後膝懸空並貼近地面。","前腳跟發力踩地，站回起始位置。","完成所有次數後換邊。"],"0782":["在地上想像一個正方形，站在其中一個角。","雙腳同時跳向下一個角，保持前腳掌輕巧點地。","依序沿著正方形的四個角繼續跳動。","落地時膝蓋微彎，放輕緩衝。","整組做到一半時換反方向跳。"],"0783":["雙腳與肩同寬站立，雙臂高舉過頭。","手臂保持在耳朵旁邊，肋骨下壓不外翻。","髖部往後往下坐，直到大腿約與地面平行。","腳跟踩穩地面，膝蓋朝腳尖方向對齊。","雙腳踩地發力，站直身體。"],"0784":["依動作設定放好彈力帶，雙腳與肩同寬站立。","收緊核心並保持挺胸。","髖部往後坐、彎曲膝蓋，往下進入深蹲。","膝蓋往外推，對抗彈力帶的拉力。","腳跟發力踩地站起。"],"0785":["從深蹲姿勢開始，雙手在胸前合攏。","身體維持低姿深蹲，雙腳往外跳開。","繼續保持低姿，雙腳跳回中間。","保持挺胸，膝蓋對齊腳尖方向。","以穩定、輕快的節奏持續動作。"],"0786":["槓鈴架在鎖骨前肩膀上，雙腳與肩同寬。","屈膝微下沉蓄力，挺胸背打直。","雙腿爆發性蹬直，順勢將槓鈴推過頭頂。","槓鈴升至最高點時，雙腿迅速前後分開剪刀步下沉接槓（挺舉分腿上挺 Split Jerk）。","在分腿姿勢下手肘鎖定支撐頭頂槓鈴。","前腳先退半步、後腳向前蹬回併攏站直。","槓鈴收回肩膀，重複所需次數。"],"0788":["雙腳與肩同寬站立，正握將槓鈴置於後頸處。","背部維持挺直，核心收緊。","伸展雙臂將槓鈴推過頭頂（頸後肩推 Behind-the-neck Press）。","頂端停留片刻，慢慢降回後頸。","重複所需次數。"],"0789":["站直身體，一腳往前伸，腳跟點地、腳尖朝上。","前腿保持伸直，後腿膝蓋微彎。","背部打直，從髖部往前傾，直到感覺大腿後側被拉開。","維持 20 到 30 秒。","換腳重複。"],"0790":["站直身體，需要時可以扶著固定物。","將重心移到一隻腳上，另一腳膝蓋彎曲。","將彎曲的膝蓋往側邊抬起，身體不要跟著歪斜。","有控制地放下。","完成所有次數後換邊。"],"0791":["站在牆壁或椅子旁以維持平衡，身體站直。","髖部保持朝前擺正，腳尖朝前。","膝蓋打直，將一隻腳往側邊抬起。","在最高點稍微停頓一下。","慢慢放下，完成次數後換腳。"],"0792":["手扶固定物站直，核心收緊。","重心移到一隻腳，另一腳膝蓋彎曲。","將彎曲腿的腳跟往後上方推，同時夾緊臀肌。","下背不要過度拱起。","有控制地放下，完成次數後換腳。"],"0793":["雙腳踩在彈力帶中段，雙手各握住一端。","手肘保持微彎。","雙臂往身體兩側平舉到肩膀高度。","對抗彈力帶的張力，慢慢放下手臂。","避免聳肩或靠身體晃動借力。"],"0794":["雙腳分開與肩同寬站立，膝微屈。","雙臂向兩側水平展開與地面平行。","慢慢將上半身向一側側傾，感受體側與背闊肌拉伸。","保持拉伸 15-30 秒。","回正後換另一側重複。","重複所需次數。"],"0795":["雙腳與臀部同寬站立，雙手叉腰。","重心移至左腿，右腳向後勾起屈膝。","收縮腿後腱，慢慢將右腳跟拉向臀部（站姿單腿後勾腿）。","頂端停留片刻，慢慢降回地面。","重複所需次數後換腿。"],"0796":["站直雙腳與肩同寬，健腹輪置於腳前地面。","彎腰俯身抓住輪把，慢慢向前推滾出輪子，背部打直核心收緊（站姿健腹輪滾出 Standing Ab Wheel Rollout）。","向前滾動至身體完全伸展成水平直線。","在最遠延伸點停頓片刻，腹肌與背肌發力將輪子拉回腳前站直。","重複所需次數。"],"0798":["調整健身車或飛輪車座椅高度與握把。","腳掌踩入踏板拉緊踏套。","以穩定舒適的步頻開始踩踏熱身，背打直收緊核心。","維持均勻踏頻，視訓練強度逐步增加阻力。","持續踩踏至目標有氧時間。","結束前調低阻力放慢步頻緩和。","下車進行腿部肌群伸展放鬆。"],"0799":["面對穩固的踏板或跳箱站立。","一腳踩上踏板，另一腳膝蓋往上抬並跨向身體對側。","有控制地退回地面。","保持挺胸，核心收緊。","以穩定的節奏左右交替進行。"],"0800":["面對穩固的踏板站立，雙手放在頭部兩側。","右腳踩上踏板，同時將左膝往上抬高。","轉動軀幹，讓右手肘朝左膝靠近。","小心地退回地面，重新站好。","換邊重複，左右交替進行。"],"0801":["面對穩固的踏板或長凳站立。","將一隻腳整個踩在踏板上。","前腳跟發力往下踩，將身體往上帶到前腿完全伸直。","慢慢放低身體回到地面。","完成所有次數後換腳。"],"0803":["高棒式姿勢開始，雙手略寬於肩，雙腳併攏。","收緊核心下沉進行伏地挺身。","推起時同時將右手與左腿向上抬離地面水平伸展（超人伏地挺身）。","頂端停頓片刻，放回手腳順勢下沉，換左手與右腿抬起。","交替進行至所需次數。"],"0805":["TRX 懸吊繩固定在高錨點，長度調至腰部。","背對錨點站立，正握抓把手向前伸展。","身體前傾，保持身體從頭到腳成一直線，收緊核心。","雙臂向前向上伸展，身體順勢前傾延展（TRX 站姿滾腹 TRX Rollout）。","在核心極限處停頓片刻，腹肌發力拉回站姿。","重複所需次數。"],"0806":["TRX 調整至適當高度，背對錨點站立。","正握抓把手，雙腳向後退成斜向高棒式。","身體維持一直線，手肘微收彎曲降下胸部貼近把手（TRX 伏地挺身）。","胸大肌發力推回頂端。","重複所需次數。"],"0807":["正手抓住單槓懸掛，雙臂伸展。","收緊核心屈膝將雙膝拉向胸口，骨盆向胸腔捲起（懸垂屈膝提腿）。","頂峰停頓片刻，慢慢放回雙腿。","重複所需次數。"],"0808":["TRX 懸吊繩設定在腰胸高度。","面對錨點站立，雙腳與肩同寬。","對握抓把手，雙腳向前走，身體向後仰躺成懸掛斜板。","兩側肩胛骨夾緊屈肘，將胸口拉向握把（TRX 划船 TRX Row）。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0809":["背對 TRX 站立，雙腳與肩同寬。","單腳向後伸，將腳背套入身後的 TRX 腳圈中。","前腿屈膝下沉成弓箭步（TRX 保加利亞分腿蹲），挺胸膝蓋對齊腳尖。","踩穩前腳跟蹬起回起始位置。","重複所需次數後換腿。"],"0810":["背部靠牆，往下滑動進入靠牆深蹲。","雙腳平貼地面，維持深蹲姿勢。","雙手往前下方伸向腳趾。","回到背部貼牆的挺直姿勢。","維持穩定的坐姿高度，重複動作直到整組結束。","深蹲時膝蓋維持約 90 度，結束後沿著牆面滑回站姿。"],"0811":["雙腳分開與肩同寬站立，站在六角槓（Trap Bar）中央。","屈髖屈膝俯身，正握抓住兩側握把。","挺胸背打直，腳跟推地伸膝展髖拉起槓鈴（六角槓硬舉 Trap Bar Deadlift）。","站直時完全挺髖夾緊臀部。","慢慢屈髖屈膝將槓鈴放回地面。","重複所需次數。"],"0812":["坐在重訓椅邊緣，雙手抓緊椅緣。","雙腳向前走，臀部滑出椅面懸空。","手肘彎曲下沉身體至上手臂平行地面。","掌心發力推直手臂撐回頂端。","重複所需次數。"],"0813":["坐在平凳上，雙手抓在臀部兩側凳緣。","臀部滑出長凳，雙手支撐身體。","手肘彎曲下沉身體，背貼長凳。","底部稍作停頓，推直手臂撐回。","重複所需次數。"],"0814":["坐在椅子或重訓椅邊緣，雙手抓住椅緣，手指朝前。","臀部移出椅面懸空，雙臂支撐體重。","手肘微收彎曲下沉身體，背部貼近椅身。","底部停頓片刻，手臂推直撐回頂端（椅子撐體 Chair Dips）。","重複所需次數。"],"0815":["坐在椅子邊緣，雙手握住兩側椅緣，雙腿向前伸直。","臀部移開椅子，雙手支撐全身。","手肘彎曲下沉身體，直到手肘呈約 90 度。","三頭肌發力推直手臂回到頂端。","重複所需次數。"],"0816":["雙腳與肩同寬站立，膝微屈。","雙臂向前水平伸直。","手肘微收彎曲降下身體，手肘貼緊身側。","底部停頓片刻，推回頂端。","重複所需次數。"],"0817":["站姿或坐姿挺直，背打直。","單臂向上伸過頭頂，屈肘將手伸向後頸。","另一手扶在手肘上，輕輕向頭部後方拉動加深伸展。","保持拉伸 15-30 秒感受三頭肌伸展。","放鬆換另一手重複。"],"0818":["調整座椅高度，面對滑輪下拉機坐好。","正握抓住握把，雙手與肩同寬。","大腿卡在大腿墊下方，雙腳踩實地面。","身體微後傾挺胸，背闊肌發力將握把向下拉向上胸鎖骨處。","底部停留片刻，擠壓背肌。","慢慢放回把手，重複所需次數。"],"0820":["側躺並以單側前臂撐起身體，雙腳交疊。","抬起髖部，讓身體呈一直線。","上方手臂穿過軀幹下方，順勢稍微轉動身體。","回到身體呈一直線的姿勢。","完成所有次數後換邊。"],"0821":["仰躺在地上，膝蓋彎曲，雙手放在頭部兩側。","將軀幹往上捲離地面。","轉動身體，讓一側手肘朝對側膝蓋靠近。","有控制地躺回地面。","每一下左右交替進行。"],"0822":["雙腳與肩同寬站立，雙手在胸前合攏。","往下坐進入深蹲。","站起來的同時，將軀幹轉向其中一側。","轉回正中央，再次往下深蹲。","左右交替轉體。"],"0823":["仰躺在地上，膝蓋彎曲，雙臂伸直朝向天花板。","將肩膀捲離地面。","伸直的雙臂往膝蓋的其中一側延伸。","慢慢躺回。","左右交替進行，過程中保持頸部放鬆。"],"0826":["雙手撐在雙槓上，雙臂伸展支撐全身。","收緊核心，雙腿打直併攏向前上方抬起至平行地面（雙槓 L 撐體懸垂抬腿）。","頂端停頓片刻，慢慢降回雙腿。","重複所需次數。"],"0827":["站直身體，雙手舉在胸前高度。","將一側膝蓋往上提向雙手。","雙腿快速交換，像原地跑步一樣。","保持以前腳掌著地。","維持穩定、輕快的節奏。"],"0828":["踏上器材並設定舒適的速度。","身體站直，肩膀放鬆。","步行時雙臂自然擺動。","腳跟先著地，再順勢滾動到腳尖推蹬。","以還能輕鬆講話的配速走 10 到 30 分鐘。","結束前慢慢放慢速度。"],"0829":["站直身體，雙臂自然放鬆。","將一側膝蓋抬高到髖部高度。","踩下後換抬起另一側膝蓋。","雙臂自然擺動。","在設定的時間內維持穩定的節奏。"],"0830":["坐在重訓椅邊緣，雙手抓緊椅緣。","臀部移開椅面懸空，雙臂支撐體重。","手肘彎曲下沉身體，直到上手臂平行地面。","手臂推直撐回頂端。","重複所需次數。"],"0831":["仰躺在地上，膝蓋彎曲，雙腳平貼地面。","雙手將負重抱在胸前。","將肩膀往上捲離地面。","在最高點稍微停頓一下。","慢慢放低身體並重複動作。"],"0832":["平躺，雙膝彎曲，雙腳平踩地面。","雙手持槓片或啞鈴置於胸前。","腹肌發力收緊，將肩胛骨捲離地面（負重捲腹）。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0833":["前腳掌踩在踏台邊緣，腳跟完全懸空。","手扶穩固物體維持平衡。","伸展腳踝將腳跟盡可能抬高，收縮小腿（台階提踵）。","頂峰停頓片刻，慢慢降回腳跟至踏面以下。","重複所需次數。"],"0834":["雙腳與肩同寬站立，手持啞鈴置於大腿前，掌心朝後。","手臂打直，吐氣將啞鈴向前平舉至肩高。","頂端停留片刻，吸氣慢慢降回。","重複所需次數。"],"0835":["趴在抗力球上，髖部貼球，雙腳頂住牆面維持穩定。","雙手抱頭或交叉胸前。","啟動核心與背肌，慢慢挺起上半身直到身體呈一直線（抗力球背部挺身）。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0836":["仰躺在地上，雙手將負重抱在胸前。","起始時膝蓋彎曲並抬離地面。","往上捲腹的同時，將雙腿往前伸直。","躺回時將膝蓋收回。","全程保持下背貼緊地面。"],"0837":["側躺，將負重放在上方腿的大腿或腳踝處。","保持身體呈一直線。","將上方腿往上並稍微往後抬起。","有控制地放下。","完成所有次數後換邊。"],"0838":["側躺在長凳上，頭部剛好超出邊緣，戴上掛有輕重量的頭部護具。","讓頭部稍微往地面方向垂下。","只靠頸部出力，將頭往天花板方向抬起。","在最高點稍微停頓一下。","慢慢放下並重複，完成後換邊。","請使用輕重量，並維持受控的慢速節奏。"],"0839":["仰躺在地上，膝蓋彎曲抬起，雙手將負重舉在胸口上方。","保持雙肩貼緊地面。","將雙膝往其中一側放低。","回到正中央，再往另一側放低。","動作放慢並維持控制。"],"0840":["坐在抗力球上，雙腳踩實，膝呈 90 度。","雙手持槓片或啞鈴高舉過頭頂。","收緊腹肌，慢慢向前捲動軀幹使胸部靠近膝蓋（抗力球負重捲腹）。","頂端稍作停頓，慢慢降回。","重複所需次數。"],"0841":["正握抓單槓，握距略寬於肩寬。","完全懸掛，雙臂伸展身體打直。","背闊肌發力，挺胸將身體拉向單槓，手肘貼身。","拉至下巴超過橫槓。","頂端停頓片刻，慢慢降回懸掛。","重複所需次數。"],"0842":["上背靠在健身球上，抬高髖部。","雙手合握一個負重，舉在胸口上方。","手肘保持微彎，將負重往頭頂後方下放。","將負重拉回胸口上方。","全程保持核心收緊、髖部抬高。"],"0843":["採坐姿或仰臥，膝蓋彎曲，將負重放在大腿上。","讓雙膝往外打開呈三角形。","對抗重量，用力將雙膝往內夾緊。","稍微停頓一下。","慢慢打開並重複動作。"],"0844":["雙腳與肩同寬站立，雙手握啞鈴。","膝微屈屈髖前傾，背部打直。","手肘微彎，向兩側平舉雙臂至平行地面（俯身側平舉）。","頂端停頓片刻，慢慢降回。","重複所需次數。"],"0845":["坐在地上，雙膝彎曲，雙腳離地懸空併攏。","雙手抱重物於胸前，手肘微屈。","微向後傾斜啟動核心肌群平衡。","軀幹向右旋轉將重物移向右側地面。","停頓片刻，轉向左側將重物移向左側地面。","雙側交替進行至所需次數。"],"0846":["坐在地上，雙膝彎曲，雙腳平踩。","雙手抱藥球或槓片於胸前。","微向後仰，背部打直核心收緊。","軀幹向右旋轉將藥球拉向右側地面（坐姿藥球俄羅斯轉體）。","稍作停頓，轉向左側將藥球拉向左側地面。","雙側交替進行至所需次數。"],"0847":["坐在抗力球上，雙腳踩實，背部打直。","雙手反握藥球（掌心朝上），雙臂垂於身側。","上手臂固定不動，吐氣收縮二頭肌將藥球向上彎舉至胸肩前。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢放回起始位置。","重複所需次數。"],"0848":["坐在長凳上，戴上頭部護具並讓輕重量自然垂在身前。","身體稍微前傾，雙手放在大腿上支撐。","有控制地讓下巴往胸口方向垂下。","將頭往上抬起，直到頸部回到自然中立位置。","放慢速度重複動作直到整組結束。","保持背部挺直，並使用輕重量。"],"0849":["坐在抗力球上，雙腳踩實，膝蓋呈 90 度。","雙手在胸前抱住槓片或啞鈴。","收緊核心，慢慢將軀幹向一側旋轉，骨盆維持穩定不動。","轉動到底停頓片刻，慢慢回正。","換向另一側旋轉重複。","交替進行至所需次數。"],"0850":["坐在抗力球上，雙腳分開與肩同寬踩實。","單手拿啞鈴垂於體側，另一手叉腰。","啟動核心，慢慢向持啞鈴側側屈，背部維持平直。","底部停頓片刻，核心發力拉回正中。","重複所需次數後換邊。"],"0851":["雙腳開立與肩同寬，腳尖微朝外。","雙手抱重物於胸前（或槓鈴扛在上背）。","挺胸收腹，屈膝屈髖向後下蹲進入深蹲。","下蹲至大腿平行地面或略低。","底部稍作停頓，踩穩腳跟蹬起回站姿。","重複所需次數。"],"0852":["雙腳與肩同寬站立，腳尖微朝外。","將重物抱在胸前或扛在肩上。","挺胸收腹，臀部向後坐深蹲。","蹲至大腿平行地面或舒適深度。","腳跟發力站起，頂峰夾緊臀部。","重複所需次數。"],"0853":["雙腳與肩同寬站立，雙手各持一啞鈴垂於體側，掌心朝前。","手肘貼緊軀幹，吐氣彎舉啞鈴至肩高。","頂端停留片刻，吸氣慢慢降回。","重複所需次數。"],"0854":["雙腳與肩同寬站立，雙手在身前合掌夾住槓片（或重物）。","雙臂向前水平伸展，掌心相對。","雙手盡可能用力向內擠壓槓片（等長胸肌擠壓 Svend Press 概念）。","持續用力按壓數秒，放鬆片刻。","重複所需次數。"],"0855":["雙腳與肩同寬站立，雙手將負重抱在胸前。","保持髖部朝前不動。","將軀幹轉向其中一側。","回到正中央，再轉向另一側。","動作保持流暢，不要猛力甩動。"],"0856":["雙腳與肩同寬站立，雙手掌心在胸前水平夾住槓片（站姿槓片推胸 Svend Press）。","手肘微彎，用力向內夾緊槓片。","維持向內夾緊的張力，將槓片向前水平推直伸展。","頂端稍作停頓，慢慢收回胸前。","重複所需次數。"],"0857":["雙膝跪在地板上，健腹輪置於身前。","雙手握住健腹輪手柄，手臂向前伸展。","收緊核心肌群，推動健腹輪向前滾出，背部維持平直不塌腰（跪姿健腹輪滾出 Kneeling Ab Wheel Rollout）。","向前滾至身體完全伸展、手臂越過頭頂。","在最遠處停頓片刻，腹肌發力收縮將健腹輪拉回膝蓋前方。","重複所需次數。"],"0858":["在跑道或空地上進行訓練。","站立雙腳與肩同寬，採起跑預備姿。","全力爆發加速向前衝刺（衝刺跑 Sprint），擺動雙臂高抬膝。","衝刺至指定距離或時間。","慢走緩和後重複所需組數。"],"0859":["將重物繩索固定在捲腕器（Wrist Roller）的一端。","雙手正握抓住捲腕器握桿兩端，掌心朝下。","雙腳與肩同寬站立，雙臂向前水平伸直。","手腕交替向上屈起旋轉，將重物捲起至最頂端。","在頂端稍作停頓，隨後手腕受控反向旋轉將重物慢慢放回地面。","重複所需次數。"],"0860":["面向滑輪機站立，雙腳與肩同寬。","右手抓滑輪把手，後退拉緊纜繩。","膝微屈，屈髖前傾，背部打直。","上手臂貼緊身側，手肘呈 90 度屈曲。","前臂向後推直伸展，手臂完全打直（滑輪三頭後屈伸）。","停頓片刻，慢慢放回 90 度。","重複所需次數後換手。"],"0861":["坐在坐姿划船機上，雙腳踩在腳踏板上，雙膝微彎。","正握抓把手，背部挺直雙肩放鬆。","將把手拉向腹部，兩側肩胛骨向內夾緊。","頂端停留片刻，慢慢送回把手。","重複所需次數。"],"0862":["雙腳與肩同寬站立面向滑輪機。","雙手在胸前握滑輪把手，雙臂微屈。","收緊核心，慢慢將軀幹向一側旋轉，下盤骨盆維持穩定。","旋轉到底停頓片刻，慢慢轉回。","換向另一側旋轉。","交替進行至所需次數。"],"0863":["側躺在平凳上，上手臂貼緊身側，手肘彎曲 90 度。","手中握啞鈴，前臂平貼腹部。","上手臂貼身固定，慢慢向上旋轉前臂使啞鈴指向天花板（側臥啞鈴肩外旋）。","頂端稍作停頓，慢慢降回腹前。","重複所需次數後換邊。"],"0864":["雙腳與肩同寬站立，手持啞鈴垂於體側。","手肘彎曲 90 度，將雙臂向兩側平舉至上手臂平行地面。","上手臂位置固定，向外向上旋轉前臂將啞鈴舉向天花板（古巴推舉肩外旋動作）。","最高點停頓片刻，慢慢旋轉降回。","重複所需次數。"],"0865":["平躺在地上，雙腿伸展，手臂放於身側。","雙手墊在臀部下方支撐。","收緊核心將雙腿打直抬向天花板（仰臥抬腿 Leg Raise）。","頂端停留片刻，慢慢降回地面上方懸空。","重複所需次數。"],"0866":["正握抓單槓懸掛，雙臂伸展，掌心朝外。","啟動核心，雙腿打直抬至身前平行地面或更高（懸垂抬腿 Hanging Leg Raise）。","頂端稍作停頓，慢慢放回雙腿。","重複所需次數。"],"0867":["坐在地上，雙腿伸直，雙手放在髖部後方，手指朝前。","雙手與腳跟向下推地，將髖部抬起。","讓身體從頭到腳跟呈一直線。","夾緊臀肌，肩膀遠離耳朵。","維持 20 到 45 秒。","穩定控制將髖部放回地面。"],"0868":["面對滑輪機站立，雙腳與肩同寬。","反手握住滑輪配件，掌心朝上。","手肘貼緊身側，上手臂固定不動。","吐氣收縮二頭肌將把手彎舉向肩前。","頂峰停頓片刻，擠壓二頭肌。","吸氣慢慢降回起始位置。","重複所需次數。"],"0869":["調整機械推胸機座椅高度與靠背。","背貼靠墊坐穩，雙腳踩實地面。","正握抓住機器手把，握距略寬於肩寬。","向前向上推動把手至雙臂完全伸展。","頂端停頓片刻，慢慢放回胸前。","重複所需次數。"],"0870":["平躺，雙膝彎曲，雙腳平踩地面。","雙臂置於體側，掌心朝下。","收緊腹肌將雙腿抬離地面，雙膝抱向胸口。","在最高點用力收縮擠壓腹肌停頓片刻。","慢慢放回起始位置。","重複所需次數。"],"0871":["平躺，雙膝彎曲，雙腳平踩。","雙手輕扶後腦勺，手肘朝外。","收緊腹肌，肩胛骨抬離地面，同時雙膝拉向胸前，將上半身捲向膝蓋（對向捲腹）。","頂端停頓片刻，慢慢降回肩胛骨與放回雙腿。","重複所需次數。"],"0872":["平躺在地上，雙臂放於身側。","屈膝將雙腳抬離地面，大腿垂直地面。","收縮腹肌，將臀部捲離地面，使雙膝抱向胸口（反向捲腹）。","頂峰停頓片刻，慢慢放回臀部。","重複所需次數。"],"0873":["纜繩接在低滑輪上，仰臥躺在墊子上。","雙手抓住繩索把手，雙臂垂直伸向天花板。","屈膝將大腿拉向胸前。","上半身維持穩定，骨盆向胸部捲起將臀部抬離墊面（滑輪反向捲腹）。","頂端停頓片刻，慢慢放回臀部。","重複所需次數。"],"0874":["繩索接在胸部高度的滑輪機上。","背對機台站立，雙腳與肩同寬。","雙手握繩索置於後腦勺兩側，手肘彎曲。","收緊腹肌，向前下方捲曲軀幹，手肘靠近膝蓋。","頂端停頓片刻，慢慢回正。","重複所需次數。"],"0878":["將槓鈴設定在深蹲架約上胸高度，走進槓下讓槓鈴放在上背。","起槓後退一步，雙腳與肩同寬。","屈髖屈膝往下深蹲，蹲到自己舒適的最深位置。","保持挺胸，膝蓋朝腳尖方向對齊。","全腳掌推地站回起始位置。","將安全護槓設定在比最低蹲點稍低的位置。"],"0880":["將腳踝扣環接上低位滑輪，面向配重片站立。","扶住機台外框保持平衡。","收緊核心，將繫有扣環的腿往後踢。","在頂點夾緊臀肌。","慢慢收回，完成次數後換腿。"],"0881":["站直，雙手各拿一個啞鈴垂在身體兩側。","將一腳往後斜跨到另一腳後方。","雙膝彎曲下蹲，直到前側大腿接近平行地面。","保持挺胸，髖部朝向正前方。","前腳推地站回原位。","換邊重複並交替進行。"],"0882":["將啞鈴抱在胸前或拿在身體側邊。","單腳站立，另一腳在前方抬起。","髖部往後坐，穩定控制身體下蹲。","保持膝蓋對齊腳尖方向。","往上推地站直，接著換腿。"],"0884":["在身旁放一張長凳，將槓鈴放在上背。","站在長凳側邊。","靠近長凳的那隻腳往側邊踩上長凳。","伸直腿將身體帶上去。","慢慢放低身體，完成次數後換邊。"],"0885":["側躺在槓鈴下方，將槓鈴調整到舒適的高度。","將上方腳掌或小腿貼在槓鈴下。","對抗阻力，平穩將腿往上抬。","穩定控制放低。","完成次數後換邊。"],"0886":["單腳站立，雙手在髖部高度握住槓鈴。","站立腿膝蓋保持微彎。","髖部往後推、上半身前傾，讓槓鈴貼著腿往下滑。","保持背部平直，懸空腿往後延伸。","髖部往前推站直身體，接著換腿。"],"0891":["固定好彈力帶，繞過上背固定。","保持背部平直，從髖部往前俯身。","將軀幹往上挺起，直到身體呈一直線。","在頂點夾緊臀肌。","慢慢下放並重複動作。"],"0892":["雙腳踩住彈力帶，雙手握住兩端。","保持背部平直、膝蓋微彎，身體前傾。","將手肘往後拉向髖部。","將兩側肩胛骨往中間夾緊。","穩定控制下放。"],"0893":["雙腳踩住彈力帶，雙手各握一端。","保持背部平直，身體前傾。","手肘微彎，將雙臂往身體兩側抬起。","在頂點夾緊肩胛骨。","慢慢下放。"],"0894":["採取坐姿或站姿，將彈力帶繞在前腳掌下方。","雙手握緊兩端。","對抗彈力帶阻力，往上踮起腳尖。","在頂點稍作停留。","慢慢下放。"],"0897":["雙腳踩住彈力帶，雙手掌心相對握住兩端。","手肘貼近身體兩側。","將雙手往肩膀方向捲起。","稍作停留。","慢慢下放，避免身體晃動。"],"0901":["將彈力帶套在雙腳腳踝，或固定在低處。","站直並扶住支撐物。","對抗彈力帶阻力，將一腿筆直往後推。","在頂點夾緊臀肌。","慢慢收回，接著換腿。"],"0902":["將彈力帶繞過雙肩，下方踩在腳底或固定住。","保持背部平直，從髖部往前傾。","挺起身體，直到軀幹與雙腿呈一直線。","夾緊臀肌。","慢慢下放並重複動作。"],"0903":["雙腳踩住彈力帶，身體前傾並握住兩端。","上臂貼近身體兩側。","伸直手肘，將雙手往後推。","在頂點收緊三頭肌。","慢慢彎曲手肘回到原位。"],"0905":["將彈力帶固定在高處，面向固定點跪下。","雙臂往上伸直抓住兩端。","將手肘往下拉向肋骨兩側。","將兩側肩胛骨往中間夾緊。","穩定控制慢慢放回。"],"0906":["四足跪姿，將彈力帶一端套在一隻腳上，雙手壓住另一端。","保持核心收緊。","將套住彈力帶的腿往後上方踢。","在頂點夾緊臀肌。","慢慢下放，接著換腿。"],"0907":["雙腳踩住彈力帶，雙手握住兩端放在身體兩側。","手肘保持微彎。","將雙臂往兩側抬至肩膀高度。","穩定控制慢慢下放。","避免聳肩。"],"0908":["將彈力帶固定在低處，採前後站姿。","雙手握住兩端，手肘微彎。","雙臂在胸前往上並往中間靠攏。","在頂點夾緊胸部。","慢慢放回。"],"0909":["雙腳踩住彈力帶，雙手握住兩端舉在肩膀位置。","往前跨出一大步。","後膝朝地面下放。","前腳跟推地回到起始位置。","雙腿交替進行。"],"0910":["仰躺在地上，將彈力帶套在雙腳或固定住。","雙腿往天花板方向抬起。","將髖部捲離地面。","慢慢下放。","保持下背穩定控制。"],"0911":["俯臥在地上，將固定好的彈力帶套在雙腳腳踝。","保持髖部貼地。","將腳跟往臀肌方向捲起。","收緊大腿後側。","慢慢下放。"],"0912":["仰躺在地上，將彈力帶套在雙腿。","保持雙腿伸直。","對抗彈力帶阻力將單腿抬起。","慢慢下放。","雙側交替進行。"],"0913":["將彈力帶固定在胸口高度，背對固定點站立。","雙手握住兩端，手肘微彎。","雙手在胸前往中間靠攏。","夾緊胸肌。","慢慢放回。"],"0915":["將彈力帶繞過上背，雙手掌心壓住兩端。","擺出高棒式姿勢。","胸口朝地面下放。","對抗彈力帶阻力往上推回。","保持身體呈一直線。"],"0917":["雙腳踩住彈力帶，掌心朝下握住兩端。","手肘貼近身體兩側。","將雙手往肩膀方向捲起。","慢慢下放。","避免身體晃動。"],"0919":["單腳踩住彈力帶，雙手握住兩端。","站立腿膝蓋保持微彎。","保持背部平直，身體前傾並將懸空腿往後延伸。","髖部往前推回到站姿。","完成次數後換腿。"],"0921":["將彈力帶固定在手肘高度，側對固定點站立。","手肘彎曲 90 度握住彈力帶一端。","前臂往身體外側旋轉打開。","慢慢放回。","完成次數後換手。"],"0923":["將彈力帶固定在後方低處，雙手在胸前握住兩端。","採前後站姿。","將雙手往斜前上方推。","在頂點夾緊胸部。","慢慢放回。"],"0924":["將彈力帶固定在手肘高度，側對固定點站立。","手肘彎曲 90 度握住彈力帶一端。","前臂往腹部方向向內旋轉。","慢慢放回。","完成次數後換手。"],"0926":["將彈力帶固定在後方，套在一隻腳踝上。","扶住支撐物，將膝蓋微微抬起。","將膝蓋往前伸直。","收緊股四頭肌。","慢慢彎曲收回，接著換腿。"],"0927":["將彈力帶套在腳踝，並固定在身體後方。","站直並扶住支撐物。","保持腿部伸直往前抬起。","慢慢下放。","完成次數後換腿。"],"0928":["將彈力帶固定在頭頂上方，面向固定點站立。","雙臂伸直握住兩端。","將雙手往下拉向大腿前側。","夾緊背闊肌。","慢慢放回。"],"0930":["將彈力帶固定在胸口高度，雙手握住兩端。","往後退一步讓彈力帶產生張力。","將手肘往後拉過肋骨兩側。","夾緊肩胛骨。","慢慢放回。"],"0931":["將彈力帶固定在低處，雙手在靠近固定點一側握住彈力帶。","保持髖部朝向正前方。","旋轉軀幹，將彈力帶往斜上方拉。","慢慢放回。","完成次數後換邊。"],"0934":["雙腳與髖同寬踩在彈力帶中段，雙手握住兩端。","雙臂自然垂在大腿前側，讓彈力帶保持微緊。","手肘帶動，將雙手沿著身體往上拉到約胸口高度。","稍作停留，接著穩定控制下放，不要讓彈力帶彈回。","保持挺胸，肩膀遠離耳朵。"],"0935":["將彈力帶固定在手肘高度，側對固定點站立，用外側手握住握把。","手肘貼緊身體側邊並彎曲呈 90 度。","手肘固定不動，將前臂往遠離腹部的方向外旋。","手部朝向斜外側時稍作停留，接著慢慢放回。","完成所有次數後換邊。"],"0938":["踩上踏板，雙手輕扶握把保持平衡。","一腳往下踩同時另一腳升起，維持流暢節奏。","站直身體，保持膝蓋朝向正前方。","以舒適的配速持續踩幾分鐘，依需求調整阻力。","準備下機前先逐漸放慢速度。"],"0942":["從四足跪姿開始，手腕在肩膀正下方，膝蓋在髖部正下方。","吐氣，雙手推地，將背部往天花板方向拱起。","下巴收向胸口，腹部往內收。","維持 20 到 30 秒，保持緩慢呼吸。","吸氣，回到背部自然中立的位置。"],"0943":["雙腳併攏站立，雙臂放在身體兩側。","彎曲膝蓋，髖部往後往下坐，就像要坐進椅子一樣。","雙臂往上延伸貼近耳朵，拉長脊椎。","重心放在腳跟，再往下蹲低一點。","維持 5 個緩慢呼吸，接著伸直雙腿站起。"],"0944":["雙腳併攏或與髖同寬站立。","彎曲膝蓋並將髖部往後推，保持胸口挺起。","雙臂高舉過頭，掌心相對。","保持膝蓋在腳踝上方，尾骨微微內收。","維持 5 個緩慢呼吸，接著站直。"],"0945":["跪在地上，大腳趾相碰，雙膝打開。","將髖部往後坐向腳跟。","上半身往前摺，雙臂貼地往前延伸。","額頭輕靠地面，放鬆肩膀。","維持 20 到 30 秒，保持緩慢呼吸。"],"0946":["雙腳併攏蹲下，雙手平貼地面，與肩同寬。","手肘微彎，將小腿前側靠在上臂後側。","重心往前移到雙手，先抬起一腳，再抬起另一腳。","拱起上背，腹部內收，視線看向斜前方。","維持幾個呼吸，接著輕輕把腳放回地面。"],"0947":["雙腳併攏站直，雙臂高舉過頭，雙掌合十。","指尖往上延伸，保持髖部水平。","上半身慢慢往一側彎曲，呈現溫和弧線。","維持 3 到 5 個呼吸，身體不要往前或往後扭轉。","回到中間，換另一側重複。"],"0948":["雙腳約與髖同寬站立，重心平均落在雙腳。","雙臂自然垂放在身體兩側。","拉長脊椎，肋骨輕輕往下收。","放鬆肩膀，視線直視前方。","平穩呼吸幾次。"],"0949":["從四足跪姿開始，雙手放在肩膀稍微前方的位置。","腳趾踩地，將髖部往後上方推高。","在舒適範圍內盡量伸直雙腿，胸口往大腿方向推近。","手指張開，雙手推地。","維持 20 到 30 秒，保持緩慢呼吸。"],"0950":["仰躺在地上，雙腿伸直，雙臂放在身體兩側，掌心朝下。","前臂往下推地，將胸口抬起。","拱起上背，讓頭頂輕輕點地。","雙腿保持放鬆，深呼吸到胸口。","維持 15 到 30 秒，接著慢慢放平。"],"0951":["雙腳站得比髖部稍寬，腳尖朝外。","往下深蹲，可以的話盡量讓腳跟貼地。","雙手在胸前合十。","手肘抵住雙膝內側往外推，並拉長脊椎。","維持 20 到 30 秒，保持緩慢呼吸。"],"0952":["從寬站姿開始，將一腳腳尖轉向外側。","朝那隻腳的方向前傾，將手放在該腳前方的地面或瑜伽磚上。","將後腿往上抬，直到與地面平行。","展開胸口並讓雙側髖部上下疊合，上方手往上延伸。","維持幾個呼吸，接著放下並換邊。"],"0953":["雙腳與髖同寬站立。","拉長脊椎，從髖部往前摺。","掌心朝上將雙手滑進腳底下方，讓腳趾踩在手指上。","膝蓋保持微彎，雙手輕輕出力加深伸展。","維持 20 到 30 秒，保持緩慢呼吸。"],"0954":["雙膝併攏跪地，雙腳分開比髖部稍寬。","將髖部往下坐在雙腳腳跟之間，需要的話可墊瑜伽磚。","雙手放在大腿上，拉長脊椎。","放鬆肩膀，保持平穩呼吸。","維持 30 到 60 秒，接著慢慢解開動作。"],"0955":["仰躺在地上，雙腿伸直。","抬起一腿並往側邊打開，另一腿保持貼地。","保持髖部擺正，下背放鬆。","溫和維持伸展，保持平穩呼吸。","收回中間，換另一腿重複。"],"0956":["坐直身體，雙腿在前方伸直。","彎曲一邊膝蓋，將腳掌放在對側大腿靠近髖部的位置。","如果髖部活動度允許，彎曲另一膝並將腳掌疊放到對側大腿上。","雙手放在膝蓋上，拉長脊椎。","緩慢呼吸 30 到 60 秒，接著互換上下腳的位置。"],"0957":["跨出一大步呈弓步，後腳跟抬起。","雙手在胸前合十。","扭轉軀幹，將對側手肘卡在前膝外側。","雙掌互推，視線往上看或看向前方。","維持 3 到 5 個呼吸，接著換邊。"],"0958":["坐在地上，在舒適範圍內盡量將雙腿往兩側打開。","勾起腳尖，保持膝蓋朝上。","雙手往前走，從髖部往前摺。","保持脊椎延伸拉長，不要拱背。","維持 20 到 30 秒，保持緩慢呼吸。"],"0959":["雙腳與髖同寬站立。","膝蓋保持微彎，從髖部往前摺。","雙手輕放地面，或互抱對側手肘。","放鬆頸部，讓頭部重量自然垂下。","維持 20 到 30 秒，保持緩慢呼吸。"],"0960":["雙腳寬步站立，腳尖朝前。","保持脊椎修長，從髖部往前傾。","雙手往下放到地面或小腿前側。","放鬆頭部與頸部。","維持 20 到 30 秒，保持緩慢呼吸。"],"0961":["站直身體，將重心移到一隻腳上。","將另一腳腳底踩在站立腿的小腿或大腿內側，避開膝蓋。","雙手在胸前合十，或高舉過頭。","視線專注看定一個點以保持穩定。","維持 5 個呼吸，接著換腿。"],"0962":["雙腳寬步站立，將一腳往外轉 90 度。","雙臂平舉至肩膀高度。","身體往設定為前腳的方向延伸，將前手往下放在小腿或地面。","另一隻手往上延伸，視線看向指尖。","維持 3 到 5 個呼吸，接著換邊。"],"0963":["雙腳寬步站立，將前腳腳尖朝外。","前膝彎曲對齊腳踝上方。","雙臂往身體兩側平舉至肩膀高度。","轉頭看向前方手的方向。","維持 5 個呼吸，接著換邊。"],"0964":["一腳往後跨出一大步，後腳尖微微朝外。","前膝彎曲對齊腳踝上方。","將髖部轉正朝向前方。","雙臂高舉過頭並挺起胸口。","維持 5 個呼吸，接著換邊。"],"0965":["雙腳分開約一腿長，腳尖微微朝內。","雙手叉腰，保持背部平直從髖部往前傾。","雙手往下放到肩膀正下方的地面。","讓頭部自然垂下延伸。","維持 20 到 30 秒，保持緩慢呼吸。"],"0966":["雙腳與髖同寬站立，槓鈴在腳掌中段上方。","屈髖俯身，雙手在雙腿外側握住槓鈴。","繃緊核心，保持背部平直。","雙腳推地站起，讓槓鈴貼近雙腿往上移動。","在頂點鎖定髖部，但不要往後仰。","髖部往後推並彎曲膝蓋，將槓鈴放回地面。"],"0967":["雙腳與髖同寬站立，槓鈴在腳掌中段上方。","屈髖俯身，雙手在雙腿外側握住槓鈴。","繃緊核心，保持背部平直。","雙腳推地站起，讓槓鈴貼近雙腿往上移動。","在頂點鎖定髖部，但不要往後仰。","髖部往後推並彎曲膝蓋，將槓鈴放回地面。"],"0968":["雙腳分開與肩同寬站立，反握抓住彈力帶，掌心朝上。","手肘貼緊身側，單手慢慢向肩膀彎舉，頂峰擠壓二頭肌。","放回原位，換另一手重複。","雙手交替進行至所需次數。"],"0969":["平躺，雙腿伸直，雙臂伸過頭頂握住彈力帶。","收緊腹肌，同時抬起雙腿與上半身（V 字折刀捲腹），雙手伸向腳尖。","放低時雙腿在空中交叉換位。","每次重複時持續交替雙腿交叉位置。","重複所需次數。"],"0970":["彈力帶固定在單槓上。","單腳踩入彈力帶下緣，正握抓槓，握距略寬於肩。","雙臂完全伸展，核心收緊，肩胛骨下沉後收。","手肘向下拉，肩胛夾緊，將身體向上拉過單槓（彈力帶輔助引體向上）。","下巴過槓後，緩慢控制降回。","重複所需次數。"],"0971":["雙膝跪地，雙手正握健腹輪手把。","將健腹輪放在身前地面，雙手與肩同寬。","收緊核心慢慢向前推滾出輪子，身體受控伸展拉長。","在最遠點停頓片刻，核心收縮將輪子拉回膝蓋前方。","重複所需次數。"],"0972":["平躺，雙手輕扶後腦勺，膝蓋彎曲。","雙腳離地，右膝抱向胸前同時軀幹轉體，左肘靠近右膝。","伸直右腿同時左膝拉向胸前，轉體使右肘靠近左膝。","流暢進行踩踏轉體（腳踏車捲腹）。","重複所需次數。"],"0973":["採取坐姿或站姿，將彈力帶繞在前腳掌下方。","雙手握緊兩端，讓彈力帶保持緊繃。","盡可能往上踮高腳尖。","在頂點稍作停留，接著慢慢下放。","保持腳踝穩定對齊，避免往外翻。"],"0974":["彈力帶固定在單槓等高處。","面對錨點站立，反握抓彈力帶，雙手與肩同寬。","後退一步拉緊彈力帶，雙腳與臀同寬。","背打直核心收緊，將彈力帶下拉向胸口，肩胛骨夾緊。","底部停頓片刻，慢慢放回。","重複所需次數。"],"0975":["彈力帶套在上手臂手肘上方。","擺出伏地挺身姿勢，手在肩正下方，身體呈直線。","手肘彎曲下沉胸部貼地，手肘貼緊身側。","推地將手臂伸展推回起始位置。","重複所需次數。"],"0976":["坐在椅子上，雙腿張開，雙腳平踩。","單手握彈力帶一端，同側腳踩住另一端。","微向前傾，手肘抵在大腿內側近膝蓋處。","掌心朝上，慢慢將手向肩膀彎舉。","頂峰停頓片刻，慢慢放回。","重複所需次數後換邊。"],"0977":["雙腳與肩同寬站立，彈力帶置於大腿前，掌心朝下。","手臂伸直，將彈力帶向前上方平舉至與地面平行。","頂峰停頓片刻，慢慢降回。","重複所需次數。"],"0978":["雙腳與肩同寬站立，雙手握彈力帶置於大腿前，掌心朝下。","手臂保持打直，慢慢向前平舉至平行地面。","頂端停頓片刻，緩緩降回。","重複所需次數。"],"0979":["彈力帶固定在腰部高度錨點。","側面垂直於錨點站立，雙腳與肩同寬。","雙手握住彈力帶把手，往外側跨步拉出張力。","雙手維持在胸前，手肘微屈貼身。","收緊核心維持軀幹絕對抗旋轉穩定。","雙手向前水平推直，遠離胸口（帕洛夫推舉 Pallof Press）。","維持伸直姿勢數秒，對抗旋轉拉力。","慢慢收回胸前，重複指定次數後換邊。"],"0980":["彈力帶固定在腳踝高度的錨點。","背對錨點站立，雙腳與肩同寬。","後退一步使彈力帶產生張力，膝蓋微彎。","屈髖前傾，脊椎維持中立。","單腿向後伸展蹬出，頂峰夾緊臀部（站姿彈力帶後踢腿）。","收回換腿重複，雙腿交替進行至所需次數。"],"0981":["平躺，雙腿伸直，雙臂伸過頭頂握彈力帶。","收緊腹肌，同時抬起雙腿與上半身，雙手伸向腳尖。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0982":["側躺屈膝，將環狀彈力帶套在膝蓋上方的大腿處。","雙腳貼合，雙側髖部上下疊齊。","像蚌殼打開一樣，將上方膝蓋往上旋轉打開。","在頂點稍作停留。","慢慢下放並重複動作，接著換邊。","保持骨盆穩定不動，讓動作完全由髖部發力。"],"0983":["彈力帶固定在高處錨點。","單膝跪地，單手握彈力帶，掌心朝下。","手臂伸展過頭頂，手肘微彎。","啟動背闊肌將彈力帶拉向身側，手肘貼近肋骨。","底部停頓片刻，慢慢放回。","重複所需次數後換邊。"],"0984":["仰臥平躺，雙腿打直，阻力帶套在雙腳上。","雙膝彎曲拉向胸前，雙腳併攏。","慢慢向外張開雙膝，雙腳維持貼合（仰臥蚌式）。","外展到底停頓片刻，緩慢收回。","重複所需次數。"],"0985":["彈力帶固定在腰部高度。","背對錨點跪下，雙手握彈力帶，手肘貼側。","收緊腹肌，將軀幹向一側轉體，雙手拉向對側髖部。","停頓片刻，慢慢回正。","換向另一側重複。","交替進行至所需次數。"],"0986":["雙腳與肩同寬站立，單腳踩住彈力帶一端。","另一端握在同側手，手臂高舉過頭頂，掌心朝前。","上手臂固定，手肘彎曲將前臂向後下放，隨後伸展三頭肌推直。","頂端停頓片刻，慢慢放回。","重複所需次數後換手。"],"0987":["雙腳與臀同寬站立，彈力帶套在腳踝上。","單腿向後抬起，將腳尖搭在身後長凳上（保加利亞分腿蹲 Bulgarian Split Squat）。","手可扶牆維持平衡。","前腿屈膝下沉至大腿平行地面。","腳跟蹬地推回站姿。","重複所需次數後換腿。"],"0988":["彈力帶固定在腰部高度。","面對錨點站立，雙腳與肩同寬。","單手握彈力帶掌心朝內，後退拉緊彈力帶。","膝微屈，屈髖前傾，背部打直。","將彈力帶向後拉向腰側，肩胛骨向內夾緊。","頂端停頓片刻，慢慢放回。","重複所需次數後換手。"],"0989":["彈力帶固定在胸部高度。","側身面對錨點站立，單手抓彈力帶。","往側邊跨步拉出張力，雙腳與肩同寬。","握帶的手橫越胸前朝向對側肩膀。","維持張力向前推展手臂伸直。","慢慢收回，重複所需次數後換邊。"],"0990":["坐在椅子上，背打直雙腳踩平。","單手拿彈力帶向前伸直。","背部維持挺直，手肘彎曲夾緊肩胛骨將彈力帶拉向身體。","拉動同時軀幹順勢轉向拉力側。","頂峰停頓片刻，慢慢送回。","重複所需次數後換手。"],"0991":["阻力帶固定在地面錨點。","背對錨點站立，雙腳與肩同寬。","往前跨一步拉出張力，膝蓋微彎。","屈髖將臀部向後推，背部打平俯身（彈力帶早安式）。","俯身至軀幹接近平行地面，感受大腿後側拉伸。","臀肌收縮向前挺髖站直。","重複所需次數。"],"0992":["彈力帶固定在穩固錨點。","平躺，膝蓋彎曲雙腳踩地。","雙手握彈力帶垂直伸向天花板。","腹肌發力收緊，將上半身捲離地面至 45 度。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0993":["彈力帶固定在胸部高度。","雙腳與肩同寬站立，雙手在身前拉住彈力帶。","手臂伸直向兩側水平展開，直到與地面平行（反向飛鳥）。","頂端夾緊肩胛骨，慢慢放回。","重複所需次數。"],"0994":["坐在椅子上，雙腳踩實。","正握抓彈力帶，掌心朝下。","前臂平放在大腿上，手腕懸空。","手腕向上屈起，收縮前臂肌肉。","頂端停頓片刻，慢慢放回。","重複所需次數。"],"0995":["坐在長凳或椅子上，將彈力帶套在雙膝或大腿周圍。","雙腳踩穩地面，背部挺直。","對抗彈力帶，將雙膝往外推開。","在最開的位置短暫停留。","慢慢將雙膝收回併攏。","軀幹保持不動，避免傾倒。"],"0996":["坐在椅子上，背打直雙腳踩地。","彈力帶套在大腿膝蓋正上方。","膝蓋維持 90 度，雙腳與肩同寬。","臀中肌發力將雙膝向外張開，對抗彈力帶阻力（坐姿髖外展）。","外展到底停頓片刻，慢慢收回。","重複所需次數。"],"0997":["雙腳與肩同寬站立，雙腳踩住彈力帶。","掌心朝前握住彈力帶兩端，雙手舉至肩高。","雙臂向上推舉過頭頂，完全伸展。","頂端停頓片刻，慢慢降回肩部。","重複所需次數。"],"0998":["雙腳與肩同寬站立，雙手握彈力帶，掌心朝下。","手臂向兩側平舉與地面平行。","手肘彎曲將雙手拉向肩膀，上手臂維持水平固定。","停頓片刻，慢慢伸展打直。","重複所需次數。"],"0999":["雙腳與臀同寬站立，彈力帶套在左前腳掌下。","手扶穩固物體維持平衡。","慢慢將左腳跟抬離地面，重心移至前腳掌（單腳提踵）。","頂端停頓片刻，緩慢放回。","重複所需次數後換右腳。"]}')
